local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:94414"] = {n="The Anchors of Zephras",s="“泽风之锚”是由泽风岛上的Halaan Hawk-Eye所提供的入门任务。Halaan邀请旅行者借用他那远眺的目光，去观察那些系留并守护着这座浮空岛的古老锚柱。尽管从远处看这些高耸的巨石似乎完好无损，但Halaan警告说，风之灵用来维持稳定的魔法已经开始动摇了。",h="“泽风之锚”是由泽风岛上的Halaan...",kw={"锚柱","泽风之锚","halaan hawk-eye","地脉","天视","风之灵","泽风岛"},ang={["class:Mage"]="Halaan将他敏锐的视力与那些能够汲取泽风岛下方地脉之力的魔法区分开来。",["class:Shaman"]="锚柱直接依赖于风之灵的祝福，这使得它们魔法中的任何不稳定对于寻求维持平衡的萨满祭司而言，都是一个紧迫的元素问题。"},sec={{t="岛屿的系留",b="泽风岛的锚柱是由风之灵所赐予的古老而高耸的巨石。它们深植于岛屿的神秘基座之中，起到固定、稳定和支撑这片陆地悬浮于动荡天空之中的作用。注视着其中任何一座锚柱，便是见证泽风岛得以漂浮的脆弱平衡，而这一切持续依赖于风之灵的眷顾。"},{t="令人不安的变动",b="尽管锚柱在肉眼看来依然巍然屹立且未受损伤，但它们已经变得不再稳定。Halaan Hawk-Eye指出，维持它们运作的魔法和谐最近变得不稳定且前后不一。在没有明显的物理损伤迹象的情况下，这种微妙的衰退引起了守护林地之人的警觉，暗示着威胁岛屿的深层失衡正在发生。"},{t="Halaan的天赋",b="虽然缺乏能够洞察世界彼端的“天视”或引动泽风岛深层地脉的奥术能力，但Halaan拥有一种更单纯、更敏锐的天赋：在极远距离上拥有清晰明锐的视力。通过借出这种视角，他让其他人能够细致地观察远处的锚柱，鼓励新来者在对当下心存感激的同时，也要警惕家园命运的变迁。"}},faq={{q="泽风岛上的锚柱是什么？",a="锚柱是风之灵所赐予的古老神秘建筑。它们结合、锚定并以魔法支撑着泽风岛，使其在周围的世界之上保持稳定。",al={"什么是锚","泽风岛锚柱","什么是锚柱"}},{q="锚柱出了什么问题？",a="虽然锚柱没有显示出明显的物理损伤或外部衰退，但其维持稳定的魔法近期变得不稳定且前后不一，引发了人们对究竟是什么在悄然干扰它们运作的担忧。",al={"为什么锚失效了","锚柱问题","锚发生了什么"}},{q="Halaan Hawk-Eye是谁？",a="Halaan Hawk-Eye是一位居住在泽风岛林地中的守护者。他拥有敏锐且深远的天然视力，监视着这片土地的健康状况，并思考着岛屿的神秘福祉。",al={"halaan的背景","谁是halaan"}},{q="Halaan的天赋是什么？",a="Halaan的天赋是极其敏锐的长距离视力。与那些挥舞天视以洞察世界之间，或引导地脉能量的神秘主义者不同，Halaan的力量是自然且平凡的，这使他能够以纯净的清晰度感知遥远的地标。",al={"halaan的天赋","halaan如何远视"}},{q="什么是天视？",a="天视是泽风岛上某些修行者所拥有的神秘感知力，它使他们能够穿透面纱，直接洞察世界之间，这远超普通人的肉眼视觉。",al={"什么是天视","天视的含义"}},{q="驱动锚柱的魔法来自哪里？",a="锚柱是由风之灵赐予泽风岛的。Halaan说锚柱负责束缚和维持岛屿，但没有解释它们持续力量的来源。",al={"谁制造了锚柱","锚柱的起源"}}},fx={["61bc2f74"]={q="为什么 Halaan Hawk-Eye 想让你查看锚桩？",a="Halaan Hawk-Eye 守望着林地，十分关心 Zephras 的安危。古老的锚桩是风之精灵的馈赠，能束缚并维系这座岛屿，但它们的魔法最近变得不稳定、不规律。尽管锚桩看起来没有受到物理损坏，Halaan 仍愿意与你分享他那远及千里的视野，让你亲眼看看锚桩，了解故土的微妙处境。",al={"halaan 的动机","为什么要查看锚桩","halaan 为什么想要这样做"}}},fp="22,370,19.361.0,18.378.0,13.412.0,38.198.0,37.200.0,23.200.0,22.249.0,17.190.0,51.181.0"}
P.entries["quest:94449"] = {n="Call of Fire",s="Call of Fire是一项萨满祭司的任务，指引学徒们进入丹莫罗高地危险而混乱的火焰领域。在掌握了大地之道的耐心教诲后，修行者会被指引去寻找Bruegs Kindleborn，以测试他们是否准备好接受火焰灵契。",h="Call of Fire是一项萨满祭司的任务，指引学徒们进入丹莫罗高地危险而混乱的火焰领域。在掌握了大地之道的耐心教诲后，修行者会被指引去寻找Bruegs Kindleborn，以测试他们是否准备好接受火焰灵契。",kw={"bruegs kindleborn","call of fire","丹莫罗","大地灵契","火焰图腾","火焰灵契","萨满祭司","南门哨岗"},ang={["class:Shaman"]="这项任务标志着萨满祭司的一次关键精神试炼，是从岩石的忍耐向火焰狂暴、毁灭性力量的过渡。",["faction:Alliance"]="随着试炼在丹莫罗的山脉中展开，联盟的萨满祭司们听从长者的指引，唤醒与火元素的沟通。",["race:Dwarf"]="这项仪式在丹莫罗南门哨岗上方的崇山中进行，测试矮人是否拥有能够抑制火焰燃烧渴望的纪律。"},sec={{t="燃烧试炼",b="在通过大地元素证明了自己的耐心与稳重后，萨满祭司会被指引去面对一种更不稳定的力量：火元素之灵。与稳固而坚毅的岩石不同，火焰带来的召唤充满了混乱、毁灭与狂暴的能量。长者会派遣学徒穿越丹莫罗覆盖着积雪的山峰，在尝试驾驭这股狂野的热量之前去寻求指引。"},{t="山巅隐士",b="在南门哨岗上方的崇山峻岭中，导师Bruegs Kindleborn在一处隐蔽的洞穴中守护着。当携带长者推荐信的学徒抵达时，Bruegs会为他们准备火焰灵契。但他发出了严厉的警告：燃烧与吞噬的渴望极易被唤醒，但想要掌控火焰，就必须准确地知道何时该克制。"}},faq={{q="Bruegs Kindleborn是谁？",a="Bruegs Kindleborn是一位居住在丹莫罗南门哨岗上方高处山洞里的导师。他会评估由长者派来的萨满祭司，以确定他们是否具备接受火焰灵契所需的成熟度与纪律。",al={"bruegs kindleborn是谁","bruegs kindleborn背景故事","bruegs在哪里"}},{q="什么是火焰灵契？",a="灵契是一种元素药剂或制剂，允许萨满祭司与该元素的灵魂进行沟通。火焰灵契赋予了与火焰及其原始力量沟通的能力，这需要精神上的专注以及此前在大地之道上的基础。",al={"什么是火焰灵契","火焰灵契","灵契的含义"}},{q="Bruegs Kindleborn在哪里？",a="Bruegs Kindleborn位于丹莫罗东部遥远的雪山之中，藏身于俯瞰南门哨岗的一处洞穴里。",al={"哪里可以找到bruegs kindleborn","南门哨岗洞穴","call of fire在哪里交任务"}},{q="Call of Fire的目的是什么？",a="Call of Fire是萨满祭司的成人礼，针对的是那些已经展现出耐心并掌握了大地之道的萨满。它召唤他们去面对毁灭的混乱力量，并在Bruegs Kindleborn的注视下进行考验。",al={"什么是call of fire","丹莫罗火焰图腾任务"}},{q="为什么萨满祭司必须在学习火焰之前先学习岩石的教诲？",a="大地代表着坚定的耐心、稳定与控制。如果没有岩石所教授的基础，萨满祭司就有可能被火焰那不稳定的渴望与毁灭性的激情所淹没。",al={"为什么要先学岩石","记住岩石教给你的知识"}},{q="在进行Call of Fire之前需要什么先决条件？",a="该任务建立在之前的试炼之上，学徒在那些试炼中展现了耐心并将自己扎根于大地。只有当学生的纪律得到充分证明时，长者才会将他们送到Bruegs Kindleborn那里。",al={"call of fire先决条件","耐心任务关联"}}},fp="12,263,17.390.0,24.360.0,25.221.0,26.226.0,35.129.0,40.200.0,57.200.0,68.201.0"}
P.entries["quest:94465"] = {n="Call of Fire",s="Call of Fire是一项神圣的试炼，旨在考验入门者是否有能力驾驭元素之火。祈求者必须手持眠炎火炬，沿着洛克莫丹一条隐蔽的山路前行，在眠炎圣殿寻找Braldir Ashmantle。",h="Call of Fire是一项神圣的试炼，旨在考验入门者是否有能力驾驭元素之火。祈求者必须手持眠炎火炬，沿着洛克莫丹一条隐蔽的山路前行，在眠炎圣殿寻找Braldir Ashmantle。",kw={"braldir ashmantle","call of fire","火焰图腾","洛克莫丹","萨满","眠炎圣殿","眠炎火炬","国王谷"},ang={["class:Shaman"]="这项试炼考验着萨满祭司学徒与火焰元素之灵沟通的决心，要求他们将神圣的火炬带到洛克莫丹的一座与世隔绝的山峰上。",["faction:Alliance"]="虽然联盟领地上的普通游客眼中只有荒凉的山石，但圣殿的守护者守卫着不为凡人所知的古老元素秘密。",["race:Dwarf"]="任务对话反映了矮人的语言，并指引入门者越过国王谷，进入卡兹莫丹崎岖的峭壁中。"},sec={{t="国王谷之外的道路",b="获得火焰图腾不仅仅需要强大的体魄。入门者必须携带未点燃的眠炎火炬，攀登至洛克莫丹高耸的峭壁之上。穿过国王谷的石刻，那条艰险的攀登之路通向一座与世隔绝的山峰，那里的元素之力远高于凡人行走的道路。"},{t="眠炎圣殿",b="在风吹过的山峰之巅矗立着Braldir Ashmantle，他是守护眠炎圣殿的守卫。毫无准备的流浪者和寻宝者爬上高处，只会发现寂静与裸露的岩石。对于携带神圣火炬的真正入门者，Braldir会揭示圣殿火盆中沉睡的深层元素力量，等待着被重新点燃。"}},faq={{q="什么是Call of Fire任务？",a="Call of Fire是入门者为了获得火焰图腾而必须经历的成人礼。任务指引祈求者进入洛克莫丹的峭壁，向圣山之巅的Braldir Ashmantle献上眠炎火炬。",al={"call of fire是什么","萨满火焰任务洛克莫丹","火焰图腾任务"}},{q="Braldir Ashmantle是谁？",a="Braldir Ashmantle是驻守在洛克莫丹高处峭壁中眠炎圣殿的守护者。他会拒见普通的游客和寻宝者，只欢迎那些携带眠炎火炬的人。",al={"braldir ashmantle是谁","洛克莫丹圣殿守护者"}},{q="眠炎圣殿在哪里？",a="眠炎圣殿坐落在洛克莫丹高耸的峭壁之中，沿着国王谷之外的一条秘道即可到达。",al={"眠炎圣殿在哪里","眠炎位置"}},{q="眠炎火炬的作用是什么？",a="眠炎火炬是入门者携带的仪式信物，用来证明他们沟通元素之火的真诚意图和准备工作。Braldir Ashmantle要求在接见前先看到火炬。",al={"什么是眠炎火炬","眠炎火炬用途"}},{q="为什么祈求者必须前往洛克莫丹？",a="安置眠炎圣殿的神圣元素之巅俯瞰着国王谷之外的洛克莫丹，这里因远离普通游客而备受青睐。",al={"为什么要去洛克莫丹","为什么火焰圣殿在洛克莫丹"}},{q="如何通过这项试炼获得火焰图腾？",a="在找到Braldir Ashmantle并用火炬证明意图后，入门者必须在圣殿的火盆中引燃火焰，带着燃烧的火炬返回，从而正式获得火焰图腾。",al={"找到braldir后会发生什么","如何获得火焰图腾"}}},fp="12,284,35.354.0,31.378.0,31.235.0,25.224.0,49.149.0,54.221.0,45.167.0,48.189.0"}
P.entries["quest:94466"] = {n="Call of Fire",s="Call of Fire是洛克莫丹的一项元素试炼，初学者在这里准备与永恒之火进行沟通，并获得他们的火焰图腾。在Braldir Ashmantle的引导下，候选人必须从当地的狗头人和穴居人那里收集元素试剂，以酿造一种具有约束力的火焰灵契。这次旅程教导人们，火焰不仅是毁灭的工具，更是锻造的源泉和生命的呼吸本身。",h="Call of Fire是洛克莫丹的一项元素试炼，初学者在这里准备与永恒之火进行沟通，并获得他们的火焰图腾。在Braldir...",kw={"braldir ashmantle","call of fire","永恒之火","火焰灵契","火焰焦油","火焰图腾","洛克莫丹","石窟预言者","隧道鼠地卜师"},ang={["class:Shaman"]="与火焰沟通需要通过专门的灵契建立元素纽带，从而通向与永恒之火的沟通并获得火焰图腾。",["faction:Alliance"]="这项试炼设定在矮人领地洛克莫丹，将萨满仪式牢牢扎根于联盟土地上，以对抗当地穴居人和狗头人的威胁。",["race:Dwarf"]="Braldir Ashmantle以一种朴实的、矮人的元素火焰视角在洛克莫丹指导初学者，将其视为锻造和创造的呼吸，而非单纯的破坏。"},sec={{t="火焰之路",b="在洛克莫丹崎岖的峭壁中，一位名叫Braldir Ashmantle的元素导师监督着那些寻求火焰力量的初学者的道路。与火灵沟通绝非简单的召唤；凡人的灵魂必须首先通过一种被称为火焰灵契的神圣药剂，与燃烧的元素相调和。没有这种准备，永恒之火的热量只会将人吞噬，而不会带来启迪。Braldir要求请求者从山谷的敌对居民那里收集两种与火焰紧密相连的关键试剂，以证明他们的决心。"},{t="大地与火花的试剂",b="制作火焰灵契需要富含元素共鸣的物质。在北方，隧道鼠地卜师在他们错综复杂的巢穴中采集粘稠的火焰焦油，为他们的地下魔法提供燃料。在南方，被称为石窟预言者的穴居人神秘主义者带着装满原始元素护身符的试剂袋穿过崎岖的丘陵。夺取这些物品需要与洛克莫丹最根深蒂固的两种害虫进行斗争，强行获取将初学者的灵魂与火焰绑定所需的材料。"},{t="智慧的磨砺",b="在收到试剂后，Braldir Ashmantle提供了用耐心来调节原始破坏力的智慧。对于这位经验丰富的导师来说，火焰不仅仅是愤怒和灰烬，它代表着生命、锻造工艺以及创造的呼吸本身。对元素真正的掌握在于平衡：正如阴影赋予光意义一样，火焰阻止石头仅仅成为冰冷的记忆。掌握火焰需要知道何时去融合，而不是仅仅去燃烧。"}},faq={{q="Call of Fire的目的是什么？",a="Call of Fire是渴望与永恒之火沟通的萨满祭司候选人的通过仪式。为了与火灵沟通并获得火焰图腾，必须首先准备一份火焰灵契，将他们凡人的灵魂与该元素绑定。",al={"什么是call of fire","这是一个什么任务","call of fire的目的"}},{q="Braldir Ashmantle是谁？",a="Braldir Ashmantle是一位居住在洛克莫丹的元素向导。他指导初学者掌握火焰的平衡，并在收集到适当的元素试剂后准备必要的火焰灵契。",al={"谁给予call of fire","braldir ashmantle是谁","braldir ashmantle的位置"}},{q="什么是火焰灵契？",a="火焰灵契是一种由火焰相关试剂制成的元素药剂或制剂。饮用或使用它会使萨满的灵魂与火焰元素位面相协调并绑定，从而实现与永恒之火的视觉沟通。",al={"什么是火焰灵契","火焰灵契有什么作用","为什么要用火焰灵契"}},{q="在哪里可以找到火焰焦油？",a="火焰焦油由居住在洛克莫丹北部狗头人洞穴中的隧道鼠地卜师携带。地卜师们利用这些焦油进行原始的火焰工艺。",al={"在哪里获得火焰焦油","火焰焦油位置","狗头人洞穴的火焰焦油"}},{q="在哪里可以找到石窟试剂袋？",a="试剂袋必须从潜伏在洛克莫丹南部丘陵的石窟预言者身上夺取。这些穴居人神秘主义者使用这些袋子来盛放与元素魔法相关的试剂。",al={"在哪里获得试剂袋","石窟预言者的试剂袋","石窟试剂袋位置"}},{q="Braldir Ashmantle如何看待火焰元素？",a="Braldir并没有将火焰视为盲目的破坏，而是教导说火焰是锻造、生命和创造的呼吸。它与其他力量保持平衡，通过调和冰冷的石头，赋予存在以温暖和意义。",al={"braldir对火焰的看法","洛克莫丹火焰的意义","矮人的火焰哲学"}}},fp="12,372,21.545.0,31.497.0,23.459.0,36.228.0,25.196.0,21.230.0,28.176.0,47.179.0,52.225.0"}
P.entries["quest:94467"] = {n="Call of Fire",s="Call of Fire是一项元素试炼，初学者需要饮下调制好的火焰灵契，以感知并面对一个次级火焰显化。通过制服这个灵魂并将余烬置于神圣火盆中，祈求者便能赢得火焰的眷顾。",h="Call of Fire是一项元素试炼，初学者需要饮下调制好的火焰灵契，以感知并面对一个次级火焰显化。通过制服这个灵魂并将余烬置于神圣火盆中，祈求者便能赢得火焰的眷顾。",kw={"火盆","call of fire","火焰灵契","余烬","次级火焰显化","萨满试炼","永恒火焰神龛"},ang={["class:Shaman"]="这是一项萨满与火焰沟通的基础试炼，需要使用神圣的灵契来感知并对抗火焰之灵。"},sec={{t="火焰仪式",b="Call of Fire是一项考验精神与勇气的传统试炼。在元素知识的指引下，初学者会获得一种调制好的火焰灵契，用以唤醒对不可见世界的感知。在神龛饮下药水并向山顶攀登时，凡人双眼与原始力量之间的界限会变得模糊，显露出一个等待挑战的沉睡火焰显化。"},{t="面对显化",b="与次级火焰显化的对抗是对决断力和耐力的考验。这个元素灵魂不会主动攻击，但一旦受到挑战，其强度会随着时间的推移而不断攀升。将其击败后会掉落余烬，必须将其带到永恒火焰神龛顶部的火盆中，点燃火炬以确保获得该灵魂持久的眷顾。"}},faq={{q="什么是Call of Fire？",a="Call of Fire是一项神圣的成人礼，初学者饮下特制的火焰灵契来感知火焰之灵，在战斗中与它对抗，并将它的余烬献给火盆，从而赢得火焰的眷顾。",al={"什么是call of fire","call of fire任务","火焰图腾试炼"}},{q="火焰灵契的用途是什么？",a="火焰灵契是一种调制好的药水，能够开启初学者的灵视，让他们看到在山顶等待他们的隐形元素之灵。",al={"火焰灵契用途","为什么要喝灵契","灵契有什么用"}},{q="试炼中会出现什么灵魂？",a="这项试炼要求初学者在山顶对抗一个次级火焰显化，它会一直等待直到受到攻击才加入战斗。",al={"我要和什么灵魂战斗","call of fire怪物","火焰显化"}},{q="为什么必须尽快击败火焰之灵？",a="战斗持续的时间越长，元素之灵就会变得越凶猛、越炽热，因此迅速、果断地出击对于在火焰变得势不可挡之前将其制服至关重要。",al={"为什么要快速击杀","call of fire战斗","火焰之灵计时"}},{q="余烬如何处理？",a="在击败次级火焰显化后，将其余烬带到永恒火焰神龛顶部的火盆中，点燃仪式火炬。",al={"余烬交到哪里","call of fire火盆","永恒火焰神龛火盆"}},{q="赢得火焰的眷顾意味着什么？",a="完成仪式并点燃火炬，将赢得火元素直接的眷顾与沟通，与火焰建立起至关重要的联系。",al={"奖励是什么","仪式有什么奖励","火焰眷顾"}}},fp="12,252,17.364.0,24.367.0,25.221.0,38.163.0,37.142.0,45.170.0,37.155.0,40.148.0"}
P.entries["quest:94468"] = {n="Call of Fire",s="Call of Fire 是一项神圣的试炼，学徒需要从俯瞰洛克莫丹的制高点取得恒焰火炬，并将其带到丹莫罗。将火焰带回导师 Bruegs Kindleborn 的身边，既证明了旅行者对元素的掌握，也能赢得属于他们的火焰图腾。",h="Call of Fire 是一项神圣的试炼，学徒需要从俯瞰洛克莫丹的制高点取得恒焰火炬，并将其带到丹莫罗。将火焰带回导师 Bruegs Kindleborn...",kw={"bruegs kindleborn","call of fire","丹莫罗","火焰图腾","烈焰之子","洛克莫丹","萨满祭司","恒焰火炬"},ang={["class:Shaman"]="这项仪式完成了卡兹莫丹萨满学徒的火焰试炼，使他们获得引导火焰并与火元素交流所需的火焰图腾。",["faction:Alliance"]="随着精神召唤在卡兹莫丹的联盟领地中扎根，像 Bruegs Kindleborn 这样的导师会引导新学徒掌握元素艺术。",["race:Dwarf"]="将火焰从洛克莫丹上方的山巅带回丹莫罗，反映了矮人精神追求者与其家园山脉的元素力量之间深厚的联系。"},sec={{t="洛克湖上的火焰",b="Call of Fire 标志着学徒在元素交流道路上的关键时刻。在山脊高处，狂风呼啸而过，学徒点燃了俯瞰洛克莫丹的恒焰火炬。跳动的火焰映照着觉醒的精神，激发起一种元素共鸣，学徒必须悉心呵护，沿着山路将其安全带回丹莫罗的雪谷之中。"},{t="烈焰之子的奖赏",b="在丹莫罗，元素导师 Bruegs Kindleborn 正在等待着旅行者，他将评判旅行者内心的火焰是否真正觉醒。呈上燃烧的火炬证明了请愿者拥有与火焰交流的意志和敬意。Kindleborn 会宣布学徒为“烈焰之子”，并授予火焰图腾，使其成为族群中元素指引的传承者。"}},faq={{q="什么是 Call of Fire？",a="Call of Fire 是卡兹莫丹萨满祭司的一项精神试炼。在俯瞰洛克莫丹的火盆处点燃恒焰火炬后，学徒必须带着燃烧的火焰穿过群山，回到丹莫罗寻找 Bruegs Kindleborn。",al={"什么是 call of fire","call of fire 任务","call of fire 要做什么"}},{q="Bruegs Kindleborn 是谁？",a="Bruegs Kindleborn 是一位居住在丹莫罗的导师和元素向导。他负责监督火焰的元素仪式，并向完成旅程的学徒授予火焰图腾。",al={"bruegs kindleborn 是谁","bruegs kindleborn 在哪里","bruegs kindleborn 位置"}},{q="什么是恒焰火炬？",a="恒焰火炬是一把神圣的仪式火炬，需要在俯瞰洛克莫丹的火盆处点燃。它象征着学徒与元素之火的内在连接，必须安全地带回丹莫罗交给 Bruegs Kindleborn。",al={"什么是恒焰火炬","恒焰火炬","在哪里获取火炬"}},{q="完成这项试炼能得到什么？",a="在安全地将恒焰火炬送到 Bruegs Kindleborn 手中后，这位导师会认可你那燃烧的精神，并授予你火焰图腾，标志着你已成为烈焰之子。",al={"call of fire 的奖励是什么","能获得火焰图腾吗","call of fire 图腾"}},{q="这段旅程发生在什么地方？",a="旅程始于俯瞰洛克莫丹的制高点（在那里点燃火炬），随后沿着山路返回积雪覆盖的丹莫罗领地，与 Bruegs Kindleborn 会合。",al={"call of fire 在哪里进行","call of fire 路径","要把火炬带到哪里"}},{q="为什么 Bruegs 会提到 Madoran？",a="Bruegs 发誓时所说的“以 Madoran 之胡须起誓”，指的是 Madoran Bronzebeard，即在三锤之战中带领铜须部族的受人尊敬的矮人领袖。",al={"为什么提到 madoran 的胡须","madoran 的含义","bruegs 提到的 madoran 是谁"}}},fp="12,280,23.390.0,22.396.0,25.244.0,25.182.0,35.231.0,47.173.0,35.181.0,32.161.0"}
P.entries["quest:94484"] = {n="Unnerving Silence",s="Unnerving Silence 起因于影风森林东北部一个洞穴内的德鲁伊隐修会突然中断了通讯。随着 Ban'aethall 的毁灭以及该地区日益动荡，一名调查员被派遣前往寻找 Elegael Thornpaw，以评估该隐修会的命运。",h="Unnerving Silence 起因于影风森林东北部一个洞穴内的德鲁伊隐修会突然中断了通讯。随着 Ban'aethall 的毁灭以及该地区日益动荡，一名调查员被派遣前往寻找 Elegael...",kw={"ban'aethall","德鲁伊","德鲁伊隐修会","elegael thornpaw","影风森林","unnerving silence"},ang={["class:Druid"]="与影风森林中一个隐居隐修会的联络中断，引起了那些致力于维持荒野平衡的德鲁伊们的直接关注。调查 Elegael Thornpaw 的沉默，是为了保护同胞并查明是什么破坏了他们的沟通。"},sec={{t="树冠下的寂静",b="Ban'aethall 陷落后，一片寂静的忧虑笼罩着荒野。那座村庄化为废墟，且神秘的动荡在领地内蔓延，原本稳固的联络线开始断裂。特别是影风森林东北部一处深藏在洞穴中的德鲁伊隐修会，他们定期的派遣突然中断，令盟友们感到不安。"},{t="寻找隐修会",b="前往影风森林的旅者肩负着寻找 Elegael Thornpaw 的重任，她是这些洞穴德鲁伊中的杰出人物。深入那阴影笼罩的东北部，调查员必须查明该隐修会究竟只是退隐以与自然进行更深层次的沟通，还是已经沦陷于摧毁了 Ban'aethall 的危险之中。"}},faq={{q="Unnerving Silence 这个任务是关于什么的？",a="Unnerving Silence 是一项调查任务，旨在探寻影风森林中一个德鲁伊隐修会突然失联的原因。忧心忡忡的当事人请求途经此地的旅者搜索东北部的一个洞穴，查明那个隐居的组织遭遇了什么。",al={"unnerving silence 任务","什么是 unnerving silence"}},{q="Elegael Thornpaw 在哪里可以找到？",a="Elegael Thornpaw 住在影风森林东北部边缘的一处洞穴中。她是驻扎在那里的隐居德鲁伊隐修会的联络人。",al={"elegael thornpaw 在哪里","elegael thornpaw 位置","寻找 thornpaw"}},{q="Elegael Thornpaw 是谁？",a="Elegael Thornpaw 是居住在影风森林东北部洞穴中的德鲁伊隐修会成员。她长期的沉默和未按时发送联络信息，引发了对该隐修会安全状况的严重担忧。",al={"谁是 elegael thornpaw","thornpaw 背景故事"}},{q="什么是影风森林？",a="影风森林是一片树木繁茂的区域，其东北部隐藏着一个德鲁伊洞穴隐修会。在广泛的地区动荡和 Ban'aethall 陷落后，与这片森林居住者之间的联络变得极度不稳定。",al={"什么是影风森林","影风森林隐修会"}},{q="什么是 Ban'aethall？",a="Ban'aethall 是影风森林深处的一座村庄，最近已化为废墟。它的毁灭，加上整个领地内更广泛的动荡，加剧了人们的担忧，即像影风森林隐修会这样的附近营地可能也处于危险之中。",al={"banaethall 发生了什么","banaethall 废墟背景故事","ban'aethall 陷落"}},{q="为什么德鲁伊隐修会没有消息了？",a="影风森林德鲁伊的定期信息和报告已莫名中断。鉴于 Ban'aethall 的毁灭以及地区局势的不断升级，人们严重担心他们可能遭遇了灾难或被敌对势力袭击。",al={"为什么德鲁伊停止发送信息","为什么德鲁伊保持沉默"}}},fp="17,288,21.392.0,19.349.0,42.260.0,36.179.0,24.235.0,26.244.0,20.248.0,39.251.0"}
P.entries["quest:94485"] = {n="Tears of the Lady",s="Tears of the Lady 是在影风森林中为 Elegael 执行的一项紧急救援任务。为了救治被困在 Nightclaw Den 中的受伤同伴，旅行者必须在当地的树干上搜寻 Lady's Tear，这是一种对于包扎严重伤口至关重要的防腐苔藓。",h="Tears of the Lady 是在影风森林中为 Elegael 执行的一项紧急救援任务。为了救治被困在 Nightclaw Den 中的受伤同伴，旅行者必须在当地的树干上搜寻 Lady's...",kw={"elegael","lady's tear","苔藓","nightclaw den","药膏","影风森林","tears of the lady"},ang={["class:Priest"]="虽然牧师们可以引导圣光来治愈凡人的伤势，但在魔法救援力量薄弱时，像 Lady's Tear 这样的天然药膏可以作为受伤幸存者的重要物理敷料。",["profession:Herbalism"]="草药师和战地医疗人员都很看重 Lady's Tear，因为它具有粘性的防腐分泌物，可以在荒野紧急情况下迅速封住伤口并防止感染。"},sec={{t="影风森林的绝望补救措施",b="在影风森林阴影笼罩的深处，Elegael 急需援助来救治被困在 Nightclaw Den 中的同伴。由于身负重伤的盟友正等待救援，且常规补给匮乏，需要直接从周围的荒野中搜寻野外医疗用品。这次行动的关键在于在被遗弃的伤员生命耗尽之前，获取到这些天然药物。"},{t="疗伤苔藓",b="Elegael 计划配制的药膏中，至关重要的成分是 Lady's Tear，这是一种附着在影风森林各处树木根部的细长苔藓。这种植物会分泌出一种粘稠的、具有天然防腐特性的分泌物，能够封住开放性伤口，并保护严重外伤免受潮湿荒野环境的影响而恶化。提供足够的苔藓，Elegael 就能配制出稳定伤者状况所需的敷料。"}},faq={{q="Tears of the Lady 是关于什么的？",a="Tears of the Lady 是由影风森林中的 Elegael 所指导的一项恢复工作。受伤的同伴仍被困在 Nightclaw Den 中，Elegael 需要当地的植物来配制紧急药膏以维持他们的生命。",al={"什么是 tears of the lady","tears of the lady 任务信息"}},{q="什么是 Lady's Tear？",a="Lady's Tear 是一种生长在影风森林各处树木根部的细长苔藓。它会分泌出一种天然的粘性树液，作为强效防腐剂，非常适合用于包扎和封盖开放性伤口。",al={"什么是 ladys tear","ladys tear 苔藓","什么是 lady's tear 苔藓"}},{q="谁是 Elegael？",a="Elegael 是一位组织了影风森林医疗救助工作的幸存者。在将受伤的同伴留在 Nightclaw Den 后，Elegael 正收集医疗物资以配制治疗用品，然后返回营救他们。",al={"谁是 elegael","tears of the lady 任务发布者"}},{q="什么是 Nightclaw Den？",a="Nightclaw Den 是影风森林附近的一个地点，Elegael 的几名受伤盟友被困在那里。他们的情况岌岌可危，迫使人们必须急切地搜集治疗草药。",al={"什么是 nightclaw den","nightclaw den 在哪里"}},{q="为什么 Elegael 需要 Lady's Tear 苔藓？",a="这种苔藓能提供一种重要的防腐分泌物，用于配制医用药膏。这种粘性物质可以封住开放性伤口，并帮助被困在洞穴中的幸存者抵御感染。",al={"为什么需要 ladys tear","这种苔藓有什么作用"}},{q="在哪里可以找到 Lady's Tear 苔藓？",a="Lady's Tear 苔藓通常附着在影风森林各处的树木根部。虽然 Elegael 已经收集了触手可及的部分，但还需要从周围的树林中搜寻更多。",al={"ladys tear 在哪里生长","寻找 ladys tear"}}},fp="17,263,32.369.0,16.398.0,42.203.0,20.224.0,15.219.0,26.190.0,39.194.0,32.198.0"}
P.entries["quest:94486"] = {n="Feathers for Binding",s="\"Feathers for Binding\" 是影风森林中的一项任务，主要目标是从幼年尖叫兽身上收集保温羽毛，用于制作保护性的药膏。虽然这些通常温顺的生物变得极具攻击性，但它们的羽毛对于保护杀菌药膏免受外界环境影响至关重要。冒险者必须勇敢面对这些充满敌意的幼崽，以获取区域护理所需的材料。",h="\"Feathers for Binding\"...",kw={"杀菌树液","feathers for binding","药膏","影风森林","影风森林尖叫兽","尖叫兽"},ang={["class:Druid"]="德鲁伊可能会对猎杀这些幼年林地野兽与任务发布者感同身受，尽管日益增长的攻击性和紧迫的医疗需求让人别无选择。",["profession:Herbalism"]="草药师和自然治疗者能够理解结合苔藓、杀菌树液和隔热羽毛来制作有效的战地敷料或药膏时的精妙平衡。"},sec={{t="森林疗法",b="在影风森林深处，准备战地药物往往需要从土地中寻找资源。在治疗重伤时，草药师和治疗者会使用一种基于苔藓和杀菌树液的特制药膏。为了确保药液不会迅速干涸或在恶劣天气下失去效力，需要耐用的绝缘敷料。影风森林幼年尖叫兽的羽毛提供了一种理想的天然屏障，既能保护伤口，又能封住药物。"},{t="反常的敌意",b="获取这些绒羽变得出乎意料地危险。在通常情况下，影风森林的幼年尖叫兽是温顺的林间居民。然而近来，一股莫名其妙的攻击性浪潮席卷了它们。这些幼年掠食者挥舞着足以造成致命伤的强力爪子，现在会凶猛地攻击路人。收集它们的羽毛需要冒险者面对这些从无害幼崽转变为真正威胁的生物。"},{t="令人遗憾的必要之举",b="要求旅行者猎杀幼年生物让当地的看护者感到沉重，他们公开哀悼这种淘汰的必要性。然而，随着多重紧急情况威胁着该地区，且这些野兽变得越来越危险，减少它们的数量具有双重目的：收集重要的治疗材料，同时压制森林道路上日益增长的威胁。每一根收集到的羽毛都受到尊重，以确保它们的牺牲没有被浪费。"}},faq={{q="为什么药膏需要影风森林尖叫兽的羽毛？",a="幼年影风森林尖叫兽的羽毛具有天然的隔热特性。放在苔藓层上，它们可以作为一种保护性敷料，防止杀菌药液干涸，同时保护伤口免受恶劣环境的影响。",al={"羽毛的用途","为什么使用尖叫兽羽毛","药膏羽毛"}},{q="幼年尖叫兽有多危险？",a="虽然影风森林尖叫兽通常是温顺的生物，但它们最近变得异常具有敌意。尽管它们还很年幼，但却拥有巨大的利爪，足以剖开毫无防备的旅行者的腹部。",al={"尖叫兽的危险性","尖叫兽危险吗","尖叫兽的攻击性"}},{q="为什么要猎杀幼年尖叫兽而不是成年个体？",a="任务发布者对捕杀幼兽表示了由衷的悔意。然而，由于它们突然激增的攻击性，以及需要应对其他相互竞争的荒野紧急情况，在收集所需药物的同时减少它们的数量被认为是一项痛苦的必要之举。",al={"为什么要杀死幼年尖叫兽","杀死幼年尖叫兽"}},{q="在哪里可以找到影风森林尖叫兽？",a="影风森林尖叫兽在影风森林的林冠和灌木丛中游荡，旅行者必须小心穿过树林才能追踪到它们。",al={"影风森林在哪里","尖叫兽位置","尖叫兽在哪里"}},{q="除了这些羽毛外，还使用了哪些其他成分？",a="这种药膏由当地的苔藓和杀菌树液分层组成，然后用从幼年尖叫兽身上采集的绒羽进行包裹和隔热。",al={"药膏成分","药膏里有什么"}},{q="为什么尖叫兽最近变得如此具有敌意？",a="它们突然产生敌意的确切原因尚不清楚，但这些平时温和的幼兽变得异常好斗，这增加了当地看护者所面临的危机。",al={"为什么尖叫兽很愤怒","尖叫兽攻击性的原因"}}},fp="20,414,22.495.0,26.496.0,23.457.0,63.255.0,43.212.0,58.263.0,43.154.0,63.160.0,50.207.0"}
P.entries["quest:94487"] = {n="Unwanted and Unworthy",s="Unwanted and Unworthy是泽弗拉斯（Zephras）上的一个任务，冒险者们将在任务中协助埃雷加尔（Elegael）对奥拉凯斯（Al'Aketh）邪教徒进行报复，此前这些邪教徒在影风森林（Shadowgale Forest）发动了一场血腥的伏击。玩家通过击杀邪教徒并找回被盗的传家宝，为牺牲的德鲁伊复仇，并为大长老（High Elder）收回神圣的祖传遗物。",h="Unwanted and...",kw={"奥拉凯斯","染血的传家宝","埃雷加尔","步兵","传家宝","影风森林","shen'dorei","风暴追猎者","泽弗拉斯"},ang={["class:Druid"]="奥拉凯斯邪教徒在对泽弗拉斯的无端袭击中流下了当地德鲁伊的鲜血，使得这次打击成为了一次直接的复仇行动，也是对自然平衡的捍卫。"},sec={{t="影风森林的伏击",b="当奥拉凯斯邪教徒在影风森林对当地德鲁伊发动突然袭击时，泽弗拉斯宁静的平衡被瞬间打破。埃雷加尔曾认为这些狂热者不过是“脑子里塞满云雾”的无害梦想家，却因他们袭击手段的极度残忍而措手不及。这场袭击导致德鲁伊的鲜血洒满了森林，引发了对肇事的步兵和风暴追猎者进行迅速报复的呼声。"},{t="被玷污的传家宝与逝去的青春",b="对埃雷加尔来说，邪教徒的背叛剥夺了他们的传承：他们不再配被称为shen'dorei，他们的遗骸也不配得到故乡之风的吹拂。许多邪教徒是原本拥有光明未来却因狂热而生命过早终结的年轻人。通过找回他们血迹斑斑的传家宝，冒险者们协助确保这些神圣物品被交还给大长老，等待更睿智、更值得拥有的下一代。"}},faq={{q="谁是奥拉凯斯邪教徒？",a="奥拉凯斯邪教徒是一群活跃在泽弗拉斯岛上、痴迷于风暴的狂热信徒。据埃雷加尔所言，他们曾经只被视为愚蠢或“脑子里塞满云雾”，但他们突然对当地德鲁伊转向了残暴的暴力行径。",al={"奥拉凯斯是谁","奥拉凯斯邪教","邪教徒是谁"}},{q="谁是埃雷加尔？",a="埃雷加尔是泽弗拉斯的一位shen'dorei守护者或德鲁伊，曾遭到奥拉凯斯邪教徒的伏击。由于对年轻生命的背叛和流血事件感到悲痛，埃雷加尔寻求报复并找回被盗的祖传遗物。",al={"埃雷加尔是谁","任务发布者埃雷加尔"}},{q="什么是染血的传家宝？",a="这些染血的传家宝属于那些被卷入奥拉凯斯邪教的年轻shen'dorei。埃雷加尔收集它们，以便最终能归还给大长老的收藏，并传给未来更值得拥有的后代。",al={"染血的传家宝","为什么要收集传家宝","什么是传家宝"}},{q="什么是shen'dorei？",a="shen'dorei是居住在泽弗拉斯的族群。埃雷加尔认为，奸诈的奥拉凯斯邪教徒因其暴力的背叛和对岛屿和谐的亵渎，已经失去了被称为shen'dorei的权利。",al={"shen'dorei的含义","什么是shen'dorei"}},{q="影风森林在哪里？",a="影风森林是位于泽弗拉斯的一片林区，奥拉凯斯步兵和风暴追猎者在此活动，这也是针对德鲁伊的无端伏击发生的地方。",al={"影风森林位置","影风森林在哪里"}},{q="为什么奥拉凯斯邪教徒要伏击德鲁伊？",a="这些邪教徒的具体动机对埃雷加尔来说仍是一个令人不安的谜团。尽管长期以来他们被视为无害的狂热者，但他们突然且恶毒的暴动打破了岛上维持的脆弱平衡。",al={"邪教徒为何攻击","邪教动机","为何伏击德鲁伊"}}},fp="21,304,27.471.0,32.425.0,30.258.0,15.240.0,32.229.0,24.224.0,27.171.0,48.201.0"}
P.entries["quest:94488"] = {n="The Ties That Bind",s="“The Ties That Bind”是影风森林中的一个任务，其核心在于德鲁伊教团内部的一场痛苦背叛。艾蕾加尔·荆爪发现失踪的教团德鲁伊哈林投靠了入侵的邪教徒并担任指挥官，于是下令将其处决。当亲人背叛了自己的种族时，这个任务揭示了履行职责所要付出的惨痛个人代价。",h="“The Ties That...",kw={"塞纳里奥议会","哈林指挥官","邪教徒","德鲁伊","艾蕾加尔·荆爪","哈林","影风森林","the ties that bind"},ang={["class:Druid"]="塞纳里奥议会将维护平衡与亲缘视为神圣之事，因此哈林的背叛以及他在教团德鲁伊同僚之间造成的血腥杀戮，被视为对该组织尤为严重的冒犯。"},sec={{t="森林中的背叛",b="在影风森林深处，德鲁伊们遭遇了一群凶残的邪教徒，他们播撒着恐怖与鲜血。对于艾蕾加尔·荆爪来说，这场袭击因为一个痛苦的发现而变得更加沉重：在屠杀现场弥漫着前教团德鲁伊哈林的气息。哈林几个月前就失踪了，但他并没有在荒野中丧生，而是投靠了入侵的邪教徒，指挥他们对昔日的同胞发起了残酷的攻势。"},{t="血缘与羁绊",b="哈林的背叛不仅是违背了对塞纳里奥议会的誓言。当艾蕾加尔呈上这位阵亡指挥官的首级时，她透露哈林其实是她的表亲。尽管她对他的暴行感到愤怒，但亲手处决自己的亲人依然是她独自难以承受的重担。他的死为这个恶行导致无数无辜生命逝去的叛徒画上了一个血腥的句号。"}},faq={{q="谁提供了“The Ties That Bind”这个任务？",a="艾蕾加尔·荆爪是一名驻扎在影风森林的德鲁伊。在应对邪教徒入侵的过程中，她在发现哈林指挥官参与了屠杀后，指引冒险者去将他除掉。",al={"谁给予the ties that bind任务","影风森林任务发布者","谁是艾蕾加尔·荆爪"}},{q="哈林指挥官是谁？",a="哈林指挥官曾是塞纳里奥议会的一名德鲁伊，在邪教徒袭击前几个月失踪。他并没有成为步步逼近的黑暗的受害者，而是主动加入了敌对的邪教徒，并指挥他们的军队对抗自己的同胞。",al={"谁是哈林","哈林指挥官背景故事","哈林背景"}},{q="为什么艾蕾加尔想要哈林指挥官死？",a="哈林背弃了他的德鲁伊教团，指挥邪教徒屠杀无辜生命，并沾染了同僚的鲜血。由于他的所作所为以及对森林构成的威胁，艾蕾加尔下令将他处决。",al={"为什么要杀死哈林","哈林的罪行","哈林做了什么"}},{q="艾蕾加尔·荆爪和哈林之间有什么关系？",a="哈林指挥官是艾蕾加尔·荆爪的表亲。虽然她对他的罪行深感愤怒，但她承认，亲手处决自己的血亲将是一个沉重的负担，因此她决定请求冒险者的帮助。",al={"艾蕾加尔和哈林的关系","艾蕾加尔和哈林是如何认识的"}},{q="为什么邪教徒会出现在影风森林？",a="邪教徒出现在影风森林的确切动机即便是当地德鲁伊也感到困惑。然而，他们的队伍是由像哈林这样的前教团成员带头的，正是他指挥了针对森林守护者的暴力与屠杀。",al={"影风森林的邪教徒","为什么邪教徒在影风森林"}},{q="这个任务发生在什么地方？",a="任务事件发生在影风森林内，艾蕾加尔·荆爪在那里调查邪教徒的入侵，并面对表亲背叛的残酷现实。",al={"the ties that bind发生在哪里","影风森林位置"}}},fp="18,345,22.444.0,17.377.1,40.204.0,25.258.0,45.218.0,60.221.0,50.254.0,33.174.0"}
P.entries["quest:94489"] = {n="The Wounds of Betrayal",s="The Wounds of Betrayal 是影风森林中的一个任务，围绕着针对稀有的辛多雷德鲁伊的惨烈袭击后的余波展开。伊莱加尔派遣玩家将紧急草药膏送到夜牙洞穴，救治她受伤的同胞，并寻找失踪的伴侣乔雷尔·风歌。这次任务很快揭示了背叛带来的苦涩代价，并引发了针对奥拉凯斯的复仇冲突。",h="The Wounds of Betrayal...",kw={"奥拉凯斯","德鲁伊","伊莱加尔","乔雷尔·风歌","夜牙洞穴","影风森林","辛多雷","the wounds of betrayal"},ang={["class:Druid"]="作为荒野的德鲁伊守护者，目睹同道修行者——特别是稀有的辛多雷德鲁伊——屈服于背叛和重伤，背负着沉重的个人情感负担。",["race:NightElf"]="暗夜精灵崇尚德鲁伊传统，这使得影风森林中同胞德鲁伊的苦难以及与背叛的斗争产生了深刻的共鸣。"},sec={{t="对辛多雷的援助",b="The Wounds of Betrayal 始于伊莱加尔，一位在影风森林中处理毁灭性袭击后果的辛多雷德鲁伊。在匆忙准备了药用草药膏后，她急需一名冒险者将援助送到撤退至附近夜牙洞穴的同胞手中，那里就在穿过空地的北面。辛多雷德鲁伊的人数极其稀少，因此每一位成员的幸存对于他们脆弱的聚居地来说都至关重要。"},{t="寻找乔雷尔·风歌",b="除了为洞穴中七位受伤的德鲁伊提供紧急救治外，伊莱加尔心中还有一个恳求：寻找她的伴侣乔雷尔·风歌。当她为了准备药物而逃离战斗时，乔雷尔已是奄奄一息。冒险深入夜牙洞穴的黑暗深处，揭示了圣地所遭受的真正破坏，以及乔雷尔所面临的残酷命运。"},{t="复仇誓言",b="在得知乔雷尔的悲惨结局以及同胞们遭受的恐怖伤亡后，伊莱加尔的冷静因悲痛与愤怒而崩塌。她咬牙切齿，带着痛苦的咆哮，摒弃了绝望，转而寻求彻底的报复，发誓任何与阴影中的奥拉凯斯结盟的人，都将因屠杀她的族人而遭受她无情的愤怒。"}},faq={{q="是谁发布了 The Wounds of Betrayal 任务？",a="该任务由伊莱加尔发布，她是一位辛多雷德鲁伊，在影风森林发生暴力袭击后，正绝望地试图救治她受伤的同胞。",al={"谁发布了 the wounds of betrayal","the wounds of betrayal 任务发布者","伊莱加尔是谁"}},{q="夜牙洞穴位于哪里？",a="夜牙洞穴是一个位于影风森林穿过空地北面的洞穴，受伤的辛多雷德鲁伊已撤退至此寻求庇护。",al={"夜牙洞穴在哪里","夜牙洞穴位置","受伤的德鲁伊在哪里"}},{q="乔雷尔·风歌是谁？",a="乔雷尔·风歌是伊莱加尔的伴侣。他在袭击中身受重伤并留在了夜牙洞穴内，玩家会在那里发现他悲惨的命运。",al={"乔雷尔·风歌是谁","乔雷尔·风歌的命运","乔雷尔在哪里"}},{q="什么是辛多雷德鲁伊？",a="辛多雷是一个稀有的群体，其中只有极少数德鲁伊修行者。由于他们人数稀少，伊莱加尔强调，他们当中幸存的每一个生命都极其珍贵。",al={"什么是辛多雷","谁是辛多雷德鲁伊","辛多雷德鲁伊背景故事"}},{q="奥拉凯斯是谁？",a="奥拉凯斯是应对袭击或与袭击德鲁伊者结盟的敌人。在得知乔雷尔的命运和她教派所受的毁灭性打击后，伊莱加尔发誓要向奥拉凯斯及其任何盟友复仇。",al={"谁是奥拉凯斯","奥拉凯斯","伊莱加尔为何憎恨奥拉凯斯"}},{q="在任务中乔雷尔·风歌发生了什么？",a="当你找到夜牙洞穴中的乔雷尔·风歌时，你发现他的情况发生了悲剧性的转变。带着他的命运以及幸存德鲁伊的严峻处境的消息返回找伊莱加尔，使她陷入了悲痛，并立下了愤怒的复仇誓言。",al={"乔雷尔·风歌发生了什么","乔雷尔还活着吗","乔雷尔的结局"}}},fp="22,394,22.448.0,31.390.1,20.340.2,43.149.0,31.148.0,24.157.0,31.191.0,21.223.0,46.232.0"}
P.entries["quest:94490"] = {n="Ripped Missive",s="Ripped Missive是从Haalien身上找回的一封血迹斑斑的信件，它揭示了一场针对影风森林中一座德鲁伊大兽穴的残酷邪教徒袭击。信中的内容揭露了这场屠杀背后冷酷的动机，并暗示了源自瓦拉纳尔内部的危险颠覆活动。",h="Ripped Missive是从Haalien身上找回的一封血迹斑斑的信件，它揭示了一场针对影风森林中一座德鲁伊大兽穴的残酷邪教徒袭击。信中的内容揭露了这场屠杀背后冷酷的动机，并暗示了源自瓦拉纳尔内部的危险颠覆活动。",kw={"邪教徒","德鲁伊大兽穴","elegael thornpaw","haalien","lotheluum","晶塔","ripped missive","影风森林","瓦拉纳尔"},ang={["class:Druid"]="德鲁伊们会在这封信中发现悲惨的苦果，信中揭露了在大兽穴中被屠杀的德鲁伊仅仅是因为挡了那些寻找远古晶塔的邪教徒的路。"},sec={{t="血迹斑斑的命令",b="这份破损且沾满血迹的文件被塞在Haalien的护腕后面，其中包含有关最近影风森林中发生的暴力事件的严峻情报。在激烈的冲突后找回，这片文字揭示了袭击当地德鲁伊大兽穴的邪教徒的阴暗意图，为那些寻求为死者伸张正义的人提供了重要的线索。"},{t="无谓的屠杀",b="当把这张羊皮纸交给影风森林的Elegael Thornpaw时，这次突袭的可怕真相大白了。邪教徒并非因为与德鲁伊有特定的积怨才发动袭击；他们是为了寻找一座神秘的晶塔，仅仅因为大兽穴的居民挡了他们的路就将其杀害。Elegael对这场无谓的屠杀感到愤怒，誓要向森林中残留的任何邪教徒复仇。"},{t="瓦拉纳尔的背叛",b="除了揭示邪教徒对晶塔的关注外，这封信还带来了一个更令人震惊的消息：指令似乎直接源自瓦拉纳尔。这一严峻的事实指向了在定居点内部活动的叛徒。为了在更多生命逝去之前揭露这个阴谋，必须立即将此信件送到瓦拉纳尔的Lotheluum手中。"}},faq={{q="什么是Ripped Missive？",a="Ripped Missive是一封在战斗后发现被塞在Haalien护腕后面的血迹斑斑、破损的信件。它包含揭露邪教徒袭击影风森林德鲁伊大兽穴动机的关键情报。",al={"什么是ripped missive","ripped missive任务","血迹斑斑的便条 haalien"}},{q="这封信是从哪里找回的？",a="这封信是直接从Haalien身上找回的，是在一场激烈的对峙后发现被塞在他们的一个护腕后面。信件在战斗中受损并沾染了血迹。",al={"谁掉落了ripped missive","ripped missive来自哪里","haalien是谁"}},{q="谁应该收到Ripped Missive？",a="这封信最初被带给影风森林的Elegael Thornpaw。在阅读了这份文件后，Elegael指示将其迅速送到瓦拉纳尔的Lotheluum手中，以警告潜在的背叛。",al={"谁需要ripped missive","我应该把ripped missive交给谁","elegael thornpaw 信件"}},{q="为什么邪教徒袭击德鲁伊大兽穴？",a="信件揭示，邪教徒袭击德鲁伊大兽穴并非出于对德鲁伊本身的仇恨，而是为了夺取位于那里的一座晶塔。居住在其中的德鲁伊仅仅因为挡在邪教徒的路上就被无情地杀害了。",al={"为什么邪教徒袭击德鲁伊大兽穴","邪教徒在大兽穴的动机","为什么haalien发动袭击"}},{q="袭击命令源自何处？",a="信件表明邪教徒的指令源自瓦拉纳尔，暗示有一名叛徒正隐藏在定居点内部并策划行动。",al={"命令来自哪里","谁派遣了haalien","瓦拉纳尔的叛徒"}},{q="Lotheluum是谁，为什么要通知他们？",a="Lotheluum是位于瓦拉纳尔的一位联系人。Elegael Thornpaw命令The Adventurer将这封信带给Lotheluum，提醒他们邪教徒的致命指令可以追溯到隐藏在瓦拉纳尔的某个人。",al={"lotheluum是谁","为什么要把信件带给lotheluum","lotheluum 瓦拉纳尔"}}},fp="14,284,19.354.0,19.423.1,21.365.2,27.233.0,36.185.0,38.203.0,42.255.0,38.175.0,47.204.0"}
P.entries["quest:94491"] = {n="The Fate of the Den",s="《大兽穴的命运》讲述了邪教徒突袭隐秘德鲁伊大兽穴后的惨烈余波。一位冒险者被派遣将一份寻获的信件送往瓦拉纳尔的洛瑟鲁姆，带去伤亡惨重的消息。这份公文揭露了一个令人深感不安的事实：瓦拉纳尔内部有人一直向敌人提供关键情报。",h="《大兽穴的命运》讲述了邪教徒突袭隐秘德鲁伊大兽穴后的惨烈余波。一位冒险者被派遣将一份寻获的信件送往瓦拉纳尔的洛瑟鲁姆，带去伤亡惨重的消息。这份公文揭露了一个令人深感不安的事实：瓦拉纳尔内部有人一直向敌人提供关键情报。",kw={"邪教徒","德鲁伊大兽穴","大长老","洛瑟鲁姆","信件","the fate of the den","叛徒","瓦拉纳尔"},ang={["class:Druid"]="德鲁伊们深刻地感受到了这场悲剧的沉重，因为在大兽穴倒下的是他们的同伴，而他们隐秘的避难所却被背叛给了敌对的邪教徒。"},sec={{t="大兽穴的惨剧",b="在邪教徒对德鲁伊大兽穴发动暴力入侵后，幸存的守卫者们饱受摧残，哀悼着同伴的逝去。尽管在外部援助下，紧迫的危机得到了控制，但无论是肉体上还是精神上的创伤都极其巨大。倒下的人无法复生，而身负重伤的幸存者在附近仍有残留邪教徒徘徊的情况下，也无力进行长途跋涉。"},{t="瓦拉纳尔的背叛",b="一份寻获的信件证实，邪教徒并非随机行事；瓦拉纳尔内有人一直潜伏其中，向他们积极泄露情报。当洛瑟鲁姆看到这份公文时，他对同伴的屠杀以及有人在他们的定居点内逍遥法外这一恐怖暗示感到极其惊恐。他下定决心不能让他们的牺牲被遗忘，于是将证据直接呈交给了大长老。"}},faq={{q="洛瑟鲁姆是谁？",a="洛瑟鲁姆是瓦拉纳尔的一位人物，负责接收有关德鲁伊大兽穴的报告。在得知袭击事件并审阅了那份寻获的信件后，他为阵亡的同伴深感悲痛，并发誓要将背叛的证据直接呈交给大长老。",al={"洛瑟鲁姆","洛瑟鲁姆是谁","洛瑟鲁姆npc"}},{q="德鲁伊大兽穴发生了什么？",a="德鲁伊大兽穴遭到了敌对邪教徒的毁灭性打击，导致多名守卫者死亡。尽管在一位冒险者的帮助下消除了直接威胁，但幸存的保护者们已伤痕累累，并发现了这次袭击是在内部人员指引下进行的证据。",al={"大兽穴发生了什么","德鲁伊大兽穴袭击","大兽穴的命运背景故事"}},{q="那份寻获的信件揭露了什么？",a="信件揭露，潜伏在瓦拉纳尔定居点内的一名内应一直在秘密向邪教提供情报。这些情报表明，针对大兽穴的致命突袭正是通过当地的破坏活动和间谍行为才得以实现。",al={"信件说了什么","大兽穴信件","背叛信件"}},{q="洛瑟鲁姆提到的大长老是谁？",a="大长老是瓦拉纳尔的一位显赫权威，洛瑟鲁姆向其负责。由于伤亡惨重且面临现行叛徒的威胁，洛瑟鲁姆立即将信件和惨剧的消息上报给了大长老。",al={"大长老是谁","瓦拉纳尔大长老","大长老"}},{q="谁该为袭击德鲁伊大兽穴负责？",a="这次袭击是由在该地区活动的邪教成员执行的。多亏了瓦拉纳尔内部一名内应的指引，邪教徒成功对大兽穴的居民造成了灾难性的损失。",al={"谁袭击了大兽穴","谁袭击了德鲁伊大兽穴","大兽穴邪教徒"}},{q="为什么大兽穴的幸存者不能亲自递送信件？",a="大兽穴的幸存者在袭击后伤势过重，无法承受前往瓦拉纳尔的长途跋涉。除了身体状况不适合赶路之外，幸存者还留下来清除残余的邪教徒，并派出一名冒险者前去报信。",al={"为什么要递送信件","任务发布者受伤","为什么幸存者不能去瓦拉纳尔"}}},fp="19,339,18.413.0,21.447.1,17.277.0,31.280.0,39.251.0,45.245.0,48.210.0,69.250.0"}
P.entries["quest:94494"] = {n="Call of Water",s="“水之召唤”是一项精神试炼，旨在让萨满祭司能够与水元素的净化本质进行沟通。在与风、地、火元素达成和谐后，受训者将前往洛克莫丹寻找诺里克·洛克塔恩，他会敦促受训者迈出学习水之纯净的第一步。",h="“水之召唤”是一项精神试炼，旨在让萨满祭司能够与水元素的净化本质进行沟通。在与风、地、火元素达成和谐后，受训者将前往洛克莫丹寻找诺里克·洛克塔恩，他会敦促受训者迈出学习水之纯净的第一步。",kw={"call of water","元素","大山","纯净","萨满","图腾试炼","水之图腾"},ang={["class:Shaman"]="这项试炼标志着与元素灵魂调谐的基本步骤，从大地和火焰开始，进而理解水的流动性与纯净。",["race:Dwarf"]="导师那粗犷的矮人语调反映了矮人萨满是如何通过崎岖的山路来与自然进行沟通的。"},sec={{t="纯净之道",b="“水之召唤”是萨满祭司元素平衡之旅中至关重要的一步。随着大地让每一步变得扎实，狂风在身后呼啸，心中的火焰熊熊燃烧，旅行者被召唤去领悟水的深层本质。它不仅是一种外部力量，更是纯净与坚韧的精神体现。"},{t="元素的飞升",b="在一位有着山峰般稳重语调的资深导师的指引下，受训者被催促着毫不犹豫地前进。萨满的共鸣从不会轻易授予；它需要肉体的努力、坚韧的精神以及对崎岖地形的攀登。正如导师所警告的那样，大山不会等待任何人，通往真正理解的旅程必须从那决定性的第一步开始。"}},faq={{q="什么是水之召唤？",a="“水之召唤”代表了萨满祭司寻求与水元素沟通的精神洗礼。在已经领悟了大地之稳固、风之疾驰和火焰之火花后，请求者被召唤去学习水之深层真理。",al={"什么是水之召唤","水之召唤任务","这个任务是什么"}},{q="谁指引了这段旅程？",a="铁炉堡的萨满训练师艾尔德兰·风暴断裂者将受训者指引至洛克莫丹的诺里克·洛克塔恩处。诺里克说了这番话，敦促受训者采取果断行动，并提醒旅行者，元素与高地不会等待犹豫不决的人。",al={"谁给予水之召唤","谁说大山不会等待任何人","水之召唤导师"}},{q="“大山不会等待任何人”是什么意思？",a="这是迈出艰苦攀登第一步的号召。萨满的旅程往往通向灵魂居住的高峰和偏远荒野，这需要坚定的决心，而不是徘徊不定的怀疑。",al={"大山不会等待任何人是什么意思","大山不会等待任何人","大山的含义"}},{q="水之纯净的真理是什么？",a="在萨满的修行中，每种元素都提供独特的教导。如果说岩石提供了稳定性，火焰点燃了决心，那么水则体现了净化、流动与纯净——这是平衡内心灵魂的重要智慧。",al={"为什么是水之纯净","水之纯净的真理","水元素的含义"}},{q="在这里水与其他元素有何关联？",a="这段旅程承认大地、风和火是已经在脚步、呼吸和腹中感受到的基础，然后才接触水。与元素和谐共处需要掌握平衡，而不是孤立地追求单一的力量。",al={"哪些元素优先","水的先决条件","水之召唤元素"}},{q="受训者听完这些话后要去哪里？",a="受训者必须迈出第一步。诺里克·洛克塔恩会派他们前往湿地，寻找住在南部瀑布下方洞穴里的赫夫达娜·萨格伦德，以获取水之水塔。",al={"水之召唤下一步会发生什么","我现在要去哪里","水之召唤的下一步"}}},fp="13,294,18.336.0,24.387.0,26.259.0,36.248.0,53.197.0,36.224.0,49.230.0,53.182.0"}
P.entries["quest:94495"] = {n="Call of Water",s="“水之召唤”将精神探索者派遣至湿地，去领悟水的净化之力并寻找水之萨普塔。在南侧瀑布下方的一处隐蔽洞穴中，矮人赫薇达娜·萨格伦德迎接那些勇闯荒野的旅者。",h="“水之召唤”将精神探索者派遣至湿地，去领悟水的净化之力并寻找水之萨普塔。在南侧瀑布下方的一处隐蔽洞穴中，矮人赫薇达娜·萨格伦德迎接那些勇闯荒野的旅者。",kw={"call of water","矮人","赫薇达娜·萨格伦德","萨满祭司","南侧瀑布","water sapta","湿地"},ang={["class:Shaman"]="该任务是学习水的本质并获取水之萨普塔以与水之灵沟通的重要一步。",["faction:Alliance"]="这段旅程将旅者带入危险的湿地深处，远离任何矮人或联盟的巡逻队。",["race:Dwarf"]="赫薇达娜认出这位寻求者是敢于在危险的沼泽地和潜伏的黑铁矮人面前闯荡的同胞。"},sec={{t="水的本质",b="理解水的旅程始于关于其双重本质的简单课程：水象征着重生，在纯净时能切石净污，但一旦被污染，它便会带来毁灭。寻求沟通的初学者被派遣到野外，从那些栖居于水元素旁的人那里获取水之萨普塔。"},{t="瀑布下的庇护所",b="在湿地潮湿的沼泽深处，赫薇达娜·萨格伦德和她的家人居住在一个直接位于南侧瀑布下方的隐蔽洞穴中。他们远离铁炉堡卫兵的保护，忍受着潜伏在周围沼泽中的黑铁矮人的威胁，以维持他们在奔流瀑布旁的隐居生活。"}},faq={{q="赫薇达娜·萨格伦德是谁？",a="赫薇达娜·萨格伦德是一位矮人，她与家人住在湿地南侧瀑布下方的一个洞穴里。她帮助那些寻求与水沟通以及探索水之萨普塔秘密的萨满祭司。",al={"赫薇达娜是谁","赫薇达娜·萨格伦德","赫薇达娜在哪里"}},{q="什么是水之萨普塔？",a="水之萨普塔是萨满祭司用来与水之灵沟通的一种仪式药剂。在东部王国，寻求者会被指引去南侧瀑布附近找赫薇达娜·萨格伦德获取此物。",al={"什么是水之萨普塔","萨普塔含义","为什么要获取水之萨普塔"}},{q="在哪里可以找到赫薇达娜·萨格伦德？",a="赫薇达娜和她的家人隐居在湿地南侧瀑布正下方的一个洞穴里。",al={"赫薇达娜住在哪里","洞穴在哪里","南侧瀑布位置"}},{q="为什么赫薇达娜要住在危险的湿地？",a="尽管沼泽中潜伏着黑铁矮人，且完全没有城市守卫的保护，赫薇达娜和她的族人出于各自的原因，选择了这个瀑布洞穴作为隐居之所。",al={"为什么住在湿地","湿地的危险","湿地的黑铁矮人"}},{q="这里传授的水的课程是什么？",a="水代表着重生，在纯净时可以切开岩石、洗净污垢、安抚疲惫。然而，如果受到腐蚀或污染，它会摧毁所触及的一切。",al={"水意味着什么","水的哲学","水的课程"}},{q="“水之召唤”任务的目的是什么？",a="“水之召唤”是萨满祭司的一项成人仪式，引导初学者理解水元素的本质，并从隐居的向导那里寻找水之萨普塔。",al={"这是什么类型的任务","这是为谁准备的任务","矮人萨满任务"}}},fp="13,235,19.304.0,25.334.0,25.190.0,24.195.0,37.118.0,49.209.0,40.160.0,47.150.0"}
P.entries["quest:94497"] = {n="Call of Water",s="“水之召唤”是在湿地进行的一项精神任务，指引修行者走上获取萨普塔的道路。通过在山间瀑布与海潮交汇的咸淡水入海口收集水源，寻求者在穿越沼泽的危险时，也能领悟到水的生命能量。",h="“水之召唤”是在湿地进行的一项精神任务，指引修行者走上获取萨普塔的道路。通过在山间瀑布与海潮交汇的咸淡水入海口收集水源，寻求者在穿越沼泽的危险时，也能领悟到水的生命能量。",kw={"call of water","黑铁矮人","入海口","赫瓦娜","萨普塔","水囊","湿地"},ang={["class:Shaman"]="寻求萨普塔需要理解不同土地上水的本质，使精神与水的各种表现形式相调和。",["race:Dwarf"]="赫瓦娜感叹着矮人氏族之间挥之不去的分裂，尤其是当黑铁矮人甚至入侵到湿地这样偏北的地方时。"},sec={{t="萨普塔之道",b="为了获得萨普塔并与灵魂沟通，修行者必须寻找各种形态的水。赫瓦娜指引寻求者观察水是如何流动、如何改变生命以及滋养大地。这段旅程始于理解入海口的水，那里是大海的潮汐与高地淡水径流汇合之处。"},{t="淡水与咸水交汇之处",b="在赫瓦娜洞穴下方的瀑布底部，高地泉水流入沼泽，与被海潮带入内陆的咸水相撞。海潮携带的沉积物、矿物质和能量与清澈的山间融雪截然不同，这使得入海口成为了自然智慧的源泉。"},{t="沼泽中的阴影",b="在湿地收集水源并非没有危险。除了危险的沼泽生物外，黑铁矮人也已经向北推进，进入了令人不安的距离。赫瓦娜怀着遗憾注视着矮人氏族之间持续不断的敌对状态，并感叹如果他们能放下世仇，矮人一族本可以取得多么伟大的成就。"}},faq={{q="什么是萨普塔？",a="萨普塔是一种用于与元素之灵沟通的神圣饮品。为了获得它，修行者必须寻找各种状态的水，并理解它如何塑造大地以及滋养万物。",al={"什么是萨普塔","萨普塔的含义","为何寻找萨普塔"}},{q="赫瓦娜是谁？",a="赫瓦娜在她位于湿地瀑布上方的洞穴中发布这项任务。她作为向导，指引修行者收集水样，以使他们与元素调和。",al={"谁发布水之召唤","赫瓦娜在哪里","赫瓦娜的洞穴"}},{q="为什么要收集淡水与咸水交汇处的水？",a="入海口的水代表了一种特殊的汇流，高地融雪和淡水泉水在此与海潮混合。这种淡水与富含矿物质的咸水的碰撞，携带了独特的沉积物和精神智慧。",al={"为何选择入海口的水","湿地的咸淡水","淡水与盐水的汇合"}},{q="瀑布附近潜伏着什么危险？",a="黑铁矮人已经潜入北方的湿地，对于试图进入沼泽和瀑布的旅行者和元素寻求者来说，他们构成了现实的威胁。",al={"湿地里的黑铁矮人","为什么黑铁矮人会在这里","黑铁矮人的威胁"}},{q="成为一名“容器”意味着什么？",a="“容器”是指已经开始积极寻求水的智慧，并携带大自然的水作为祭品，以发展更深层次元素调和的修行者。",al={"什么是容器","水的容器"}},{q="空的棕色水囊有什么用途？",a="空的棕色水囊是赫瓦娜提供的容器，用于从沼泽瀑布底部收集咸淡水样本。",al={"空的棕色水囊的使用方法","使用了什么水囊"}}},fp="13,266,20.286.0,26.307.0,20.303.0,18.206.0,16.169.0,52.204.0,38.160.0,37.149.0,43.130.0"}
P.entries["quest:94499"] = {n="Call of Water",s="“水之召唤”是一项任务，要求旅行者前往赤脊山的石堡瀑布，调查止水湖的流水是否存在污染。萨满祭司需要装满一个空的红色水囊并将其带回湿地的赫尔达娜·萨格伦德，从而揭示当地鱼人变异的真正原因，并为他们的精神试炼获得一种关键试剂。",h="“水之召唤”是一项任务，要求旅行者前往赤脊山的石堡瀑布，调查止水湖的流水是否存在污染。萨满祭司需要装满一个空的红色水囊并将其带回湿地的赫尔达娜·萨格伦德，从而揭示当地鱼人变异的真正原因，并为他们的精神试炼获得一种关键试剂...",kw={"call of water","赫尔达娜·萨格伦德","止水湖","夜行鱼人","赤脊山","药剂","暗影巫师","石堡瀑布","湿地"},ang={["class:Shaman"]="这项任务是酿造水之药剂的关键一步，在与水之灵沟通之前，考验萨满祭司跨越遥远水域的奉献精神和感知力。"},sec={{t="可疑的瀑布",b="位于湿地的赫尔达娜·萨格伦德派遣有志成为萨满祭司的冒险者前往赤脊山，调查从石堡瀑布倾泻而下的水流。虽然止水湖为湖畔镇的居民提供了纯净的水源，但潜伏在瀑布底部的鱼人却变得异常巨大且扭曲。赫尔达娜怀疑是毒素、邪恶法术或者上方古老堡垒的渗漏导致了这一切，因此要求旅行者用空的红色水囊采集样本。"},{t="污染的真正源头",b="在检查了装满的水囊后，赫尔达娜发现从止水湖倾泻而下的水完全干净，并未受到任何污染。当地夜行鱼人所表现出的身体扭曲并非由受到污染的水源引起，而是石堡周围潜伏的暗影巫师所施展的黑暗法术所致。该样本既证明了瀑布的纯净，也考验了萨满祭司的奉献精神，它是酿造精神药剂所必需的关键试剂。"}},faq={{q="谁发布了这个任务，他们位于何处？",a="位于湿地的赫尔达娜·萨格伦德发布了此项任务。她致力于研究水资源以及酿造萨满祭司精神试炼所需药剂的试剂。",al={"谁发布水之召唤","任务发布者赫尔达娜"}},{q="为什么会被派去从石堡瀑布采集水？",a="赫尔达娜怀疑奇怪的毒素、黑暗魔法或污染可能正从上方的旧堡垒渗透过石堡瀑布，导致瀑布底部的鱼人畸变。她需要一份新鲜的样本来进行检查。",al={"为什么要在赤脊山装满水囊","石堡瀑布的目的"}},{q="石堡瀑布的水真的受到污染了吗？",a="没有，水本身证明是完全纯净且未受污染的。赫尔达娜断定，当地鱼人的扭曲状态是源于当地暗影巫师施展的黑暗魔法，而不是因为受污染的径流。",al={"石堡的水是否受到污染","止水湖是否受到腐蚀"}},{q="为什么石堡瀑布周围的鱼人如此巨大且扭曲？",a="与洛克湖或湿地的鱼人相比，瀑布底部的夜行鱼人更为巨大且扭曲。赫尔达娜得出结论，这种变化是当地暗影巫师的邪恶魔法所导致的。",al={"为什么赤脊山的鱼人会变异","石堡鱼人的不同之处"}},{q="水样本是用来做什么的？",a="药剂是一种仪式性的混合物，能让萨满祭司穿透帷幕，感知元素之灵。赫尔达娜从各种水域收集纯净样本，以酿造你需要的那种试剂。",al={"什么是药剂","水之召唤奖励的用途"}},{q="诺瑞克是谁？",a="诺瑞克是参与萨满试炼的伙伴或导师，赫尔达娜提到他会对你成功取回纯净水样本感到满意。",al={"谁是诺瑞克","诺瑞克水之召唤"}}},fp="13,368,17.466.0,29.473.1,48.170.0,56.205.0,50.213.0,65.204.0,34.194.0,14.160.0"}
P.entries["quest:945"] = {n="护送瑟瑞露尼",s="在黑海岸南部，一位名叫瑟瑞露尼的年轻暗夜精灵误入了阴森的主宰之剑挖掘场，并被敌对的邪教徒包围。需要联盟护送她到安全地带，并将她幸存的消息告诉她担忧的姐姐瑟瑞希尔，她正在艾森娜神殿休息。",h="在黑海岸南部，一位名叫瑟瑞露尼的年轻暗夜精灵误入了阴森的主宰之剑挖掘场，并被敌对的邪教徒包围。需要联盟护送她到安全地带，并将她幸存的消息告诉她担忧的姐姐瑟瑞希尔，她正在艾森娜神殿休息。",kw={"灰谷","邪教徒","护送","主宰之剑","艾森娜神殿","瑟瑞露尼","瑟瑞希尔","暮光之锤"},ang={["faction:Alliance"]="帮助像瑟瑞露尼这样受困的旅人，能巩固联盟在保卫灰谷的暗夜精灵中的存在感和善意。",["race:NightElf"]="主宰之剑是卡利姆多历史上的一道古老伤疤。看到你的同胞卡多雷毫无防备地闯入邪教徒的挖掘场，是一个令人清醒的警示，提醒着灰谷内部潜伏的威胁。"},sec={{t="危险的漫步",b="主宰之剑是黑海岸最令人不安的地标之一，那里有一具被巨大的石刃贯穿的古代怪物的巨大头骨。尽管山谷中弥漫着恐惧，瑟瑞露尼还是误闯进了峡谷深处。她很快就被暮光之锤的邪教徒困住，仅凭敏捷的反应和在崎岖地形中隐藏的天赋才得以幸存。"},{t="送往神殿的消息",b="瑟瑞露尼的姐姐瑟瑞希尔住在遥远的南方，平静的艾森娜神殿。虽然瑟瑞露尼以爱冒险且不介意弄脏衣服而闻名，但她冒险进入主宰之剑那令人不适的挖掘场，这让她的亲人都感到震惊。带来瑟瑞露尼平安的消息可以宽慰她那深受困扰的姐姐，她深知目前正在黑海岸的古老土地上挖掘的黑暗势力。"}},faq={{q="瑟瑞露尼是谁？",a="瑟瑞露尼是一位爱冒险的年轻暗夜精灵，她误入了黑海岸南部主宰之剑危险的挖掘场。她是瑟瑞希尔的妹妹。",al={"瑟瑞露尼","这个女孩是谁","受困的精灵"}},{q="瑟瑞希尔是谁？",a="瑟瑞希尔是瑟瑞露尼的姐姐，驻扎在灰谷宁静的艾森娜神殿。得知她的妹妹竟然游荡到如此黑暗且被污染的地方附近，她感到非常不安。",al={"瑟瑞希尔","瑟瑞露尼的姐姐"}},{q="为什么主宰之剑如此危险？",a="主宰之剑是一处古老且不祥的峡谷，很久以前有一位古老的“古老领主”陨落于此。暮光之锤的邪教徒蜂拥至该区域，大肆挖掘遗迹并攻击任何入侵者。",al={"主宰之剑的危险","主宰之剑的邪教徒"}},{q="瑟瑞露尼需要被护送到哪里？",a="瑟瑞露尼需要护送以离开主宰之剑的直接包围圈前往安全地带，之后拯救者必须前往艾森娜神殿通知她的姐姐。",al={"护送目的地","瑟瑞露尼去哪了"}},{q="艾森娜神殿位于哪里？",a="艾森娜神殿位于灰谷西南部，阿斯特兰纳以西，是供奉森林之魂艾森娜的圣地。",al={"艾森娜神殿的位置","瑟瑞希尔在哪"}},{q="瑟瑞露尼在邪教徒的包围下是如何幸存的？",a="瑟瑞露尼能在周围的暮光之锤邪教徒发现她之前，找到岩石和地形间一个隐蔽的藏身处，从而得以避免被抓。",al={"瑟瑞露尼如何躲藏"}}},fx={["8c0c4bd7"]={q="为什么瑟瑞露尼需要你的帮助才能逃出去？",a="瑟瑞露尼误入主宰之剑那处阴森的挖掘现场，很快就发现自己被困住，周围全是暮光之锤教徒。她凭借藏匿的本领活了下来，却无法独自躲过这些包围她的狂热分子，逃到安全之处并让妹妹瑟瑞希尔安心。",al={"瑟瑞露尼为什么需要帮助","瑟瑞露尼的动机","为什么要帮助瑟瑞露尼"}},cc515991={q="为什么瑟瑞露尼不能自己逃走？",a="瑟瑞露尼虽然擅长藏匿，暂时躲过了被抓的危险，却全然没有武器，毫无自卫能力，困在敌方领地深处。附近没有守卫或盟友能帮她，她只能完全依靠路过的冒险者杀出一条逃生之路。",al={"瑟瑞露尼为什么需要我","瑟瑞露尼为什么不能逃走","为什么找我帮助瑟瑞露尼"}}},fp="18,319,17.430.0,18.430.0,17.163.0,16.181.0,40.202.0,41.176.0,39.135.0,49.167.0"}
P.entries["quest:94500"] = {n="Call of Water",s="Call of Water 任务要求冒险者深入灰谷那翠绿的树冠之下，从环绕阿斯特兰纳的湖泊中收集纯净、古老的水。这是在将旅行者送回 Norric 之前，收集任务所需的最后一步。",h="Call of Water 任务要求冒险者深入灰谷那翠绿的树冠之下，从环绕阿斯特兰纳的湖泊中收集纯净、古老的水。这是在将旅行者送回 Norric 之前，收集任务所需的最后一步。",kw={"灰谷","阿斯特兰纳","奥伯丁","call of water","米奈希尔港","norric","南海镇","水囊"},ang={["faction:Alliance"]="这项任务引导旅行者沿着联盟的航海路线从东部王国前往卡利姆多，连接了米奈希尔港、奥伯丁以及暗夜精灵的定居点阿斯特兰纳。",["race:NightElf"]="任务指引旅行者前往阿斯特兰纳周边的纯净水域，那里是灰谷中卡多雷的核心地带之一，古老的遗迹至今仍静静地躺在那里。"},sec={{t="寻找纯净之水",b="Call of Water 任务要求冒险者从灰谷未受腐蚀的水域中灌满一只水囊。寻求者必须前往阿斯特兰纳，这是一处坐落在清澈、古老水域之中的避难所，湖水轻拍着往昔时代的沉没遗迹。这瓶纯净的样本是任务发布者所需的最后一种液体，随后旅行者将被派往 Norric 那里。"},{t="通往阿斯特兰纳之路",b="Reaching the depths of Ashenvale requires crossing the sea from the Eastern Kingdoms. The recommended path takes travelers aboard the ship sailing out of Menethil Harbor toward Auberdine, making port at Southshore along the journey. From the docks of Auberdine, the road leads inland into the emerald boughs of Ashenvale, where travelers are warned to stay alert among the watchful shadows of the trees."}},faq={{q="什么是 Call of Water 任务？",a="Call of Water 是一个要求旅行者携带空水囊深入灰谷古老森林的任务。其目标是在返回任务发布者处之前，从环绕阿斯特兰纳定居点的湖泊中收集一份纯净、古老且可能带有魔力的水。",al={"什么是 call of water","call of water 任务","call of water 目标"}},{q="我该在哪里收集这个任务所需的水？",a="水必须从位于灰谷深处的环绕阿斯特兰纳的湖泊中采集。那里的水依然未受腐蚀，流淌在往昔时代留下的古老沉没遗迹之间。",al={"在哪里寻找纯净水","在哪里灌满水囊","call of water 地点"}},{q="我该如何前往灰谷完成这个任务？",a="建议旅行者从米奈希尔港搭乘船只前往奥伯丁，途中会在南海镇停留。从黑海岸的奥伯丁出发，向南前往灰谷深邃的翡翠森林，即可抵达阿斯特兰纳。",al={"如何前往阿斯特兰纳","前往灰谷","前往阿斯特兰纳的船"}},{q="阿斯特兰纳的水有什么特别之处？",a="环绕阿斯特兰纳的湖泊以其未受腐蚀的水质而闻名。其湖面之下掩埋着石制遗迹，暗示着暗夜精灵文明的一个古老、往昔的时代，这赋予了湖水纯净且可能蕴含魔力的特质。",al={"阿斯特兰纳的湖","阿斯特兰纳的水域遗迹","阿斯特兰纳湖中的遗迹"}},{q="Norric 是谁？",a="Norric 是在旅行者采集到这份最后的液体样本后等待他们的人。任务发布者收集这瓶纯净的灰谷之水作为最后一种成分，然后将冒险者送回 Norric 那里。",al={"谁是 norric","返回 norric 处"}},{q="在灰谷我该提防什么危险？",a="灰谷是一片古老而茂密的森林，充满了危险。任务发布者警告旅行者要时刻保持警惕，告诫说当人们深入其翠绿树冠之下时，森林里有时刻注视着他们的眼睛。",al={"灰谷的危险","灰谷的威胁"}}},fp="13,229,25.349.0,21.403.0,32.289.0,44.199.0,44.240.0,42.251.0,14.209.0,42.219.0"}
P.entries["quest:94501"] = {n="Call of Water",s="“Call of Water”是萨满祭司追求神圣水之图腾仪式时的一场精神试炼。求道者需要将受Hervdana祝福的纯净水送到洛克莫丹的Norric Lochthane手中，以此准备与斯特登的池塘中的灵魂沟通所需的元素水之灵药。",h="“Call of Water”是萨满祭司追求神圣水之图腾仪式时的一场精神试炼。求道者需要将受Hervdana祝福的纯净水送到洛克莫丹的Norric...",kw={"call of water","hervdana","洛克莫丹","月溪镇","norric lochthane","萨满祭司","斯特登的池塘","一瓶最纯净的水","water sapta","水之图腾"},ang={["class:Shaman"]="这场试炼是与元素沟通以获得水之图腾仪式，并制作看见元素灵魂所需的水之灵药的关键一步。",["faction:Alliance"]="联盟萨满祭司跨越洛克莫丹和西部荒野，寻求与东部大地的水元素灵魂进行沟通。",["race:Dwarf"]="这段旅程将矮人萨满候选人与像Norric Lochthane这样遍布卡兹莫丹的元素导师连接了起来。"},sec={{t="通往水之图腾之路",b="“Call of Water”是渴望与水元素达成和谐的萨满祭司必须经历的精神感应试炼。踏上这条道路，需要收集由Hervdana亲自祝福的水，在将容器带给洛克莫丹的Norric Lochthane之前，以证明求道者对灵魂的耐心与敬畏。"},{t="水之灵药的诞生",b="在收到受祝福的容器后，Norric透露这些神圣的液体旨在酿造一种水之灵药。这种药水能让求道者洞穿虚妄，见到居住在月溪镇附近斯特登的池塘中的水元素灵魂。每一滴水都被视为珍宝，因为即使是湿润的塞子在神圣仪式中也大有用处。"}},faq={{q="谁是Norric Lochthane？",a="Norric Lochthane是一位居住在洛克莫丹的导师，他引导候选人完成元素感应。他负责监督获得水之图腾所需的准备工作和仪式。",al={"谁是norric","norric 洛克莫丹","谁是norric lochthane"}},{q="谁是Hervdana？",a="Hervdana Saegrund是湿地的向导，她与家人住在南部瀑布旁的一个洞穴里，她负责祝福求道者收集的神圣之水，使其拥有酿造水之灵药所需的精神纯度。",al={"谁是hervdana","受hervdana祝福","hervdana的水"}},{q="水之灵药有什么用？",a="水之灵药是一种使用神圣之水调制而成的元素药水。饮用它能让萨满祭司洞穿面纱，感知到存在于天然水池中的隐秘水元素灵魂。",al={"什么是水之灵药","水之灵药的用途","水之灵药的作用"}},{q="斯特登的池塘在哪里？",a="斯特登的池塘位于西部荒野，靠近月溪镇。萨满祭司在饮用准备好的水之灵药后，必须前往那里寻找栖息在其中的水元素灵魂。",al={"斯特登的池塘在哪里","斯特登的池塘位置","斯特登的水元素灵魂"}},{q="为什么一瓶最纯净的水很重要？",a="一瓶最纯净的水中装有酿造水之灵药和进行获得水之图腾所需神圣仪式必不可少的受祝福之水。Norric告诫说，即使一滴也不能浪费。",al={"为什么要纯净水","一瓶最纯净的水的用途"}},{q="什么是水之图腾仪式？",a="水之图腾仪式是萨满祭司为了与水元素达成共鸣而进行的精神试炼，通过这些仪式证明自己的尊重与平衡，从而获得水之图腾。",al={"什么是水之图腾仪式","如何获得水之图腾"}}},fp="13,257,27.325.0,18.332.1,24.179.0,16.226.0,25.175.0,32.161.0,42.208.0,31.180.0"}
P.entries["quest:94502"] = {n="Call of Water",s="Call of Water是一项元素任务，要求从洛克莫丹前往西部荒野，以恢复一处被腐蚀的泉水的平衡。通过净化斯特登的池塘中的受污染实体，并在遗忘的神龛处执行古老的仪式，请求者可以获得水之灵魂的青睐以及他们的水之图腾。",h="Call of Water是一项元素任务，要求从洛克莫丹前往西部荒野，以恢复一处被腐蚀的泉水的平衡。通过净化斯特登的池塘中的受污染实体，并在遗忘的神龛处执行古老的仪式，请求者可以获得水之灵魂的青睐以及他们的水之图腾。",kw={"call of water","洛克莫丹","月溪镇","诺里克","萨满","斯特登的池塘","水之图腾","西部荒野"},ang={["class:Shaman"]="这项试炼是与水之灵魂建立联系并获得水之图腾的关键仪式，展现了对元素力量的和谐与掌控。",["faction:Alliance"]="联盟的萨满必须穿越他们的领土，从洛克莫丹冒险进入动荡的西部荒野，以净化被腐蚀的水域。"},sec={{t="被暗影侵蚀的泉水",b="在月溪镇的阴影之下坐落着斯特登的池塘，这里曾经是一处清澈纯净的泉水。横扫西部荒野的黑暗影响已经玷污了它宁静的水域，迫使当地的水之灵魂陷入了沉寂。岸边矗立着一座古老的神龛，被尘土和蛛网覆盖，废弃已久，等待着有人来唤醒其中沉睡的力量。"},{t="净化仪式",b="位于洛克莫丹的诺里克（Norric）会指引请求者完成恢复平衡所需的仪式。该仪式要求面对污染斯特登的池塘的邪恶实体，获取其护腕，并将它们与几滴炼金药水一起供奉在石制神龛上。当咒语被念出时，蒸气会召唤出一个被净化的灵魂，它将传授智慧，并证明携带者有资格获得水之图腾。"}},faq={{q="Call of Water是什么任务？",a="Call of Water是一项针对萨满的灵性试炼，旨在与水的元素进行沟通。该任务要求请求者净化西部荒野中斯特登的池塘的腐蚀，利用那里的古老神龛召唤一个被净化的水之灵魂，并获得他们的水之图腾。",al={"call of water是什么","水之图腾任务","西部荒野水之任务"}},{q="谁发布了这个任务？",a="该任务由洛克莫丹的导师诺里克发布。他指导请求者进行元素仪式，提供特殊的药水，并引导他们净化被腐蚀的元素水域。",al={"谁发布call of water","洛克莫丹 诺里克","任务发布者"}},{q="斯特登的池塘在哪里？",a="斯特登的池塘位于西部荒野西南部的月溪镇外。它曾经是一处纯净的泉水，但在黑暗、腐蚀力量的影响下，如今已变得死寂而浑浊。",al={"斯特登的池塘在哪里","斯特登的池塘位置","月溪镇附近的池塘"}},{q="如何净化斯特登的池塘的腐蚀？",a="要净化水域，你必须击败斯特登的池塘中的腐蚀存在，取走它的护腕，并将它们与剩余的药水一起放置在古老的神龛上，同时念诵诺里克传授的咒语。",al={"如何净化池塘","净化斯特登的池塘","神龛仪式"}},{q="完成此任务能获得什么奖励？",a="完成试炼并将净化的证明带回给洛克莫丹的诺里克，请求者将获得他们的水之图腾，从而获得对水之元素力量的掌控权。",al={"call of water有什么奖励","水之图腾奖励"}},{q="为什么斯特登的池塘会被腐蚀？",a="黑暗的来源尚不确定。池塘呈现出反常的停滞状态，周围散布着野兽的白骨，这引发了人们的担忧：它究竟是被西部荒野蔓延的苦难所毒害，还是其本身就是腐蚀的源头。",al={"为什么斯特登的池塘会被腐蚀","什么腐蚀了池塘"}}},fp="13,302,26.358.0,21.400.1,32.273.0,21.190.0,24.166.0,52.220.0,43.181.0,32.238.0"}
P.entries["quest:94503"] = {n="Call of Water",s="Call of Water 是一个位于西部荒野的任务，要求冒险者净化受污染的元素力量。玩家通过用圣光驱散不安的灵魂，与水之魂进行沟通，以守护该地区日渐衰弱的生命力。",h="Call of Water 是一个位于西部荒野的任务，要求冒险者净化受污染的元素力量。玩家通过用圣光驱散不安的灵魂，与水之魂进行沟通，以守护该地区日渐衰弱的生命力。",kw={"call of water","净化","腐蚀","元素","水之魂","水之灵魂","西部荒野"},ang={["class:Shaman"]="与原始元素沟通并净化受污染的水之灵魂是元素的基本仪式，提醒萨满他们平衡自然的永恒职责。",["faction:Alliance"]="该显现居住在西部荒野，这是一个联盟领土，当地的灵魂正承受着侵蚀这片土地的蔓延枯萎。"},sec={{t="净化受污染的水域",b="在西部荒野那片饱受风霜的土地上，自然的水之平衡正面临着受腐蚀灵魂的侵害。被称为 Call of Water 的仪式需要面对这些邪恶，诵读圣言唤出耀眼的光芒，将这些躁动、污秽的本质驱散为无害的灰烬与平静的薄雾。"},{t="灵魂的警告",b="随着腐蚀实体被击退，水之魂可以安全地现身进行沟通。虽然眼前的腐蚀已有所减退，但灵魂警告说，这片土地的生命能量仍在不断衰弱，提醒勇士们守护生命是一场永无止境的守望。"}},faq={{q="Call of Water 是什么？",a="Call of Water 是西部荒野的一场灵魂试炼，通过爆发圣光的仪式驱逐腐蚀的灵魂，净化受困的水域，并允许玩家与水之魂沟通。",al={"什么是 call of water","call of water 西部荒野","西部荒野水任务"}},{q="水之魂在哪里可以找到？",a="水之魂位于西部荒野。它会在周围的腐蚀灵魂被镇压并驱散后出现，等待与那些帮助过水域的人交谈。",al={"水之魂在哪里","显现位置","西部荒野水之灵魂"}},{q="净化腐蚀的灵魂后会发生什么？",a="随着咒语的结束，耀眼的光芒爆发并驱散了腐蚀的灵魂，使它们污秽的本质瓦解并如灰烬般消散，而水流则嘶嘶作响，化作柔和的薄雾。",al={"仪式期间发生了什么","call of water 腐蚀灵魂"}},{q="完成任务后，这片土地完全恢复了吗？",a="眼前的腐蚀已被击退并逐渐消退，但元素警告说生命力仍在衰弱，守护生命的重任仍落在凡人手中。",al={"腐蚀消失了吗","我们拯救了水域吗"}},{q="谁被召唤来协助这一显现？",a="该任务认可了玩家的使命，感谢他们的职业挺身而出，净化灵魂并肩负起保护衰弱生命的责任。",al={"谁能执行 call of water","水任务职业要求"}},{q="为什么西部荒野的水之灵魂会被腐蚀？",a="腐蚀的灵魂扰乱了西部荒野沿岸的自然水域。虽然这种污染的确切起源尚不明确，但它们恶意的存在直接汲取了该地区的生命活力。",al={"为什么西部荒野的水被腐蚀了","西部荒野水的问题"}}},fp="13,260,28.310.0,20.273.0,22.214.0,52.181.0,53.184.0,53.168.0,47.177.0,49.195.0"}
P.entries["quest:94505"] = {n="Call of Water",s="Call of Water是一项元素试炼，萨满祭司通过它学会与水之灵交流并运用其恢复力量。通过从西部荒野为洛克莫丹的诺里克·洛克萨恩取回水灵碎片，试炼者证明了自己的奉献精神并获得了他们的水之图腾。",h="Call of Water是一项元素试炼，萨满祭司通过它学会与水之灵交流并运用其恢复力量。通过从西部荒野为洛克莫丹的诺里克·洛克萨恩取回水灵碎片，试炼者证明了自己的奉献精神并获得了他们的水之图腾。",kw={"call of water","洛克莫丹","诺里克·洛克萨恩","萨满祭司","水灵碎片","水之图腾","西部荒野"},ang={["class:Shaman"]="这项试炼标志着一个基本的通过仪式，赋予萨满祭司与水之灵的交流能力以及用于治愈和维持生命的水之图腾。",["faction:Alliance"]="与卡利姆多的部落萨满祭司不同，联盟的试炼者向洛克莫丹的诺里克·洛克萨恩之类的导师汇报，并面对像西部荒野这样的地方的试炼。"},sec={{t="水之道",b="Call of Water是萨满祭司为了与水元素建立联系而进行的一项至关重要的精神试炼。试炼者被派往西部荒野，并将水灵碎片带回洛克莫丹交给诺里克·洛克萨恩。通过展现他们对水之生命本质及其在净化腐蚀中作用的理解，萨满祭司赢得了他们的水之图腾，并迈出了元素旅程中重要的一步。"},{t="生命赋予者",b="这项试炼传授了一条基础的元素真理：水即生命，而腐蚀则终结生命。萨满祭司肩负着运用水的恢复力量来保护弱小和维持生命的使命。正如导师诺里克·洛克萨恩在收到水灵碎片时所观察到的，水的纯净馈赠远不止简单的肉体修复，还触及了耐力、复苏和精神平衡。"}},faq={{q="诺里克·洛克萨恩是谁？",a="诺里克·洛克萨恩是一位驻守在洛克莫丹的萨满祭司导师。他引导试炼者通过试炼以了解水之灵，通过前往西部荒野的旅程考验他们的决心，并在他们交出交流证明时为他们颁发水之图腾。",al={"诺里克·洛克萨恩是谁","谁给予水之图腾","诺里克 洛克莫丹"}},{q="什么是水灵碎片？",a="水灵碎片是证明试炼者已从西部荒野归来交给洛克莫丹诺里克·洛克萨恩的实物凭证。它标志着试炼者已经与水进行了交流，掌握了其赋予生命的本质，并学会了对抗腐蚀。",al={"什么是水灵碎片","水灵碎片的用途","水灵碎片任务物品"}},{q="为什么试炼会前往西部荒野？",a="试炼者被派往西部荒野是为了理解水赋予生命的力量以及腐蚀是如何威胁它的。即使在那个动荡之地取得的微小胜利，对于证明试炼者保护生命的能力来说也具有重要的意义。",al={"为什么要去西部荒野","西部荒野水任务","前往西部荒野 call of water"}},{q="水之图腾的意义是什么？",a="水之图腾体现了萨满祭司与水元素的联系。虽然它主要以通过净水来抚慰和治愈伤口而闻名，但其精神馈赠远超基础的治疗，涵盖了保存与活力。",al={"水之图腾有什么作用","萨满祭司为什么需要水之图腾","水之图腾背景"}},{q="这项试炼关于水传授了什么课程？",a="试炼期间教授的元素哲学强调水赋予生命，而腐蚀则会阻碍生命。萨满祭司肩负着用水的元素力量在任何腐蚀威胁生命的地方进行滋养、保护和恢复平衡的使命。",al={"什么是水即生命","call of water哲学","萨满祭司水之教导"}},{q="完成Call of Water后会发生什么？",a="诺里克·洛克萨恩指出，萨满祭司的下一个元素试炼不会立刻到来。他鼓励萨满祭司花时间练习并探索水更深层的奥秘，然后再进行进一步的试炼。",al={"接下来是什么试炼","下一个萨满祭司试炼","call of water之后发生什么"}}},fp="13,280,17.421.0,13.413.0,24.261.0,27.224.0,36.217.0,44.236.0,45.252.0,46.207.0"}
P.entries["quest:94568"] = {n="The Cult's True Plans",s="《The Cult's True Plans》讲述了一位邪教叛逃者不幸身亡后的余波。随着线人死亡且其秘密丢失，调查人员必须咨询Talaanis Shadowsong，以制定对抗该邪教的新策略。",h="《The Cult's True Plans》讲述了一位邪教叛逃者不幸身亡后的余波。随着线人死亡且其秘密丢失，调查人员必须咨询Talaanis Shadowsong，以制定对抗该邪教的新策略。",kw={"邪教","叛逃者","维和人员","talaanis shadowsong","the cult's true plans","变节者"},sec={{t="被噤声的叛逃者",b="一名内部人员因对邪教日益临近的阴谋感到恐惧而选择叛逃，希望能寻求外界的帮助。不幸的是，这名叛逃者在分享他所知的信息之前就被杀害了，留下了不详的警告，但关于邪教打算释放什么却没有任何具体细节。"},{t="重新思考应对方案",b="随着主要线人身亡，领导层必须咨询Talaanis Shadowsong以重新评估他们的策略。让维和人员与邪教进行正面交锋被认为是一场必败之战，这迫使那些调查威胁的人寻找另一条前进的道路。"}},faq={{q="在这个任务中提到的变节者是谁？",a="一名邪教叛逃者因对邪教正在策划的事情感到恐惧而寻求援助。不幸的是，他在透露其阴谋细节之前就被杀害了，将宝贵的情报带进了坟墓。",al={"在《the cult's true plans》中谁死了","死去的变节者是谁","变节者的邪教秘密"}},{q="Talaanis Shadowsong是谁？",a="Talaanis Shadowsong是在线人突然死亡后，商讨如何应对邪教的关键联络人。你见证了与Talaanis进行的一次战略性谈话，以确定下一步的行动方针。",al={"talaanis shadowsong的角色","talaanis shadowsong是谁","与talaanis交谈"}},{q="为什么维和人员不能直接攻击邪教？",a="将维和人员直接部署到与邪教势力的正面战斗中被认为风险太大，因为维和人员在正面冲突中表现预计不会很好。因此需要一种更巧妙或替代的策略。",al={"为什么不与邪教战斗","维和人员对阵邪教","直接袭击邪教"}},{q="邪教的真正计划是什么？",a="由于线人在分享他所知信息之前就已死亡，邪教计划的具体性质仍然笼罩在迷雾中。无论他们的目标是什么，其恐怖程度足以让一名成员绝望地选择叛逃。",al={"邪教在策划什么","邪教阴谋","《the cult's true plans》的含义"}},{q="与Talaanis交谈后的下一步是什么？",a="在意识到正面战斗行不通且主要情报来源已死之后，领导层必须设计一种替代方法来揭露并挫败邪教的阴谋。",al={"《the cult's true plans》之后会发生什么","邪教任务的后续步骤"}},{q="在《The Cult's True Plans》中发生了什么？",a="你与Talaanis Shadowsong交谈并观察了一场关于局势的商议。讨论的中心是线人死亡后的余波，并评估为何不能依靠正规军事力量来阻止该邪教。",al={"《the cult's true plans》任务概要","你在《the cult's true plans》中做什么"}}},fp="21,224,19.279.0,23.278.1,45.215.0,27.228.0,55.235.0,33.221.0,51.196.0,42.219.0"}
P.entries["quest:94616"] = {n="Water Sapta",s="“水之萨普塔”是一种仪式性的药剂，用于使人的灵魂视觉能够感知到水中隐藏的灵魂和腐化。持有此药剂的人会被派往西部荒野的田野中，寻找被污染的池塘水，以调查元素失衡的情况。",h="“水之萨普塔”是一种仪式性的药剂，用于使人的灵魂视觉能够感知到水中隐藏的灵魂和腐化。持有此药剂的人会被派往西部荒野的田野中，寻找被污染的池塘水，以调查元素失衡的情况。",kw={"元素协调","萨普塔","萨满试炼","被污染的池塘","water sapta","水之灵魂","西部荒野"},ang={["class:Shaman"]="萨普塔是一种炼金或仪式药剂，被萨满用来调整他们的灵魂感官，以感知那些在普通视觉下无法看见的元素灵魂。",["faction:Alliance"]="调查西部荒野内被腐蚀的水域，将元素净化仪式带到了联盟领地的中心。"},sec={{t="水之视觉",b="在萨满的元素传统中，萨普塔是一种专门调制出的仪式药剂，用来穿透物质领域与灵魂领域之间的面纱。“水之萨普塔”专门将使用者的感官与水元素协调一致，从而赋予他们感知元素扰动和隐形灵魂所需的灵视能力。如果没有这种协调，普通的旅行者即使直视元素显现，也只能看到寻常的涟漪。"},{t="西部荒野的扰动",b="使用“水之萨普塔”的指令会将持有者指引至西部荒野。这片饱受动乱和荒废之苦的联盟土地上，有一处池塘的水遭到了灵魂层面的污染。在萨普塔赋予的感知的引导下，持有者必须找出这些被污染的水域，揭开其中的扰动，并恢复当地水之灵魂的和谐。"}},faq={{q="什么是水之萨普塔？",a="水之萨普塔是为萨满与元素沟通而特制的精神药剂。饮用或使用萨普塔可以暂时开启使用者的感知，使其能看到凡人肉眼无法察觉的元素实体和灵魂失衡。",al={"什么是水之萨普塔","水之萨普塔的目的","水之萨普塔的作用"}},{q="西部荒野的被污染池塘在哪里？",a="被污染的池塘水位于西部荒野境内。萨满们会被指引前往那里，手持水之萨普塔寻找受腐蚀的水源，并解决该地区内滋生的任何灵魂扰动。",al={"被污染的池塘在哪","西部荒野被污染的池塘","被污染的池塘位置"}},{q="为什么水之萨普塔会指引去西部荒野？",a="即使是在像西部荒野这样以农业为主、遭受旱灾的人类土地上，元素之水也可能遭受污染或邪恶腐化的侵袭。任务要求你寻找被污染的池塘水，以调查并恢复当地不安灵魂的平衡。",al={"为什么要去西部荒野","西部荒野水体腐化","为什么西部荒野的水会被污染"}},{q="谁会使用水之萨普塔？",a="水之萨普塔被授予正在接受元素沟通试炼的萨满。通过服用萨普塔，修行者会将他们的感官与水之灵魂协调，从而使其能够感知到隐藏的元素生物或检查被污染的水池。",al={"谁喝水之萨普塔","谁使用水之萨普塔","萨满饮用萨普塔"}},{q="当你带着萨普塔来到被污染的池塘时会发生什么？",a="在西部荒野的被污染池塘附近使用水之萨普塔后，你将获得元素视觉，从而显现出水的灵魂状态，或是召唤出与当地水之试炼相关的隐藏灵魂。",al={"使用萨普塔后会发生什么","萨普塔元素视觉"}},{q="元素萨普塔在萨满传统中是如何运作的？",a="萨普塔将大地的试剂与元素的祝福结合成一种仪式性的药剂。萨满在试炼中依靠它们来与特定的元素——土、火、水或气——达成协调，从而跨越物质世界与灵魂领域之间的鸿沟。",al={"萨普塔如何运作","萨普塔背景知识"}}},fp="11,274,23.457.0,23.371.0,22.247.0,38.224.0,42.260.0,25.232.0,58.191.0,51.250.0"}
P.entries["quest:947"] = {n="洞中的蘑菇",s="“洞穴蘑菇”是暗夜精灵巴瑞萨斯·月影在奥伯丁发布的一项联盟任务。在配制某种特制药剂时，巴瑞萨斯委托一位冒险者前往峭壁之泉背后的一处隐秘洞穴，采集珍稀真菌，并核实古树之林所感应到的不安预兆。",h="“洞穴蘑菇”是暗夜精灵巴瑞萨斯·月影在奥伯丁发布的一项联盟任务。在配制某种特制药剂时，巴瑞萨斯委托一位冒险者前往峭壁之泉背后的一处隐秘洞穴，采集珍稀真菌，并核实古树之林所感应到的不安预兆。",kw={"奥伯丁","巴瑞萨斯·月影","洞穴蘑菇","峭壁之泉","黑海岸","毒帽蘑菇","古树之林","欧努","粗糙柄菇"},ang={["faction:Alliance"]="奥伯丁是联盟在卡利姆多海岸的主要堡垒，东部山脉中蔓延的邪恶直接威胁着整个海岸的稳定。",["profession:Herbalism"]="采集者和草药师会喜欢搜寻毒帽蘑菇和粗糙柄菇的过程，尽管这些特殊的样本生长在阴暗的洞穴里，而不是茂密的林地土壤中。",["race:NightElf"]="古树之林始终与黑海岸的自然平衡保持着深刻的共鸣，因此他们在瀑布之下探测到的任何骚动，对卡多雷来说都是需要紧急关注的问题。"},sec={{t="瀑布后的配方",b="巴瑞萨斯·月影需要特定的配料来调制强力药剂：粗糙柄菇和一种难以寻觅的毒帽蘑菇。这些特殊的真菌生长在黑海岸东北部、峭壁之泉后方隐蔽的阴暗潮湿洞穴中。虽然炼金本身很精细，但收集这些样本要比采集普通的林地草药危险得多。"},{t="古树的警告",b="巴瑞萨斯并非因为懒惰而不去那座洞穴。古树之林的古老树木守护者发出了严厉的警告，感应到一股邪恶的力量开始在山洞中筑巢。月影派遣一位强健的探险者而非亲自调查，正是为了确认长老们关于黑海岸北部潜伏着一股邪恶力量的预感是否属实。"}},faq={{q="这项任务在哪里开始？",a="你可以从巴瑞萨斯·月影那里接到这项任务，他居住在黑海岸中部的暗夜精灵沿海定居点奥伯丁。",al={"如何接取洞穴蘑菇任务","巴瑞萨斯·月影的位置","洞穴蘑菇任务起始"}},{q="蘑菇在哪里？",a="它们生长在峭壁之泉后面隐藏的洞穴里，位于奥伯丁东北部的山坡上。",al={"哪里有粗糙柄菇","毒帽蘑菇位置","黑海岸瀑布后的洞穴"}},{q="为什么巴瑞萨斯·月影不亲自去取蘑菇？",a="古树之林明确建议巴瑞萨斯远离那处瀑布。伟大的古树们感觉到一股非自然的邪恶力量正在那个洞穴中栖身。",al={"为什么巴瑞萨斯不去","为什么巴瑞萨斯留在奥伯丁"}},{q="需要哪些特定的蘑菇？",a="月影需要五株粗糙柄菇，外加一株极度危险的毒帽蘑菇才能完成他的药剂。",al={"所需蘑菇","月影需要的真菌"}},{q="这项差事接下来会指向哪里？",a="一旦确认了洞穴中的异状并交付了真菌，旅程将转向南方，前往古树之林寻找远古保护者欧努。",al={"洞穴蘑菇后的后续任务","欧努后续"}},{q="为什么古树们会担心峭壁之泉？",a="古树之林警告巴瑞萨斯，瀑布后的洞穴中可能潜伏着一股日益壮大的邪恶力量。他请求一位旅行者去采集蘑菇并调查这一警告。",al={"古树对峭壁之泉的警告","为什么侦察洞穴"}}},fx={a048db56={q="为什么巴瑞萨斯·月影想要完成这件事？",a="巴瑞萨斯·月影是一名草药师，正在调制一种强效新药剂，需要采集只有峭壁之泉后方洞穴中才有的稀有真菌。然而，除了炼金工作，他还有更深的顾虑：古树之林警告他，一股邪恶势力正在那座洞穴中滋长。他派你去采集原料，也希望借此查明古树们不祥的预兆是否属实。",al={"巴瑞萨斯为什么要找洞穴蘑菇","巴瑞萨斯·月影的动机","为什么替巴瑞萨斯采蘑菇"}},["991c4c10"]={q="毒帽蘑菇有什么用？",a="毒帽蘑菇是一种极其稀有、毒性强烈的真菌，生长于峭壁之泉后方的洞穴中。巴瑞萨斯·月影需要一株完好的毒帽蘑菇，作为他在奥伯丁调制的一种特制药剂的关键原料。",al={"毒帽蘑菇有什么用途","毒帽蘑菇的用途","巴瑞萨斯为什么需要毒帽蘑菇"}},be6516db={q="粗柄蘑菇有什么用？",a="粗柄蘑菇是稀有蘑菇，生长在峭壁之泉后方潮湿阴暗的洞穴中。巴瑞萨斯·月影需要五株粗柄蘑菇，将它们与强效的毒帽蘑菇一起加入他正在调制的炼金药剂中。",al={"粗柄蘑菇有什么用","粗柄蘑菇的用途","巴瑞萨斯为什么需要粗柄蘑菇"}}},fp="14,322,25.366.0,21.406.1,27.136.0,32.122.0,61.183.0,35.115.0,35.153.0,55.168.1"}
P.entries["quest:94792"] = {n="Taming the Beast",s="Taming the Beast 是一项入门级的试炼，有志向的冒险者将在此学习安抚野兽并与其建立羁绊的艺术。在 Josephine Carson 的指导下，新手们会带着一根驯兽棒进入森林，去驯服一只岩皮野猪并练习必要的生存技能。这项任务旨在证明，只要尊重并维护微妙的自然平衡，有了一只忠诚的野兽伙伴，在严酷的荒野中生存就会变得轻松许多。",h="Taming the Beast 是一项入门级的试炼，有志向的冒险者将在此学习安抚野兽并与其建立羁绊的艺术。在 Josephine Carson...",kw={"动物伙伴","自然的平衡","野兽驯服","猎人宠物","josephine carson","岩皮野猪","驯兽棒","taming the beast"},ang={["class:Druid"]="虽然德鲁伊不像猎人那样保留动物伙伴，但任务中对维护微妙的自然平衡的强调，反映了德鲁伊的核心教义。以关怀和克制的态度与森林中的野生生物互动，就是对他们发誓要保护的自然平衡的尊重。",["class:Hunter"]="对于猎人来说，掌握驯服野生野兽的艺术是一个决定性的成人礼，它从根本上改变了他们在荒野中的生存方式。忠诚的伙伴提供了必要的战斗保护和警觉，在追踪者与野兽之间铸就了持久的伙伴关系。"},sec={{t="与野兽建立羁绊",b="对于许多荒野漫游者来说，独自深入未经开垦的领地无异于自寻死路。一只动物伙伴不仅能在战斗中提供凶猛的保护，还能在艰苦的旅途中给予坚定不移的陪伴。学习如何建立这种羁绊，对于任何立志成为猎人或追踪者的人来说，都是一个至关重要的里程碑。在 Josephine Carson 的指引下，新手们会获赠一根特制的驯兽棒，并被要求前往森林中寻找一只岩皮野猪。安抚并驾驭这种生物是一项基础试炼，它能证明旅行者是否具备引导野兽所需的专注与镇定，而不会因恐惧而失控，或引发不必要的流血冲突。"},{t="自然的平衡",b="驾驭野生动物肩负着深远的道德和生态责任。正如 Josephine Carson 提醒她的学生们所言，将野兽纳入麾下绝不能沦为鲁莽的剥削，因为自然的平衡是脆弱的，必须时刻加以维护。驯服的过程并非为了残忍或统治，而是为了在野兽与主人之间建立和谐与纪律。使用这根附魔的驯兽棒，新手可以在不永久性消耗当地野生动物的前提下，安全地练习驾驭像岩皮野猪这样强大的生物。一旦掌握了指挥和安抚野兽的基础知识，驯兽棒就需要归还，这体现了对自然秩序的尊重高于个人的傲慢。"}},faq={{q="Taming the Beast 任务的目的是什么？",a="这项任务是为寻求与野生生物建立羁绊的冒险者提供的基础训练。在 Josephine Carson 的指导下，新手将学习如何使用特制的驯兽棒接近并安抚一只野生的岩皮野猪。该练习教导有志成为猎人的冒险者，动物伙伴如何帮助他们在荒野中生存，同时也强调了尊重自然平衡的重要性。",al={"taming the beast 任务","taming the beast 是什么","猎人宠物任务"}},{q="Josephine Carson 是谁？",a="Josephine Carson 是一位导师，她指导冒险者掌握管理动物伙伴的微妙艺术。她会提供驯兽棒，并指派学生在附近的树林里用岩皮野猪练习他们的能力。Josephine 强调，学会与野兽共事需要耐心、实践以及对自然微妙平衡的深刻认识。",al={"josephine carson","谁发布 taming the beast","驯兽棒任务发布者"}},{q="驯兽棒有什么用？",a="驯兽棒是 Josephine Carson 提供的一种特制工具，用于辅助动物训练。冒险者带着这根棒子进入森林，去安抚并驯服一只野生的岩皮野猪。它能让新手在不伤害当地动物群的前提下，安全地练习指挥野兽，且在试炼完成后必须将其归还给 Josephine。",al={"驯兽棒","驯兽棒的作用","如何使用驯兽棒"}},{q="猎人为什么需要动物伙伴？",a="独自在荒野中穿行会让旅行者面临严重的危险和伏击。动物伙伴可以提供可靠的保护、共同的警惕以及战斗中强有力的援助，让危险的环境变得更容易应对。在穿越荒地的漫长而危险的旅途中，忠诚的野兽既是凶猛的前线卫士，也是值得信赖的伙伴。",al={"为什么要获取宠物","野兽伙伴的好处","为什么要驯服野兽"}},{q="在此次试炼中需要驯服什么生物？",a="此次试炼要求冒险者深入森林，使用提供的驯兽棒驯服一只岩皮野猪。这些强壮的野兽是练习基础动物操控技能的理想测试对象，教导旅行者在面对具有攻击性的野生动物时如何保持镇定和纪律，然后返回向 Josephine Carson 报告进度。",al={"我要驯服哪种野猪","岩皮野猪目标","taming the beast 怪物"}},{q="为什么 Josephine Carson 强调自然的平衡？",a="Josephine Carson 警告说，驯服野生野兽时必须时刻保持谨慎和尊重，而不是贪婪或强迫。自然秩序是脆弱的，鲁莽地破坏当地的野生动物或虐待生物会打破生态平衡。对野兽真正的驾驭，需要理解并尊重它们在生态系统中的位置，而不是仅仅将它们视为可随意丢弃的工具。",al={"自然平衡的含义","自然平衡与驯服","为什么要尊重自然"}}},fp="16,430,19.689.0,21.716.0,50.399.0,24.376.0,32.354.0,38.377.0,46.356.0,58.402.0"}
P.entries["quest:94793"] = {n="Training the Beast",s="Training the Beast 是年轻猎人的基础任务，引导他们前往闪金镇寻找老练的林务员 Isaac Chan。通过完成这一步骤，猎人将学会如何适当地训练、喂养和复活他们的野兽伙伴，将一头刚驯服的野兽转变为忠诚的战斗伙伴。",h="Training the Beast 是年轻猎人的基础任务，引导他们前往闪金镇寻找老练的林务员 Isaac...",kw={"艾尔文森林","喂养宠物","闪金镇","猎人宠物","isaac chan","宠物训练","复活宠物","training the beast","林务员"},ang={["class:Hunter"]="这项任务标志着成长中猎人的重要成人礼，从仅仅是捕捉野兽转变为通过喂养、复活和训练它们来建立持久、纪律严明的羁绊。",["faction:Alliance"]="在艾尔文森林活动的联盟猎人依靠像闪金镇的 Isaac Chan 这样的老练林务员来掌握野兽驯养的基础知识。"},sec={{t="狩猎的责任",b="学会驯服野生生物只是准猎人的第一步；维持持久的伙伴关系需要纪律和知识。该任务引导初出茅庐的猎人去寻找驻扎在闪金镇的经验丰富的林务员 Isaac Chan，以获取野兽训练的必备技能。如果没有适当的指导，驯服的野兽将只是难以管教的野生动物，而非荒野中坚定的盟友。"},{t="林务员的指导",b="到达闪金镇后，Isaac Chan 会传授照料野兽伙伴所需的技能。这些指导超越了简单的战斗指令，包括喂养伙伴以保持其满足感的重要职责，以及学习在伙伴倒下时将其复活的仪式。Chan 提醒他的学生，拥有驾驭野兽的力量同时也意味着有责任尊重自然平衡，并对周围的世界怀有敬畏之心。"}},faq={{q="Isaac Chan 是谁？",a="Isaac Chan 是一位资深的、终身的林务员，居住在艾尔文森林的闪金镇。他因对野生动物和荒野生存的深刻理解而备受尊敬，并教导新手猎人如何适当地引导、喂养、复活他们的野兽伙伴，并传授它们技能。",al={"isaac chan 是谁","闪金镇野兽训练师","isaac chan 背景故事"}},{q="Training the Beast 的目的是什么？",a="虽然猎人可能已经知道如何驯服野兽，但该任务提供了维持这种羁绊的必要知识。它指导猎人如何喂养他们的伙伴，在伙伴战斗中倒下时将其复活，并教给它们新的战斗技能。",al={"这个任务有什么用","为什么要训练野兽","training the beast 的目的"}},{q="在哪里可以找到 Isaac Chan？",a="Isaac Chan 位于闪金镇，这是艾尔文森林的中心城镇，位于北郡山谷正南方，暴风城西南方。",al={"isaac chan 在哪里","我在哪里交这个任务","isaac chan 位置"}},{q="Isaac Chan 教授什么技能？",a="Isaac Chan 传授宠物照料和训练的核心原则。这包括喂养野兽以维持其健康，在它战斗中死亡时将其复活，以及在它随你成长时教给它新的能力。",al={"能学到什么技能","学习的宠物技能","isaac chan 教什么"}},{q="为什么 Isaac Chan 提醒猎人要尊重自然？",a="Isaac Chan 强调，驾驭野兽需要谦逊而非支配。他敦促猎人尊重自然界的平衡，并对周围的自然怀有敬畏之心，确保猎人和野兽之间的伙伴关系建立在守护而非剥削的基础上。",al={"为什么尊重自然","猎人尊重平衡"}},{q="谁会执行这个任务？",a="Training the Beast 是专门为那些已经获得了驯服野兽的初始能力，并且需要维持和训练野兽伙伴所需的林地纪律的猎人量身定制的。",al={"谁可以做这个任务","training the beast 是猎人专属吗"}}},fp="18,301,32.424.0,21.438.0,18.272.0,42.244.0,30.138.0,34.223.0,53.293.0,26.192.0"}
P.entries["quest:948"] = {n="安努",s="这个任务要求旅行者从奥伯丁出发向南前往古树之林，去拜见奥努。在探查了峭壁之泉后的洞穴后，你的发现已经引起了黑海岸最古老的守护者之一的密切关注。",h="这个任务要求旅行者从奥伯丁出发向南前往古树之林，去拜见奥努。在探查了峭壁之泉后的洞穴后，你的发现已经引起了黑海岸最古老的守护者之一的密切关注。",kw={"知识古树","奥伯丁","巴瑞萨斯·月影","峭壁之泉","黑海岸","古树之林","奥努"},ang={["class:Druid"]="德鲁伊们深切地尊崇古树，视其为自然智慧的化身。按照奥努的要求调查奇怪的洞穴生长物，完全符合塞纳里奥议会的职责。",["faction:Alliance"]="对于帮助保卫黑海岸的联盟旅行者来说，获得当地古树的信任与洞见，对于在卡利姆多神秘的北部荒野中穿行至关重要。",["race:NightElf"]="知识古树是卡多雷神圣的伙伴，自从大分裂之前就一直指引着你们的人民。回应奥努的召唤，是维护黑海岸神圣不可侵犯的一项庄严职责。"},sec={{t="来自古树的召唤",b="在带着从峭壁之泉深处采集的真菌样本返回奥伯丁后，巴瑞萨斯·月影意识到，这些发现的意义绝非仅仅是植物学上的好奇。被污染的洞穴的消息很快传到了奥努耳中，这是一位扎根于镇南古树之林那片宁静圣所中的知识古树。尽管古树生物天性耐心且深沉，但奥努如此急切地想要商议，表明黑海岸水道中蔓延的腐蚀可能触及了一些古老而令人不安的力量。"},{t="前往树林",b="沿着奥伯丁南下的道路前行，便可远离海岸遗迹，深入内陆，向山坡走去。古树之林是自然之力的祖传堡垒，在很大程度上躲避了侵蚀海岸线的腐朽蔓延。在这里，奥努等待在参天的石冢和同类灵体之间，准备指引盟友前往荒野边缘那些更深、更可怕的枯萎之源。"}},faq={{q="奥努是谁？",a="奥努是一位知识古树，是一个巨大的、有思想的树人守护者，致力于收集和保存知识。他坐镇在黑海岸南部的古树之林，为这片土地的保卫者提供智慧和指引。",al={"奥努是谁","奥努的身份","奥努是什么"}},{q="为什么奥努想和我谈谈？",a="你最近深入峭壁之泉下的洞穴，为巴瑞萨斯·月影采集了真菌样本。在那里发现的奇特事物引起了博物学家的警觉，促使奥努请求会面，以应对日益严重的腐蚀问题。",al={"为什么奥努召唤我","谈话原因","为什么要去见奥努"}},{q="古树之林在哪里？",a="古树之林位于奥伯丁以南，坐落在东部山脉的山麓边。沿着黑海岸的主路向南走，然后向东前往山坡，就能找到奥努。",al={"奥努的位置","古树之林在哪里","如何找到奥努"}},{q="知识古树是什么样的生物？",a="知识古树是与暗夜精灵及塞纳里奥议会结盟的古老树人生物。它们因其深厚的智慧和记忆而备受尊崇，是自然魔法和历史秘密的活体宝库。",al={"知识古树","奥努是什么生物","树人和古树的区别"}},{q="为什么奥努的召唤被认为是紧急的？",a="众所周知，古树的行事风格深思熟虑、从容不迫，很少会匆忙行事。正如巴瑞萨斯·月影所指出的，如果像奥努这样耐心且有条理的生物主动要求与你商议，那么黑海岸面临的威胁一定非常严重。",al={"为什么紧急","奥努是否担心","巴瑞萨斯的警告"}},{q="与奥努会面后会发生什么？",a="在你到达古树之林后，奥努会请求你的协助，去调查海岸以南更远处的巨大威胁：围绕着主宰之剑正在进行的险恶挖掘活动。",al={"奥努之后的下一个任务","接下来会发生什么","奥努让你去哪里"}}},fx={be40e913={q="为什么巴瑞萨斯·月影要派我去找 Onu？",a="巴瑞萨斯知道，博学古树对这片土地的腐化有深刻的了解，而 Onu 已经直接注意到了你在峭壁之泉洞穴中的发现。古树很少主动召唤他人，除非黑海岸面临严重而紧迫的威胁，因此巴瑞萨斯催促你立刻响应召唤。",al={"巴瑞萨斯的动机","为什么要去找 onu","巴瑞萨斯为什么要我做这件事"}}},fp="3,240,27.538.0,20.427.0,11.238.0,35.259.0,35.208.0,44.211.0,39.231.0,34.209.1"}
P.entries["quest:94863"] = {n="Taming the Beast",s="“Taming the Beast”是一项由Josephine Carson监督的猎人训练课程。在学习了驯服野猪的野兽掌控基础知识后，有抱负的猎人必须使用驯兽棒来赢得一只更凶猛的灰森林狼的信任。",h="“Taming the Beast”是一项由Josephine Carson监督的猎人训练课程。在学习了驯服野猪的野兽掌控基础知识后，有抱负的猎人必须使用驯兽棒来赢得一只更凶猛的灰森林狼的信任。",kw={"野兽驯服","灰森林狼","猎人","猎人训练","josephine carson","驯兽棒","taming the beast"},ang={["class:Hunter"]="这项训练标志着猎人成长过程中的重要仪式，教会了猎人与荒野中凶猛的掠食者交流所需的耐心与尊重。"},sec={{t="猎人之道",b="猎人与荒野的联系不仅仅需要追踪和射击技巧，更需要赢得野生生物信任所需的尊重与耐心。在通过简单的野猪证明了自己的基础技能后，有抱负的猎人们将面临一项更严峻的挑战：深入森林，驯服一只灰森林狼。在训练师Josephine Carson的注视下，猎人将被授予一根附魔的驯兽棒，用以安抚这只掠食者，并学习猎人与野兽之间微妙的平衡。"},{t="本能与信任的考验",b="Josephine Carson为猎人提供了一根特制的驯兽棒，旨在引导一种能够让猎人接近危险野生动物的安抚力量。这项任务需要耐心和精确，因为必须在不使用致命武力的情况下接近狼，并温和地克服其天生的攻击性。一旦建立了联系，且猎人证明了自己能够与野兽的精神和谐相处，驯兽棒就会归还给Josephine，作为猎人对荒野掌控力日益增强的证明。"}},faq={{q="什么是“Taming the Beast”任务？",a="“Taming the Beast”是一项猎人训练试验，训练师会要求有抱负的猎人使用附魔的驯兽棒追踪并驯服一只灰森林狼。",al={"taming the beast任务","灰森林狼任务","驯狼课程"}},{q="谁发布并完成这个任务？",a="Josephine Carson担任这项试验的指导员。她提供驯兽棒，并在任务完成后评估你与森林野兽之间的联系，随后收回驯兽棒。",al={"谁发布taming the beast","josephine carson是谁","taming the beast交任务地点"}},{q="你需要驯服什么生物？",a="你的任务是驯服一只灰森林狼，这比你之前练习驯服的野猪更进一步，难度也更高。",al={"我要驯服什么","什么野兽","taming the beast的目标"}},{q="驯兽棒有什么用？",a="驯兽棒是Josephine Carson提供的一种教学工具，旨在帮助见习猎人安抚野生的灰森林狼并与之建立临时的联系，而不会造成永久性的伤害。",al={"驯兽棒的作用","为什么要用驯兽棒","驯兽棒背景故事"}},{q="猎人在这次试验前驯服了什么？",a="在面对灰森林狼之前，你通过掌握如何驯服一只森林野猪，展示了你对野兽掌控的初步能力。",al={"之前的驯服课程","在狼之前驯服了什么"}},{q="灰森林狼会成为永久的伙伴吗？",a="不会，这项试验旨在作为掌握野兽羁绊技巧的集中课程。当你练习完技巧后，需要将驯兽棒归还给Josephine Carson。",al={"狼会保留吗","狼是永久宠物吗"}}},fp="16,228,22.510.0,28.478.0,35.164.0,35.178.0,34.125.0,32.191.0,43.131.0,58.174.0"}
P.entries["quest:94864"] = {n="Taming the Beast",s="Taming the Beast是猎人在艾尔文森林初期训练的最终考验，由约瑟芬·卡森负责监督。在证明了驯服野猪和狼的能力后，猎人们需要使用驯兽棒来安抚一头森林幼熊，并赢得它的信任。这项最终试炼加深了猎人与野兽之间的协调，并通过尊重与技巧来维护林地的自然平衡。",h="Taming the...",kw={"与野兽协调","野兽训练","艾尔文森林","猎人任务","约瑟芬·卡森","驯兽棒","taming the beast","森林幼熊"},ang={["class:Hunter"]="这项试炼标志着学徒猎人的一个重要成年仪式，将简单的追踪技巧转化为与荒野野兽之间深刻的共情与协调。",["faction:Alliance"]="熟练的兽王猎人加强了联盟的荒野侦察力量，他们提供的训练有素的同伴能够保卫家园并巡逻暴风城领地内的贸易道路。",["race:Human"]="对于在艾尔文森林训练的人类猎人来说，驯服当地野生生物教会了他们与王国的天然掠食者共存的重要性，而不是仅仅将其消灭。"},sec={{t="狩猎的最终试炼",b="艾尔文森林的准猎人们需要接受严格的训练，以了解与他们共享这片土地的野生生物。在已经展示了对狡猾的狼和强韧的野猪的控制力后，猎人们将面临勇气与耐心的终极测试。约瑟芬·卡森指导他们去面对森林幼熊，这是森林中最强壮、最威猛的常见掠食者。这项仪式旨在考验猎人能否承受熊的原始力量，并赢得它的信任，而不是单纯的征服。"},{t="艾尔文森林的尊重与平衡",b="驯服艾尔文森林野生生物的课程核心在于尊重，而非支配。森林熊代表了林地的力量与活力，在维护自然秩序方面发挥着至关重要的作用。通过使用专门制作的驯兽棒，猎人学会了平息野兽的侵略性，并建立起一种真正的相互理解的纽带。成功安抚这种强大的动物不仅能加深猎人对荒野的精神协调，也完成了他们在卡森指导下的基础课程。"}},faq={{q="是谁向猎人指派这项试炼的？",a="约瑟芬·卡森负责监督艾尔文森林猎人的这项试炼。在猎人成功驯服次级野兽后，她会对猎人的进度进行评估，并提供驯服森林熊所需的指导和驯兽棒。试炼完成后，猎人会直接将棒子交还给她，以标志训练的圆满完成。",al={"谁给予taming the beast任务","taming the beast任务发布者","约瑟芬·卡森任务"}},{q="在挑战这项试炼之前必须驯服哪些野兽？",a="在进行驯服森林幼熊的挑战之前，猎人必须先通过驯服野猪和狼来证明自己的技巧与耐心。这些初步试炼证明了猎人在尝试面对艾尔文森林熊的强大力量之前，已经能够应对好斗的野兽和群体性野兽。",al={"驯服任务的前置野兽","驯服熊之前驯服什么","在此之前驯服的野兽"}},{q="为什么要让猎人去寻找森林幼熊？",a="森林幼熊代表了艾尔文森林野生生物的力量与威猛。野猪和狼测试了猎人处理敏捷或顽强野兽的能力，而熊则是对忍耐力、尊重和身体勇气的终极考验。赢得这种强大掠食者的信任，证明了猎人已经完全掌握了基础的野兽驯服技巧。",al={"为什么驯服森林幼熊","森林幼熊的目的","为什么艾尔文有熊"}},{q="驯兽棒的用途是什么？",a="驯兽棒是约瑟芬·卡森提供的一种特殊训练工具，用于帮助猎人安抚野生动物。它能引导猎人集中精神，在不杀死森林幼熊的情况下平息其攻击性，从而建立起和平的纽带。试炼结束后，随着训练完成，驯兽棒会被交还给卡森。",al={"驯兽棒的作用","驯兽棒的功能","为什么要使用驯兽棒"}},{q="驯服野兽如何帮助艾尔文森林？",a="驯服野生生物被视为维护艾尔文森林自然平衡的一项必要实践。通过以尊重和克制而非狩猎的方式对待掠食者，猎人有助于保护当地生态系统与整个地区的人类定居点之间的和谐，确保危险的野兽得到和平引导，而不是被消灭。",al={"为什么艾尔文的平衡很重要","艾尔文森林平衡","驯服与森林平衡"}},{q="完成这门课程对猎人意味着什么？",a="完成这项最终任务加深了猎人与荒野野兽之间内在的协调。通过赢得艾尔文森林最强大生物的信任，猎人超越了简单的狩猎技巧，掌握了与艾泽拉斯各地的动物同伴建立终身伙伴关系所需的精神连接。",al={"驯服熊之后会发生什么","猎人训练完成","与野兽协调的意义"}},{q="在哪里可以找到森林幼熊？",a="森林幼熊在艾尔文森林的林区中游荡，与狼和蜘蛛一起生活在茂密的树林中。从附近定居点出发的猎人必须在森林的灌木丛中追踪这些强壮的生物，以便使用驯兽棒并完成卡森的最终指令。",al={"森林幼熊位置","在艾尔文哪里找熊","艾尔文森林熊"}}},fp="16,388,27.493.0,29.509.0,34.354.0,49.325.0,47.350.0,38.343.0,42.366.0,54.308.0,35.294.0"}
P.entries["quest:94896"] = {n="Aid For The Refugees",s="“Aid For The Refugees”聚焦于班艾萨尔的流离失所的幸存者们，这是一个深藏在影风森林中的定居点，在深夜时分被突然疏散。随着他们的家园坠入天空，周围的荒野也变得太过危险而无法进入，难民们只能依靠勇敢的旅行者来找回他们不得不留下的财物。",h="“Aid For The...",kw={"aid for the refugees","班艾萨尔","财物","ealaane","难民","影风森林"},sec={{t="绝望的恳求",b="“Aid for the Refugees”是Ealaane和她流离失所的村民同伴们发出的求助。在险些逃离了深藏于影风森林的家园后，幸存者们聚集在一起，几乎一无所有，希望路过的旅行者能勇闯他们留下的危险之地。"},{t="班艾萨尔的灾难",b="班艾萨尔定居点在深夜遭遇了难以想象的命运，整个村庄突然开始坠入天空。这场怪异而恐怖的灾难只给居民们留下了片刻的逃生时间，迫使他们在周围森林变得充满敌意和危险时，不得不放弃了他们的个人财物。"}},faq={{q="Ealaane是谁？",a="Ealaane是班艾萨尔的一名难民，在他们的定居点开始崩塌时，她与其他幸存者一起逃了出来。她请求路过并前往影风森林的冒险者们找回留在废墟中的个人财物。",al={"谁发布了aid for the refugees","aid for the refugees任务发布者","ealaane"}},{q="班艾萨尔发生了什么？",a="班艾萨尔是深藏于影风森林中的一处定居点。由于一场突如其来的离奇灾难，其居民最近被迫在深夜进行了疏散。",al={"什么是班艾萨尔","班艾萨尔在哪里","班艾萨尔村"}},{q="村民们为什么要疏散班艾萨尔？",a="疏散行动在深夜突然触发，当时班艾萨尔开始坠入天空。村庄和周围的森林变得太过危险，以至于居民们无法留下或返回。",al={"为什么要疏散班艾萨尔","坠入天空","班艾萨尔灾难"}},{q="村民们为什么要请求找回他们的财物？",a="这场灾难在深夜突然降临，迫使村民们在几乎一无所有的情况下逃命。由于森林和废墟现在充满了危险，他们只能依靠有能力的冒险者来取回留下的东西。",al={"为什么要找回财物","被遗弃的财物","为何要回收财物"}},{q="什么是影风森林？",a="影风森林是拥有班艾萨尔定居点的林区。在撕裂了村庄的离奇灾难发生后，这片森林对普通人来说已经变得极其危险。",al={"影风森林在哪里","影风森林背景故事"}},{q="难民们能回到他们的家园吗？",a="不能。据Ealaane所说，无论是影风森林还是班艾萨尔废墟，对于流离失所的居民来说都太过危险，他们无法独自返回。",al={"难民能回去吗","班艾萨尔安全吗"}}},fp="20,359,16.297.0,26.311.0,15.222.0,28.182.0,50.204.0,66.247.0,26.196.0,39.155.0"}
P.entries["quest:94897"] = {n="The Fate of a Loved One",s="\"The Fate of a Loved One\" 是一项关于 Resaan 的任务，他冒险进入危险的班艾萨尔废墟搜寻补给，却一去不回。一周多过去了，他悲痛的伴侣请求前往该废墟的旅人们查明他的下落，要么带他回家，要么寻回他珍视的传家宝。",h="\"The Fate of a Loved One\" 是一项关于 Resaan...",kw={"班艾萨尔","传家宝","resaan","班艾萨尔废墟","补给","the fate of a loved one"},sec={{t="绝望的恳求",b="\"The Fate of a Loved One\" 的核心是一位绝望者的请求，他的伴侣 Resaan 冒险重回了班艾萨尔废墟。尽管曾恳切地劝他留下，Resaan 还是执意要闯入废墟寻找补给，留下某人在痛苦的未知中等待。"},{t="消失在废墟中",b="自 Resaan 出发以来已经过去了一周多，这远远超出了能够迅速返回的预期。前往班艾萨尔废墟的旅人们受托在废墟中寻找他——如果他还活着，就指引他回来；如果只剩下不幸的结果，就寻回他的家族传家宝。"}},faq={{q="Resaan 是谁？",a="Resaan 是一名冒险回到班艾萨尔废墟搜集补给的人，尽管他曾被苦苦哀求留下。在一周多没有音讯后，他的爱人担心他在废墟中遭遇了不幸。",al={"resaan 是谁","resaan 在哪里","寻找 resaan"}},{q="班艾萨尔废墟是什么地方？",a="班艾萨尔废墟是一处危险之地，Resaan 冒险前往那里寻找必要的补给。他的爱人认为这趟旅程极其凶险，独自在那里生存一周的可能性微乎其微。",al={"班艾萨尔是什么","班艾萨尔废墟背景故事","班艾萨尔在哪里"}},{q="为什么 Resaan 要回到班艾萨尔废墟？",a="Resaan 回到班艾萨尔废墟是为了取回补给。尽管他的爱人恳求他不要去，他还是选择了踏上这段危险的旅程。",al={"为什么 resaan 要回去","为什么 resaan 在班艾萨尔废墟"}},{q="任务发布者请求你带回什么？",a="如果 Resaan 还活着，任务发布者请求将他平安带回家。如果他已在废墟中遇难，任务发布者请求寻回他的私人传家宝作为最后的纪念。",al={"任务发布者想要什么","如果 resaan 死了会怎样"}},{q="Resaan 失踪了多久？",a="自出发前往班艾萨尔废墟以来，Resaan 已经失踪了一周多。考虑到该地区的危险，这段漫长的沉默让他的爱人担心发生了最坏的情况。",al={"resaan 失踪了多久","resaan 离开了多久"}},{q="谁发布了这个任务？",a="该任务由 Resaan 悲痛的伴侣或爱人发布，他们渴望得到一个了结，并愿意向途经此处前往班艾萨尔废墟的旅人寻求帮助。",al={"谁发布了 the fate of a loved one","the fate of a loved one 任务发布者"}}},fp="23,296,16.297.0,21.290.0,14.217.0,33.199.0,36.156.0,47.193.0,33.180.0,22.165.0"}
P.entries["quest:949"] = {n="暮光之锤的营地",s="暮光营地是联盟的一项侦察任务，旨在调查在黑海岸南部主宰之剑周围安营扎寨的神秘邪教徒。调查员通过观察水晶球窥见了他们的祭坛，必须潜入挖掘现场，查明暮光之锤试图挖掘出什么东西。",h="暮光营地是联盟的一项侦察任务，旨在调查在黑海岸南部主宰之剑周围安营扎寨的神秘邪教徒。调查员通过观察水晶球窥见了他们的祭坛，必须潜入挖掘现场，查明暮光之锤试图挖掘出什么东西。",kw={"黑海岸","主宰之剑","欧努","观察水晶球","暮光营地","暮光典籍","暮光之锤"},ang={["class:Druid"]="揭露邪教的研究对于塞纳里奥哨兵来说至关重要，他们致力于让那些带有腐蚀性的远古实体安全地保持埋藏状态。",["faction:Alliance"]="阻止邪教诡异的挖掘活动，可以防止一个正在形成的威胁破坏卡利姆多北部的稳定。",["race:NightElf"]="暮光之锤在黑海岸远古树林的枝叶下，用黑暗巫术玷污了神圣的卡利姆多土地。"},sec={{t="探测挖掘点",b="主宰之剑长久以来一直矗立在黑海岸南部的崎岖山丘上，是一个令人不安的石化谜团，但暮光之锤邪教的突然到来，让这处远古奇观变成了一个现实的威胁。在利用观察水晶球窥探了他们的防御工事后，斥候们被派往营地深处，以便在敌人采取防御措施之前查明他们的真实意图。"},{t="插图典籍",b="搜查营地后发现，这些邪教徒并非仅仅是拾荒者或强盗，他们的行动受到深奥神秘学研究的指引。在他们北部营地的深处，放置着一本古老且精心手绘的典籍，里面配有精湛却令人不安的插图。这本典籍证明，暮光之锤正在蓄意调查埋藏在地下的巨大实体。"}},faq={{q="“暮光营地”任务的目标是什么？",a="你必须潜入黑海岸南部主宰之剑附近的暮光之锤营地，并找回一份详述他们动机的线索——具体来说，就是存放在他们营地中的一本手绘仪式典籍。",al={"暮光营地任务目标","暮光营地要做什么"}},{q="是谁派你去调查营地的？",a="该任务直接从主宰之剑上方眺望台的观察水晶球处获取，延续了代表远古守护者欧努所发起的调查。",al={"谁给予暮光营地任务","暮光营地任务发布者"}},{q="在营地哪里可以找到线索？",a="有效的线索是位于营地北部的暮光典籍。营地中的其他典籍可能是危险的诱饵，会向闯入者释放防护魔法。",al={"书在哪里","暮光典籍位置","寻找暮光营地线索"}},{q="暮光之锤为什么会在主宰之剑？",a="这些邪教徒痴迷于上古之神及其仆从的远古黑暗力量。他们正在挖掘被那把巨大的石剑钉住的巨大石化尸骸，试图研究或唤醒残留在其中的任何远古邪恶。",al={"为什么邪教徒在主宰之剑","暮光之锤在黑海岸的目的"}},{q="找到典籍后会发生什么？",a="找回典籍后会引出“重回欧努身边”任务，指示你将发现的文书带往北部的古树之林，交给那里的远古树人。",al={"暮光营地后续任务","找到暮光典籍后去哪里"}}},fx={["8554815a"]={q="为什么占卜之碗指引你去调查营地？",a="Onu 的占卜之碗显示，暮光之锤教徒聚集在主宰之剑周围。那里很久以前曾有一位古老的“旧主”陨落。他们聚集于此的目的尚不清楚，但 Onu 确信绝非善事。在他和林地的守卫制订计划之前，他们需要从营地找到能揭示教徒意图的东西。",al={"为什么调查暮光营地","占卜之碗的用途","为什么搜查暮光营地"}}},fp="17,319,15.403.0,20.395.1,44.211.0,38.174.0,36.178.0,52.225.0,36.160.0"}
P.entries["quest:94947"] = {n="Welcome to Azeroth",s="“Welcome to Azeroth”标志着Skyborne旅客通过Skyborne Portal抵达人类首都暴风城。在向Stormwind Keep报到后，新来者将获得伯瓦尔·弗塔根公爵的正式认可与许可，得以在联盟领土上自由旅行。",h="“Welcome to Azeroth”标志着Skyborne旅客通过Skyborne Portal抵达人类首都暴风城。在向Stormwind...",kw={"bolvar fordragon","高等精灵","高阶会","肯瑞托","传送门","skyborne","stormwind keep","welcome to azeroth"},ang={["faction:Alliance"]="伯瓦尔·弗塔根公爵代表安度因·乌瑞恩国王正式欢迎高阶会，并授予他们自由穿行联盟领土的许可。",["race:Skyborne"]="对于Skyborne来说，这次觐见正式为通过传送门抵达的高等精灵旅客打开了暴风城和联盟领土的大门。"},sec={{t="抵达首都",b="旅客通过神秘的Skyborne Portal抵达，直接踏入了繁华的暴风城首都。作为报到任务的一部分，新来者穿过城市的大道，前往Stormwind Keep，向摄政王报到。"},{t="觐见摄政王",b="站在宏伟的王座大厅里，伯瓦尔·弗塔根公爵在收到肯瑞托信使的预先通知后，迎接了到来的高阶会成员。摄政王提到，已经有很长一段时间没有高等精灵走在Stormwind Keep的走廊里了，他慷慨地接受他们作为客人，并代表国王授予他们在所有联盟领土上自由通行的权利。"}},faq={{q="这个任务是关于什么的？",a="“Welcome to Azeroth”是一个引导任务，旅行者通过Skyborne Portal进入暴风城，并在Stormwind Keep向伯瓦尔·弗塔根公爵报到。",al={"welcome to azeroth是什么","welcome to azeroth任务"}},{q="Bolvar Fordragon是谁？",a="伯瓦尔·弗塔根公爵担任暴风城王位的摄政王，在国王Varian失踪期间，代表年轻的安度因·乌瑞恩国王在Stormwind Keep治理国家。",al={"bolvar fordragon是谁","暴风城摄政王"}},{q="为什么Bolvar要接待Skyborne？",a="一位来自肯瑞托的信使通知了Bolvar Fordragon，高阶会成员即将抵达。Bolvar接受他们作为王室的客人，并允许他们在联盟领土上自由探索和旅行。",al={"为什么skyborne在暴风城","暴风城高等精灵"}},{q="什么是高阶会？",a="高阶会代表了与Skyborne高等精灵相关的派系或团体，他们的到来是由肯瑞托向暴风城的领导层通报的。",al={"高阶会是谁","高阶会背景故事"}},{q="Skyborne Portal通向哪里？",a="Skyborne Portal将旅客直接带入人类首都暴风城，让新来者可以直接前往Stormwind Keep寻求觐见王室。",al={"skyborne portal目的地","传送门去哪"}},{q="Skyborne可以在联盟领土内自由活动吗？",a="Bolvar Fordragon代表国王正式欢迎Skyborne作为客人，并明确允许他们在联盟全境畅行无阻。",al={"skyborne是联盟吗","skyborne加入联盟"}}},fp="18,272,22.292.0,27.369.0,25.187.0,24.188.0,37.226.0,23.158.0,36.180.0,55.171.0"}
P.entries["quest:95"] = {n="斯温的复仇",s="出于悲痛与复仇的驱使，隐士斯温·约根请求过往旅人回到他位于暮色森林南部的破败农场。尽管他多年来一直在追捕屠杀他家人的暗影骑士，但曾有一个可疑的身影在他的谷仓附近埋下了某样东西，那可能藏着真相。",h="出于悲痛与复仇的驱使，隐士斯温·约根请求过往旅人回到他位于暮色森林南部的破败农场。尽管他多年来一直在追捕屠杀他家人的暗影骑士，但曾有一个可疑的身影在他的谷仓附近埋下了某样东西，那可能藏着真相。",kw={"暗影骑士","逆风小径","暮色森林","松散的土堆","树桩","斯温·约根","斯温的复仇","约根农场"},ang={["class:Paladin"]="来自逆风小径的邪恶势力对无辜者的残酷屠杀，必须得到正义的制裁，为死者讨回公道。",["faction:Alliance"]="约根一家的惨剧是暮色森林与世隔绝的又一例证，展示了在没有暴风城常规军队巡逻的情况下，黑暗势力的触角延伸得有多远。"},sec={{t="农场的惨剧",b="斯温·约根曾是一名在暮色森林东南部耕作的普通农夫。在他外出时，从逆风小径策马而下的兜帽暗影骑士袭击了他的家园，屠杀了他的家人，他的人生由此破碎。斯温回到家看到屠杀现场时，瞥见一个不知名的人影在谷仓附近鬼鬼祟祟，慌忙地在土里埋着什么东西。斯温选择了复仇，他立即出发去追杀凶手，将那个被掩埋的东西丢在了身后。"},{t="挖掘秘密",b="如今，心怀愤怒的斯温在西部的山丘上安营扎寨，他需要有人回到约根农场。在农舍和破败谷仓之间的一截老树桩后，有一堆匆忙堆起的松散泥土。找回埋在那里的东西，是了解为何那些暗影骑士会对一位宁静的暮色森林农夫下手的关键第一步。"}},faq={{q="谁是斯温·约根？",a="斯温·约根曾是一位居住在暮色森林东南部，靠近逆风小径边缘的普通农夫。在回家发现家人被邪恶的骑士杀害后，他抛弃了农场，变成了一个一心只想向凶手复仇的隐士。",al={"斯温是谁","斯温背景故事","斯温人物传记"}},{q="斯温的农场发生了什么？",a="斯温的农场遭到了来自逆风小径的神秘暗影骑士的突袭。他们在斯温赶回防守之前就屠杀了他全家，并将农场洗劫一空。",al={"约根农场惨剧","斯温农场发生了什么","为什么斯温的农场被摧毁"}},{q="谁在谷仓后埋了东西？",a="屠杀刚刚发生后，斯温看到一个暗影般的身影潜伏在谷仓附近埋藏物品。为了追击暗影骑士，斯温逃向了荒野，没能抓住那个陌生人，也没能挖掘出被隐藏的东西。",al={"谁埋了那个东西","斯温农场的暗影人影","谁挖了土堆"}},{q="那堆松散的泥土在哪里？",a="那堆松散的泥土位于暮色森林东南部的约根农场，就在谷仓和破败农舍之间的一截老树桩的正后方。",al={"土堆在哪里","土堆位置","树桩在哪里"}},{q="暗影骑士是什么人？",a="暗影骑士是骑马从逆风小径中出来的邪恶兜帽骑士。关于他们的起源知之甚少，但他们在暮色森林的暴力入侵只会留下死亡与废墟。",al={"暗影骑士是什么","暗影骑士背景","逆风小径的骑士"}},{q="为什么斯温自己不挖出那个埋藏的物品？",a="当斯温回到家看到那个人埋藏物品时，他被悲痛所吞噬，立即去追赶撤退的暗影骑士了。等他建立起隐藏的营地时，农场已经被洗劫一空，对他来说那是一个过于痛苦、无法直接重返的地方。",al={"为什么斯温不去检查泥土","斯温为何离开"}}},fx={e064b97c={q="斯温·约根为什么想找回埋藏的物品？",a="斯温想为家人遭到逆风小径神秘的黑暗骑士残忍屠杀一事复仇。他发现惨案时，目睹一个阴影中的身影在谷仓附近匆忙埋下了什么，随后逃走。斯温满腔怒火，迫切想弄清真相。他相信土里埋着的东西能揭开农场遭袭的原因，以及谁参与了他家人的惨祸。",al={"斯温为什么想要这个","斯温·约根的动机","斯温复仇任务的原因"}}},fp="14,282,24.471.0,18.385.0,19.274.0,29.193.0,37.213.0,41.166.0,24.197.0,47.247.0"}
P.entries["quest:950"] = {n="向安努回复",s="“返回奥努身边”是一个联盟任务，它终结了对黑海岸沿岸扎营的邪教徒的初步调查。在突袭了邪教徒的营地并尝试阅读《暮光宝典》后，冒险者获得了一张令人发狂的书页，需要将其交给古树之林里的知识古树奥努。",h="“返回奥努身边”是一个联盟任务，它终结了对黑海岸沿岸扎营的邪教徒的初步调查。在突袭了邪教徒的营地并尝试阅读《暮光宝典》后，冒险者获得了一张令人发狂的书页，需要将其交给古树之林里的知识古树奥努。",kw={"黑海岸","古树之林","令人发狂的书页","古神","奥努","暮光宝典","暮光之锤"},ang={["class:Druid"]="涂鸦中混乱且不自然的共鸣，代表了对自然秩序的亵渎，而德鲁伊正致力于与像奥努这样的树人共同维护这些秩序。",["faction:Alliance"]="调查黑海岸沿岸的邪教活动，可以确保像奥伯丁这样的暗夜精灵定居点免受隐秘威胁的侵害。",["race:NightElf"]="黑暗邪教徒对黑海岸海岸的亵渎威胁到了知识古树们所守护的平衡，这使得奥努的警告与卡多雷息息相关。"},sec={{t="疯狂的一瞥",b="在暮光之锤的营地中发现《暮光宝典》后，任何窥视书中内容的人都会立刻感受到感官遭受的冲击。书写的文字在羊皮纸上游动舞动，原本华丽的卷轴装饰变成了怪诞的图形。精神上的压力如此巨大，以至于凡人的心智在屈服于眩晕之前，只能忍受撕下这一页胡乱涂写的笔记。"},{t="古老的疑虑",b="当这张碎片被送到奥努手中时，这位高大的古树辨认出了弥漫在其上的不自然气息。羊皮纸散发出一种混乱、原始的魔法，奥努将其直接归因于埋藏在地底的古老阴影力量。虽然这些潦草的涂鸦难以辨认，但它们证实了暮光之锤在黑海岸的存在并非单纯的强盗行径，而是某种更深层、更亵渎的计划的一部分。"}},faq={{q="从《暮光宝典》中取出的书页是什么？",a="这张书页被简单地称为“令人发狂的书页”，它是从该邪教的圣书中撕下来的一页。注视它会引起严重的精神痛苦，因为上面的文字会扭曲成与原始虚空魔法相连的怪诞、变幻的图形。",al={"令人发狂的书页","什么是涂鸦","暮光宝典书页"}},{q="奥努是谁？",a="奥努是一棵扎根于黑海岸南部古树之林的知识古树。他作为长者守护者和学者，引导暗夜精灵和联盟盟友对抗森林中出现的腐蚀。",al={"奥努是谁","奥努黑海岸","树人奥努"}},{q="奥努从这些涂鸦中学到了什么？",a="奥努感知到了从书页中散发出的混乱、原始的能量，并确认了古老邪恶实体的影响。这些文字表明暮光之锤的邪教徒正在黑海岸各处积极寻找遗迹地点和掩埋的力量。",al={"奥努发现了什么","涂鸦的含义"}},{q="为什么暮光之锤会出现在黑海岸？",a="该邪教被吸引到黑海岸是为了挖掘精灵遗迹，发掘与原始黑暗和古神有关的远古力量的痕迹，并利用这片土地上的混乱来掩盖他们的仪式。",al={"黑海岸的邪教徒","暮光之锤为何在此"}},{q="这项调查接下来会引向何处？",a="在发现邪教的存在后，奥努将注意力转向了北方的玛塞斯特拉废墟，指挥冒险者在邪教徒夺取这些古代遗物之前将其保护起来。",al={"下一个任务是什么","返回奥努身边后的后续"}},{q="为什么阅读宝典会导致头晕？",a="《暮光宝典》上刻有虚空和混乱的黑暗、疯狂魔法。这些符文会主动迷惑凡人的心智，引起幻觉和昏厥，从而阻止外人解开它们的秘密。",al={"为何宝典导致头晕","暮光宝典的效果"}}},fp="13,336,22.414.0,18.421.1,46.218.0,11.210.0,39.241.0,42.194.0,40.208.1,42.205.0"}
P.entries["quest:95041"] = {n="Data Hoarders",s="Data Hoarders是居住在铁炉堡的一名流亡侏儒Jemma Quikswitch所委托的任务。在诺莫瑞根绝望的大撤退期间，她将家族最珍贵的档案复制到了打孔卡上，却不慎在城市大门外的冰雪漂流中弄丢了几张。找回这些丢失的数据卡意味着要抢救从先进海军工程图纸到无可替代的家族食谱等一切重要资料。",h="Data Hoarders是居住在铁炉堡的一名流亡侏儒Jemma...",kw={"data hoarders","丹莫罗","诺莫瑞根","铁炉堡","jemma quikswitch","打孔卡","第二次战争","潜艇船体"},ang={["faction:Alliance"]="联盟非常依赖侏儒的独创性；帮助流离失所的难民保存战时工程记录，可以确保宝贵的联盟技术知识不会永远丢失。",["profession:Cooking"]="和世界级的工程图纸放在一起的，还有Quikswitch奶奶的个人辣椒食谱，这证明了美食与军事科学一样，具有同样的情感价值。",["profession:Engineering"]="工程师们可以体会到隐藏在这些卡片中的巨大价值，其中包括真实的第二次战争潜艇船体蓝图和复杂的奥术技术方程。",["race:Gnome"]="对于侏儒冒险者来说，找回这些打孔卡是文化保护的问题，确保重要的发明和家族记忆不会因为他们家园的放射性废墟而遗失。"},sec={{t="冰雪中的混乱",b="当穴居人入侵和随后的核辐射灾难迫使侏儒离开诺莫瑞根时，成千上万的人带着在混乱中抢到的任何物品逃离。Jemma Quikswitch采取了谨慎的措施，将几代人的家族知识转录到实体打孔卡档案中。不幸的是，一个破损的背包将几张关键卡片散落在了这座沦陷城市周围的雪原上。没有这些丢失的打孔卡，剩余的数据就会显示为无法解读的乱码，这可能会抹去她家族的知识遗产。"},{t="方程与辣椒",b="侏儒的数据档案反映了他们文明所侧重的奇异广度。Quikswitch家族的记录包括深奥的奥术技术领域方程、至关重要的第二次战争潜艇船体蓝图，以及Quikswitch奶奶的秘制辣椒食谱。对外人来说，将军事工程与家庭烹饪结合起来似乎很奇怪，但对于在铁炉堡幸存的难民来说，保存家庭生活的美好与保存技术奇迹同样重要。"}},faq={{q="Jemma Quikswitch是谁？",a="Jemma Quikswitch是一位设法逃脱诺莫瑞根陷落的侏儒难民，现在安全地居住在铁炉堡的矮人大厅中。",al={"jemma quikswitch","谁发布了data hoarders","data hoarders任务发布者"}},{q="丢失的卡片上存储了什么数据？",a="这些打孔卡保存着Quikswitch家族的档案，包括奥术技术方程、可追溯到第二次战争的潜艇船体图纸，以及Quikswitch奶奶的辣椒食谱。",al={"什么是打孔卡","卡片上有什么","quikswitch家族档案"}},{q="数据卡是在哪里丢失的？",a="它们在Jemma逃离诺莫瑞根时从她背包的破洞里滑落，埋在了丹莫罗这座地下城市大门外的雪地里。",al={"卡片在哪里","数据卡位置","她在哪里弄丢了卡片"}},{q="为什么没有丢失的卡片，Jemma就无法阅读幸存的卡片？",a="Jemma说，如果没有丢失的打孔卡，数据太乱了，无法恢复。任务中没有解释这些卡片是如何编码或组织这些信息的。",al={"为什么要找回所有卡片","乱码数据","打孔卡数据"}},{q="侏儒在第二次战争中对潜艇发挥了什么作用？",a="在第二次战争期间，侏儒通过先进的工程技术为联盟的军事行动做出了巨大贡献，特别是设计并驾驶潜水艇来对抗部落的海军部队。",al={"侏儒潜艇 第二次战争","潜艇船体设计"}},{q="为什么侏儒难民住在铁炉堡？",a="在诺莫瑞根因穴居人入侵和灾难性辐射而突然陷落后，幸存的侏儒逃离了他们的地下家园，并得到了国王麦格尼·铜须在邻近的矮人城市铁炉堡提供的庇护。",al={"为什么侏儒在铁炉堡","侏儒与矮人同住"}}},fp="13,403,22.544.0,19.469.0,24.143.0,38.187.0,34.180.0,66.158.0,65.204.0,45.234.0"}
P.entries["quest:95065"] = {n="Fishin' Time",s="“Fishin' Time”是吉尔伯特·格雷（Gilbert Gray）发布的一项简单的跑腿任务。这位年迈的垂钓者正悠闲地坐在暴风城港口，享受着迷人的海岸风光。就在鱼群开始上钩时，他的鱼饵用完了，因此他请求路过的冒险者前往城内的运河区，帮他补给鱼饵盒。",h="“Fishin' Time”是吉尔伯特·格雷（Gilbert...",kw={"运河","凯瑟琳·莱兰","fishin' time","吉尔伯特·格雷","夜行虫","发光的浮漂","暴风城港口","trade district"},ang={["faction:Alliance"]="花时间协助像吉尔伯特·格雷这样的老市民，体现了维持暴风城生活与士气的点滴日常琐事。",["race:Human"]="对于以暴风城为家的人类来说，帮助邻里长辈度过一个宁静的午后钓鱼时光，是远离王国政治纷争的一种惬意调剂。"},sec={{t="水边的一天",b="并非暴风城里的每个人都沉浸在政治、战争或迫在眉睫的阴谋之中。在港口边，吉尔伯特·格雷度过着平静的日子，享受着海风，看着浮漂在潮汐中起舞。但狂热的垂钓者很容易忘了查看自己的渔具，而鱼群一阵接一阵地上钩，很快就会耗尽哪怕是准备最充分的饵料罐。与其放弃他珍视的鲈鱼，这位老人转向好心的冒险者请求补给，希望能补充必需品。"},{t="运河边的补给",b="暴风城的本地垂钓需求都经由凯瑟琳·莱兰（Catherine Leland）满足。她在繁忙的Trade District以西，沿着石砌运河经营着一家知名的渔具店。莱兰为全城的渔民供应鱼饵和诱饵，确保像吉尔伯特·格雷这样的老顾客永远不会因为缺少发光的浮漂或扭动的夜行虫而不得不提前收竿。"}},faq={{q="吉尔伯特·格雷是谁？",a="吉尔伯特·格雷是一位年迈的渔夫，驻守在暴风城港口的水边。他满足于在海边度过抛竿垂钓的日子，当补给不足时，他会请路过的冒险者帮忙去取新鲜的鱼饵和诱饵。",al={"吉尔伯特·格雷","老格雷","谁发布的任务"}},{q="凯瑟琳·莱兰是谁？",a="凯瑟琳·莱兰是暴风城的常驻渔具供应商。她的商店位于Trade District以西的城市运河沿岸，在那里她向王国的垂钓者出售渔具和鱼饵。",al={"凯瑟琳·莱兰","暴风城渔具供应商","莱兰 暴风城"}},{q="吉尔伯特·格雷在哪里钓鱼？",a="吉尔伯特·格雷位于暴风城港口的水边，在那里他可以避开拥挤的城市街道，欣赏广阔的海景。",al={"吉尔伯特·格雷位置","吉尔伯特·格雷在哪里","港口渔夫"}},{q="吉尔伯特·格雷需要什么补给？",a="吉尔伯特·格雷需要夜行虫作为鱼饵，还需要一个发光的浮漂作为诱饵，这两样东西都可以从运河边的凯瑟琳·莱兰那里买到。",al={"fishin' time任务物品","格雷需要什么鱼饵"}},{q="为什么吉尔伯特·格雷不自己去取补给？",a="当你与他交谈时，鱼正咬钩咬得欢，他不想为了跑回城里补货而错过这个绝佳的垂钓点或放跑好鱼。",al={"为什么格雷不能自己买鱼饵","为什么格雷需要帮助"}},{q="凯瑟琳·莱兰的商店在运河哪里？",a="她的商店位于Trade District以西，正对着运河水域，可以直接从横跨城市水道网的石砌人行道到达。",al={"凯瑟琳·莱兰位置","莱兰的商店在哪里","trade district运河"}}},fp="12,264,18.462.0,25.376.0,20.228.0,24.196.0,29.139.0,37.159.0,52.165.0,58.163.0"}
P.entries["quest:951"] = {n="玛塞斯特拉遗物",s="这个任务指引联盟探险者沿着黑海岸的海岸线向北，去搜寻杂草丛生的玛塞斯特拉废墟。欧努，一位扎根于古树之林的知识古树，正在寻找这些古老的卡多雷神器，以了解暮光之锤教派是如何利用暗夜精灵魔法来举行邪恶仪式的。",h="这个任务指引联盟探险者沿着黑海岸的海岸线向北，去搜寻杂草丛生的玛塞斯特拉废墟。欧努，一位扎根于古树之林的知识古树，正在寻找这些古老的卡多雷神器，以了解暮光之锤教派是如何利用暗夜精灵魔法来举行邪恶仪式的。",kw={"黑海岸","古树之林","主宰之剑","玛塞斯特拉","欧努","遗物","玛塞斯特拉废墟","暮光之锤"},ang={["class:Druid"]="帮助欧努可以让德鲁伊侍奉自然界最伟大的长者哨兵之一，保护黑海岸的古老历史不被黑暗教徒所扭曲。",["faction:Alliance"]="防止暮光之锤将古代魔法武器化，对于保护卡利姆多北部免受黑暗地下势力的侵害至关重要。",["race:NightElf"]="对于暗夜精灵来说，看着他们大分裂前辉煌时期的遗物被从土里挖出来，这既是对文明衰落的沉痛提醒，也是一个令人震惊的警告：他们祖先的强大技艺正被末日疯子所利用。"},sec={{t="一项令人不安的发现",b="在探险者从潜伏在名为“主宰之剑”的巨大纪念碑周围的教徒手中找回一份被污染的羊皮纸后，欧努解读出了一个令人不安的真相。上面的文字并非本土教派的经文，而是一段被诅咒的古暗夜精灵文字残片。这份被暮光之锤污染的羊皮纸揭示，这些末日狂热者正在利用被遗忘的精灵魔法来唤醒或召唤他们古老的主人回到凡间。"},{t="陨落的壁垒",b="为了对抗这一邪恶企图，欧努指引英雄们前往位于黑海岸东北岸的玛塞斯特拉废墟。很久以前，玛塞斯特拉曾是上层精灵文明的一座辉煌壁垒，但在大分裂中毁于一旦。虽然这座城市已经沦为瓦砾、杂草丛生并遭到纳迦的入侵，但其最初奥术和精神魔法的强大残余仍萦绕在散落于石基之上的破碎骨灰瓮和古代遗物中。"},{t="洞悉黑暗阴谋",b="通过从废墟杂草丛生的瓦砾中收集幸存的工艺品，黑海岸的守卫者们希望揭开教徒们打算利用的具体手段。欧努研究着注入在这些遗物中的残留魔法，与时间赛跑，试图在暮光之锤完全扭曲古老的卡多雷魔法以解放其地下主人之前，解读出教派的计划。"}},faq={{q="什么是黑暗深渊遗物？",a="它们是遗留在玛塞斯特拉废墟中的附魔陶器、骨灰瓮和工艺品的碎片。它们创造于大分裂前古暗夜精灵文明的鼎盛时期，至今仍散发着残留的魔法能量。",al={"什么是遗物","黑暗深渊遗物背景","玛塞斯特拉精灵遗物"}},{q="欧努为什么想要这些遗物？",a="欧努发现暮光之锤教派正在利用古老的精灵魔法，试图将他们的黑暗主人带回这个世界。通过研究从玛塞斯特拉找回的完整遗物，欧努希望了解该教派打算如何操纵那股古老的力量。",al={"欧努为何需要遗物","黑暗深渊遗物的用途"}},{q="玛塞斯特拉废墟位于何处？",a="废墟位于黑海岸的东北海岸线沿途，在亚米萨兰和巴莎兰废墟以北，刚过奥萨拉克斯之塔。",al={"玛塞斯特拉在哪里","玛塞斯特拉位置"}},{q="暮光之锤试图召回谁？",a="该教派崇拜古老而邪恶的主人；欧努警告说，他们正在使用古老的精灵魔法将那些古老的主人带回艾泽拉斯。",al={"暮光之锤的主人是谁","黑海岸教派主人"}},{q="玛塞斯特拉在成为废墟之前是什么？",a="玛塞斯特拉曾是数千年前暗夜精灵的一座伟大壁垒和城市。它在大分裂期间沦为废墟，此后被荒野、鬼魂以及像纳迦这样邪恶的沿海生物所占据。",al={"玛塞斯特拉历史","玛塞斯特拉是什么"}},{q="谁提供了“黑暗深渊遗物”任务？",a="该任务由欧努提供，这是一位扎根于黑海岸中南部古树之林的远古树人，在调查过主宰之剑后即可领取。",al={"谁发布黑暗深渊遗物任务","黑暗深渊遗物任务发放者"}}},fp="16,329,22.461.1,18.465.0,21.377.1,30.237.0,31.253.0,42.141.0,50.142.0,43.230.0,39.163.0"}
P.entries["quest:95161"] = {n="Remember That I Love You",s="\"Remember That I Love You\"是一项联盟任务，起始于暴风城孤儿院，指引旅行者前往阴森的暮色森林。探险者需要递送一封凄惨的“染血的信”，并追踪一位新近被领养的孤儿Jeremy Heartweaver以及他的养母Avette Fellwood。",h="\"Remember That I Love You\"是一项联盟任务，起始于暴风城孤儿院，指引旅行者前往阴森的暮色森林。探险者需要递送一封凄惨的“染血的信”，并追踪一位新近被领养的孤儿Jeremy...",kw={"avette fellwood","染血的信","暮色森林","jeremy heartweaver","remember that i love you","暴风城","暴风城孤儿院"},ang={["faction:Alliance"]="将逝去或失踪亲人的信物带给被领养的孤儿，凸显了在这个王国动荡局势下，人们所承受的持久的个人代价。",["race:Human"]="对于暴风城的人类来说，这一差事连接起了相对安全的王国中心地带与暮色森林中那些闹鬼且被遗忘的定居点。"},sec={{t="给孤儿的信",b="暴风城孤儿院的孩子们肩负着沉重的负担，战争、苦难和笼罩王国的混乱让他们失去了家人。Jeremy Heartweaver曾是其中一员，直到最近他被一位名叫Avette Fellwood的妇女领养。尽管暮色森林阴森的林地里充满了危险和繁重的劳动，但孤儿院的看护人认为，与其让他被关在城里，不如给他一个拥有家庭的机会。"},{t="凄惨的信物",b="该任务围绕着递送一封寄给Jeremy的“染血的信”展开，信件需交由Avette Fellwood代收。打探消息会指引旅行者向南穿过安全的艾尔文森林，进入暮色森林的阴影中。包裹所透露出的惨状暗示着一段过去的悲剧，这段悲剧一直跟随着年幼的Jeremy，直到暴风城的大门之外。"}},faq={{q="谁是Jeremy Heartweaver？",a="Jeremy Heartweaver曾是在暴风城孤儿院抚养长大的一名小男孩。他最近被Avette Fellwood领养，离开了城市，去往暮色森林的阴影之地生活和工作。",al={"jeremy","jeremy是谁","孤儿jeremy"}},{q="谁是Avette Fellwood？",a="Avette Fellwood是Jeremy刚认的养母，居住在暮色森林。暴风城的修女们认为她是个和善的女人，领养Jeremy很可能是为了找个帮手来处理日常劳作。",al={"avette","avette是谁","养母"}},{q="什么是“染血的信”？",a="“染血的信”是一件寄给Jeremy Heartweaver的阴郁的递送物品，需直接交到他的养育者Avette Fellwood手中，信中承载着暴力或悲剧的余波。",al={"染血的信","这封信","什么是这封信"}},{q="我在哪里可以找到Avette Fellwood？",a="Avette Fellwood居住在暮色森林，这片黑暗的森林领地位于艾尔文森林河对岸的正南方。",al={"avette fellwood的位置","avette在哪里","寻找avette"}},{q="为什么Jeremy被送往暮色森林？",a="Jeremy是从暴风城孤儿院被领养走的。虽然暮色森林是一片危险且令人望而却步的土地，但他的看护人认为，与家人一起生活并从事诚实的劳动，比继续留在孤儿院里要好得多。",al={"为什么是暮色森林","jeremy为什么离开暴风城","孤儿院暮色森林"}},{q="哪个阵营可以接取此任务？",a="该任务仅限联盟接取，起始于人类主城暴风城，并深入到联盟控制的领地暮色森林。",al={"这是联盟任务吗","仅限联盟","部落任务"}}},fp="24,311,23.447.0,12.328.1,26.197.0,23.205.0,33.200.0,32.124.0,32.231.0,34.149.0"}
P.entries["quest:95189"] = {n="Crest of Lordaeron",s="Crest of Lordaeron是一件饱经风霜的遗物，上面刻有这个陨落的北方王国的皇室印记。在首都废墟中可以找到这样的遗物，自从王国覆灭以来，这些遗物变得十分稀有，而暴风城里的某个人对此非常感兴趣，希望能得到它。",h="Crest of Lordaeron是一件饱经风霜的遗物，上面刻有这个陨落的北方王国的皇室印记。在首都废墟中可以找到这样的遗物，自从王国覆灭以来，这些遗物变得十分稀有，而暴风城里的某个人对此非常感兴趣，希望能得到它。",kw={"crest of lordaeron","纹章","丹娜·肯尼迪女勋爵","洛丹伦","遗物","洛丹伦废墟","暴风城","提瑞斯法林地"},ang={["faction:Alliance"]="洛丹伦的徽章代表了最初联盟的基石，因此找回它不仅是象征性的胜利，也对抗了天灾军团和被遗忘者对其历史的彻底抹除。",["race:Human"]="对于人类，尤其是那些曾经把北方当作家园的家庭来说，这枚徽章是提醒人们曾经有一个伟大的王国引领过联盟的辛酸记忆。"},sec={{t="破碎的遗产",b="当亡灵天灾席卷洛丹伦王国时，它的宫殿、档案馆和引以为傲的徽章大多被摧毁，或是在幽暗城的阴影下腐朽殆尽。幸存下来的、带有皇室徽记的实物极为罕见。从北方废墟中找回一件完整或风化的徽章，代表着从遗忘中拯救出了一段真实的人类历史。"},{t="南方的避难所",b="第三次战争后，成千上万的北方难民逃往南方的暴风城王国，只带着对家园的记忆。在暴风城，丹娜·肯尼迪女勋爵渴望获得这些洛丹伦的遗存，这使得像这枚徽章这样的遗物在南方首都很受珍视。"}},faq={{q="什么是Crest of Lordaeron？",a="这是一枚风化的纹章，展示了洛丹伦的官方标志。在王国沦陷于亡灵天灾后被遗弃，对于人类幸存者来说，这是一件珍贵的历史遗物。",al={"crest of lordaeron","什么是crest of lordaeron","洛丹伦徽章物品"}},{q="谁想要Crest of Lordaeron？",a="这枚徽章被送交给了暴风城的贵族赞助人丹娜·肯尼迪女勋爵，她致力于收集和保护来自陨落北方王国的稀有文物。",al={"谁需要徽章","我应该把crest of lordaeron交给谁","徽章上交"}},{q="这枚徽章是在哪里发现的？",a="它是在提瑞斯法林地的洛丹伦废墟中发现的，那座被毁的首都城市如今就坐落在被遗忘者要塞幽暗城的正上方。",al={"徽章位置","废墟徽章","哪里可以获得徽章"}},{q="为什么洛丹伦的文物如此稀有？",a="王国在第三次战争中迅速而灾难性的覆灭，导致了其人民的系统性屠杀和地产的毁灭。很少有个人传家宝能在天灾军团以及随后崛起的被遗忘者手中幸存下来。",al={"为什么洛丹伦遗物稀有","洛丹伦文物稀有度"}},{q="为什么暴风城关心洛丹伦的遗物？",a="暴风城接纳了大量逃离北方浩劫的难民、骑士和贵族。保护这些遗物不仅是对联盟陨落的姐妹王国的缅怀，也是为了延续北方人类的文化遗产。",al={"为什么暴风城关心","暴风城洛丹伦遗物"}},{q="丹娜·肯尼迪女勋爵是谁？",a="丹娜·肯尼迪女勋爵是一位居住在暴风城的贵族女性，她热衷于搜救来自洛丹伦的历史残存和传家宝。",al={"丹娜·肯尼迪女勋爵","丹娜·肯尼迪是谁"}}},fp="18,272,20.382.0,19.297.0,31.180.0,33.164.0,26.159.0,41.242.0,50.208.0,25.164.0"}
P.entries["quest:95195"] = {n="Bloodied Insignia",s="Bloodied Insignia是洛丹伦已故守军的悲剧遗物，散落在王国那被摧毁的废墟之中。这些饱经风霜的徽记上印着旧联盟的纹章，代表着那些在第三次战争期间举家南逃至暴风城的士兵。",h="Bloodied Insignia是洛丹伦已故守军的悲剧遗物，散落在王国那被摧毁的废墟之中。这些饱经风霜的徽记上印着旧联盟的纹章，代表着那些在第三次战争期间举家南逃至暴风城的士兵。",kw={"联盟","bloodied insignia","洛丹伦","马库斯·乔纳森","难民","洛丹伦废墟","暴风城","第三次战争"},ang={["class:Paladin"]="许多在首都战死的士兵曾与白银之手骑士团并肩作战；找回他们的勋章是对这一神圣骑士团那些失散兄弟姐妹的致敬。",["faction:Alliance"]="将这些徽记交还给马库斯·乔纳森将军，不仅是一种职责，也是对那些为了保卫最初的联盟而献出生命的士兵的缅怀。",["race:Human"]="对于联盟的人类来说，这些徽记是人类最伟大王国陨落的庄严提醒，它将居住在暴风城的难民与他们在北方的阵亡亲人联系在了一起。"},sec={{t="阵亡者的信物",b="当阿尔萨斯王子带着天灾军团回到洛丹伦进行大清洗时，其庞大的军队遭到了压制与屠戮。无数士兵在保卫首都及其周边土地时战死，除却锈迹斑斑的铠甲和沾满血迹的黄铜，几乎没有留下什么实体痕迹。这些旧联盟的徽记属于那些在亡灵大军面前坚守阵地的勇士们。每一枚勋章都被践踏在废墟的泥土与瓦砾之中，它们是王国最后一搏的绝望见证。"},{t="流亡者的信使",b="许多洛丹伦的幸存者渡海向南逃亡，作为难民定居在暴风城。几十年的联盟与血缘关系将这两个人类王国紧密相连，这也让许多南方人渴望得知他们失踪亲人的下落。暴风城卫队指挥官马库斯·乔纳森将军负责保管这些Bloodied Insignia，以便让北方守军的记忆得以留存，并让他们的幸存家人最终能知晓他们的命运。"}},faq={{q="什么是Bloodied Insignia？",a="它们是洛丹伦王国士兵的军用勋章，这些士兵曾在第三次战争期间为了联盟的旗帜而战并牺牲。",al={"bloodied insignia物品","这个徽记是什么","徽记背景故事"}},{q="这些徽记在哪里可以找到？",a="它们在提瑞斯法林地的洛丹伦废墟各处被寻获，那是王国守军对阵天灾军团的最后战场。",al={"徽记在哪里掉落","徽记位置","洛丹伦废墟徽章"}},{q="为什么马库斯·乔纳森将军想要这些东西？",a="马库斯·乔纳森将军负责管理暴风城的防御，如今那里居住着无数的北方难民。他收集这些遗物是为了纪念洛丹伦战士们的牺牲，并让在南方的幸存亲属们获得解脱。",al={"马库斯·乔纳森是谁","为什么交给暴风城","马库斯·乔纳森徽记"}},{q="为什么洛丹伦士兵佩戴着联盟的徽记？",a="最初的联盟是在泰瑞纳斯·米奈希尔二世国王的领导下，在洛丹伦为了击败旧部落而组建的。在第二次和第三次战争期间，洛丹伦一直是洛丹伦联盟的核心与领导者。",al={"洛丹伦联盟纹章","洛丹伦联盟徽章"}},{q="那些佩戴勋章的士兵遭遇了什么？",a="当阿尔萨斯·米奈希尔王子背叛王国、刺杀其父并将亡灵天灾军团释放到首都时，他们在第三次战争中牺牲了。",al={"是什么杀死了士兵","洛丹伦士兵的命运"}},{q="这些士兵还有健在的亲人吗？",a="是的。在瘟疫和天灾入侵期间，成千上万的平民和士兵撤离了洛丹伦，最终在暴风城王国找到了避难所。",al={"洛丹伦难民暴风城","谁在怀念这些士兵"}}},fp="17,264,20.502.0,26.468.0,32.144.0,32.145.0,43.250.0,55.203.0,52.161.0,51.158.0"}
P.entries["quest:952"] = {n="古树之林",s="“古树之林”是一个联盟的递送任务，指引冒险者走出达纳苏斯，跨过海洋前往黑海岸。在大德鲁伊范达尔·鹿盔的指派下，信使负责将信件送给奥伯丁南部的Onu，一位受人尊敬的知识古树。",h="“古树之林”是一个联盟的递送任务，指引冒险者走出达纳苏斯，跨过海洋前往黑海岸。在大德鲁伊范达尔·鹿盔的指派下，信使负责将信件送给奥伯丁南部的Onu，一位受人尊敬的知识古树。",kw={"知识古树","奥伯丁","塞纳里奥议会","黑海岸","达纳苏斯","范达尔·鹿盔","古树之林","onu","神谕林地"},ang={["class:Druid"]="在达纳苏斯的大德鲁伊和Onu之间传递信件，让年轻的德鲁伊们接触到了塞纳里奥议会长者们截然不同的性情，对比了鹿盔的干劲与知识古树的宁静耐心。",["faction:Alliance"]="对于在达纳苏斯完成事务的联盟勇士来说，这项递送任务提供了一个早期的激励，去开启角鹰兽航线并探索黑海岸的沿海领土。",["race:NightElf"]="这项任务标志着从泰达希尔的庇护摇篮自然过渡到卡利姆多大陆更广阔的荒野，凸显了范达尔·鹿盔与玛法里奥·怒风教义之间的哲学对比。"},sec={{t="离开枝桠",b="在协助处理了泰达希尔顶部神谕林地的事务后，冒险者发现自己被大德鲁伊范达尔·鹿盔粗鲁地召集去执行进一步的任务。鹿盔从不浪费闲人，他指派信使携带一份紧急公文跨海前往黑海岸的古老森林，并指示他们从城里预订一架角鹰兽航班。"},{t="耐心的对比",b="抵达黑海岸并前往奥伯丁南部的古树之林后，信使将信件交给了Onu。这位高耸的知识古树在安静的沉思中接过了信件，微妙地指出了鹿盔那无休止的不耐烦。对于Onu和森林的古老守护者来说，万物皆有其时——这是一种珊多玛法里奥·怒风所体现的宁静而持久的智慧，而鹿盔显然缺乏这种品质。"}},faq={{q="谁发布了任务“古树之林”？",a="在你完成关于神谕林地的前序任务后，大德鲁伊范达尔·鹿盔会在达纳苏斯的塞纳里奥区发布该任务。",al={"古树之林任务发布者","谁发布古树之林任务","范达尔·鹿盔任务"}},{q="古树之林位于何处？",a="古树之林位于黑海岸的大陆上，坐落在海滨港口奥伯丁的正南方。",al={"古树之林位置","古树之林在哪里","onu位置"}},{q="Onu是谁？",a="Onu是一位居住在黑海岸，睿智而受人尊敬的知识古树。作为自然智慧的保护者和记录者，他接收来自达纳苏斯德鲁伊领袖的信件。",al={"onu是谁","onu 黑海岸","知识古树 onu"}},{q="如何从泰达希尔前往黑海岸？",a="旅行者通常会从达纳苏斯前往鲁瑟兰村，然后乘坐角鹰兽飞越水域，抵达黑海岸的港口定居点奥伯丁。",al={"如何前往黑海岸","前往奥伯丁","角鹰兽前往黑海岸"}},{q="为什么Onu提到了珊多·怒风？",a="在收到信件后，Onu评述了大德鲁伊鹿盔那躁动不安的急躁。他反思道，森林以自己的步调运行，这是一种珊多玛法里奥·怒风所理解并尊重的永恒耐心。",al={"onu评价玛法里奥","珊多·怒风提及","为什么提及珊多"}},{q="在此任务之前有什么任务？",a="该任务是一个简短的三部分序列的最后一步，该序列始于The Enchanted Glade，随后是Teldrassil，最后指引你前往黑海岸。",al={"古树之林前置任务","古树之林任务链","onu之前任务"}}},fx={["00893f03"]={q="大德鲁伊范达尔·鹿盔为什么要把这封信送给奥努？",a="范达尔·鹿盔希望与卡利姆多海对岸的古老守护者保持密切联系。扎根于黑海岸的知识古树奥努一直在等待大德鲁伊的消息，想了解泰达希尔的事务。如今范达尔收到了神谕林地的最新报告，迫不及待地想尽快传达他的发现和指示，继续推进暗夜精灵的计划。",al={"为什么给奥努送信","范达尔与古树之林的动机","范达尔为什么要送这个"}},["658e120a"]={q="范达尔·鹿盔为什么选你送信？",a="范达尔见你曾将神谕林地的消息送到达纳苏斯，认为你已经能够胜任远距离传递机密信件的差事。他没有调遣经验丰富的塞纳里奥使者或哨兵离开各自的职责，而是直接让一位可靠的信使把信送往黑海岸。",al={"范达尔为什么让我送信","为什么派玩家去找奥努","为什么不派哨兵去"}}},fp="21,265,18.383.0,22.447.0,43.149.0,43.118.0,11.183.0,43.155.0,39.210.0,33.162.0"}
P.entries["quest:95204"] = {n="Crest of Lordaeron",s="洛丹伦徽记是一件饱经风霜的历史文物，上面刻着这个已覆灭王国的纹章。在天灾军团的破坏下，几乎没有多少这样的宝物幸存下来，因此它被送往幽暗城的奥兰·斯内克威瑟手中，以帮助保护被遗忘者的过去遗产。",h="洛丹伦徽记是一件饱经风霜的历史文物，上面刻着这个已覆灭王国的纹章。在天灾军团的破坏下，几乎没有多少这样的宝物幸存下来，因此它被送往幽暗城的奥兰·斯内克威瑟手中，以帮助保护被遗忘者的过去遗产。",kw={"crest of lordaeron","被遗忘者","洛丹伦","奥兰·斯内克威瑟","遗物","幽暗城"},ang={["faction:Horde"]="协助幽暗城的被遗忘者档案管理员工作，有助于在天灾军团留下的废墟中保护洛丹伦的物质遗产。",["race:Undead"]="作为洛丹伦的曾经的公民，被遗忘者将他们已覆灭王国的幸存遗物视为他们过去生活和遗产的稀有残余。"},sec={{t="已覆灭王国的幸存象征",b="洛丹伦王国在第三次战争期间分崩离析，只留下了灰烬、废墟和天灾军团的荒芜。由于该国的大部分物质文化都被抹除了，像洛丹伦徽记这样幸存下来的徽章和纹章极为罕见。对于居住在首都废墟之下的被遗忘者来说，这些幸存下来的物品是连接他们曾经所属文明的宝贵物质纽带。"},{t="保护被遗忘者遗产",b="当从广阔的世界中寻回这枚风化的徽记后，它会被送交到幽暗城的奥兰·斯内克威瑟处。奥兰会验证其真实性——甚至会通过咬它来测试金属——然后确认它是家园一件正宗且基本完好的传家宝。对于奥兰和被遗忘者档案管理员来说，每一件回收的物品都有助于拼凑出一段天灾军团试图彻底抹去的历史。"}},faq={{q="什么是洛丹伦徽记？",a="洛丹伦徽记是一枚饱经风霜的纹章，上面刻着这个已覆灭人类王国的标志。由于在天灾军团的破坏下，极少有实物遗物留存下来，因此对于那些试图保护洛丹伦遗产的人来说，这是一件无价的历史文物。",al={"什么是洛丹伦徽记","洛丹伦徽记任务","徽记物品"}},{q="谁在幽暗城需要这枚徽记？",a="这枚徽记会被带给住在幽暗城的奥兰·斯内克威瑟。奥兰会仔细检查并妥善保管这些与旧王国有关的回收文物。",al={"谁接收徽记","在哪里上交徽记","在幽暗城上交徽记"}},{q="为什么奥兰·斯内克威瑟要咬这枚徽记？",a="在收到徽记后，奥兰·斯内克威瑟会咬它一下，以验证其真实性和材质成分，然后才宣布它是洛丹伦一件正宗且基本完好的遗物。",al={"为什么要咬徽记","奥兰咬徽记"}},{q="为什么被遗忘者珍视洛丹伦的遗物？",a="被遗忘者是洛丹伦前人口的亡灵残部。尽管他们已死且有了新的效忠对象，但他们被摧毁的家园的遗物代表了与他们历史和身份的切实联系。",al={"为什么被遗忘者关心洛丹伦","被遗忘者遗物"}},{q="徽记上交后会怎样？",a="奥兰·斯内克威瑟会接管这枚徽记以确保其安全，并将其视为一件珍贵的历史宝藏，以此来帮助恢复和铭记他们王国的遗产。",al={"徽记会怎样","徽记保存"}},{q="洛丹伦幸存的遗物有多罕见？",a="第三次战争前的实物徽章和遗物非常稀缺。当阿尔萨斯和天灾军团横扫该国时，洛丹伦的大多数象征物都被砸碎、掠夺或腐蚀了。",al={"徽记稀有吗","还剩多少徽记"}}},fp="18,256,40.433.0,28.385.0,31.248.0,33.159.0,41.173.0,46.203.0,52.181.0,45.187.0"}
P.entries["quest:95212"] = {n="Never Saddle on Quality",s="Never Saddle on Quality是丹莫罗冻石农场的一项联盟任务。驯兽师需要完好的山豹毛皮来为即将支援奥特兰克远征军的座骑公羊制作保暖鞍座。这项工作确保了坐骑和骑手能够抵御北部山脉刺骨的严寒。",h="Never Saddle on Quality是丹莫罗冻石农场的一项联盟任务。驯兽师需要完好的山豹毛皮来为即将支援奥特兰克远征军的座骑公羊制作保暖鞍座。这项工作确保了坐骑和骑手能够抵御北部山脉刺骨的严寒。",kw={"奥特兰克","奥特兰克远征军","冻石农场","丹莫罗","豹皮","never saddle on quality","完好的豹皮","公羊","鞍座"},ang={["class:Hunter"]="这项任务呼吁技术娴熟的追踪者和猎人去寻找丹莫罗最凶猛的山豹，以获取完好的毛皮。",["faction:Alliance"]="冻石农场的公羊繁育工作直接为在奥特兰克寒冷高地作战的联盟部队提供了坐骑支援。",["race:Dwarf"]="丹莫罗耐寒的山羊是标志性的矮人坐骑，冻石农场的饲养员拒绝给它们配备劣质的装备。"},sec={{t="为远征军备鞍",b="在丹莫罗的冻石农场，驯兽师们正在准备一批强壮的山羊，以支援在奥特兰克作战的联盟远征军。然而，由于缺乏制作耐用且防寒的兽鞍所需的合适材料，准备工作陷入了停滞。"},{t="高海拔山口的温暖保障",b="为了抵御奥特兰克山脉严酷的冰冻天气，远征军的坐骑需要厚实、高等级的隔热材料。猎人们被派往东部的悬崖峭壁去追踪丹莫罗体型最大、最凶猛的山豹，并获取它们完好的毛皮，以确保联盟部队得到的装备能够适应高海拔山口的生存需求。"}},faq={{q="Never Saddle on Quality是什么？",a="Never Saddle on Quality是基于丹莫罗冻石农场的一项任务。一位饲养员需要高质量的豹皮来为一批准备支援奥特兰克远征军的公羊制作结实、保暖的鞍座。",al={"这是什么任务","never saddle on quality任务","什么是never saddle on quality"}},{q="为什么需要豹皮？",a="这些毛皮用于制作耐用且保暖的远征军坐骑鞍座。丹莫罗的山豹提供了厚实、隔热性能良好的皮毛，适合保护骑手和坐骑免受奥特兰克刺骨山风的侵袭。",al={"为什么需要豹皮","兽皮有什么用","为什么需要完好的毛皮"}},{q="这些公羊将被送往何处？",a="这些坐骑将被送往在奥特兰克远征军中服役的联盟部队。由于高海拔山口气候恶劣且作战持续，装备精良的坐骑公羊是至关重要的支援。",al={"公羊要去哪里","谁接收公羊","奥特兰克援军"}},{q="冻石农场在此任务中扮演什么角色？",a="冻石农场位于卡拉诺斯以东，丹莫罗的雪山之中。它是矮人山羊的主要繁育和训练基地。",al={"冻石农场在哪里","冻石农场位置"}},{q="山豹在哪里出没？",a="凶猛的雪豹在冻石农场以东的丹莫罗雪山脊和悬崖间出没，猎人必须追踪这些体型最大的野兽以获得完好的兽皮。",al={"哪里找山豹","丹莫罗的山豹在哪里"}},{q="为什么防寒保护对远征军如此重要？",a="奥特兰克王国的山峰以严寒和强风而闻名。如果没有厚实、高质量的鞍具材料，坐骑和骑手在山地地形中将面临冻伤和力竭的风险。",al={"奥特兰克冷吗","为什么要保暖鞍座"}}},fp="23,312,23.289.0,26.335.0,32.233.0,29.217.0,30.186.0,37.160.0,27.174.0,63.193.0"}
P.entries["quest:95213"] = {n="Stolen Blasting Powder",s="“被盗的爆破火药”涉及在古博拉采掘场附近的穴居人中发现的一个空的、危险的炸药桶。将这个丢失的容器交给采掘场主管瑟斯滕，会暴露出该采掘场在安保和炸药储备方面存在的危险漏洞。",h="“被盗的爆破火药”涉及在古博拉采掘场附近的穴居人中发现的一个空的、危险的炸药桶。将这个丢失的容器交给采掘场主管瑟斯滕，会暴露出该采掘场在安保和炸药储备方面存在的危险漏洞。",kw={"爆破火药","丹莫罗","空火药桶","古博拉采掘场","火药桶","采掘场主管瑟斯滕","stolen blasting powder","瑟斯滕","穴居人"},ang={["faction:Alliance"]="确保丹莫罗的补给线和采矿前哨站不受穴居人入侵，对于联盟在卡兹莫丹的行动至关重要。",["profession:Engineering"]="爆破火药是一种危险的易燃材料；工程师比任何人都清楚穴居人使用未经授权的炸药会造成多大的破坏。",["profession:Mining"]="采掘场运作依赖于受控爆破来提取石料，但丢失的火药桶预示着挖掘坑内存在严重危险。",["race:Dwarf"]="古博拉采掘场为铁炉堡提供至关重要的石料和资源，因此其采矿炸药的安全性对任何矮人来说都是紧迫的关切。"},sec={{t="危险的发现",b="一个印有严重危险警告的空桶揭示出，危险的爆破火药已经从古博拉采掘场的授权人员手中流失。这种炸药是严格限制在采掘场主管直接授权下用于受控开采的。在敌对的穴居人中发现这个桶，表明该挖掘点正面临比日常劳动力中断更具破坏性的威胁。"},{t="采掘场主管的警觉",b="将空容器归还给采掘场主管瑟斯滕证实了矮人监督者们最担心的事。瑟斯滕看到这个桶时脸色变得苍白，意识到丢失的爆破火药已经被该地区泛滥的穴居人清空并动用。这一发现使采掘场领导层急于评估这些生物下一步打算炸毁什么。"}},faq={{q="什么是“被盗的爆破火药”？",a="“被盗的爆破火药”是一个任务，在古博拉采掘场附近的穴居人手中发现一个印有危险警告的空爆破火药桶后触发。它向采掘场主管瑟斯滕警示了易燃采矿物资被盗的情况。",al={"什么是被盗的爆破火药","火药桶任务","空火药桶背景"}},{q="谁应该接收这个空的火药桶？",a="空的火药桶必须直接交给在丹莫罗的古博拉采掘场负责运营的采掘场主管瑟斯滕。",al={"把桶带到哪里","谁是瑟斯滕","采掘场主管位置"}},{q="为什么被盗的爆破火药很危险？",a="这个桶上清楚地标有采掘场主管的授权警告，且装有危险的爆破火药。穴居人持有或引爆重型炸药会威胁到整个采掘场的挖掘工作及附近的定居点。",al={"为什么火药危险","携带炸药的穴居人","穴居人为什么有火药"}},{q="什么是古博拉采掘场？",a="古博拉采掘场是一个位于丹莫罗的矮人挖掘点，负责为铁炉堡开采石料和矿物。",al={"古博拉在哪里","采掘场位置","丹莫罗古博拉"}},{q="为什么采掘场主管瑟斯滕脸色苍白？",a="看到空桶时，采掘场主管瑟斯滕脸色明显变苍白，并询问是在哪里找到的，因为他立即意识到这些危险的内容物已经落入了敌对的穴居人手中。",al={"为什么瑟斯滕脸色苍白","瑟斯滕的反应","瑟斯滕说了什么"}},{q="穴居人在古博拉采掘场附近做什么？",a="穴居人已经侵扰了古博拉采掘场的下层区域和外围，干扰了矮人矿工，并从挖掘现场搜刮设备和爆破火药。",al={"穴居人在采掘场吗","丹莫罗穴居人入侵","穴居人为什么偷火药"}}},fp="22,240,21.389.0,24.378.1,31.240.0,40.129.0,44.210.0,25.128.0,40.193.0,44.164.0"}
P.entries["quest:95214"] = {n="Stolen Blasting Powder",s="Stolen Blasting Powder是丹莫罗的古博拉采掘场内的一项任务，探险者们必须在此找回遗失的军需品。原始的穴居怪偷走了一批足以夷平一座堡垒侧翼的炸药粉，迫使采掘场主管西斯登在灾难发生前招募谨慎的帮手。",h="Stolen Blasting Powder是丹莫罗的古博拉采掘场内的一项任务，探险者们必须在此找回遗失的军需品。原始的穴居怪偷走了一批足以夷平一座堡垒侧翼的炸药粉，迫使采掘场主管西斯登在灾难发生前招募谨慎的帮手。",kw={"爆破炸药","丹莫罗","炸药","古博拉采掘场","铁炉堡","国王麦格尼","采掘场主管西斯登","西斯登","穴居怪"},ang={["faction:Alliance"]="丹莫罗的补给线和石矿工程对联盟的山脉据点至关重要。维持和平并看管危险军需品能确保附近铁炉堡内High Seat的安全。",["profession:Mining"]="爆破炸药是深层挖掘中清理岩石和开掘矿脉不可或缺的工具，但操作它需要纪律——丢失大量炸药给野蛮的穴居怪是每一位采掘场主管的噩梦。",["race:Dwarf"]="古博拉采掘场为铁炉堡的石艺和挖掘工作提供能源。让地底穴居怪在国王麦格尼的家门口将采矿炸药武器化，这对任何矮人主管来说都是一场丢脸的安全事故。"},sec={{t="遗失的库存",b="在丹莫罗的古博拉采掘场，矮人的作业极其依赖强力爆破装药来破碎岩石并开掘深处的矿脉。然而，由于安保疏忽，潜伏在附近岩架上的原始穴居怪成功偷走了一整批高等级的爆破炸药。采掘场主管西斯登不得不匆忙寻找可靠的人手，以免这群小偷无意中引爆炸药。"},{t="岩架上的火药桶",b="遗失物资的数量极其惊人：西斯登指出，这些炸药桶所蕴含的爆炸威力足以将国王麦格尼·铜须的宏伟王座大厅变成露天庭院。穴居怪将这些危险的战利品运往了东边粗陋的山脚营地。如果放任不管，用不了多久，这些野蛮的生物就会发现火源，或是让石头撞出火花。"},{t="悄然解决",b="一旦从穴居怪手中夺回被盗的装药并安全送回采掘场仓库，西斯登如释重负地松了一口气。这位采掘场主管用一点奖励酬谢了探险者，并谨慎地恳求对方不要向任何人提及这起小事故。"}},faq={{q="谁是采掘场主管西斯登？",a="采掘场主管西斯登负责监管丹莫罗古博拉采掘场的挖掘工作。他负责工地的安全与生产效率，但他现在陷入了尴尬的困境，因为在他看管下，大量工业爆破炸药失踪了。",al={"谁是西斯登","采掘场主管西斯登","谁发布了这个任务"}},{q="在哪里可以找到被盗的爆破炸药？",a="炸药被古博拉采掘场正东面的岩架和洞穴中出没的穴居怪偷走了。探险者被派往那些岩石露头区域，从这些生物手中抢回危险的炸药桶和麻袋，以防灾难发生。",al={"stolen blasting powder在哪里","穴居怪位置","炸药位置"}},{q="穴居怪为什么要偷爆破炸药？",a="穴居怪是原始的地底生物，受本能的狡诈和领地侵略性驱使。虽然它们是从采掘场工人那里顺手牵羊偷走了炸药桶，但采掘场主管西斯登担心，即便是笨拙的实验也可能导致它们意外引爆炸药。",al={"为什么穴居怪要偷炸药","穴居怪要炸药做什么"}},{q="被盗的爆破炸药有多危险？",a="据采掘场主管西斯登所述，丢失的炸药桶内装有极其不稳定的爆破炸药，威力足以将国王麦格尼的王座大厅炸成露天庭院。如果这些炸药在封闭的采掘场或洞穴中同时引爆，后果将是毁灭性的。",al={"炸药威力如何","麦格尼王座大厅炸药","炸药危险吗"}},{q="为什么采掘场主管西斯登希望将此事保密？",a="当你归还炸药时，西斯登付给了你报酬，并请求你不要向任何人提及这起小事故。他没有说明原因，但显然，让穴居怪偷走如此大量的炸药是他不愿声张的事情。",al={"为什么要保密","西斯登的秘密","不要提及事故"}},{q="什么是古博拉采掘场？",a="古博拉采掘场是丹莫罗东部著名的矮人挖掘点，负责为王国各地的建筑和工程项目开采石料。其深坑经常需要应对从岩石中钻出的穴居怪等地下害虫。",al={"什么是古博拉","古博拉采掘场","古博拉在哪里"}}},fp="22,286,19.408.0,25.386.0,16.238.1,28.281.0,46.238.0,45.275.0,44.242.0,59.214.0,25.266.0"}
P.entries["quest:95216"] = {n="The New Plague",s="The New Plague 是由 Theodore Griffs 在幽暗城的 Apothecarium 内开展的一项研究工作。Griffs 正在调查关于地面废墟中出现一种致命节肢动物的报告，这种生物的毒液甚至能腐蚀亡灵的血肉，他试图分析并逆向工程这种生物的致命毒素。",h="The New Plague 是由 Theodore Griffs 在幽暗城的 Apothecarium 内开展的一项研究工作。Griffs...",kw={"apothecarium","毒液","洛丹伦废墟","the new plague","theodore griffs","剧毒菌株","幽暗城","witherfang"},ang={["faction:Horde"]="尽管部落将被遗忘者视为东部王国中的战术盟友，但在 Apothecarium 中酝酿的邪恶生物实验往往会引起那些更崇尚荣誉的成员的不安。",["race:Undead"]="皇家药剂师协会不懈地追求能够伤害生者与死者的毒素，以确保被遗忘者的霸权并保护他们初生的国家。"},sec={{t="药剂师的雄心",b="在 Apothecarium 阴暗潮湿的深处，皇家药剂师协会不断从艾泽拉斯各地收集剧毒制剂。作为该协会的一名专注研究员，Theodore Griffs 会追踪奇异的野兽和致命的污染物，以推动被遗忘者炼金术的创新。在听到有毒生物在上方破碎的石块间潜行的传闻后，Griffs 派遣冒险者在机会溜走之前去获取一个可用的样本。"},{t="一种消融血肉的毒素",b="该研究的目标是 Witherfang，这是一种潜伏在洛丹伦废墟地表的有毒节肢动物。它的毒液拥有一种罕见而可怕的特性，不仅能分解活体组织，还能分解死亡并经过防腐处理的血肉。对于一位致力于完善生物战并保卫被遗忘者王国的药剂师来说，揭开这种毒素如何绕过亡灵抗性的秘密，具有极其宝贵的化学研究价值。"},{t="逆向工程体液",b="虽然冒险者在消灭 Witherfang 而不是活捉它时，Griffs 表现出了沮丧，但收集到的毒液样本仍提供了足够的分析材料。通过分解这种生物的体液，这位药剂师打算逆向工程出该毒液的致病机理，确保即使是一只被压碎的节肢动物也能为幽暗城日益增长的化学实力做出贡献。"}},faq={{q="Theodore Griffs 是谁？",a="Theodore Griffs 是一位在幽暗城的 Apothecarium 工作的药剂师研究员。他调查强效毒素和奇异标本，为被遗忘者合成化合物，对任何无法欣赏这种精妙炼金工艺的人表现得漠不关心。",al={"谁发布了 the new plague","theodore griffs","theodore griffs 是谁"}},{q="Witherfang 是什么？",a="Witherfang 是一种致命的有毒节肢动物，潜伏在幽暗城上方的洛丹伦废墟中。它会产生一种极具腐蚀性的毒素，甚至能够溶解坚韧的亡灵血肉。",al={"witherfang 是什么","witherfang 在哪里","洛丹伦废墟的节肢动物"}},{q="为什么 Theodore Griffs 想要 Witherfang 的毒液？",a="Theodore Griffs 试图研究 Witherfang 的毒液，以确定其毒素如何侵蚀亡灵血肉，并希望将该物质逆向工程，开发成被遗忘者炼金武器库中的强效菌株。",al={"theodore 想要 witherfang 做什么","为什么收集剧毒菌株"}},{q="为什么 Theodore Griffs 在你回来时感到生气？",a="Theodore Griffs 本希望标本能保持完整或被小心采集，而不是直接被杀死。虽然他对 Witherfang 被杀感到恼火，但他还是设法从残骸中回收了足够的残留毒液来研究其特性。",al={"为什么 theodore 很生气","我毁掉样本了吗"}},{q="Apothecarium 的目的是什么？",a="Apothecarium 是皇家药剂师协会在洛丹伦之下的研究中心。它被描述为幽暗城最重要的区域，致力于测试剧毒菌株、调制炼金武器以及对奇异生物进行实验。",al={"apothecarium 的目的","为什么 apothecarium 很重要"}},{q="Theodore 认为剧毒菌株最好的传播方式是什么？",a="根据 Theodore Griffs 的说法，剧毒传播最有效且可靠的途径始终是直接注入血液。",al={"毒液是如何传播的","传播方式"}}},fp="14,287,25.429.0,24.413.0,29.391.1,23.272.0,19.195.0,49.203.0,45.240.0,40.261.0,64.151.0"}
P.entries["quest:95217"] = {n="The Quarry's Smith",s="The Quarry's Smith 是一项由弗拉斯·多克纳提供的安排，他是一位驻扎在采掘场营地的工匠。由于预期的补给迟迟未到，这位铁匠不得不求助于过往的旅行者，收集生金属和结实的皮革来进行必要的营地维修。作为交换，多克纳会向有志于金属加工的人传授实用的锻造技巧。",h="The Quarry's Smith...",kw={"锻造","铜锭","丹莫罗","矮人","弗拉斯·多克纳","古博拉采掘场","铁炉堡","the quarry's smith","坚韧的野猪皮"},ang={["faction:Alliance"]="协助多克纳可以确保这个偏远的矮人采掘场保持运作，从而加强雪山高地当地的基础设施和装备准备状况。",["profession:Blacksmithing"]="弗拉斯·多克纳担任学徒铁匠的实地导师，他将自己来之不易的锻造技巧传授给任何愿意提供保持铁砧炽热所需的生金属和皮革的人。",["profession:Mining"]="在周边矿点工作的矿工会发现他们的熔炼铜锭在当地有直接的消费者，将原材料矿石转化为实用的训练和营地维修。",["race:Dwarf"]="古博拉采掘场代表了铜须氏族在丹莫罗的企业和工业，即使在补给车队延误时，矮人的决心也能让熔炉保持燃烧。"},sec={{t="采掘场的物资短缺",b="在活跃的挖掘现场，生活需要不断的维护，从磨快镐头和更换磨损的支架，到加固营地装备，无所不包。当重要的补给品未能按时送达时，日常工作就会陷入停滞。由于主要贸易路线上的物资供应中断，现场的工匠们被迫随机应变，寻求过往冒险者的帮助以维持营地运作。弗拉斯·多克纳在这些持续的延误中坚持锻造，他依靠那些愿意搜集基础金属和兽皮的人，而不是坐等可能遥遥无期的运输马车。"},{t="学徒的交易",b="传统的矮人锻造公会重视纪律和严密守护的方法，很少将行业秘密传授给随意的流浪者。然而，多克纳在当地的需求与正式的公会礼仪之间取得了平衡。面对修补工具和营地装备所急需的铜和耐用皮革的短缺，他提供了一项务实的交易：将原材料直接送到他的铁砧前，他就会向你传授他个人的锻造技巧。这是一场源于边境需求的互利交易，用宝贵的职业知识换取了即时的生存和维护。"}},faq={{q="弗拉斯·多克纳是谁？",a="弗拉斯·多克纳是一位驻扎在采掘场营地的经验丰富的铁匠，负责维护现场工人的工具、结构配件和设备。当物流延误切断了他的正常补给线时，他亲自出马，招募过往的冒险者来获取他急需的原材料。",al={"弗拉斯·多克纳背景故事","采掘场铁匠是谁","采掘场铁匠"}},{q="为什么采掘场需要铜锭和野猪皮？",a="挖掘和营地维护消耗了大量的坚固材料。铜是一种易于获取、延展性好的金属，适合锻造替换配件、钉子、紧固件，以及为损坏的工具加固箍带。坚韧的野猪皮提供了必要的弹性皮革，用于制作风箱、工具裹布、绑带和防护围裙，以抵御采掘场日常工作中严酷的火花和沉重的研磨。",al={"为什么需要铜锭和野猪皮","采掘场铁匠所需的材料","采掘场维修材料"}},{q="为什么补给品运输会迟到？",a="虽然弗拉斯·多克纳没有详细说明延误的具体原因，但横跨雪峰和山隘的陆路补给路线经常受到严酷暴风雪、四处游荡的野生动物以及敌对的穴居人或强盗伏击的困扰。每当运输马车延误时，偏远的采矿营地和采掘场往往是最先感受到压力的定居点。",al={"补给品运输延迟","补给品出了什么事","为什么补给延迟"}},{q="弗拉斯·多克纳用什么来交换这些材料？",a="弗拉斯·多克纳不仅仅提供金钱，他还承诺将个人的锻造技巧传授给任何为他收集所需补给的人。对于有抱负的工匠来说，直接向驻扎在实地的老练工匠学习，能提供关于金属加工和设备维护的实用见解，而这是正规的城市公会大厅很少向新手传授的。",al={"采掘场铁匠奖励背景","弗拉斯教什么","弗拉斯的锻造技巧"}},{q="这个采掘场位于哪里？",a="弗拉斯·多克纳在丹莫罗的古博拉采掘场工作，这是一个坐落在卡拉诺斯以南雪山脚下的矮人挖掘场。采掘场面临着严酷的冬季天气和具有攻击性的地下穴居人的持续作业压力，它们经常骚扰矿工并扰乱从铁炉堡出发的贸易车队。",al={"这是哪个采掘场","弗拉斯·多克纳在哪里","采掘场铁匠位置"}},{q="弗拉斯·多克纳隶属于铁炉堡吗？",a="是的，弗拉斯·多克纳和采掘场营地在铜须氏族和铁炉堡王国的领地内运作。从丹莫罗的山脉中开采石料和提取矿石对于矮人王国的建筑项目和防御工事至关重要，这使得像多克纳这样的当地铁匠成为铁炉堡工业力量不可或缺的一部分。",al={"弗拉斯·多克纳与铁炉堡","采掘场属于铁炉堡吗","采掘场矮人效忠对象"}}},fp="18,369,23.580.0,23.599.0,20.349.0,52.409.0,32.369.0,59.358.0,29.326.0,42.360.0"}
P.entries["quest:95250"] = {n="Abominable Creatures",s="Abominable Creatures 是一个任务，由 Captain Truman 布置，他是一名坚守在洛丹伦废墟 (Ruins of Lordaeron) 郊外，绝望地等待着援军的人类忠诚派。Truman 坚信他的指挥官——一位受人尊敬的 Grand Marshal——仍在附近的洛丹伦废墟中英勇奋战，因此请求一位有能力的 The Adventurer 去寻找他。这项任务揭示了该王国失踪的守卫者们那悲惨的命运，以及在幸存的忠诚派之间阴燃的痛苦敌意。",h="Abominable Creatures 是一个任务，由 Captain Truman 布置，他是一名坚守在洛丹伦废墟 (Ruins of Lordaeron) 郊外，绝望地等待着援军的人类忠诚派。Truman...",kw={"abominable creatures","truman 队长","大元帅","男爵的徽记","洛丹伦","洛丹伦废墟","男爵","洛丹伦真正的子民"},ang={["faction:Alliance"]="该任务突显了联盟阵营的残余势力在北洛丹伦的枯萎废墟中试图行动时所面临的危险与孤立困境。它强调了残留的忠诚派分遣队是如何在希望渺茫以及对抗压倒性怪物所带来的心理重负下苦苦挣扎的。",["race:Human"]="人类 The Adventurer 目睹了洛丹伦沦陷领导层那令人心碎的命运，即便是受人尊敬的 Grand Marshal 也被转化成了恐怖的亡灵怪物。Captain Truman 的痛苦和民族主义狂热反映了人类幸存者为收复祖国而承受的沉重创伤。",["race:Undead"]="对于被遗忘者来说，男爵那怪诞的转化是一个严峻的提醒，它展示了天灾军团如何将洛丹伦最优秀的守卫者残忍地扭曲成可怕的憎恶。Captain Truman 发誓要清除废墟中所有的野兽和亡灵，这反映了活着的忠诚派对幽暗城人民所怀有的持续敌意。"},sec={{t="绝望的守望",b="Captain Truman 坚守在自己的岗位上，焦虑地等待着迟迟未到的援军来支持洛丹伦的防守。他对自己上级——一位被他描述为身材高大、像雕像般英雄的知名 Grand Marshal——的武艺充满信心。在接到指挥官冲入战场而自己必须坚守阵地的命令后，Truman 始终恪尽职守。由于对局外人持有深切怀疑，并公开鄙视那些他认为低劣的种族，这位队长拒绝信任当地的非正规军。当一位有能力的旅行者接近时，Truman 抓住了寻求援助的机会，恳求对方冒险进入废墟领地，去查看他主人的安危并评估战斗情况。"},{t="洛丹伦废墟",b="这次搜寻直接将 The Adventurer 指引向危险的洛丹伦废墟，这座在第三次战争中沦陷于天灾军团的破碎首都。尽管 Captain Truman 期望他那光荣的领袖能在死者中凯旋，但在这片枯萎的城市中，现实却要残酷得多。废墟中到处都是恐怖之物、亡灵残余以及在破碎的石制广场上徘徊的憎恶。穿过这些荒废的街道，需要面对那些进入城市的守卫者们所遭遇的残酷真相。旅行者们并没有发现一位完美的骑士在坚守阵线，而是发现指挥官在占据庭院的怪物群中遭遇了悲惨、扭曲的终结。"},{t="恐怖的真相",b="在找到失踪的指挥官（被称为男爵）后，The Adventurer 有了一个恐怖的发现：那位曾经像雕像般英俊的英雄已经被转化成了一个怪诞的亡灵怪物。完成这项严峻的任务需要击杀该生物，并将男爵的徽记带回给 Captain Truman。当看到他前任领主的断头时，Truman 的反应是震惊、恐惧和极度的厌恶。无法接受指挥官那可怕的命运，这位队长在痛苦中爆发，指责 The Adventurer 与怪物勾结，并发誓洛丹伦真正的子民终有一天会收复他们的土地并清除所有的野兽。"}},faq={{q="谁布置了 Abominable Creatures 任务？",a="该任务由 Captain Truman 提供，他是一名驻扎在已沦陷王国周边地区的人类忠诚派。Truman 在焦虑地坚守岗位、等待援军的同时，急切地寻求关于他指挥官的消息，那位 Grand Marshal 曾冲入了附近的洛丹伦废墟。",al={"谁发布了 abominable creatures","abominable creatures 任务发布者","如何开始 abominable creatures"}},{q="Abominable Creatures 任务发生在什么地方？",a="该任务指引 The Adventurer 进入洛丹伦废墟，这是被天灾军团的恐怖之物和亡灵残余所淹没的破碎首都。Captain Truman 在这片枯萎的首都外保持着哨位，请求勇敢的旅行者直接冒险进入危险的废墟，以定位他失踪的长官。",al={"abominable creatures 位置","abominable creatures 在哪里完成","abominable creatures 区域"}},{q="Captain Truman 的长官是谁？",a="Captain Truman 将他的长官称为 Grand Marshal，赞扬他是位高大、像雕像一样的军事英雄。然而，任务目标将这位失踪的贵族称为“男爵”，表明他是一位领导王国防御的高级贵族和军事指挥官。",al={"truman 的指挥官是谁","truman 的大元帅身份","男爵是谁"}},{q="洛丹伦废墟里的 Grand Marshal 发生了什么？",a="Grand Marshal 并没有胜利地坚守下来，而是在洛丹伦废墟中被杀，并被转化为一个可怕的亡灵怪物。当 The Adventurer 找到他时，发现他已经成了被称为“男爵”的憎恶，被迫将其消灭并带回男爵的徽记。",al={"男爵发生了什么","大元帅的命运","大元帅死了吗"}},{q="为什么 Captain Truman 在你完成任务时会生气？",a="Captain Truman 期望他那像雕像般的指挥官能活着并获得胜利。当看到男爵的徽记时，Truman 被恐惧和厌恶所淹没，愤怒地指责 The Adventurer 在开恶毒的玩笑并与邪恶的野兽勾结。",al={"为什么 truman 会生气","truman 对 abominable creatures 的反应","为什么 truman 对你大喊大叫"}},{q="Captain Truman 所说的“洛丹伦真正的子民”是什么意思？",a="Captain Truman 用这个词来描述那些致力于收复破碎家园的狂热人类爱国者。他的话表达了一种激烈、不宽容的愿景，即合法的人类幸存者将把王国从所有的亡灵、野兽以及任何被视为与它们勾结的人手中清除出去。",al={"洛丹伦真正的子民是什么意思","谁是洛丹伦真正的子民","truman 真正的子民"}},{q="为什么 Captain Truman 拒绝信任“混血儿”？",a="Captain Truman 对非人类种族和非正规盟友表现出极大的蔑视，将他们斥为不可信的混血儿和污秽之徒。他强烈的仇外心理使他除了那些他认为代表了王国的合格人员外，拒绝向任何人吐露心声。",al={"truman 混血儿","为什么 truman 队长有种族偏见","truman 的仇外心理"}}},fp="20,456,17.710.0,22.711.0,23.661.1,41.290.0,53.295.0,31.285.0,61.280.0,61.274.0,62.286.0,54.258.0"}
P.entries["quest:953"] = {n="亚米萨兰的毁灭",s="哨兵坦莎·月刃委托冒险者去探索黑海岸那令人毛骨悚然的亚米萨兰废墟，以破译古代石板。这些铭文记录了天崩地裂期间降临在那座上层精灵城市身上的悲剧与毁灭。所收集的知识是提供给奥伯丁的古籍学会的，旨在恢复在上古之战中大部分失传的历史。",h="哨兵坦莎·月刃委托冒险者去探索黑海岸那令人毛骨悚然的亚米萨兰废墟，以破译古代石板。这些铭文记录了天崩地裂期间降临在那座上层精灵城市身上的悲剧与毁灭。所收集的知识是提供给奥伯丁的古籍学会的，旨在恢复在上古之战中大部分失传的...",kw={"亚米萨兰","奥伯丁","艾萨拉","古籍学会","黑海岸","上层精灵","天崩地裂","石板","坦莎·月刃"},ang={["class:Mage"]="这些石板让人清醒地看到了天崩地裂前精灵法术的造诣巅峰，以及当这种力量失控时所带来的可怕毁灭。",["faction:Alliance"]="协助哨兵们守护黑海岸的历史，有助于为在卡利姆多领导联盟的暗夜精灵领袖们保存重要的知识。",["race:NightElf"]="亚米萨兰的废墟是一个严酷的警示，提醒人们注意你们的祖先在艾萨拉女王统治下的傲慢，以及不受节制的奥术魔法所带来的灾难性后果。"},sec={{t="上层精灵的回响",b="在海岸破碎成如今雾气弥漫的黑海岸之前很久，亚米萨兰曾是一个繁荣的定居点，艾萨拉女王的精英法师们在此研习强大的奥术魔法。一万年前永恒之井的灾难性毁灭之后，这座城市沦为破碎的大理石和开裂的石柱。今天，它仍然徘徊着那些在黄金时代分崩离析时死去、因痛苦而不得安息的上层精灵灵魂。"},{t="发掘失落的编年史",b="由于上古之战将暗夜精灵文明推向了混乱的求生边缘，在天崩地裂后，几乎没有文字记录完整保存下来。哨兵坦莎·月刃曾试图亲自勘察这些废墟，并发现了两块巨大的刻字石板——《亚米萨兰之歌》和《亚米萨兰的陨落》——但在幽灵般的上层精灵鬼魂迫使她撤退之前，她只来得及看这些。找回这些记载，能确保有关那场远古灾难的历史真相传达给奥伯丁古籍学会的学者们。"}},faq={{q="亚米萨兰是什么？",a="亚米萨兰是位于黑海岸中部的一处古代暗夜精灵废墟。一万年前，这里是一座城市，艾萨拉女王的上层精灵贵族们在此公开施展和研习宏大的奥术魔法，直到它在天崩地裂中陨落。",al={"亚米萨兰背景知识","亚米萨兰是什么","谁生活在亚米萨兰"}},{q="为什么亚米萨兰会有鬼魂？",a="在废墟中游荡的那些不得安息的鬼魂，是曾经生活并死在那里的上层精灵的灵魂。他们被那场突然而剧烈的、摧毁了永恒之井并分裂了卡利姆多的灾难所困，这些灵魂在永恒的折磨中被束缚在废墟里。",al={"为什么亚米萨兰会有鬼魂","亚米萨兰鬼魂","不得安息的上层精灵"}},{q="哨兵坦莎·月刃是谁？",a="哨兵坦莎·月刃是一名驻扎在黑海岸道路旁的暗夜精灵哨兵。她的任务是勘察古代遗址，并为奥伯丁的古籍学会寻回失落的历史记录。",al={"坦莎·月刃","谁发布了亚米萨兰的陨落任务"}},{q="为什么古籍学会想要解读这些石板？",a="永恒之井的毁灭使卡利姆多陷入了巨大的动荡，无数图书馆和纪念碑被夷为平地。由于上古之战后留下的文字记录寥寥无几，这些石板提供了从上层精灵视角出发的、关于天崩地裂的珍贵第一手资料。",al={"为什么要阅读石板","古籍学会石板","亚米萨兰之歌含义"}},{q="石板在什么位置？",a="两块巨大的石板——《亚米萨兰之歌》和《亚米萨兰的陨落》——刻在亚米萨兰废墟庭院中的耸立石碑上，周围游荡着该城昔日居民的鬼魂。",al={"亚米萨兰石板位置","石板位置","如何阅读亚米萨兰石板"}},{q="天崩地裂期间亚米萨兰的上层精灵遭遇了什么？",a="当永恒之井在上古之战的高潮中内爆时，巨大的震动和奥术反噬将卡利姆多撕裂。亚米萨兰在毁灭中坍塌，埋葬了它的居民，留下了在废墟中徘徊的鬼魂。",al={"亚米萨兰是如何陨落的","亚米萨兰毁灭"}}},fx={["4f4506ec"]={q="哨兵坦莎·月刃为什么要做这件事？",al={"坦莎·月刃的动机","坦莎为什么需要这个","为什么研究亚米萨兰石板"}},["2329a43d"]={q="哨兵坦莎·月刃为什么需要你的帮助？",al={"坦莎为什么不能读石板","坦莎为什么需要我","坦莎为什么不亲自去"}}},fp="22,378,23.450.0,26.515.0,19.237.0,35.260.0,32.210.0,56.292.0,30.233.0,66.238.0"}
P.entries["quest:95314"] = {n="That Shadowvale Green Elixir",s="布瑞尔的卡罗莱·安尼斯正在寻求从影谷的废弃定居点中抢救物资，该定居点位于深藏于耳语森林的幽僻处。在洛丹伦王国覆灭之前，这个村庄就以蒸馏一种名为耳语药剂的特殊本地草药而闻名——即使在洛丹伦被列为禁品后，它在黑市上依然备受追捧。",h="布瑞尔的卡罗莱·安尼斯正在寻求从影谷的废弃定居点中抢救物资，该定居点位于深藏于耳语森林的幽僻处。在洛丹伦王国覆灭之前，这个村庄就以蒸馏一种名为耳语药剂的特殊本地草药而闻名——即使在洛丹伦被列为禁品后，它在黑市上依然备受追...",kw={"炼金师","布瑞尔","卡罗莱·安尼斯","毒药","影谷","提瑞斯法","耳语药剂","耳语森林"},ang={["class:Rogue"]="长期以来，耳语药剂一直受到那些在洛丹伦前任治安官眼皮底下活动的非法用毒者和恶棍的珍视。",["profession:Herbalism"]="这种药剂的效力来源于那些只在幽僻的耳语森林那阴森的树冠下茁壮生长的独特草药。",["race:Undead"]="对于被遗忘者来说，回收洛丹伦被遗忘的蒸馏品，既能带来可观的商业利润，也为幽暗城初期的炼金实验提供了素材。"},sec={{t="被禁的佳酿",b="在第三次战争和天灾军团入侵很久之前，影谷那离群索居的居民们酿造了一种独特的混合物，被称为耳语药剂。这种药剂由提瑞斯法林地独有的稀有草药蒸馏而成，在北洛丹伦声名狼藉。尽管在王都已被正式取缔，但其不同寻常的特性使它一直受到神秘主义者、用毒者以及愿意违抗王室法令的炼金师们的追捧。"},{t="耳语森林的废墟",b="影谷隐藏在西提瑞斯法的耳语森林深处。村民们历来排外且多疑，极少欢迎外来者。天灾入侵后，该定居点沦为废墟，但那些陈年的绿色药剂遗存仍埋在瓦砾之中。卡罗莱·安尼斯在布瑞尔经营生意，利用黑市持续的需求，雇佣那些愿意冒险进入森林那令人不安的寂静中的冒险者。"},{t="耳语诅咒",b="虽然卡罗莱倾向于将这些传闻视为单纯的迷信，但耳语森林确实名声不佳。当地传说，森林的土壤和根系本身就受到古老诅咒的侵蚀，这种诅咒直接渗透进了被影谷酿造师们采集的植物中。无论是什么样的邪恶力量在废弃的村落中徘徊，都未能浇灭远方买家对这些瓶装遗存的渴望。"}},faq={{q="什么是影谷？",a="影谷是一个隐藏在西提瑞斯法林地的耳语森林中的幽僻村庄。在天灾军团席卷该地区之前，这里的人们是孤立主义者，主要以从当地野外蒸馏稀有混合物而闻名。",al={"影谷在哪里","谁住在影谷","影谷村"}},{q="什么是耳语药剂？",a="这是一种强效的绿色药剂，由提瑞斯法林地发现的独特草药酿制而成。该饮料深受神秘主义者、用毒者和炼金师的青睐，在洛丹伦覆灭前于王都被列为禁品。",al={"药剂有什么用","影谷绿色药剂背景故事","耳语药剂"}},{q="卡罗莱·安尼斯是谁？",a="卡罗莱·安尼斯是一位足智多谋的被遗忘者，居住在布瑞尔。她充当珍贵和违禁物品的中间商，获取像影谷药剂这样的非法试剂，并将其卖给王国各地的买家。",al={"卡罗莱·安尼斯","谁发布影谷绿色药剂任务","布瑞尔任务发布者"}},{q="为什么这种药剂在王都被禁？",a="原因未明。卡罗莱只说这种药剂在城里被禁，且尽管如此，炼金师、神秘主义者和用毒者依然在寻求它。有些人认为耳语森林受到诅咒，而从其根系中蒸馏出的药剂带有同样的诅咒，但卡罗莱将此视为迷信，从未将其与禁令联系起来。",al={"为什么耳语药剂是非法的","这种药剂有毒吗"}},{q="为什么耳语森林被认为很危险？",a="丧钟镇以西那片幽僻的树林被普遍认为阴森且受到诅咒。那些冒险进入那里的人谈论着深重的邪恶和奇怪的林地现象，传言称这些现象污染了从土壤中生长出来的草药。",al={"耳语森林受诅咒了吗","耳语森林背景故事"}},{q="谁想要购买这种药剂？",a="根据卡罗莱·安尼斯的说法，有许多买家渴望获得幸存的战前药剂瓶，但她没有透露具体是谁。",al={"谁购买这种药剂","卡罗莱·安尼斯的买家"}}},fx={["4d019fa8"]={q="卡罗莱·安尼斯为什么要收集低语精华？",a="卡罗莱·安尼斯在布瑞尔经营稀有货品收购，非法酿酒的需求始终没有真正消退。许多热切的买家催她供货，因此遗迹中只要还有完好的酒瓶，都能带来可观利润。",al={"卡罗莱为什么想要精华","卡罗莱·安尼斯的动机","为什么收集低语精华"}}},fp="28,340,13.457.0,30.465.0,20.427.1,19.249.0,26.193.0,21.218.0,46.329.0,50.219.0,39.131.0"}
P.entries["quest:95328"] = {n="Whispering Horror Residue",s="Whispering Horror Residue是人们从耳语森林下方发现的一种奇异野兽那蠕动的残骸。勇敢的冒险者们收集了这些被虚空侵蚀的遗骸，并将它们带给幽暗城War Quarter的兰克斯特神父，用于进行暗影研究。",h="Whispering Horror Residue是人们从耳语森林下方发现的一种奇异野兽那蠕动的残骸。勇敢的冒险者们收集了这些被虚空侵蚀的遗骸，并将它们带给幽暗城War Quarter的兰克斯特神父，用于进行暗影研究。",kw={"兰克斯特神父","暗影","提瑞斯法","幽暗城","虚空","war quarter","耳语森林","whispering horror residue"},ang={["class:Priest"]="像兰克斯特神父这样的被遗忘者暗影牧师对虚空样本有着浓厚的学术和神学兴趣，他们将这种奇异的位面残骸视为研究对象，而非仅仅是畸形怪物。",["faction:Horde"]="效忠于部落的冒险者从提瑞斯法林地隐秘的荒野中回收不安的样本，为首都废墟下的研究工作提供燃料。",["race:Undead"]="幽暗城的被遗忘者积极研究整个洛丹伦的禁忌魔法和非自然腐蚀，试图利用黑暗现象来巩固他们在这个王国岌岌可危的统治。"},sec={{t="不安的收获",b="Whispering Horror Residue是人们从栖息在耳语森林下方的一只被击败的野兽身上刮下的奇怪且蠕动的残骸。资源丰富的冒险者们并没有抛弃这种极不自然的猎奇之物，而是收集了这些还在抽搐的物质，希望幽暗城的学者们能让它们发挥作用。"},{t="暗影研究",b="这种生物的残骸在位于幽暗城War Quarter的兰克斯特神父那里找到了渴望的研究者。兰克斯特指出，耳语森林长期以来一直受到虚空的侵蚀，他很乐意借此机会在钻研暗影奥秘的同时，对这些黑暗腐蚀的物理残骸进行检查。"}},faq={{q="什么是Whispering Horror Residue？",a="Whispering Horror Residue由从耳语森林下方击败的奇异野兽身上采集到的蠕动躯体残骸组成。尽管其本质令人不安，但暗影魔法学者发现它在奥术和神秘学研究中极具价值。",al={"什么是残骸","什么是whispering horror residue","残骸物品"}},{q="谁需要Whispering Horror Residue？",a="这些残骸会被送到位于幽暗城War Quarter的被遗忘者兰克斯特神父手中。他很乐意借此机会探索暗影和虚空侵蚀现象的奥秘。",al={"谁接收残骸","谁是兰克斯特神父","在哪里上交残骸"}},{q="这个样本是从哪里来的？",a="该样本源自耳语森林下方，这是一片位于提瑞斯法林地丧钟镇以西的阴森林地。正如兰克斯特神父所观察到的那样，这片邪恶区域众所周知受到了虚空的侵蚀。",al={"怪物残骸从何而来","耳语森林背景故事","耳语森林下方"}},{q="为什么兰克斯特神父想要这些残骸？",a="兰克斯特神父致力于研究暗影和虚空的奥秘。对于那些探索禁忌艺术的被遗忘者从业者来说，受虚空污染的生物残骸能提供罕见的见解和研究材料。",al={"为什么兰克斯特需要这个","幽暗城暗影研究","为什么要研究残骸"}},{q="在哪里可以找到兰克斯特神父？",a="兰克斯特神父居住在幽暗城的War Quarter。War Quarter是洛丹伦废墟之下被遗忘者战士、学者和军事策划者们繁忙的聚集中心。",al={"war quarter在哪里","兰克斯特位于何处","幽暗城兰克斯特位置"}},{q="耳语森林受到虚空的侵蚀了吗？",a="在提瑞斯法的当地人眼中，耳语森林长期以来一直有着邪恶的名声。兰克斯特神父指出，这片邪恶的林地及其地下的空间受到虚空的侵蚀，这早已不是什么秘密。",al={"耳语森林受到诅咒了吗","耳语森林虚空腐蚀","什么侵蚀了耳语森林"}}},fp="25,256,21.318.0,17.307.0,38.242.0,40.195.0,34.206.0,43.211.0,36.195.0,45.212.0"}
P.entries["quest:95349"] = {n="The Earthen Ring",s="这段旅程标志着塑风者从Zephras抵达艾泽拉斯，他们作为先遣先锋队，此前因Valanaar的邪教活动而延误。旅客们在旅店外登上一艘破天者飞船，随后降落在莫高雷，并会见Alaana Stormwalker，开始适应这个广阔而危险的新世界。",h="这段旅程标志着塑风者从Zephras抵达艾泽拉斯，他们作为先遣先锋队，此前因Valanaar的邪教活动而延误。旅客们在旅店外登上一艘破天者飞船，随后降落在莫高雷，并会见Alaana...",kw={"alaana stormwalker","banu-alah","邪教","莫高雷","破天者","大地之环","瓦拉纳尔","塑风者","zephras"},ang={["class:Shaman"]="塑风者和萨满对元素有着深刻的崇敬，依赖风的指引来完成他们的空中穿越。以大地之环的名义抵达，将他们直接与正在莫高雷扎根的元素传统联系在了一起。",["race:Skyborne"]="对于离开Valanaar的空降冒险者来说，这段旅程标志着他们作为先遣先锋队历史性地抵达艾泽拉斯。抛开家乡的邪教麻烦，他们迈出了踏上莫高雷草海平原的第一步。",["race:Tauren"]="作为莫高雷的原住民看护者，牛头人目睹了来自Zephras的新旅客降临在他们祖先的平原上。欢迎这些乘风而来的访客，为他们与这些正在这片土地上建立据点的盟友提供了早期的联系。"},sec={{t="离开Valanaar",b="前往艾泽拉斯的旅客由于最近Valanaar邪教活动的干扰，必须调整计划。尽管高级领导人留守在旅店以处理紧急事务并平息邪教威胁，但一支小型的塑风者先遣队已被先行派遣。这些先驱者前往旅店外的码头，登上了一艘飞向天空的破天者飞船。虽然他们的指挥官承诺很快会加入他们，但最初的探险完全由这支先头部队承担，他们被派遣到前方，以便在大部队到来前建立据点。"},{t="抵达莫高雷",b="在降落在莫高雷的草海平原后，来自Zephras的冒险者们受到了Alaana Stormwalker的欢迎。在艾泽拉斯立足需要时间和谨慎的努力，新来者被鼓励去侦察周围的领土，以适应新的环境。尽管风向对此次远征有利，但艾泽拉斯依然是一个陌生且危险的领域。在来自Valanaar的其余旅客到达并加入之前，熟悉当地的地形、野生动物和邻近居民是至关重要的第一步。"}},faq={{q="为什么塑风者要前往艾泽拉斯？",a="一支塑风者先遣队被先行派遣到艾泽拉斯以建立据点，而他们的领导人则留在了Valanaar。最近涉及当地邪教的麻烦扰乱了最初的旅行计划，延误了其余队员的行程。因此，这支先头部队独自前往，以完成登陆并确保建立据点，直到后续增援部队能够跟上。",al={"为什么去艾泽拉斯","塑风者任务","为什么塑风者在莫高雷"}},{q="Alaana Stormwalker是谁？",a="Alaana Stormwalker是等待迎接抵达莫高雷的塑风者的联络人。她欢迎来自Zephras的旅客，并指出在这片新土地上建立稳固的据点需要时间。在准备工作进行的同时，她建议刚抵达的冒险者探索周边地区，并为艾泽拉斯的危险做好准备。",al={"alaana是谁","alaana stormwalker的角色","alaana stormwalker在哪里"}},{q="为什么主要行程被延误了？",a="从Valanaar出发的主航程由于最近涉及当地邪教的麻烦事件而被推迟。处理这些邪教带来的并发症迫使远征队领导人留在旅店以完成他们的事务。为了不完全中止任务，他们派遣了一小队塑风者搭乘破天者飞船前往艾泽拉斯带路。",al={"为什么延误","什么邪教延误了行程","为什么留在valanaar"}},{q="旅客如何从Valanaar前往莫高雷？",a="旅客们通过搭乘停靠在Valanaar旅店外的一艘破天者飞船进行旅行。这艘船载着先遣队穿过天空，飞往莫高雷的平原，作为在初始远征期间连接Zephras与艾泽拉斯大陆的主要交通工具。",al={"如何到达莫高雷","船在哪里","如何前往艾泽拉斯"}},{q="Zephras是什么？",a="Zephras是搭乘破天者飞船抵达的冒险者们的家乡或起源地。当旅客到达莫高雷时，Alaana Stormwalker认出他们是来自Zephras的新人，并指出有利的风向引导了他们进入艾泽拉斯这片陌生而危险的领土。",al={"zephras在哪里","zephras是什么","zephras背景故事"}},{q="冒险者抵达莫高雷后应该做什么？",a="新抵达的冒险者被鼓励去侦察和探索莫高雷的周边土地。因为建立定居点需要时间，熟悉附近的地形、生物和当地威胁是为在这个令人兴奋却又危险的新世界中航行所做的必要准备。",al={"在莫高雷做什么","抵达后的下一步行动","下一步做什么"}}},fp="16,317,23.583.0,18.573.0,45.356.0,26.381.0,35.358.0,50.281.0,16.299.0,52.302.0"}
P.entries["quest:95350"] = {n="Welcome to Azeroth",s="“Welcome to Azeroth”是一个引导任务，派遣一名旅行者代表塑风者从雷霆崖前往奥格瑞玛。在大地之环精神纽带的指引下，使者会见萨尔大酋长，旨在与部落建立生存纽带和盟友关系。",h="“Welcome to Azeroth”是一个引导任务，派遣一名旅行者代表塑风者从雷霆崖前往奥格瑞玛。在大地之环精神纽带的指引下，使者会见萨尔大酋长，旨在与部落建立生存纽带和盟友关系。",kw={"大地之环","部落","奥格瑞玛","萨尔","雷霆崖","智慧谷","welcome to azeroth","塑风者"},ang={["class:Shaman"]="在大地之环的指引和风的祝福下，这段旅程将精神同胞直接与智慧谷的萨满领导核心连接起来。",["faction:Horde"]="这次外交任务使与部落的关系正式化，将新来者直接介绍给大酋长萨尔，使他们成为在卡利姆多生存的关键盟友。",["race:Skyborne"]="离开高空前往下方的地表世界，天生的塑风者向雷霆崖和奥格瑞玛伸出援手，以巩固他们在新盟友中的地位。"},sec={{t="更广阔世界中的盟友",b="踏入卡利姆多广袤的土地，新来者很快就会发现生存取决于手足情谊。塑风者将目光投向了孤立的起源之外，看向下方行走的人民，他们认识到孤立无法抵御艾泽拉斯的威胁。通过向邻近的牛头人城市雷霆崖伸出援手，并望向东部的兽人堡垒，他们寻求坚定的伙伴，共同在荒野中闯荡。"},{t="觐见大酋长",b="这趟旅程将使者带到雷霆崖高耸的塔楼，然后指引他们穿过贫瘠之地前往部落强大的首都奥格瑞玛。在宁静的智慧谷等待着的是大酋长萨尔，他是联盟的核心向导。站在萨尔面前，标志着塑风者正式进入卡利姆多的政治和精神领域，因为共同的目标和对元素的共同尊重而结合在一起。"}},faq={{q="任务“Welcome to Azeroth”的目的是什么？",a="“Welcome to Azeroth”是一个外交引导任务，派遣一名使者代表塑风者在奥格瑞玛会见大酋长萨尔。它是通往更广泛的部落和卡利姆多地表世界的正式介绍。",al={"这个任务是什么","welcome to azeroth任务","welcome to azeroth的目的"}},{q="塑风者是谁？",a="塑风者是一个从高处向地表盟友伸出援手的群体，寻求通过与大地之环和部落的友谊来生存。他们派遣旅行者直接与杜隆塔尔的部落领袖交谈。",al={"塑风者是谁","塑风者是什么"}},{q="为什么你要被派去与萨尔交谈？",a="作为部落的大酋长和受人尊敬的萨满领袖，萨尔在智慧谷统筹联盟的主要盟友关系。与他取得联系可以使塑风者和部落之间的关系正式化。",al={"为什么要拜访萨尔","与奥格瑞玛的萨尔交谈","为什么要前往奥格瑞玛"}},{q="如何从雷霆崖前往奥格瑞玛？",a="旅行者可以从雷霆崖中心栖息地的飞行管理员处起飞，飞越卡利姆多的平原，向东进入奥格瑞玛的峡谷要塞。",al={"如何前往奥格瑞玛","雷霆崖飞行管理员","从雷霆崖前往奥格瑞玛"}},{q="大地之环在这次任务中起什么作用？",a="在这次接触中，大地之环被描述为与部落志同道合的各族联盟保持一致，帮助促进萨满教派与卡利姆多各国之间的纽带。",al={"大地之环在部落的角色","大地之环是部落吗"}},{q="萨尔在奥格瑞玛的什么位置？",a="大酋长萨尔驻扎在智慧谷，那是奥格瑞玛西部一处安静的精神圣地，萨满祭司和部落顾问常在此集会。",al={"萨尔在哪里","智慧谷萨尔位置"}}},fp="18,275,25.456.0,29.431.0,52.238.0,24.215.0,38.218.0,50.177.0,48.190.0,37.159.0"}
P.entries["quest:954"] = {n="巴莎兰",s="盘踞在古老暗夜精灵城市巴莎兰的恶魔萨特和凶残格罗尔不敢靠近一座散发着诡异蓝色光芒的神龛。奥伯丁的长者桑德里斯·风织派遣冒险者前去调查这处未受侵扰的圣所的源头。",h="盘踞在古老暗夜精灵城市巴莎兰的恶魔萨特和凶残格罗尔不敢靠近一座散发着诡异蓝色光芒的神龛。奥伯丁的长者桑德里斯·风织派遣冒险者前去调查这处未受侵扰的圣所的源头。",kw={"阿斯特利安","巴莎兰","蓝色光芒","黑海岸","格罗尔","卡多雷遗迹","萨特","桑德里斯·风织"},ang={["faction:Alliance"]="奥伯丁的斥候依靠联盟的流浪者深入黑海岸的纷争遗迹，在恶魔威胁蔓延到海岸之前将其消灭。",["race:NightElf"]="巴莎兰是一个阴郁的提醒，让人想起在大分裂时期所失去的一切，那里你古老族人的残余阴影仍在孤独地守望，对抗着步步紧逼的恶魔腐化。"},sec={{t="废墟中的信标",b="巴莎兰曾是古老卡多雷帝国的一处辉煌定居点，但如今它那破碎的大理石和杂草丛生的拱门却充斥着恶魔的污染。扭曲的萨特和堕落的格罗尔贪婪地汲取着废墟中残留的魔法能量，它们的恶意与日俱增。然而尽管有这些掠夺者的统治，奥伯丁的桑德里斯·风织还是发现了一个奇特的现象：在废墟西侧的一处悬崖上，一座神龛闪耀着飘渺的蓝色光芒，没有任何恶魔敢靠近。"},{t="受伤的阴影",b="冒着恶魔巡逻队的危险来到高处的神龛，你会发现那蓝光并非自然现象。它源自阿斯特利安，一位在长达几个世纪的孤独守望中坚持至今的古老灵魂。这疲惫的阴影被咆哮的野兽和邪恶的魔物所包围，即使是一位路过的陌生人，对他而言也是从数十年的与世隔绝中获得的片刻慰藉。"}},faq={{q="蓝色光芒在哪里？",a="蓝色光芒在巴莎兰废墟西缘的一处高耸小悬崖上闪耀，就在黑海岸奥伯丁的东面。它位于周围坍塌墙壁的稍高处。",al={"寻找蓝色光芒","阿斯特利安在哪里","巴莎兰神龛位置"}},{q="为什么萨特要避开那座神龛？",a="目前无人知晓。一种奇怪的蓝色光芒笼罩着神龛，而那些盘踞在废墟中的恶魔萨特和格罗尔却不敢靠近。桑德里斯·风织派遣你去寻找这光芒的源头。",al={"为什么恶魔感到恐惧","为什么萨特避之不及"}},{q="谁派遣你进行这项任务？",a="桑德里斯·风织，一位奥伯丁的暗夜精灵德鲁伊和长者。他在观察到东部废墟内不正常的恶魔活动后提供了这个任务。",al={"谁给予任务","任务发布者","桑德里斯·风织的位置"}},{q="巴莎兰是什么？",a="巴莎兰是一处坐落在黑海岸森林中的古老卡多雷遗迹。它在古老的大分裂时期被洗劫，如今已沦为魔法寄生虫、格罗尔和试图蚕食其沉睡的能量之线的萨特的温床。",al={"巴莎兰发生了什么","巴莎兰的历史"}}},fx={["2cba9e48"]={q="索兰·织风为什么要我调查巴莎兰？",a="索兰·织风越来越担忧巴莎兰的古代遗迹。受到腐化的精灵和萨特成群出没，利用残存的奥术能量增强恶魔之力。然而在这片受侵扰的土地上，有一座笼罩着奇异蓝色光环的神龛，竟完全未受恶魔侵扰。索兰需要弄清是什么力量将它们拒之门外，以及这股力量能否帮助抵御蔓延至黑海岸的腐化。",al={"为什么调查巴莎兰","索兰的动机","为什么派我去巴莎兰"}}},fp="11,275,21.493.0,17.354.1,31.197.0,35.204.0,28.159.0,20.223.0"}
P.entries["quest:95494"] = {n="Bruised Pride and Lion Hides",s="“Bruised Pride and Lion Hides”是一项任务，旨在帮助一位受伤的猎人或商人，他们需要生狮皮来满足与当地制革匠的贸易协议。由于受伤无法安全进行狩猎，他们只能依靠路过的冒险者来递送材料，以维持自己完美的职业记录。",h="“Bruised Pride and Lion...",kw={"bruised pride and lion hides","狩猎","皮具","狮皮","制革匠","贸易"},sec={{t="猎人的困境",b="“Bruised Pride and Lion Hides”需要帮助一位受伤的猎人，由于最近受到身体伤害，他无法追踪野兽。为了避免未能履行与附近工匠达成的贸易协议，他们雇佣了一位冒险者来追踪野狮并收集它们的毛皮。"},{t="履行契约",b="收集到的生皮会与当地制革匠交换任务发布者生计所需的成品皮质装备。尽管受了伤，且因为需要外界帮助而感到自尊心受挫，但履行这项契约确保了他们的职业声誉不会受损。"}},faq={{q="这个任务是关于什么的？",a="狮皮是为一位受伤的猎人或商人收集的，他会向当地制革匠供应原材料。作为交换，任务发布者会收到其生计所必需的成品皮具。",al={"bruised pride and lion hides是什么","任务目标","狮皮的用途"}},{q="为什么任务发布者需要帮助来收集毛皮？",a="任务发布者受了伤，无法亲自猎狮。为了不破坏与当地制革匠长期以来的业务协议，他们依靠冒险者来完成交付。",al={"为什么需要帮助","为什么不能狩猎"}},{q="谁会收到狮皮？",a="生皮会被交易给当地的制革匠。制革匠将它们加工成任务发布者日常贸易和工作所需的成品皮具。",al={"谁得到狮皮","毛皮去向"}},{q="“Bruised Pride and Lion Hides”这个名字是什么意思？",a="这个标题用了双关语：既指必须被狩猎的狮群（pride of lions），也指受伤猎人的个人自尊心（pride），因为尽管目前身体受限，他们从未在履行合同时失信。",al={"bruised pride的含义","为什么叫bruised pride"}},{q="与制革匠的协议是否处于危险之中？",a="是的。受伤使任务发布者无法狩猎，导致下一次交付面临风险。收集狮皮让他们能够履行协议，而不会违约。",al={"制革匠的协议是否成立","贸易协议破裂"}},{q="任务发布者是怎么受伤的？",a="任务发布者遭受了伤痛，导致其无法在野外猎狮，但受伤的具体原因并未详述。递送毛皮让他们得以保住自己的声誉。",al={"任务发布者受伤","猎人发生了什么"}}},fp="28,309,18.278.0,24.292.0,25.213.0,51.201.0,28.161.0,55.206.0,44.183.0,32.203.0"}
P.entries["quest:95495"] = {n="The Hermit Tanner",s="“The Hermit Tanner”是贫瘠之地的一项本地运送任务，冒险者需要将一捆兽皮送到一位居住在无水岭上方山脊的隐居工匠手中。该任务展现了这片大草原上偏远地区的商业合作，并介绍了一位虽然与世隔绝但仍保持定期贸易的奇特隐士。",h="“The Hermit...",kw={"贫瘠之地","一捆兽皮","无水岭","隐士剥皮师","山脊","剥皮师","vrang"},ang={["faction:Horde"]="穿越中部大草原的旅行者经常协助像Vrang这样的当地商人，在贫瘠之地崎岖的地形中运送必要的贸易物资。"},sec={{t="贫瘠之地的一座山脊",b="贫瘠之地的崎岖大草原促进了坚韧的居民之间的贸易，不过并非所有的工匠都喜欢在十字路口或定居点那种喧闹的环境中工作。在无水岭的阴影下，一位名叫Vrang的商人经常与一位隐居的剥皮师交换货物，这位剥皮师在俯瞰山脊的上方建立了一个安静的宅基地。由于沿着岩石山坡陡峭的攀爬对Vrang来说过于吃力，他只能依靠路过的冒险者将一捆捆生皮运送给他那位隐居的合作伙伴。"},{t="一位不寻常的工匠",b="在打发旅行者上路之前，Vrang特意对这位隐居的工匠提出了特别警告。这位隐士有着令人惊恐且不同寻常的外表，可能会让毫无准备的访客感到吃惊，但Vrang坚称这位隐居的剥皮师对客人毫无威胁。当隐士在山脊上的住所收到生皮后，他会热情地欢迎送信人，但他同时也感叹Vrang没能亲自爬上来，因为他还有一件事情希望能与那位商人当面商讨。"}},faq={{q="谁让你去进行这项送货任务的？",a="一位名叫Vrang的商人安排了这项任务，他请求路过的旅行者将一捆生皮送到位于上方山脊的商业伙伴那里。",al={"谁发布了隐士剥皮师任务","任务起始地点","vrang的运送任务"}},{q="隐居的剥皮师住在哪里？",a="隐居的剥皮师独自居住在贫瘠之地无水岭上方的一座高耸山脊的偏僻宅基地里。",al={"隐士剥皮师位置","隐士剥皮师在哪里","山脊上的隐士"}},{q="为什么Vrang要警告你关于剥皮师的外貌？",a="Vrang预先警告旅行者不要被剥皮师不寻常或令人不安的外表所惊吓，并保证尽管他看起来很吓人，但这位隐士对访客并不构成威胁。",al={"隐士外貌","为什么隐士看起来很可怕","隐士长相"}},{q="为什么Vrang自己不能爬上去？",a="Vrang解释说，沿着崎岖的山坡陡峭攀爬对他来说不是一件轻松的事，因此他只能雇用送信人代劳。",al={"为什么需要运送","为什么vrang无法亲自前往"}},{q="运送到山脊上的物品是什么？",a="运送的物品是一捆用于剥皮师生意的兽皮，这是两人经常合作的一项工艺。",al={"什么是一捆兽皮","运送的任务物品"}},{q="隐居的剥皮师想和Vrang商讨什么？",a="在收到货物后，剥皮师表达了对Vrang未能亲自攀登上来而感到遗憾，并提到有一件事他需要与Vrang直接沟通。",al={"剥皮师想和vrang商讨什么","剥皮师与vrang的生意"}}},fp="17,338,22.499.0,27.508.0,31.149.0,34.115.0,54.177.0,42.169.0,44.131.0,55.178.0"}
P.entries["quest:955"] = {n="巴莎兰",s="阿斯特利安，一位在巴莎兰古代废墟中徘徊的悲伤上层精灵幽灵，正在寻找解除束缚他灵魂形式的封印魔法的方法。他认为当地顽皮的劣魔触碰过禁锢他的封印，因此委托旅行者收集它们的耳环，以便追踪上面残留的魔法共鸣。",h="阿斯特利安，一位在巴莎兰古代废墟中徘徊的悲伤上层精灵幽灵，正在寻找解除束缚他灵魂形式的封印魔法的方法。他认为当地顽皮的劣魔触碰过禁锢他的封印，因此委托旅行者收集它们的耳环，以便追踪上面残留的魔法共鸣。",kw={"阿斯特利安","巴莎兰","束缚","黑海岸","幽灵","劣魔","劣魔耳环","封印"},ang={["class:Mage"]="阿斯特利安利用附魔饰品追踪残留魔法波动的手段，反映了上层精灵古代奥术占卜的习俗。",["faction:Alliance"]="清理巴莎兰周围混乱的劣魔，有助于平定黑海岸北部充满危险的地区，为联盟的利益提供保障。",["race:NightElf"]="对于卡多雷来说，遇见阿斯特利安是一个发人深省的提醒，让他们意识到在大分裂期间陨落的古老文明，留下了这些被困在废墟中数千年的受苦灵魂。"},sec={{t="数百年的折磨",b="在巴莎兰破碎的大理石建筑间徘徊着阿斯特利安，一位承受了数百年禁锢之苦的古代暗夜精灵灵魂。他被困在生与真正死亡之间，在黑海岸的树冠下过着痛苦的等待。由于被奥术技艺直接束缚在这片废墟聚落中，阿斯特利安无法独自打破枷锁，无尽的孤独与绝望让他心力交瘁。"},{t="荒野中的踪迹",b="阿斯特利安怀疑，他获得解脱的关键是隐藏在废墟某处的一道古老封印。虽然他无法亲自搜寻灌木丛和坍塌的石块，但盘踞在巴莎兰的野蛮劣魔经常会搜寻并偷走一些小饰品。阿斯特利安请求旅行者收集这些生物佩戴的耳环，打算通过解读饰品上残留的魔法印记，来定位禁锢他灵魂的封印。"}},faq={{q="阿斯特利安是谁？",a="阿斯特利安是一位古代暗夜精灵幽灵，被束缚在黑海岸的巴莎兰废墟中。他被一道神秘的封印困住了数百年，在痛苦中看着时光流逝，渴望从这种幽灵状态中解脱出来。",al={"阿斯特利安背景故事","谁是巴莎兰的幽灵","阿斯特利安任务发布者"}},{q="为什么阿斯特利安想要劣魔耳环？",a="劣魔是臭名昭著的拾荒者，喜欢囤积闪亮的饰品和珠宝。阿斯特利安认为这些生物触碰过禁锢他的魔法封印，这意味着它们佩戴的耳环可能带有足够的魔法残留，可以帮助他找到封印。",al={"为什么需要劣魔耳环","劣魔耳环的作用","黑海岸耳环任务"}},{q="巴莎兰是什么？",a="巴莎兰是一处古老的暗夜精灵遗迹，位于黑海岸的森林海岸边，其历史可以追溯到大分裂之前。这里到处都是野生的劣魔、萨特以及早已覆灭的定居者留下的幽灵残骸。",al={"什么是巴莎兰","巴莎兰历史","巴莎兰废墟"}},{q="收集耳环后会发生什么？",a="阿斯特利安检查了耳环，感觉到虽然劣魔并没有直接携带封印本身，但它们在相对近期的活动中触碰过它。这一踪迹让他能够缩小封印在废墟中的位置范围。",al={"耳环显示了什么","劣魔身上有封印吗","劣魔耳环结果"}},{q="为什么阿斯特利安会被困在这里？",a="阿斯特利安在数百年前被一道古老的魔法封印束缚在巴莎兰。这种束缚将他的灵魂锚定在废墟的物理位置上，阻止他前往安息之地。",al={"谁束缚了阿斯特利安","阿斯特利安如何被束缚","阿斯特利安的封印"}},{q="什么是劣魔？",a="劣魔是卡利姆多森林中原生的体型细小、心怀恶意的林地生物。它们以顽皮的天性、锋利的爪子和对饰品的喜爱而闻名，经常侵扰旧遗迹并攻击过往的旅行者。",al={"什么是劣魔","劣魔背景","黑海岸劣魔"}}},fx={["99bf1a9e"]={q="阿斯特利安为什么想让你做这件事？",a="阿斯特利安被困在痛苦的幽灵形态中，一道古老的魔法封印将他束缚在巴莎兰遗迹里。数百年的囚禁逐渐侵蚀了他的理智，他渴望摆脱折磨。通过检查当地生物携带的耳环，他希望用魔法占卜出束缚他的结界的确切位置，以便最终将其摧毁。",al={"阿斯特利安的动机","为什么帮助阿斯特利安","阿斯特利安为什么要耳环"}},a8a71265={q="阿斯特利安为什么需要你帮忙，而不是自己行动？",a="阿斯特利安是一个虚无缥缈的幽灵，被强大的巫术束缚在遗迹中。他无法远离自己安息之处，也无法亲自与格雷尔和精灵战斗，只能依靠路过的凡人猎杀这些生物，收集它们的饰物供他占卜。",al={"阿斯特利安为什么需要我","阿斯特利安为什么不能拿到耳环","阿斯特利安为什么不能离开"}}},fp="11,315,23.421.0,18.442.0,16.219.0,38.232.0,20.222.0,43.236.1,29.199.0,16.210.0"}
P.entries["quest:956"] = {n="巴莎兰",s="阿斯特利安，一位被困在巴莎兰废墟支柱间的暗夜精灵灵魂，正在寻找束缚他于此世的圣物。在察觉到当地格罗尔身上存在禁锢他的腐蚀力量后，他指引旅行者去猎杀那些驱使格罗尔的萨特，并取回远古月亮石封印。",h="阿斯特利安，一位被困在巴莎兰废墟支柱间的暗夜精灵灵魂，正在寻找束缚他于此世的圣物。在察觉到当地格罗尔身上存在禁锢他的腐蚀力量后，他指引旅行者去猎杀那些驱使格罗尔的萨特，并取回远古月亮石封印。",kw={"远古月亮石封印","阿斯特利安","巴莎兰","黑海岸","格罗尔","卡多雷","暗夜精灵幽灵","萨特"},ang={["class:Druid"]="萨特扭曲的影响力仍在不断腐蚀黑海岸的野生动物，并惊扰着那些本应在自然循环中安息的古老灵魂。",["faction:Alliance"]="清除黑海岸废墟中的萨特腐蚀，不仅能确保卡利姆多北海岸的安全，也能帮助卡多雷告慰他们那段悲剧性的过去。",["race:NightElf"]="巴莎兰是你族人古老过去的一个沉痛提醒，那些久久不愿离去的先祖们，被那些体现了天崩地裂时恶魔背叛的萨特束缚在这片土地上。"},sec={{t="古石之牢",b="一千多年来，阿斯特利安的灵魂一直被禁锢在巴莎兰的废墟之中。周围的大理石柱像是一座坚不可摧的牢笼，无论是他那日渐衰弱的灵魂力量，还是他所掌握的古老魔法，都无法将其打破。他被一件被诅咒的圣物束缚于此，几个世纪以来，他只能望着黑海岸那雾气缭绕的树冠，怀疑即便周围的岩石风化殆尽，自己能否获得解脱。"},{t="萨特与月亮石封印",b="在发现附近的格罗尔身上带有维持他囚禁状态的魔法痕迹后，阿斯特利安推断出这种附魔的源头已经落入驱使这些混乱生物的萨特手中。这些恶魔化的暗夜精灵游荡在古老的树林中，严密地看守着远古月亮石封印。夺回这件护身符是打破束缚阿斯特利安于神龛之上的无形枷锁的关键一步。"}},faq={{q="谁是阿斯特利安？",a="阿斯特利安是一位被困在巴莎兰废墟中的古老暗夜精灵幽灵。由于古老魔法的束缚，他被禁锢在神龛耸立的石柱间超过了一千年，无法超脱，也无法离开这座石之囚笼。",al={"谁是阿斯特利安","阿斯特利安的背景故事","巴莎兰的幽灵"}},{q="为什么萨特持有远古月亮石封印？",a="萨特在黑海岸北部领导并影响着那些野生的格罗尔。因为格罗尔身上带有禁锢魔法的痕迹，阿斯特利安意识到，是它们邪恶的萨特主人夺走了远古月亮石封印，以此来折磨并禁锢当地的灵魂。",al={"为什么萨特有封印","萨特月亮石封印","远古月亮石封印"}},{q="封印被找回后会发生什么？",a="阿斯特利安将收回这件束缚了他几个世纪的圣物。取回远古月亮石封印是他获得自由的倒数第二步，这使得封印能够被解除，从而让他最终能再次自由地行走于森林之中。",al={"封印的作用","取回封印"}},{q="什么是巴莎兰？",a="巴莎兰是位于黑海岸北部雾气弥漫的海岸线旁的一处古老暗夜精灵废墟。它曾经是一处宏伟的定居点或圣地，如今已支离破碎，被格罗尔、萨特以及困于此处的往昔灵魂所侵扰。",al={"巴莎兰背景故事","什么是巴莎兰"}},{q="阿斯特利安被困在这里多久了？",a="阿斯特利安已经被囚禁了一千多年。由于没有物理手段或魔法来摧毁边界，他被迫在漫长的岁月中等待，不知道自己是否还有重获自由的一天。",al={"阿斯特利安的年龄","被困多久"}},{q="阿斯特利安可以直接离开神龛吗？",a="不能。远古月亮石封印在神龛周围维持着一道形而上的屏障。这些石柱就像一座无法逾越的牢笼，阻挡了他的幽灵形态跨越此界。",al={"阿斯特利安能离开吗","为什么幽灵被困"}}},fx={["31aed888"]={q="阿斯特利安为什么想找回封印？",a="阿斯特利安迫切地渴望自由。这件古老的遗物是他永恒牢狱的束缚之源，将他的灵魂困在残破的神龛中。一千多年来，他只能望着石柱，却无法凭力量或巫术挣脱。找回神器是摧毁它、让他重新自由行走于森林中的唯一办法。",al={"阿斯特利安为什么要做这件事","阿斯特利安的动机","为什么帮助阿斯特利安"}},["5f1ff286"]={q="什么是远古月亮石封印？",a="远古月亮石封印是一件魔法遗物，是囚禁阿斯特利安的关键。它在巴莎兰的石柱之间形成一道无形屏障，宛如一座永恒牢笼，阿斯特利安无法用法术或蛮力将其打破。只要封印仍在附近的腐化势力手中，阿斯特利安就会继续被困在神龛中。",al={"什么是远古月亮石封印","月亮石封印有什么作用","远古月亮石封印的用途"}},c7650517={q="为什么要派你去对付当地的萨特？",a="萨特控制着在巴莎兰遗迹中肆虐的邪恶格雷尔。较弱的格雷尔身上带有封印的魔法痕迹，因此阿斯特利安推断它们的主人一定拿到了神器。萨特受到腐化，又被古老的魔法遗物吸引，他们把封印藏在营地中，所以你要对付他们。",al={"巴莎兰的萨特是谁","为什么要与萨特战斗","谁拿着封印"}},["341831b6"]={q="阿斯特利安为什么不能自己取回封印？",a="阿斯特利安无法离开神龛的范围。封印的魔力将他牢牢困在其中，把石柱变成无法逾越的牢栏。他既没有足够的力量，也没有足够的巫术打破囚禁，只能完全依靠外来者替他进入萨特营地。",al={"阿斯特利安为什么需要我","阿斯特利安为什么不能拿到封印","阿斯特利安为什么找我"}}},fp="11,291,25.425.0,29.449.0,16.239.0,50.265.0,40.232.1,20.235.0,40.201.0,46.187.0"}
P.entries["quest:95621"] = {n="Trouble in the Valley",s="“Trouble in the Valley”讲述了一支神秘的库尔提拉斯人小队在山谷底部进行搜寻的故事。武装部队在南边一辆损毁的大篷车附近扎营，这促使当地侦察兵寻求消除这一威胁，并揭开他们意外搜寻背后的目的。",h="“Trouble in the Valley”讲述了一支神秘的库尔提拉斯人小队在山谷底部进行搜寻的故事。武装部队在南边一辆损毁的大篷车附近扎营，这促使当地侦察兵寻求消除这一威胁，并揭开他们意外搜寻背后的目的。",kw={"大篷车","库尔提拉斯","士兵","trouble in the valley","山谷","损毁的大篷车"},ang={["race:Human"]="看到身穿代表岛国库尔提拉斯的海绿色和锚徽制服的士兵在山谷中活动，标志着与这个与世隔绝的人类航海民族进行了一次罕见且出人意料的邂逅。"},sec={{t="山谷中的可疑活动",b="一名正在俯瞰低地的警觉步枪手发现了一支库尔提拉斯人小队正在山谷底部进行搜寻。通过步枪瞄准镜仔细观察，侦察兵清晰地辨认出了那个海上王国库尔提拉斯的纹章和制服。他们出人意料地出现在山谷中立刻引发了警觉，因为武装外来者很少会如此大摇大摆地行动而不引起注意。"},{t="损毁的大篷车",b="士兵们在南边一辆损毁的大篷车附近驻扎。无论是什么吸引他们来到这辆损毁的马车旁，这都是一个亟待解决的谜团。当地观察员认为这种入侵性的武装存在是一个迫在眉睫的问题，因此派遣调查员去消灭这些士兵，并揭开他们远征的真正目的。"}},faq={{q="库尔提拉斯人士兵在山谷里做什么？",a="一名神枪手发现了一支库尔提拉斯人分遣队正在下方的山谷中搜寻某物。他们在南边一辆损毁的大篷车附近建立了营地，这促使当地侦察兵去调查他们不同寻常的动机。",al={"库尔提拉斯人为什么在这里","山谷里的库尔提拉斯士兵","库尔提拉斯人在做什么"}},{q="库尔提拉斯人营地在哪里？",a="士兵们在俯瞰山谷的侦察点南侧的一辆损毁大篷车附近建立了营地。",al={"损毁的大篷车位置","库尔提拉斯营地在哪里","大篷车地点"}},{q="库尔提拉斯人的存在是如何被发现的？",a="一名监视山谷的侦察兵使用步枪瞄准镜从远处观察那群神秘的人类，并轻易地辨认出了库尔提拉斯特有的制服和徽章。",al={"他们是如何被发现的","库尔提拉斯制服"}},{q="调查营地的目标是什么？",a="任务要求前往南方的损毁大篷车处，与驻扎在那里的库尔提拉斯人士兵对峙，并查明是什么吸引他们搜寻该区域。",al={"目标是什么","trouble in the valley任务目标"}},{q="为什么这些库尔提拉斯人士兵被视为敌人？",a="因为一支武装外国士兵分遣队在没有解释的情况下，正在损毁的大篷车周围积极搜寻领土，侦察兵认为他们是一个必须予以制服以探明意图的威胁。",al={"为什么要与库尔提拉斯战斗","库尔提拉斯人是敌对的吗"}},{q="谁在山谷里发现了这些士兵？",a="监视山谷的隐士制革工The Hermit Tanner首先通过步枪瞄准镜识别出了这些士兵，并雇佣了一名冒险者去消灭他们，弄清他们为何出现在这里。",al={"谁发现了士兵","谁发布了任务"}}},fp="21,283,33.369.0,19.318.0,48.231.0,36.143.0,42.170.0,48.165.0,50.210.0,40.178.0"}
P.entries["quest:95646"] = {n="Horrors in the Highland",s="绿色守卫者雷希耶尔感知到一股邪恶的腐蚀力量正穿过山沟，渗入湿地之上的淡水区域。冒险者必须前往发掘现场，消灭一只高地恐魔并回收它的根核。雷希耶尔发现一股古老的能量正在苏醒，并警告称持续的挖掘行为威胁到了该地区所有人的安全。",h="绿色守卫者雷希耶尔感知到一股邪恶的腐蚀力量正穿过山沟，渗入湿地之上的淡水区域。冒险者必须前往发掘现场，消灭一只高地恐魔并回收它的根核。雷希耶尔发现一股古老的能量正在苏醒，并警告称持续的挖掘行为威胁到了该地区所有人的安全。",kw={"腐蚀","发掘现场","高地恐魔","horrors in the highland","雷希耶尔","绿色守卫者雷希耶尔","根核","湿地"},ang={["class:Druid"]="雷希耶尔通过他的根系和水道感知到了自然平衡的改变；与大地协调一致的德鲁伊会意识到淡水生物在面对古老腐蚀时的脆弱性。",["faction:Alliance"]="在山区进行发掘作业的联盟探险家和勘探员有惊扰埋藏在地底的古老力量的风险。",["race:Dwarf"]="高地上的矮人发掘场出土的东西远不止古老的遗物，这促使雷希耶尔敦促挖掘者在更邪恶的东西苏醒之前停止挖掘。"},sec={{t="沟壑中的污染",b="在湿地的深处，绿色守卫者雷希耶尔感知到了大地发生了令人不安的变动。一股邪恶的污染穿过一条山沟，感染了高地之上的淡水生物。与那些在苦咸的低地水域中淬炼出的顽强生命不同，这些淡水生物从未接触过海洋的保护性盐分，这使它们在面对蔓延的邪恶时毫无防御能力。雷希耶尔呼吁冒险者前往发掘现场，消灭一只高地恐魔，并取回它的根核。"},{t="古老的苏醒",b="当高地恐魔的根核被带到雷希耶尔面前时，这位守护者的担忧得到了证实：一股古老的能量已经开始苏醒。困扰高地生物的病痛并非寻常的疾病，而是近期挖掘行为的后果。雷希耶尔紧急警告称，在山区工作的心急火燎的挖掘者必须立即停止挖掘，否则他们盲目的好奇心会给湿地带来更可怕的灾难。"}},faq={{q="谁发布了“Horrors in the Highland”任务？",a="绿色守卫者雷希耶尔，一位守护着湿地的古老保护者，在感知到附近山沟渗出的邪恶腐蚀后发布了这个任务。",al={"谁发布horrors in the highland任务","horrors in the highland任务发布者","雷希耶尔任务"}},{q="在哪里可以找到高地恐魔？",a="高地恐魔栖息在低地之上的高地发掘现场，靠近腐蚀渗出的山沟附近。",al={"高地恐魔在哪里","高地恐魔位置","如何找到高地恐魔"}},{q="为什么高地生物如此容易受到腐蚀？",a="高地的淡水生物缺乏湿地低处海洋特有的盐分浸润，这使得它们体质脆弱，在面对腐蚀性的污染时反应格外剧烈。",al={"为什么生物受到污染","为什么高地生物被腐蚀","淡水腐蚀"}},{q="什么是高地恐魔的根核？",a="根核是受腐蚀的高地恐魔的心脏。雷希耶尔需要它来检查蔓延在水道中的非自然力量，并确认腐蚀的性质。",al={"什么是根核","高地恐魔核心","为什么要取回根核"}},{q="当你交还根核时，雷希耶尔发现了什么？",a="在检查了核心后，雷希耶尔意识到一股古老的能量已经开始从地底深处苏醒，这很可能是因为发掘现场鲁莽的挖掘行为所惊扰。",al={"雷希耶尔发现了什么","湿地古老能量","挖掘危险"}},{q="为什么雷希耶尔希望挖掘者停止挖掘？",a="雷希耶尔警告说，在高地工作的心急火燎的挖掘者应该为了自身的安全立即停止挖掘，因为他们的挖掘行为有释放危险的古老力量的风险。",al={"雷希耶尔停止挖掘","挖掘者应该做什么","矮人挖掘场警告"}}},fp="23,358,18.505.0,19.443.1,45.164.0,36.152.0,60.197.0,43.185.0,57.172.0,53.184.0"}
P.entries["quest:95647"] = {n="Lost in the Thicket Things",s="一位忧心忡忡的炼金师请求路过的旅行者去寻找她失踪的丈夫阿丁·格拉斯曼（Ardin Grassman）。阿丁在追寻关于高耸、未知的草类的传闻后失踪了。他对植物的好奇心将他引向了附近的一处挖掘场，那里的考察队正遭到危险野生生物和蜘蛛的围攻。",h="一位忧心忡忡的炼金师请求路过的旅行者去寻找她失踪的丈夫阿丁·格拉斯曼（Ardin...",kw={"炼金术","阿丁","阿丁·格拉斯曼","挖掘场","草药学","lost in the thicket things","蜘蛛","高耸的草类"},ang={["class:Druid"]="关注荒野平衡的德鲁伊可能会对阿丁感知植物的天赋，以及挖掘场附近导致野生生物反常躁动的原因感兴趣。",["profession:Herbalism"]="阿丁·格拉斯曼拥有感知植物和草药的与生俱来的天赋，经常攀登险峻的地形，为炼金术收集稀有植物。"},sec={{t="采药人的呼唤",b="在“Lost in the Thicket Things”中，一位炼金师寻求帮助以寻找她失踪的丈夫阿丁·格拉斯曼。阿丁拥有一种令人难以置信的、对大自然的本能亲和力，经常冒着险攀登陡峭的悬崖，前往遥远的荒野，为妻子的炼金补给收集稀有草药和植物标本。当一支经过的挖掘队带来关于前所未见的奇异高耸草类的消息时，阿丁的好奇心占了上风，他出发去亲自考察这些植物。"},{t="挖掘场埋伏",b="阿丁追踪考察队来到了他们的挖掘场，却直接陷入了危险之中。周围土地上的某种东西扰乱了当地的动物，导致极具攻击性的野生生物——最显著的是成群的敌对蜘蛛——猛扑过来并淹没了挖掘小队。被不断逼近的野兽困住，阿丁和队员们陷入重围，直到有旅行者介入救援了这位被困的植物学家。"}},faq={{q="谁是阿丁·格拉斯曼？",a="阿丁·格拉斯曼是一位拥有感知植物和草药的天赋的采集者。他经常搜寻悬崖和山峰，为妻子的炼金工艺提供野生植物，但他对奇异的高耸草类的好奇心将他引向了一处挖掘场。",al={"阿丁是谁","阿丁·格拉斯曼背景故事","谁是阿丁·格拉斯曼"}},{q="阿丁为什么要闯入荒野？",a="阿丁无意中听到挖掘队在描述一种他们从未见过的高耸巨草。出于对奇异植物和花卉的喜爱，他冒险前往，想要亲眼见识一下这些奇怪的植被，结果却没能回家。",al={"阿丁为什么离开","为什么阿丁失踪了","阿丁在寻找什么"}},{q="阿丁去哪了？",a="在听到一支经过的考察队的消息后，阿丁前往了附近的挖掘场。寻找他的旅行者必须仔细搜查考察队建立作业点的地方。",al={"阿丁在哪里","阿丁的位置","在哪里找到阿丁·格拉斯曼"}},{q="阿丁在挖掘场发生了什么？",a="阿丁到达时发现挖掘营地已被当地野生生物的猛烈攻击所淹没。巨型蜘蛛和其他被激怒的野兽埋伏了考察队，将阿丁和队员们困住，直到外部支援到来。",al={"阿丁发生了什么","阿丁死了吗","什么攻击了阿丁"}},{q="谁在寻找阿丁？",a="搜寻工作始于阿丁的妻子，一位依赖丈夫的草药采集来补充炼金材料的炼金师。当他调查关于奇异草类的传闻而未能归来时，她寻求了能干的旅行者来带他回家。",al={"谁发布了lost in the thicket things","谁发起了这个任务","阿丁的妻子"}},{q="为什么野生生物会攻击挖掘队？",a="挖掘场周围的野生生物突然变得狂暴不安，尽管造成它们躁动的根本原因尚不明确。这种骚乱驱使具有攻击性的生物，尤其是蜘蛛，蜂拥而至并淹没了挖掘队。",al={"为什么蜘蛛在攻击","什么激怒了动物","为什么野兽如此愤怒"}}},fp="26,298,19.490.0,22.401.1,22.269.0,39.259.0,19.190.0,46.221.0,25.237.0,48.253.0"}
P.entries["quest:95697"] = {n="Changing Tastes",s="Changing Tastes是奥格瑞玛的一个关于博斯坦的火坑烹饪抱负的任务。在扎姆沙的建议和关于巨型迅猛龙爪的传说的推动下，博斯坦委托冒险者穿越无尽之海前往湿地，以获取异域的灌木迅猛龙肉。",h="Changing Tastes是奥格瑞玛的一个关于博斯坦的火坑烹饪抱负的任务。在扎姆沙的建议和关于巨型迅猛龙爪的传说的推动下，博斯坦委托冒险者穿越无尽之海前往湿地，以获取异域的灌木迅猛龙肉。",kw={"博斯坦","博斯坦的火坑","changing tastes","挖掘场","奥格瑞玛","灌木迅猛龙","灌木迅猛龙肉","湿地","扎姆沙"},ang={["faction:Horde"]="供应博斯坦的火坑意味着要深入跨越海洋的争夺领土，将异域肉类带回奥格瑞玛。",["profession:Cooking"]="博斯坦旨在将传统的乡村餐点提升为足以在部落首都享用的盛宴，凸显了烹饪口味和旅店菜单如何超越乡村主食而演变。"},sec={{t="提升首都烹饪水平",b="在奥格瑞玛的中心地带，博斯坦的火坑正寻求扩大其烹饪种类。扎姆沙建议引入家常迅猛龙烹饪，以吸引那些怀念家乡舒适、熟悉饭菜的旅行者。博斯坦喜欢供应迅猛龙肉以吸引新客人的想法，但他觉得仅仅重现乡村菜肴对于伟大的部落首都不太合适。相反，他设想了一个更宏大、更粗犷的经典主食版本。"},{t="湿地狩猎",b="当一位猎人带着从在湿地挖掘场徘徊的灌木迅猛龙身上取下的巨大爪子回到奥格瑞玛时，灵感便出现了。博斯坦对这些野兽的品质和体型很感兴趣，于是安排冒险者穿越无尽之海前往东部王国，勇闯挖掘场，并为他咆哮的炉火获取上等的灌木迅猛龙肉。"}},faq={{q="什么是Changing Tastes任务？",a="Changing Tastes是奥格瑞玛发布的一项烹饪任务。博斯坦的火坑的所有者博斯坦，寻求来自遥远湿地的灌木迅猛龙肉，以提升其旅店菜单的档次，超越基本的乡村烹饪。",al={"什么是changing tastes","changing tastes任务"}},{q="扎姆沙是谁？",a="扎姆沙是奥格瑞玛的一位同事或同行烹饪工作者，她建议在博斯坦的火坑增加家常迅猛龙菜肴，以吸引通常不会光顾的顾客。",al={"谁是扎姆沙","扎姆沙烹饪"}},{q="什么是博斯坦的火坑？",a="博斯坦的火坑是位于部落首都奥格瑞玛的一家餐馆，以向旅行者和当地居民提供丰盛的熟肉而闻名。",al={"博斯坦的火坑","博斯坦在哪里"}},{q="博斯坦为什么需要灌木迅猛龙肉？",a="虽然扎姆沙提议用普通的家常迅猛龙烹饪来吸引食客，但博斯坦想要一种更宏大的熟悉口味。受到猎人关于巨型爪子的故事的启发，他选择了在湿地发现的灌木迅猛龙。",al={"为什么要迅猛龙肉","为什么要灌木迅猛龙"}},{q="灌木迅猛龙位于哪里？",a="灌木迅猛龙栖息在位于湿地的挖掘场，这是一个横跨无尽之海、位于东部王国的联盟倾向地区。",al={"我能在哪里找到灌木迅猛龙","湿地挖掘场迅猛龙"}},{q="谁发布了Changing Tastes任务？",a="博斯坦，奥格瑞玛博斯坦的火坑的经营者，在受到扎姆沙的建议和一位冒险的猎人带回的战利品的启发后，提供了这个任务。",al={"谁发布了changing tastes","博斯坦任务发布者"}}},fp="15,264,25.472.0,24.378.0,34.201.0,13.173.0,26.142.0,42.220.0,38.143.0,36.169.0"}
P.entries["quest:957"] = {n="巴莎兰",s="这个任务要求冒险者帮助位于巴莎兰废墟中被困的阿斯特利安之灵。通过将他的束缚封印带往南方的姐妹废墟亚米萨兰，冒险者将设法打破他身上的远古羁绊。",h="这个任务要求冒险者帮助位于巴莎兰废墟中被困的阿斯特利安之灵。通过将他的束缚封印带往南方的姐妹废墟亚米萨兰，冒险者将设法打破他身上的远古羁绊。",kw={"亚米萨兰","阿斯特利安","阿斯瑞库斯","艾萨拉","巴莎兰","黑海岸","上层精灵","月亮石封印"},ang={["class:Mage"]="束缚阿斯特利安的持久附魔和亚米萨兰幸存的火焰，让人得以一窥远古上层精灵法师所掌控的原始奥术力量。",["faction:Alliance"]="清除黑海岸的远古诅咒，为从奥伯丁向外扩张的暗夜精灵新定居点确保了边境的安全。",["race:NightElf"]="对于现代卡利姆多的暗夜精灵来说，解放阿斯特利安是一次沉重的经历，让他们直面自己种族在大分裂前的过去，以及艾萨拉女王的上层精灵贵族所留下的腐化。"},sec={{t="远古法术的囚笼",b="阿斯特利安的灵魂在巴莎兰徘徊了数千年，在死后被一枚远古月亮石封印所禁锢。这枚封印由大分裂前上层精灵一族强大的法术锻造而成，凡人的力量无法将其击碎。若要摧毁它，需要借助一种远古火焰的特殊魔法，而这种火焰至今仍在南方的亚米萨兰坍塌的石构建筑中燃烧。"},{t="黑海岸的双生废墟",b="巴莎兰和亚米萨兰曾是卡多雷文明中充满活力的姐妹定居点，那时艾萨拉女王统治着帝国，永恒之井仍是帝国的基石。如今，两处遗迹都已是荒草丛生、鬼魂萦绕的废墟，充斥着挥之不去的幽灵和不稳定的奥术能量。在亚米萨兰的一座石亭内，一盏青色火焰的神秘火盆提供了唯一足以吞噬阿斯特利安束缚遗物的力量。"},{t="复仇之火觉醒",b="随着封印被摧毁，阿斯特利安终于卸下了重担。他凝视着支离破碎的卡利姆多，这里的景象与他记忆中的黄金时代相比已是天差地别。然而，自由并没有带给他平静。当感觉到他曾经的主人兼狱卒——上层精灵阿斯瑞库斯依然存在时，阿斯特利安心中远古的绝望很快转化为一种冰冷而灼热的复仇渴望。"}},faq={{q="阿斯特利安是谁？",a="阿斯特利安是一位被困在巴莎兰废墟中的暗夜精灵之灵。他可以追溯到一万年前艾萨拉女王统治的时期，并被一枚由上层精灵中最强大的法师所制作的封印束缚在废墟中。",al={"阿斯特利安","幽灵是谁","npc 阿斯特利安"}},{q="我在哪里可以摧毁远古月亮石封印？",a="封印必须带往南方的亚米萨兰，那是巴莎兰的双生废墟。寻找一座石亭，里面有一个巨大的立方体火盆，燃烧着一种远古的青绿色魔法火焰。",al={"火焰在哪里","远古火焰位置","摧毁封印"}},{q="巴莎兰和亚米萨兰之间有什么关系？",a="在大分裂之前，它们是远古暗夜精灵帝国的姐妹城市。一万年前，这两座城市都遭到了毁灭，留下了闹鬼的石柱、残留的奥术能量和不安的灵魂。",al={"双生废墟","亚米萨兰联系","巴莎兰 亚米萨兰"}},{q="是谁监禁了阿斯特利安？",a="阿斯特利安说，上层精灵中最强大的一位创造了束缚他的封印。关于他前主人的更多信息将在任务链中揭晓。",al={"谁囚禁了阿斯特利安","阿斯瑞库斯是谁","阿斯特利安的主人"}},{q="阿斯特利安记得的是哪个时代？",a="阿斯特利安最后行走于世间时，最初的永恒之井依然存在，艾萨拉女王统治着帝国，而上层精灵贵族在大分裂前拥有着他们辉煌的宫廷。",al={"阿斯特利安的过去","永恒之井时代","阿斯特利安有多古老"}},{q="解放阿斯特利安会让他的灵魂安息吗？",a="摧毁封印旨在打破阿斯特利安的牢笼。当你回到他身边时，他对于获得自由的反应自会揭晓。",al={"阿斯特利安会安息吗","阿斯特利安发生了什么","自由后的阿斯特利安"}}},fx={["8275c861"]={q="阿斯特利安为什么要摧毁远古月亮石封印？",a="远古月亮石封印是将阿斯特利安的灵魂困在巴莎兰遗迹中受苦的根源。这件封印由强大的高等精灵巫术在数千年前打造，使他身陷囹圄，无法看见外面的世界。只有在亚米萨兰的神秘古焰中摧毁它，才能斩断他的幽灵枷锁，让他获得自由，并看清卡利姆多如今的模样。",al={"为什么摧毁月亮石封印","阿斯特利安的动机","阿斯特利安为什么想打破封印"}},["51df5ddd"]={q="阿斯特利安为什么要你把封印带到亚米萨兰？",a="古老的高等精灵魔法将阿斯特利安束缚在巴莎兰，他连遗迹附近都无法离开，更别说南下前往亚米萨兰了。他需要一位旅人将封印带到古焰中。",al={"阿斯特利安为什么不能摧毁封印","阿斯特利安为什么需要我","为什么派冒险者去摧毁封印"}}},fp="11,224,27.384.0,23.435.0,17.344.1,16.225.0,46.188.0,60.212.0,24.144.1,32.188.0,45.116.1"}
P.entries["quest:95772"] = {n="Songblade Search",s="“寻回歌刃”是一项矮人任务，多林·歌刃请求旅行者们去湿地确认他兄弟达文的情况。达文带着一支来自洛克莫丹的考古队出发去未被探索的丘陵挖掘，但他一反常态的沉默让他的兄弟深感不妙。",h="“寻回歌刃”是一项矮人任务，多林·歌刃请求旅行者们去湿地确认他兄弟达文的情况。达文带着一支来自洛克莫丹的考古队出发去未被探索的丘陵挖掘，但他一反常态的沉默让他的兄弟深感不妙。",kw={"达文·歌刃","dls","多林·歌刃","洛克莫丹","songblade search","湿地","维尔加挖掘场"},ang={["faction:Alliance"]="往返于洛克莫丹和米奈希尔港之间的联盟旅行者经常会经过这些挖掘场，为陷入困境的矮人探矿者和工匠们提供帮助。",["race:Dwarf"]="矮人探险队和考古挖掘在卡兹莫丹随处可见，但走出洛克莫丹的安全范围，进入危险的湿地，往往会给族人带来巨大的风险。"},sec={{t="兄弟的担忧",b="多林·歌刃留在了他的工作室里，因为忙于重新装配皮带扣的订单而抽不开身，而他的兄弟达文则加入了一支从洛克莫丹出发的矮人挖掘队。达文北上进入了湿地崎岖的丘陵，渴望探索尚未被矮人镐头触及的处女地。然而，达文通常在抵达后会立刻写信，他的沉默让多林深感不安。"},{t="湿地的挖掘",b="前往湿地的旅行者们可以在维尔加挖掘场的挖掘者中找到达文·歌刃。达文与他的兄弟多林长得非常像，他带着一把独特的步枪，枪托上刻着“DLS”的缩写，这证明他确实到达了这片沼泽地中偏远的挖掘营地。"}},faq={{q="谁发布了“寻回歌刃”这个任务？",a="多林·歌刃发布了这个任务。他是一位工匠，目前正忙于重新装配一大堆皮带扣，这让他无法陪同他的兄弟进行考古挖掘。",al={"谁发布了寻回歌刃","寻回歌刃任务发布者","多林·歌刃"}},{q="达文·歌刃是谁？",a="达文·歌刃是多林·歌刃的兄弟。他与一支从洛克莫丹出发的挖掘队一起前往湿地那片未驯服的丘陵，但并没有像他通常做的那样寄回消息。",al={"多林的兄弟是谁","失踪的歌刃矮人","达文·歌刃"}},{q="在哪里可以找到达文？",a="达文位于湿地的维尔加挖掘场。你可以通过他与多林极其相似的长相，以及他那支枪托上刻有“DLS”字样的火枪来辨认他。",al={"达文在哪里","去哪找达文·歌刃","寻回歌刃地点"}},{q="达文为什么要去湿地？",a="达文加入了一支从洛克莫丹出发的矮人挖掘探险队，前往湿地寻找未知的丘陵进行考古挖掘。",al={"为什么达文去了湿地","维尔加挖掘场的目的","矮人们为什么去湿地"}},{q="刻在枪上的缩写是什么意思？",a="刻在火枪枪托上的“DLS”缩写属于达文·歌刃，这证实了在挖掘场发现的那名矮人确实是多林失踪的兄弟。",al={"dls代表什么","dls枪上的刻字","dls缩写"}},{q="多林为什么担心他的兄弟？",a="多林感到担忧是因为达文在踏上旅程后通常会及时回信。在前往湿地后迟迟没有收到信件，多林有一种不安的预感，觉得出事了。",al={"多林为什么担心","为什么要寻找达文","寻回歌刃的原因"}}},fp="16,280,18.413.0,23.320.1,37.181.0,24.201.0,26.191.0,38.141.0,44.161.0,40.228.0"}
P.entries["quest:95774"] = {n="Her Name Is Olgra",s="得知奥格拉在战斗中阵亡后，曼科里克决心为她建造一座长存的纪念碑。他请你从附近的剃刀沼地掠夺者手中找回她遗失的骨饰，好让它们陪伴在她的纪念碑旁。",h="得知奥格拉在战斗中阵亡后，曼科里克决心为她建造一座长存的纪念碑。他请你从附近的剃刀沼地掠夺者手中找回她遗失的骨饰，好让它们陪伴在她的纪念碑旁。",kw={"饰品","曼科里克","纪念碑","奥格拉","抛光骨头","野猪人","剃刀沼地掠夺者"},sec={{t="缅怀逝者",b="尽管一位治疗者设法救下了曼科里克，奥格拉却在战场上伤重不治。悲痛的战士决心让她的名字与牺牲永不被遗忘，正准备建造一座长存的纪念碑，以纪念她。"},{t="遗失的珍爱之物",b="奥格拉佩戴着珍爱的抛光骨饰，但这些饰品已不在她的安息之地。曼科里克想从附近的剃刀沼地掠夺者手中找回这些私人物品，让它们陪伴在他为她建造的纪念碑旁。"}},faq={{q="奥格拉是谁？",a="奥格拉在与野猪人的战斗中阵亡。曾帮助曼科里克的治疗者设法救下了他，却没能救回她。曼科里克打算永远缅怀她。",al={"奥格拉是谁","曼科里克的妻子","谁死了"}},{q="奥格拉的饰品是什么？",a="她的饰品是用抛光骨头制成的珍贵手工珠宝，她在遇害前一直佩戴着它们。",al={"奥格拉的饰品是什么","奥格拉的珠宝","饰品是什么做的"}},{q="为什么要追捕剃刀沼地掠夺者？",a="奥格拉倒下后，她的饰品被人拿走了。曼科里克因此派你前往她遇害地点附近，对付剃刀沼地掠夺者并找回饰品。",al={"为什么杀剃刀沼地掠夺者","谁偷了奥格拉的饰品","饰品在哪里"}},{q="曼科里克会如何处置找回的饰品？",a="曼科里克打算将找回的骨饰放在他为奥格拉建造的纪念碑旁，让她的记忆永不褪色。",al={"曼科里克的纪念碑","曼科里克会如何处置饰品","曼科里克为什么想要饰品"}}},fp="17,220,19.236.0,14.238.0,13.173.0,28.116.0,43.157.0,51.139.0"}
P.entries["quest:95795"] = {n="Fallen in the Fen",s="\"Fallen in the Fen\" 是一段忧伤的旅程，始于在挖掘场中发现一名倒下的矮人。将这个悲剧性的消息告知他在湖畔镇的兄弟Dorin Songblade，为这位心碎的工匠带来了一个了结，他原本一直为他逝去的亲人锻造礼物。",h="\"Fallen in the Fen\" 是一段忧伤的旅程，始于在挖掘场中发现一名倒下的矮人。将这个悲剧性的消息告知他在湖畔镇的兄弟Dorin...",kw={"铁匠","dorin","dorin songblade","矮人","挖掘","挖掘场","fallen in the fen","湖畔镇","songblade"},ang={["faction:Alliance"]="为赤脊山的一位工匠带来慰藉，为在这王国动荡时期悲痛的城镇居民提供了一丝安抚。",["profession:Blacksmithing"]="Dorin将他的手艺倾注在原本打算给亲人的惊喜装备上，这些装备现在只能作为他兄弟英年早逝的提醒。",["race:Dwarf"]="矮人们理解失去兄弟于古老挖掘场和荒野中的苦痛，尤其是当锻造的金属比本应握住它们的手存在得更久时。"},sec={{t="挖掘场惨剧",b="挖掘场发生了一起静悄悄的悲剧，人们在那里发现了一具爱冒险的矮人的遗体。在用那名矮人自己的斗篷覆盖遗体后，一位冒险者将这沉痛的消息带回湖畔镇，去寻找他的亲人。"},{t="兄弟的悲痛",b="在湖畔镇，矮人工匠Dorin Songblade得知兄弟的命运后崩溃了。Dorin曾花了几周时间在铁匠铺工作，为他的兄弟锻造了一套惊喜装备，但没能赶在探险队出发前完成。他因没有一同前往而深感懊悔，无法忍受重铸或出售自己亲手打造的作品，于是决定将成品赠送给带回消息的人。"}},faq={{q="什么是Fallen in the Fen？",a="\"Fallen in the Fen\" 是一项沉重的任务，始于在挖掘场发现一名倒下的矮人的遗体。用他的斗篷覆盖遗体后，你前往湖畔镇，亲自将他的命运告知这位悲痛的兄弟，Dorin Songblade。",al={"什么是fallen in the fen","fallen in the fen 任务"}},{q="谁是Dorin Songblade？",a="Dorin Songblade是一位居住在湖畔镇的矮人铁匠。在得知挖掘场的惨剧之前，他一直在锻造装备作为送给兄弟的惊喜礼物。",al={"谁是dorin songblade","湖畔镇的dorin","dorin songblade的角色"}},{q="在挖掘场发现的倒下的矮人是谁？",a="在挖掘场发现的倒下的矮人是Dorin Songblade的兄弟。他最近刚路过湖畔镇为他的探险收集物资，随后在野外丧生。",al={"谁在fen中死了","挖掘场死去的矮人","谁的遗体在挖掘场"}},{q="在哪里可以找到Dorin Songblade？",a="可以在赤脊山的主要定居点湖畔镇找到Dorin Songblade，他在那里从事铁匠工作。",al={"dorin songblade在哪里","dorin songblade的位置"}},{q="Dorin在为他的兄弟锻造什么？",a="Dorin一直在忙着锻造打算送给兄弟的惊喜装备。遗憾的是，这份工作没能在兄弟出发探险前完成，这让他心碎不已，留下了他无法忍受保留或出售的装备。",al={"dorin在锻造什么","dorin的惊喜礼物"}},{q="为什么Dorin要把他制作的物品送人？",a="沉浸在没能陪同兄弟的悲伤和懊悔中，Dorin不想重铸或出售他辛苦打造的武器。他将成品赠送给带回他亲人消息的旅人，以示感激。",al={"为什么dorin送出了装备","为什么dorin给你装备"}}},fp="17,263,18.237.0,17.442.1,26.255.0,23.178.0,48.206.0,35.127.0,39.229.0,46.228.0"}
P.entries["quest:95805"] = {n="Grace of An'she and Mu'sha",s="Grace of An'she and Mu'sha是一场神圣的牛头人朝圣之旅，在红云台地进行，旨在纪念作为大地母亲天界双眼的太阳和月亮。通过将易碎、闷燃的香火带到东南丘陵的一座高处祭坛，旅行者们向这些为平原带来温暖、生命和指引的天界之光表达敬意。",h="Grace of An'she and...",kw={"an'she","大地母亲","月亮","mu'sha","莫高雷","红云台地","祭坛","闷燃的香火","太阳","牛头人"},ang={["class:Druid"]="牛头人德鲁伊将太阳和月亮的永恒之舞视为平衡的原始体现，指引着他们对自然宇宙韵律的理解。",["class:Shaman"]="虽然萨满直接与土、火、水、风的尘世之灵沟通，但他们同样向这对天界孪生神祇致敬，它们的光芒维系着所有的生命能量。",["faction:Horde"]="在台地上进行的圣礼展示了游牧的牛头人带给部落盟友的那种深厚的、尊崇自然的文化。",["race:Tauren"]="对An'she和Mu'sha的敬畏是牛头人精神身份的核心，提醒年轻的勇士们，生活不仅需要像忠于大地母亲一样，还要忠实地敬奉这两道天界孪生之光。"},sec={{t="大地母亲的双眼",b="在牛头人的神话中，太阳和月亮被称为An'she和Mu'sha，被尊为大地母亲的双眼。虽然元素之灵直接居住在艾泽拉斯的岩石、风和水中，但这两位天界孪生神祇却在天界的至高处注视着这个世界。它们在天空中永恒的旅程标记着昼夜的永恒节奏，为所有生物带来温暖、指引和希望。纪念这两位孪生神祇是一项基本的精神职责，它教导我们要明白平衡不仅需要敬畏脚下的土地，也要敬畏从天而降的光芒。"},{t="高地上的祭礼",b="为了纪念这两位天界孪生神祇，朝圣者必须携带闷燃的香火前往俯瞰台地的东南丘陵，那里坐落在多刺的野猪人领地以南。这段旅程是对专注力和速度的考验：芬芳的余烬必须在燃尽成冰冷的灰烬之前送达，旅行者在沿途必须小心，避免让香火沾水。到达高处的祭坛后，朝圣者将余烬投入圣火中，让芳香的烟雾带着他们的敬意升入天空，飘向太阳和月亮。"}},faq={{q="An'she和Mu'sha是谁？",a="An'she和Mu'sha是牛头人神话中的太阳和月亮，被尊为大地母亲的双眼。与土、风、火、水之灵不同，它们并不直接居住在艾泽拉斯的土地中。相反，它们从上方的苍穹照亮世界，An'she提供温暖和生命，而Mu'sha则提供夜间的指引和慰藉。",al={"anshe和musha是谁","anshe和musha背景故事","牛头人的太阳和月亮神"}},{q="为什么牛头人要向太阳和月亮献祭？",a="牛头人的哲学教导说，平衡对万物的存在至关重要。虽然尘世之灵掌管着眼前的景观，但An'she和Mu'sha的光芒为所有生物赋予了至关重要的能量、远见和希望。在高处献上闷燃的香火是一种相互尊重的行为，承认凡人的生命若没有这两个天体的持续恩泽就无法繁荣。",al={"为什么要敬畏太阳和月亮","牛头人的天界崇拜","为什么要纪念anshe和musha"}},{q="An'she和Mu'sha的祭坛位于何处？",a="An'she和Mu'sha的祭坛位于台地东南方的高丘之上。它俯瞰着下方的广阔平原，坐落在多刺的野猪人领地以南。其高海拔提供了开阔、无遮挡的视野，使其成为向天空升起烟雾的理想之地。",al={"anshe祭坛在哪里","祭坛位置 莫高雷","如何找到香火祭坛"}},{q="闷燃的香火有什么意义？",a="闷燃的香火是祈祷和敬意的有形媒介。当芬芳的余烬燃烧时，升起的烟雾将旅行者的虔诚直接带向天空，飘向太阳和月亮。将余烬投入祭坛圣火标志着仪式的结束，让朝圣者获得一种宁静的精神满足感。",al={"香火有什么作用","香火供奉的含义","为什么要燃烧闷燃的香火"}},{q="为什么要快速运送香火并保持干燥？",a="该仪式要求朝圣者保持警惕、速度和小心。香火投入祭坛圣火时必须仍处于闷燃状态，这意味着旅程必须在余烬烧成冷灰之前完成。此外，浸入水中会立即熄灭余烬，在祭品到达高处之前就将其毁坏。",al={"为什么要给香火计时","不要弄湿它","香火燃尽"}},{q="野猪人会威胁到前往祭坛的朝圣之旅吗？",a="野猪人部落占据了祭坛位置以北丘陵中防御严密的棘刺巢穴。虽然祭坛本身位于他们领地南侧的一处安静观景点，但旅行者必须小心不要误入野猪人的荆棘丛，因为敌对攻击很容易延误或破坏这一精细的旅程。",al={"祭坛附近的野猪人","野猪人会威胁朝圣者吗","台地南部的野猪人"}},{q="Mu'sha与其他文化对月亮的看法有何不同？",a="牛头人神话将月亮视为Mu'sha，即大地母亲充满慈爱、注视着凡人生命的左眼。艾泽拉斯的其他种族，尤其是暗夜精灵，将同一轮明亮的白色月亮尊为女神Elune，但牛头人传统认为她与其太阳孪生兄弟An'she有着不可分割的联系。",al={"musha是elune吗","牛头人的月亮与elune","musha与暗夜精灵"}}},fp="26,342,27.602.0,26.548.0,26.366.0,53.398.0,49.314.0,51.336.0,55.353.0,54.310.0,61.306.0"}
P.entries["quest:95809"] = {n="Heartwoven",s="Heartwoven 是湿地的一个联盟任务，讲述了一个关于生存与关爱的简单故事。在为一名被困在沼泽中的采集者清理出逃生路线后，冒险者将一颗手工编织的芦苇心带回米奈希尔港交给凯特琳·格拉斯曼。",h="Heartwoven 是湿地的一个联盟任务，讲述了一个关于生存与关爱的简单故事。在为一名被困在沼泽中的采集者清理出逃生路线后，冒险者将一颗手工编织的芦苇心带回米奈希尔港交给凯特琳·格拉斯曼。",kw={"凯特琳·格拉斯曼","格拉斯曼","heartwoven","米奈希尔港","芦苇心","芦苇","湿地"},ang={["faction:Alliance"]="米奈希尔港是湿地的一个关键联盟港口，这里的普通平民依赖过往的旅行者来确保危险的沼泽路线安全。",["profession:Cooking"]="收到芦苇心并得知丈夫幸存后，凯特琳立即着手准备一顿温暖丰盛的饭菜，欢迎他回家。"},sec={{t="来自沼泽的信号",b="在湿地险恶的沼泽中，生活与劳作总是伴随着危险。阿丁·格拉斯曼前往挖掘场查看奇异的草丛，却发现自己被困在沼泽的重重危机之中，直到一位路过的旅人清理出了一条荒野之路。他虽然精疲力竭，但意志坚定，在返回港口避难之前，他停下来喘口气，并整理好自己的收获。"},{t="米奈希尔的信物",b="在踏上归途之前，采集者从包里拿出沼泽芦苇，编织成了一颗草心。他将这件信物交给冒险者，请其带往米奈希尔港交给凯特琳·格拉斯曼。在这个繁忙的沿海定居点，凯特琳在深深的忧虑中等待着，当听说他幸存下来并很快就会回来享用热腾腾的饭菜时，她如释重负，将那颗编织的芦苇心紧紧地贴在胸前。"}},faq={{q="Heartwoven 是什么任务？",a="Heartwoven 是湿地的一个联盟任务。一位冒险者帮助了被困在沼泽挖掘场地的阿丁·格拉斯曼，他用芦苇制作了一件编织信物，作为生存和爱的信息，委托其交给米奈希尔港的凯特琳·格拉斯曼。",al={"heartwoven 任务","heartwoven 是什么","湿地 heartwoven"}},{q="凯特琳·格拉斯曼是谁？",a="凯特琳·格拉斯曼是一位焦急地在米奈希尔港等待的联盟居民。她为丈夫阿丁的安危感到担忧，因为他深入湿地危险的挖掘场地，当你带去他幸存的消息时，她感到无比宽慰。",al={"凯特琳·格拉斯曼是谁","凯特琳 米奈希尔港","凯特琳·格拉斯曼"}},{q="芦苇编织的心是什么？",a="芦苇编织的心是那位被困的采集者用行囊里的沼泽芦苇手工制作的信物。他匆忙编织它，是为了证明自己还活着，并很快就能回家，以此让家人安心。",al={"芦苇心是什么","用芦苇编织的心","芦苇编织的心"}},{q="在哪里交 Heartwoven 任务？",a="该任务最终需要交给凯特琳·格拉斯曼，她正在湿地西海岸的联盟港口城市米奈希尔港等待。",al={"哪里交 heartwoven 任务","heartwoven 交任务地点","凯特琳·格拉斯曼在哪里"}},{q="谁发布了 Heartwoven 任务？",a="该任务由凯特琳的丈夫阿丁·格拉斯曼发布，他在湿地的挖掘场地中幸存了下来。在一位冒险者为他清理出一条安全通道后，他休息片刻，收集好自己的收获，并将一件手工制作的信物交给冒险者带给凯特琳。",al={"谁发布 heartwoven 任务","谁制作了那颗心","heartwoven 幸存者"}},{q="被困的采集者遭遇了什么？",a="阿丁前往挖掘场地查看奇异的高大草丛，却因受惊的野生动物（尤其是蜘蛛）袭击了挖掘队而被困。多亏了一位冒险者清理了周围的威胁，他才得以幸存，并能安全地收集好自己的收获，返回米奈希尔港。",al={"采集者遭遇了什么","他幸存了吗","heartwoven 幸存者"}}},fp="10,263,25.409.0,18.392.0,29.261.0,24.263.0,29.209.0,32.140.0,35.268.0,39.319.0"}
P.entries["quest:95810"] = {n="Lost Relic Carry",s="“Lost Relic Carry”涉及回收一件古代岩石机械自动体的残片，并将其送交给湿地的勘察员维尔加。这件圣物的成分材质未知，暗示了泰坦高超的工程技术，这令矮人研究者对其肃然起敬。",h="“Lost Relic Carry”涉及回收一件古代岩石机械自动体的残片，并将其送交给湿地的勘察员维尔加。这件圣物的成分材质未知，暗示了泰坦高超的工程技术，这令矮人研究者对其肃然起敬。",kw={"自动体","挖掘场","探险者协会","lost relic carry","勘察员维尔加","岩石机械","泰坦圣物","湿地"},ang={["profession:Engineering"]="岩石机械自动体的复合材质和精密设计暗示了远超标准凡人工程学的先进机械原理。",["race:Dwarf"]="探险者协会的矮人探险家们痴迷于发掘他们制造者的古代圣物，这使得这件自动体碎片成为矮人遗产中一件珍贵的发现。"},sec={{t="古代工艺的碎片",b="在古老之地的深处，冒险者可以发掘出一件岩石机械自动体的残损组件。它并非普通的碎石，其独特的复合材质揭示了一种与泰坦相关的、先进古代机械的工艺水准。"},{t="运往挖掘场",b="勘察员维尔加驻扎在湿地的挖掘场，负责研究古代遗迹。将圣物从危险中带出并交给他，为那些探索古代遗产的矮人学者提供了宝贵的实物证据。"}},faq={{q="什么是泰坦圣物？",a="这件圣物是一件古代岩石机械自动体的残片。它并非普通的石块碎片，而是由一种未知的复合材料构成，显然曾是某种精密机械装置的一部分。",al={"什么是圣物","物品是什么","岩石机械碎片"}},{q="勘察员维尔加是谁？",a="勘察员维尔加是一位矮人研究者，负责监管湿地的挖掘场。他研究在该地区挖掘点发现的古代土灵遗骸和圣物。",al={"维尔加是谁","维尔加背景","挖掘场负责人"}},{q="圣物需要送到哪里？",a="圣物需送到位于湿地的挖掘场交给勘察员维尔加，那里是矮人挖掘者调查古代遗迹的地方。",al={"我该送到哪里","去哪里交任务","维尔加位置"}},{q="是什么制造了岩石机械自动体？",a="该自动体碎片被确认为泰坦圣物。在矮人传说中，古代机械构装体和岩石自动体都与塑造世界的神秘泰坦有关。",al={"谁制造了岩石机械","自动体起源","泰坦关联"}},{q="为什么勘察员维尔加对圣物如此敬重？",a="冒险进入这些自动体栖息的深处极其危险。维尔加指出，能够从探索中幸存并带回这样一件完好的碎片，确实令人敬佩。",al={"为什么维尔加印象深刻","危险探索"}},{q="自动体的材质有什么不同寻常之处？",a="这种材料是一种独特的复合材料，具有不同于普通石材或锻造金属的陌生质感，展现了古代泰坦构装体高深而神秘的工艺。",al={"材质是什么","奇怪的复合材料"}}},fp="16,290,27.241.0,26.245.0,24.212.0,26.184.0,42.142.0,37.177.0,59.183.0,47.181.0"}
P.entries["quest:95883"] = {n="The Tortured Soul",s="“被折磨的灵魂”是一个围绕银松森林中博伦的巢穴内一处匆忙搭建的仪式祭坛展开的任务。为了推进一张被遗弃的字条上所记载的黑暗仪式，冒险者们必须从附近危险的峭壁中收集一个饱受折磨的灵魂。",h="“被折磨的灵魂”是一个围绕银松森林中博伦的巢穴内一处匆忙搭建的仪式祭坛展开的任务。为了推进一张被遗弃的字条上所记载的黑暗仪式，冒险者们必须从附近危险的峭壁中收集一个饱受折磨的灵魂。",kw={"博伦的巢穴","邪恶能量","鲜血献祭","祭祀之石","仪式","银松森林","被折磨的灵魂"},ang={["class:Priest"]="该仪式依赖于从受苦灵魂中撕裂出的邪恶能量，这与圣光的修复原则截然对立。",["class:Warlock"]="引导受折磨的灵魂并在古代祭祀之石（The Offering Stone）上进行黑暗仪式，反映了恶魔和暗影魔法那冷酷且具有操纵性的本质。",["race:Undead"]="银松森林是被遗忘者的领土，黑暗魔法的残余和挥之不去的苦难时刻威胁着洛丹伦的边界。"},sec={{t="仓促的仪式",b="在银松森林的博伦的巢穴里，坐落着一座祭坛，上面残留着一场匆忙搭建的黑暗仪式的痕迹。在杂乱无章的陈设中留有一张潦草的字条，上面显示大部分材料都已备齐，只剩下献祭鲜血和收集一个被折磨的灵魂来完成这项工作。"},{t="释放邪恶能量",b="栖息在博伦的巢穴峭壁中的生物承受着剧烈的痛苦，使它们成为获取仪式所需被折磨精华的主要目标。将收集到的灵魂呈现给那块阴森的祭祀之石（The Offering Stone），会激发出汹涌的邪恶魔法能量，推动仪式向完成迈进。"}},faq={{q="什么是“被折磨的灵魂”？",a="“被折磨的灵魂”是设定在银松森林博伦的巢穴的一项任务。它涉及调查祭祀之石（The Offering Stone）上一个未完成的黑暗仪式，并寻找附近受折磨生物的灵魂以补全仪式的要素。",al={"什么是被折磨的灵魂任务","被折磨的灵魂银松森林","博伦的巢穴任务"}},{q="这个仪式在哪里进行？",a="仪式祭坛及其阴森的祭祀之石（The Offering Stone）位于博伦的巢穴，这是一个坐落在银松森林中多山且危险的飞地。",al={"仪式在哪里","博伦的巢穴在哪里","祭祀之石位置"}},{q="仪式需要什么组件？",a="根据留在祭坛上的一张字条残片，除了两个关键组件——鲜血献祭和被折磨的灵魂——之外，几乎所有的材料都已仓促备齐。",al={"仪式需要什么","博伦的巢穴仪式组件"}},{q="你在哪里可以找到被折磨的灵魂？",a="任务文本指出，附近栖息在博伦的巢穴的生物看起来饱受折磨，足以产出激活祭祀之石（The Offering Stone）所需的精华。",al={"去哪里获取被折磨的灵魂","谁有灵魂"}},{q="当被折磨的灵魂被带到祭坛时会发生什么？",a="将被折磨的灵魂带到祭祀之石（The Offering Stone）处会使其散发出邪恶的能量，使黑暗仪式离完成更近了一步。",al={"带来灵魂后会发生什么","提交被折磨的灵魂"}},{q="是谁在博伦的巢穴创造了仪式？",a="仪式的具体创造者未被说明，但字条和匆忙收集的材料表明，某人在博伦的巢穴的敌对居民中极度仓促地逃离或搭建了祭坛。",al={"谁制造了仪式","谁写了字条"}}},fp="17,261,12.295.0,23.301.1,26.235.0,34.146.0,44.173.0,36.153.0,60.143.0,40.197.0"}
P.entries["quest:95884"] = {n="The Offering Stone",s="The Offering Stone是一座隐藏在银松森林博伦的巢穴中的仪式祭坛。通过一张破烂的笔记碎片，人们发现了这块石头，上面散落着奇怪的器具和用于某种未知献祭的物品。对该地点的调查显示，在这片阴暗的荒野中，正有活跃的仪式准备活动在进行。",h="The Offering...",kw={"博伦的巢穴","器具","offering stone","仪式","笔记碎片","银松森林","the offering stone"},ang={["class:Warlock"]="看到一块散落着黑暗器具的献祭之石，意味着这里有仪式性的行为，值得黑暗艺术的修行者密切研究。",["faction:Horde"]="保卫银松森林的被遗忘者和部落冒险者必须对徘徊在博伦的巢穴阴暗岩隙中的可疑仪式和邪教活动保持警惕。"},sec={{t="破烂的笔记",b="这是一张在银松森林发现的风化纸片，上面记载着奇怪的仪式准备活动。虽然时间和潮湿使得大部分文字已无法辨认，但残留的碎片足以让人发现关于一个仪式和附近一块献祭之石的记载。顺着这些线索进入博伦的巢穴的岩隙中，旅行者们就能找到藏在荒野中的那座粗糙祭坛。"},{t="仪式地点",b="在博伦的巢穴找到The Offering Stone后，其粗糙的表面显露出近期令人不安的活动迹象。奇怪的器具和物品散落在岩石上，证实有人一直在此地活跃，在远离窥探视线的地方进行献祭或黑暗仪式。"}},faq={{q="什么是The Offering Stone？",a="The Offering Stone是一座位于银松森林博伦的巢穴内的风化石祭坛。它似乎是某种神秘准备工作和黑暗仪式的焦点，上面散落着奇怪的器具和仪式用品。",al={"什么是offering stone","银松森林offering stone","这是什么石头"}},{q="在哪里可以找到The Offering Stone？",a="The Offering Stone位于博伦的巢穴，这是一个位于银松森林南部的多岩且危险的区域。",al={"offering stone在哪里","offering stone位置","寻找offering stone"}},{q="谁创造或使用了The Offering Stone？",a="附近发现的破损笔记让仪式参与者的身份变得模糊，但留在石头上的工具和物品表明，有人一直在该地区积极筹备某种献祭或黑暗仪式。",al={"谁制造了offering stone","谁在使用offering stone","谁在进行仪式"}},{q="那张神秘的笔记上写了什么？",a="这张笔记碎片大多已风化且难以辨认，但仍能辨认出的碎片清楚地描述了即将到来的仪式的准备工作，并指出了附近存在一块献祭之石。",al={"什么笔记","银松森林笔记碎片","笔记上写了什么"}},{q="在The Offering Stone上发现了什么？",a="石头的粗糙表面上散落着奇怪的工具、仪式器具以及为了献祭而摆放的各种物品。",al={"石头上有什么物品","石头上有什么器具","offering stone物品"}},{q="这里正在进行什么样的仪式？",a="虽然笔记中残存的碎片并未完全详述仪式的具体性质，但这块石头被专门布置成了一个祭坛，上面摆放着用于仪式的物品或祭品。",al={"offering stone是什么仪式","为什么要设offering stone","银松森林有什么献祭"}}},fp="18,321,15.390.0,15.301.0,27.231.0,38.123.0,39.200.0,34.180.0,36.131.0,44.196.0"}
P.entries["quest:95885"] = {n="The Offering of Blood",s="The Offering of Blood 是在博伦的巢穴的 The Offering Stone 处进行的一种神秘仪式。冒险者需要利用一个被折磨的灵魂，按照字条碎片的指示，在祭坛处献上鲜血祭品。",h="The Offering of Blood 是在博伦的巢穴的 The Offering Stone 处进行的一种神秘仪式。冒险者需要利用一个被折磨的灵魂，按照字条碎片的指示，在祭坛处献上鲜血祭品。",kw={"博伦的巢穴","血祭仪式","the offering of blood","the offering stone","祭品","银松森林","被折磨的灵魂"},ang={["class:Priest"]="关注逝者灵魂命运的牧师们会认为，在不祥的血祭仪式中使用被折磨的灵魂在道德上令人不安，无论这是否能让该实体安息。",["class:Warlock"]="术士们对黑暗仪式和与灵魂进行交易早已习以为常，尽管即使是经验丰富的邪能修炼者，在面对一块未知的古代祭坛进行血祭时，也会感到一阵寒意。"},sec={{t="最终仪式",b="在博伦的巢穴的峭壁深处，伫立着 The Offering Stone，这是一个等待着最后黑暗交易的不祥遗物。根据要求进行自愿牺牲的废弃字条碎片上的线索，冒险者们被引导着带上所需的鲜血祭品，以满足祭坛残留的魔法。带着那种躁动不安的精华靠近祭坛，会给人一种难以名状的恐惧感。"},{t="击碎祭坛",b="将被折磨的灵魂献给祭坛会引发剧烈的反应，将残留的力量从这座古代遗迹中抽干。鲜血仪式并没有唤醒更大的恐怖，反而彻底耗尽了该遗物的能量。失去奥术目的后，粗糙的石块开裂并坍塌成瓦砾，显露出埋藏在破碎残骸中的闪亮奖励。"}},faq={{q="这个仪式在哪里进行？",a="The Offering of Blood 仪式是在银松森林内博伦的巢穴的 The Offering Stone 处进行的。该地区充满了危险，并笼罩在黑暗且挥之不去的魔法阴影之下。",al={"这个任务在哪里","the offering of blood 在哪里","博伦的巢穴任务"}},{q="什么是 The Offering Stone？",a="The Offering Stone 是位于博伦的巢穴的一座神秘古代遗迹。它需要一种黑暗仪式——具体来说，是来自自愿牺牲者的鲜血祭品——来解锁或排空沉睡在其中的力量。",al={"什么是 the offering stone","博伦的巢穴的 the offering stone","博伦的巢穴的祭坛"}},{q="被折磨的灵魂有什么用？",a="该仪式需要一个被折磨的灵魂，充当被发现的字条碎片中提到的“自愿牺牲者”。将这个灵魂呈献在 The Offering Stone 前，即可满足这座古代遗物所要求的鲜血祭品。",al={"谁是被折磨的灵魂","什么是被折磨的灵魂","需要什么祭品"}},{q="当祭品完成后会发生什么？",a="仪式完成后，赋予 The Offering Stone 生命的黑暗能量会被完全抽干。由于失去了存在的意义，这块粗糙的石头会开裂并崩解，在残骸中留下一件闪闪发光的东西。",al={"祭坛会发生什么","祭坛会破碎吗","仪式后会发生什么"}},{q="谁建造了这座祭坛，为什么？",a="这座祭坛的具体起源和最终目的仍然是一个谜。虽然成功完成仪式会抽干其潜在能量并将其摧毁，但究竟是谁最初建造了这座纪念碑，以及其背后的宏大设计为何，至今仍不得而知。",al={"谁建造了 the offering stone","the offering of blood 的目的","为什么建造祭坛"}},{q="什么是博伦的巢穴？",a="博伦的巢穴是银松森林中一个以野兽和隐藏危险而闻名的岩石地标。The Offering Stone 的存在表明，黑暗仪式和躁动不安的灵魂也曾在这里留下了痕迹。",al={"什么是博伦的巢穴","博伦的巢穴背景故事","为什么叫博伦的巢穴"}}},fp="21,202,14.388.0,18.371.1,34.176.0,27.217.0,35.211.0,44.213.0,30.244.0,22.216.0"}
P.entries["quest:959"] = {n="港口的麻烦",s="起重机操作员比戈弗兹在棘齿城的码头上引发了一场笨拙的货物事故，让一个名叫疯狂的马格利什的小混混趁乱抢走了一瓶无价的陈年佳酿。这瓶99年波尔多陈酿是由大财主里维加兹直接寄给加兹鲁维的，必须在码头管理员开除这个粗心的起重机操作员之前从哀嚎洞穴的阴影中找回来。",h="起重机操作员比戈弗兹在棘齿城的码头上引发了一场笨拙的货物事故，让一个名叫疯狂的马格利什的小混混趁乱抢走了一瓶无价的陈年佳酿。这瓶99年波尔多陈酿是由大财主里维加兹直接寄给加兹鲁维的，必须在码头管理员开除这个粗心的起重机操...",kw={"比戈弗兹","藏宝海湾","加兹鲁维","马格利什","波尔多陈酿","棘齿城","里维加兹","哀嚎洞穴"},ang={["class:Rogue"]="追踪疯狂的马格利什需要善于发现拙劣的伪装，因为这个小偷依靠在洞穴缝隙中进行初步的潜行来逃避关注。",["faction:Alliance"]="尽管在部落控制的贫瘠之地深处运营，但与热砂港的港口经营者保持良好关系可以确保在中立水域的安全通行。",["faction:Horde"]="协助棘齿城的码头工人有助于维持连接卡利姆多和东部王国的主要中立港口的顺利运营。"},sec={{t="笨拙的事故",b="棘齿城依靠与藏宝海湾跨越无尽之海的持续海上贸易而繁荣，但其地精的效率有时会在巨大的货运量下出现问题。当一批异常庞大的早间货物抵达港口时，起重机操作员比戈弗兹为了加快卸货过程试图走捷径。他吊起的货物远远超过了起重机的负荷，导致整批货物在码头上摔了个粉碎。在随后的混乱中，当地一个麻烦人物名叫疯狂的马格利什趁着货物撒落之机，抢走了一瓶珍贵的酒，并逃往了内陆。"},{t="外交赠礼",b="被盗的货物远不止是码头上普通的酒水。这瓶酒是99年波尔多陈酿，是大财主里维加兹（藏宝海湾臭名昭著的黑水海盗头目）作为私人外交礼物送给加兹鲁维（棘齿城的总工程师兼监督者）的。丢失这样一份奢华的礼物不仅会让比戈弗兹丢脸，还会激怒这两位贸易大亨。为了保住饭碗，或者避免更糟的后果，比戈弗兹追踪小偷来到了哀嚎洞穴那令人毛骨悚然的洞口，但恐惧让他不敢追随马格利什深入其中。"},{t="洞穴藏身处",b="疯狂的马格利什并没有冒险进入地下城本身那腐化的梦境深处，而是选择躲藏在内部门户之外那片蔓延且潮湿的天然隧道中。依靠着笨拙的潜行和阴暗的壁龛，马格利什在这些地下洞穴中潜行，希望追捕者能放弃。要找回这瓶酒，就必须在美酒被开瓶或损坏之前，将这个小偷从外围区域驱赶出来。"}},faq={{q="为什么这瓶酒如此重要？",a="这瓶99年波尔多陈酿不是普通的劣酒；它是藏宝海湾的大财主里维加兹送给棘齿城老板加兹鲁维的一份奢侈的私人礼物。在码头事故中弄丢了它，可能会严重激怒棘齿城的领导层，并导致起重机操作员比戈弗兹丢掉饭碗。",al={"为什么比戈弗兹会在意","什么是99年波尔多陈酿","为什么酒很重要"}},{q="谁是疯狂的马格利什？",a="疯狂的马格利什是一个在棘齿城游荡的机会主义小偷和捣乱分子。当比戈弗兹在码头上把一大批货物摔落时，马格利什抢走了那瓶珍贵的酒，并直接逃进了附近的哀嚎洞穴躲藏起来。",al={"谁是马格利什","谁偷了酒","疯狂的马格利什的背景故事"}},{q="我必须进入哀嚎洞穴地下城才能找到小偷吗？",a="不用。疯狂的马格利什躲在副本入口外蜿蜒的公共洞穴通道中。他使用低级的潜行技能，潜伏在通往主入口的上层侧隧道或靠近被淹没的房间附近。",al={"马格利什在副本里吗","疯狂的马格利什在哪里","寻找马格利什"}},{q="货物事故是怎么发生的？",a="一批从藏宝海湾运来的大型货物抵达了，起重机操作员比戈弗兹试图一次卸载比他设备所能承受的更多的板条箱。超载的起重机导致货物掉落，珍贵的货物散落在棘齿城的码头上。",al={"为什么板条箱会掉落","比戈弗兹做了什么","棘齿城起重机事故"}},{q="棘齿城和藏宝海湾是什么关系？",a="这两个港口城市都是热砂港的重要据点，通过商业和私掠舰队紧密相连。定期的贸易货运和正式的礼节往来在南方的里维加兹和贫瘠之地的加兹鲁维之间进行，以维持他们共同的贸易帝国。",al={"棘齿城和藏宝海湾的联系","热砂港港口","里维加兹和加兹鲁维"}},{q="为什么比戈弗兹没有自己找回这瓶酒？",a="比戈弗兹一直追着小偷到了哀嚎洞穴的入口，但地下迷宫那诡异的名声和其中的怪物居民把这个地精吓坏了，让他止步于洞口。",al={"为什么地精没有自己去拿","为什么比戈弗兹停止了追逐"}}},fx={b908c2b9={q="起重机操作员比戈弗兹为什么需要找回这瓶波特酒？",a="比戈弗兹的饭碗岌岌可危。他试图卸下超过起重机承载能力的货箱，结果藏宝海湾运来的整批早间货物都塌了。在一片混乱中，那瓶珍贵的九十九年陈酿波特酒不见了，从那以后，码头主管就一直紧盯着他。那瓶酒是送给棘齿城首席工程师加兹鲁维的私人礼物；如果找不回来，比戈弗兹就会立刻被解雇。",al={"比戈弗兹为什么想要波特酒","比戈弗兹的动机","为什么帮助比戈弗兹"}}},fp="20,361,15.535.0,18.522.0,18.419.0,40.271.0,20.238.0,65.208.0,31.240.0,55.258.0,50.207.0"}
P.entries["quest:95981"] = {n="Watching the Roads",s="Watching the Roads是一项由位于瑟伯切尔的暗影牧师奥利斯特发布的银松森林被遗忘者任务。任务要求冒险者们在安伯米尔附近的道路上袭击达拉然法师和看守者，以阻止肯瑞托向被遗忘者的领地运输物资。",h="Watching the Roads是一项由位于瑟伯切尔的暗影牧师奥利斯特发布的银松森林被遗忘者任务。任务要求冒险者们在安伯米尔附近的道路上袭击达拉然法师和看守者，以阻止肯瑞托向被遗忘者的领地运输物资。",kw={"安伯米尔","dalaran watcher","dalaran wizard","肯瑞托","pendants","relics","瑟伯切尔","暗影牧师奥利斯特","银松森林","watching the roads"},ang={["class:Mage"]="达拉然的法师和看守者依靠专业的圣物和魔法巡逻来确保通行，这使他们成为敌对施法者的主要目标。",["class:Priest"]="暗影牧师奥利斯特在瑟伯切尔指挥这一攻势，体现了被遗忘者神职人员在边境防御中发挥的积极作用。",["faction:Horde"]="干扰达拉然在安伯米尔周边的补给线，有助于维护部落在这一地区对抗敌对人类据点的立足点。",["race:Undead"]="确保通过银松森林的交通路线，对于被遗忘者防御边界并阻止达拉然的魔法入侵至关重要。"},sec={{t="安伯米尔公路上的紧张局势",b="在安伯米尔周围的道路上，肯瑞托始终保持着咄咄逼人的态势。自从笼罩达拉然的屏障消失后，他们的法师和警惕的哨兵加强了对银松森林边界交通的管制。被遗忘者从他们在瑟伯切尔的基地观察到了这种集结，并日益感到不安，因为他们意识到人类法师正利用这些开阔的道路，将危险的圣物和附魔吊坠运往充满争议的土地深处。"},{t="切断补给线",b="暗影牧师奥利斯特认为，没收单个吊坠不过是治标不治本。为了从源头上遏制达拉然魔法制品的流入，他派遣特工直接在公路上猎杀肯瑞托的护卫。通过清除安伯米尔附近的达拉然法师和达拉然看守者，被遗忘者试图粉碎肯瑞托对区域交通的严密封锁，并将他们的东部边境从外界的奥术干预中封锁起来。"}},faq={{q="是谁发布了Watching the Roads这个任务？",a="该任务由位于银松森林瑟伯切尔的暗影牧师奥利斯特发布并回收。他指派勇士去打击在当地贸易路线上活动的肯瑞托巡逻队。",al={"who gives watching the roads","quest giver watching the roads","where to turn in watching the roads"}},{q="为什么被遗忘者要袭击安伯米尔附近的达拉然巡逻队？",a="暗影牧师奥利斯特想要切断从达拉然运往银松森林的魔法圣物和吊坠的稳定来源。消灭安伯米尔附近道路上的法师和看守者，可以消除达拉然在被遗忘者边境的通行便利。",al={"why kill dalaran wizards","why attack ambermill roads","kirin tor silverpine purpose"}},{q="达拉然周围的屏障情况如何？",a="据暗影牧师奥利斯特所言，笼罩达拉然的防护屏障已经消失了。作为回应，肯瑞托加强了对周边道路的控制，并在巡逻安伯米尔地区时表现出明显的偏执。",al={"what happened to dalaran barrier","dalaran dome down","barrier down dalaran"}},{q="在什么地方可以找到达拉然法师和看守者？",a="达拉然法师和达拉然看守者都会在银松森林安伯米尔镇周边的道路上巡逻。他们监控交通以确保肯瑞托人员和附魔物品的顺利转移。",al={"where are dalaran watchers","ambermill patrol locations","where to find dalaran wizards"}},{q="达拉然在这些道路上运输什么样的物品？",a="肯瑞托一直在将附魔吊坠和其他魔法圣物从达拉然运出并送往银松森林。奥利斯特试图在这些制品进一步扩散到领地之前，从源头切断这条补给路线。",al={"what relics dalaran shipping","what are the pendants","ambermill pendants"}},{q="为什么肯瑞托在安伯米尔道路上如此警惕？",a="自从达拉然周围的魔法屏障消失后，肯瑞托一直对通往银松森林的道路保持着严密的监视。虽然奥利斯特注意到了他们的极度怀疑和警惕，但他们确切的动机对于瑟伯切尔的被遗忘者来说尚未确认。",al={"why is kirin tor paranoid","why are dalaran guards patrolling","kirin tor road control"}}},fp="18,263,33.480.0,24.437.0,39.205.0,62.268.0,54.243.0,52.225.0,57.239.0,60.284.0"}
P.entries["quest:95998"] = {n="The Great Outdoors",s="“大自然”是一项入门级的野外生存任务，旅者萨姆在此教导初出茅庐的冒险者如何在野外生存的艺术。通过在简易篝火旁驻足休息，旅行者们将学会如何在踏上旅程前维持体力，然后再去追求专业的专业技能。",h="“大自然”是一项入门级的野外生存任务，旅者萨姆在此教导初出茅庐的冒险者如何在野外生存的艺术。通过在简易篝火旁驻足休息，旅行者们将学会如何在踏上旅程前维持体力，然后再去追求专业的专业技能。",kw={"基础篝火","提升休息","营地设施","营地技巧","户外生存者","萨姆","the great outdoors","专业技能"},ang={["class:Hunter"]="靠山吃山、在篝火旁休息对野外追踪者来说是第二天性，但即使是经验丰富的斥候也能从掌握营地技巧中受益。",["profession:Cooking"]="篝火是野外烹饪的主要工具，学习正确的野外露营技巧为在露天之下准备食物奠定了基础。"},sec={{t="炉火边的课程",b="艾泽拉斯广袤的土地召唤着无数寻求财富、危险和名望的躁动灵魂。然而，单凭满腔热血无法保护初出茅庐的冒险者抵御刺骨的寒冷或长途跋涉的疲惫。掌握基本的野外生存技巧——知道何时停下脚步、点起篝火并积蓄力量——是每段传奇旅程赖以建立的宁静基石。萨姆的邀请为新手提供了一个驻足学习这些基本户外生存习惯的机会。"},{t="野外生存与贸易",b="在温暖的篝火旁寻找庇护所不仅仅是为了抵御夜晚的寒冷；它还提供了一种被称为“提升休息”的重要恢复时刻。经验丰富的生存专家都知道，在野外探险的持久力取决于能否在两次远征之间获得充分休息。一旦掌握了这些生存基础，工匠和采集者就可以转而关注专业技能，学习如何组装专门针对他们在野外特定工作需求的营地设施。"}},faq={{q="萨姆是谁？",a="萨姆是一位经验丰富的户外生存者和老练的旅行者，他主动承担起教导初出茅庐的冒险者野外生存基本功的责任。他欢迎四处流浪的灵魂分享他营火的温暖，同时传授实用的户外智慧。",al={"萨姆是谁","萨姆篝火任务","任务发布者"}},{q="坐在篝火旁有什么作用？",a="“提升休息”代表了在野外合适的篝火旁休息所带来的恢复效果。花时间坐在温暖舒适的环境中，可以让疲惫的冒险者恢复活力，并为前方的道路保持充沛的精力。",al={"什么是提升休息","提升休息增益","炉火休息"}},{q="为什么野外技能对冒险者很重要？",a="定居点城墙外的世界广阔而危险，这要求任何寻求财富和荣耀的流浪者必须学会如何维持生存。适当的野外生存技巧能确保旅行者在漫长的旅途中不会因疲劳而倒下。",al={"为什么要学习户外技能","为何要在野外生存","生存技能"}},{q="专业技能与野外露营有什么关系？",a="在学会如何搭建一个基本的营地后，专业技能大师可以教你如何制作专门针对你所选专业的营地设施，从而增强你在野外驻扎时的能力。",al={"专业技能露营","营地设施","之后的专业"}},{q="完成这门课程后，冒险者应该做什么？",a="一旦你在萨姆的篝火旁休息并掌握了基本的营地技巧，萨姆会敦促你去找专业训练师。在实用的工艺上精进，使你能够建造适合你专业的定制野外工作站。",al={"后续步骤","大自然任务之后","篝火任务之后"}},{q="谁可以参加“大自然”？",a="这项任务向任何踏入广阔世界的躁动灵魂开放，无论其背景或阵营如何，它是学习在道路上生存的入门课程。",al={"谁都可以做吗","谁能接取大自然任务","这是通用任务吗"}}},fp="18,291,19.479.0,20.460.0,11.258.0,47.240.0,52.235.0,48.215.0,58.210.0,37.177.0"}
P.entries["quest:95999"] = {n="WANTED: Incinerator Gar'im",s="WANTED: Incinerator Gar'im 是湖畔镇官方发布的一份悬赏，目标是盘踞在撕裂者山谷的敌对兽人指挥官。加因姆统率着一支危险的暗影施法者部队，据称他正与占据石堡要塞的黑石氏族合作。所罗门镇长为提供其死亡证明的人提供丰厚的悬赏。",h="WANTED: Incinerator Gar'im...",kw={"黑石","悬赏","加因姆","焚化者","湖畔镇","撕裂者山谷","暗影施法者","所罗门"},ang={["class:Mage"]="加因姆和他的暗影施法者代表了一种腐化的进攻性奥术和暗影魔法展示，需要迅速的反制法术回应。",["faction:Alliance"]="击倒焚化者加因姆能直接保护湖畔镇脆弱的市民免受兽人入侵首领及其极其危险的暗影施法者的侵害。"},sec={{t="撕裂者山谷的火焰",b="赤脊山正变得愈发危险，黑石兽人从他们的山中据点不断涌出。在撕裂者山谷，焚化者加因姆正领导着一场积极的入侵，并与忠诚的暗影施法者一同施展黑暗魔法。由于当地镇卫兵兵力不足，且暴风城的军队大多缺席，所罗门镇长只得求助于独立的雇佣兵来铲除加因姆，据称他正与石堡要塞的黑石兽人合作。"},{t="死亡证明",b="加因姆以其毁灭性的魔法和对暗影施法者的指挥能力而闻名。想要领取镇上的赏金，猎人们必须深入敌占区，击败焚化者，并将他的断裂法杖带回湖畔镇市政厅，作为威胁已被清除的实物证明。"}},faq={{q="谁是焚化者加因姆？",a="焚化者加因姆是一位兽人督军兼施法者，正在撕裂者山谷领导入侵。据称他正与石堡要塞的黑石兽人合作，并统率着危险的暗影施法者。",al={"谁是加因姆","加因姆","焚化者加因姆"}},{q="在哪里可以找到焚化者加因姆？",a="加因姆在位于赤脊山东南部的撕裂者山谷内的敌对兽人部队中建立了营地。",al={"加因姆位置","加因姆在哪里","撕裂者山谷位置"}},{q="谁发布了针对加因姆的悬赏？",a="这份悬赏由所罗门镇长代表湖畔镇发布，他迫切希望平息压迫着这座受困城镇的兽人入侵。",al={"谁发布的悬赏","所罗门悬赏"}},{q="领取悬赏需要什么证明？",a="所罗门镇长需要焚化者加因姆的断裂法杖来确认这位施法者已死，然后才会发放奖励。",al={"加因姆的证明","破损的法杖任务物品"}},{q="加因姆和他的追随者构成了什么威胁？",a="加因姆掌握着致命的毁灭魔法，并有暗影施法者随行。如果任其发展，他们的存在将加深黑石氏族在赤脊山的根基，并可能淹没湖畔镇。",al={"加因姆的能力","赤脊山的暗影施法者"}},{q="为什么湖畔镇要依赖悬赏而不是暴风城军队？",a="暴风城在政治斗争和兵力短缺的情况下，基本让赤脊山自生自灭，迫使所罗门镇长雇佣愿意效力的冒险者去暗杀敌方领袖。",al={"为什么湖畔镇有悬赏","暴风城军队在哪里"}}},fp="26,345,25.467.0,15.302.0,26.204.0,38.125.0,33.149.0,43.132.0,45.192.0,68.180.0"}
P.entries["quest:96"] = {n="水之召唤",s="这项任务标志着萨满祭司为了与水元素和谐共鸣而进行的艰苦朝圣之旅达到了顶峰。通过将净化的水灵碎片带回贫瘠之地沿岸交给水之先知伊斯伦，初学者证明了他们与复苏能量之间的和谐，并获得了他们的水之图腾。",h="这项任务标志着萨满祭司为了与水元素和谐共鸣而进行的艰苦朝圣之旅达到了顶峰。通过将净化的水灵碎片带回贫瘠之地沿岸交给水之先知伊斯伦，初学者证明了他们与复苏能量之间的和谐，并获得了他们的水之图腾。",kw={"call of water","水之先知伊斯伦","水之魂","水灵碎片","银松森林","贫瘠之地","水之图腾"},ang={["class:Shaman"]="这项试炼仪式将授予你水之图腾，解锁作为精神治疗者核心职责的复苏泉源与净化之泉。",["faction:Horde"]="这项试炼展示了部落的精神责任，号召年轻的萨满祭司去净化卡利姆多和东部王国各地受到枯萎侵害的土地。"},sec={{t="漫漫回家路",b="水的试炼要求初学者跨越大陆，远行至银松森林那片饱受污染的海岸，去直面腐蚀。水代表了生命、适应与治愈，但其柔韧的本质使其特别容易受到枯萎和黑暗魔法的侵蚀。在伫立于水之魂面前并亲眼见证了纯粹的元素意志之后，初学者将被托付一件独特的礼物：水灵碎片。将这枚信物带回大海对岸那片烈日灼烤的贫瘠之地，是一个实实在在的提醒，水连接着这个世界所有遥远的角落。"},{t="水之图腾",b="当水之先知伊斯伦收到这块碎片时，她不仅是在检验任务完成的证明，更是在测试萨满祭司是否已经领悟了保存与复苏之间的平衡。洛丹伦不断蔓延的腐烂往往掩盖了细微的胜利，但即便是净化一处孤立的泉水，对灵魂而言也至关重要。随着这份供奉得到认可，伊斯伦将水之图腾授予了萨满祭司。这个实体焦点允许修行者将净化、治疗和恢复法力的溪流引导至凡世，从而巩固他们与潮汐永恒的交流。"}},faq={{q="什么是水灵碎片？",a="水灵碎片是由水之魂所赐予的一种浓缩的元素残余。它作为一种切实证据，表明初学者已经理解了水作为生命之源的作用，并成功地抵御了威胁元素之流的腐蚀。",al={"水灵碎片","什么是碎片"}},{q="我该把水灵碎片交给谁？",a="这块碎片必须带回给水之先知伊斯伦，她居住在贫瘠之地东海岸，棘齿城以南的一处隐蔽营地中。",al={"哪里交任务","谁获得碎片","交任务地点"}},{q="完成这次试炼我能得到什么？",a="完成这项最终试炼将奖励萨满祭司水之图腾，这是召唤水系元素图腾以进行治疗和恢复魔法所必需的重要媒介。",al={"任务奖励","图腾奖励","我能得到什么"}},{q="为什么试炼地点设在银松森林？",a="银松森林的水域遭受了瘟疫和暗影魔法的严重污染。将萨满祭司派往那里是为了让他们见证水的脆弱，并积极捍卫其自然纯净，对抗腐朽。",al={"为什么是银松森林","为什么是东部王国","银松森林的水"}},{q="谁是水之先知伊斯伦？",a="水之先知伊斯伦是一位位于贫瘠之地东海岸的牛头人萨满祭司。她负责监督水的萨满试炼，教导初学者如何与流动的灵魂交流并掌握复苏艺术。",al={"伊斯伦","谁是水之先知伊斯伦"}}},fx={["352084e3"]={q="水之魂为什么让你回去找水之先知伊斯伦？",a="这个元素化身是纯净之水的活生生的声音，通过你的仪式接受考验并被召唤而来。它将水灵碎片交给你，把水的本质这一根本真理托付给你：水孕育生命，腐化则会将其熄灭。它让你回去找水之先知伊斯伦，好让这位萨满确认你与灵界的沟通，认可你成功对抗腐化，并赐予你配得上的水之图腾。",al={"水之魂的动机","为什么把水灵碎片带给伊斯伦","水之魂为什么想要这个"}}},fp="13,274,19.595.0,15.570.0,27.269.0,35.143.0,44.171.0,43.205.0,23.208.0"}
P.entries["quest:960"] = {n="安努正在沉思",s="在调查黑暗海岸南部的主宰之剑时，知识古树奥努进入了深度的冥想，以沉思日益增长的威胁。如果不慎丢失了神秘的占卜之水，玩家可以与这位正在冥想的古树交谈，以获取补充。他的思绪集中在暮光之锤教派与蜿蜒的纳迦之间那险恶的结盟及其动机上。",h="在调查黑暗海岸南部的主宰之剑时，知识古树奥努进入了深度的冥想，以沉思日益增长的威胁。如果不慎丢失了神秘的占卜之水，玩家可以与这位正在冥想的古树交谈，以获取补充。他的思绪集中在暮光之锤教派与蜿蜒的纳迦之间那险恶的结盟及其动...",kw={"黑暗海岸","古树之林","主宰之剑","冥想","奥努","占卜之水","占卜之盆","暮光之锤"},ang={["class:Druid"]="德鲁伊与知识古树之间有着深厚的自然羁绊。通过占卜仪式维持沟通，反映了塞纳里奥议会从远处勘测受污染土地的方法。",["faction:Alliance"]="保护黑暗海岸免受教派成员和水生入侵者的侵害，对于往返于泰达希尔和灰谷之间的联盟旅者来说至关重要。",["race:NightElf"]="作为卡利姆多平衡的守护者，暗夜精灵崇敬像奥努这样的知识古树，并依靠他们永恒的智慧来解读黑暗海岸荒野中的动荡。"},sec={{t="沉思的灵魂",b="奥努是一棵扎根于黑暗海岸古树之林的知识古树，他如同卡利姆多历史的活档案库。当有关在主宰之剑进行黑暗挖掘的凶兆传闻浮出水面时，奥努便将他那广博的意识转向内心。他正在深度冥想，思考究竟是什么原因，让狂热的暮光之锤教派成员和阴险的纳迦会被吸引到这具古老巨兽的石化遗骸处。对于执行他侦察任务的冒险者来说，他是一个随时可以寻求帮助的锚点，如果他们在野外不慎丢失了占卜之水，他可以提供补充。"},{t="洞察深渊",b="为了在不让古树本体身处险境的情况下监视遗迹，奥努依靠与自然调和的占卜术。冒险者被委托携带一瓶占卜之水，以便在挖掘现场直接召唤一个占卜之盆，从而让奥努可以从远方进行沟通。由于向南穿越黑暗海岸的旅途充满艰险，到处都是充满敌意的野生生物和教派巡逻队，奥努预料到了意外的发生。他的冥想并非无止境的沉睡，而是一种专注的守望；他乐意提供另一瓶圣水，以确保对主宰之剑的调查能够顺利进行，毫不延误。"}},faq={{q="奥努为什么要冥想？",a="奥努是一棵知识古树，他正在思考暮光之锤教派和纳迦同时出现在主宰之剑所带来的令人不安的局面。他通过冥想来洞察他们的动机，并指引正在调查该区域的冒险者。",al={"奥努为什么要冥想","奥努冥想状态","奥努在做什么"}},{q="这次互动的目的是什么？",a="它是为执行“主宰之剑”任务的玩家提供的一种安全机制。如果你丢失、摧毁或过早使用了你的占卜之水，与正在冥想的奥努交谈可以为你提供一瓶新的占卜之水，以便你完成仪式。",al={"占卜之水丢失","获取另一瓶占卜之水","奥努补充任务物品"}},{q="奥努在哪里？",a="奥努扎根在古树之林，位于黑暗海岸中南部，就在大路旁。",al={"奥努位置","哪里可以找到奥努"}},{q="我该如何使用占卜之水？",a="带着占卜之水前往主宰之剑并使用它来创建一个占卜之盆。之后奥努就能通过这个盆与你进行交流。",al={"如何使用占卜之水","黑暗海岸占卜之盆","占卜之水用途"}},{q="什么是主宰之剑？",a="主宰之剑是黑暗海岸南部一个巨大的古代挖掘现场，那里有一具被巨大刀刃刺穿的、被遗忘实体的巨大石化头骨。教派成员和纳迦为了某种未知的邪恶目的聚集在那里。",al={"什么是主宰之剑","黑暗海岸南部的遗迹"}},{q="部落玩家可以在这里与奥努互动吗？",a="不能。奥努严格效忠于暗夜精灵和联盟。在古树之林附近徘徊的部落冒险者会发现奥努和他的守护者们充满敌意，且拒绝合作。",al={"奥努是否只对联盟开放","部落与正在冥想的奥努"}}},fx={["72a6a09e"]={q="奥努为什么需要你帮忙，而不是自己调查？",a="奥努留在古树之林冥想暮光之锤和娜迦。他需要旅人调查主宰之剑，并通过占卜碗与他联系。",al={"为什么派我去","奥努为什么不亲自去","奥努为什么需要你"}}},fp="17,366,28.564.0,18.581.0,22.227.0,40.244.0,21.106.0,39.127.0,28.246.0,41.185.0"}
P.entries["quest:96031"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking 指导工匠们如何利用熟化皮革制作他们自己的便携式荒野庇护所。它强调了在远离文明的地方生存的必要条件，提醒冒险者，一个真正的营地既需要在野外搭建帐篷，也需要烹饪训练师所教授的篝火。",h="Camping 101: Leatherworking...",kw={"营地帐篷","篝火","露营","烹饪","皮革加工","庇护所","帐篷","荒野"},ang={["profession:Cooking"]="篝火是任何荒野营地不可或缺的核心。学习基础烹饪可以确保冒险者能够点燃火焰，从而在野外维持营地的运作。"},sec={{t="在荒野中搭建庇护所",b="制作个人庇护所对于任何从事皮革加工的工匠来说都是一个重要的里程碑。当漫游者在开阔的地形中旅行时，坚固的皮帐篷能为他们提供一道抵御恶劣天气、风和夜晚寒冷的可靠屏障。然而，当地城镇居民不希望在拥挤的街道或集市广场上搭建个人庇护所，这意味着冒险者必须前往城门之外的荒野才能搭建庇护所。"},{t="篝火的温暖",b="搭建的帐篷只是建立可持续营地所需条件的一半。一个合格的营地还需要燃烧的篝火来驱散黑暗，抵御寒风，并在危险的土地上提供温暖。由于生火和照看火堆是野外准备食物的基础，因此我们指导冒险者在建立营地之前，先向烹饪大师和烹饪训练师寻求指导，学习如何点燃篝火。"}},faq={{q="你可以在哪里搭建营地帐篷？",a="城镇居民不希望在街道或城市广场中间搭建营地帐篷。冒险者必须前往有充足开阔地面的荒野，才能正确地搭建帐篷。",al={"使用营地帐篷","在哪里搭建帐篷","我可以在城里露营吗"}},{q="除了搭建帐篷，搭建营地还需要什么？",a="仅有帐篷并不能构成一个功能性的营地。在建立真正的营地之前，你还需要在帐篷旁边燃起一堆合适的篝火。",al={"营地需要生火吗","营地需求","如何露营"}},{q="冒险者在哪里学习生火？",a="精通烹饪艺术的训练师会教授准备食物的基础知识，其中就包括如何点燃和维护基本的篝火。寻找烹饪训练师可以获得在任何地方生火所需的知识。",al={"学习篝火技能","谁教授篝火技能","烹饪篝火"}},{q="皮革加工与制作营地帐篷有什么关系？",a="皮革工匠使用熟化皮革、毛皮和坚固的缝线来制作耐用的庇护所覆盖物，使其能够抵御恶劣的荒野环境。这种实用的手艺让漫游者能够用动物皮革组装出一个可靠的庇护所。",al={"camping 101: leatherworking","皮革营地帐篷","通过皮革加工制作帐篷"}},{q="为什么冒险者要在荒野中建立营地？",a="冒险深入定居点之外的区域会使旅行者暴露在自然环境和危险的地形中。拥有便携式庇护所和温暖的篝火，可以在远离旅店和定居点时提供一个安全的休息和恢复场所。",al={"为什么要野外露营","露营的目的","荒野生存营地"}},{q="为什么城镇居民反对在城内搭建帐篷？",a="定居点和城镇已经为旅行者建立了旅店和私人住所。在公共街道上架设帐篷会阻碍交通并造成骚扰，因此当地居民坚持认为营地应设在野外。",al={"城内露营规则","城内禁止帐篷","为什么不能在城里搭建帐篷"}}},fp="27,322,28.477.0,24.427.0,32.206.0,53.152.0,47.220.0,54.235.0,53.215.0,56.216.0"}
P.entries["quest:96044"] = {n="Camping 101: Blacksmithing",s="Camping 101: Blacksmithing 是一项指引铁匠前往卡拉诺斯寻找 Tognus Flintfire 的入门任务。通过他，工匠们可以学习制作便携式磨刀石，以便在野外的营地中维护武器。",h="Camping 101: Blacksmithing 是一项指引铁匠前往卡拉诺斯寻找 Tognus Flintfire 的入门任务。通过他，工匠们可以学习制作便携式磨刀石，以便在野外的营地中维护武器。",kw={"锻造","刀刃","营地","camping 101","丹莫罗","卡拉诺斯","磨刀石","tognus flintfire","武器"},ang={["class:Rogue"]="对潜行者而言，锋利的匕首是必不可少的职业工具，这使得营地磨刀石成为了野外任务间隙中备受欢迎的装备。",["class:Warrior"]="战士在激战中依赖锋利的刀刃，当铁匠将磨刀石带到探险营地时，他们会直接受益。",["profession:Blacksmithing"]="有抱负的铁匠可以学习制作像磨刀石这样的野外实用工具，将他们的手艺从城市锻炉延伸到野外，以支援盟友。",["race:Dwarf"]="由于卡拉诺斯坐落在丹莫罗的雪山脚下，矮人铁匠们以保持寒铁锋利并随时准备应对任何道路而感到自豪。"},sec={{t="野外行路的装备维护",b="Camping 101: Blacksmithing 指导新手铁匠学习野外实用技术。虽然任何城镇的锻炉都能打造胸甲或利剑，但外出探险的冒险者需要的维护远非城市围墙内的舒适所能及。证明了自身基本能力的铁匠会被指引前往卡拉诺斯，那里的大师级工匠会分享如何将原材料打造成便携式营地工具，以保持刀刃在漫长旅途中的锋利。"},{t="卡拉诺斯的大师",b="在白雪皑皑的卡拉诺斯定居点，Tognus Flintfire 指导有能力的铁匠制作磨刀石。在营地架设这种磨刀石可以将普通的休息地变成临时的军械库，吸引那些急于在下一次行军前磨去钢材缺口和钝边的战士和潜行者。"}},faq={{q="Tognus Flintfire 是谁？",a="Tognus Flintfire 是一位位于丹莫罗卡拉诺斯镇的锻造训练师。他为那些已展现出足够职业熟练度的铁匠提供培训，教导他们如何打造专门的营地装备。",al={"谁是tognus flintfire","tognus在哪里","tognus flintfire的位置"}},{q="什么是磨刀石？",a="磨刀石是一种由铁匠制作的营地工具。当它被安放在冒险者的营地时，它提供了一个专门的工作台，像战士和潜行者这样的挥舞武器的盟友可以在野外磨砺和维护他们刀刃的锋利度。",al={"磨刀石有什么用","营地磨刀石","磨刀石的用途"}},{q="为什么战士和潜行者关心磨刀石？",a="战士和潜行者从营地配备磨刀石中受益最大，因为他们的战斗效能很大程度上取决于在远离城镇锻炉的长途旅行中，能否保持刀刃、斧头和匕首的锋利。",al={"谁需要磨刀石","战士磨刀石","潜行者磨刀石"}},{q="卡拉诺斯在哪里？",a="卡拉诺斯是一个繁华的矮人定居点，位于铁炉堡西南方，坐落在丹莫罗的雪峰之中。它是穿行于山口的旅行者、矿工和工匠的重要中转枢纽和贸易站。",al={"卡拉诺斯在哪里","卡拉诺斯的位置","寻找卡拉诺斯"}},{q="学习此营地物品需要什么条件？",a="铁匠必须先展示出基本的专业能力，Tognus Flintfire 才会指导他们制作营地装备。一旦你在铁砧上练习了基础技能，他就会教你锻造这种便携式磨刀石。",al={"camping 101: blacksmithing的要求","什么时候可以学习磨刀石","锻造营地训练"}},{q="为什么铁匠要制作营地物品？",a="营地物品使铁匠能够在定居城镇之外支援冒险队伍。与其强迫同伴返回城市锻炉进行基本的武器维护，像磨刀石这样的便携式工具可以在露天环境下提供必要的维护。",al={"为什么要制作营地物品","锻造营地物品","野外锻造工具"}}},fp="26,222,35.414.0,22.341.0,24.241.0,27.260.0,59.233.0,18.230.0,44.226.0,39.266.0"}
P.entries["quest:96045"] = {n="Camping 101: Alchemy",s="《Camping 101: Alchemy》向铁炉堡初出茅庐的炼金术师介绍了在Vosur Brakthel指导下的实用野外生存技巧。通过学习为野营搭建法力之井，炼金术师可以为旅途中的施法者和治疗者提供关键的恢复手段。",h="《Camping 101: Alchemy》向铁炉堡初出茅庐的炼金术师介绍了在Vosur Brakthel指导下的实用野外生存技巧。通过学习为野营搭建法力之井，炼金术师可以为旅途中的施法者和治疗者提供关键的恢复手段。",kw={"炼金术","篝火","扎营","camping 101: alchemy","铁炉堡","法力之井","vosur brakthel"},ang={["faction:Alliance"]="前往矮人要塞铁炉堡的有志炼金术师可以咨询Vosur Brakthel，学习如何通过恢复性药剂来增强他们的探险之旅。",["profession:Cooking"]="一个正规的营地需要一个基础篝火，这是一项由各地的烹饪训练师教授的实用技能，用于补充专业的营地制作技艺。"},sec={{t="旅途中的酿造",b="对于在Azeroth蛮荒之地冒险的炼金术师来说，在安静的实验室里调制药剂只是这项技艺的一半。在宏伟的矮人都市铁炉堡，炼金术师Vosur Brakthel指导学员如何将他们精细的技艺适应严苛的野外生存环境。通过展示出色的炼金能力，冒险者可以学会将知识提炼为制作法力之井的技巧——这是一种专为在野外维持同伴状态而设计的便携式营地设施。"},{t="野外营地",b="虽然法力之井能为疲惫的治疗者和施法者提供恢复增益，但它无法在铺设鹅卵石的街道上独立运作。城里的居民对于旅行者在城市中心搭帐篷的行为不以为然，这意味着这类设施必须带到野外去使用。此外，没有合适篝火的温暖余烬，营地就不算完整，因此有志于建造营地的人在前往野外之前，需要先向当地的烹饪师寻求指导。"}},faq={{q="谁是Vosur Brakthel？",a="Vosur Brakthel是一位居住在山中之城铁炉堡的炼金训练师。他指导新兴的炼金术师如何运用他们的药剂制作专长来制造法力之井，以在野外支援冒险者。",al={"camping 101 alchemy的教学者","vosur brakthel的作用","vosur brakthel是谁"}},{q="什么是法力之井？",a="法力之井是炼金术师调配的一种营地装置，用于恢复施法者和治疗者的状态。当放置在野外的营地时，它能为施法者提供清爽的饮品，在漫长的旅途中补充他们的奥术能量。",al={"法力之井的作用","法力之井的目的","为什么要制作法力之井"}},{q="可以在铁炉堡内扎营吗？",a="市民通常不赞成在城市街道上扎营。想要建造营地并部署法力之井的炼金术师必须前往城墙之外的荒野。",al={"我能在铁炉堡扎营吗","在城镇中扎营","放置法力之井的位置"}},{q="扎营还需要什么？",a="每个营地都需要一个基础的篝火作为核心。尚未学会如何生火的冒险者建议在出发前寻找烹饪训练师，学习基础的烹饪生火技能。",al={"篝火要求","扎营需要烹饪技能吗","如何开始扎营"}},{q="炼金术师什么时候可以学习制作法力之井？",a="一旦炼金术师习得该专业并展示出一定的技艺水平，Vosur Brakthel就会提供指导。当他们足够熟练时，制作法力之井的秘诀便会传授给他们。",al={"何时能学习法力之井","法力之井的要求","camping 101的要求"}},{q="谁最能从营地的法力之井中受益？",a="法力之井主要惠及施法者和治疗者，例如法师、牧师和德鲁伊，他们在远离城镇旅店和炉石的地方冒险时，非常依赖法力值的补充。",al={"谁能从法力之井中受益","法力之井受益职业","谁使用法力之井"}}},fp="20,273,20.475.0,20.465.0,22.228.0,20.235.0,39.195.0,37.203.0,48.215.0,43.202.0"}
P.entries["quest:96046"] = {n="Camping 101: Mining",s="《Camping 101: Mining》指导矿工如何制作磁石，以便在荒野中建立营地。这是生存训练中的重要一步，强调了野外露营对矿石制作和基础生火技巧的依赖。",h="《Camping 101: Mining》指导矿工如何制作磁石，以便在荒野中建立营地。这是生存训练中的重要一步，强调了野外露营对矿石制作和基础生火技巧的依赖。",kw={"篝火","露营","camping 101: mining","营地","烹饪","磁石","采矿","荒野"},ang={["profession:Cooking"]="露营技巧与基础烹饪技能密切相关，因为任何可用的庇护所都需要烹饪训练师传授的适当篝火。",["profession:Mining"]="矿工学会了如何将原始泥土和矿石塑造成磁石，这是在荒野中固定野外营地的必备工具。"},sec={{t="矿工的野外生存技巧",b="冒险离开有守卫保护的道路，需要自力更生和野外生存技巧。矿工学会应用他们对矿物和石头的知识来制作磁石，这是一种用于在未开化的世界中搭建功能性营地的锚定工具。"},{t="荒野法则",b="定居的居民对于在城镇广场或繁忙大道中央搭建庇护所的旅行者向来持负面看法。建立营地需要前往开阔的荒野，远离城镇范围。此外，如果没有熊熊燃烧的篝火来抵御夜晚的寒冷，任何荒野营地都无法正常使用，这使得基础的烹饪生火技巧成为矿业工作中不可或缺的伙伴。"}},faq={{q="磁石有什么用途？",a="磁石是荒野生存专家用来在野外建立并固定个人营地的基础工具。",al={"磁石用途","磁石是干什么用的","为什么要制作磁石"}},{q="我可以在城镇或城市里扎营吗？",a="城镇居民和定居点当局不赞成冒险者在公共广场或城市街道上搭帐篷和建立营地，这意味着你必须冒险前往野外才能建立营地。",al={"我能在镇上露营吗","在城市露营","在定居点内露营"}},{q="建立营地前需要什么条件？",a="每个营地都需要一个温暖的篝火才算完整。没有在附近燃烧的篝火，你就无法妥善地搭建营地。",al={"我需要篝火吗","如何建立营地","露营先决条件"}},{q="我在哪里可以学会生火？",a="基础生火技巧是烹饪艺术的重要组成部分，艾泽拉斯各地的烹饪训练师和厨师都很乐意传授。",al={"在哪里学习生火","谁教生火","篝火训练师"}},{q="采矿与制作磁石有什么联系？",a="矿工掌握了提取和加工制作磁石所需的天然矿物和石头所需的专业知识。",al={"矿工为何露营","采矿与磁石的联系","制作磁石"}},{q="我应该去哪里测试我的新营地？",a="你应该穿过城门，前往有充足开阔地且没有不满的城镇居民的荒野地区。",al={"去哪里测试营地","测试磁石","户外露营"}}},fp="19,241,21.247.0,17.389.0,29.133.0,40.192.0,42.126.0,41.126.0,48.123.0,38.136.0"}
P.entries["quest:96047"] = {n="Camping 101: First Aid",s="此任务指导丹莫罗的新手医疗兵将他们的生存技能扩展至基础绷带之外。通过寻找卡拉诺斯的Thamner Pol，冒险者们将学会如何组装专门的急救包，以便在野外宿营时维持生命。",h="此任务指导丹莫罗的新手医疗兵将他们的生存技能扩展至基础绷带之外。通过寻找卡拉诺斯的Thamner Pol，冒险者们将学会如何组装专门的急救包，以便在野外宿营时维持生命。",kw={"绷带","野外生存101","丹莫罗","急救","急救包","卡拉诺斯","生存","thamner pol"},ang={["faction:Alliance"]="在卡兹莫丹冰冻的核心地带进行训练的联盟新兵很早就认识到，自给自足和野外医疗对于任何军事或探险单位来说都是至关重要的资产。",["race:Dwarf"]="矮人登山者在巡逻丹莫罗高耸的雪山隘口时，非常依赖坚固实用的装备，这使得营地急救包成为了必备的生存物资。",["race:Gnome"]="以卡拉诺斯为行动基地的难民和侏儒流浪者们，在诺莫瑞根失落大厅之外求生时，发现高效的野外医疗手段是极其宝贵的。"},sec={{t="野外伤口处理",b="在丹莫罗的冰天雪地中冒险，探险者们很快就会发现亚麻布片和简单的缝合只不过是生存医疗的开端。真正的荒野生存往往取决于在休息点拥有完善的补给。那些在基础治疗方面展现出天赋的人，会被指引去向卡拉诺斯的当地手艺导师请教，学习如何将原始的医疗物资制作成适合营地生存的完整急救包。"},{t="卡拉诺斯的教诲",b="在繁忙的卡拉诺斯村落，Thamner Pol传授着将远征营地配备应急物资的实用技术。知道如何建造一套合适的野外急救包，可以确保整个小队在冒险回到刺骨寒风中之前，能围着炉火一起包扎伤口并恢复体力。"}},faq={{q="这项任务的目的是什么？",a="该任务引导新训练的野外医疗兵前往卡拉诺斯寻找Thamner Pol，他会教导他们如何制作专为冒险者营地设计的实用急救包。",al={"为什么要完成野外生存101：急救","这个任务有什么作用","野外生存101的目标"}},{q="Thamner Pol是谁？",a="Thamner Pol是一位位于丹莫罗卡拉诺斯镇的训练师。他指导熟练的生存专家制作与专业相关的装备，以升级他们的野外营地。",al={"谁是thamner pol","thamner pol的位置","thamner pol在哪里"}},{q="这项训练在哪里进行？",a="训练在卡拉诺斯进行，这是位于铁炉堡以南、丹莫罗中心地带的主要定居点。",al={"我该去哪里","野外生存101的位置","卡拉诺斯急救"}},{q="为什么营地急救包很重要？",a="在恶劣的荒野远征中，受伤是常有的事。专门的急救包为休息中的冒险者提供了必要的治疗资源，使旅者们能够在战斗间隙包扎伤口并安全恢复。",al={"急救包有什么用","为什么要制作急救包","营地急救的用途"}},{q="在寻找Thamner Pol之前需要先进行医疗训练吗？",a="是的。冒险者在Thamner Pol教授他们高级宿营配方之前，必须已经掌握急救的基础知识并展现出一定的专业能力。",al={"野外生存101的要求","所需的急救技能","我是否需要先学会急救"}},{q="这项追求对所有冒险者开放吗？",a="任何冒险者都可以学习急救，无论他们的职业为何，这使得营地医疗成为每位在丹莫罗游荡的旅者的一项实用技能。",al={"任何人都可以做这个吗","职业要求","谁可以学习营地急救"}}},fp="22,236,26.437.0,23.337.0,33.161.0,19.174.0,36.111.0,38.218.0,62.176.0,39.143.0"}
P.entries["quest:96050"] = {n="Camping 101: Fishing",s="《Camping 101: Fishing》指导户外人士掌握野外生存的基本技能和礼仪。它教导冒险者如何为他们的营地制作装饰性的鱼缸，并强调在前往野外之前，必须先从烹饪训练师那里学会制作篝火。",h="《Camping 101: Fishing》指导户外人士掌握野外生存的基本技能和礼仪。它教导冒险者如何为他们的营地制作装饰性的鱼缸，并强调在前往野外之前，必须先从烹饪训练师那里学会制作篝火。",kw={"营地","篝火","露营","烹饪","鱼缸","钓鱼","野外"},ang={["profession:Cooking"]="学习烹饪基础知识对于建立营地至关重要，因为烹饪训练师会教旅行者如何搭建所需的篝火。"},sec={{t="野外礼仪",b="在艾泽拉斯的旅途中生活，需要具备前线的实用知识。对于有志于钓鱼的旅行者和流浪者来说，建立一个井然有序的营地需要了解基本的户外礼仪。城镇居民和卫兵不欢迎旅客在定居点的中心搭帐篷和散落装备，因此任何想要休息的人都必须将物资带到城市边界之外的广阔野外。"},{t="营地的舒适",b="一个像样的探险营地需要一些基本的设施。最重要的是，如果没有温暖的篝火，营地就无法使用，这项技能通常由烹饪训练师传授。一旦生起火，经验丰富的旅行者就可以摆放一些特殊的装备，比如手工制作的鱼缸，将一个简单的休息站变成一个装备齐全的垂钓者乐园。"}},faq={{q="你能从《Camping 101: Fishing》中学到什么？",a="这门课程教导冒险者如何制作鱼缸来布置他们的营地。它涵盖了在远离文明定居点的地方建立适合钓鱼和放松的野外休养地的基础知识。",al={"此任务教授什么","制作鱼缸","野营钓鱼奖励"}},{q="你可以在哪里建立营地？",a="营地不能搭建在城镇中心，因为城镇居民反感旅客在公共通道上肆意扩张。你必须冒险进入野外来建立你的营地。",al={"在哪里扎营","我可以在城镇里扎营吗","露营地点规则"}},{q="在搭建营地之前你需要什么？",a="没有篝火的野外营地是不完整的。在你开始搭建营地之前，你必须准备好一堆火来稳固营地并提供温暖。",al={"如何开始露营","我需要篝火吗","营地要求"}},{q="如何学习制作篝火？",a="烹饪导师和烹饪训练师传授生火的基本艺术。那些还没有学会烹饪基础知识的人应该寻找一位厨师来学习如何制作篝火。",al={"如何制作篝火","在哪里学习篝火","谁教授生火"}},{q="鱼缸有什么用途？",a="鱼缸是为户外营地制作的装饰性物品，为任何想要在水边建立前哨站的旅行垂钓者提供了恰到好处的点缀。",al={"鱼缸有什么用","露营鱼缸用途","鱼缸背景知识"}},{q="为什么要对冒险者进行野营教学？",a="野外导师提供关于前线生活的实用指导，确保流浪者在进入野外之前知道如何正确地维持生计、生火并尊重定居点的边界。",al={"谁提供camping 101","为什么需要露营课程","野外生存指南"}}},fp="20,289,20.399.0,20.374.0,44.210.0,28.186.0,40.164.0,37.187.0,37.170.0,46.200.0"}
P.entries["quest:96055"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism会指引有前途的草药师前往铁炉堡寻找Reyna Stonebranch，以扩展他们的实用技艺。采集者将学习如何将野生草药合成为适合露营生活的舒缓的熏香蜡烛。这些芳香的野外产物能提振精神，并在艰苦的野外探险中为施法者提供帮助。",h="Camping 101: Herbalism会指引有前途的草药师前往铁炉堡寻找Reyna...",kw={"露营","camping 101","草药学","草药","熏香蜡烛","铁炉堡","reyna stonebranch"},ang={["faction:Alliance"]="联盟的草药师会被指引前往矮人城市铁炉堡，寻找Reyna Stonebranch以学习专业的野外生存技能。",["profession:Herbalism"]="磨练了花草技艺的采集者可以制作熏香蜡烛，将采集到的野生草药转化为适合施法盟友使用的芳香露营辅助品。",["race:Dwarf"]="制作这些草药露营辅助品的知识由铁炉堡的草药学导师Reyna Stonebranch掌握。"},sec={{t="实用野外植物学",b="在野外采集草药绝非简单的采花而已。熟练的植物学家发现，采集到的植物可以转化为实用的户外生存工具，为旅行队伍提供宝贵的露营用品。对于那些希望将自身的作用扩展到基础试剂采集之外的采集者来说，学习专业的野外技术可以将野生植物转化为必要的支援物品。"},{t="炉边的芳香",b="精通草药学的玩家会被指引前往山城铁炉堡寻找Reyna Stonebranch。在证明了自己的技艺水平后，草药师便可以学习制作熏香蜡烛。这些芳香的蜡烛为营地带来了急需的慰藉，不仅能提振旅伴的精神，还能提供一种令施法者和治疗者在长途探险中倍感舒适的宁静环境。"}},faq={{q="什么是Camping 101: Herbalism？",a="Camping 101: Herbalism是一项教学指令，旨在指导熟练的采集者学习如何将他们的植物学技艺应用于户外生存和野外露营。",al={"什么是camping 101: herbalism","草药学露营任务","草药学露营指南"}},{q="Reyna Stonebranch是谁？",a="Reyna Stonebranch是一位驻扎在伟大的矮人城市铁炉堡的草药学训练师，她教导精通草药学的玩家如何制作露营用品。",al={"谁传授熏香蜡烛制作","reyna stonebranch在哪里","reyna stonebranch位置"}},{q="熏香蜡烛有什么用？",a="熏香蜡烛是一种由草药师制作的芳香类露营物品，它能提振营地的士气，提供一种特别受治疗者和施法者青睐的提神效果。",al={"熏香蜡烛的作用","熏香蜡烛露营","熏香蜡烛用途"}},{q="为什么熏香蜡烛对施法者很有用？",a="高昂的士气有助于保持耐力，这使得熏香蜡烛舒缓的香气对在旅途中休整的治疗者和魔法使用者格外有益。",al={"谁从熏香蜡烛中获益","熏香蜡烛对施法者有用吗"}},{q="草药师必须去哪里接受指导？",a="该任务指引草药师在展示出足够的采集熟练度后，前往卡兹莫丹的铁炉堡与Reyna Stonebranch会面。",al={"去哪里学习露营草药学","camping 101: herbalism在哪个城市"}},{q="在学习制作蜡烛前有什么要求？",a="草药师必须在采集草药方面展现出足够的熟练度和实用技能，Reyna Stonebranch才会传授制作营地熏香的技巧。",al={"什么时候可以学习熏香蜡烛","草药学露营要求"}}},fp="22,311,22.393.0,24.411.0,31.172.0,25.157.0,31.173.0,47.166.0,50.158.0,53.161.0"}
P.entries["quest:96056"] = {n="Camping 101: Skinning",s="Camping 101: Skinning 是一个引导任务，指导冒险者如何利用收集到的动物皮毛来制作荒野家具。它指引熟练的剥皮师前往铁炉堡寻找 Balthus Stoneflayer，学习如何为他们的营地制作舒适的营地椅子。",h="Camping 101: Skinning 是一个引导任务，指导冒险者如何利用收集到的动物皮毛来制作荒野家具。它指引熟练的剥皮师前往铁炉堡寻找 Balthus...",kw={"balthus stoneflayer","营地椅子","露营","camping 101: skinning","皮毛","铁炉堡","剥皮"},ang={["class:Hunter"]="那些以狩猎为生并会在野外剥取猎物皮毛的猎人，从建立一个合适的营地以在长途追踪间隙进行休息中获益匪浅。",["faction:Alliance"]="制作这种野外座椅的道路直通矮人山城铁炉堡，这使得这座联盟主城成为皮革采集者的重要停靠点。",["race:Dwarf"]="Balthus Stoneflayer 将家安在铁炉堡，他为熟练的剥皮师们提供了将生皮转化为坚固营地舒适用品的矮人秘诀。"},sec={{t="荒野采集",b="剥取野兽尸体是冒险者在艾泽拉斯荒野穿行时最实用的技能之一。除了为护甲匠和工匠提供原料皮革外，从捕食性猫科动物、熊和野兽身上收集的皮毛还可以直接在野外重新利用。这项入门任务指引剥皮师将原材料转化为实用的荒野用品，而不是仅仅将其出售。"},{t="铁炉堡的工匠",b="该任务要求剥皮修行者前往矮人主城铁炉堡寻找 Balthus Stoneflayer。Balthus 掌握着将处理过的动物皮毛变成实用营地椅子的秘诀。然而，他要求冒险者在传授制作技巧之前，必须先证明自己在剥皮艺术方面的精湛技艺。"},{t="休息与整备",b="旅途生活对旅行者和猎人来说都是沉重的体力消耗。一张结实的营地椅子让冒险者有机会坐在篝火旁放松身心，恢复精力和敏锐的感官。花点时间休整可以确保在下一次危险冲突开始时，冒险者能以最佳状态投入战斗，并在关键时刻予以重击。"}},faq={{q="什么是 Camping 101: Skinning？",a="Camping 101: Skinning 是一个教学任务，旨在指引熟练的剥皮师前往铁炉堡寻求专业的营地制作训练。它教导冒险者如何将野外收获的动物皮毛制作成舒适的营地椅子，供其个人营地使用。",al={"什么是 camping 101: skinning","任务目标","camping 101: skinning 任务"}},{q="谁教你制作营地物品？",a="任务指引你与居住在山城铁炉堡的工艺大师 Balthus Stoneflayer 交谈。一旦你展示了在采集专业中足够的熟练度，他就会教你如何制作专门的营地用品。",al={"找谁交谈","谁教授营地椅子","balthus stoneflayer 是谁"}},{q="你需要去哪里完成这个任务？",a="你必须前往坐落在丹莫罗雪山中的矮人主城铁炉堡。Balthus Stoneflayer 就在城内，随时准备指导合格的剥皮师。",al={"去哪里","balthus 的位置","铁炉堡训练师"}},{q="剥皮师可以学习制作什么物品来用于营地？",a="你将学习利用收集到的皮毛制作营地椅子。摆放一把舒适的椅子可以让冒险者在野外歇脚，帮助他们在危险的遭遇战之间恢复专注力并保持巅峰的身体状态。",al={"你制作什么","营地椅子的用途","剥皮营地制作"}},{q="为什么制作营地椅子对冒险者有用？",a="在舒适的营地椅子上休息，能在长途跋涉于荒野的过程中提供至关重要的喘息机会。花时间放松可以确保冒险者保持巅峰的战斗状态，并在不可避免的战斗爆发时精准出击。",al={"为什么要制作椅子","营地椅子有什么用","营地椅子的好处"}},{q="Balthus 教你之前需要什么样的熟练度？",a="只有当冒险者证明了自己在剥皮专业方面的熟练度后，Balthus Stoneflayer 才会分享他的制作知识。你必须展示出剥取野兽皮毛的扎实技能，他才会将图样教给你。",al={"要求","何时可以学习","所需熟练度"}}},fp="21,281,20.424.0,24.346.0,18.363.0,30.262.0,42.252.0,47.179.0,52.240.0,54.240.0,59.219.0"}
P.entries["quest:96101"] = {n="The Great Outdoors",s="The Great Outdoors是一个入门任务，由户外生存专家Raan提供，他会向新手冒险者传授荒野生存的基础知识。通过在简易营火旁休息以获得“双倍经验”(Boosted Rest)，流浪者在前往附近的贸易训练师处学习实用专业技能之前，可以先学到基本的露营技巧。",h="The Great Outdoors是一个入门任务，由户外生存专家Raan提供，他会向新手冒险者传授荒野生存的基础知识。通过在简易营火旁休息以获得“双倍经验”(Boosted...",kw={"简易营火","双倍经验","露营设施","营火","raan","the great outdoors","专业技能","荒野生存"},ang={["class:Hunter"]="荒野生存始于露营的基础知识，这是习惯于在露天环境下生活的追踪者和游侠必备的一项基本纪律。",["profession:Cooking"]="围坐在简易营火旁休息和恢复体力是营地厨师的第二天性，他们依靠明火来维持野外旅行队伍的生存。"},sec={{t="荒野课程",b="The Great Outdoors是关于如何在定居点围墙之外生存的入门课程。这项任务由一位名叫Raan的经验丰富的荒野旅行者提供，它提醒四处游历的冒险者：如果没有应对恶劣环境所需的实用露营技巧，单纯的雄心壮志和锋利的武器毫无用处。Raan欢迎有志向的流浪者加入那些寻求财富与荣耀的躁动灵魂的行列，并为愿意学习的人提供实用的指导。"},{t="炉火的温暖",b="该课程的核心要求简单得令人意想不到：坐在Raan的简易营火旁，直到温暖带来“双倍经验”效果。在艾泽拉斯广袤而未受驯服的领土上，懂得如何停下脚步、安营扎寨和恢复体力，往往意味着生与死的差别。一旦掌握了露营的基础知识，Raan就会指引新手前往当地村庄的训练师处，学习一项商业技能，并学会制作专门的露营设施。"}},faq={{q="谁发布了The Great Outdoors任务？",a="该任务由Raan发布，他是一位经验丰富的旅行者，能够发掘流浪冒险者的潜力，并向他们传授在野外生存的基本知识。",al={"谁提供the great outdoors","the great outdoors任务发布者","raan营火任务"}},{q="The Great Outdoors的任务目的是什么？",a="它向冒险者介绍了野外生存的基础知识，展示了在简易营火旁休息如何提供舒适感、恢复体力和在进行危险旅程前所需的双倍经验加成。",al={"the great outdoors教什么","the great outdoors目的","我从raan那里学到什么"}},{q="如何完成该任务？",a="要完成这门课程，请坐在Raan的简易营火旁休息，直到获得“双倍经验”增益效果，这表明你已经了解如何在野外恢复体力。",al={"如何完成the great outdoors","raan营火目标","双倍经验目标"}},{q="Raan建议在完成任务后做什么？",a="在完成营火课程后，Raan鼓励你去拜访附近村庄的训练师学习一项专业技能，并指出工匠可以制作适合其专业的露营设施。",al={"raan接下来有什么建议","完成the great outdoors后去哪里","完成the great outdoors之后"}},{q="什么是“双倍经验”？",a="“双倍经验”是在已建立的营火旁休息时获得的恢复效果，它能让旅行中的冒险者在直面恶劣环境时获得更强的恢复能力。",al={"什么是双倍经验","营火双倍经验增益"}},{q="专业技能是否允许冒险者制作露营设施？",a="是的，当地的商业训练师可以指导工匠如何制作适合其所选专业的实用露营设施，使旅行者能够在户外维持专业的营地设置。",al={"专业技能可以制作营火吗","专业技能营地设施","贸易营地物品"}}},fp="18,319,19.453.0,24.453.0,39.174.0,42.211.0,27.175.0,56.190.0,21.174.0,60.193.0"}
P.entries["quest:96130"] = {n="Chakuyak",s="Chakuyak是一头极其凶猛的草原狼，在莫高雷的石牛湖以西的树丛中徘徊。她对过往的旅人构成了日益严重的威胁，当地部落决定将她列为狩猎目标，在除掉威胁的同时，也为了通过鞣制这头野兽的毛皮来表达敬意。",h="Chakuyak是一头极其凶猛的草原狼，在莫高雷的石牛湖以西的树丛中徘徊。她对过往的旅人构成了日益严重的威胁，当地部落决定将她列为狩猎目标，在除掉威胁的同时，也为了通过鞣制这头野兽的毛皮来表达敬意。",kw={"chakuyak","莫高雷","草原狼","石牛湖","牛头人狩猎","旅人","狼皮"},ang={["class:Hunter"]="在林木丛生的山丘间追踪一头异常凶猛、独来独往的头狼，需要耐心、敏锐的感知力，以及对野生掠食者的尊重。",["race:Tauren"]="这场狩猎反映了牛头人的精神，即在保护部落、利用野兽毛皮以示纪念的实际职责，与对自然生物的敬畏之间保持平衡。"},sec={{t="石牛湖的阴影",b="在莫高雷那长满青草的高原和连绵起伏的山丘间游荡的草原狼中，有一头名为Chakuyak的极其凶猛的雌性头狼，以其持续不断的攻击性而闻名。她在石牛湖以西的树丛中潜行，已经从普通的野兽变成了一个威胁，直接危及着从外地赶来的旅人。这促使当地的猎人决定在她伤害到无辜的游人之前将其除掉。"},{t="敬畏与必要",b="对于当地部落而言，终结像Chakuyak这样强大的掠食者的生命，是一种充满哀伤的敬畏，而非残忍的炫耀。屠戮她被视为保护旅人和村民的必要举动。按照游牧民族的习俗，她的厚实毛皮会被带回来仔细鞣制并加以利用，以确保这头巨狼的精神和牺牲得到尊重，而非被浪费。"}},faq={{q="Chakuyak是什么？",a="Chakuyak是一头体型硕大且极具攻击性的草原狼，在莫高雷石牛湖附近的丘陵中潜行。由于她对经过该地区的旅人构成了威胁，因此被特别命名。",al={"chakuyak是什么","谁是chakuyak","chakuyak是狼吗"}},{q="Chakuyak在哪里？",a="Chakuyak潜行在石牛湖正西方的林地地形中，在山丘沿线的树丛间悄悄游荡。",al={"在哪里可以找到chakuyak","chakuyak出没地点","chakuyak在哪里游荡"}},{q="为什么要狩猎Chakuyak？",a="虽然当地的草原狼是莫高雷自然生态的一部分，但Chakuyak表现得异常大胆且具有攻击性，直接威胁到了从外地进入该领地的旅人。",al={"为什么要杀掉chakuyak","chakuyak的威胁"}},{q="狩猎结束后Chakuyak的毛皮会怎样处理？",a="任务发布者会确保夺取这头强大野兽生命的举动并非毫无意义；她的毛皮会被妥善保存并加以利用，确保不会有任何浪费。",al={"chakuyak的毛皮会怎样","chakuyak的皮毛"}},{q="狩猎Chakuyak需要组队吗？",a="与普通的狼相比，Chakuyak异常凶猛且危险，旅人们通常会组成小规模的狩猎队伍来追踪她，以安全地将其击杀。",al={"打chakuyak需要组队吗","chakuyak单人好打吗"}},{q="谁会认可你击败Chakuyak的战绩？",a="指派任务的猎人承诺，一旦这头野兽被击败且毛皮被带回，他会直接向部落首领称赞你的英勇事迹。",al={"谁会奖励狩猎chakuyak的任务","chakuyak和酋长"}}},fp="8,280,28.419.0,23.408.0,24.208.0,26.125.0,33.182.0,47.156.0,35.170.0,44.157.0"}
P.entries["quest:962"] = {n="毒蛇花",s="毒蛇花是一项由皇家药剂师学会的特使，驻扎在雷霆崖的药剂师扎玛所发布的采集任务。扎玛正在寻找一种原产于哀嚎洞穴地底深处的稀有草药样本，以协助被遗忘者的研究。",h="毒蛇花是一项由皇家药剂师学会的特使，驻扎在雷霆崖的药剂师扎玛所发布的采集任务。扎玛正在寻找一种原产于哀嚎洞穴地底深处的稀有草药样本，以协助被遗忘者的研究。",kw={"药剂师","贫瘠之地","皇家药剂师学会","毒蛇花","灵魂高地","雷霆崖","幽暗城","哀嚎洞穴","扎玛"},ang={["faction:Horde"]="这项任务巩固了幽暗城与卡利姆多各部落之间早期的行动联盟，促进了跨越海洋的资源与稀有试剂的共享。",["profession:Herbalism"]="哀嚎洞穴内扭曲的环境孕育了独特的植物，而在贫瘠之地被烈日炙烤的地面上是无法找到这些植物的。",["race:Tauren"]="在灵魂高地之下接待被遗忘者药剂师体现了部落的好客，尽管他们对致命药剂的关注与传统的自然治愈理念形成了鲜明对比。",["race:Undead"]="提供毒蛇花直接支持了皇家药剂师学会在黑暗女王的指令下，于洛丹伦进行的炼金术计划。"},sec={{t="药剂师之眼",b="药剂师扎玛驻扎在雷霆崖灵魂高地下方的预见之池，她是幽暗城皇家药剂师学会的一名特使。虽然牛头人东道主们专注于精神平衡与治愈受伤的土地，但扎玛的注意力却集中在稀有且具有致命性的材料上。在分离出一种名为毒蛇花的异常植物样本后，她寻求大量的采集，以推进希尔瓦娜斯·风行者女王和被遗忘者的研究方针。"},{t="洞穴深处",b="毒蛇花并不会在贫瘠之地的烈日下生长，而是繁衍于哀嚎洞穴阴暗潮湿、蜿蜒曲折的石窟中。这种植物在被尖牙德鲁伊腐化的潮湿地底环境中培育而成，不仅难以触及，而且受到洞穴中蛇类生物的严密守卫。扎玛坦言，此前派出的多名侦察兵都有去无回，因此只能将进一步的采集工作交给身经百战的冒险者。"}},faq={{q="药剂师扎玛是谁？",a="药剂师扎玛是一位代表幽暗城皇家药剂师学会的研究员。她驻扎在雷霆崖灵魂高地下方的预见之池，担任被遗忘者炼金术师与广阔的卡利姆多大陆之间的联络人。",al={"扎玛","药剂师扎玛背景故事","谁发布了毒蛇花任务"}},{q="为什么皇家药剂师学会想要毒蛇花？",a="扎玛认为，这种草药在经过大量提炼后，具有巨大的潜在化学价值。学会一直在卡利姆多各地搜寻稀有且强力的植物，以辅助被遗忘者的炼金实验。",al={"为什么需要毒蛇花","被遗忘者草药研究","毒蛇花的用途"}},{q="毒蛇花生长在哪里？",a="毒蛇花仅生长在哀嚎洞穴的地底深处，依附在贫瘠之地北部地下的潮湿岩石长廊和地底通道中。",al={"毒蛇花在哪里","毒蛇花位置"}},{q="为什么之前的侦察兵没有回来？",a="哀嚎洞穴里充斥着退化的野兽、迅猛龙和被腐化的尖牙德鲁伊。那些被派往迷宫隧道中缺乏经验的采集者，很快就被洞穴中凶猛的掠食者和有毒的守护者所淹没。",al={"失踪的侦察兵","扎玛的侦察兵","哀嚎洞穴危险吗"}},{q="牛头人是否认可扎玛的研究？",a="雷霆崖的牛头人出于同情和治愈他们的愿望，向被遗忘者提供了庇护。但皇家药剂师学会的炼金术实践往往涉及不自然的实验，这使得传统的萨满祭司和德鲁伊感到不安。",al={"牛头人的反应","灵魂高地的药剂师"}},{q="采集毒蛇花需要草药学技能吗？",a="不需要。虽然它属于植物样本，但任何愿意闯入哀嚎洞穴深处的冒险者，都无需正式的草药学训练，可以直接从洞穴地面上采摘这些植物。",al={"需要学习草药学吗","采集毒蛇花的专业要求"}}},fx={["962715c8"]={q="药剂师扎玛为什么要收集毒蛇花？",a="药剂师扎玛受皇家药剂师协会派遣，前往雷霆崖执行一项特定任务，以维护被遗忘者和黑暗女王希尔瓦娜斯·风行者的利益。分析过一份稀有毒蛇花样本后，扎玛发现这种植物的特性潜力巨大，若能大量获取更是如此。收集到足够的样本，就能推动她的研究，助力幽暗城的科学与炼金术事业。",al={"药剂师扎玛的动机","扎玛为什么需要毒蛇花","为什么收集毒蛇花"}},["92b49307"]={q="药剂师扎玛为什么派冒险者去收集毒蛇花，而不是自己去？",a="扎玛不便轻易离开她在雷霆崖的岗位，而采集这种草药则需要深入危险且遭到腐化的哀嚎洞穴。她已经派了几名侦察兵和代理人替她进入洞穴，但他们无一生还。她需要经验丰富、能力出众的冒险者，前去普通侦察兵无法生还的幽暗深处。",al={"为什么派我去收集毒蛇花","扎玛为什么不自己采集毒蛇花","为什么派冒险者去采集毒蛇花"}}},fp="12,259,22.476.0,25.436.0,24.253.0,56.226.0,29.188.0,37.240.0,42.259.0,54.188.0"}
P.entries["quest:96243"] = {n="Call of Earth",s="Call of Earth是一项入门召唤，呼唤初学者与岩石之灵建立共鸣。旅行者必须前往寒脊山谷，并在安威玛尔的矮人据点中寻找Teo Hammerstorm。",h="Call of Earth是一项入门召唤，呼唤初学者与岩石之灵建立共鸣。旅行者必须前往寒脊山谷，并在安威玛尔的矮人据点中寻找Teo Hammerstorm。",kw={"安威玛尔","call of earth","寒脊山谷","丹莫罗","大地图腾","元素","萨满","teo hammerstorm"},ang={["class:Shaman"]="聆听大地的召唤是走上萨满之路的基础一步，它将初学者与大地深处的岩石和坚定不移的土地之灵紧密相连。",["faction:Alliance"]="丹莫罗的联盟萨满从矮人的祖传据点安威玛尔开启了他们的元素之旅。",["race:Dwarf"]="矮人与岩石和大地有着与生俱来的联系，这使得在丹莫罗深邃的宝库中与这些陆地之灵进行交流显得十分自然。"},sec={{t="岩石之声",b="对于走上元素之路的初学者而言，Call of Earth是至关重要的第一次交流。虽然元素能量可能已经在体表激荡，但学会与岩石直接交谈才能建立起坚定的平衡。它教会灵魂如何找到不可动摇的力量，在脚下以及灵魂深处打下坚实的基础。"},{t="安威玛尔据点",b="丹莫罗雪域的初学者会被指引前往安威玛尔的庇护所，这是一座由铁锤、火焰与意志锻造而成的巨大据点。在这座寒脊山谷中受人尊敬的堡垒内，Teo Hammerstorm正在等待，他将指导萨满学徒如何聆听大地的轰鸣并开始他们的元素职责。"}},faq={{q="什么是Call of Earth？",a="Call of Earth是一项入门召唤，指引有志成为萨满的玩家开始与大地之灵交流。它指示初学者寻求指引，并沉浸在活体岩石的力量中以此稳固自身。",al={"什么是call of earth","call of earth任务","这个任务是什么"}},{q="Teo Hammerstorm是谁？",a="Teo Hammerstorm是一位导师，位于寒脊山谷的安威玛尔矮人据点内。他引导初学者与大地交流，并理解其稳固的力量。",al={"teo hammerstorm是谁","teo hammerstorm在哪里","teo hammerstorm位置"}},{q="安威玛尔是什么？",a="安威玛尔是一座由铁锤、火焰与意志锻造而成的坚固据点，坐落于丹莫罗寒脊山谷的雪原之中。它是年轻英雄的核心堡垒和训练场。",al={"安威玛尔在哪里","安威玛尔是什么","安威玛尔位置"}},{q="为什么萨满必须聆听大地的召唤？",a="与大地交流可以让萨满稳固其精神本质，在脚下和灵魂深处打下坚实的基础，从而引导岩石稳固的力量。",al={"为什么要与大地交谈","call of earth的目的","萨满大地连接"}},{q="谁会接受这项召唤？",a="该任务旨在培养在丹莫罗起步的萨满，指引他们寻找经验丰富的元素训练师，以引导他们与灵魂建立连接。",al={"谁发送了call of earth","谁接受call of earth","谁做这个任务"}},{q="这个任务会将玩家引向何处？",a="这段旅程将通往安威玛尔，它坐落在丹莫罗雪域的寒脊山谷中。初学者必须深入据点去寻找他们的导师。",al={"call of earth在哪里进行","call of earth地区","去哪里"}}},fp="13,215,18.352.0,24.313.0,22.211.0,23.185.0,17.201.0,41.190.0,28.173.0,27.161.0"}
P.entries["quest:963"] = {n="永志不渝",s="“永恒之爱”是一个悲剧性的任务，由奥伯丁的塞瑞利恩·白爪发布。塞瑞利恩被他失去的爱人安娜雅·晨行者的回忆所困扰，他请求冒险者前往破碎的亚米萨兰废墟，让她那不得安息的灵魂从永恒的折磨中解脱出来。",h="“永恒之爱”是一个悲剧性的任务，由奥伯丁的塞瑞利恩·白爪发布。塞瑞利恩被他失去的爱人安娜雅·晨行者的回忆所困扰，他请求冒险者前往破碎的亚米萨兰废墟，让她那不得安息的灵魂从永恒的折磨中解脱出来。",kw={"亚米萨兰","安娜雅·晨行者","安娜雅的坠饰","奥伯丁","塞瑞利恩·白爪","黑海岸","永恒之爱","大分裂"},ang={["class:Druid"]="塞瑞利恩的命运反映了那些追随珊多·怒风进入数千年沉睡的德鲁伊所付出的个人代价，当他们苏醒时，却发现这个世界依然刻印着他们久远的伤痛。",["faction:Alliance"]="帮助塞瑞利恩让联盟英雄们得以一窥暗夜精灵盟友们那跨越千年的悲剧人生，并了解他们是如何适应苏醒后的世界的。",["race:NightElf"]="对于黑海岸的暗夜精灵而言，帮助塞瑞利恩是时刻提醒他们大分裂和远古城市陷落所留下的永恒伤痕。"},sec={{t="充满悲伤的沉睡",b="一万年前的上古之战期间，永恒之井引发的灾难将古老的卡利姆多撕裂。亚米萨兰城也是当时的牺牲品之一，塞瑞利恩·白爪在那里失去了他挚爱的安娜雅·晨行者。塞瑞利恩陷入了绝望，他跟随珊多玛法里奥·怒风进入了德鲁伊漫长的冬眠，希望在翡翠梦境中漫步的千年时光能平息他那颗破碎的心。然而，他的悲伤并未消散，而是跨越了漫长的岁月，始终如影随形。"},{t="亚米萨兰的幽灵",b="近期苏醒后，塞瑞利恩在黑海岸恍惚游荡，最终他的脚步将他带回了凄凉的亚米萨兰废墟。在那里，徘徊在古老的石块之间时，他看见了安娜雅那饱受折磨的幽灵。他不忍心对自己所爱的女人举起武器，于是请求过往的旅人消灭她那痛苦的化身，找回她的坠饰，让她那不安的灵魂最终得到安息。"},{t="跨越面纱的离别",b="当安娜雅的坠饰被送回奥伯丁后，安娜雅的幽灵残影最后一次出现在塞瑞利恩面前。从束缚她于废墟的久远苦痛中解脱后，她匆匆道别，随后消散在以太之中，只留下这位悲伤的德鲁伊在海边独自流泪，心中交织着苦涩与慰藉。"}},faq={{q="塞瑞利恩·白爪是谁？",a="塞瑞利恩·白爪是一位在奥伯丁休息的暗夜精灵德鲁伊。在一万年前的大分裂中失去挚爱安娜雅后，他跟随珊多玛法里奥·怒风进入了长期的德鲁伊休眠，带着他那未愈的创伤度过了数千年。",al={"塞瑞利恩·白爪","永恒之爱任务发布者","塞瑞利恩背景故事"}},{q="安娜雅·晨行者是谁？",a="安娜雅·晨行者是一位在大分裂之前居住在亚米萨兰城的暗夜精灵。在上古之战的余波中，随着城市沦陷，她不幸遇难，自那以后，她的幽灵一直被困在废墟之中。",al={"安娜雅·晨行者","安娜雅是谁","黑海岸的安娜雅"}},{q="安娜雅的灵魂在哪里？",a="她的灵魂徘徊在被幽灵占据的亚米萨兰古老废墟中，该遗迹位于黑海岸南部，大路以东。",al={"安娜雅位置","安娜雅·晨行者在哪里","安娜雅的坠饰位置"}},{q="为什么塞瑞利恩无法亲自解救安娜雅？",a="尽管时光流逝了一万年，塞瑞利恩对安娜雅的爱依然深沉，他不忍心亲手向她的幻影举起武器或施放法术，即使是为了结束她的痛苦也无法做到。",al={"为什么塞瑞利恩不杀安娜雅","为什么塞瑞利恩寻求帮助"}},{q="亚米萨兰发生了什么事？",a="亚米萨兰是一个古老的暗夜精灵定居点，于一万年前上古之战后的大分裂中被摧毁。它在黑海岸的废墟中至今仍充斥着徘徊的幽灵和残留的奥术回响。",al={"亚米萨兰历史","亚米萨兰的陷落","什么是亚米萨兰"}},{q="交还安娜雅的坠饰会发生什么？",a="在解救安娜雅那不安的灵魂后，将安娜雅的坠饰带给奥伯丁的塞瑞利恩。当你交还任务时，就会知晓结果。",al={"安娜雅任务交还","塞瑞利恩结局","永恒之爱结局"}}},fx={dc23d6a3={q="塞瑞利恩·白爪为什么想让安娜雅的灵魂得到解脱？",a="塞瑞利恩一直以为自己的爱人安娜雅在万年以前、亚米萨兰于天崩地裂中化为废墟时便已死去。当他发现她饱受折磨的幽魂仍在废墟中徘徊时，心都碎了。他知道她被束缚在这个世界上，承受着痛苦，无法忍受她继续受苦的念头，却也不忍亲手对她下手。",al={"塞瑞利恩为什么想让你这么做","塞瑞利恩的动机","为什么要解放安娜雅的灵魂"}},ed60ea9d={q="安娜雅的坠饰有什么用？",a="安娜雅的坠饰是塞瑞利恩请你带回的纪念物。你需要先在亚米萨兰解放她那困顿的灵魂。",al={"安娜雅的坠饰用途","安娜雅的坠饰有什么作用","安娜雅的坠饰有什么用"}}},fp="16,272,23.504.0,23.431.0,23.312.1,27.264.0,25.241.0,32.126.0,42.217.0,28.223.0,45.138.1"}
P.entries["quest:96339"] = {n="Legacy Reward: Replica Ironforge Air Rifle",s="“Legacy Reward: Replica Ironforge Air Rifle”标志着你收集了一件为你预留的神秘包裹。这件包裹由一名身份不明的信使留下，在送达你手中之前，险些被当成垃圾扔进海里。",h="“Legacy Reward: Replica Ironforge Air Rifle”标志着你收集了一件为你预留的神秘包裹。这件包裹由一名身份不明的信使留下，在送达你手中之前，险些被当成垃圾扔进海里。",kw={"气枪","铁炉堡","铁炉堡气枪","遗产奖励","神秘包裹","铁炉堡气枪复刻版"},ang={["profession:Engineering"]="修理工和枪匠们一定会喜欢这份精巧的枪械模型，尽管它是通过一位冷漠的快递员送达，且差点被丢到海底。",["race:Dwarf"]="包裹里装的是一把铁炉堡气枪的复刻版，这是对卡兹莫丹著名的枪械和机械工艺的纪念。"},sec={{t="等待领取的包裹",b="一件指名给你的神秘包裹被寄放在了一位不情愿的管理员那里。那位身份不明的快递员坚称你会亲自来取，随后便匆匆离去，连让接收者拒绝代收的机会都没有。幸运的是，你及时赶到，否则这件无人认领的包裹就要和当晚的垃圾一起被扔进大海了。"},{t="袖珍版矮人工程学",b="包裹里装着一把铁炉堡气枪复刻版，这是一款向矮人首都著名的枪械传统致敬的纪念品。虽然矮人登山者和神射手在丹莫罗随身携带致命的火力，但像这样的复刻品旨在颂扬由铁炉堡工匠完善的复杂枪管工艺和气动装置。"}},faq={{q="是谁寄来的包裹？",a="快递员或最初的寄件人从未留下姓名或解释。据保管包裹的接收人所说，有人把专门留给你的包裹放下后，坚持说你迟早会来认领，随后在还没人得及询问的情况下就消失了。",al={"谁寄的包裹","气枪的寄件人","谁留下了这把枪"}},{q="这件包裹险些遭遇什么？",a="如果你没有及时赶到，包裹就会和当晚的垃圾一起被扔进大海。管理员承认他们并不提供寄存服务，通常会把不需要的杂物直接丢进海里。",al={"包裹本来会发生什么","海里的垃圾","包裹被扔掉"}},{q="包裹里装的是什么？",a="包裹里装有一把铁炉堡气枪复刻版，作为专门留给你的遗产物品寄送。它是一件纪念品，代表了矮人的枪械设计。",al={"包裹里有什么","复刻枪内容物","包裹奖励"}},{q="为什么管理员要保管这件包裹？",a="保管者明确表示他们不提供邮件代收或存储服务。这件包裹之所以被留下，仅仅是因为那位神秘的快递员走得太急，在消失之前根本没有机会拒绝代收。",al={"他们为什么要保管","代收邮件","这里保管包裹吗"}},{q="为什么这被称为遗产奖励？",a="《WoW Forever》中的“遗产奖励”代表了神秘恩人留给资深冒险者的特殊认可和包裹，它们在指定的哨站等待着你，等你抵达后即可取回。",al={"为什么叫遗产奖励","遗产奖励传说","这里的遗产是什么意思"}},{q="这把复刻步枪是功能性武器吗？",a="它被特别标注为铁炉堡气枪的复刻版，是仿照工艺精湛的矮人远程武器制作的，而非一线作战步枪。",al={"这把枪是真武器吗","能用它射击吗","复刻品功能"}}},fp="42,239,29.337.0,32.333.0,22.273.0,36.226.0,26.178.0,42.224.0,39.202.0,41.169.0"}
P.entries["quest:96390"] = {n="Nip 'Em in the Bud",s="Nip 'Em in the Bud 是由大地先知法森委托的一项任务，旨在清除潜入丹莫罗的黑铁矮人间谍。这些秘密行动人员被发现在铁环营地附近徘徊，威胁到了铜须矮人家园的安全。",h="Nip 'Em in the Bud 是由大地先知法森委托的一项任务，旨在清除潜入丹莫罗的黑铁矮人间谍。这些秘密行动人员被发现在铁环营地附近徘徊，威胁到了铜须矮人家园的安全。",kw={"黑铁地图","黑铁间谍","丹莫罗","大地先知法森","领主大厅","铁环营地","nip 'em in the bud","underground map"},ang={["faction:Alliance"]="消灭丹莫罗境内的敌方斥候可以确保铁炉堡重要的补给线和周边哨所免遭破坏。",["race:Dwarf"]="对于铜须矮人来说，清除祖居山脉中的黑铁渗透者是保卫家园与延续氏族复仇的大事。"},sec={{t="严寒中的注视",b="长期以来，丹莫罗一直是铁炉堡矮人的堡垒与避风港，但矮人氏族之间古老的宿怨从未真正平息。黑铁矮人的渗透者溜过了高耸的山口与积雪的岩脊，形迹可疑地潜伏在重要的挖掘场和定居点附近。大地先知法森意识到，即使是少数隐藏的观察者也可能预示着一场毁灭性的袭击，因此他呼吁联盟的忠诚卫士在他们的阴谋得逞前将其铲除。"},{t="铁环营地附近的威胁",b="这些间谍将他们的窥探活动集中在铁环营地周围，这是丹莫罗东部的一个重要地点。虽然法森起初无法断定他们的确切动机，但击败这些秘密特工却揭示了他们更大阴谋的实物证据。在被击败的斥候身上搜出的黑铁地图证实，他们的闯入绝非简单的侦察行动，而是为通往领主大厅这类古老地下秘密做准备。"}},faq={{q="谁提供了任务 Nip 'Em in the Bud？",a="该任务由大地先知法森在完成任务 Farsen's Watch 后提供，呼吁帮助处理丹莫罗境内的入侵者。",al={"任务 nip 'em in the bud 委托人","谁开启 nip 'em in the bud","法森任务"}},{q="为什么黑铁矮人间谍会出现在丹莫罗？",a="黑铁氏族一直在策划针对铜须族人的阴谋。渗透到丹莫罗东部使他们的特工能够监视定居点，并挖掘或侦察铁环营地附近的地下通道。",al={"为什么这里有黑铁间谍","黑铁矮人在丹莫罗做什么","铁环营地黑铁间谍"}},{q="黑铁矮人间谍位于何处？",a="他们集中在丹莫罗东部的铁环营地附近，从积雪的周边地区进行监视。",al={"间谍位置","黑铁间谍在哪里","去哪里找间谍"}},{q="什么任务指引到这里？",a="这项任务在报告完成 Farsen's Watch 后解锁，将防御工作从单纯的观察提升到了主动清除的阶段。",al={"前置任务","在 nip 'em in the bud 之前的任务是什么","nip 'em in the bud 前置任务"}},{q="在猎杀这些间谍时发现了什么？",a="被击杀的间谍会掉落黑铁地图，该物品开启任务 Underground Map，并指向与领主大厅相关的深层秘密。",al={"间谍掉落什么","黑铁地图掉落","nip 'em in the bud 之后的任务是什么"}},{q="大地先知法森是谁？",a="大地先知法森是一位驻扎在丹莫罗的敏锐矮人，负责监测雪山各处不寻常的地震活动和敌对氏族的动向。",al={"谁是法森","大地先知法森背景"}}},fx={bdd12e65={q="大地之灵法师法尔森为什么想除掉黑铁间谍？",a="大地之灵法师法尔森知道，黑铁矮人在丹莫罗站稳脚跟，就会给铁炉堡及周边土地带来危险。虽然他不清楚对方的具体动机，但放任潜入者肆意行动，只会招致更大规模的破坏甚至公开袭击。他想立即铲除他们的势力，以免他们正在筹划的阴谋得逞。",al={"法尔森为什么想杀死间谍","大地之灵法师法尔森的动机","为什么要斩草除根"}}},fp="18,247,16.475.0,31.452.1,40.132.0,38.228.0,38.121.0,26.137.0,44.134.1,24.146.0"}
P.entries["quest:96391"] = {n="Underground Map",s="这张地下地图是从铁环营地附近的潜入间谍身上缴获的，它揭示了通往铁炉堡根基的秘密隧道网络。地图上崎岖的黑铁地图符文勾勒出一条直通山底古老密室的隐秘地下路线。将其交给大地之环先知法尔森，是揭露即将到来的地下入侵阴谋的第一步。",h="这张地下地图是从铁环营地附近的潜入间谍身上缴获的，它揭示了通往铁炉堡根基的秘密隧道网络。地图上崎岖的黑铁地图符文勾勒出一条直通山底古老密室的隐秘地下路线。将其交给大地之环先知法尔森，是揭露即将到来的地下入侵阴谋的第一步。",kw={"黑铁地图","丹莫罗","大地之环先知法尔森","领主大厅","铁环营地","铁炉堡","underground map"},ang={["class:Shaman"]="引导你去找大地之环先知法尔森的那阵微弱的阵风，暗示了元素之灵正在对丹莫罗下方非自然的地下挖掘活动发出警告。",["faction:Alliance"]="消除这一地下渗透路线对于维护铁炉堡及联盟北部据点的安全至关重要。",["race:Dwarf"]="对于铜须矮人来说，发现黑铁矮人的隧道直接切向铁炉堡的地基，是对首都领土完整性的严重侵犯。"},sec={{t="渗透蓝图",b="从铁环营地附近的黑铁间谍身上缴获的羊皮纸上，展示了一个错综复杂的地下道路迷宫。上面刻着黑铁氏族特有的粗犷而崎岖的符文，图纸描绘了直接汇聚在铁炉堡下方的深层地下通道。这些汇聚的通道暗示了铜须之都下方可能存在威胁，但地图上的黑铁注释内容尚不明确。"},{t="风中低语",b="在研究这份粗糙的地图时，一阵非自然的狂风带来了一个矮人声音微弱的低语，催促着采取果断行动。这个神秘的提示直接指向了大地之环先知法尔森。报告这一情报将揭露针对城市下方深处被封印的古老殿堂的初期活动，这些活动威胁到了山中王国的避难所。"}},faq={{q="这张地下地图从何而来？",a="这张地图由在丹莫罗铁环营地周边进行勘测的黑铁间谍携带。在山脚下对付他们的侦察兵时可以找到它。",al={"地图掉落","哪里寻找地图","如何获取地下地图"}},{q="地图上显示了什么？",a="它勾勒出一个复杂的地下公路和隧道网络，如同蛇行般穿过大地，所有这些通道都直接汇聚在铁炉堡城下。",al={"地图上有什么","地图细节","黑铁地图目的"}},{q="谁是大地之环先知法尔森？",a="大地之环先知法尔森是一位来自鹰巢山的矮人大地之环先知，能够感应深层的岩石和山脉之灵。他察觉到了非自然的地下活动，需要这张地图来评估铁炉堡下方的缺口。",al={"法尔森在哪里","谁是法尔森","大地之环先知"}},{q="为什么黑铁矮人要挖掘铁炉堡的下方？",a="地图暗示了铁炉堡下方可能存在一条路线，但其黑铁注释尚未被解读。大地之环先知法尔森需要对其进行检查，然后才能确定该计划的目的。",al={"为什么黑铁矮人要挖掘","丹莫罗黑铁阴谋"}},{q="这个任务后续是什么？",a="将这张地图交给大地之环先知法尔森，开启了对城市下方深处的调查工作，并将直接导致Old Ironforge Incursion任务，并开启通往领主大厅的入口。",al={"地下地图后续","地下地图的下一个任务"}},{q="地图上的符文是什么语言？",a="这张地图使用了黑铁矮人的崎岖符文。发现它的人无法确定注释的具体含义。",al={"地图符文","黑铁语言"}}},fx={["1c73103d"]={q="为什么必须把黑铁地图交给大地之灵法师法尔森？",a="这张地图详细标出了纵横交错的地下隧道和道路，它们全都汇聚于铁炉堡正下方。地图上粗犷的黑铁符文需要解读，而风中传来的诡异矮人声音也表明，大地之灵法师法尔森必须立即调查潜在的地下威胁，向这座山中王国发出警告。",al={"为什么把地图交给法尔森","黑铁地图的用途","为什么要送地图"}}},fp="15,383,27.404.0,20.344.1,41.165.0,23.147.0,24.216.0,49.181.0,29.201.1,45.127.0"}
P.entries["quest:96392"] = {n="Farsen's Watch",s="Farsen's Watch 是由大地之环成员 Farsen 给予的一项观察任务。这位蛮锤萨满正在古博拉采掘场上方的高处驻守。利用这位大地之环成员的萨满远视术，冒险者们可以亲眼目睹黑铁矮人对丹莫罗腹地的渗透。这次至关重要的侦察标志着通往领主大厅之路的早期阶段。",h="Farsen's Watch 是由大地之环成员 Farsen...",kw={"鹰巢山","黑铁矮人","丹莫罗","大地之环成员","farsen","远视术","古博拉","领主大厅","蛮锤部族"},ang={["class:Shaman"]="蛮锤大地之环成员展示了他们传统中对大地和灵性的洞察力，为人们展现了扎根于鹰巢山峭壁的矮人萨满教义的一角。",["faction:Alliance"]="揭露丹莫罗的黑铁矮人阴谋对于维护铁炉堡及周边山口的安全，保障所有联盟成员的通行至关重要。",["race:Dwarf"]="对于铜须矮人守卫来说，收到来自鹰巢山同族的警告，凸显了黑铁矮人对他们家园的渗透已经变得多么肆无忌惮。"},sec={{t="跨越山脊的视线",b="Farsen 栖身于古博拉采掘场风雪覆盖的挖掘点上方，时刻警惕地监视着丹莫罗的下层区域。这位蛮锤客人从鹰巢山的峭壁远道而来，将敏锐的灵性感知带到了通常由铁炉堡山地探险队员巡逻的土地上。Farsen 不依赖普通的侦察兵，而是运用他所在氏族的传统技艺来监测地下的隆隆声和山坡上异常的动向。"},{t="借来的视野",b="为了让旅行者们相信即将到来的危险，Farsen 将他的远视术借给他们——这是一种能将一个人的意识投射到远方的萨满天赋。透过这面灵性透镜，可以清晰地看出丹莫罗面临的问题早已超出了那些捣乱的石腭怪和野兽。黑铁矮人已经潜入铁炉堡工业中心附近，并正在那里稳固阵地，进行一项必须在扎根之前就立即制止的行动。"}},faq={{q="大地之环成员 Farsen 是谁？",a="大地之环成员 Farsen 是一位从辛特兰鹰巢山来到丹莫罗访问的蛮锤矮人。作为一名大地之环成员，他掌握着萨满魔法，这使他能够感知土地上的不安并从远处观察威胁。",al={"大地之环成员 farsen","farsen 是谁","蛮锤部族 farsen"}},{q="这个观察任务发生在哪里？",a="大地之环成员 Farsen 驻守在俯瞰古博拉采掘场的位置，这是一个位于丹莫罗东部的铜须矮人重点采矿挖掘点。",al={"farsen 的位置","farsen 在哪里","采掘场俯瞰点"}},{q="Farsen 揭示了什么威胁？",a="通过他的萨满远视术，Farsen 揭示了敌对的黑铁矮人已经在附近建立了立足点，这对该地区构成了活跃且危险的威胁。",al={"远视术显示了什么","黑铁矮人威胁","farsen 的视野"}},{q="这与领主大厅有什么联系？",a="调查在 Farsen's Watch 期间发现的黑铁矮人踪迹，是寻求进入领主大厅的冒险者们所需完成的一系列大型任务的开端。",al={"领主大厅的准入要求","领主大厅任务线"}},{q="为什么会有蛮锤矮人参与丹莫罗的防御？",a="虽然蛮锤矮人以辛特兰为家，但血缘纽带和对黑铁矮人共同的敌意，偶尔会让像 Farsen 这样的旅行者来到铜须矮人的祖地丹莫罗。",al={"为什么蛮锤矮人会在这里","鹰巢山矮人 丹莫罗"}},{q="完成 Farsen's Watch 后紧接着是什么？",a="一旦你通过他的视野见证了黑铁矮人的渗透，Farsen 就会催促你继续执行“防患于未然”任务，以积极压制入侵的敌人。",al={"后续任务","farsen's watch 之后是什么","防患于未然"}}},fx={["73fc96dc"]={q="大地之灵法师法尔森为什么想让你这么做？",a="大地之灵法师法尔森从鹰巢山途经丹莫罗时，发现黑铁矮人正在古博拉采掘场附近步步进逼。萨满不想贸然行动或惊动众人，而是希望你借助他的千里眼魔法亲眼见证正在酝酿的危险，确保铁炉堡的守军了解敌方渗透的真实规模，以免事态失控。",al={"法尔森的守望任务为何而来","法尔森的动机","法尔森为什么让我去查看"}}},fp="14,364,21.463.0,17.448.0,24.219.0,33.127.0,31.165.0,44.164.0,59.191.0,52.174.0"}
P.entries["quest:96393"] = {n="Old Ironforge Incursion",s="“Old Ironforge Incursion”是调查潜伏在铁炉堡深处的黑铁矮人渗透者的最终任务。在大地之环先知法森（Earthseer Farsen）的指引下，勇士们将深入Old Ironforge下方的领主大厅，消灭敌方指挥官Durgen Dirgehammer，并直接向国王麦格尼·铜须汇报这一威胁。",h="“Old Ironforge Incursion”是调查潜伏在铁炉堡深处的黑铁矮人渗透者的最终任务。在大地之环先知法森（Earthseer Farsen）的指引下，勇士们将深入Old...",kw={"黑铁矮人","dirgehammer","法森","入侵","铁炉堡","卡拉诺斯","麦格尼","领主"},ang={["faction:Alliance"]="阻止这次入侵可以防止针对联盟在东部王国主要据点的毁灭性偷袭。",["race:Dwarf"]="对于铜须氏族而言，黑铁矮人渗透者潜伏在High Seat下方被遗忘的金库中，是对他们祖传堡垒不可容忍的侵犯。"},sec={{t="突破金库",b="在发现一张揭示黑铁矮人行动的地下地图后，先知法森确认了这场地下入侵背后的主谋。在Old Ironforge古老的石质大厅深处，隐藏着通往领主大厅的入口。当上层城市忙于地面的事务时，阴险的势力已经潜入了王国脚下这些沉寂已久的洞穴。"},{t="Durgen Dirgehammer",b="法森对缴获的黑铁矮人文件进行翻译后，指出了策划这一系列行动的指挥官：Durgen Dirgehammer。他驻扎在下层金库深处，对铜须山脉王国的核心构成了直接威胁。为了折断这次入侵的脊梁，冒险者们必须深入地底，将其击杀，并将他的头颅带给上方的国王麦格尼·铜须。"},{t="觐见国王",b="将Durgen Dirgehammer的头颅呈交给国王麦格尼·铜须，证实了黑铁矮人的威胁正在城市古老的根基中蔓延这一严峻事实。冒险者们带着胜利的血腥证明以及老友法森的个人问候，正式结束了此次调查，并确保麦格尼知晓了潜伏在下方的危机。"}},faq={{q="什么是Old Ironforge Incursion？",a="这是调查丹莫罗下方黑铁矮人活动的任务线终章。该任务由先知法森发布，要求玩家进入Old Ironforge下方的领主大厅，击杀黑铁矮人指挥官Durgen Dirgehammer。",al={"old ironforge incursion任务","durgen dirgehammer任务"}},{q="这个任务发生在哪里？",a="该任务将冒险者们带入领主大厅，这是一个位于Old Ironforge下方，深埋在山脉首都基岩之中的古老地下室。",al={"领主大厅在哪里","领主大厅位置"}},{q="Durgen Dirgehammer是谁？",a="Durgen Dirgehammer是领导此次地下入侵Old Ironforge下方领主大厅的黑铁矮人指挥官。先知法森通过回收的黑铁矮人文件确认了他的名字。",al={"dirgehammer是谁","durgen dirgehammer"}},{q="谁发布任务，谁接收任务？",a="该任务在回收Underground Map后由先知法森发布。任务直接在铁炉堡交给国王麦格尼·铜须完成。",al={"old ironforge incursion任务发布者","谁交付old ironforge incursion"}},{q="我该如何开启导致此任务的任务线？",a="该任务线始于任务“A Visitor to Dun Morogh”，由丹莫罗卡拉诺斯外面的贝尔丁·钢架提供。",al={"如何开始领主大厅任务","a visitor to dun morogh开始"}},{q="先知法森和国王麦格尼之间有什么联系？",a="先知法森自认为是国王麦格尼·铜须的老友，并指示冒险者在王座大厅呈交Durgen Dirgehammer的头颅时转达他的个人问候。",al={"法森与麦格尼","先知法森背景故事"}}},fx={bdae81a8={q="大地之灵法师法尔森为什么想杀死杜根·哀锤？",a="法尔森发现敌人在山下的行动，并破译了命令，得知杜根·哀锤正是率领部队入侵Old Ironforge的指挥官。黑铁矮人出现在古老的领主大厅，直接从地下威胁着矮人首都。法尔森派你除掉他们的首领，意在粉碎这场进攻，阻止黑铁矮人站稳脚跟，并将确凿的威胁证据直接送到国王麦格尼·铜须手中。",al={"法尔森的动机","为什么要杀死杜根·哀锤","法尔森为什么派你去"}},["664606f0"]={q="杜根·哀锤的头颅有什么用？",a="你需要拿杜根·哀锤的头颅作为确凿证据，向国王麦格尼·铜须证明地下袭击的指挥官已被处置。将这件血腥的战利品直接送到王座厅，便能证实领主大厅中的黑铁矮人突击部队失去了首领，同时把大地之灵法师法尔森的亲笔警告带给国王。",al={"杜根·哀锤的头颅有什么用","为什么要带回杜根的头颅","杜根·哀锤的头颅"}}},fp="23,341,20.394.0,18.411.1,22.347.1,32.237.0,33.165.0,26.200.0,41.150.0,50.117.0,63.190.0"}
P.entries["quest:96394"] = {n="The Restless Dead",s="“The Restless Dead”讲述了领主大厅地下墓穴中一起令人不安的骚乱，古老的矮人灵魂从沉睡中被惊醒。由于看守者们不敢进入地下室，一位冒险者必须深入墓穴，让愤怒的幻影和安威玛尔之灵重归安宁。",h="“The Restless Dead”讲述了领主大厅地下墓穴中一起令人不安的骚乱，古老的矮人灵魂从沉睡中被惊醒。由于看守者们不敢进入地下室，一位冒险者必须深入墓穴，让愤怒的幻影和安威玛尔之灵重归安宁。",kw={"安威玛尔","矮人墓穴","矮人灵魂","狂怒的幻影","鬼魂","领主大厅","安威玛尔之灵","the restless dead","受折磨的灵魂"},ang={["class:Priest"]="那些徘徊在痛苦或愤怒中的灵魂，对于那些能够与灵魂沟通并指引困顿的亡者走向宁静安息的人来说，是直接的职责召唤。",["faction:Alliance"]="确保铁炉堡下方祖先墓穴的安全，能保证看守者们在履行神圣职责时，无需担心被复仇的幻影所淹没。",["race:Dwarf"]="领主大厅安葬着受人尊敬的亡者和矮人先祖，他们突如其来的剧烈躁动，构成了矮人文明核心地带的一场令人不安的骚乱。"},sec={{t="深处地下室的骚乱",b="在领主大厅地表深处，祖先的墓穴里安葬着数代受人尊敬的亡者。这些通常在宁静沉睡中的灵魂，因地下室里一场看不见的骚乱而变得狂暴不安。从下方传来的阵阵怪声吓坏了此处的看守者，在恢复秩序之前，他们拒绝进入下层房间履行职责。冒险者们被召集起来，深入那阴森的石厅，平息这些躁动的灵魂。"},{t="平息先祖",b="在领主大厅安息的灵魂以浅眠著称。无论是什么事件或存在震动了下层的墓穴，都激起了阵阵狂怒的幻影和受折磨的灵魂，将这片圣地变成了险象环生的鬼蜮。其中被惊醒的就包括受人崇敬的安威玛尔之灵，需要以恭敬而坚定的手段来平息这些被唤醒的先祖的怒火，使墓穴重归平静。"}},faq={{q="“The Restless Dead”任务是关于什么的？",a="“The Restless Dead”是一项调查并平息领主大厅地下幽灵骚乱的任务。某人或某种东西惊扰了埋葬在此的灵魂，导致看守者们在处理掉这些幽灵之前不敢进入地下室。",al={"什么是 the restless dead","这个任务是什么","the restless dead 任务概述"}},{q="灵魂为什么会苏醒？",a="地下室深处一场未知的骚乱唤醒了安葬的亡者。由于领主大厅的灵魂被描述为睡眠很浅，发生在墓穴底部的任何事情都可能惊扰他们，使其陷入愤怒和痛苦的疯狂。",al={"鬼魂为什么愤怒","是谁惊扰了墓穴","幻影为什么苏醒"}},{q="骚乱发生在哪里？",a="这场骚乱集中在领主大厅的地下墓穴和拱顶，这里是位于铁炉堡下方的一处祖先安息之地，古老的矮人灵魂在此长眠。",al={"领主大厅在哪里","the restless dead 在哪里刷新","领主大厅位置"}},{q="安威玛尔之灵是谁？",a="安威玛尔之灵是一个安息在领主大厅深处墓穴中的古老而显赫的灵魂。与其他较弱的幻影一样，这位伟大的灵魂从沉睡中被惊醒，必须让他重归宁静的安息。",al={"安威玛尔之灵是谁","安威玛尔之灵背景故事","安威玛尔鬼魂是谁"}},{q="为什么看守者需要冒险者的帮助？",a="看守者是被指派照看墓穴并在领主大厅履行日常职责的守护者。由于愤怒的灵魂在厅内游荡，在威胁被消除之前，他们拒绝下到下层地下室。",al={"看守者是谁","为什么看守者需要帮助","领主大厅看守者"}},{q="领主大厅里有哪些灵魂在作祟？",a="受到惊扰的地下室里有狂怒的幻影、受折磨的灵魂，以及受人尊崇的安威玛尔之灵本身，它们都因受到惊吓而在墓室中开始了狂暴的游荡。",al={"下面有哪些鬼魂","领主大厅里的幻影","the restless dead 的类型"}}},fp="17,321,30.474.0,22.404.1,38.258.0,30.226.0,39.169.0,30.215.0,45.228.0,38.184.0"}
P.entries["quest:96395"] = {n="An Ancient Grudge",s="在历史悠久的领主大厅深处，一位以太侍从恳求结束一位陨落统治者的折磨。Faldrim Anvilmar 的灵魂仍在徘徊，被旧日的怨恨所吞噬，无法获得永恒的安宁。冒险者们被委派去让这位不安息的领主获得安息。",h="在历史悠久的领主大厅深处，一位以太侍从恳求结束一位陨落统治者的折磨。Faldrim Anvilmar 的灵魂仍在徘徊，被旧日的怨恨所吞噬，无法获得永恒的安宁。冒险者们被委派去让这位不安息的领主获得安息。",kw={"ancient grudge","安威玛尔","矮人鬼魂","faldrim anvilmar","幽灵侍从","领主大厅","不安的灵魂","领主"},ang={["class:Paladin"]="让受折磨的灵魂安息是发誓为受苦死者带来和平的神圣战士的神圣职责。",["class:Priest"]="牧师们明白，挥之不去的怨恨和未获救赎的悲伤可以在肉体化为尘土许久之后，仍将凡人的灵魂束缚在物质位面。",["race:Dwarf"]="对于矮人来说，面对自己族人的一位不安领主是一个令人清醒的提醒：古老的怨恨可以比死亡本身更长久。"},sec={{t="An Ancient Grudge",b="在领主大厅的石质拱顶内，死亡并没有提供即刻的解脱。Faldrim Anvilmar 的一位幽灵侍从在那里徘徊，几乎无法积攒起足够的力量穿过凡世的面纱进行交谈。这个幻影并不寻求自身的自由，它唯一关心的是它的主人，恳求旅行者安抚这位不安的领主灵魂。"},{t="过去的重负",b="死亡并没有让 Faldrim Anvilmar 从过去中解脱出来。被一种吞噬一切的古老怨恨束缚在物质世界，Faldrim 的灵魂依然躁动且充满敌意，如果不被强行解脱，就无法找到安眠。"}},faq={{q="Faldrim Anvilmar 是谁？",a="Faldrim Anvilmar 是一位矮人领主，他那不安的幻影如今盘踞在领主大厅。他的幽灵侍从说他被一种古老的怨恨所吞噬，无法找到安宁。该任务没有提及关于他的生平或血统的更多信息。",al={"faldrim anvilmar 传说","faldrim 是谁","领主 anvilmar"}},{q="领主大厅位于何处？",a="领主大厅位于铁炉堡这座矮人首都内部，Old Ironforge 下方的洞穴中。",al={"领主大厅位置","领主大厅在哪里","领主大厅入口"}},{q="为什么 Faldrim Anvilmar 的灵魂带有敌意？",a="根据这位幽灵侍从的说法，这位前任领主被一种古老的怨恨所吞噬。矮人的历史沉浸在数百年的部族竞争中，而 Faldrim 挥之不去的仇恨阻止了他的灵魂进入安宁的沉睡。",al={"faldrim 为什么愤怒","为什么领主会攻击","ancient grudge 解释"}},{q="谁提供了任务 An Ancient Grudge？",a="该任务由在领主大厅内发现的一位幽灵侍从提供。即使死后仍被束缚在仆役身份中，这位侍从只寻求为其前主人带来安宁。",al={"谁给予 ancient grudge","幽灵侍从任务","任务提供者"}},{q="你必须做什么来完成这个任务？",a="你必须在领主大厅内面对 Faldrim Anvilmar 的灵魂，在战斗中击败他那不安的鬼魂以将其从折磨中解脱，然后回到幽灵侍从那里报告。",al={"如何完成 ancient grudge","让 faldrim 安息","ancient grudge 目标"}},{q="Faldrim 与安威玛尔镇有关吗？",a="目前尚不清楚。Faldrim 与寒脊山谷的安威玛尔定居点名字相同，但该任务没有提及他的家人或与该镇的任何联系。",al={"faldrim 来自 anvilmar 吗","anvilmar 和寒脊山谷的联系","anvilmar 家族"}}},fp="17,276,21.348.0,22.214.1,24.233.0,36.102.0,45.234.0,38.168.0,39.186.0,43.166.0"}
P.entries["quest:96403"] = {n="Important Heirlooms",s="Important Heirlooms 是一个任务，冒险者将协助一位名叫Thom的紧张的侏儒。当黑铁矮人利用地下钻探机突破金库时，他正潜伏在领主大厅内被当场撞见。任务要求玩家在所谓的“历史保护”幌子下，找回散落在各处的矮人遗物。",h="Important Heirlooms...",kw={"黑铁矮人","矮人传家宝","侏儒","领主大厅","important heirlooms","钻探机","thom","宝库"},ang={["class:Rogue"]="潜行者很容易看穿Thom那拙劣的“巡逻”借口，认出这是另一个因地下入侵而被困住的拾荒者。",["race:Dwarf"]="矮人冒险者可能会对Thom突然热衷于打捞祖先遗物持深度怀疑态度，尤其是考虑到他关于战利品和估价的口误。",["race:Gnome"]="Thom的投机本性和笨拙的掩饰，突显了在面对宝贵文物时，侏儒好奇心不那么学术的一面。"},sec={{t="宝库中的麻烦",b="在探索领主大厅的地下宝库时，一位投机取巧的侏儒Thom被突然出现的黑铁矮人打断了，他们正驾驶着钻探机从地下钻出。Thom无法独自确保该地区的安全，于是招募路过的冒险者深入危险的挖掘现场，在入侵者抢走或摧毁文物之前，找回散落在各房间里的宝贵矮人遗物。"},{t="文化保护还是牟取暴利？",b="尽管Thom坚持说他只是在巡逻，并希望将这些遗物编目以进行保护，但他不断说漏嘴提到“无价的战利品”和“评估收获”，这表明他有更自私的动机。冒险者因其勇敢行为获得了丰厚的报酬，但这些古代矮人宝藏最终是会被送进博物馆，还是落入拍卖行，仍是个未知数。"}},faq={{q="Thom是谁？",a="这个任务由Thom发布，他是一个出现在宝库附近的投机侏儒。他紧张时的口误表明，相比合法的金库安保，他对那些利润丰厚的战利品更感兴趣。",al={"任务发布者是谁","thom是谁","任务发布者"}},{q="什么是领主大厅？",a="领主大厅是一处矮人地下宝库，内存放着古代文物和传家宝。最近，该处被黑铁矮人的地下部队攻破。",al={"什么是领主大厅","领主大厅在哪里"}},{q="为什么黑铁矮人在宝库里？",a="一支黑铁矮人突击队利用地下钻探机直接从深处攻破了宝库，使该地区陷入混乱，其目的尚不明确。",al={"为什么黑铁矮人会出现在那里","黑铁矮人钻探机"}},{q="Thom真的在归还传家宝吗？",a="Thom经常说漏嘴，把潜入称为“巡逻”，把传家宝称为“战利品”和“收获”，把编目称为“评估”。虽然他支付了约定的报酬，但他声称要将遗物送回荣誉之地的说法非常可疑。",al={"thom在撒谎吗","thom在偷窃吗","thom是否值得信赖"}},{q="什么是矮人传家宝？",a="它们是存放在领主大厅内的古代矮人文物，被历史学家视为无价之宝，而被像Thom这样的投机者视为利润丰厚的战利品。",al={"什么是传家宝","矮人传家宝背景"}},{q="为什么Thom不能自己找回传家宝？",a="当黑铁矮人的钻探机突然出现时，Thom正潜伏在宝库中，被打了个措手不及，导致他在没有冒险者保护的情况下无法安全地搜寻这些遗物。",al={"为什么thom需要帮助","为什么要帮助thom"}}},fp="19,306,21.398.0,43.388.1,12.191.0,27.167.0,40.162.0,39.237.0,31.167.0,46.196.0"}
P.entries["quest:96408"] = {n="A Visitor to Dun Morogh",s="“丹莫罗的访客”是贝尔丁·钢架在卡拉诺斯外发布的一项调查任务。山地巡逻队员报告称，在俯瞰古博拉采掘场的悬崖高处发现了一处陌生的营火，因此派遣一名侦察兵去查明那个陌生人是否对当地的矮人构成了威胁。",h="“丹莫罗的访客”是贝尔丁·钢架在卡拉诺斯外发布的一项调查任务。山地巡逻队员报告称，在俯瞰古博拉采掘场的悬崖高处发现了一处陌生的营火，因此派遣一名侦察兵去查明那个陌生人是否对当地的矮人构成了威胁。",kw={"贝尔丁·钢架","丹莫罗","大地之环先知法尔森","farsen's watch","古博拉采掘场","领主大厅","卡拉诺斯","访客"},ang={["class:Shaman"]="与大地之环先知法尔森的会面直接联系着与山石的精神沟通，这在丹莫罗的雪域高地上是非常罕见的景象。",["faction:Alliance"]="协助卡拉诺斯外的当地山地巡逻队员，可以确保补给线和采掘场工人们免受突发威胁。",["race:Dwarf"]="对于铜须矮人而言，监视那些俯瞰如古博拉采掘场等大型矿区的未经邀请的观察者，是保护卡兹莫丹边境的标准安全措施。"},sec={{t="高处的烟雾",b="丹莫罗的山地巡逻队员们一直勤勉地守护着铁炉堡周围的峭壁和雪谷。当一处营火突然出现在古博拉采掘场上方的高处时，卡拉诺斯的人们警觉了起来。贝尔丁·钢架对这处位于矮人重要挖掘地点正上方的异常营地感到担忧，于是招募旅行者前往山脊，确认这位神秘的陌生人究竟是无害的旅人还是入侵者。"},{t="会见大地之环先知",b="前往山脊调查后发现，这位旅行者是大地之环先知法尔森，一位在风雪高地上搭起营地的神秘人士。这位神秘的观察者并非劫掠的穴居人或怀有敌意的间谍，而是与大地有着深厚的精神联系。他在俯瞰采掘场的悬崖上的存在，开启了一段揭示卡兹莫丹地下深处潜藏的更严重动荡的旅程，并最终与领主大厅的谜团联系在了一起。"}},faq={{q="是谁派你去调查这位访客的？",a="贝尔丁·钢架，驻扎在丹莫罗的卡拉诺斯外，在山地巡逻队员报告山上出现不明火光后发布了此任务。",al={"谁发布此任务","任务起始","贝尔丁·钢架任务"}},{q="神秘的营地位于哪里？",a="营火位于卡拉诺斯以东积雪覆盖的山脊高处，正好俯瞰着古博拉采掘场的挖掘现场。",al={"营地位置","访客在哪里","访客地点"}},{q="在采掘场上方俯瞰的访客是谁？",a="这位访客是大地之环先知法尔森，一位居住在采掘场上方高处偏僻营地里的精神观察者。",al={"谁是法尔森","谁是访客","大地之环先知法尔森"}},{q="为什么矮人们会对那处营火起疑？",a="古博拉采掘场是矮人的一项关键作业，本就承受着当地穴居人的压力。任何位于矿坑上方的高处不明营地，都有可能是监视矮人动向的侦察兵或敌对势力。",al={"为何怀疑","为何调查","为何派我去"}},{q="这项任务会引出什么后续？",a="向大地之环先知法尔森报告后将直接开启任务“法尔森的注视”，这也是领主大厅准入任务线的开端。",al={"what comes next","后续任务","领主大厅引导"}},{q="你需要在这个营地与那个陌生人战斗吗？",a="不需要。虽然贝尔丁·钢架让你做好了可能发生暴力的准备，但这位访客是大地之环先知法尔森，他是一位愿意与你交谈的和平观察者。",al={"访客是否有敌意","我要杀死访客吗","访客战斗"}}},fx={["3b0d76fb"]={q="贝尔丁·钢架为什么找冒险者帮忙，而不是找巡山人？",a="当地的巡山人远远看见了山坡上的营火，但他们人手紧缺，必须守卫道路、定居点和采掘场，防范穴居人和野兽。既然那堆火很可能并无危险，贝尔丁便请一位途经卡拉诺斯、身手不凡的旅人迅速去山脊探查，而不必从正在执勤的卫兵中抽调人手。",al={"为什么派我去","为什么不派卫兵","贝尔丁·钢架为什么选我"}}},fp="23,274,28.427.0,21.440.1,41.138.0,41.132.0,42.114.1,48.212.0,31.154.1,46.153.1"}
P.entries["quest:965"] = {n="奥萨拉克斯之塔",s="哨兵艾莉萨·星风肩负着保卫奥伯丁的重任，她怀疑北方的古代遗迹中隐藏着邪恶的勾当。她委托冒险者去寻找巴苏尔·影击，一名被派去监视神秘的奥萨拉克斯之塔，却未按时汇报情况的侦察兵。",h="哨兵艾莉萨·星风肩负着保卫奥伯丁的重任，她怀疑北方的古代遗迹中隐藏着邪恶的勾当。她委托冒险者去寻找巴苏尔·影击，一名被派去监视神秘的奥萨拉克斯之塔，却未按时汇报情况的侦察兵。",kw={"奥萨拉克斯","奥伯丁","巴苏尔·影击","黑海岸","艾莉萨·星风","侦察兵","哨兵","塔"},ang={["faction:Alliance"]="奥伯丁是联盟进入卡利姆多北部的门户，因此保卫其周边道路和边界对所有来访的盟友来说都至关重要。",["race:NightElf"]="奥萨拉克斯的遗迹是古代卡利姆多陨落的上层精灵历史的见证，而保护奥伯丁免受那些腐朽石块中的腐蚀影响，是暗夜精灵哨兵的一项重要职责。"},sec={{t="失踪的侦察兵",b="奥伯丁的哨兵必须时刻警惕黑海岸潜伏的危险。哨兵艾莉萨·星风注意到森林北部的奥萨拉克斯之塔周围有可疑的活动。她派遣了巴苏尔·影击去调查这座古代遗迹。几天过去了，侦察兵却杳无音信，这促使艾莉萨寻找一位愿意前往北方、定位巴苏尔并确保他没有遭遇不幸的旅行者。"},{t="注视遗迹",b="从奥伯丁向北的道路穿过古老的卡多雷遗迹，跨过壁泉河，然后到达阴影笼罩的塔楼区域。虽然与奥伯丁失去了联络，巴苏尔在最初的监视行动中幸存了下来。当你在周围的树林中找到他时，他证实了艾莉萨的直觉是正确的：在坍塌的石塔内，黑暗而令人不安的事件正在进行中。"}},faq={{q="哨兵艾莉萨·星风是谁？",a="艾莉萨·星风是一名驻扎在奥伯丁的暗夜精灵哨兵。她负责保护该定居点免受整个黑海岸外部威胁的影响，并监控区域内的危险，例如奥萨拉克斯之塔。",al={"艾莉萨·星风","谁给予任务","奥伯丁任务发布者"}},{q="巴苏尔·影击是谁？",a="巴苏尔·影击是哨兵艾莉萨·星风派遣的一名侦察兵，负责刺探奥萨拉克斯之塔周围的神秘活动。他守候在遗迹外，以监视敌对势力的动向。",al={"巴苏尔","谁是侦察兵","影击"}},{q="奥萨拉克斯之塔在哪里？",a="这座塔坐落在黑海岸的东北部。旅行者可以从奥伯丁向东出发，沿着北面的道路经过巴莎兰，跨过壁泉河上的桥，直到看到那座尖塔。",al={"奥萨拉克斯之塔位置","塔在哪里","如何找到奥萨拉克斯"}},{q="为什么要派侦察兵去塔那里？",a="艾莉萨在履行保护奥伯丁职责的同时，派遣巴苏尔去观察奥萨拉克斯之塔周围发生的怪事。",al={"为什么要监视塔","奥萨拉克斯出了什么问题","为什么要派巴苏尔"}},{q="为什么巴苏尔没有回到奥伯丁？",a="艾莉萨没有收到巴苏尔的报告，因此请求你去查看他的情况。当你找到他时，巴苏尔会向你解释他的处境。",al={"为什么巴苏尔失踪","巴苏尔被困了吗","为什么巴苏尔留下了"}},{q="这个任务链有后续吗？",a="有的。找到巴苏尔·影击将开启一系列调查任务，探究占据奥萨拉克斯之塔的黑暗势力及其在黑海岸的险恶野心。",al={"这是任务链吗","下一个任务是什么","奥萨拉克斯任务链"}}},fx={["895f5562"]={q="哨兵艾莉萨·星风为什么想让你这么做？",a="作为负责守卫奥伯丁的哨兵，艾莉萨·星风肩负着保护黑海岸免受威胁的职责。她派巴苏尔·影击去调查奥萨拉克斯之塔附近的可疑情况，但他迟迟没有回来。她担心他遭遇了意外，因此需要有人找到他并确认他的安危。",al={"为什么要找巴苏尔","艾莉萨·星风的动机","为什么派我去奥萨拉克斯之塔"}}},fp="22,285,23.441.0,18.424.1,34.211.0,29.214.0,40.228.0,53.132.0,42.125.0,31.166.0"}
P.entries["quest:966"] = {n="奥萨拉克斯之塔",s="侦察兵巴苏尔·影击在黑海岸北部奥萨拉克斯之塔周边调查可疑活动时，寻求帮助以从聚集的术士那里搜集情报。通过从废墟外的狂热者身上找回丢弃的羊皮纸残片，他试图揭开这些邪教徒的身份及其阴险目的。",h="侦察兵巴苏尔·影击在黑海岸北部奥萨拉克斯之塔周边调查可疑活动时，寻求帮助以从聚集的术士那里搜集情报。通过从废墟外的狂热者身上找回丢弃的羊皮纸残片，他试图揭开这些邪教徒的身份及其阴险目的。",kw={"奥萨拉克斯之塔","奥伯丁","巴苏尔","黑岸","黑海岸","德尔格伦","狂热者","羊皮纸","净化者","影击","术士"},ang={["class:Paladin"]="在黑海岸北部发现一个有组织的黑暗邪教，直接助力了净化者德尔格伦的远征，他是一位致力于清除邪能和恶魔腐化的盟友。",["class:Warlock"]="黑岸邪教证明了不受约束的结社将占据古老的废墟，在远离联盟和部落当局窥探的地方进行召唤仪式。",["race:NightElf"]="奥萨拉克斯之塔被黑暗邪教徒亵渎，代表了古老精灵遗产在卡利姆多海岸上遭遇的又一次玷污。"},sec={{t="浅滩之眼",b="巴苏尔·影击站在黑海岸北部雾气缭绕的海岸线上，警惕地注视着被称为奥萨拉克斯之塔的古老废墟。他被派往此地为奥伯丁监视现场，并向净化者德尔格伦报告任何迫在眉睫的危险。巴苏尔不愿离开岗位去报告，因为他担心自己会错过那些占据废墟的黑暗施法者们的关键动向，因此他转而依靠过往的旅人来侦察周边营地。"},{t="破解邪教",b="出没在废墟中的低阶追随者身上携带着破碎的卷轴和笔记。通过拼凑从这些外围邪教徒身上找回的几张破旧的羊皮纸，巴苏尔发现了一个令人不安的名字：黑岸邪教。侦察兵对这个阴暗的教派一无所知，他意识到这些威胁比一伙流氓术士要组织严密得多，必须立即向德尔格伦发出警告。"}},faq={{q="巴苏尔·影击是谁？",a="巴苏尔·影击是一名联盟侦察兵，驻扎在黑海岸北部奥萨拉克斯之塔附近的道路上。他受奥伯丁的领导层和圣骑士净化者德尔格伦之托，被派往监视塔内可疑的集会。",al={"巴苏尔·影击传说","巴苏尔是谁","巴苏尔黑海岸"}},{q="奥萨拉克斯之塔是什么？",a="奥萨拉克斯之塔是位于黑海岸北部的一座古老精灵废墟。最近，阴险的术士及其邪教徒爪牙占据了周边的场地和塔楼内部，在远离奥伯丁守望的地方进行黑暗仪式。",al={"奥萨拉克斯之塔","奥萨拉克斯之塔是什么","黑海岸废弃之塔"}},{q="塔楼周边的邪教徒是谁？",a="他们属于黑岸邪教，这是一个由术士和狂热者组成的秘密组织，聚集在这座古老的精灵废墟中进行黑暗召唤仪式。",al={"术士是谁","黑岸邪教","黑岸狂热者"}},{q="为什么巴苏尔告诫不要进入塔内？",a="巴苏尔指出，居住在塔楼上层的术士比在废墟外扎营的狂热者要强大且危险得多。他建议在尝试强攻据点之前，先从外围搜集情报。",al={"我可以进入塔内吗","塔中术士危险吗","塔内部"}},{q="破旧的羊皮纸揭示了什么？",a="邪教狂热者随身携带的零散碎片提供了该组织名字——黑岸邪教——的第一个明确证据，向巴苏尔揭示了占领者是一个有组织的教派，其存在对该地区构成了直接威胁。",al={"羊皮纸上写了什么","破旧的羊皮纸传说","邪教笔记"}},{q="净化者德尔格伦是谁？",a="净化者德尔格伦是一位驻扎在灰谷迈斯特拉岗哨的联盟圣骑士，致力于净化恶魔和腐化势力。他怀疑奥萨拉克斯之塔正在滋生邪恶活动，并依赖像巴苏尔这样的侦察兵提供情报。",al={"德尔格伦","德尔格伦是谁","净化者德尔格伦"}}},fx={bc625320={q="巴苏尔·影击为什么想让你这么做？",a="巴苏尔·影击担心黑暗势力正在黑海岸边境秘密集结。德尔格伦怀疑术士聚集在古代遗迹中，但他们都不知道这些人是谁，也不知道他们打算施行什么邪恶仪式。巴苏尔需要取得足够的书面证据，弄清他们的身份和动机，然后才能采取果断行动保护这片地区。",al={"巴苏尔为什么要那些文书","巴苏尔的动机","为什么调查奥萨拉克斯之塔"}},["151da73d"]={q="巴苏尔·影击为什么派你去，而不是亲自前往？",a="巴苏尔驻守在遗迹外的一处偏僻哨点，执行侦察任务。他不能离开岗位去搜查周围的邪教徒营地，也不能回奥伯丁汇报，因为他担心任何缺岗都可能让他错过敌人的关键动向。让你去对付外围的邪教徒并取回他们的文书，他就能继续监视高塔。",al={"巴苏尔为什么需要帮手","为什么不是巴苏尔去","巴苏尔为什么找你"}}},fp="22,337,20.454.0,20.404.1,29.253.0,31.250.0,43.171.0,50.247.0,35.255.0,28.265.0"}
P.entries["quest:96604"] = {n="The Great Outdoors",s="The Great Outdoors是一项由Brakk向有抱负的冒险者提供的入门级荒野生存任务。通过学习在简易营火旁休息，旅行者们能在追求实用专业技能之前，掌握在野外维持生存的基础知识。",h="The Great Outdoors是一项由Brakk向有抱负的冒险者提供的入门级荒野生存任务。通过学习在简易营火旁休息，旅行者们能在追求实用专业技能之前，掌握在野外维持生存的基础知识。",kw={"强效休息","brakk","营地设施","营火","the great outdoors","专业技能","荒野生存"},ang={["faction:Horde"]="伴随着传统的兽人问候语“Lok-tar”，这门生存课程为初出茅庐的部落冒险者在踏入危险区域前提供了基础的指导。"},sec={{t="荒野课程",b="冒险进入艾泽拉斯未受驯服的疆域，需要的不仅仅是武力，还需要能够忍受恶劣环境的基础知识。Brakk用一声豪迈的“Lok-tar”欢迎有抱负的冒险者，认可那些寻求财富与荣耀之人的躁动灵魂。为了在前方漫长的道路上生存下来，每一位旅行者都必须首先掌握安营扎寨并在荒野中恢复体力的艺术。"},{t="从炉火到技艺",b="在Brakk的简易营火旁坐下，可以传授恢复体力的精髓，让人在露天环境下获得恢复性休息。一旦理解了这些生存基础，初出茅庐的冒险者就会被指引前往当地村庄的工匠处。在那里，他们可以学习专业技能，并探索如何建造适合其所选技艺的功能性营地设施。"}},faq={{q="什么是The Great Outdoors？",a="The Great Outdoors是一项由Brakk提供的入门级生存任务，旨在教导新冒险者在学习专业技能之前，通过在营火旁休息来学会在荒野中茁壮成长。",al={"什么是the great outdoors","the great outdoors任务"}},{q="Brakk是谁？",a="Brakk是一位经验丰富的户外生存专家，他欢迎躁动的旅行者，提供关于荒野生存和在营火旁休息的实用课程。",al={"brakk是谁","任务发布者"}},{q="什么是“强效休息”增益效果？",a="在Brakk的简易营火旁休息可以获得“强效休息”增益效果，这展示了在野外，通过寻找遮蔽处并在明火旁恢复体力是如何让冒险者重获新生的。",al={"强效休息增益","营火增益"}},{q="完成任务后你应该做什么？",a="在学完荒野休息的基础知识后，Brakk会建议冒险者去拜访附近村庄的训练师，学习一项专业技能，并了解如何构建适合其技艺的营地设施。",al={"任务后的下一步","营火之后要做什么"}},{q="什么是营地设施？",a="营地设施是由附近村庄的专业训练师教授的专门营地装置，使旅行者能够改造他们的营地，以支持他们所选择的专业技能。",al={"营地设施","什么是营地设施"}},{q="这项训练是为谁准备的？",a="任何在荒野中寻求财富和荣耀的躁动灵魂都能从这门课程中受益，特别是那些刚刚踏上旅程并准备选择职业的人。",al={"谁应该做这个任务","这是部落任务吗"}}},fp="18,262,19.401.0,20.356.0,27.194.0,13.153.0,30.169.0,46.198.0,23.179.0,34.163.0"}
P.entries["quest:96605"] = {n="The Great Outdoors",s="“The Great Outdoors”是一个引导任务，旨在教导胸怀大志的冒险者掌握荒野生存的基本技能。在旅行者Kaga的指引下，新人将学会如何在简易营火旁恢复体力，并进而学习专业技能和制作特制的营地设施。",h="“The Great Outdoors”是一个引导任务，旨在教导胸怀大志的冒险者掌握荒野生存的基本技能。在旅行者Kaga的指引下，新人将学会如何在简易营火旁恢复体力，并进而学习专业技能和制作特制的营地设施。",kw={"boosted rest","营地设施","营火","kaga","生存","the great outdoors","专业技能","荒野"},ang={["profession:Cooking"]="营火和荒野生存构成了野外烹饪的基础，使得营地制作成为在露天环境下准备餐点的自然补充。"},sec={{t="荒野课程",b="每一个踏出文明安全区冒险者很快就会发现，光靠勇气是不足以在边境地带生存下去的。“The Great Outdoors”向新人们介绍了荒野适应能力的至关重要性。通过经验丰富的旅行者Kaga的教导，这一简短的课程提醒那些初出茅庐的英雄们：在未知的领土中兴旺发展，始于学会如何建立营地并忍受露天环境的考验。"},{t="炉火与工艺",b="一堆简单的营火往往就是探险者与荒野疲劳之间的唯一屏障。坐在Kaga的炉火旁并获得“Boosted Rest”增益效果，冒险者们就能体会到营地生活的恢复力量。一旦理解了荒野休息的基本原理，Kaga就会督促旅行者们拜访附近的定居点工匠，学习专业技能并掌握专业营地设施的制作方法。"}},faq={{q="什么是“The Great Outdoors”？",a="“The Great Outdoors”是由Kaga提供的一项荒野生存入门任务。它向初出茅庐的冒险者介绍了荒野生存、在营火旁休息以及为专业技能做准备的基本知识。",al={"什么是“the great outdoors”","“the great outdoors”任务"}},{q="谁提供这个任务？",a="Kaga是一位经验丰富的旅行者和户外导师，他指导有抱负的冒险者掌握荒野生存的基础知识。他维护着一处基础营火，新人可以在那里学习如何休息和恢复。",al={"谁是kaga","kaga任务发布者"}},{q="什么是“Boosted Rest”增益？",a="“Boosted Rest”是通过安静地坐在Kaga的基础营火旁所获得的有益放松状态。它代表了在荒野营地适当休息所带来的恢复效果。",al={"boosted rest","什么是“boosted rest”增益"}},{q="什么是营地设施？",a="在掌握了基本的荒野休息方法后，附近定居点的专业训练师可以教导冒险者如何根据他们选择的职业建造特制的营地设施。",al={"营地设施背景知识","专业营地设施"}},{q="为什么Kaga让你坐在营火旁？",a="在文明城镇外生存需要学会如何扎营并恢复体力。坐在营火旁可以让冒险者在危险的旅途中获得温暖、专注和休息恢复。",al={"为什么要在营火旁休息","营火休息"}},{q="完成这节课后你应该做什么？",a="在学会如何正确地在荒野中休息后，Kaga建议去寻找附近村庄的专业训练师，学习一门手艺并获取特定职业营地设施的配方。",al={"完成“the great outdoors”后做什么","kaga任务之后"}}},fp="18,289,19.425.0,24.429.0,27.225.0,22.193.0,30.193.0,23.181.0,43.199.0,48.186.0"}
P.entries["quest:96606"] = {n="The Great Outdoors",s="“The Great Outdoors”是一门由名为莱瑞娜（Lyreena）的资深斥候为猎人提供的入门级野外生存课程。该课程强调在营火旁休息以恢复体力，并在穿越荒野时获得“强化休息”增益的重要性。",h="“The Great Outdoors”是一门由名为莱瑞娜（Lyreena）的资深斥候为猎人提供的入门级野外生存课程。该课程强调在营火旁休息以恢复体力，并在穿越荒野时获得“强化休息”增益的重要性。",kw={"冒险者","强化休息","营火","猎人","莱瑞娜","生存","the great outdoors","荒野"},ang={["class:Hunter"]="这门课程直接面向猎人，强化了在荒野中追踪时野外生存和露营技巧的必要性。"},sec={{t="荒野课程",b="冒险深入文明之外的边境，需要的不仅仅是敏锐的准星和灵敏的感知，更需要对原始荒野元素的敬畏。一位经验丰富的斥候莱瑞娜为流浪的猎人们提供指导，欢迎他们停下脚步，在她的营火旁寻求慰藉。在艾泽拉斯危险的荒野中，学会如何建立炉火并在狩猎间隙恢复体力，与学会如何追踪猎物同样至关重要。"},{t="营火休憩",b="熊熊燃烧的营火能让人在寒冷的夜晚感到舒适，提供片刻的宁静，让疲惫的旅人驱散困倦。靠近火焰坐下，冒险者便能获得“强化休息”效果，这能让他们恢复精力，为严酷的探索做好准备。花时间坐在余烬旁会让年轻的冒险者明白，耐心和休息是野外生存不可或缺的支柱。"}},faq={{q="莱瑞娜是谁？",a="莱瑞娜是一位经验丰富的野外导师，她教导有抱负的冒险者和猎人如何在荒野中正确休息和生存。她会在营火旁提供实用的建议。",al={"莱瑞娜是谁","莱瑞娜 营火","任务发布者"}},{q="什么是“The Great Outdoors”？",a="“The Great Outdoors”是一项野外生存入门任务，一位名叫莱瑞娜的资深户外专家会邀请猎人坐在她的营火旁，学习如何在长途远征中维持体力。",al={"什么是the great outdoors","这是什么任务","the great outdoors任务"}},{q="什么是“强化休息”？",a="在简易营火旁坐下，可以让疲惫的流浪者从旅途的劳顿中恢复，并获得“强化休息”效果，为接下来的旅程重振精神。",al={"强化休息增益","强化休息 营火","如何获得强化休息"}},{q="为什么要坐在营火旁休息？",a="营火在严酷的荒野中提供至关重要的温暖和休憩。在营火旁休息可以让冒险者喘口气，清醒头脑，并为穿越荒野之地的危险跋涉做好准备。",al={"营火的用途","为什么要在火边坐下","在营火旁休息"}},{q="为什么户外生存对猎人至关重要？",a="猎人的大部分时间都在与世隔绝的地区穿行，附近既没有旅店也没有安全的城镇。掌握基本的露营技巧能确保猎人在严苛的环境中生存，而不至于被疲惫击垮。",al={"猎人生存技能","户外生存","为什么是猎人任务"}},{q="完成这项任务需要做什么？",a="要完成这项任务，你只需要在莱瑞娜的简易营火旁坐下，等待片刻，直到营火的温暖为你赋予“强化休息”增益即可。",al={"任务目标","如何完成the great outdoors","the great outdoors目标"}}},fp="18,266,19.439.0,16.406.0,15.191.0,27.207.0,21.189.0,38.200.0,44.214.0,38.164.0"}
P.entries["quest:96607"] = {n="The Great Outdoors",s="The Great Outdoors 是一项入门级的生存课程，由经验丰富的旅行者为艾泽拉斯各地初出茅庐的流浪者们提供。通过在温暖的篝火旁小憩片刻，新手们可以了解到保持充分休息和做好准备对于冒险者在城墙之外生存的重要性。这标志着掌握野外生存和专业野外营地技巧的第一步。",h="The Great Outdoors...",kw={"冒险者","boosted rest","篝火","露营","eleanor shackleton","艾尔文森林","sam sarsaparilla","生存","专业技能"},ang={["faction:Alliance"]="在安全的艾尔文森林中，人类旅行者在面对西部荒野和赤脊山潜藏的严酷威胁之前，会先从经验丰富的旅者那里学习这些生存基础知识。",["faction:Horde"]="无论是穿越杜隆塔尔干旱的平原，还是莫高雷风吹过的平顶山，部落的生存专家们都会向每一位年轻的战士灌输火种工艺和野外纪律。",["profession:Cooking"]="每一个野外营地都始于火焰，这使得烹饪成为野外生存的天然伴侣。在这堂课程之后，露营大师会立即引导你进行路边烹饪教学。"},sec={{t="小径之课",b="无论你的刀刃多么锋利，魔法多么强大，如果你忽视了生存的基本知识，艾泽拉斯的荒野很快就会磨损你的锐气。驻扎在路边空地附近的资深流浪者们，会为那些从家乡谷地出发的旅行者提供这堂简单的课程。花点时间在篝火旁休息，不仅能缓解双脚的酸痛，更能平复心境，为前方艰险的旅途做好准备。只有那些掌握了定期休息和准备这一准则的人，才有机会生存得足够久，从而获得财富与荣耀。"},{t="他乡之居",b="一旦冒险者明白了跳动的火焰和适当休息的价值，导师们就会指引他们直接前往城镇的技艺工匠处。野外营地很少仅凭火星和睡袋就能搭建完成；生存需要实际的技能。无论是锻造修补用的铆钉、烹饪行军口粮，还是在星空下缝补破损的装备，每一项专业技能都提供了独特的营地设施，能将荒芜的山坡变为自给自足的前哨站。"}},faq={{q="谁会向新晋的流浪者提供这堂课程？",a="根据你所在的位置，会有各种各样的老练旅行者提供指导。在艾尔文森林，经验丰富的流浪者 Sam Sarsaparilla 会挺身而出，而在其他地方，像 Eric Brighthammer、Lyreena Duskblade、Brakk、Eleanor Shackleton、Kaga Wildhoof 和 Raan Wildwind 这样的人物也会分享他们的野外生存经验。",al={"谁给予the great outdoors","谁开启the great outdoors","任务给予者the great outdoors"}},{q="在篝火旁休息的目的是什么？",a="安静地坐在熊熊燃烧的篝火旁，可以让冒险者喘口气并获得“Boosted Rest”效果。在野外刻意安排休整时间，对于在穿越荒野的长途跋涉中保持体力至关重要。",al={"为什么要坐在火堆旁","篝火的作用是什么","boosted rest增益效果"}},{q="这项训练接下来会导向什么内容？",a="一旦你在火堆旁休息完毕，你的导师会引导你前往附近的定居点学习实用的专业技能。从那里开始，你将学习 Camping 101: Cooking 以及针对你选择追求的任何专业而定制的特定野外露营课程。",al={"the great outdoors之后是什么","the great outdoors后续任务","露营任务"}},{q="部落的冒险者也能参加这堂课程吗？",a="是的。无论效忠于哪一方，在严酷的荒野中生存都是一项必备技能。来自联盟和部落的资深导师——例如 Brakk、Eleanor Shackleton 和 Kaga Wildhoof——都会向各自阵营的新手教授完全相同的基本营地技巧。",al={"这是联盟专属吗","部落的the great outdoors","兽人可以做这个任务吗"}},{q="为什么导师们让你去和专业训练师交谈？",a="生存不仅仅意味着坐在火焰旁；冒险者需要具备自力更生的能力。专业技能训练师会教你如何制作专门的营地设施，让你能够运用你的技艺，无论是在户外烹饪行军口粮、修理护甲，还是酿制药物。",al={"为什么要学习专业技能","营地设施与专业训练师","专业技能与营地的联系"}},{q="在接受这个任务之前需要什么样的先前经验？",a="冒险者通常是在完成“The Adventurer”之后紧接着接到这堂课程，此时他们已经证明了自己的基本志向，并已走出新手封地进入了更广阔的区域。",al={"the great outdoors的前提条件","如何解锁the great outdoors","the great outdoors之前"}}},fp="18,359,20.539.0,21.445.0,40.310.0,47.231.0,35.262.0,52.261.0,61.278.0,59.186.0"}
P.entries["quest:96608"] = {n="The Great Outdoors",s="The Great Outdoors向流浪的冒险者们介绍了荒野生存和露营技巧的基础知识。在Eric的营火旁坐下后，旅行者们可以学习如何在野外适当地休整，并在此后学习通过专业技能来支持自己的旅程。",h="The Great Outdoors向流浪的冒险者们介绍了荒野生存和露营技巧的基础知识。在Eric的营火旁坐下后，旅行者们可以学习如何在野外适当地休整，并在此后学习通过专业技能来支持自己的旅程。",kw={"强效休息","营地装置","营火","eric","生存","the great outdoors","专业技能","荒野"},ang={["class:Priest"]="虽然牧师们通常在神圣的圣所和教堂中寻找他们的使命，但道路上的生活除了祈祷和祝福之外，还需要实用的生存技能。"},sec={{t="荒野课程",b="踏入广阔的世界需要的不仅仅是雄心壮志和武器或圣契。对于初出茅庐的旅行者来说，生存取决于如何学会在荒野中适当地休息。在简易的营火旁，经验丰富的旅行者Eric欢迎流浪的冒险者们坐下，在余烬中取暖，并了解在进入未开发的荒野之前进行适当休息的重要性。"},{t="从营火到制造",b="在漫长的旅途中，简单的营火只是维持有效营地生活的第一步。在掌握了荒野恢复的基础知识后，旅行者们被鼓励去邻近定居点的专业技能训练师那里访问。在那里，工匠和制作者会教导他们如何组装专门的营地装置，使冒险者们无论走到哪里，都能在营地中练习他们的专业技能并为探险提供支持。"}},faq={{q="Eric是谁？",a="Eric是一位经验丰富的户外生存专家和冒险同伴，他主动向初出茅庐的旅行者传授在荒野中生存的基本要领。他欢迎旅行者们在营火旁休息，并分享远离城市围墙后如何生存的实用建议。",al={"谁提供这个任务","eric是谁","谁教授户外知识"}},{q="什么是强效休息增益？",a="在Eric的营火旁休息可以提供强效休息效果，帮助疲惫的旅行者恢复精力，为接下来的挑战做好精神准备。这代表了在野外环境中抽出时间进行适当地休整。",al={"什么是强效休息","营火有什么帮助","营地休息增益"}},{q="什么是营地装置？",a="营地装置是针对特定专业技能的实用结构或工具，冒险者们可以在野外设置这些装置。正如附近定居点的专业技能训练师所解释的那样，学习一项专业技能可以让工匠们在营地中建立工作台。",al={"什么是营地装置","专业装置","专业技能营地物品"}},{q="为什么要坐在Eric的营火旁？",a="在营火旁坐下可以让冒险者们停下来，取暖，并聆听Eric关于荒野生存的指导。这给了身体放松的时间，并能获得在户外舒适庇护所中充分休息的好处。",al={"为什么要坐在火旁","在营火旁坐下","营火目标"}},{q="完成这门课程后，冒险者应该去哪里？",a="在掌握了营地休息的基础知识后，Eric建议前往附近的村庄，在当地的专业训练师那里学习一项专业技能。一旦受训，你就可以开始学习如何构建适合你专业的营地装置了。",al={"之后做什么","接下来去哪里","the great outdoors之后"}},{q="这门生存课程是为谁准备的？",a="Eric呼唤着过往的冒险者，注意到了他们那不安分的灵魂以及在世界各地寻求财富与荣耀的决心。他的荒野指导可以帮助任何离开安全区并冒险进入广阔荒野的人。",al={"谁可以完成这个任务","仅限牧师","这是给冒险者准备的吗"}}},fp="18,255,19.391.0,22.411.0,12.250.0,30.227.0,23.266.0,44.212.0,59.230.0,41.227.0"}
P.entries["quest:96626"] = {n="Camping 101: Cooking",s="Camping 101: Cooking告诉初出茅庐的冒险者，烹饪是在野外建立营地的基石。通过向闪金镇的Cook Tomas学习这项技艺，旅行者们可以获得建造营火和搭建野外营地的能力。",h="Camping 101: Cooking告诉初出茅庐的冒险者，烹饪是在野外建立营地的基石。通过向闪金镇的Cook Tomas学习这项技艺，旅行者们可以获得建造营火和搭建野外营地的能力。",kw={"营火","露营","camping 101: cooking","营地","烹饪","陈设","闪金镇","tomas"},ang={["faction:Alliance"]="艾尔文森林的新手联盟冒险者被指引前往闪金镇的Lion's Pride Inn寻找Cook Tomas，以掌握烹饪基础和营火制作。",["profession:Cooking"]="烹饪训练是野外生存的重要基石，赋予了冒险者建造能够固定营地的基础营火的技能。"},sec={{t="野外的炉火",b="对于任何在艾泽拉斯荒野中冒险的勇士来说，建立营地首先需要一团可靠的火焰。任务Camping 101: Cooking告诉新手旅行者，烹饪训练不仅仅是为了准备热食；它是野外生存的重要基础。通过掌握烹饪专业，旅行者可以学会如何点燃合适的营火，将未开发的空地变成安全的避难所。"},{t="闪金镇的指导",b="在艾尔文森林的新旅行者会被派往闪金镇与Cook Tomas交谈，以学习这项技艺的基础知识。在接受他的指导后，冒险者将获得建立基础野外营地的能力。虽然最初的营地比较简陋，陈设也有限，但提升烹饪熟练度可以解锁更大的营火，而其他制造专业则提供了布置和定制营地的更多选择。"}},faq={{q="什么是任务Camping 101: Cooking？",a="Camping 101: Cooking向冒险者介绍了在野外生存的基础知识。它引导你学习烹饪专业，教你如何点燃基本的营火，作为你在野外营地的核心。",al={"什么是camping 101: cooking","camping 101教授什么","camping 101的目的"}},{q="Tomas是谁，在哪里可以找到他？",a="Tomas是位于艾尔文森林闪金镇的驻地烹饪训练师。他以Lion's Pride Inn为基地，指导有抱负的冒险者学习基础烹饪和点燃营火的艺术。",al={"tomas是谁","tomas在哪里","闪金镇的tomas"}},{q="为什么建立营地需要烹饪？",a="营火是任何野外营地的基础。学习烹饪提供了建造营火所需的基本知识，冒险者可以围绕营火休息并布置他们的营地陈设。",al={"为什么露营需要烹饪","露营需要烹饪吗","烹饪与营火的关系"}},{q="随着技能的提高，可以制作更大的营火吗？",a="提升你的烹饪专精可以让你建造更大、更坚固的火堆。随着烹饪技能的发展，你的营火将成为野外探索更坚实的基地。",al={"如何升级营火","可以建造更大的营火吗","更大的烹饪营火"}},{q="如何获取营地陈设？",a="除了烹饪之外，额外的营地陈设可以向世界各地的其他专业技能训练师学习。精通各种制造专业的冒险者可以制作物品来装饰和增强他们的野外营地。",al={"如何增加营地陈设","营地陈设从哪里来","制作营地物品"}},{q="冒险者可以在哪里建立营地？",a="一旦你掌握了烹饪和营火制作的基础知识，你就能获得在开阔荒野中搭建营地的能力。然而，在提升技能之前，最初的营地规模较小，且仅能容纳极少量的陈设。",al={"可以在任何地方露营吗","野外露营规则","营地放置限制"}}},fp="20,267,22.409.0,24.423.0,39.254.0,39.203.0,48.210.0,53.190.0,49.228.0,36.245.0"}
P.entries["quest:96627"] = {n="The Adventurer",s="The Adventurer是治安官玛克布莱德在北郡山谷发布的一项引导任务。玛克布莱德认可了你初期的能力，并指示你离开封闭的北郡修道院前往闪金镇，去调查一位名叫Sam Sarsaparilla的新来者。",h="The Adventurer是治安官玛克布莱德在北郡山谷发布的一项引导任务。玛克布莱德认可了你初期的能力，并指示你离开封闭的北郡修道院前往闪金镇，去调查一位名叫Sam Sarsaparilla的新来者。",kw={"艾尔文森林","闪金镇","治安官玛克布莱德","北郡","sam sarsaparilla","the adventurer"},ang={["faction:Alliance"]="对于刚在北郡完成服役的联盟新兵来说，这标志着他们第一次正式踏入更广阔的艾尔文森林。",["race:Human"]="走出北郡修道院的人类保卫者迈出了通往闪金镇的第一步，那里是艾尔文的繁华中心。"},sec={{t="离开山谷",b="一旦新兵清除了北郡山谷中诸如迪菲亚兄弟会成员和害虫之类的直接威胁，治安官玛克布莱德就会开始关注道路上的情况。由于暴风城的正规军在王国各地兵力吃紧，当地驻军必须依靠有前途的战士来监视在周边森林中游荡的旅人和流浪者。"},{t="一位好奇的新来者",b="这并非一项军事命令或悬赏任务，玛克布莱德指派给你一件不寻常的差事：去查看一下闪金镇附近出现的一位名叫Sam Sarsaparilla的冒险者。这项请求标志着你从与世隔绝的北郡山谷走向更广阔、更危险的艾尔文森林。"}},faq={{q="谁派我执行这项任务？",a="驻扎在北郡山谷的暴风城守军指挥官治安官玛克布莱德，会在你证明了自己保卫修道院的能力后提供这项任务。",al={"任务发布者","谁发布了the adventurer","治安官玛克布莱德任务"}},{q="Sam Sarsaparilla是谁？",a="Sam Sarsaparilla是一位徘徊在闪金镇附近道路上的冒险者。治安官玛克布莱德听闻了他的行踪，并要求你去调查他的意图。",al={"sam sarsaparilla","sam是谁","闪金镇冒险者"}},{q="我在哪里可以找到Sam Sarsaparilla？",a="他在从北郡通往艾尔文森林闪金镇的主路上。",al={"sam sarsaparilla位置","sam在哪里","寻找sam sarsaparilla"}},{q="为什么治安官玛克布莱德会关心一个普通的冒险者？",a="北郡始终对强盗和入侵者保持高度戒备。玛克布莱德更倾向于密切关注在这一地区出没的陌生雇佣兵和流浪者，并利用可靠的当地人才进行初步接触。",al={"为什么派我去","玛克布莱德的动机","为什么要找sam"}},{q="我需要离开北郡山谷才能完成这项任务吗？",a="是的。这项任务指引你穿过北郡山谷的南门，来到通往闪金镇的森林道路上。",al={"北郡之外","这需要离开北郡吗","前往闪金镇"}},{q="这是暴风城正常军事指挥链的一部分吗？",a="虽然这是由暴风城的一名军官发布的，但玛克布莱德明确表示这是一项不同寻常的任务，而非标准的守卫职责，他更看重你作为独立护卫的判断力，而非正式的军事规程。",al={"暴风城军队","这是标准职责吗","公务"}}},fx={dd262048={q="治安官玛克布莱德为什么选我去调查萨姆？",a="治安官玛克布莱德认为这是一项不同寻常的任务，并非一般的驻防职责。看到你处理了北郡的当地威胁后，他认为你有能力保护他人，也能在修道院外谨慎行事。他手下的守军忙于应付当地麻烦，人手紧张，因此派一名值得信任的新兵去调查路边的传闻，比派遣正规卫兵更合适。",al={"治安官玛克布莱德为什么选我","玛克布莱德为什么派我去","为什么不派卫兵去找萨姆"}}},fp="14,244,18.338.0,18.303.0,26.159.0,24.165.0,33.105.0,56.225.0,52.129.0,63.210.0"}
P.entries["quest:96628"] = {n="The Adventurer",s="The Adventurer 是一项由驻守在丹莫罗南门的巡山人萨鲁斯派发的本地任务。在指引旅行者穿过山间隧道前往卡拉诺斯之前，萨鲁斯会要求他们将一捆补给包带给埃里克·亮锤，一位刚在村庄外扎营的新人。",h="The Adventurer 是一项由驻守在丹莫罗南门的巡山人萨鲁斯派发的本地任务。在指引旅行者穿过山间隧道前往卡拉诺斯之前，萨鲁斯会要求他们将一捆补给包带给埃里克·亮锤，一位刚在村庄外扎营的新人。",kw={"寒脊山小径","丹莫罗","埃里克·亮锤","卡拉诺斯","巡山人萨鲁斯","补给包","the adventurer"},ang={["faction:Alliance"]="巡山人依靠联盟新兵在冰雪覆盖的道路上运送关键补给品，以确保在卡拉诺斯外围游历的盟友能够获得足够的物资。",["race:Dwarf"]="对于离开寒脊山谷的年轻矮人来说，将物资带给埃里克·亮锤标志着他们与巡山人在广阔的丹莫罗大地上进行的首次合作。"},sec={{t="帮巡山人的忙",b="守卫寒脊山谷与广阔的丹莫罗雪原之间的高地关隘和隧道，对于铁炉堡巡山人来说是一项艰巨的工作。巡山人萨鲁斯驻扎在边境大门，时刻警惕着当地的危险和沿小径经过的旅行者。当哨所收到关于一名独自的冒险者抵达卡拉诺斯附近的消息时，萨鲁斯便会委托值得信赖的过路人将必要的补给品运送过去，以支援那些深入冰封峭壁的新人。"},{t="送往卡拉诺斯的补给品",b="从南部关隘蜿蜒而下的道路通往卡拉诺斯定居点，这里是丹莫罗中部矮人手工艺和旅行的主要枢纽。埃里克·亮锤最近在村庄外围扎下了营地。通过将巡山人的补给包送到他手中，旅行者们协助在偏远的哨兵与活跃在荒野中的人们之间建立起了一条重要的纽带。"}},faq={{q="谁发布了 The Adventurer 这个任务？",a="巡山人萨鲁斯发布了这个任务。他驻守在连接寒脊山谷小径与广阔丹莫罗的山隘大门处。",al={"任务发布者","谁发布 the adventurer","萨鲁斯任务"}},{q="埃里克·亮锤是谁？",a="埃里克·亮锤是一位最近抵达矮人城镇卡拉诺斯外围的冒险者。巡山人萨鲁斯派遣旅行者给他带去了一份必要的补给包。",al={"埃里克·亮锤在哪里","谁是 the adventurer","亮锤"}},{q="这次运送的地点在哪里？",a="运送地点位于丹莫罗的卡拉诺斯外围，在巡山人萨鲁斯驻守的寒脊山小径隧道的北面。",al={"在哪里交付补给品","埃里克·亮锤的位置","补给包掉落"}},{q="巡山人萨鲁斯为什么要运送补给品？",a="巡山人时刻关注着丹莫罗各地的旅行者。当萨鲁斯得知一名冒险者在卡拉诺斯附近扎营后，他便安排人手运送物资，以支持他在严寒中的生活。",al={"为什么要运送补给品","萨鲁斯的目的","补给包的原因"}},{q="你携带的是什么物品？",a="你携带的是由巡山人萨鲁斯直接提供的补给包，你需要将其交给埃里克·亮锤。",al={"什么补给品","补给包物品"}},{q="部落玩家可以接取这个任务吗？",a="不可以。巡山人萨鲁斯是丹莫罗的一名联盟阵营矮人卫兵，因此该任务仅限联盟阵营。",al={"部落可以做这个吗","是否仅限联盟","部落的冒险者任务"}}},fx={["95095969"]={q="巡山人萨鲁斯为什么请你运送补给？",a="巡山人萨鲁斯和他的巡逻队驻扎在山口，负责监视道路并守护隧道，防范当地的危险。你正好要经过山口继续前往卡拉诺斯，他便请你顺路送去补给，不必让巡山人离开守卫岗位。",al={"the adventurer为什么选我","萨鲁斯为什么需要我","为什么派玩家去找eric brighthammer"}}},fp="14,279,28.484.0,21.418.0,36.140.0,25.178.0,36.132.0,43.199.0,27.102.0,41.118.0"}
P.entries["quest:96629"] = {n="Camping 101: Cooking",s="《Camping 101: Cooking》向丹莫罗的冒险者介绍了烹饪这项基本的生存技能。除了准备补给品，学习这项专业还能让旅行者点燃篝火，作为野外营地的基石。",h="《Camping 101: Cooking》向丹莫罗的冒险者介绍了烹饪这项基本的生存技能。除了准备补给品，学习这项专业还能让旅行者点燃篝火，作为野外营地的基石。",kw={"篝火","露营","烹饪","丹莫罗","陈设","gremlock pilsnor","卡拉诺斯","荒野"},ang={["class:Priest"]="即使是虔诚的圣光信徒，在远离神殿和定居点旅行时，也必须掌握生火等基本的生存技能。",["faction:Alliance"]="在丹莫罗附近起步的联盟冒险者会向卡拉诺斯的矮人导师学习丛林生存和烹饪的基础知识。",["profession:Cooking"]="烹饪提供了建立野外营地和放置营地陈设所必需的基础篝火。"},sec={{t="野外篝火",b="对于任何在荒野中跋涉的旅行者来说，建立可靠的营地始于火焰。在丹莫罗，新手冒险者会被指引前往卡拉诺斯，在Gremlock Pilsnor的指导下学习烹饪基础。烹饪不仅仅是为了在旅途中用热食填饱肚子；坚固的篝火是任何户外营地实质且实用的核心。"},{t="扩展营地",b="新学的篝火可以让冒险者在开阔的荒野中搭建简陋的营地。虽然简易的炉火只能支撑最基本的陈设，但提高烹饪熟练度可以解锁建造更大篝火的能力。此外，精通其他制造专业的工匠可以制作额外的陈设，将简单的休息点变成设施齐全的驻地。"}},faq={{q="《Camping 101: Cooking》任务是什么？",a="《Camping 101: Cooking》是一个教学任务，向冒险者介绍烹饪这一基本专业，将其作为野外生存和营地搭建的基石。",al={"什么是camping 101 cooking","任务目标","露营基础烹饪"}},{q="Gremlock Pilsnor是谁？",a="Gremlock Pilsnor是位于丹莫罗卡拉诺斯的当地烹饪训练师，他教导新手如何准备食物和建造篝火。",al={"谁在卡拉诺斯教授烹饪","gremlock pilsnor的位置","丹莫罗烹饪训练师"}},{q="为什么露营需要烹饪？",a="烹饪能让冒险者建造基本的篝火，这是搭建野外营地并放置营地陈设的核心基础。",al={"为什么露营需要烹饪","篝火的作用","烹饪与营地"}},{q="可以在哪里建立营地？",a="一旦你掌握了生火技巧，就可以在荒野中搭建一个基础营地，为旅途提供休息之处。",al={"在哪里可以扎营","营地规则","搭建营地"}},{q="如何改进或扩展营地？",a="提升烹饪技能可以让你建造更大的篝火，而学习其他制造专业则能让你制作并放置更多的营地陈设。",al={"如何升级营地","更大的篝火","更多营地装饰"}},{q="其他专业能对露营有帮助吗？",a="如果你精通其他专业，其他商业技能训练师可以传授为你营地制作陈设的基础知识。",al={"谁提供营地陈设","商业技能营地物品","其他营地训练师"}}},fp="20,242,22.367.0,22.396.0,39.166.0,24.141.0,37.157.0,36.136.0,40.165.0,44.140.0"}
P.entries["quest:96630"] = {n="The Adventurer",s="“The Adventurer”是一个发生在泰达希尔的简短任务，涉及在野外发现一本丢弃的日志。这本朴素的笔记本记录了一名不知名旅行者平凡的旅程和露营经历，需要将其送到多兰纳尔附近的莱琳娜·暮刃手中。",h="“The Adventurer”是一个发生在泰达希尔的简短任务，涉及在野外发现一本丢弃的日志。这本朴素的笔记本记录了一名不知名旅行者平凡的旅程和露营经历，需要将其送到多兰纳尔附近的莱琳娜·暮刃手中。",kw={"露营","多兰纳尔","日志","丢失的日志","莱琳娜·暮刃","泰达希尔","the adventurer"},ang={["faction:Alliance"]="对于那些在世界之树下刚刚起步的联盟新手来说，将遗失物品归还给同行的旅行者有助于维护树林中的秩序。",["race:NightElf"]="在泰达希尔巡逻的年轻暗夜精灵经常会发现旅行者经过的痕迹，他们会将捡到的遗失私人物品交给像莱琳娜·暮刃这样的流浪者。"},sec={{t="流浪者日志",b="在泰达希尔茂密的枝叶和盘根错节的树根间，旅行者偶尔会偶然发现遗弃的私人物品。这本简单的日志记录了一名无名冒险者平凡却真挚的流浪生活。书中大部分页面并没有记录什么宏大的英雄事迹或危险的怪物狩猎，而是热情地记载了在暮色树冠下露营的简单快乐。"},{t="送往多兰纳尔",b="发现者没有让这件私人物品在潮湿的荒野中风化，而是选择将其带往多兰纳尔。驻扎在暗夜精灵定居点附近的莱琳娜·暮刃是这些散落页面的接收者，她或许能通过这些记录了解这位逝去之人的旅程，并给予其慰藉。"}},faq={{q="任务中提到的日志是什么？",a="这是一本在泰达希尔野外发现的朴素个人笔记本。其中的条目详细记录了一个陌生人的平静生活和旅程，突显了平凡的冒险以及对户外露营的持久热爱。",al={"遗失的日志","这是什么书","冒险者日志"}},{q="莱琳娜·暮刃是谁？",a="莱琳娜·暮刃是一位出现在多兰纳尔附近的暗夜精灵。她是这本在森林中找到的遗失日志的预期接收者。",al={"莱琳娜","莱琳娜·暮刃在哪里","任务上交npc"}},{q="这个任务发生在哪里？",a="该任务发生在暗夜精灵的巨枝泰达希尔，主要集中在多兰纳尔村周围的荒野地区。",al={"冒险者任务在哪里","任务区域"}},{q="日志中是否描述了危险的怪物或战斗？",a="没有。书写的内容被描述为相当平淡，主要集中在一名不知名人士平庸的生活和流浪经历上，特别强调了露营是多么令人愉悦。",al={"日志背景故事","日志里有什么","它写了什么"}},{q="谁可以完成这项任务？",a="这项任务仅限在泰达希尔新手区游荡的联盟成员，特别是那些在多兰纳尔附近探险的暗夜精灵新手。",al={"部落可以做这个任务吗","联盟任务"}},{q="为什么要将日志上交到多兰纳尔？",a="多兰纳尔是泰达希尔该地区主要的集散地和十字路口，因此那里是归还遗失私人物品最合理的地方，而且莱琳娜·暮刃就在附近等待接收这本日志。",al={"为什么是多兰纳尔","为什么找莱琳娜"}}},fp="14,259,20.373.0,20.307.0,43.220.0,25.128.0,33.135.0,56.177.0,27.153.0,36.218.0"}
P.entries["quest:96634"] = {n="Camping 101: Cooking",s="“Camping 101: Cooking”是一项入门任务，旨在通过烹饪艺术教导冒险者野外露营的基本知识。通过向多兰纳尔的扎瑞恩等当地训练师学习如何生火，旅行者可以建立起搭建野外营地的必要基础。这是掌握户外生存技能并布置个人营地的第一步。",h="“Camping 101...",kw={"篝火","camping 101","营地","烹饪","多兰纳尔","家具","野外生存","扎瑞恩"},ang={["profession:Cooking"]="烹饪是野外生存的基础学科，提供了锚定任何户外营地所需的篝火。提升烹饪技艺可以让冒险者建造更大、更耐用的篝火。",["race:NightElf"]="途经多兰纳尔的暗夜精灵新手冒险者，在深入泰达希尔的荒野之前，通常会先向扎瑞恩学习野外生存和生火的基本知识。"},sec={{t="荒野之炉",b="每一次穿越荒野的长途跋涉，都始于能够燃起一堆温暖篝火的能力。在“Camping 101: Cooking”中，初出茅庐的冒险者会被引导去寻求烹饪训练，作为他们野外生存技巧的第一课。学习烹饪不仅仅是为了用野生猎物烹制食物；点燃基础篝火这一核心技能，是任何户外营地在物理和实践层面上的锚点。如果没有篝火来驱散寒冷和黑暗，在荒野中建立一个可靠的营地是不可能的。"},{t="扩建营地",b="学会点燃基础篝火，就具备了在荒野各处建立简易营地的能力。虽然初级营地只能容纳少数简陋的家具，但专心致志的冒险者可以扩展其功能。随着冒险者磨练烹饪熟练度，他们将解锁点燃更大、更稳固篝火的方法。此外，精通其他专业技能的工匠可以咨询各自的训练师，学习如何制作家具和改良设施，从而充实他们的营地。"}},faq={{q="“Camping 101: Cooking”的目的是什么？",a="“Camping 101: Cooking”通过指导冒险者学习烹饪专业，向他们介绍野外生存的基本知识。建立篝火是你在荒野中任何地方搭建营地的核心基础。",al={"这个任务有什么用","camping 101: cooking 的目的","为什么要完成 camping 101"}},{q="扎瑞恩是谁？",a="扎瑞恩是一位位于泰达希尔的多兰纳尔的烹饪训练师。他教导新手冒险者烹饪艺术的基础知识，以及如何搭建基础篝火。",al={"扎瑞恩是谁","扎瑞恩 多兰纳尔","多兰纳尔的烹饪训练师在哪里"}},{q="如何在荒野中搭建营地？",a="搭建营地始于通过烹饪专业学会的建立基础篝火。虽然基础训练允许你带着简单的家具在野外露营，但提升你的技能可以解锁更大的篝火和额外的营地改进。",al={"如何搭建营地","露营是如何运作的","建立一个营地"}},{q="可以为营地添加家具吗？",a="虽然烹饪提供了固定营地的篝火，但艾泽拉斯各地的其他专业技能训练师可以教导熟练的工匠如何用专门的装备和装饰来布置和升级他们的营地。",al={"营地布置","营地装饰","其他专业的营地家具"}},{q="为什么露营需要烹饪？",a="烹饪教导冒险者如何在野外搭建和维护露天篝火。因为火是任何户外营地的核心，学习烹饪是进行正规野外露营的第一步。",al={"为什么露营需要烹饪","烹饪与露营的联系"}},{q="可以制造更大的篝火吗？",a="可以。当你练习烹饪技艺并提升烹饪等级时，你可以学习如何建造更大的篝火，以更好地支持你的野外营地。",al={"我可以制造更大的篝火吗","如何升级篝火"}}},fp="20,384,22.515.0,22.504.0,44.234.0,14.159.0,44.272.0,41.214.0,36.228.0,30.155.0"}
P.entries["quest:96638"] = {n="The Adventurer",s="“The Adventurer”是泽风岛上的一项引导旅程任务。该任务由森达尔林地的Aetheen of the Gales发布，引导初出茅庐的游荡者向西南方前往申达尔村，去拜访一位了解荒野的露营老手Raan Wildwind。",h="“The Adventurer”是泽风岛上的一项引导旅程任务。该任务由森达尔林地的Aetheen of the Gales发布，引导初出茅庐的游荡者向西南方前往申达尔村，去拜访一位了解荒野的露营老手Raan...",kw={"aetheen of the gales","raan wildwind","申达尔村","the adventurer","森达尔林地","泽风岛"},ang={["race:Skyborne"]="对于从森达尔林地遮蔽的树冠下走出的年轻Skyborne来说，与Raan Wildwind的相遇标志着他们迈向岛屿家园更广阔、未被驯服地域的第一步。"},sec={{t="离开林地",b="虽然森达尔林地提供了庇护和安静的避风港，但泽风岛更广阔的区域依然狂野且充满危险。Aetheen of the Gales注视着初学者，观察着他们何时准备好跨出熟悉的边界。对于那些寻求名声、财富或目标的人来说，留在这片林地的庇护范围内已不再足够。"},{t="道路上的向导",b="在林地西南方向通往申达尔村的路上，另一位旅行者已经扎下了营地。Raan Wildwind曾花时间在安全区外探索，历经艰险。寻找他能为新兴的游荡者们提供关于森达尔林地以外生存的实用入门知识，并向已经在大道上历练过的人学习。"}},faq={{q="谁派你去寻找Raan Wildwind？",a="Aetheen of the Gales在森达尔林地内发布该任务。在你证明了自己的实力后，她会鼓励你寻找一位对这片广阔岛屿有着第一手经验的人。",al={"谁发布the adventurer","谁开启the adventurer任务","aetheen任务"}},{q="Raan Wildwind在哪里？",a="Raan Wildwind在森达尔林地西南方扎下了营地，位置就在通往申达尔村的主路旁。",al={"raan wildwind位置","raan在哪里","如何找到raan wildwind"}},{q="这项任务的目的是什么？",a="它起到了引导作用，将旅行者带出森达尔林地的安全区，并让他们与更深入泽风岛的导师和挑战建立联系。",al={"为什么要做the adventurer","the adventurer任务目的","raan教什么"}},{q="在领取此任务前必须完成什么前提条件？",a="你必须为Aetheen of the Gales完成有关Foul Matriarch的任务，之后她才会指引你沿路前往Raan Wildwind处。",al={"the adventurer前置条件","the adventurer要求"}},{q="申达尔村对旅行者来说安全吗？",a="申达尔村位于Raan的营地之外，在森达尔林地向西南延伸的道路尽头。虽然它是岛上一个显著的定居点，但年轻的冒险者在道路和周围荒野行进时仍需保持谨慎。",al={"申达尔安全吗","申达尔村是什么"}},{q="Raan Wildwind是谁？",a="Raan Wildwind是一位勇敢的游荡者，他冒险离开森达尔林地，在申达尔村外建立了营地，为沿途的新人提供建议和任务。",al={"raan背景故事","raan wildwind是谁"}}},fx={dc12ab9c={q="Aetheen of the Gales为什么派你去寻找Raan Wildwind？",a="Aetheen注意到，越来越多的流浪者为了追逐荣耀与财富，踏出森达尔林地的安全地带。Aetheen知道荒野对缺乏经验的人来说十分危险，因此想让你去寻找同为旅人的Raan Wildwind。他在申达尔村附近扎营，可以传授实用的知识和生存经验，帮助你在岛上的旅途中活下来。",al={"aetheen为什么派你去","aetheen of the gales的动机","为什么要见raan wildwind"}}},fp="14,245,17.355.0,19.347.0,36.193.0,31.125.0,33.169.0,64.136.0,39.226.0,21.182.0"}
P.entries["quest:96646"] = {n="Camping 101: Cooking",s="Camping 101: Cooking 是一项入门任务，向冒险者传授烹饪艺术，作为荒野生存的重要基石。通过向申达尔村的 Zerril Softbreeze 学习如何生起篝火，旅行者将解锁在野外搭建营地的能力。",h="Camping 101: Cooking 是一项入门任务，向冒险者传授烹饪艺术，作为荒野生存的重要基石。通过向申达尔村的 Zerril Softbreeze 学习如何生起篝火，旅行者将解锁在野外搭建营地的能力。",kw={"篝火","露营","营地","烹饪","陈设","申达尔村","zerril softbreeze"},ang={["profession:Cooking"]="学习基础烹饪提供了建造篝火所需的基本知识，从而为任何野外营地建立起中心支柱。"},sec={{t="荒野炉火",b="对于行走在荒蛮之地的冒险者来说，生存之道始于炉火。Camping 101: Cooking 为游荡者介绍了烹饪工艺的艺术，这不仅是为了准备食物，更是因为掌握基本的生火技巧是建立野外安全休息点的第一步。"},{t="营地基础",b="有志于露营的冒险者需要前往申达尔村寻找 Zerril Softbreeze，学习烹饪行业的入门知识。一旦冒险者掌握了如何点燃篝火，他们就获得了在荒野各处建立小型营地的能力。虽然简陋的营地只能提供最基本的陈设，但提升工艺水平可以让你通过其他专业技能的辅助，生起更大的篝火并进行更丰富的布置。"}},faq={{q="什么是 Camping 101: Cooking？",a="这是一项野外生存入门教学，教导冒险者烹饪艺术和点燃基础篝火如何成为建立营地的核心基础。",al={"什么是 camping 101 cooking","露营烹饪任务"}},{q="Zerril Softbreeze 是谁？",a="Zerril Softbreeze 是一位位于申达尔村的烹饪训练师，负责指导新手掌握基本的烹饪艺术以及如何生起篝火。",al={"zerril softbreeze 是谁","申达尔村烹饪训练师"}},{q="为什么建立营地需要学习烹饪？",a="烹饪教导冒险者如何建造并维护篝火，这是建立任何野外营地的核心基础。",al={"为什么要学烹饪来露营","为什么露营需要烹饪"}},{q="Zerril Softbreeze 在哪里？",a="可以在申达尔村找到正在传授专业技能的 Zerril Softbreeze。",al={"zerril softbreeze 在哪里","申达尔村位置"}},{q="营地如何进行装饰？",a="新手可以在他们的篝火旁放置基础陈设，但学习其他工匠训练师的专业技能后，冒险者将能够制作并布置更多的营地陈设。",al={"营地陈设","如何装饰营地"}},{q="篝火可以升级吗？",a="通过提升你的烹饪技能，你可以学会如何生起更大的篝火，从而改善你的野外营地。",al={"更大的篝火","升级营地"}}},fp="20,284,22.312.0,27.442.0,29.173.0,25.145.0,41.152.0,35.76.0,31.183.0,26.116.0"}
P.entries["quest:96652"] = {n="The Adventurer",s="在探索杜隆塔尔崎岖荒野的过程中，旅人们无意间发现了一本朴素且被遗弃的日记，记录着一位陌生人平静的旅途。日记的字里行间流露出对户外生活的热爱，以及在星空下露营的惬意，并提到要将其送交到剃刀岭附近的布拉克手中。",h="在探索杜隆塔尔崎岖荒野的过程中，旅人们无意间发现了一本朴素且被遗弃的日记，记录着一位陌生人平静的旅途。日记的字里行间流露出对户外生活的热爱，以及在星空下露营的惬意，并提到要将其送交到剃刀岭附近的布拉克手中。",kw={"冒险者","布拉克","露营","杜隆塔尔","日记","遗失的日记","剃刀岭"},ang={["class:Hunter"]="那些一生都在野外求生的猎人，很容易对日记中反复提及的荒野露营之乐产生共鸣。",["faction:Horde"]="杜隆塔尔干旱的道路上有许多新兵行走；回收遗失的财物并将其交给像剃刀岭附近的布拉克这样的流浪者，有助于维护中部边境的秩序。"},sec={{t="流浪者的笔记",b="杜隆塔尔是一片严酷的土地，生存通常远比悠闲的旅行重要，因此发现一本流浪记述者的书是一件罕见的事。这本朴素的日记孤零零地躺在红色的尘土中，记载着一位对于部落的普通英雄来说完全陌生的人的所思所想和经历。日记中没有详述血腥的战斗或宏大的战役，而是沉浸在露宿荒野和野外露营的平凡乐趣之中。"},{t="送交布拉克",b="无论这本笔记出自谁之手，他都留下了一些线索——或是某种联系——指向了布拉克，一位在剃刀岭定居点附近露营的冒险者。将遗失的旅人私人物品送还给那些熟悉道路的人，往往是分散的流浪者寻回财物，或者至少被那些守望尘土飞扬的道路的人们所铭记的唯一途径。"}},faq={{q="遗失的日记里有什么？",a="这本书内容极其普通，写满了关于一位默默无闻的冒险者平静经历的日常条目。特别是在字里行间，反复强调了在荒野中扎营的简单快乐与乐趣。",al={"日记里说了什么","遗失日记的内容","日记文本"}},{q="谁写了这本日记？",a="在寻获的书页中，作者的身份依然是个谜；它描述了在你于荒野中发现这本书之前，从未听说过的一个人的生活和旅程。",al={"冒险者是谁","遗失日记的作者","谁写了这本书"}},{q="布拉克是谁？",a="布拉克是一位在杜隆塔尔中部剃刀岭附近露营的冒险者，他负责接收这本遗失的日记。",al={"布拉克 剃刀岭","布拉克是谁","布拉克在哪里"}},{q="日记在哪里找到？",a="这本朴素的日记被发现遗弃在杜隆塔尔的地形之中，等待着路过的部落旅人将其寻回。",al={"我在哪里可以找到日记","遗失日记的位置","冒险者任务起始"}},{q="布拉克为什么关心这本日记？",a="任务中并未提及。布拉克是一位经验丰富的冒险者，在剃刀岭外露营，专门教导新手基本的露营技巧，因此一本写满露营故事的日记对他来说十分受用。",al={"为什么要带给布拉克","布拉克的用途","布拉克的日记"}},{q="写日记的冒险者有危险吗？",a="寻获的书页并未显示有任何不测，仅仅记录了关于露营的美好回忆。然而，在杜隆塔尔的红尘中遗落旅行日记，暗示着作者要么是不小心弄丢了，要么是意外离开了。",al={"作者还活着吗","冒险者死了吗","遗失冒险者的状态"}}},fp="14,268,18.468.0,17.368.0,32.220.0,22.178.0,13.104.0,27.130.0,39.197.0,41.252.0"}
P.entries["quest:96655"] = {n="Camping 101: Cooking",s="Camping 101: Cooking向冒险者介绍了荒野生存的基本技能。通过指引旅行者前往剃刀岭的Cook Torka处，它教授了烹饪和篝火制作的基础知识，这是在野外建立个人营地的必要条件。",h="Camping 101: Cooking向冒险者介绍了荒野生存的基本技能。通过指引旅行者前往剃刀岭的Cook Torka处，它教授了烹饪和篝火制作的基础知识，这是在野外建立个人营地的必要条件。",kw={"篝火","camping 101","camping 101: cooking","营地","cook torka","烹饪","杜隆塔尔","陈设","剃刀岭"},ang={["faction:Horde"]="在杜隆塔尔各地开始冒险的冒险者可以向剃刀岭的Cook Torka报到，学习烹饪这一基础行业。",["profession:Cooking"]="烹饪是建造基本篝火的核心要求，也是荒野生存和建立营地不可或缺的锚点。"},sec={{t="荒野炉火",b="对于任何踏出定居点大门的漫游者来说，在荒野中生存需要的不仅仅是锋利的钢铁和坚固的护甲。任务Camping 101: Cooking指引初露头角的冒险者前往剃刀岭的Cook Torka处学习烹饪艺术。在杜隆塔尔及更远处的开阔荒野中，烹饪不仅意味着准备热腾腾的饭菜，它更是点燃可靠篝火所需的基本准则，而篝火是任何营地的核心。"},{t="建立和布置营地",b="掌握了这些基础知识，旅行者几乎可以在边境的任何地方搭建一个简陋的营地。虽然新手篝火只能支持少数基本陈设，但对这项工艺的进一步钻研会开启新的可能性。加深烹饪专精可以建造更大的火堆，而追求其他商业技能则提供了布置营地所需的工艺，并将其增强为对抗蛮荒野外的坚固堡垒。"}},faq={{q="什么是Camping 101: Cooking任务？",a="Camping 101: Cooking是一项入门任务，教授冒险者户外生存的基础知识。通过学习烹饪和篝火制作，冒险者获得了在野外任何地方建立自己营地的能力。",al={"什么是camping 101 cooking","camping 101 cooking任务","这个任务有什么作用"}},{q="谁是Cook Torka？",a="Cook Torka是位于杜隆塔尔剃刀岭的部落烹饪训练师。他教授有抱负的冒险者烹饪专业的基础知识，以及如何点燃基本的篝火。",al={"谁在剃刀岭教授烹饪","谁是cook torka","cook torka在哪里"}},{q="为什么露营需要烹饪？",a="烹饪不仅仅是为了准备食物；通过烹饪制作的篝火是搭建营地的基础锚点。没有火，在野外就无法维持一个像样的营地。",al={"为什么露营需要烹饪","烹饪与篝火的联系","露营需要烹饪吗"}},{q="冒险者可以在哪里搭建营地？",a="一旦你学会了烹饪和篝火制作的基础知识，你就能在开阔的荒野中几乎任何地方搭建一个小营地。初始营地非常基础，无法容纳很多陈设。",al={"我可以在哪里露营","露营是如何运作的","营地放置"}},{q="如何升级你的篝火？",a="随着你提高烹饪专业的熟练度，你可以学会建造更大、更持久的篝火，从而获得更强的营地能力。",al={"更大的篝火","升级篝火","如何改善营地"}},{q="如何获得营地的陈设？",a="虽然烹饪提供了篝火基础，但世界各地的其他商业技能训练师可以教授冒险者如何制作和放置额外的陈设，以定制和扩展他们的营地。",al={"营地装饰","布置营地","营地陈设训练师"}}},fp="20,265,22.457.0,30.450.0,39.235.0,18.177.0,36.207.0,42.208.0,33.160.0,45.199.0"}
P.entries["quest:96656"] = {n="The Adventurer",s="The Adventurer 是执行官阿伦交给丧钟镇外经验丰富的年轻被遗忘者勇士的一项入门任务。在打击血色十字军的行动中证明了可靠性后，你被派往布瑞尔方向的道路上，调查在定居点附近徘徊的陌生人。这项任务并没有让你发现又一个狂热间谍，而是让你接触到了 Eleanor Shackleton，一位渴望传授野外生存实用技能的独立旅行者。",h="The Adventurer...",kw={"布瑞尔","露营","丧钟镇","eleanor shackleton","执行官阿伦","血色十字军","the adventurer","the great outdoors","提瑞斯法林地"},ang={["faction:Horde"]="虽然执行官阿伦守卫着被遗忘者领土的新生边界，但与流浪的生存专家进行和平对话，能为部落的新手们获得宝贵的实用技能。",["race:Undead"]="对于刚走出丧钟镇的被遗忘者来说，遇见像 Eleanor 这样的被遗忘者冒险家，是让他们了解到并非布瑞尔附近的所有陌生人都是血色间谍的一门早期课程。"},sec={{t="可疑的监视",b="执行官阿伦时刻警惕着丧钟镇及其周边的动向。由于血色十字军积极地在这一地区进行侦察并渗透进洛丹伦北部，任何在布瑞尔附近游荡的陌生人都必须受到立即审查。既然你已经通过清除边境上的十字军威胁证明了自己的忠诚，阿伦便转而让你秘密调查这位未知的人物，以确定她是否对被遗忘者构成潜在威胁。"},{t="林间的旅行者",b="当你循迹在布瑞尔附近的路上找到 Eleanor Shackleton 时，她的意图与十字军的狂热阴谋或天灾军团的死灵法术毫无关联。作为一名在踏上前往荒野的下一次旅程前稍作停顿的被遗忘者，Eleanor 仅仅是一位冒险者。相反，她从被派来盘问她的人身上认出了冒险者的火花，并提出分享在开阔荒野中生存和建立营地的实用基本常识。"}},faq={{q="为什么执行官阿伦要调查 Eleanor？",a="丧钟镇和布瑞尔不断受到血色十字军渗透者和敌对间谍的威胁。任何在高路上徘徊的陌生人，在证实其动机无害之前，都会被视为可疑对象。",al={"为什么要调查 eleanor","谁派我去见 eleanor","阿伦 eleanor 任务"}},{q="Eleanor Shackleton 是谁？",a="Eleanor Shackleton 是一位在布瑞尔附近的道路旁露营的独立冒险者。她对血色十字军没有任何忠诚，一心专注于探索荒野，并向其他旅行者分享生存经验。",al={"eleanor 是谁","eleanor shackleton 传说","the adventurer npc 是谁"}},{q="Eleanor 与血色十字军有关联吗？",a="没有。抵达她的营地后，Eleanor 很快澄清说，她与威胁提瑞斯法林地的狂热十字军没有任何从属关系。",al={"eleanor 是血色十字军吗","eleanor 敌人","eleanor 是间谍吗"}},{q="这个任务通向哪里？",a="向 Eleanor 报告后会开启任务“户外活动”，在那里她会开始教你野外生存和搭建营地的基础知识。",al={"the adventurer 之后是什么","the adventurer 之后的任务","eleanor shackleton 后续"}},{q="在哪里可以找到 Eleanor Shackleton？",a="她在通往提瑞斯法林地布瑞尔镇的主路旁扎营。",al={"eleanor 位置","eleanor shackleton 在哪里","eleanor 提瑞斯法营地"}},{q="为什么执行官阿伦选择了你来执行这项任务？",a="你通过在丧钟镇附近清除血色十字军特工和信使的出色表现赢得了阿伦的信任，证明你有能力处理敏感的侦察工作。",al={"为什么选我","阿伦的信任","为什么执行官阿伦派你去"}}},fp="14,455,18.461.0,23.423.0,50.208.0,26.227.0,44.151.0,27.143.0,38.99.0,51.172.0"}
P.entries["quest:96658"] = {n="Camping 101: Cooking",s="Camping 101: Cooking 教导初出茅庐的冒险者在野外生火和准备食物的基本艺术。这项课程在联盟和部落的各个新手定居点均有提供，介绍了营火作为任何临时户外营地的核心基石的作用。",h="Camping 101: Cooking 教导初出茅庐的冒险者在野外生火和准备食物的基本艺术。这项课程在联盟和部落的各个新手定居点均有提供，介绍了营火作为任何临时户外营地的核心基石的作用。",kw={"营火","camping 101","烹饪","闪金镇","shackleton","tomas","荒野","扎瑞恩"},ang={["faction:Alliance"]="从北郡、丹莫罗或泰达希尔出发的新手会被指引前往闪金镇、卡拉诺斯和多兰纳尔等城镇，在深入荒野之前学习独立生存的本领。",["faction:Horde"]="对于部落来说，生存是第二天性。杜隆塔尔、莫高雷和提瑞斯法的年轻战士会被直接指引前往剃刀岭、血蹄村和布瑞尔的营火处。",["profession:Cooking"]="烹饪是露营生活的真正火花，它既提供了恢复体力的必要食物，也提供了搭建户外临时营地所需的中心营火。"},sec={{t="荒野之炉",b="为了在坚固的围墙之外生存，每一位旅行者都必须学会如何生火。除了烧水和烤肉之外，基础的营火是这门课程所介绍的、在未知地形搭建营地的关键基础。"},{t="从余烬到营地",b="虽然学徒厨师只能在有限的环境中维持小规模的火势，但掌握烹饪艺术后，你将能够点燃更大的火焰，从而支持更复杂的营地。此外，涉足其他实用商业技能的冒险者还能发现制作实用家具的方法，以完善他们的营地。"}},faq={{q="这个任务的目的是什么？",a="该任务指引新晋冒险者寻找附近定居点的烹饪训练师，确保他们学会基础烹饪并掌握如何点燃营火，作为户外营地的基石。",al={"为什么要学习 camping 101","camping 101 cooking 的目的","这个任务有什么用"}},{q="谁为旅行者提供此任务？",a="双方阵营中都有许多经验丰富的荒野向导和冒险者提供此项训练，包括 Eleanor Shackleton、Eric Brighthammer、Lyreena Duskblade、Sam Sarsaparilla、Brakk、Kaga Wildhoof 以及 Raan Wildwind。",al={"谁提供 camping 101","露营任务发布者"}},{q="联盟玩家在哪里交任务？",a="根据各自的家乡领地，联盟冒险者可以向闪金镇的 Tomas、卡拉诺斯的 Gremlock Pilsnor 或多兰纳尔的 Zarrin 等训练师报告。",al={"联盟在哪里交任务","联盟烹饪训练师"}},{q="部落玩家在哪里交任务？",a="部落冒险者可以在剃刀岭的 Cook Torka、布瑞尔的 William Pickman 或血蹄村的 Pyall Silentstride 处完成训练。",al={"部落烹饪训练师","部落在哪里交任务"}},{q="营地规模以后可以扩大吗？",a="可以。随着烹饪技能的提升，你可以学会点燃更大的火堆，从而在野外支撑更多的营地设施。",al={"更大的营火","升级营地"}},{q="其他专业能对露营做出贡献吗？",a="可以。虽然烹饪提供了作为营地基石的营火，但如果你练习过其他商业技能，对应的训练师也能提供制作实用营地家具的方法。",al={"露营专业","营地设施"}}},fp="20,286,28.273.0,26.338.0,34.189.0,35.222.0,39.155.0,36.144.0,36.134.0,44.181.0"}
P.entries["quest:96659"] = {n="The Adventurer",s="当年轻的牛头人准备离开他们红云台地上的祖传训练场时，鹰风酋长请求他们帮最后一个忙。他委托他们将一份必要的补给包交给卡加·野蹄，一位驻扎在血蹄村附近、曾经在鹰风酋长过去遭遇困境时伸出援手的资深流浪者。",h="当年轻的牛头人准备离开他们红云台地上的祖传训练场时，鹰风酋长请求他们帮最后一个忙。他委托他们将一份必要的补给包交给卡加·野蹄，一位驻扎在血蹄村附近、曾经在鹰风酋长过去遭遇困境时伸出援手的资深流浪者。",kw={"血蹄村","纳拉其营地","鹰风酋长","卡加·野蹄","莫高雷","红云台地","补给包","the adventurer"},ang={["faction:Horde"]="鹰风酋长确保离开新手台地的部落盟友能与莫高雷经验丰富的流浪者和哨站建立早期的联系。",["race:Tauren"]="对于第一次迈出纳拉其营地的年轻牛头人来说，向卡加·野蹄传递鹰风的荣誉债务，代表了他们为莫高雷广阔平原上的族人所做的初步贡献。"},sec={{t="酋长的报偿",b="在旅人们沿着台地小径走下莫高雷广阔平原之前，鹰风酋长停下来处理一笔未了的私人债务。早在指引纳拉其营地的新一代猎人和萨满之前，鹰风就与卡加·野蹄有过交集。在酋长口中，她是一位成就卓著的冒险者，曾在他最需要的时候提供了至关重要的帮助。听说她已经在血蹄村外扎营，鹰风便借着这些刚证明了自己的新手的离去，将物资送给这位老恩人。"},{t="离开台地",b="这个任务标志着年轻的部落勇士离开红云台地的一个关键成年礼。通往高原下的小径直达血蹄村，那里是莫高雷中部的文化和后勤中心。将补给包带过平原，连接了台地上受庇护的训练生活与牛头人部族更广阔、更野性的斗争。"}},faq={{q="卡加·野蹄是谁？",a="卡加·野蹄是一位资深的牛头人冒险者，最近在血蹄村外扎营。她与鹰风酋长有着长久的友谊，在过去几年里曾为他提供过重要的帮助。",al={"卡加·野蹄","野蹄是谁","卡加在哪里"}},{q="为什么鹰风酋长要送这些补给？",a="鹰风认为，年轻勇士动身前往血蹄村正是一个绝佳的机会，可以用来偿还对野蹄的一笔旧债，确保这位同为冒险者的朋友有足够的补给继续她的旅程。",al={"鹰风的债务","为什么送补给","补给包的用途"}},{q="卡加·野蹄的营地在哪里？",a="她的营地位于血蹄村外的平原上，从红云台地沿蜿蜒的南向小径进入莫高雷中部即可到达。",al={"卡加的营地位置","寻找卡加","血蹄村营地"}},{q="这个任务什么时候可以接到？",a="一旦旅人在红云台地上证明了自己的实力，并准备好前往莫高雷的广阔领地冒险时，鹰风酋长就会提供这项任务。",al={"什么时候接到冒险者任务","鹰风任务时机","台地出口任务"}},{q="这个任务会让你离开纳拉其营地吗？",a="是的。运送这些补给直接促使你离开纳拉其营地，踏上前往血蹄村的道路。",al={"离开红云台地","前往血蹄村的旅程"}},{q="补给包里装的是什么？",a="补给包里装满了由纳拉其营地的部族所收集的必需品，以维持冒险者在定居点之外生存的需求。",al={"补给品是什么","补给包内容物"}}},fx={["2c6e5885"]={q="鹰风酋长为什么请你运送补给？",a="你已在红云台地完成最初的仪式，正准备离开纳拉其营地，前往莫高雷更广阔的平原。既然你离开时正好会经过血蹄村，鹰风酋长便把这件差事托付给你，而不是派出那些需要留守台地、保护在那里接受训练的年轻牛头人的勇士。",al={"鹰风酋长为什么选我","为什么让我带补给"}}},fp="14,306,23.521.0,16.370.0,21.217.0,44.208.0,38.139.0,38.157.0,48.133.0,43.148.0"}
P.entries["quest:96661"] = {n="Camping 101: Cooking",s="“Camping 101: Cooking”是一项入门任务，旨在向冒险者传授基本的烹饪知识如何成为在荒野中建立营地的基础。通过寻找血蹄村的Pyall Silentstride，旅行者们可以学习如何搭建营火来锚定他们的营地，并为边境的生活做好准备。",h="“Camping 101: Cooking”是一项入门任务，旨在向冒险者传授基本的烹饪知识如何成为在荒野中建立营地的基础。通过寻找血蹄村的Pyall...",kw={"血蹄村","营火","露营入门101","营地","烹饪","家具","pyall silentstride","荒野"},ang={["faction:Horde"]="穿越莫高雷的冒险者将在当地牛头人工匠和厨师的指导下，在血蹄村开始他们的边境生存训练。",["profession:Cooking"]="烹饪是荒野生存的核心基石，不仅提供营养，还是点燃营火的必要技能，而营火则是建立整个营地的中心。"},sec={{t="荒野之炉",b="每一次穿越未开化荒野的长途跋涉都需要基本的荒野生存技能，而每一个真正的营地都始于火。对于踏上卡利姆多的流浪者来说，任务“Camping 101: Cooking”介绍了烹饪训练与边境生存之间的核心联系。烹饪不仅仅是烹饪猎物的肉来提供营养，它还提供了在野外环境中建造一个实用营火所需的基础知识。没有火，冒险者在夜幕降临时就无处栖身。"},{t="建立营地",b="在莫高雷的草海平原，冒险者会被指引去血蹄村寻找Pyall Silentstride学习烹饪的基础知识。通过这项基础训练，冒险者便能在荒野的任何地方点燃营火并搭建一个简单的营地。虽然最初的营地比较简陋，能放置的家具也很少，但随着烹饪技能的提升，你可以解锁更大营火的秘诀。与此同时，精通其他行业的工匠可以制作家具来充实他们的边境哨所。"}},faq={{q="什么是“Camping 101: Cooking”？",a="“Camping 101: Cooking”是一项入门任务，它教导冒险者烹饪和生火是如何成为荒野生存的真正基石的。通过学习烹饪，冒险者将获得在野外制造营火和建立营地的能力。",al={"什么是camping 101 cooking","露营烹饪任务","露营烹饪基础"}},{q="谁是Pyall Silentstride？",a="Pyall Silentstride是一位位于莫高雷血蹄村的烹饪训练师。他指导新手冒险者进行烹饪艺术的学习，并教导他们如何建造基础的营火。",al={"谁是pyall silentstride","pyall silentstride位置","血蹄村烹饪训练师"}},{q="为什么学习露营需要烹饪？",a="在荒野中，烹饪不仅仅是为了准备食物；学习烹饪可以教冒险者如何点燃营火，这正是任何营地的物理和实际锚点。",al={"为什么露营需要烹饪","为什么为了露营要学烹饪","营火与露营的联系"}},{q="随着技能提高，可以制造更大的营火吗？",a="随着你的进步并提升烹饪技能，你将掌握建造更大、更坚固营火所需的知识，从而允许在荒野中进行更完善的营地设置。",al={"可以升级营火吗","更大的营火","如何制作更大的火"}},{q="如何布置营地？",a="虽然营火是营地的核心锚点，但如果你接受过其他工艺的训练，你也可以向世界各地的其他专业训练师学习额外的家具和饰品制作方法。",al={"营地家具如何运作","营地装饰","通过专业技能布置营地"}},{q="可以在哪里搭建营地？",a="一旦你通过基础烹饪训练掌握了如何点燃营火，你就可以在旅途所及的任何开阔荒野中建立一个简陋的营地。",al={"哪里可以放置营地","可以随处露营吗","营地限制"}}},fp="20,322,22.515.0,17.512.0,29.263.0,26.181.0,42.193.0,53.177.0,30.197.0,28.175.0"}
P.entries["quest:967"] = {n="奥萨拉克斯之塔",s="这个任务将黑海岸北部对暗滩教派的调查与整个卡利姆多北部的防御行动联系在了一起。巴苏尔·影击派遣一名联盟信使向南前往灰谷的迈斯特拉岗哨，向他的导师净化者德尔格伦警示教派在奥萨拉克斯之塔的可疑集会。",h="这个任务将黑海岸北部对暗滩教派的调查与整个卡利姆多北部的防御行动联系在了一起。巴苏尔·影击派遣一名联盟信使向南前往灰谷的迈斯特拉岗哨，向他的导师净化者德尔格伦警示教派在奥萨拉克斯之塔的可疑集会。",kw={"灰谷","巴苏尔·影击","暗滩","黑海岸","净化者德尔格伦","圣光","迈斯特拉岗哨","奥萨拉克斯之塔"},ang={["class:Paladin"]="见到德尔格伦为圣骑士们提供了一个在陌生土地上实践神圣使命的鼓舞人心的榜样：一位人类十字军挥舞着圣光，赢得了卡利姆多隐居的暗夜精灵们的深深信任。",["faction:Alliance"]="巴苏尔在黑海岸与德尔格伦在灰谷之间的合作，展示了将卡利姆多北部散落的联盟驻军联系在一起的重要通讯线。",["race:NightElf"]="对于暗夜精灵来说，这项任务凸显了她们的哨兵与那些前来帮助肃清林中恶魔残余的东部王国种族之间日益增长且务实的伙伴关系。"},sec={{t="请求增援",b="在与奥萨拉克斯之塔周围的暗滩教派成员进行初步交锋后，暗夜精灵侦察兵巴苏尔·影击意识到这一威胁已超出了他独自一人所能应对的范畴。为了组织起决定性的反击，他写了一份详细的报告，并将其托付给一名联盟信使，带给他效忠的导师——净化者德尔格伦。由于教派的召唤者们每小时都在变得更加猖狂，必须将消息传达给那些有能力指挥肃清行动的资深领袖。"},{t="通往灰谷之路",b="传递巴苏尔的信件需要跋涉过整个黑海岸，沿着漫长的海岸公路向南走出迷雾，穿过森林边界进入灰谷。净化者德尔格伦驻扎在西侧道路旁的迈斯特拉岗哨，他致力于净化徘徊在林地中的恶魔与亡灵。尽管最初并不了解暗夜精灵的风俗，这位人类圣骑士还是与哨兵建立了深厚的相互尊重关系，成为了不可或缺的盟友。"},{t="觉醒的神圣战士",b="德尔格伦神色严峻地收到了巴苏尔的紧急信件。作为一名忠诚于圣光的战士，他将黑暗教派、灵魂腐蚀以及恶魔爪牙出现在这片古老森林中视为一种不可容忍的亵渎。在读到关于暗滩教派在废墟般的上层精灵之塔中已根深蒂固的消息后，德尔格伦立即准备接管行动并进行反击。"}},faq={{q="净化者德尔格伦是谁？",a="净化者德尔格伦是一位驻扎在灰谷迈斯特拉岗哨的人类圣骑士。他忠诚于圣光，向暗夜精灵哨兵提供他的军事与精神专长，以肃清侵蚀她们祖传森林的恶魔和亡灵。",al={"净化者德尔格伦","德尔格伦是谁","德尔格伦背景故事"}},{q="巴苏尔·影击为什么要给灰谷发送信使？",a="巴苏尔是驻扎在奥萨拉克斯之塔外的一名侦察兵，一直在研究暗滩教派。他意识到该教派的黑暗仪式与人数正在迅速升级，因此将他的发现发给他的导师德尔格伦，以便组织一场有计划的突袭。",al={"为什么给德尔格伦送信","巴苏尔送信原因"}},{q="巴苏尔与德尔格伦是什么关系？",a="德尔格伦是巴苏尔的导师。这位人类圣骑士教导了这位暗夜精灵战斗的艺术，并将他引向圣光的教义，跨越了他们的文化隔阂，建立了不同寻常的亲密纽带。",al={"巴苏尔与德尔格伦","巴苏尔与德尔格伦如何认识"}},{q="迈斯特拉岗哨在哪里？",a="迈斯特拉岗哨是位于灰谷西部、沿着从黑海岸通往南方的干道上的一个联盟前哨站。它是往来于黑海岸与森林深处的旅行者的早期警戒哨岗。",al={"迈斯特拉岗哨位置","迈斯特拉岗哨在哪"}},{q="暗滩教派在奥萨拉克斯之塔做什么？",a="暗滩是一个以黑海岸北部的上层精灵废墟——奥萨拉克斯之塔为基地的教派。他们从事黑暗魔法，与恶魔力量勾结，威胁要将腐蚀之力释放到整个海岸线。",al={"暗滩教派奥萨拉克斯","奥萨拉克斯之塔教派成员"}},{q="德尔格伦如何看待他与暗夜精灵的联盟？",a="德尔格伦承认，他刚来到卡利姆多时，对暗夜精灵的行为举止和生活方式并不习惯。然而随着时间的推移，与她们并肩对抗共同的邪恶，使他对哨兵产生了极大的敬意。",al={"德尔格伦与暗夜精灵","人类圣骑士与暗夜精灵"}}},fx={["4ad41352"]={q="巴苏尔为什么让你当信使，而不是亲自前往？",a="巴苏尔必须留在奥萨拉克斯之塔附近，密切监视黑海岸邪教徒并留意他们不断升级的威胁。从黑海岸的一端前往灰谷路途遥远，他需要一位身手可靠、装备精良的旅人穿越危险的道路，确保这份紧急警告安全送到德尔格伦手中。",al={"为什么派我去找德尔格伦","巴苏尔为什么让你送信","巴苏尔为什么不能送信"}}},fp="22,322,25.469.0,21.486.0,23.383.1,28.252.0,62.264.0,54.217.0,24.221.0,61.223.0,56.246.0"}
P.entries["quest:968"] = {n="上层精灵的工具",s="“上层精灵的工具”是一个由奥伯丁的桑德里斯·织风者提供的联盟任务。旅行者们被派往南部的亚米萨兰废墟，从那些躁动不安的上层精灵幽灵手中夺回遗留的魔法遗物。目标很简单：在这些潜藏的魔法力量对卡利姆多造成进一步危害之前，回收这些古代神器。",h="“上层精灵的工具”是一个由奥伯丁的桑德里斯·织风者提供的联盟任务。旅行者们被派往南部的亚米萨兰废墟，从那些躁动不安的上层精灵幽灵手中夺回遗留的魔法遗物。目标很简单：在这些潜藏的魔法力量对卡利姆多造成进一步危害之前，回收这...",kw={"亚米萨兰","奥伯丁","黑海岸","上层精灵","遗物","大分裂","桑德里斯·织风者"},ang={["class:Druid"]="清除亚米萨兰受腐化的奥术残余，有助于抚平破坏黑海岸荒野自然宁静的精神创伤。",["class:Mage"]="虽然卡多雷社会因恐惧而寻求粉碎这些神器，但奥术学者们却将其视为大分裂前上层精灵工艺的珍稀且原始的范例。",["faction:Alliance"]="协助暗夜精灵保卫他们受诅咒的领土，巩固了联盟在卡利姆多北部原始森林中的存在感与团结。",["race:NightElf"]="对于卡多雷而言，直面亚米萨兰的鬼魂是一个令人悲伤的提醒，让他们想起祖先的傲慢以及其祖先帝国那灾难性的大分裂。"},sec={{t="废墟中的回响",b="在奥伯丁以南，沿海大路以东，坐落着杂草丛生的亚米萨兰石砌地基。一万年前，这座定居点曾是上层精灵——即古代暗夜精灵帝国中的特权贵族——的堡垒。当他们肆无忌惮的奥术实验最终导致了世界大分裂时，亚米萨兰也被摧毁了。然而，它的居民却从未真正离去。在黑海岸巡逻的哨兵们报告说，这些贵族的鬼魂依然游荡在沉没的广场上，紧紧抓着他们生前拥有的附魔工具和饰品。"},{t="净化奥术往事",b="对于现代卡多雷社会而言，奥术不仅是被禁止的知识，更是一种几乎将艾泽拉斯的生命抹去的生存威胁。桑德里斯·织风者深知，将这些上层精灵的器具留在幽灵手中无异于为腐化敞开大门。通过派遣冒险者从这些躁动不安的灵魂手中夺回遗物，桑德里斯意图彻底摧毁它们，确保那潜藏的、被污染的魔法永远不会再引发另一场灾难。"}},faq={{q="我在哪里可以找到上层精灵的遗物？",a="这些遗物可以在亚米萨兰的废墟中找到，它位于奥伯丁以南，黑海岸主路东侧。游荡在废弃石砌庭院中的灵魂携带着这些古代器具。",al={"遗物在哪里","亚米萨兰位置","去哪里找遗物"}},{q="桑德里斯·织风者是谁？",a="桑德里斯·织风者是一位居住在港口城镇奥伯丁的暗夜精灵学者兼长者。他与当地的哨兵紧密合作，协调各项工作，以保护黑海岸免受大分裂遗留下来的魔法污染和古老诅咒的侵害。",al={"桑德里斯·织风者","谁提供上层精灵的工具任务"}},{q="为什么桑德里斯想要销毁这些遗物？",a="由于上层精灵的鲁莽魔法导致了毁灭性的大分裂，暗夜精灵社会严令禁止奥术魔法。桑德里斯担心如果放任不管，这些物品中残留的奥术力量可能会重新唤醒潜伏的邪恶。",al={"为什么要销毁遗物","上层精灵的工具任务目标"}},{q="在亚米萨兰游荡的是什么样的灵魂？",a="这些灵魂是上古之战中丧生的上层精灵精英的残影。即使在死后，他们依然执着于曾经的骄傲、力量和魔法神器，在废墟的石头间重演着他们已逝的生前时光。",al={"亚米萨兰的鬼魂","这些灵魂是什么"}},{q="为什么上层精灵仍然被束缚在废墟中？",a="桑德里斯没有明说。他只知道哨兵告诉他的情况：上层精灵的灵魂依然徘徊在亚米萨兰的废墟之中，并且仍然挥舞着他们古老的魔法器具。",al={"为什么它们变成了鬼魂","上层精灵的诅咒"}},{q="当你上交遗物后，它们会怎样？",a="桑德里斯·织风者会将收集到的遗物收管，并明确计划将它们永久拆解和销毁，以确保其潜藏的奥术污染永远不会再被利用或释放。",al={"桑德里斯如何处理遗物","遗物的命运"}}},fx={df86da6d={q="上层精灵的遗物是什么？",a="这些遗物是远古的魔法器具，保存自天崩地裂之前，曾由艾萨拉女王宫廷中的精英法师使用。即使历经万年，它们依然残留着奥术力量的污秽；当年，正是对奥术力量的鲁莽试验撕裂了古老的卡利姆多。它们落在依旧徘徊的幽灵手中，仍是潜藏着危险力量的媒介。",al={"上层精灵的遗物是什么","什么是上层精灵遗物","上层精灵遗物的背景"}}},fp="22,360,19.561.0,23.480.0,37.224.0,27.257.0,46.238.0,38.236.0,47.186.0,50.202.0"}
P.entries["quest:96821"] = {n="Legging It",s="“Legging It”是一个专注于清理南部危险道路以保护苦工的任务。道路沿线的威胁吓坏了劳工，使他们停止了前行，导致日常工作陷入停滞。通过击退这些危险，冒险者们恢复了道路的安全，使劳工们能够重返工作岗位。",h="“Legging It”是一个专注于清理南部危险道路以保护苦工的任务。道路沿线的威胁吓坏了劳工，使他们停止了前行，导致日常工作陷入停滞。通过击退这些危险，冒险者们恢复了道路的安全，使劳工们能够重返工作岗位。",kw={"清理了路径","部落劳工","legging it","监工","苦工劳作","苦工","南部路径"},ang={["faction:Horde"]="兽人的劳工和补给线在很大程度上依赖于苦工，因此路线安全对于部落的建设和资源采集至关重要。",["race:Orc"]="苦工是兽人定居点的支柱，监工们依靠勇士来清除路径上的威胁，以确保工作能够持续进行。"},sec={{t="确保路线安全",b="“Legging It”解决了当地劳工运作中的中断问题，因为苦工们因害怕而不敢南下。工人们拒绝在充满危险的道路上冒险，而不去执行指派的任务。通过介入并清除沿途的威胁，旅行者们恢复了足够的安全保障，使监工们能够派遣劳工队继续工作。"},{t="劳工与路线安全",b="苦工是部落基础设施的支柱，负责采伐木材、采石和建造哨所。由于苦工几乎没有战斗能力，即使是轻微的路边掠食者或敌对侦察兵也会导致供应链中断。确保交通要道的畅通对于维持定居点的补给和生产至关重要。"}},faq={{q="什么是“Legging It”？",a="“Legging It”是一项旨在为劳工队确保南部运输路线安全的任务。道路沿线的威胁恐吓了当地苦工，使他们的日常工作陷入停顿，直到一位冒险者介入清除了障碍。",al={"什么是legging it","legging it任务信息","legging it任务"}},{q="为什么苦工们不敢往南走？",a="苦工们因为道路上存在的实际威胁而不敢向南行进。在没有保护或清理路径的情况下，工人们拒绝冒险前往目的地，导致当地的劳作陷入瘫痪。",al={"为什么苦工会害怕","苦工的恐惧","为什么苦工停止工作"}},{q="完成该任务能达成什么效果？",a="随着南部路线的清理和直接威胁的消除，监工们能够安全地将苦工队伍派回实地，恢复劳作和资源采集。",al={"完成legging it之后会发生什么","legging it任务结果","清理路径的成果"}},{q="任务中提到的苦工是谁？",a="苦工是部落的基础劳动力，负责搬运重物、采伐木材、采矿和建造防御工事。虽然他们对定居点的运作至关重要，但他们并不适合战斗，遇到危险往往会退缩。",al={"谁是苦工","苦工的角色","苦工做什么"}},{q="苦工们要去哪里？",a="道路通往南部的外围工作区和资源矿点，这些地方需要苦工进行日常维护，但在路线清理之前，这段旅程已经变得极其危险，迫使所有交通中断。",al={"路径通向哪里","南部路径","前往南方"}},{q="为什么苦工需要冒险者来清理路线？",a="苦工缺乏正规的军事训练和战斗装备，这使他们容易受到荒野掠食者和敌对势力的伤害。监工们必须依靠经验丰富的冒险者来消除外围威胁并维护安全的工作通道。",al={"为什么苦工需要保护","苦工安全","保护苦工"}}},fp="10,324,17.367.0,24.349.0,19.211.0,42.218.0,44.182.0,40.243.0,31.207.0,55.231.0"}
P.entries["quest:96822"] = {n="For Honor",s="For Honor是一项旨在纪念阵亡战士的任务，让他们的事迹不被遗忘。通过完成这项任务，冒险者可以确保这些战斗人员的牺牲被永远铭记。",h="For Honor是一项旨在纪念阵亡战士的任务，让他们的事迹不被遗忘。通过完成这项任务，冒险者可以确保这些战斗人员的牺牲被永远铭记。",kw={"阵亡战士","for honor","荣耀","纪念","任务","缅怀","战士"},ang={["class:Warrior"]="这项任务直接以纪念阵亡战士为核心，能与那些珍视战场牺牲和永恒缅怀的战士产生强烈共鸣。"},sec={{t="缅怀之责",b="For Honor任务是一项庄严的使命，核心在于纪念阵亡的战士。在一个不断受到冲突考验的世界里，确保那些付出了一切的士兵不被遗忘，对于生者而言是一项至关重要的职责。"},{t="守护传承",b="在完成任务后，任务发布者会确认，多亏了你的努力，那些阵亡战士的事迹将永载史册。这项已完成的功绩确保了他们的牺牲得到认可与尊重，而非湮没在历史的长河中。"}},faq={{q="For Honor任务的内容是什么？",a="For Honor是一项专注于纪念阵亡战士的任务。通过承接并完成这项任务，你能够帮助确保这些战士的牺牲得到认可，而不会被历史遗忘。",al={"for honor是什么","for honor任务概览"}},{q="任务完成后提到的战士是指谁？",a="任务文本特别致敬了那些阵亡的战士，他们的事迹和记忆通过你的行动得以保存。那些坚持完成任务的人，让他们的服务与牺牲得以延续。",al={"战士是谁","谁被铭记"}},{q="为什么要纪念这些战士？",a="这项任务的目的是缅怀。在这个充满战乱与冲突的世界里，纪念那些战死沙场的人们既是给予他们尊严，也是确保他们的勇气得到认可。",al={"为什么要完成这个任务","for honor的含义"}},{q="是谁要求完成这项任务的？",a="这项任务是由想要纪念阵亡战友的人所指派的。当你归来时，他们会核实任务是否完成，并确认这些战士将永远被铭记。",al={"谁发布了for honor","for honor的任务发布者"}},{q="这项任务会引出其他任务吗？",a="任务中没有任何线索指向后续任务。它本身就是为了纪念阵亡战士而存在，巩固他们的遗产，确保他们的牺牲永不被遗忘。",al={"for honor是否属于任务链","for honor之后是什么"}},{q="For Honor这个标题意味着什么？",a="这个名称反映了纪念阵亡士兵这一核心主题。它强调了承认牺牲并让战场的记忆长存，是战士所能承担的最庄严的职责之一。",al={"为何它被称为荣耀","for honor的意义"}}},fp="9,201,21.240.0,21.232.0,34.196.0,47.187.0,41.197.0,34.194.0,36.186.0,38.201.0"}
P.entries["quest:96825"] = {n="This Fruit Could Bite Back",s="“This Fruit Could Bite Back”是一项采集任务，专注于在奥格瑞玛附近的干旱土地上收集野生仙人掌果。这些果实既可加工成食物，其种子也会被保存下来用于日后种植，目的是培育出一种适应性强的沙漠作物，以养活部落的首府。",h="“This Fruit Could Bite...",kw={"仙人掌果","杜隆塔尔","果实","奥格瑞玛","种子","this fruit could bite back"},ang={["faction:Horde"]="确保可持续的食物来源（如充实的沙漠果实）对于供养兽人首府和滋养部落不断增长的人口至关重要。",["profession:Cooking"]="在杜隆塔尔的干旱气候下，仙人掌果具备极佳的烹饪潜力，既可作为美味菜肴的配料，也是城市居民的给养。",["profession:Herbalism"]="采集者和植物学家们深知沙漠植物的顽强，也了解为了耕种而收集多刺野生果实所付出的努力。"},sec={{t="收获干旱荒原",b="杜隆塔尔是一片崎岖、被烈日烘烤的土地，传统的农业几乎无法在此开展。为了支持日益壮大的奥格瑞玛首府，足智多谋的居民们转向了本地的沙漠植物。仙人掌果是一种生命力顽强的仙人掌果实，长有保护性的尖刺，在干旱的土壤中茁壮成长，小心采集后可提供急需的养分。"},{t="耕种与补给",b="采集仙人掌果不仅仅是为了提供一顿即时的餐食。虽然果肉可以加工成美味的菜肴，但采摘下来的种子会被仔细保存以供种植。其宏愿是在奥格瑞玛周围种植这些适应性强的作物，在堡垒城墙外建立一个触手可及且持久的食物来源。"}},faq={{q="“This Fruit Could Bite Back”是什么？",a="“This Fruit Could Bite Back”是一项专注于在杜隆塔尔收集野生仙人掌果的任务。收集到的果实既用于即时的烹饪，也用于保存种子，以便在奥格瑞玛周围的干旱地带进行繁殖。",al={"什么是 this fruit could bite back","this fruit could bite back 任务","咬人果实任务"}},{q="为什么要采集仙人掌果？",a="采集的仙人掌果具有双重用途：为当地居民准备美味的餐食，以及收获可用的种子。长远目标是在奥格瑞玛周围的干旱土地上广泛种植仙人掌果。",al={"为什么要采集仙人掌果","仙人掌果的用途","仙人掌果的作用"}},{q="种子将种在哪里？",a="从收获中留存的种子计划种在奥格瑞玛的郊区和周边土地上，以帮助在贫瘠的沙漠土壤中建立一个具有韧性、可持续的食物供应。",al={"仙人掌果生长在哪里","在奥格瑞玛种植仙人掌果"}},{q="谁要求采集这些果实？",a="一位当地居民希望改善本地食物储备，并在杜隆塔尔严酷的沙漠气候中耕种作物，因此请求采集这些果实，以供养过往旅人并培育未来的作物。",al={"谁需要仙人掌果","任务发放者咬人果实"}},{q="为什么这种果实会“咬人”？",a="仙人掌果覆盖着坚韧沙漠仙人掌特有的锋利尖刺和针芒，如果处理不当，采集它们会有危险。",al={"为什么会咬人","为什么果实会咬人"}},{q="为什么在奥格瑞玛周围种植果实很重要？",a="杜隆塔尔主要由干旱的岩石地形构成，传统的农业难以开展。建立耐旱作物（如仙人掌果）有助于为这座首府城市提供可持续的补给。",al={"奥格瑞玛缺粮吗","奥格瑞玛农业","杜隆塔尔农耕"}}},fp="26,286,26.348.0,26.348.0,35.227.0,37.223.0,32.211.0,32.179.0,31.138.0,49.197.0"}
P.entries["quest:96875"] = {n="Beasts of Thunder Ridge",s="Beasts of Thunder Ridge是奥格瑞玛的一项任务，由制皮师Kamari发布，他支持部落首都的持续扩建。冒险者们被派往雷霆山的峭壁，收集耐用的蜥蜴皮，并提供熟化皮毛来加固这座城市新建的建筑。",h="Beasts of Thunder Ridge是奥格瑞玛的一项任务，由制皮师Kamari发布，他支持部落首都的持续扩建。冒险者们被派往雷霆山的峭壁，收集耐用的蜥蜴皮，并提供熟化皮毛来加固这座城市新建的建筑。",kw={"beasts of thunder ridge","熟化轻皮","杜隆塔尔","kamari","制皮","奥格瑞玛","苦工","粗糙蜥蜴皮","雷霆山"},ang={["faction:Horde"]="随着部落在杜隆塔尔确立其势力，从周边荒野收集的补给直接推动了奥格瑞玛的防御加固和发展。",["race:Orc"]="兽人的建筑依赖于猎人和劳工采集的坚固耐用材料，以抵御杜隆塔尔恶劣的自然环境。"},sec={{t="不断扩建的首都",b="随着部落在杜隆塔尔干旱的土地上建立家园，首都奥格瑞玛依然处于不断的扩建状态。新的住所、作坊和防御工事需要源源不断的木材、石料和动物皮毛。虽然木材必须从更远的地方运来，但杜隆塔尔当地的动物为城市的苦工和建造者们提供了坚韧耐用的皮革补给。"},{t="峡谷中的野兽",b="在雷霆山深处，本地的蜥蜴生长着坚硬、粗糙的皮。虽然这些皮毛通常太厚且太硬，无法制成可穿戴的皮甲，但它们的韧性使其成为绝佳的建筑材料。如果采集得当，它们可以用来覆盖奥格瑞玛木石结构建筑的天花板和墙壁，保护室内免受烈日和峡谷强风的侵袭。"}},faq={{q="为什么奥格瑞玛需要雷霆山的蜥蜴皮？",a="在雷霆山采集的粗糙蜥蜴皮对于制作可穿戴的护甲来说太粗、太厚了，但它们的韧性使其非常适合用于建筑。奥格瑞玛的苦工们用它们来覆盖新建建筑的墙壁和屋顶，以抵御恶劣的天气。",al={"皮革的用途","为什么要粗糙蜥蜴皮","雷霆山皮革的用途"}},{q="Kamari是谁？",a="Kamari是部落首都奥格瑞玛的一名制皮师，他为城市的建造者和苦工提供持续建设工程所需的坚固皮毛和皮革。",al={"谁是kamari","kamari 奥格瑞玛","beasts of thunder ridge的发布者"}},{q="雷霆山在哪里？",a="雷霆山是位于杜隆塔尔干旱领地内的一处崎岖峡谷，以Kamari为城市新建筑所需的、皮质厚实的蜥蜴而闻名。",al={"雷霆山在哪里","雷霆山位置","雷霆山 杜隆塔尔"}},{q="为什么要和蜥蜴皮一起收集熟化轻皮？",a="除了沉重的蜥蜴皮，Kamari还需要熟化轻皮来配合这些较重的材料，这是对冒险者在皮革加工方面更广泛的了解和技能的考验。",al={"为什么需要熟化轻皮","熟化皮革的用途"}},{q="为什么奥格瑞玛扩建得如此迅速？",a="作为部落新建立的首都，奥格瑞玛正在进行持续的施工和扩建，以容纳日益增多的兽人及其盟友，从而对原材料产生了持续的需求。",al={"为什么奥格瑞玛在施工","奥格瑞玛扩建"}},{q="雷霆山的蜥蜴皮能制成护甲吗？",a="来自雷霆山的粗糙蜥蜴皮通常太厚且太僵硬，无法制成柔韧的护甲，因此它们的主要实际价值在于建筑而非穿戴。",al={"蜥蜴皮可以穿吗","粗糙蜥蜴皮是护甲吗"}}},fp="23,302,17.404.0,20.426.0,56.295.0,14.172.0,31.161.0,60.183.0,38.198.0,59.173.0"}
P.entries["quest:96876"] = {n="Ukor's Lost Pack",s="Ukor's Lost Pack是一个在杜隆塔尔南部荒野中发现的掉落物品，上面粗糙地缝着主人的名字。在乌克尔遭遇该地区原生的一种巨型蜘蛛并仓皇逃窜时，他不慎将其遗弃。",h="Ukor's Lost Pack是一个在杜隆塔尔南部荒野中发现的掉落物品，上面粗糙地缝着主人的名字。在乌克尔遭遇该地区原生的一种巨型蜘蛛并仓皇逃窜时，他不慎将其遗弃。",kw={"杜隆塔尔","部落","失落的包裹","杜隆塔尔南部","蜘蛛","乌克尔","ukor's lost pack"},ang={["faction:Horde"]="在杜隆塔尔南部冒险的年轻部落冒险者经常会帮助像乌克尔这样的当地人，通过从危险的野生动物手中找回遗失的个人物品，来证明自己的价值和可靠性。"},sec={{t="失落的物品",b="当The Adventurer穿越杜隆塔尔南部干旱的荒野时，发现了一个被遗弃的旅行包，包盖上粗糙地缝着“Ukor”的名字。在杜隆塔尔这片严酷的土地上生存，没有粗心大意的余地，发现被遗弃的装备通常意味着附近发生过不幸的遭遇。"},{t="逃离荒野",b="将包裹归还给杜隆塔尔南部的乌克尔后，它被遗弃背后的故事浮出水面。乌克尔在遭遇该地区原生的一种巨型蜘蛛伏击时惊慌失措，丢下了包裹，并确信自己永远无法再找回补给品。找回完好无损的包裹为旅行者赢得了他衷心的感激和赞美。"}},faq={{q="乌克尔是谁？",a="乌克尔是居住在杜隆塔尔南部的一名居民。在干旱的荒野中面对一只巨型蜘蛛时，为了安全脱身，他被迫遗弃了自己的财物。",al={"乌克尔是谁","乌克尔 杜隆塔尔"}},{q="乌克尔为什么会弄丢他的包裹？",a="乌克尔在躲避杜隆塔尔中潜伏的一只巨型蜘蛛时，为了保命而丢下了包裹。在The Adventurer追踪并找到这个包裹之前，他以为自己的财物已经彻底遗失了。",al={"为什么包裹会丢失","乌克尔在哪里丢失的包裹"}},{q="这个包裹需要送到哪里？",a="找回的包裹属于乌克尔，他就在杜隆塔尔南部等待，随时准备迎接归来的旅行者。",al={"去哪里归还包裹","乌克尔 任务提交"}},{q="如何辨认这个包裹？",a="包裹上粗糙地缝着乌克尔的名字，这使得它很容易辨认。",al={"如何辨认包裹","包裹缝线"}},{q="是什么样的生物追赶了乌克尔？",a="乌克尔遭到了杜隆塔尔南部地形中游荡的一只巨型蜘蛛的伏击，这让他惊恐万分，丢下所有财物逃命去了。",al={"杜隆塔尔的蜘蛛","袭击乌克尔的是什么蜘蛛"}},{q="把包裹归还给乌克尔会发生什么？",a="乌克尔对于能再次见到自己失落的财物感到非常惊讶和感激，并称赞找回他包裹的The Adventurer是一位真正的英雄。",al={"乌克尔的奖励","乌克尔的反应"}}},fp="16,232,16.327.0,17.317.0,12.183.0,27.174.0,37.116.0,27.99.0,34.152.0,46.138.0"}
P.entries["quest:96877"] = {n="Halikor's Hoof",s="Halikor's Hoof 是一项任务，核心在于猎杀强大的蜥蜴 Halikor 后取得实物证据。将那只巨大的断蹄带回部落首都奥格瑞玛，是对猎人战胜这只强大荒野野兽的荣耀嘉奖。",h="Halikor's Hoof 是一项任务，核心在于猎杀强大的蜥蜴 Halikor 后取得实物证据。将那只巨大的断蹄带回部落首都奥格瑞玛，是对猎人战胜这只强大荒野野兽的荣耀嘉奖。",kw={"halikor","halikor's hoof","部落","狩猎","蜥蜴","奥格瑞玛","战利品"},ang={["class:Hunter"]="击败像 Halikor 这样巨大而强大的野兽，是追踪者技艺和狩猎快感的典范。",["faction:Horde"]="将强大野兽被击败的证明带到奥格瑞玛，彰显了部落崇尚力量和狩猎技艺的传统。"},sec={{t="强大野兽的战利品",b="Halikor's Hoof 是从体型极其巨大的蜥蜴 Halikor 的遗骸上获取的有形战利品。在穿梭于蛮荒前线的猎人和勇士中，从如此强大的生物身上获取实物信物来验证猎杀成果是一项古老的习俗。蹄子巨大的尺寸毫无疑问地证明了这只野兽生前的庞大规模和力量。"},{t="带给首都的证明",b="将沉重的蹄子带回奥格瑞玛那防御森严的大门，是为了向部落宣告野兽的覆灭。在一个崇尚原始力量并在严酷的荒野掠食者面前求生存的勇士社会中，展示这样的战利品不仅能为猎人带来荣耀，也能让首都确信这只危险的生物已被击杀。"}},faq={{q="Halikor 是什么？",a="Halikor 是一只强大无比的蜥蜴生物。其巨大的体型可以通过其断蹄的庞大规模来体现，猎人们以此作为其覆灭的铁证。",al={"什么是 halikor","halikor 是谁","halikor 蜥蜴"}},{q="为什么必须将蹄子送到奥格瑞玛？",a="将蹄子带回部落首都奥格瑞玛是为了作为野兽被击败的实物证明，向全城展示猎人的凯旋。",al={"为什么要将蹄子带到奥格瑞玛","halikor 蹄子交付","蹄子要去哪里"}},{q="Halikor's Hoof 是如何获得的？",a="Halikor's Hoof 是在追踪并战斗击杀这只巨大的蜥蜴后，直接从 Halikor 的尸体上获得的。",al={"如何获取 halikors hoof","halikor 掉落"}},{q="为什么蜥蜴会有蹄子？",a="Halikor 并非普通的蜥蜴，而是一只荒野中的强大野兽，其巨大的蹄子就是证明你将其击倒的战利品。至于为什么它会长着蹄子，无人知晓。",al={"halikor 有蹄子吗","为什么蜥蜴会有蹄子"}},{q="奥格瑞玛里谁想要 Halikor's Hoof？",a="你将蹄子带回奥格瑞玛作为胜利的证明；并没有指定特定的猎人或官员来接收它。",al={"在奥格瑞玛谁接收 halikors hoof","在奥格瑞玛上交 halikor 蹄子"}},{q="Halikor's Hoof 这个任务背后的故事是什么？",a="Halikor's Hoof 是一项围绕击败巨大蜥蜴 Halikor 的任务。将其巨大的断蹄带回奥格瑞玛，展现了猎人的武勇，并将野兽覆灭的消息传达给部落。",al={"什么是 halikors hoof 任务","halikors hoof 的故事"}}},fp="14,235,24.357.0,21.337.0,16.181.0,44.146.0,31.121.0,30.176.0,38.115.0,50.222.0"}
P.entries["quest:96895"] = {n="The Argent Emissary",s="The Argent Emissary标志着两名效力于银色黎明的被遗忘者代表抵达此地，追踪幽暗城附近的亡灵天灾邪教徒。他们的出现既凸显了双方共同对抗天灾军团的事实，也反映了这个中立组织与被遗忘者当局之间微妙的紧张关系。",h="The Argent Emissary标志着两名效力于银色黎明的被遗忘者代表抵达此地，追踪幽暗城附近的亡灵天灾邪教徒。他们的出现既凸显了双方共同对抗天灾军团的事实，也反映了这个中立组织与被遗忘者当局之间微妙的紧张关系。",kw={"银色黎明","the argent emissary","邪教徒","被遗忘者","天灾军团邪教徒","提瑞斯法林地","幽暗城"},ang={["faction:Horde"]="虽然银色黎明是中立的，但部落当局对他们在幽暗城附近的独立行动保持着警惕。",["race:Undead"]="看到被遗忘者同胞选择加入银色黎明而非幽暗城，这鲜明地提醒了人们自由亡灵之间效忠对象的不同。"},sec={{t="谨慎的欢迎",b="两名来自银色黎明的被遗忘者使者最近抵达了提瑞斯法林地，这让当地的当局感到不安。尽管银色黎明反对天灾军团，但当地的被遗忘者依然对任何未经监督就在其领土内活动的武装中立组织持怀疑态度。即使这些使者本身就是同族，也难以缓解他们的警惕。"},{t="大门外的邪教徒",b="这些使者并非为了瞻仰洛丹伦废墟而来；他们正在追踪一群被发现潜伏在幽暗城东南郊外的天灾军团邪教徒。为了在巫妖王的代理人站稳脚跟前将其铲除，其中一名使者已经前往城门附近，监视敌人的动向。"}},faq={{q="银色黎明使者是什么人？",a="两名代表银色黎明的使者最近前往了提瑞斯法林地。值得注意的是，这两名使者都是已经加入该神圣中立组织的被遗忘者，而不是单纯效力于幽暗城。",al={"谁是使者","银色黎明访客","谁来到了提瑞斯法"}},{q="为什么银色黎明要在幽暗城附近活动？",a="他们正在追踪在幽暗城东南郊外窥探的天灾军团邪教徒。银色黎明致力于在任何天灾残党出现的地方将其猎杀，即使是在部落的主要定居点附近也是如此。",al={"为什么他们在幽暗城附近","银色黎明提瑞斯法任务","使者在做什么"}},{q="为什么当地的被遗忘者对这些使者保持警惕？",a="尽管银色黎明与天灾军团这一共同敌人作战，但当地的被遗忘者并不喜欢中立的武装组织在没有监督的情况下在提瑞斯法林地活动，无论这些使者是否与他们同为亡灵。",al={"为什么对银色黎明感到紧张","我们能信任银色黎明吗","被遗忘者对银色黎明的看法"}},{q="邪教徒构成了什么威胁？",a="一小群天灾军团邪教徒被发现在城市东南的郊外潜伏。由于巫妖王对自由亡灵持续构成的威胁，他们的出现立刻引起了当地斥候和银色黎明的注意。",al={"幽暗城外的邪教徒","提瑞斯法的亡灵天灾","邪教徒是什么人"}},{q="使者去哪了？",a="其中一名使者向东南方移动，前往幽暗城的入口，跟踪监视那些在城墙外活动的亡灵天灾邪教徒。",al={"在哪里可以找到使者","使者位置","寻找银色黎明成员"}},{q="被遗忘者可以在银色黎明效力吗？",a="可以。与血色十字军不同，银色黎明欢迎所有愿意对抗天灾军团的人，包括那些投身于此事业的自由意志亡灵。",al={"被遗忘者是否允许加入银色黎明","银色黎明亡灵","亡灵能否加入银色黎明"}}},fp="19,285,12.370.0,21.360.0,30.233.0,52.219.0,46.234.0,41.244.0,26.162.0,41.174.0"}
P.entries["quest:96896"] = {n="A Righteous Cause",s="“正义事业”见证了受人尊敬的列奥尼德·巴萨洛缪与达妮萨·莫尔之间的交谈，他们回顾了幽暗城防御纳克萨玛斯进攻的往事。他们的交流重点提到了加瑞克·班达里恩，一位重新发掘如何以圣骑士身份运用圣光的被遗忘者英雄。该任务揭示了那些尽管遭到同胞质疑，却依然努力维持与圣光联系的少数被遗忘者。",h="“正义事业”见证了受人尊敬的列奥尼德·巴萨洛缪与达妮萨·莫尔之间的交谈，他们回顾了幽暗城防御纳克萨玛斯进攻的往事。他们的交流重点提到了加瑞克·班达里恩，一位重新发掘如何以圣骑士身份运用圣光的被遗忘者英雄。该任务揭示了那些...",kw={"达妮萨·莫尔","被遗忘者","加瑞克·班达里恩","列奥尼德·巴萨洛缪","圣光之愿礼拜堂","纳克萨玛斯","圣骑士","正义事业","天灾军团","幽暗城"},ang={["class:Paladin"]="加瑞克·班达里恩和达妮萨的队伍代表了一种非凡的发展：被遗忘者尽管处于亡灵状态，却重新发掘了以圣骑士身份运用圣光的方法。",["faction:Horde"]="列奥尼德·巴萨洛缪的出现凸显了幽暗城防御者与驻扎在瘟疫之地圣光之愿礼拜堂的银色黎明之间的联系。",["race:Undead"]="虽然列奥尼德和达妮萨努力与圣光重新建立联系，但大多数被遗忘者仍然对他们在亡灵状态下的这条圣光之路保持冷漠或敌视。"},sec={{t="老兵重聚",b="“正义事业”围绕两位洛丹伦老兵防御者的感人重聚展开：受人尊敬的列奥尼德·巴萨洛缪和达妮萨·莫尔。在经历了纳克萨玛斯向幽暗城发动天灾军团袭击的惨烈战斗后，两人共同缅怀了阵亡的战友，并反思了那些依然崇敬圣光的被遗忘者所走的艰难道路。"},{t="加瑞克·班达里恩的遗产",b="他们共同记忆的焦点是加瑞克·班达里恩，这座堡垒正是以这位阵亡英雄的名字命名的。据列奥尼德所言，加瑞克或许是第一位重新发掘如何以真正的圣骑士身份运用圣光的被遗忘者。虽然大多数被遗忘者已经完全背弃了圣光，但达妮萨和她的同伴致力于继承加瑞克的遗产，并探索圣光不死之身的潜力。"},{t="重返瘟疫之地",b="与达妮萨谈话后，列奥尼德准备离开堡垒。他的忠诚属于在满目疮痍的东部地区持续对抗天灾军团的战斗，他在东瘟疫之地的圣光之愿礼拜堂驻扎，欢迎任何愿意为这一事业拿起武器的健壮冒险者。"}},faq={{q="受人尊敬的列奥尼德·巴萨洛缪是谁？",a="受人尊敬的列奥尼德·巴萨洛缪是银色黎明中一位著名的亡灵成员。虽然他在东瘟疫之地的圣光之愿礼拜堂开展工作，但他仍与洛丹伦曾并肩对抗天灾军团的旧日战友保持着联系。",al={"列奥尼德·巴萨洛缪是谁","列奥尼德","列奥尼德·巴萨洛缪背景故事"}},{q="达妮萨·莫尔是谁？",a="达妮萨·莫尔是一位在纳克萨玛斯袭击幽暗城时与列奥尼德·巴萨洛缪并肩作战的被遗忘者领袖。她现在领导着一支致力于传承加瑞克·班达里恩的教诲和神圣遗产的队伍。",al={"达妮萨·莫尔是谁","达妮萨","达妮萨·莫尔背景故事"}},{q="加瑞克·班达里恩是谁？",a="加瑞克·班达里恩是一位英勇的被遗忘者战士，在纳克萨玛斯袭击幽暗城的防御战中阵亡。列奥尼德指出，他可能是第一位重新发掘如何以圣骑士身份运用圣光的被遗忘者。",al={"加瑞克·班达里恩是谁","加瑞克·班达里恩背景故事","堡垒命名来源"}},{q="幽暗城受袭期间发生了什么？",a="当纳克萨玛斯大墓地对幽暗城发起突袭时，包括达妮萨·莫尔、列奥尼德·巴萨洛缪和加瑞克·班达里恩在内的被遗忘者勇士们团结起来，共同抵御天灾军团的猛攻，在战斗中损失惨重。",al={"幽暗城纳克萨玛斯袭击","幽暗城之战","天灾军团袭击幽暗城"}},{q="被遗忘者能以圣骑士的身份运用圣光吗？",a="虽然引导圣光会给亡灵躯体带来剧痛，且被大多数被遗忘者所排斥，但加瑞克·班达里恩证明了亡灵战士以圣骑士身份运用圣光是可能的，这也是达妮萨和她的同伴继续研究的方向。",al={"被遗忘者可以成为圣骑士吗","亡灵圣骑士背景","运用圣光的被遗忘者"}},{q="列奥尼德·巴萨洛缪之后去了哪里？",a="在拜访朋友并与达妮萨·莫尔交谈后，列奥尼德计划返回东瘟疫之地的圣光之愿礼拜堂，银色黎明在那里协调针对天灾军团的十字军征讨。",al={"列奥尼德去哪了","之后在哪里找到列奥尼德","圣光之愿礼拜堂列奥尼德"}}},fp="17,426,19.353.0,29.416.0,25.311.0,38.251.0,20.220.0,24.225.0,49.261.0,45.270.0,44.201.0"}
P.entries["quest:96897"] = {n="The Cult of the Damned",s="The Cult of the Damned是活跃在提瑞斯法林地内，威胁着天灾军团凡人仆从的一项任务。通过清除黑暗新信徒和黑暗执行者，防御者能够阻止巫妖王那些阴险的活人代理人重演当年摧毁洛丹伦的背叛行径。",h="The Cult of the Damned是活跃在提瑞斯法林地内，威胁着天灾军团凡人仆从的一项任务。通过清除黑暗新信徒和黑暗执行者，防御者能够阻止巫妖王那些阴险的活人代理人重演当年摧毁洛丹伦的背叛行径。",kw={"the cult of the damned","黑暗执行者","黑暗新信徒","活着的仆从","洛丹伦","通灵术","天灾军团","提瑞斯法林地"},ang={["class:Paladin"]="圣骑士曾立誓要铲除摧毁洛丹伦的阴影，这使得致力于天灾军团的活人邪教徒成为了圣光的不共戴天之敌。",["class:Priest"]="所有流派的牧师都认识到The Cult of the Damned所代表的信仰扭曲，这些人用神圣的虔诚换取了黑暗的通灵术。",["race:Undead"]="被遗忘者非常清楚这些活着的邪教徒是如何摧毁洛丹伦并导致他们沦为亡灵的。在提瑞斯法阻止新的邪教组织对于保卫这个新王国至关重要。"},sec={{t="天灾军团的凡人代理人",b="The Cult of the Damned代表了天灾军团的凡人面孔。这些邪教徒由发誓效忠巫妖王的活人男女组成，他们在没有思想的死者无法行动的地方进行活动。在提瑞斯法林地，当地居民本已在应付游荡的亡灵和血色十字军那毫不留情的狂热分子，而新发现的黑暗新信徒和黑暗执行者巢穴则发出了天灾军团试图重新建立立足点的阴险信号。"},{t="陨落的教训",b="洛丹伦的毁灭不仅是因为亡灵军团的进军，更是因为邻里之间的互相背叛。The Cult of the Damned最初渗透进各个村庄，毒害粮仓，并从阴影中策划了王国的崩溃。在提瑞斯法对新的邪教活动保持警惕，对于确保历史不会在这片北方的伤痕之地重演至关重要。"}},faq={{q="什么是The Cult of the Damned？",a="The Cult of the Damned是一个由自愿侍奉巫妖王和天灾军团的凡人组成的组织。这些活着的侍僧并非被复活为无脑的亡灵，而是刻意为了侍奉死亡而散布瘟疫、破坏防御并进行通灵术。",al={"什么是the cult of the damned","谁是邪教徒","谁是黑暗新信徒"}},{q="为什么邪教成员会在提瑞斯法林地活动？",a="提瑞斯法林地仍然是一片充满争议的边境之地，这里不仅有游荡的无脑亡灵、血色十字军的狂热分子，还有幸存的天灾军团残党。邪教在该地区秘密行动，以破坏当地的抵抗力量并推进天灾军团的黑暗计划。",al={"为什么邪教徒在提瑞斯法","提瑞斯法林地的邪教"}},{q="谁是黑暗新信徒和黑暗执行者？",a="黑暗新信徒是刚开始学习黑暗艺术和仪式的初学者，而黑暗执行者则充当守卫邪教行动并维护组织纪律的打手。他们共同在地面上组成了活跃的行动小组。",al={"谁是黑暗执行者","黑暗新信徒的作用"}},{q="为什么说活着的仆从比无脑的亡灵更糟糕？",a="无脑的亡灵仅凭本能或直接命令行动，但活着的邪教徒却是出于完全的清醒而选择了背叛。他们能够融入凡人社会并渗透进定居点的能力，使他们比游荡的食尸鬼或骷髅要阴险得多。",al={"为什么活着的邪教徒更糟","天灾军团的活人仆从"}},{q="任务中所说的“不要让洛丹伦的历史重演”是什么意思？",a="洛丹伦的陨落不仅是因为一场公开的外部入侵，更是因为The Cult of the Damned在内部悄悄毒害了粮食供应，并背叛了自己的同胞。允许邪教徒立足，只会招致同样的灾难。",al={"洛丹伦历史重演","洛丹伦的陷落与邪教"}},{q="该邪教与提瑞斯法的血色十字军有何关系？",a="血色十字军疯狂地猎杀任何受到亡灵天灾污染的事物，这使得天灾军团和该邪教都成为了他们的主要目标。这种持续不断的冲突使当地居民陷入了无脑的恐怖生物、狂热的十字军和隐秘的邪教徒之间。",al={"与血色十字军的关系","邪教与血色十字军"}}},fp="22,276,28.432.0,19.400.0,31.262.0,57.261.0,46.233.0,62.256.0,74.239.0,60.241.0"}
P.entries["quest:96898"] = {n="Remnants of War",s="“战争残余”委托冒险者回收纳克萨玛斯在袭击幽暗城时坠落的亡灵聚焦水晶碎片。被遗忘者和银色黎明在击退这座浮空城时都遭受了惨重的损失，收集这些危险的碎片可以阻止天灾军团的邪教徒利用其中的黑暗魔法。",h="“战争残余”委托冒险者回收纳克萨玛斯在袭击幽暗城时坠落的亡灵聚焦水晶碎片。被遗忘者和银色黎明在击退这座浮空城时都遭受了惨重的损失，收集这些危险的碎片可以阻止天灾军团的邪教徒利用其中的黑暗魔法。",kw={"银色黎明","邪教徒","被遗忘者","纳克萨玛斯","亡灵水晶碎片","remnants of war","天灾军团","提瑞斯法林地","幽暗城"},ang={["class:Mage"]="即便是破碎且大多已耗尽能量，纳克萨玛斯的亡灵聚焦水晶依然保留着不稳定的魔法能量，需要极端谨慎地对待。",["class:Priest"]="亡灵碎片中残留的邪恶腐化代表着一种危险的枯萎病，必须在它进一步玷污这片土地之前将其封存。",["faction:Horde"]="从残留的天灾魔法中保护提瑞斯法林地，有助于守护幽暗城并巩固部落在洛丹伦北部的关键据点。",["race:Undead"]="纳克萨玛斯的袭击威胁到了幽暗城的存亡。回收这些碎片可以保护你的人民免受家门口的天灾死灰复燃的威胁。"},sec={{t="城上阴影",b="不久前，恐怖的浮空城纳克萨玛斯曾笼罩在提瑞斯法林地上空，企图摧毁幽暗城并将被遗忘者彻底抹去。在一场孤注一掷的防御战中，被遗忘者和银色黎明付出了巨大代价才击退了这座浮空要塞。战斗中，纳克萨玛斯顶端巨大的亡灵聚焦水晶被摧毁，碎片散落到下方的林地中。"},{t="散落的死灵术",b="尽管纳克萨玛斯已经被击退，但残留的碎片仍深深嵌入了土地之中。天灾军团的邪教徒们开始行动，试图回收这些亡灵水晶碎片，希望汲取其中残留的黑暗魔法。收集这些碎片能够剥夺天灾军团的原始邪恶力量，尽管要将所有碎片从提瑞斯法林地清理干净，可能需要数年的时间。"}},faq={{q="什么是亡灵水晶碎片？",a="它们是曾经安装在恐怖浮空城纳克萨玛斯顶端的大型亡灵聚焦水晶破碎后的残片。当水晶在针对幽暗城的袭击中被摧毁时，碎片像雨点般落在了提瑞斯法林地上。",al={"什么是亡灵水晶碎片","这些水晶是什么","亡灵水晶"}},{q="纳克萨玛斯为什么要袭击幽暗城？",a="纳克萨玛斯降临提瑞斯法林地，直接目的是毁灭幽暗城并将被遗忘者从地图上彻底抹去。被遗忘者和银色黎明的联合防御成功击退了这座浮空城，但双方阵营都遭受了惨重的损失。",al={"为什么纳克萨玛斯要进攻","纳克萨玛斯袭击幽暗城","纳克萨玛斯在这里做了什么"}},{q="为什么天灾军团的邪教徒要收集这些水晶碎片？",a="天灾军团的邪教徒正在搜寻提瑞斯法林地以回收这些破碎的残片。即使已经破损且耗尽能量，这些水晶中仍然残留着天灾军团可以回收或用于其邪恶仪式的亡灵魔法。",al={"为什么邪教徒想要水晶","邪教徒要残片做什么","天灾军团邪教徒水晶"}},{q="接触这些亡灵水晶危险吗？",a="是的。尽管已经破碎且大部分主要充能已经耗尽，这些碎片仍然蕴含着强大且不稳定的亡灵能量，直接进行身体接触是非常危险的。",al={"水晶接触危险吗","水晶身体接触","亡灵水晶会伤人吗"}},{q="谁帮助被遗忘者击退了纳克萨玛斯？",a="在保卫幽暗城的战斗中，被遗忘者与银色黎明并肩作战，共同对抗纳克萨玛斯的部队，为了确保被遗忘者的生存而付出了沉重的人员伤亡。",al={"谁在纳克萨玛斯之战中作战","谁保卫了幽暗城","银色黎明保卫幽暗城"}},{q="提瑞斯法林地里的亡灵水晶会被清理干净吗？",a="短期内很难清理完毕。因为巨大的水晶是在高空破碎的，碎片散落得到处都是，这意味着当地居民可能在未来几年里都得不断从土地中清理这些残片。",al={"提瑞斯法会清理干净水晶吗","他们能清理所有残片吗","提瑞斯法残留的水晶"}}},fp="15,339,24.390.0,20.338.0,40.233.0,39.249.0,58.217.0,44.176.0,44.194.0,61.228.0"}
P.entries["quest:96899"] = {n="班达里安堡",s="班达里安堡是提瑞斯法林地中的一个任务，指引冒险者前往一处隐秘的要塞会见银色黎明指挥官莱奥尼德·巴萨洛梅。这座堡垒曾是银色黎明对抗天灾军团的集结基地，现在由达尼莎和她的圣骑士教团负责维护。",h="班达里安堡是提瑞斯法林地中的一个任务，指引冒险者前往一处隐秘的要塞会见银色黎明指挥官莱奥尼德·巴萨洛梅。这座堡垒曾是银色黎明对抗天灾军团的集结基地，现在由达尼莎和她的圣骑士教团负责维护。",kw={"银色黎明","班达里安堡","诅咒神教","达尼莎","莱奥尼德·巴萨洛梅","圣骑士","天灾军团","提瑞斯法林地"},ang={["class:Paladin"]="班达里安堡是由达尼莎和她的圣骑士同伴们管理的据点，作为提瑞斯法林地对抗黑暗势力的圣洁堡垒。"},sec={{t="堡垒的召唤",b="班达里安堡是一个银色黎明的任务，指引冒险者穿过提瑞斯法林地去会见指挥官莱奥尼德·巴萨洛梅。在协助银色黎明对抗诅咒神教的活动后，旅行者被指引向西北方前往要塞，与指挥官会合，并进一步了解该组织针对黑暗势力的持续远征。"},{t="历史与管理",b="这座据点曾是银色黎明在提瑞斯法林地对抗天灾军团入侵时的重要集结地。当银色黎明将重心转向东瘟疫之地和西瘟疫之地时，这座堡垒被遗弃，面临着沦为废墟的危险，直到圣骑士达尼莎和她的同伴接管了这里。"},{t="关于一位共同好友的回忆",b="在要塞与莱奥尼德·巴萨洛梅重逢时，这位指挥官回顾了曾经在这里的城墙上进行的战斗。虽然他为这座据点没有被荒废感到欣慰，但他提到，是达尼莎为了纪念一位共同的好友才为其命名。"}},faq={{q="莱奥尼德·巴萨洛梅是谁？",a="莱奥尼德·巴萨洛梅是银色黎明的一位指挥官。在早些时候天灾军团入侵提瑞斯法林地时，他曾将班达里安堡作为基地，现在他已返回此处与达尼莎和她的圣骑士们会面。",al={"莱奥尼德·巴萨洛梅是谁","莱奥尼德·巴萨洛梅在哪里","莱奥尼德 班达里安堡"}},{q="什么是班达里安堡？",a="班达里安堡是一座位于提瑞斯法林地西部的要塞。它最初是银色黎明在天灾军团袭击期间的前哨站，当该组织撤回瘟疫之地后，它曾一度失修，后来被达尼莎的圣骑士们修复并占据。",al={"什么是班达里安堡","班达里安堡历史","谁占据着班达里安堡"}},{q="达尼莎是谁？",a="达尼莎是一位圣骑士，在银色黎明向东撤往瘟疫之地后，她与她的教团接管了班达里安堡的管理工作。她还以一位与莱奥尼德·巴萨洛梅共同的好友的名义，为这座堡垒命名。",al={"达尼莎是谁","达尼莎 圣骑士","谁管理班达里安堡"}},{q="为什么它被称为班达里安堡？",a="这座要塞由达尼莎命名，以纪念她和指挥官莱奥尼德·巴萨洛梅共同的一位好友。",al={"为什么命名为班达里安堡","班达里安是谁","班达里安名字含义"}},{q="银色黎明为什么对班达里安堡感兴趣？",a="银色黎明的成员前往班达里安堡与达尼莎的圣骑士们进行协调，并保持警惕，以对抗提瑞斯法林地各处的天灾军团势力和诅咒神教的活动。",al={"为什么要前往班达里安堡","银色黎明 提瑞斯法林地","班达里安堡 银色黎明"}},{q="银色黎明以前为什么要放弃这座堡垒？",a="当银色黎明将主力部队转移到东方，在瘟疫之地与天灾军团作战时，他们从要塞中撤出，留下了这座空荡荡的建筑，直到达尼莎和她的圣骑士们介入并进行了维护。",al={"战争结束后堡垒发生了什么","银色黎明为什么要离开班达里安堡"}}},fp="14,264,21.335.0,23.351.0,27.268.1,26.218.0,23.246.0,15.226.0,32.113.0,52.192.0,52.215.0"}
P.entries["quest:96988"] = {n="Source of Power",s="Source of Power是幽暗城的一项任务，由马丁·费尔本医生委托，他试图利用达拉然内部的动荡。当这座魔法城市正遭受其自身流氓构装体围攻时，费尔本指派冒险者去获取它们的奥术核心。他的野心是将达拉然的魔法科技与被遗忘者的缝合技术相结合，制造出注入奥术力量的憎恶，从而引起黑暗女王的注意。",h="Source of...",kw={"憎恶","奥术构装体","破碎的哨兵核心","达拉然","马丁·费尔本医生","皇家药剂师学会","source of power","sylvanas windrunner","幽暗城"},ang={["class:Mage"]="法师们会发现达拉然的魔法构装体反戈一击，而它们先进的奥术能源却被掠夺去进行幽暗城的恐怖炼金实验，这真是一种残酷的讽刺。",["faction:Horde"]="在洛丹伦活动的部落冒险者支持被遗忘者从周围的竞争对手那里获取先进军事资产的努力，此时达拉然正因其自身的流氓造物而陷入瘫痪。",["profession:Engineering"]="工程师们可以欣赏达拉然自主哨兵背后复杂的工艺，即使它们脆弱的奥术动力核心被拆除，去供给恐怖的缝合憎恶。",["race:Undead"]="被遗忘者严重依赖皇家药剂师学会冷酷的创新来在洛丹伦求得生存。协助费尔本医生可以推进该派系在黑暗女王监视下对奥术缝合术的研究。"},sec={{t="投机取巧的收割",b="达拉然这座魔法城市内的混乱为被遗忘者创造了一个他们渴望利用的缺口。随着达拉然自身的奥术构装体失控暴走并围攻法师们，马丁·费尔本医生在这场混乱中看到了一个绝佳的机会。这位药剂师没有向被围困的施法者提供援助，而是寻求搜刮那些为这些流氓守卫提供动力的奥术核心。长期以来，达拉然一直严密守护着其魔法研究，但目前的脆弱状态使得其魔法哨兵成为了幽暗城那些机会主义研究者眼中的肥肉。"},{t="皇家药剂师学会的野心",b="费尔本医生对破碎的哨兵核心的兴趣完全源于他在皇家药剂师学会内的个人野心。费尔本梦想着通过向被遗忘者的憎恶中注入不稳定的达拉然构装体魔法，来组建一支具有奥术动力的毁灭性肉体野兽大军。他计算过，这样的恐怖突破将能吸引Sylvanas Windrunner的全部注意力，并展示他无与伦比的炼金天赋。最终，费尔本希望这一发明能大幅提升他的地位，甚至可能确保他获得皇家药剂师学会的领导权，这是一个崇尚冷酷狡诈和强大成果来决定生存与排名的派系。"}},faq={{q="谁发布了Source of Power任务？",a="该任务由马丁·费尔本医生发布，他是一位居住在被遗忘者首都幽暗城的药剂师。费尔本是一位雄心勃勃的研究员，他试图通过开发全新的军事怪兽来向皇家药剂师学会和Sylvanas Windrunner证明自己的炼金才华。",al={"谁发布source of power","source of power任务发布者","马丁·费尔本任务"}},{q="在此任务期间达拉然发生了什么？",a="达拉然目前正遭受其自身奥术构装体的围攻，这些构装体已经反戈一击。魔法城市内部由此产生的混乱和战斗为局外人创造了一个难得的机会，可以潜入达拉然并打捞那些驱动这些流氓守卫的强大魔法组件。",al={"达拉然发生了什么","达拉然被围攻","为什么构装体攻击达拉然"}},{q="费尔本医生为什么想要这些构装体核心？",a="费尔本医生打算利用达拉然哨兵核心内的奥术能量来增强被遗忘者的憎恶。通过将原始的奥术机械与缝合技术相结合，他希望创造出一支奥术驱动的憎恶大军，向Sylvanas Windrunner证明他的炼金术造诣。",al={"为什么要收集哨兵核心","费尔本需要核心做什么","费尔本的哨兵核心计划"}},{q="Source of Power的任务目标是什么？",a="冒险者被指派前往达拉然城，对抗流氓构装体并收集六个破碎的哨兵核心。一旦获得，这些不稳定的魔法遗物必须运回幽暗城交给马丁·费尔本医生，以供给他正在进行的实验。",al={"source of power目标","我需要多少个核心","source of power收集什么"}},{q="费尔本医生在皇家药剂师学会内的目标是什么？",a="马丁·费尔本医生寻求在被遗忘者的等级制度中获得认可和快速晋升。通过向Sylvanas Windrunner展示一支由奥术强化的憎恶组成的强大部队，他希望给这位黑暗女王留下足够深刻的印象，从而被任命为皇家药剂师学会的领导者。",al={"费尔本药剂师的目标","谁领导皇家药剂师学会","费尔本获得黑暗女王认可"}},{q="为什么被遗忘者要搜刮达拉然的技术？",a="皇家药剂师学会和被遗忘者不断寻找非传统的武器和能源，以确保他们在洛丹伦的生存。在达拉然内部防御崩溃时利用这座魔法城市，使被遗忘者的药剂师能够在不与法师正式交战的情况下获得先进的奥术组件。",al={"为什么被遗忘者想要达拉然的魔法","幽暗城达拉然构装体","被遗忘者对达拉然的兴趣"}},{q="在哪里可以找到破碎的哨兵核心？",a="破碎的哨兵核心可以从目前正在围攻达拉然城的流氓构装体身上收集。玩家必须在这座魔法城市中与这些充满敌意的附魔守卫战斗，从而为费尔本医生在幽暗城的研究提取必要的完整组件。",al={"在哪里寻找破碎的哨兵核心","破碎的哨兵核心位置","达拉然哨兵核心掉落"}}},fp="15,407,24.594.0,34.676.0,36.287.0,47.296.0,48.294.0,44.276.0,65.281.0,53.344.0,41.282.0"}
P.entries["quest:97"] = {n="斯塔文的传说",s="调查的这一阶段终于证实了将这位行踪诡秘的导师与夜色镇的记录联系起来的邪恶真相。书记员达尔塔成功地将从寻回文件中发现的笔迹与斯塔文·密斯曼托进行了比对，并立即向指挥官阿尔泰娅·埃伯洛克进行了汇报。这一时刻标志着守夜人的怀疑成为了不可否认的事实。",h="调查的这一阶段终于证实了将这位行踪诡秘的导师与夜色镇的记录联系起来的邪恶真相。书记员达尔塔成功地将从寻回文件中发现的笔迹与斯塔文·密斯曼托进行了比对，并立即向指挥官阿尔泰娅·埃伯洛克进行了汇报。这一时刻标志着守夜人的怀疑...",kw={"althea ebonlocke","书记员达尔塔","夜色镇","暮色森林","笔迹","密斯曼托","守夜人","斯塔文"},ang={["faction:Alliance"]="对于联盟的调查者来说，解开斯塔文的线索证明了夜色镇饱受打击的领导层与四处游历的冒险者之间必须进行必要的合作，才能确保王国南部领土的安全。",["race:Human"]="人类玩家在这里看到了自身社会悲剧性的衰落，受人尊敬的导师和乡村城镇一样，悄无声息地从文明滑向了疯狂与孤立。"},sec={{t="记录比对",b="在搜遍了人类王国各地的遥远庄园、旅店和市政档案后，破碎的线索回到了夜色镇的市政厅。书记员达尔塔将染血的日记页面与城镇登记册上的签名进行了比对。结果是不言而喻的：笔迹属于斯塔文·密斯曼托，这为守夜人提供了将此事视为紧急地方威胁所需的铁证。"},{t="守夜人的怀疑",b="从调查一开始，指挥官阿尔泰娅·埃伯洛克就对斯塔文有着不祥的预感。暮色森林本已在狂暴的狼人、骷髅亡灵和潜伏的通灵师的重压下不堪重负；一个隐藏在森林阴影中、下落不明的凶手是她无法忽视的危险。收到达尔塔的确认验证了她最深层的恐惧，也让守夜人开始着手定位并彻底铲除这个隐居者。"}},faq={{q="书记员达尔塔发现了什么？",a="书记员达尔塔将染血的日记页面与夜色镇城镇登记册上的签名进行了比对，并确认笔迹与斯塔文·密斯曼托完全吻合，正如指挥官埃伯洛克所怀疑的那样。",al={"达尔塔发现了什么","达尔塔笔迹比对","斯塔文笔迹证据"}},{q="为什么指挥官阿尔泰娅·埃伯洛克如此在意斯塔文？",a="指挥官阿尔泰娅·埃伯洛克领导着夜色镇那支饱受困扰的民兵组织——守夜人。在这片本已深受恐怖威胁的土地上，她不能容忍一个有着黑暗过去的暴力阴影人物在暮色森林境内逍遥法外且下落不明。",al={"为什么阿尔泰娅要在意","埃伯洛克调查","守夜人斯塔文"}},{q="这一步发生在什么地方？",a="这一步全部发生在夜色镇内。书记员达尔塔驻守在市政厅内，而指挥官阿尔泰娅·埃伯洛克则可以在镇中心道路附近巡逻时找到。",al={"这个任务在哪里","任务地点","夜色镇斯塔文交任务"}},{q="上报笔迹比对结果后会发生什么？",a="一旦指挥官埃伯洛克收到书记员达尔塔的确认，调查重点就会转向在暮色森林闹鬼的荒野中积极搜寻斯塔文目前的下落。",al={"斯塔文下一步","达尔塔比对之后","斯塔文系列任务下一步"}},{q="斯塔文·密斯曼托原本是谁？",a="斯塔文·密斯曼托曾经在Moonbrook Schoolhouse任教，后来担任弗林特里奇家族孩子的私人导师。他留下的书信和日记页的线索从月溪镇和闪金镇一路延伸回暮色森林，如今他作为一名危险的隐居者生活在森林里。",al={"斯塔文是谁","斯塔文背景","斯塔文·密斯曼托的故事"}},{q="为什么需要进行笔迹分析？",a="由于围绕斯塔文发生的事件和指控发生在不同的地区——包括月溪镇和闪金镇——官方记录并不连贯。夜色镇的市政登记册保存了经过验证的本地样本，可以明确地将外来的线索与此人联系起来。",al={"为什么要比对笔迹","为什么达尔塔要检查笔迹","证明斯塔文身份"}}},fx={cc1b58e5={q="书记员达尔塔为什么急着让你向指挥官伊博克洛克汇报？",a="书记员达尔塔是镇上的档案管理员，并非守夜人组织的军官。确认字迹出自斯塔尔文·米斯特曼特，便能证实指挥官伊博克洛克的严重怀疑。达尔塔明白，正式的谋杀调查需要立即交由武装力量处理，因此必须尽快让阿尔西亚拿到确凿证据。",al={"达尔塔为什么要你这么做","达尔塔的动机","为什么向阿尔西亚汇报"}}},fp="21,363,22.413.0,28.456.1,31.220.0,63.241.0,32.202.0,51.186.0,38.289.0,39.282.0"}
P.entries["quest:970"] = {n="奥萨拉克斯之塔",s="这个任务标志着对邪恶的暗滩教派调查工作中的一个关键转折点，将追查目标从黑海岸的奥萨拉克斯之塔转移到了边界另一侧的灰谷迈斯特拉岗哨。净化者德尔格伦派遣冒险者前往附近的教派营地，以夺取一颗强力的发光的灵魂宝石。解开这个神器的秘密将揭示这股正在腐蚀北部森林的教派力量背后所隐藏的邪恶巫术。",h="这个任务标志着对邪恶的暗滩教派调查工作中的一个关键转折点，将追查目标从黑海岸的奥萨拉克斯之塔转移到了边界另一侧的灰谷迈斯特拉岗哨。净化者德尔格伦派遣冒险者前往附近的教派营地，以夺取一颗强力的发光的灵魂宝石。解开这个神器的...",kw={"奥萨拉克斯之塔","灰谷","暗滩教派","黑海岸","德尔格伦","净化者德尔格伦","发光的灵魂宝石","迈斯特拉岗哨","奥迪拉兰"},ang={["class:Paladin"]="净化黑暗灵魂容器并处决堕落的教派成员，这与圣骑士肃清世间邪恶腐化的职责不谋而合。",["class:Priest"]="检查黑暗灵魂容器与牧师对抗腐化并安抚痛苦灵魂的使命产生了共鸣。",["faction:Alliance"]="协调黑海岸和灰谷的前哨站工作，能巩固北部防线，抵御威胁联盟旅行者的黑暗施法者。",["race:NightElf"]="眼见邪恶教派成员玷污奥迪拉兰等古代废墟并腐蚀北部森林，肃清暗滩教派成为了任何暗夜精灵的当务之急。"},sec={{t="越过边境的请求",b="在揭露了黑暗海岸北部奥萨拉克斯之塔周围的阴险活动后，报告显示这些线索直指灰谷南部的净化者德尔格伦。德尔格伦驻扎在迈斯特拉岗哨，长期以来一直致力于对抗那些侵蚀古代精灵森林的暗滩教派。意识到教派的威胁横跨了这两个地区，德尔格伦决心从源头打击他们的邪恶巫术。"},{t="奥迪拉兰的秘密",b="迈斯特拉岗哨的东北方坐落着奥迪拉兰废墟，如今已被狂热的暗滩教派成员所占据。德尔格伦发现他们的成员身上携带着发光的灵魂宝石——这些注入了邪恶魔法的黑暗容器维持着教派的力量。通过在废墟中猎杀这些教派成员并夺回其中一颗宝石，德尔格伦打算打破上面的咒语，揭露他们邪恶仪式背后的真正来源。"},{t="被困的灵魂",b="在破译了束缚在发光的灵魂宝石上的邪恶符文后，德尔格伦不仅发现了黑暗咒语，还揭开了一个痛苦的牢笼。打破宝石上的结界释放了萨格斯的灵魂，他是亚米萨兰的精灵之一，在大分裂期间被阿斯瑞库斯·纳拉辛囚禁在灵魂宝石中并一直被缓慢汲取能量。这个灵魂提到了阿斯瑞库斯的副官伊尔库德·玛格苏尔，他的典籍或许能揭示剩余的灵魂宝石被藏在哪里。"}},faq={{q="我在哪里可以找到发光的灵魂宝石？",a="发光的灵魂宝石由位于灰谷迈斯特拉岗哨东北方奥迪拉兰废墟的暗滩教派成员持有。潜伏在废墟中的各类教派成员都有可能携带此物，不过你可能需要多尝试几次才能获得。",al={"灵魂宝石位置","灵魂宝石掉落地点","暗滩教派灵魂宝石"}},{q="净化者德尔格伦是谁？",a="净化者德尔格伦是一位驻扎在灰谷北部的联盟勇士。他积极对抗侵入森林的邪恶势力，尤其专注于追捕并消灭暗滩教派。",al={"德尔格伦","德尔格伦是谁"}},{q="什么是暗滩教派？",a="暗滩教派是一个从黑海岸的奥萨拉克斯之塔以及灰谷的奥迪拉兰等古代精灵废墟中运作的邪恶组织。他们从事黑暗巫术、灵魂绑定和死灵仪式。",al={"暗滩教派","暗滩教派成员"}},{q="为什么黑海岸的任务要让我去灰谷？",a="虽然调查是从黑海岸的奥萨拉克斯之塔开始的，但该教派的网络延伸到了南部的灰谷边境。位于迈斯特拉岗哨的净化者德尔格伦拥有对抗该教派灵魂绑定魔法所需的专业知识。",al={"为什么去迈斯特拉岗哨","为什么去灰谷"}},{q="当灵魂宝石被破译后会发生什么？",a="德尔格伦打算破译发光的灵魂宝石上的黑暗咒语。你将他带回宝石后，便能揭晓他发现了什么。",al={"灵魂宝石里有什么","灵魂宝石幽灵"}},{q="奥迪拉兰在哪里？",a="奥迪拉兰是一处古代精灵废墟，位于灰谷北部迈斯特拉岗哨的东北方，目前已被暗滩教派侵占。",al={"奥迪拉兰位置","奥迪拉兰在哪里"}}},fx={a63b3648={q="净化者德尔格伦为什么想让你这么做？",a="德尔格伦一直在与黑海岸邪教徒交战，他们已在迈斯特拉岗哨东北方盘踞下来。在他看来，这些人是必须彻底铲除的危险祸患。巴苏尔·影击信中发出的严厉警告证实，他们的腐化影响正在加剧。德尔格伦认为，揭开邪教徒魔法灵魂宝石中的秘密，是暴露并瓦解他们势力的唯一办法。",al={"德尔格伦的动机","德尔格伦为什么想要灵魂宝石","为什么要对抗黑海岸邪教徒"}},c112c454={q="发光的灵魂宝石有什么用？",a="发光的灵魂宝石是黑海岸邪教徒在奥迪尔兰携带的一件黑暗魔法神器。德尔格伦认为，宝石中藏着邪教徒邪恶魔法的秘密以及他们所掌握的力量。把宝石带给他，他就能解读石头上编织的黑暗魔法，并查明其中囚禁着什么精华或实体。",al={"发光的灵魂宝石是什么","发光的灵魂宝石有什么用","黑海岸邪教徒的灵魂宝石"}},d0742ede={q="你被派去对付奥迪拉兰的什么人？",a="你受命对付盘踞在奥迪拉兰废墟的黑海岸教派。废墟位于迈斯特拉岗哨东北方。邪教徒、狂热者、侍僧和熟练施法者聚集在精灵遗迹中，举行禁忌仪式。他们中有一人携带着一块附魔灵魂宝石，净化者德尔格伦需要它来揭开教派的秘密。你必须一路杀入敌阵，直到找回这件圣物。",al={"奥迪拉兰有什么人","奥迪拉兰的黑海岸教派","谁拿着灵魂宝石"}}},fp="22,428,24.417.0,25.426.0,16.471.1,37.251.0,28.239.0,36.222.0,49.245.0,45.132.1,28.151.0"}
P.entries["quest:97003"] = {n="Chol'aruk the Ravener",s="Chol'aruk the Ravener 是贫瘠之地的一项狩猎任务，目标是一头据传栖息在荆棘岭洞穴中的巨型野猪人。兽人 Gur'ak 在遭遇过类似的野兽后，对此类传言深信不疑，于是委托冒险者前往其巢穴并带回它的头颅。",h="Chol'aruk the Ravener 是贫瘠之地的一项狩猎任务，目标是一头据传栖息在荆棘岭洞穴中的巨型野猪人。兽人 Gur'ak 在遭遇过类似的野兽后，对此类传言深信不疑，于是委托冒险者前往其巢穴并带回它的头颅。",kw={"贫瘠之地","chol'aruk","cholaruk","gur'ak","gurak","野猪人","razormane","吞噬者","荆棘岭"},ang={["class:Hunter"]="追踪一只据传比普通野猪人大五倍的怪物，需要猎人敏锐的直觉和针对强大猎物的准备。",["class:Warrior"]="面对一只以贪得无厌的嗜血本性而闻名的残暴生物，需要前线战士做好准备，以应对其压倒性的物理狂暴。",["faction:Horde"]="兽人 Gur'ak 以部落传统的战斗口号“鲜血与雷鸣”发出了这一集结号召，委托冒险者去消灭潜伏在贫瘠之地的一个危险威胁。"},sec={{t="关于吞噬者的传说",b="在贫瘠之地的荒原上，Razormane 野猪人部落中流传着关于 Chol'aruk 的低语，这头巨兽被称为“吞噬者”。据当地的流言称，这头噩梦般的野兽栖息在荆棘岭东北部的一处深洞中。野猪人声称它大约是普通野猪人大小的五倍，内心充满了暴力和对鲜血永不满足的渴望。虽然许多人将这些故事斥为夸大的篝火传说，但 Gur'ak 因为过去与类似怪物的战斗经历，对此有更清醒的认识。"},{t="Gur'ak 的警告",b="意识到这种体型的野兽带来的真正威胁，Gur'ak 指引有能力的旅者追踪这只生物，前往它在荆棘岭的地下巢穴。他的指示很直接：除掉这头怪兽，并带回它的头颅作为无可辩驳的证据。鉴于 Chol'aruk 传闻中的凶猛和巨大的体型，Gur'ak 严厉告诫，只有准备充分的小队才应冒险进入洞穴去对抗这只“吞噬者”。"}},faq={{q="Chol'aruk the Ravener 是谁？",a="Chol'aruk，也就是 Razormane 部落所称的“吞噬者”，是一头传奇且凶猛的野猪人。传闻它的体型是普通野猪人的五倍，有着无法满足的嗜血欲望，栖息在贫瘠之地的一处深洞中。",al={"谁是 cholaruk","cholaruk 是什么","吞噬者"}},{q="在哪里可以找到 Chol'aruk？",a="Chol'aruk 栖息在荆棘岭的一处深洞中，位于贫瘠之地 Gur'ak 营地的东北方。冒险者必须深入荆棘岭的洞穴才能找到它的巢穴。",al={"cholaruk 在哪","cholaruk 位置","荆棘岭洞穴在哪里"}},{q="谁提供了针对 Chol'aruk 的狩猎任务？",a="驻扎在贫瘠之地的兽人 Gur'ak 提供了这项任务。与其他将关于这只巨兽的故事视为酒馆闲谈的人不同，Gur'ak 因为曾面对过类似的怪物，所以相信这些传言。",al={"谁提供 cholaruk 任务","谁是 gurak","gurak 贫瘠之地"}},{q="为什么 Gur'ak 要狩猎 Chol'aruk？",a="Gur'ak 希望消灭 Chol'aruk，以消除恐吓该地区的野蛮威胁，并要求带回这头野兽被砍下的头颅，作为“吞噬者”已被击败的证据。",al={"为什么要杀死 cholaruk","cholaruk 悬赏原因"}},{q="我可以独自挑战 Chol'aruk 吗？",a="Gur'ak 明确警告旅行者不要独自寻找 Chol'aruk。鉴于其巨大的体型和凶猛的嗜血本性，击败“吞噬者”是一项艰巨的挑战，需要组织一支准备充分的狩猎小队。",al={"我可以单挑 cholaruk 吗","cholaruk 很难吗","带队打 cholaruk"}},{q="Chol'aruk 与 Razormane 野猪人之间有什么联系？",a="野猪人是卡利姆多中部平原上的一种类人生物，Razormane 部落居住在贫瘠之地的部分地区。Razormane 人在谈论 Chol'aruk 时充满了恐惧，并给予了它“吞噬者”的称号。",al={"什么是野猪人","razormane cholaruk","为什么 razormane 害怕他"}}},fp="21,271,25.527.0,16.438.0,29.242.0,29.177.0,34.209.0,32.159.0,31.222.0,68.230.0"}
P.entries["quest:97005"] = {n="Chol'aruk the Ravener",s="Chol'aruk the Ravener 是一头令人胆寒的巨大畸变怪，潜伏在贫瘠之地荆棘岭的一处洞穴中。当地的钢鬃野猪人称它为 Chol'aruk，或者“掠食者”。有传言说这头怪兽体型巨大，能将一名兽人整个吞下。Bainham 想要得到它的头颅，以祭奠那些在类似恐怖灾难中丧生的战友。",h="Chol'aruk the Ravener 是一头令人胆寒的巨大畸变怪，潜伏在贫瘠之地荆棘岭的一处洞穴中。当地的钢鬃野猪人称它为...",kw={"畸变怪","bainham","贫瘠之地","chol'aruk","钢鬃","掠食者","荆棘岭"},ang={["class:Hunter"]="面对一头传说中能将全身披甲的战士一口吞下的顶级掠食者，是对追踪者实力与胆识的终极考验。",["class:Warrior"]="Bainham 的恳求直接诉诸了战士的信条：通过在地下巢穴中与庞然大物正面交锋，来为牺牲的战友复仇。",["faction:Horde"]="在高地上肆意游荡的怪物威胁着穿行于贫瘠之地的旅行者和商队，因此铲除这头野兽已成为关乎地区安全的问题。"},sec={{t="荆棘岭的恐怖",b="在贫瘠之地，Bainham 等候之处的西北方坐落着被称为荆棘岭的高原，这里长期以来一直是被当地的钢鬃部族所争夺的领地。最近，有流言悄悄传出，在那里的某个洞穴中盘踞着一个可怕的存在：一头被钢鬃野猪人称为 Chol'aruk，或称“掠食者”的巨大畸变怪。尽管许多旅行者将这头能一口吞下全身披甲的兽人的怪兽传说视为篝火边的奇谈怪论，但那些亲眼目睹了血腥场面的人知道，这种威胁是千真万确的。"},{t="了结夙愿",b="对于 Bainham 来说，Chol'aruk 的存在绝非神话。他过去曾与类似的恐怖生物交过手，身上留下了个人的伤疤，也为倒在这些野兽蹄下的战友感到哀伤。深知这种贪婪的畸变怪对所有漫游在草原上的人构成的危险，他委托经验丰富的勇士登上高原，突入其地下巢穴，击杀 Chol'aruk 并取回它巨大的头颅。"}},faq={{q="Chol'aruk 是一种什么样的生物？",a="Chol'aruk 被描述为潜伏在荆棘岭一处洞穴中的巨大畸变怪。据传它体型极其庞大，能够将一名成年兽人整个吞下，这使得它在当地的钢鬃野猪人中获得了“掠食者”这一恐怖称号。",al={"什么是 cholaruk","cholaruk 怪物类型","谁是掠食者"}},{q="Chol'aruk 的巢穴在哪里？",a="Chol'aruk 的巢穴位于贫瘠之地西北方荆棘岭高地上的一个洞穴内。",al={"cholaruk 在哪里","cholaruk 位置","荆棘岭洞穴"}},{q="Bainham 是谁？为什么要杀死 Chol'aruk？",a="Bainham 身处贫瘠之地，有着与此类野兽作战的个人经历。他过去曾有盟友死于类似的畸变怪之手，因此出于荣誉感和为牺牲战友复仇的念头，他寻求终结 Chol'aruk 的生命。",al={"谁给予 cholaruk 任务","为什么要杀 cholaruk","bainham 传说"}},{q="“掠食者”是什么意思？",a="当地的钢鬃野猪人以此为名来形容 Chol'aruk 那贪得无厌、暴食成性的本性，因为有传言称它毫不犹豫地将身披重甲的战士整个吞食。",al={"cholaruk 的含义","为什么叫掠食者","钢鬃 cholaruk"}},{q="钢鬃野猪人是崇拜还是恐惧 Chol'aruk？",a="目前尚不得而知。钢鬃野猪人称这头生物为 Chol'aruk 或“掠食者”，但任务描述中并未说明他们究竟是恐惧还是崇拜这头盘踞在荆棘岭洞穴中的巨大畸变怪。",al={"野猪人喜欢 cholaruk 吗","钢鬃与 cholaruk"}},{q="需要什么证据来确认 Chol'aruk 已死？",a="Bainham 要求你带回 Chol'aruk 的头颅，作为这头畸变怪已被铲除的无可辩驳的证明。",al={"cholaruk 任务交付","我要带什么给 bainham"}}},fp="21,309,20.512.0,15.379.0,35.232.0,34.114.0,51.209.0,29.172.0,52.195.0,52.125.0"}
P.entries["quest:971"] = {n="深渊中的知识",s="“深渊中的知识”是联盟的一项任务，由铁炉堡Forlorn Cavern的葛利·硬骨提供。他指派冒险者横跨海洋，前往灰谷的黑暗深渊沉没遗迹，寻回古老的洛迦里斯手稿。在硬骨那学者外表的伪装下，隐藏着一个与黑暗实体及末日预言相关的险恶计划。",h="“深渊中的知识”是联盟的一项任务，由铁炉堡Forlorn...",kw={"灰谷","黑暗深渊","forlorn cavern","葛利·硬骨","铁炉堡","深渊中的知识","洛迦里斯手稿"},ang={["class:Warlock"]="硬骨就在铁炉堡Forlorn Cavern中潜藏的术士们旁边活动，分享着他们对扭曲位面的禁忌书籍的渴望。",["faction:Alliance"]="尽管帮助一名联盟学者看起来人畜无害，但硬骨的真实动机及其背后的黑暗同伙暗示了铁炉堡城墙内正在进行更阴险的勾当。",["race:NightElf"]="书稿位于黑暗深渊中，那是一处被淹没的暗夜精灵圣所，现在被邪教徒和其他入侵者占据。"},sec={{t="阴影中的学者",b="葛利·硬骨潜藏在铁炉堡潮湿的Forlorn Cavern深处，伪装成一位致力于收集古籍的学者。然而，他的学术追求却带有明显的邪恶意味。硬骨对世俗的历史或城市编年史毫无兴趣；他明确地在寻找那些能够开启门户并唤醒“沉睡者”的遗忘知识。他谈论着在“末日”之后生存的话题，这让他显得不仅是个怪人，更像是一个危险的、崇拜黑暗与沉睡力量的信徒。"},{t="洛迦里斯的沉没遗迹",b="硬骨指示寻求者穿越整个艾泽拉斯，前往灰谷阴影笼罩的海岸，那里沉没着古老的暗夜精灵圣所——黑暗深渊。在大分裂将卡利姆多撕裂之前，暗夜精灵学者曾在这些沿海神庙中汇聚了极其庞大的魔法知识。如今，在布满娜迦、萨特和暮光之锤邪教徒的被淹没的走廊中，安放着洛迦里斯手稿——一本存放在凹陷的铁皮箱里的禁忌知识之书。"},{t="兄弟姐妹",b="当把浸水的书稿交给他时，硬骨并没有打算将其归档到铁炉堡的Hall of Explorers。相反，他公开欢呼这些书稿将被复制并分发给他那些神秘的“兄弟姐妹”。虽然他感谢取回书稿的联盟冒险者，但硬骨显然忠于一个秘密教派，该教派渴望利用这些寻回的知识进行改变世界的秘术仪式。硬骨与暮光之锤有关联，该组织的成员一直在搜寻关于古神的禁忌知识。"}},faq={{q="谁给予了“深渊中的知识”任务？",a="该任务由葛利·硬骨给予，他是一位矮人寻古者，居住在矮人山城铁炉堡内光线昏暗的Forlorn Cavern中。",al={"任务给予者","哪里接任务","谁开启深渊中的知识"}},{q="什么是洛迦里斯手稿？",a="洛迦里斯手稿是葛利·硬骨想要从黑暗深渊中找回的文献。它被存放在被淹没的废墟中一个凹陷的铁皮箱里。",al={"什么是洛迦里斯手稿","洛迦里斯传说","我能找到什么书"}},{q="洛迦里斯手稿在哪里？",a="该手稿位于黑暗深渊地下城深处，该地下城坐落在卡利姆多灰谷西北海岸的佐拉姆海岸旁。",al={"洛迦里斯手稿位置","黑暗深渊里的书在哪里","黑暗深渊书籍位置"}},{q="葛利·硬骨提到的“沉睡者”是谁？",a="硬骨用这个神秘的名字来称呼他在收集的禁忌知识中所描述的那些沉睡的力量。任务的受保护部分探索了他与黑暗势力的联系。",al={"沉睡者","硬骨在谈论谁","葛利崇拜什么"}},{q="葛利计划与谁分享这些书稿的“兄弟姐妹”是谁？",a="硬骨的同伙与他有着同样的对禁忌知识的兴趣。找回书稿可以揭示更多关于他效忠对象的信息。",al={"葛利的兄弟姐妹","葛利在为谁工作","硬骨阵营"}},{q="为什么在铁炉堡的任务会把玩家派到灰谷那么远的地方？",a="铁炉堡的Forlorn Cavern吸引了那些寻求隐秘知识的非正统施法者、术士和潜行者。硬骨收集古老且强大的知识，而他想要的洛迦里斯手稿据传就在灰谷黑暗深渊的底部，那里曾是早已消亡、掌握着巨大知识的精灵们的居所。",al={"为什么要前往灰谷","铁炉堡到黑暗深渊的任务","前往黑暗深渊"}}},fx={["32faf93b"]={q="葛利·硬骨为什么想要洛迦里斯手稿？",a="葛利·硬骨收集古老而强大的典籍，这些典籍能够开启被遗忘的门扉，唤醒沉睡者。他相信洛迦里斯手稿记载着黑暗深渊古代暗夜精灵失传已久的秘密，并打算在末日来临前抄录这份黑暗知识，分发给他那些行事隐秘的兄弟姐妹。",al={"葛利·硬骨的动机","葛利为什么要手稿","葛利·硬骨的任务缘由"}}},fp="22,354,24.495.0,27.469.0,20.538.1,43.154.0,32.148.0,41.146.0,55.165.0,77.123.1,68.325.0"}
P.entries["quest:972"] = {n="水之灵契",s="Water Sapta是水之先知伊斯伦交给贫瘠之地沿岸的年轻部落萨满祭司的一项过渡性任务。在炼金药剂的加持下，萨满祭司将被派遣横跨无尽之海，前往银松森林那片被腐蚀的土地，去面对一口被污染的泉水。",h="Water Sapta是水之先知伊斯伦交给贫瘠之地沿岸的年轻部落萨满祭司的一项过渡性任务。在炼金药剂的加持下，萨满祭司将被派遣横跨无尽之海，前往银松森林那片被腐蚀的土地，去面对一口被污染的泉水。",kw={"call of water","水之先知伊斯伦","萨满试炼","银松森林","贫瘠之地","图腾任务","water sapta"},ang={["class:Shaman"]="Water Sapta标志着你元素试炼中的一个关键转折点，它开启了你对灵魂世界的视野，随后你才能获得掌控Water Totem的治疗能力。",["faction:Horde"]="这项试炼展示了新部落横跨大陆的团结精神，将新兵从阳光炙烤的卡利姆多平原送往洛丹伦那阴森诡谲的树林中。"},sec={{t="水的幻象",b="在部落萨满的元素传统中，sapta是一种炼金药剂，可以使人的感官直接与世界的灵魂调和。当普通人的眼睛只能看到平静的溪流或停滞的池塘时，喝下这种sapta就能穿透物理层面的面纱，揭示出隐藏在水流中的元素生物。"},{t="通往银松森林之路",b="在证明了自己对灵魂的奉献之后，萨满祭司可以直接从水之先知伊斯伦那里获得这种药剂，伊斯伦是一位居住在棘齿城以南荒凉海岸上的隐士。伊斯伦并没有让新兵在卡利姆多的干旱山谷中测试这种sapta，而是命令他们横跨无尽之海，长途跋涉来到银松森林那阴暗且被遗弃的树林，去对抗正在毒害洛丹伦溪流的元素腐蚀。"}},faq={{q="什么是水之sapta？",a="Sapta是一种由萨满导师准备的仪式药剂。饮用后，它会增强精神感知力，使饮用者能够直接看到并与那些在凡人眼中不可见的元素灵魂进行交流。",al={"什么是sapta","water sapta的含义","sapta有什么作用"}},{q="水之先知伊斯伦是谁？",a="水之先知伊斯伦是一位萨满大师，居住在商旅海岸以南、贫瘠之地东海岸的僻静处进行沉思。她引导年轻的部落萨满踏上艰苦的旅程，与水元素沟通并驾驭它们。",al={"水之先知伊斯伦背景故事","伊斯伦是谁"}},{q="萨满祭司为什么要前往银松森林？",a="银松森林的水元素灵魂正遭受着广泛的折磨。为了完成他们的试炼，萨满祭司必须带着sapta横跨海洋，亲眼观察被腐蚀的水源并净化那里的污秽。",al={"为什么要前往银松森林","为什么要前往东部王国"}},{q="喝下sapta后会发生什么？",a="饮用Water Sapta可以让萨满祭司亲眼目睹潜伏在银松森林受污染水池中的受腐蚀水元素，从而开启对抗腐化源头的道路。",al={"饮用sapta","sapta的效果"}},{q="所有的部落萨满都需要进行这次试炼吗？",a="是的。无论是兽人、牛头人还是巨魔萨满，都必须响应Call of Water，将这种sapta作为获得Water Totem之前必不可少的成人礼。",al={"谁会接到这个任务","这是职业任务吗"}},{q="银松森林里的腐蚀水池在哪里？",a="受腐蚀的泉水位于银松森林的海岸边，瑟伯切尔的西侧。",al={"银松森林水池位置","水源在哪里"}}},fx={c8d11240={q="水之先知伊斯伦为什么派你去银松森林？",a="水之先知伊斯伦希望引导你完成精神上的成年礼，帮助你与水元素的力量建立联系。若要与水之精灵沟通并完成Call of Water，你必须面对并净化污染世界水域的污秽。她已将准备好的Water Sapta交给你，让你亲眼感知隐藏的元素腐化，并证明你作为一名新晋萨满的虔诚。",al={"伊斯伦为什么要完成这件事","水之先知伊斯伦的动机","为什么要净化受腐化的水"}}},fp="11,256,17.335.0,22.426.0,22.231.0,23.239.0,48.240.0,38.177.0,44.162.0,50.86.0"}
P.entries["quest:97220"] = {n="Philmor's Favor",s="Philmor's Favor是暴风城内的一项运送任务，起因是当地码头工人持续短缺。信使需要将一批易碎的Gatehouse货物运送到位于Trade District的Trias' Cheese店二楼的一个隐蔽仓库入口。",h="Philmor's Favor是暴风城内的一项运送任务，起因是当地码头工人持续短缺。信使需要将一批易碎的Gatehouse货物运送到位于Trade District的Trias' Cheese店二楼的一个隐蔽仓库入口。",kw={"elaine","gatehouse","gatehouse货物","philmor","philmor's favor","暴风城","trade district","trias' cheese"},ang={["faction:Alliance"]="协助完成暴风城Trade District各处的运送任务，可以在码头工人短缺的情况下保持城市物流平稳运行。"},sec={{t="暴风城内紧张的物流状况",b="暴风城各地的码头工人持续短缺，导致城市的日常货运业务吃紧。为了不让当地的货物进度落后，搬运工们一直在寻找可靠的过路人，愿意将敏感的板条箱直接运进商业区。"},{t="在Trias' Cheese的秘密投递",b="这批货物是标记给Gatehouse的，但其投递方式却一点也不寻常。货物不是通过正规的卫兵岗哨入口，而是被搬运到位于Trade District的Trias' Cheese店二楼。这家店隐藏着一个仓库入口，用于悄悄地搬运供给品和送给守卫军官的礼品，以免被他人窥见。"}},faq={{q="谁需要这项运送任务的帮助？",a="这项任务旨在缓解暴风城周围的货物运输压力，此时当地的码头人手不足。",al={"谁发布了philmor's favor","philmor任务发布者"}},{q="送货目的地在哪里？",a="这批货物必须送到Gatehouse的仓库入口，该入口可以通过暴风城Trade District的Trias' Cheese店二楼进入。",al={"我该把包裹送到哪里","trias' cheese运送","gatehouse入口在哪里"}},{q="谁负责接收货物？",a="Elaine是Trias' Cheese店的女主人，她习惯处理运往毗邻的Gatehouse仓库的机密货物。",al={"谁是elaine","trias' cheese的elaine"}},{q="Gatehouse的货物里装的是什么？",a="这批货物包含运往Gatehouse的易碎物品。据当地搬运工称，为了方便安排给守卫军官的仪式性惊喜，货物通常需要特别谨慎地送达。",al={"包裹里有什么","gatehouse运送内容"}},{q="为什么可以通过奶酪店进入军事仓库？",a="Trias' Cheese店的楼上有一个通往Gatehouse仓库的入口，允许在不经过主军事入口招摇过市的情况下，进行机密的通行和货物卸载。",al={"为什么通过trias' cheese进入gatehouse","trias' cheese的秘密入口"}},{q="为什么码头工人会短缺？",a="由于全周人员短缺，码头和货物搬运工手头紧缺，迫使物流协调员不得不依靠路过的旅行者来保证运送进度。",al={"为什么码头工人短缺","暴风城码头工人短缺"}}},fp="15,268,31.262.0,36.382.0,34.118.0,34.167.0,26.147.0,38.202.0,59.193.0,34.182.0"}
P.entries["quest:97222"] = {n="Gatehouse Goods",s="Gatehouse Goods是一项暴风城的本地任务，要求将一批货物运送到Trias' Cheese店内的楼梯上方。由于这家奶酪店与相邻的城门卫所共用一个楼层，货物可以安静地放置在储藏室门外，供卫兵回收。这一安排突显了暴风城商业区与防御区紧凑、互通的城市设计。",h="Gatehouse Goods是一项暴风城的本地任务，要求将一批货物运送到Trias'...",kw={"送货","埃林·提亚斯","gatehouse goods","卫所货物","储藏室","暴风城","trias cheese"},ang={["class:Rogue"]="对于那些重视谨慎行事的人来说，在Trias' Cheese周围安静地操作并注意向内开启的门等建筑细节是第二天性。",["faction:Alliance"]="通过Trias' Cheese协助安排谨慎的送货，可以保持暴风城当地店主与邻近卫所人员之间的物资顺畅流通。"},sec={{t="共用的区域与楼层",b="Gatehouse Goods是一项简单的运送任务，地点位于繁忙的暴风城街道内。该工作要求将城门卫所的货物搬运到Trias' Cheese的内部楼梯上方。虽然这家著名的奶酪店是一家完全独立的生意，拥有自己的库存，但其实体建筑与邻近的卫所设施共用一个楼层。这种建筑布局上的巧合使得该店的上方平台成为在相邻区域之间运输物资的便利通道，且不会干扰到正面的街道。"},{t="便利的卸货点",b="运送流程非常明确：信使必须将板条箱直接放在储藏室门外，而不是搬进里面。常规的卫所守卫会留意到货物的送达，并指派人员在返回岗位时顺便将其取回。此外，储藏室的门特意设计为向内开启的合页，确保堆放在外面的货物永远不会堵塞入口，也不会妨碍里面的人员自由通行。"}},faq={{q="什么是Gatehouse Goods？",a="Gatehouse Goods是暴风城的一项本地送货差事，涉及Trias' Cheese和邻近的卫所。信使需要将货物搬上楼梯，并将其放在卫所储藏室门外。",al={"什么是gatehouse goods","gatehouse goods任务"}},{q="货物应该送到哪里？",a="货物需要送到Trias' Cheese店内的楼梯上方。虽然Trias' Cheese是一家独立的企业，但它的建筑与卫所共用一个楼层，允许直接将货物卸在储藏室门外。",al={"trias cheese卫所","货物送到哪里"}},{q="为什么板条箱要留在门外，而不是搬进里面？",a="接收方特别指示信使将板条箱留在储藏室门外，而不是搬进去。卫所的守卫会注意到货物的送达，并在返回岗位时派人顺便将其搬进去。",al={"为什么不搬进里面","谁来取走箱子"}},{q="为什么储藏室的门要向内开启？",a="储藏室的门合页设计为向内开启，主要是为了防止放置在门外的包裹和货物堵塞门口或将里面的人困住。",al={"trias内部开门","储藏室门合页"}},{q="Trias' Cheese与卫所有关联吗？",a="没有，Trias' Cheese不属于卫所，也不共用库存。然而，这两处设施共用一个楼层，这使得楼上成为了一个便利的转运点。",al={"trias cheese属于卫所吗","trias cheese库存"}},{q="谁负责监管货物的运送？",a="这项任务由当地的操作员安排，他们期待专业的尊重和相互的谨慎，并在货物成功送达且不阻碍门口的情况下，对可靠的信使表示认可。",al={"谁发布gatehouse goods","谁接收货物"}}},fp="15,378,33.531.0,20.455.0,24.213.0,47.214.0,65.245.0,40.142.0,47.194.0,39.207.0"}
P.entries["quest:97223"] = {n="Bloodtalon Matriarch",s="Bloodtalon Matriarch是森金村附近一支敏捷狡诈的迅猛龙群的首领。由于成年后的她太过危险且桀骜不驯，无法被驯服，因此必须将其解决，这样才能获取她的后代，将它们从蛋开始培养，使其成为暗矛巨魔忠诚的伙伴。",h="Bloodtalon Matriarch是森金村附近一支敏捷狡诈的迅猛龙群的首领。由于成年后的她太过危险且桀骜不驯，无法被驯服，因此必须将其解决，这样才能获取她的后代，将它们从蛋开始培养，使其成为暗矛巨魔忠诚的伙伴。",kw={"bloodtalon","暗矛","matriarch","迅猛龙","迅猛龙蛋","森金村","森金","巨魔坐骑"},ang={["class:Hunter"]="猎人们深知驯服经验丰富的成年野兽的难度，也明白必须从出生起就抚养掠食者才能建立真正的羁绊。",["faction:Horde"]="将当地的掠食者培养成忠诚的盟友，有助于巩固暗矛巨魔的定居点，并加强部落在杜隆塔尔海岸的影响力。",["race:Troll"]="森金村的暗矛巨魔将迅猛龙视为敏捷的伙伴和战马，他们非常看重Bloodtalon血脉的狡诈与迅捷。"},sec={{t="血爪血脉",b="Bloodtalon兽群以其卓越的速度和敏锐的狡诈在杜隆塔尔海岸闻名。当暗矛巨魔的驯兽师想要寻找可靠的坐骑和伙伴时，他们最看重的正是这些特质。然而，成年迅猛龙有着固执且暴力的本能，一旦它们适应了野外生活，几乎不可能被驯化。"},{t="保护血脉",b="尽管曾多次尝试直接捕获并训练这位Matriarch，但她日益增长的攻击性使她成为了对周边地区的一大威胁。为了在保护部落的同时确保其优秀的血脉不被断绝，巨魔们决定解决这位危险的母亲并抢救她的那一窝蛋，以确保下一代能从蛋开始就被培养成忠诚的盟友。"}},faq={{q="谁是Bloodtalon Matriarch？",a="Bloodtalon Matriarch是一只凶猛的成年迅猛龙，她的兽群以速度和狡诈著称。虽然早期曾尝试捕获并训练她，但她最终变得太危险而无法控制，因此暗矛巨魔转而选择获取她的蛋。",al={"谁是bloodtalon matriarch","bloodtalon迅猛龙首领","迅猛龙首领"}},{q="为什么必须对付Bloodtalon Matriarch？",a="成年迅猛龙以难以驯服而著称，而这位Matriarch对当地定居点构成了巨大的危险。通过制服她并收集她的蛋，森金村的驯兽师们可以在消除危险的同时保存其血脉。",al={"为什么要杀掉matriarch","为什么要获取蛋","为什么要猎杀matriarch"}},{q="为什么不直接驯服Matriarch？",a="成年迅猛龙拥有凶猛且无法驯服的本能，一旦成年就几乎无法训练。驯兽师通过获取蛋并直接从小培养幼崽，能取得更好的成果，使其与未来的伙伴建立联系。",al={"可以驯服成年迅猛龙吗","训练成年迅猛龙"}},{q="Matriarch的后代会怎么样？",a="捕获的蛋会被带回森金村进行孵化和培育。巨魔们打算从幼年开始训练这些小迅猛龙，让它们成长为部落可靠的盟友和坐骑。",al={"蛋会怎么样","matriarch的后代","森金村的迅猛龙"}},{q="这个任务发生在哪里？",a="该任务以森金村为中心，这是暗矛巨魔在杜隆塔尔南部的沿海避风港，驯兽师们在这里致力于为他们的人民繁育和培养忠诚的迅猛龙。",al={"这个任务在哪里交","森金村迅猛龙任务"}},{q="Bloodtalon兽群有什么特别之处？",a="Bloodtalon迅猛龙因其敏捷和智慧而备受推崇。只要在它们野性本能占据主导之前进行训练，这些特质就使它们的血脉成为极佳的伙伴和坐骑选择。",al={"bloodtalon迅猛龙特征","为什么选择bloodtalon迅猛龙"}}},fp="20,280,22.393.0,24.386.0,32.262.0,48.249.0,35.230.0,46.200.0,29.175.0,39.231.0"}
P.entries["quest:97225"] = {n="Forgotten Loa Idols",s="“Forgotten Loa Idols”的核心内容是为暗矛巨魔寻回神圣的宗教雕像。这些遗失的圣物对于恢复至关重要的精神仪式，并维系部落与其守护荒野之神之间长久的崇敬纽带至关重要。",h="“Forgotten Loa Idols”的核心内容是为暗矛巨魔寻回神圣的宗教雕像。这些遗失的圣物对于恢复至关重要的精神仪式，并维系部落与其守护荒野之神之间长久的崇敬纽带至关重要。",kw={"暗矛","forgotten loa idols","雕像","洛阿","崇敬","仪式","神灵","巨魔"},ang={["class:Priest"]="巨魔牧师和巫医直接依赖仪式和祖传圣物来引导精神力量并供奉洛阿。",["class:Shaman"]="虽然萨满修行调用的是元素力量，但巨魔灵术士对与部落生存息息相关的荒野之神和祖先洛阿怀有深切的崇敬。",["faction:Horde"]="暗矛巨魔是部落的创始成员，协助他们的圣职长老保护重要的宗教文物，能够加强部落内部的团结。",["race:Troll"]="对于暗矛巨魔来说，与洛阿的交流是精神生活的核心。寻回遗失的雕像能确保重要的仪式得以继续，并使部落保持在神灵的庇佑之中。"},sec={{t="洛阿的圣洁遗物",b="对暗矛巨魔而言，精神平衡与他们和洛阿——即他们祖先遗产中的原始动物之灵与荒野之神——的联系密不可分。“Forgotten Loa Idols”涉及找回对于开展部落仪式必不可少的遗失宗教圣物。没有这些神圣的物品，精神领袖们就无法执行那些与神圣守护者保持和谐所需的仪式。"},{t="暗矛的纽带",b="虽然艾泽拉斯各地有几个敌对的巨魔部族实行血祭，或者试图通过武力来强迫神灵屈服，但暗矛巨魔以保持相互尊重和谦卑的崇敬纽带而自豪。对暗矛巨魔来说，失去守护者的青睐是一场严重的灾难，这使得找回这些遗失的雕像成为了维系部落生存的重要举措。"}},faq={{q="“Forgotten Loa Idols”的目的是什么？",a="“Forgotten Loa Idols”是一项为暗矛巨魔进行的任务，旨在寻回失落的神圣雕像。这些雕像对于恢复关键的部落仪式并保持他们对所崇敬荒野之神的尊崇是必不可少的。",al={"forgotten loa idols","这是什么任务","什么是 forgotten loa idols"}},{q="什么是洛阿？",a="洛阿是巨魔所崇敬的古老、强大的原始之灵和动物神。巨魔文化通过祭品、祈祷和仪式来供奉他们，以换取保护、恩惠和精神指引。",al={"什么是洛阿","巨魔之神","谁是洛阿"}},{q="与其他巨魔部族相比，暗矛巨魔如何看待他们的洛阿？",a="与那些试图使黑暗神灵屈服或进行祭祀的残酷巨魔部族不同，暗矛巨魔将他们与洛阿的关系视为深切的崇敬、相互尊重和精神职责。他们相信自己的生存取决于能否继续获得神灵的青睐。",al={"暗矛洛阿关系","为什么要崇敬洛阿","其他部族的洛阿"}},{q="为什么部落仪式需要这些雕像？",a="这些雕像作为部落仪式的圣洁焦点。没有它们，长老和精神领袖就无法妥善地进行与守护神灵交流及表达敬意所需的仪式。",al={"为什么需要雕像","洛阿雕像的用途","为什么雕像很重要"}},{q="为什么保持洛阿的青睐对暗矛巨魔如此重要？",a="暗矛长老们担心，如果没有适当的仪式和祭品，他们的部落可能会失去洛阿的恩惠和庇护，使部落在这个充满危险的世界中变得脆弱。",al={"如果不归还雕像会发生什么","失去青睐","暗矛洛阿的恩惠"}},{q="谁在寻求找回“Forgotten Loa Idols”？",a="该任务由一位暗矛巨魔精神向导授予，他急于恢复集体仪式并确保获得部落祖先守护者的祝福。",al={"谁发布 forgotten loa idols","任务发布者","谁要求找回雕像"}}},fp="19,252,26.411.0,18.367.0,43.208.0,13.216.0,67.267.0,44.193.0,57.191.0,48.161.0"}
P.entries["quest:97234"] = {n="Reading Room",s="Reading Room围绕着Roy's Book Club和暴风城图书馆之间的一次交换展开。冒险者们协助该俱乐部，将一包包裹好的旧文学书籍送到图书馆，以便为成员们的讨论获取现代著作。",h="Reading Room围绕着Roy's Book Club和暴风城图书馆之间的一次交换展开。冒险者们协助该俱乐部，将一包包裹好的旧文学书籍送到图书馆，以便为成员们的讨论获取现代著作。",kw={"书籍","传说","图书管理员","reading room","roy's book club","暴风城图书馆","卷宗"},ang={["faction:Alliance"]="联盟的旅行者经常造访位于Stormwind Keep内的Royal Library，那里的公民和学术交流维持着城市的知识生活。"},sec={{t="暴风城的文学追求",b="在繁忙的暴风城首都，文学爱好者们聚集在Roy's Book Club的旗帜下，剖析经典传说，辩论发人深省的著作。该俱乐部通过轮换文本来保持讨论的新鲜感，用较旧或不太受欢迎的作品换取城市庞大馆藏中更新、更引人入胜的卷宗。"},{t="图书馆交换",b="为了保持他们的阅读清单与时俱进，该俱乐部依靠与暴风城图书馆建立的借阅协议。Roy使用一种标志性的包装技术将俱乐部归还的卷宗打包，让冒险者们可以直接将包裹送到图书管理员手中，以换取一份新的现代书籍清单。"}},faq={{q="什么是Reading Room任务？",a="Reading Room是一项涉及Roy's Book Club的任务，这是一个讨论传奇故事和文学的读者聚会。该任务要求一名冒险者将一捆不太受欢迎的包裹送到暴风城图书馆，以换取更现代的书籍。",al={"reading room任务","什么是reading room","reading room故事"}},{q="Roy是谁？",a="Roy经营着一个活跃的读书俱乐部，成员们在那里聚集，辩论传奇故事和文学的深层含义。他与暴风城图书馆保持着轮换阅读材料的安排，并将借来的书籍以完好无损的状态归还。",al={"roy是谁","roy's book club","读书俱乐部负责人"}},{q="书被送往哪里？",a="包裹好的阅读材料被直接送到暴风城的图书馆。那里的图书管理员认出了Roy的俱乐部所使用的独特包装技术，并欣然接受了用其交换新鲜的现代著作。",al={"书被送往何处","暴风城图书馆投递","包装好的阅读材料交付"}},{q="为什么要交换这些书？",a="俱乐部正在淘汰一些不太受欢迎的文学作品，以换取更现代、更引人深思的著作，并依赖于与城市图书馆建立的借阅安排。",al={"为什么要交换书籍","为什么要归还书籍","交换阅读材料"}},{q="暴风城的图书管理员如何看待这个读书俱乐部？",a="暴风城的图书管理员对这一安排非常满意，并指出Roy的俱乐部始终能以极好的状态归还借阅的材料，并且无论主题多么具有挑衅性，都能小心地对待所有的文本。",al={"图书管理员怎么看","读书俱乐部是被允许的吗","图书馆协议"}},{q="提到的俱乐部茶点是什么？",a="俱乐部为赞助者和协助在阅读场所与城市档案馆之间进行图书交换的帮手提供免费茶点。",al={"俱乐部免费茶点","俱乐部福利","有什么茶点"}}},fp="12,239,30.329.0,20.310.0,31.259.0,11.248.0,32.219.0,34.189.0,52.237.0,41.159.0"}
P.entries["quest:97236"] = {n="Fang of Githyiss",s="Fang of Githyiss是一种罕见且可怕的样本，取自一只潜伏在奥达希尔附近荒野中的巨型蜘蛛。将这枚毒牙交给保护区内的一位博物学家，可以帮助学者们研究这种怪物，并监测幽影谷内滋生的捕食威胁。",h="Fang of Githyiss是一种罕见且可怕的样本，取自一只潜伏在奥达希尔附近荒野中的巨型蜘蛛。将这枚毒牙交给保护区内的一位博物学家，可以帮助学者们研究这种怪物，并监测幽影谷内滋生的捕食威胁。",kw={"奥达希尔","fang of githyiss","githyiss","幽影谷","蜘蛛","蜘蛛研究","泰达希尔"},ang={["class:Druid"]="德鲁伊密切关注着泰达希尔内部的自然平衡，通过研究异常的捕食者和过度生长的蜘蛛来监测周边荒野的健康状况。",["faction:Alliance"]="对泰达希尔各地危险野生动物的研究有助于联盟确保年轻的招募者和研究人员了解在奥达希尔附近滋生的腐化威胁。",["race:NightElf"]="作为泰达希尔的保卫者，幽影谷的年轻暗夜精灵冒险者通过消灭危险的怪物并协助当地研究人员，帮助守护奥达希尔的枝干。"},sec={{t="一个巨大的样本",b="Fang of Githyiss是取自潜伏在幽影谷荒野中的巨型蜘蛛Githyiss身上的一种战利品和生物样本。这种体型巨大的野兽对从奥达希尔出发的年轻旅行者构成了明显的威胁，因此回收它的毒牙既关乎安全，也具有科学意义。与其让这只生物的遗骸在灌木丛中腐烂，足智多谋的侦察兵们会将样本带回这棵巨树的保护区。"},{t="在奥达希尔的研究",b="在奥达希尔，暗夜精灵的博物学家和学者们密切关注着在森林地面上游荡的野生动物。呈现一枚来自Githyiss这样规模的生物的新鲜、完整的毒牙，能为研究泰达希尔树冠下繁衍的蜘蛛种群提供关键的洞察。当地的研究人员欢迎这种意外的发现，并利用这枚巨大的毒牙进一步开展他们对林地攻击性动物群的持续研究。"}},faq={{q="什么是Fang of Githyiss？",a="Fang of Githyiss是取自巨型蜘蛛Githyiss身上的一枚新鲜样本。回收这样一枚巨大的毒牙可以提供有关栖息在奥达希尔周围荒野中的捕食性蜘蛛的罕见研究材料。",al={"什么是fang of githyiss","githyiss毒牙任务","fang of githyiss物品"}},{q="Githyiss是谁，或者是什么？",a="Githyiss是一只体型巨大且危险的蜘蛛，在幽影谷奥达希尔附近的森林中徘徊。它的体型使它成为旅行者的威胁，也是当地博物学家研究的有趣对象。",al={"谁是githyiss","githyiss蜘蛛","githyiss在哪里"}},{q="谁想要Fang of Githyiss？",a="这枚毒牙会被带给奥达希尔的一位专门研究蜘蛛的学者。这类研究人员欢迎新鲜的样本，以推进他们对当地蜘蛛生物学的了解。",al={"谁上交fang of githyiss","我把毒牙带到哪里","奥达希尔蜘蛛研究员"}},{q="奥达希尔在哪里？",a="奥达希尔是幽影谷的巨大枝干和中心保护区，位于世界之树泰达希尔的树冠之内。它是年轻暗夜精灵的训练场和避难所。",al={"奥达希尔在哪里","奥达希尔位置"}},{q="为什么奥达希尔的学者要研究蜘蛛毒牙？",a="奥达希尔的学者和博物学家研究当地的蜘蛛，是为了更好地了解幽影谷的生态，并监测泰达希尔树冠下栖息的攻击性超大野兽。",al={"为什么他们在奥达希尔研究蜘蛛","为什么要研究蜘蛛毒牙"}},{q="部落玩家可以上交Fang of Githyiss吗？",a="不能。该任务发生在泰达希尔之上的暗夜精灵新手区域——幽影谷，因此只有在奥达希尔开启旅程的联盟冒险者才能完成。",al={"这个任务是联盟专属吗","部落能做fang of githyiss任务吗"}}},fp="16,279,20.462.0,21.438.0,29.219.0,24.188.0,31.185.0,19.184.0,52.194.0,47.182.0"}
P.entries["quest:97237"] = {n="Shelf Picked",s="“Shelf Picked”是暴风城的一项信差差事，需要为Roy Lewells从图书馆书架上取回一份特定的阅读清单。作为授权代理人，跑腿者将代表公园里的一个本地读书会领取这些书籍。",h="“Shelf Picked”是暴风城的一项信差差事，需要为Roy Lewells从图书馆书架上取回一份特定的阅读清单。作为授权代理人，跑腿者将代表公园里的一个本地读书会领取这些书籍。",kw={"读书会","信差","图书馆","公园","roy lewells","shelf picked","暴风城"},ang={["faction:Alliance"]="在暴风城的图书馆和当地聚会点之间跑腿送信，反映了在王国局势紧张的情况下，首都里依旧持续着的平静的日常公民生活。"},sec={{t="书架差事",b="“Shelf Picked”的内容是担任Roy Lewells的官方信差，此人与暴风城的公园区有关。Roy提交了一份各种阅读书目的请求，虽然负责的图书管理员确认了所列书目皆有库存，但信差必须亲自从书架上找到并取下每一本书。图书管理员留在前台处理监督性的簿记工作，在委托物理取书的同时确保库存记录维护妥当。"},{t="地窖读书会",b="处理借阅的图书馆藏书通常带有严格的归还义务，但携带Roy Lewells的授权书可提供官方信差身份。主管图书管理员指出，个人责任并不由跑腿者承担；相反，Lewells的机构承担归还借阅作品的全部责任。一旦送到公园，Roy就会准备好这些散发着异香的书籍，供晚些时候在地窖里举办的活跃讨论会使用。"}},faq={{q="谁发布了“Shelf Picked”这个任务？",a="该任务是在Roy Lewells发送了一张差事便条后，从负责管理图书馆库存的图书管理员那里接取的。图书管理员证实了Roy要求的阅读清单有货，但指示你亲自从书架上取下这些书籍。",al={"谁发布shelf picked","shelf picked任务发布者","shelf picked在哪里开始"}},{q="Roy Lewells是谁？",a="Roy Lewells是暴风城公园区一个本地读书会的组织者。他派遣信差从图书馆取回预订的书籍，用于即将在他们地窖中举行的非正式讨论会。",al={"roy lewells是谁","roy lewells公园","lewells是谁"}},{q="藏书是在哪里取出的？",a="该任务发生在图书馆，Lewells先生所选的读物都存放在那里。负责的图书管理员管理着库存记录，而信差则在场所的书架上寻找特定的书籍。",al={"这是什么图书馆","在哪里取书","shelf picked是哪个图书馆"}},{q="为什么Roy Lewells需要这些书？",a="Roy Lewells请求这些阅读材料是为了让一个非正式读书会的成员激发热烈的讨论。由于聚会的性质，一旦书送到，他们就会在下班后的时间在地窖里集合。",al={"为什么要为lewells取书","什么是lewells读书会","地窖下班后读书会"}},{q="你有责任归还借来的书吗？",a="不。图书管理员明确澄清，以官方信差身份持有Roy Lewells的便条可以免除你归还书籍的个人责任；归还书籍的重担完全由Roy的机构承担。",al={"我有责任归还书籍吗","谁归还shelf picked的书","图书馆图书归还责任"}},{q="取回书后该带到哪里？",a="你将收集到的阅读材料直接送回给Roy Lewells，他就在暴风城的公园区。",al={"shelf picked在哪里交任务","哪里找到roy lewells","shelf picked交任务"}}},fp="12,256,24.484.0,23.462.0,33.245.0,19.204.0,42.225.0,38.222.0,53.238.0,44.137.0"}
P.entries["quest:97242"] = {n="Yelmak's Medley",s="Yelmak's Medley是奥格瑞玛的一个任务，旨在缓解Valley of Honor中Yelmak's Alchemy and Potions内部的紧张局势。炼金大师Yelmak试图通过调制一种由当地水生植物制成的舒缓自制药剂，来遏制他的学徒Whuut那破坏性的笨拙和顽固的自尊心。",h="Yelmak's Medley是奥格瑞玛的一个任务，旨在缓解Valley of Honor中Yelmak's Alchemy and...",kw={"炼金术","香蒲","kor'geld","奥格瑞玛","矛草","valley of honor","whuut","yelmak","yelmak's medley"},ang={["faction:Horde"]="这项差事直接在奥格瑞玛的Valley of Honor内进行，有助于维持秩序并平息首都炼金业内部的不满情绪。",["profession:Herbalism"]="沿着城市水道采集新鲜的香蒲和矛草，突显了奥格瑞玛城内的当地植物是如何被用于调制药剂和草药饮料的。"},sec={{t="实验室里的麻烦",b="在奥格瑞玛Valley of Honor的Yelmak's Alchemy and Potions里，商店年轻学徒Whuut的顽固自尊让生活变得复杂。这位新手调配师不仅不寻求帮助，也不承认自己力不从心，反而因为沮丧而开始破坏商店设备。为了减少损失并平息这名年轻人的暴躁脾气，同时又不伤及他脆弱的自尊心，炼金大师Yelmak设计了一种镇静的自制药剂。"},{t="舒缓的当地植物",b="配方需要新鲜采摘的野外香蒲和矛草插条，它们生长在Valley of Honor蜿蜒的水流边。Kor'geld无法离开商店，否则会引起这位多疑学徒的注意，因此需要一个第三方谨慎地收集这些河岸植物。一旦收集完毕，这种植物混合剂将被调制出来，以微妙地控制Whuut的态度，恢复炼金商店的平静。"}},faq={{q="谁发布了Yelmak's Medley任务？",a="Kor'geld位于奥格瑞玛Valley of Honor的Yelmak's Alchemy and Potions内，他代表该店的炼金大师发布了这项任务。",al={"谁发布yelmak's medley","任务发布者yelmak's medley"}},{q="Whuut是谁？",a="Whuut是在Valley of Honor跟随Yelmak训练的学徒调配师。他以顽固的自尊心闻名，他宁愿破坏设备也不愿承认自己需要指导或帮助。",al={"whuut是谁","yelmak的学徒","奥格瑞玛的whuut"}},{q="这种自制药剂的目的是什么？",a="这是一种由炼金大师Yelmak用新鲜香蒲和矛草插条调制的特殊自制混合剂，旨在微妙地安抚或缓和其傲慢学徒的不良情绪。",al={"yelmak's medley的配方是什么","yelmak想酿造什么"}},{q="在哪里采集原料？",a="野生香蒲和矛草直接生长在奥格瑞玛Valley of Honor流经的淡水溪流和水池边。",al={"在哪里寻找香蒲和矛草","valley of honor的插条"}},{q="为什么Kor'geld不亲自去采集插条？",a="Kor'geld不能离开Yelmak's Alchemy and Potions，因为Whuut会立刻意识到商店员工是在秘密地费尽心思迁就他那难以相处的脾气。",al={"为什么kor'geld需要帮助","为什么kor'geld不能采摘植物"}},{q="Yelmak's Alchemy and Potions位于何处？",a="Yelmak's Alchemy and Potions坐落在Valley of Honor，这是部落首都奥格瑞玛的东部地区，以其水道、战士兵营和工匠商店而闻名。",al={"yelmak's alchemy and potions在哪里","yelmak商店位置"}}},fp="15,307,25.449.0,20.431.0,37.139.0,13.190.0,46.177.0,35.135.0,52.180.0,46.180.0"}
P.entries["quest:97243"] = {n="Call of Fire",s="Call of Fire会指引一名初学者穿过天空之墙的风暴，去寻找奥拉里安·迅燃（Olariaan Swiftburn），这是一位与火元素共鸣的辛多雷（shen'dorei）塑风者。旅行者需要带着沉寂火焰之炬前往阵风浆果低地的火焰神龛，并在那里开始学习如何在风的领域中聆听火焰的召唤。",h="Call of Fire会指引一名初学者穿过天空之墙的风暴，去寻找奥拉里安·迅燃（Olariaan...",kw={"call of fire","元素位面","阵风浆果低地","奥拉里安·迅燃","辛多雷","火焰神龛","天空之墙","沉寂火焰之炬","瓦拉纳尔","塑风者"},ang={["class:Shaman"]="聆听元素的召唤是萨满修行的基础，即使在天空之墙，与火元素沟通也需要专注的指导和对先祖的敬畏。",["race:Skyborne"]="虽然身为天空之墙风之子，但空行者和塑风者们都认识到，平衡需要认可所有四种原始元素。"},sec={{t="元素位面中的声音",b="Even within Skywall, the domain ruled by the air elementals, the broader currents of the Elemental Plane remain connected. The spirits of earth, water, and fire still speak to those with the sensitivity to hear them. The Windshapers count among their fellowship individuals uniquely receptive to these other forces, including Olariaan Swiftburn, a shen'dorei who fosters a deep attunement with the element of fire."},{t="火焰神龛",b="初学者会被授予沉寂火焰之炬，并被指引前往阵风浆果低地。在岛屿边缘的远方，瓦拉纳尔的西侧，矗立着火焰神龛。在那里，奥拉里安·迅燃会接收这份沉寂的火焰，并主动向有志向的学生传授如何在翻涌的空气领域中回应火焰的召唤。"}},faq={{q="谁是奥拉里安·迅燃？",a="奥拉里安·迅燃是一位塑风者的辛多雷成员，他对火元素有着天生的共鸣。他居住在阵风浆果低地边缘、瓦拉纳尔西侧的火焰神龛。",al={"谁发布call of fire任务","把火炬交给谁","奥拉里安·迅燃"}},{q="火焰神龛在哪里？",a="火焰神龛位于天空之墙的阵风浆果低地内。它坐落在浮岛群边缘的一处僻静之地，位于瓦拉纳尔的正西方。",al={"火焰神龛在哪里","阵风浆果低地位置","如何找到奥拉里安"}},{q="为什么要在天空之墙学习火元素？",a="尽管天空之墙主要是风元素的领域，但它仍然是广阔的元素位面不可或缺的一部分。对于那些能够感知到的修行者来说，所有四种元素的灵魂依然在其领地内回荡。",al={"为什么要在天空之墙研究火元素","元素位面火元素","天空之墙不是只有风吗"}},{q="什么是沉寂火焰之炬？",a="沉寂火焰之炬是携带给奥拉里安·迅燃的一种元素焦点，它是初学者寻求学习如何与火元素沟通的媒介。",al={"什么是沉寂之火","沉寂火焰之炬","我需要携带什么物品"}},{q="谁是塑风者？",a="塑风者是天空之墙中那些能够驾驭和塑造元素力量的修行者，他们的队伍中包含了如辛多雷等不同起源的成员。",al={"谁是塑风者","塑风者阵营"}},{q="这个任务通向哪里？",a="奥拉里安·迅燃会教导弟子如何聆听火焰的召唤，并强调在天空之墙这样苛刻的领域内掌握原始力量需要极大的毅力。",al={"奥拉里安教授什么","在天空之墙训练火元素"}}},fp="12,327,33.414.0,20.363.0,26.202.0,30.164.0,37.225.0,35.162.0,24.170.0,29.180.0"}
P.entries["quest:97244"] = {n="Call of Fire",s="“Call of Fire”是来自塑风者的一个任务，要求处决天祭司法拉迪尔（Skypriest Faladiel），他曾是一名为了力量而背叛教派的兄弟。冒险者必须追踪这名叛变的天祭司前往阵风浆果低地，并取回他的心脏，以作为一种强大元素仪式的燃料。",h="“Call of Fire”是来自塑风者的一个任务，要求处决天祭司法拉迪尔（Skypriest...",kw={"奥拉凯斯","call of fire","法拉迪尔","法拉迪尔的心脏","阵风浆果低地","阿基尔神殿","天祭司法拉迪尔","瓦拉纳尔","塑风者"},ang={["class:Priest"]="牧师们或许会认为天祭司法拉迪尔的腐化与堕落引人深思，因为他原本神圣的召唤职责被扭曲，变成了对自身教派的背叛与谋杀。",["class:Shaman"]="专注于火焰和元素仪式的萨满祭司们会认出这种严酷、原始的本质：将叛徒的精华喂给火焰，以增强其神圣的力量。"},sec={{t="烈焰中的叛徒",b="“Call of Fire”要求冒险者猎杀天祭司法拉迪尔。他曾是一名塑风者，为了加入奥拉凯斯而抛弃了自己的忠诚。法拉迪尔曾是一名忠诚的火焰召唤者，但最终选择了力量而非盟誓，向同僚挥下屠刀，手上沾满了兄弟的鲜血。塑风者派遣了一名代理人去向他传达不容妥协的判决。"},{t="低地的清算",b="法拉迪尔躲藏在阵风浆果低地的一处农场中，该地位于瓦拉纳尔东北方，阿基尔神殿正南。杀死这名叛变的天祭司不仅仅是为了复仇；塑风者需要他的心脏作为即将举行的仪式中必不可少的残酷材料，他们坚信，吞噬叛徒的心脏能让他们的圣火燃烧得更加炽热。"},{t="以血偿血",b="在收到心脏后，塑风者重申了他们的信条：以血偿血。然而，法拉迪尔的死亡只是他们工作的一个阶段，因为这颗心脏只是仪式结束前，他们祭祀之火所需的一部分。"}},faq={{q="谁是天祭司法拉迪尔？",a="天祭司法拉迪尔曾是一名虔诚的火焰召唤者和塑风者的忠实成员。像许多奥拉凯斯成员一样，他为了追求力量而背弃了忠诚，转而对付自己的族人，手上沾满了他们的鲜血。",al={"谁是法拉迪尔","法拉迪尔背景故事","天祭司法拉迪尔传说"}},{q="为什么塑风者要杀掉法拉迪尔？",a="塑风者寻求报复是因为法拉迪尔为了力量背叛了他们，并杀害了昔日的兄弟姐妹。根据塑风者的信条，必须以血偿血，因此对他的处决既是正义的伸张，也是必要的报复。",al={"为什么要杀法拉迪尔","为什么塑风者要杀死法拉迪尔","法拉迪尔的背叛"}},{q="为什么塑风者需要法拉迪尔的心脏？",a="法拉迪尔的心脏是极其有效的仪式试剂。塑风者相信，火焰渴望吞噬叛徒心脏的祭品，以此为食会让烈焰燃烧得更加猛烈和炽热。",al={"为什么需要法拉迪尔的心脏","心脏有什么用","仪式试剂心脏"}},{q="在哪里可以找到天祭司法拉迪尔？",a="天祭司法拉迪尔在阵风浆果低地的一处农场中避难，该地位于瓦拉纳尔的东北方，阿基尔神殿的正南方。",al={"法拉迪尔在哪里","天祭司法拉迪尔位置","找到法拉迪尔"}},{q="塑风者的信条是什么？",a="塑风者是一个受严格且坚定信条约束的组织，在他们的教义中，背叛永不被遗忘，鲜血必须以鲜血偿还。他们修习火焰召唤和神圣的元素仪式。",al={"谁是塑风者","塑风者信条","塑风者派系"}},{q="奥拉凯斯与这次任务有什么联系？",a="奥拉凯斯是一个已知的派系或团体，其成员为了个人力量而交易掉了他们曾经的忠诚和荣誉，法拉迪尔就是他们天祭司中一个显著的例子。",al={"什么是奥拉凯斯","法拉迪尔奥拉凯斯","奥拉凯斯叛徒"}}},fp="12,272,25.371.0,25.392.0,21.268.1,26.241.0,44.220.0,45.205.0,38.146.0,37.197.0,50.204.0"}
P.entries["quest:97245"] = {n="Call of Fire",s="“Call of Fire”是一项任务，冒险者受Olariaan Swiftburn委托，前往申达尔高地寻找并对决古老的森林精灵Kuramaa。通过从树桩中召唤精灵并用火焰将其击败，旅行者可以获得它强大的木制面具。随后，这件圣物会被带到阵风浆果低地，点燃永恒之火，并与火之灵沟通。",h="“Call of Fire”是一项任务，冒险者受Olariaan...",kw={"锚点塔","call of fire","森林精灵","阵风浆果低地","kuramaa","kuramaa的面具","olariaan swiftburn","申达尔高地"},ang={["class:Mage"]="Kuramaa对大多数魔法流派有着极强的抗性，迫使施法者只能纯粹依赖火焰魔法来战胜该精灵。",["class:Shaman"]="虽然该仪式与传统的萨满火焰试炼同名，但其重点在于用火焰制服强韧的高地之灵，从而汇聚力量以与火之灵进行沟通。"},sec={{t="高地的精灵",b="在申达尔高地，当地居民流传着关于Kuramaa的传说，这是一位古老的森林精灵，居住在靠近该地区锚点塔的一座山顶上的扭曲树桩内。想要引出这位隐居的实体，挑战者必须用赤手空拳敲击它木制家园的树皮，以此要求它现身，并在战斗中考验他们的勇气。"},{t="火与木",b="对于奥术或神圣力量的使用者来说，战胜Kuramaa并非易事，因为该精灵对大多数形式的魔法有着深厚的天然防护。只有灼热的火焰才能穿透它古老的树皮并将其击倒。击败该生物会掉落Kuramaa的木制面具，这是一件蕴含强大力量的文物。即便如此，Kuramaa依然是永恒的，注定会在被召唤时再次成形并显现。"},{t="永恒之火",b="在阵风浆果低地，Olariaan Swiftburn正等待着Kuramaa面具的带回。这件附魔的木制圣物是进行神秘仪式的催化剂：点燃永恒之火以直接与火之灵沟通，并通过击败高地自然之灵来开启古老的元素交流。"}},faq={{q="Kuramaa是谁？",a="Kuramaa是一位居住在申达尔高地的古老森林精灵。据当地高地居民所述，它居住在靠近高地锚点塔的一座山顶上的扭曲树桩内。",al={"kuramaa是谁","kuramaa背景故事","kuramaa是什么"}},{q="Olariaan Swiftburn是谁？",a="Olariaan Swiftburn是委托冒险者与Kuramaa对决的仪式主持者。Olariaan驻扎在阵风浆果低地，需要Kuramaa的木制面具来执行神圣的火焰仪式。",al={"谁发布call of fire任务","olariaan swiftburn是谁","call of fire在哪里交任务"}},{q="如何召唤Kuramaa？",a="Kuramaa生活在申达尔高地锚点塔附近一座山顶上的扭曲树桩内。要将该精灵召唤出来进行战斗，必须用拳头用力敲击树桩的树皮。",al={"如何召唤kuramaa","kuramaa的树桩在哪里","召唤森林精灵"}},{q="Kuramaa在战斗中有什么弱点？",a="Kuramaa对大多数形式的魔法拥有卓越的天然抗性。只有火焰的触碰才能克服它的防御，并在战斗中击倒这位古老的森林精灵。",al={"kuramaa的弱点","如何击败kuramaa","kuramaa魔法免疫"}},{q="Olariaan Swiftburn为什么需要Kuramaa的面具？",a="Kuramaa的木制面具被公认为是一个拥有强大力量的容器。Olariaan Swiftburn利用这件强力的圣物作为点燃永恒之火并直接与火之灵沟通的关键组件。",al={"为什么要收集kuramaa面具","面具有什么用","kuramaa面具的用途"}},{q="Kuramaa被击败后会永久死亡吗？",a="Kuramaa是永恒的林地精灵，而非凡人生物。尽管它的物理形态会被击败以夺取其面具，但该精灵依然存在，并会在需要时再次显现。",al={"kuramaa死了吗","我杀了kuramaa吗","kuramaa刷新背景"}}},fp="12,388,27.364.0,13.383.0,17.323.1,15.225.0,26.194.0,26.194.0,40.174.0,48.207.0,47.191.0"}
P.entries["quest:97246"] = {n="Meal Appeal",s="Meal Appeal 是奥格瑞玛的一项跑腿任务，发布者是 Thatog。Thatog 是一位被日常职责束缚的兽人，他担心自己年幼的儿子 Migi 因为玩耍而错过了吃饭。旅行者需要从 Borstan's Firepit 取一份准备好的午餐，并找到在 Grommash Hold 后方玩耍的 Migi。这个任务展现了部落首都里平凡的家庭生活。",h="Meal Appeal 是奥格瑞玛的一项跑腿任务，发布者是 Thatog。Thatog 是一位被日常职责束缚的兽人，他担心自己年幼的儿子 Migi 因为玩耍而错过了吃饭。旅行者需要从 Borstan's Firepit...",kw={"borstan","borstan's firepit","grommash hold","午餐派送","meal appeal","migi","奥格瑞玛","thatog"},ang={["faction:Horde"]="奥格瑞玛城墙内的生活并非只有战争与防御；像给在 Valley of Strength 奔跑的孩子们喂饭这样的日常琐事，维系着这座城市的社区活力。",["race:Orc"]="即使在严酷的兽人文化中，像 Thatog 这样的父母也会担心他们的孩子因为在杜隆塔尔首都的街头玩耍而忽略了吃饭。"},sec={{t="奥格瑞玛的为人父母之道",b="In the bustling red-rock avenues of Orgrimmar, everyday domestic life continues alongside the drills of grunt warriors and the machinations of the Horde. Thatog, bound to his daily post by duty, finds himself unable to keep a watchful eye over his energetic young son, Migi. Left to his own devices, Migi spends from morning till dusk racing through the city streets with his friends, consistently neglecting his stomach until returning home famished."},{t="要塞后方的派送",b="为了不让孩子下午饿肚子，Thatog 在 Borstan's Firepit 安排了一份热乎的午餐。因为 Migi 不会为了拿午餐而中断游戏，Thatog 便请求路过的冒险者充当私人信使。这项跑腿任务将指引旅行者从 Borstan 的炉火处前往 Grommash Hold 后方的空地，Migi 和街坊邻里的孩子们通常总能在那里找到，沉浸在他们的儿时游戏中。"}},faq={{q="Thatog 是谁？",a="Thatog 是一位驻守在奥格瑞玛的忙碌兽人父亲，他的日常职责使他无法抽身去监管年幼的儿子 Migi。出于对 Migi 因为和朋友玩耍而错过饭点的担忧，Thatog 请一位乐于助人的冒险者去为男孩取餐并送餐。",al={"thatog 是谁","任务发布者 thatog","thatog 奥格瑞玛"}},{q="去哪里能找到 Migi？",a="Migi 白天都在首都和朋友们一起玩耍。Thatog 指出，孩子们几乎肯定会在奥格瑞玛的 Grommash Hold 后方嬉戏打闹。",al={"migi 在哪里","migi 位置","找到 migi"}},{q="Borstan's Firepit 是什么？",a="Borstan 经营着 Borstan's Firepit，这是奥格瑞玛的一家地方餐饮店。Thatog 请旅行者先去那里，告知 Borstan 你是来取一份预定好的午餐，并亲自送给 Migi。",al={"borstan's firepit 在哪里","borstan's firepit 位置","borstan 午餐"}},{q="Migi 为什么会忘记吃饭？",a="和许多精力充沛的年轻兽人一样，Migi 因为在 Grommash Hold 后方和朋友们玩得太投入，以至于忘记或者选择不去 Borstan's Firepit 吃饭，往往在一天结束时饿着肚子回到家。",al={"migi 为什么不吃午饭","migi 挨饿","migi 为什么不吃饭"}},{q="Migi 是谁？",a="Migi 是 Thatog 的幼子。他在奥格瑞玛四处游荡，和一群朋友玩游戏，比起回家或去取准备好的饭菜，他把玩耍放在了第一位。",al={"migi 是谁","migi 兽人小孩","thatog 的儿子"}},{q="Meal Appeal 的任务目标是什么？",a="任务要求前往 Borstan's Firepit 告知 Borstan 你是 Thatog 派来取 Migi 的午餐的人，然后将食物直接送到 Grommash Hold 后方的 Migi 手中，这样男孩在游戏时就不会挨饿了。",al={"meal appeal 任务目标","meal appeal 怎么做","meal appeal 任务"}}},fp="11,345,28.451.0,24.448.0,14.291.0,24.193.0,26.210.0,28.247.0,12.170.0,37.216.0"}
P.entries["quest:97249"] = {n="Favorite Food",s="“Favorite Food”是一个关于Migi的奥格瑞玛任务。Migi是个贪玩的孩子，常在格罗玛什要塞后玩耍，他的父母担心他吃得不够多。为了在不让他饿肚子的情况下拓宽他的口味，Borstan's Meats的博斯坦准备了各种午餐，并用Migi最爱的蜜汁酥脆猪皮调味。这份午餐确保了这孩子和他的朋友们会停下游戏，享受一顿营养均衡的饭菜。",h="“Favorite Food”是一个关于Migi的奥格瑞玛任务。Migi是个贪玩的孩子，常在格罗玛什要塞后玩耍，他的父母担心他吃得不够多。为了在不让他饿肚子的情况下拓宽他的口味，Borstan's...",kw={"博斯坦","borstan's meats","favorite food","grommash hold","猪腩","午餐","migi","奥格瑞玛","蜜汁"},ang={["faction:Horde"]="这个任务展现了奥格瑞玛日常生活的一瞥，展示了当地商贩和家庭如何确保首都的孩子们得到照顾和喂养。",["profession:Cooking"]="这项任务演示了部落首都中实用的烹饪工艺，将酥脆的熏猪腩猪皮碎屑再利用，作为日常餐食的美味调料。"},sec={{t="玩耍的胃口",b="在部落权力的中心——格罗玛什要塞后方，年幼的Migi和他的朋友们常常在奥格瑞玛尘土飞扬的小路上玩耍。然而，Migi的父母担心这孩子在玩的时候经常不吃饭，没法填饱肚子。为了确保他能按时进食，他们找来了Borstan's Meats制作每日盒装午餐。但父母提出了一个严格的要求：博斯坦不能每天都提供同样的餐食，他们坚持要让Migi尝试不同的食物，而不是只依赖他最爱的那一道菜。"},{t="蜜汁妥协",b="博斯坦面临着烹饪挑战，因为众所周知，Migi非常钟爱蜜汁猪腩三明治，而且只有在熏肉房里飘出那种甜味时，他才会准时出现吃午饭。为了满足父母对餐食多样性的要求，同时又能让孩子吃饱，这位屠夫想出了一个巧妙的办法。当准备蜜汁猪肉时，剩下的酥脆蜜汁猪皮碎屑可以制成一种咸香的调料，撒在任何菜肴上。送到格罗玛什要塞后方的这份带有香气的调料，成功让Migi和他的同伴们停下游戏，聚在一起享用午餐。"}},faq={{q="Migi是谁？",a="Migi是奥格瑞玛的一名小居民，平日里总是在格罗玛什要塞后方和朋友们一起玩游戏。因为他玩得太投入，父母很担心他没法填饱肚子，所以安排了Borstan's Meats每天送午餐过来。",al={"migi 奥格瑞玛","格罗玛什要塞后面的孩子是谁","migi的午餐"}},{q="是谁发布了“Favorite Food”任务？",a="该任务由奥格瑞玛Borstan's Meats的博斯坦发布。在了解到Migi父母对其营养和饮食习惯的担忧后，博斯坦准备了一份旨在拓宽这孩子口味的特别餐点。",al={"favorite food任务发布者","谁开启favorite food","博斯坦 favorite food"}},{q="Migi在哪里可以找到？",a="Migi位于奥格瑞玛的格罗玛什要塞后方，他常在那里和当地的其他孩子一起玩耍。这些孩子经常经过通往要塞的路，仅凭气味就能认出博斯坦每日提供的特色菜。",al={"migi的位置","migi在哪里","在哪递送migi的午餐","寻找migi 奥格瑞玛"}},{q="Migi最喜欢吃什么？",a="Migi最喜欢吃的是Borstan's Meats熏肉房里制作的蜜汁猪腩三明治。只要熏肉房开工，Migi总会准时来吃午饭，被飘向格罗玛什要塞的独特香气所吸引。",al={"migi喜欢吃什么","migi最爱的食物","蜜汁猪腩 mgi"}},{q="为什么Migi的父母要求提供不同的餐食？",a="Migi的父母要求博斯坦不要每天都打包完全一样的午餐，这样他们的儿子就能培养对更多食物的兴趣。虽然他们很想让孩子吃饱，但更希望他能养成全面的饮食习惯，而不是只靠蜜汁猪肉度日。",al={"为什么要改变migi的午餐","migi父母的要求","为什么不能每天都吃蜜汁三明治"}},{q="博斯坦是如何让Migi吃下不同食物的？",a="博斯坦将熏猪腩剩下的酥脆蜜汁猪皮碎片捣碎，做成一种可以撒在不同菜肴上的配料。这种浓郁且熟悉的蜜汁风味，让博斯坦能提供各种各样的饭菜，而Migi依然会吃得干干净净。",al={"博斯坦的诀窍","博斯坦如何让migi吃饭","蜜汁碎屑"}},{q="什么是Borstan's Meats？",a="Borstan's Meats是位于奥格瑞玛的一家熏肉房和肉铺，以其熏猪腩三明治和为城中居民提供盒装餐食而闻名。博斯坦利用他的烹饪天赋，让社区里的孩子们吃得饱饱的。",al={"博斯坦的肉铺 奥格瑞玛","博斯坦的肉铺在哪里","博斯坦是什么人"}}},fp="13,381,20.574.0,25.604.0,12.289.0,34.224.0,24.241.0,29.245.0,46.267.0,49.267.0,24.229.0"}
P.entries["quest:97250"] = {n="Wrongly Blamed, Justly Corrected",s="“误会被责，正义纠正”聚焦于部落与联盟在东海岸日益升级的紧张局势，起因是一间路边旅店的离奇毁灭。这一事件给了联盟军队一个严厉的警告，同时也留下了一个悬而未决的疑点：究竟是谁威胁到了这条重要的平民贸易路线。",h="“误会被责，正义纠正”聚焦于部落与联盟在东海岸日益升级的紧张局势，起因是一间路边旅店的离奇毁灭。这一事件给了联盟军队一个严厉的警告，同时也留下了一个悬而未决的疑点：究竟是谁威胁到了这条重要的平民贸易路线。",kw={"联盟警告","平民路线","东海岸","部落贸易","旅店","领土冲突","wrongly blamed, justly corrected"},ang={["faction:Alliance"]="这一结果是部落军队针对联盟日益增长的势力和挑衅行为，在东海岸发出的严厉警告。",["faction:Horde"]="该任务标志着一次显著的胜利和对联盟入侵行为的防御性声明，同时也引起了对保护重要部落贸易和平民路线的担忧。"},sec={{t="海岸摩擦",b="随着部落与联盟在东海岸沿线的摩擦不断加剧，冲突已经开始蔓延至争议地区。主要通道上一间当地旅店的毁灭将这些紧张局势推向了顶峰，并威胁到了普通旅客的安全与地区的稳定。"},{t="疑点与破坏",b="虽然最初的怀疑指向部落的侵略行为，但当地领导层怀疑并非己方力量摧毁了旅店。这条通道是部落平民和商人们运输货物的生命线，部落有充分的理由保持这条道路畅通，这也促使人们更深入地调查究竟是谁摧毁了它。"},{t="对联盟的警告",b="尽管关于旅店本身的疑问尚存，但这件事的结局标志着部落军队在当地取得了一次决定性的胜利。这一结果向联盟发出了明确的警告：任何沿海岸的领土侵犯都将遭到立即的抵抗。"}},faq={{q="“误会被责，正义纠正”讲的是什么？",a="“误会被责，正义纠正”是一个部落任务，讲述了因一条重要旅行路线上的路边旅店被毁，而导致的东海岸阵营间摩擦升级。",al={"这个任务是什么","误会被责正义纠正剧情","误会被责发生了什么"}},{q="是部落摧毁了旅店吗？",a="部落领导层仍然非常怀疑部落军队是否负有责任。太多的部落平民依赖这条路线进行贸易和日常通行，摧毁它只会适得其反。",al={"部落摧毁了旅店吗","谁烧了旅店","谁摧毁了旅店"}},{q="为什么被毁的旅店对部落很重要？",a="这家旅店位于一条重要的通道上，平民旅客和商人们高度依赖它进行贸易和通行，因此它的损毁是一个战略性的忧虑。",al={"为什么旅店路线很重要","为什么旅店很重要"}},{q="是什么导致了东海岸的紧张局势？",a="最初导致紧张局势的原因尚不明确。部落与联盟在东海岸的摩擦由来已久，现在冲突已经波及到了部落领地。",al={"为什么在东海岸战斗","东海岸冲突"}},{q="这一结果向联盟传达了什么信息？",a="这次行动是一次战术上的胜利，并向联盟发出了严厉的警告，表明针对部落利益的领土入侵行为不会不受惩罚。",al={"部落取得了什么成就","为什么要警告联盟"}},{q="是否会对旅店的损毁进行进一步调查？",a="由于旅店损毁的情况依然存疑，且平民通行受到威胁，各方都在寻求进一步调查以查明究竟是谁造成了这次破坏。",al={"调查什么","会调查旅店吗"}}},fp="32,313,21.306.0,20.347.1,25.284.0,47.188.0,33.197.0,50.170.0,42.183.0,52.177.0,61.186.0"}
P.entries["quest:97253"] = {n="Parts and Pieces",s="“Parts and Pieces”是卑鄙的维尼克斯在棘齿城港口发布的一个取回任务。在几名雇佣兵相继在当地海盗手中丧命后，维尼克斯部署了一台机械装置来应对威胁，结果却被海盗拆成了废铁。冒险者受命前往海盗的上层营地，在造成进一步损失前找回散落的零件。",h="“Parts and...",kw={"复杂零件","机器","parts and pieces","海盗","海盗们","棘齿城","弯刀","上层海盗营地","卑鄙的维尼克斯"},ang={["profession:Engineering"]="技师和工程师们一定能体会到这一讽刺：一台精密的机械装置，竟然败给了粗野的海盗。打捞维尼克斯的复杂零件，能让人深刻地意识到，在没有足够的物理防护下将自动化原型机部署到敌对营地是多么危险。"},sec={{t="机械方案",b="棘齿城南侧海岸的海盗活动对该港口的居民和商贩来说愈发令人头疼。为了在不浪费更多金钱雇佣无用打手的情况下解决这些掠夺者，技师卑鄙的维尼克斯决定亲自出马。在先后派出了五六个一去不复返的雇佣兵后，维尼克斯想出了一个似乎更高明的替代方案：派出一台自动化机器来对付海盗。与其让其他活人去冒险，不如让这台机械构装体自主解决营地的问题。"},{t="弯刀与螺丝刀",b="The inventive deployment did not go as smoothly as planned. The pirates occupying the encampments south of town proved surprisingly resourceful with their blades, quickly discovering that curved scimitars could double as makeshift screwdrivers. Before Wrenix could send instructions directing the machine to retreat back toward Ratchet, the marauders pried the mechanism apart and scattered its delicate components all over their upper camp. Now, instead of eliminating the pirate presence, the inventor requires a daring scout to slip into the encampment and gather up five handfuls of the complicated mechanical parts left behind in the dirt."}},faq={{q="谁是卑鄙的维尼克斯？",a="卑鄙的维尼克斯是一位住在中立港口城市棘齿城的古怪技师。面对南侧海岸的一群气焰嚣张的掠夺者，维尼克斯试图通过技术创新来解决海盗问题。在几名雇佣兵相继丧命后，他制造并派出了一台自动化机器来应对威胁，结果很快就被拆毁了。",al={"谁是维尼克斯","卑鄙的维尼克斯背景","棘齿城 维尼克斯"}},{q="维尼克斯之前雇佣的那些佣兵怎么了？",a="在诉诸机械自动化之前，维尼克斯雇佣了五六个不同的冒险者来消灭棘齿城南面的海盗威胁。没有一个人活着回来，这证明了海盗营地是何等致命且防御森严。他们的惨死让维尼克斯断定，依赖血肉之躯的雇佣兵既低效又致命。",al={"维尼克斯之前的佣兵","其他冒险者发生了什么","维尼克斯先派了谁"}},{q="维尼克斯为什么要派一台机器去对付海盗？",a="维尼克斯制造并派遣了这台机械装置，因为他之前使用真人士兵的尝试彻底失败，导致了人员伤亡。他相信钟表驱动的造物可以在凡人战士倒下的地方取得成功——或者至少避免进一步的伤亡——于是他直接将机器送进了营地，期待着机械的巧妙设计能压制住海盗。",al={"为什么要派机器","维尼克斯的机器人计划","维尼克斯为何使用机械装置"}},{q="海盗是如何拆毁维尼克斯的机器的？",a="在面对维尼克斯的构装体时，海盗们展现出了惊人的创造力。掠夺者们用弯刀充当临时螺丝刀，在维尼克斯发出指令让机器撤回棘齿城之前，就迅速将机器拆散了。他们把装置拆得只剩下框架，并将错综复杂的组件扔得到处都是。",al={"机器是如何被摧毁的","海盗如何拆毁机器人","海盗 弯刀 螺丝刀"}},{q="那些复杂的零件在哪里？",a="The components of Wrenix's shattered machine are located within the upper pirate camp situated along the coastline south of Ratchet. After stripping the device with their scimitars, the pirates left its intricate pieces scattered on the ground throughout their hilltop camp. Adventurers must slip into the camp and collect five handfuls of these complicated parts.",al={"零件在哪里","上层海盗营地位置","复杂零件收集地点"}},{q="为什么维尼克斯认为这个回收任务更安全？",a="Wrenix believes this assignment offers far better odds of survival because it is purely a salvage operation rather than an open assault. The previous mercenaries were instructed to eradicate the pirate presence directly, whereas this retrieval mission simply requires slipping into the upper encampment, gathering five handfuls of scattered machine components from the dirt, and returning to Ratchet.",al={"parts and pieces任务安全吗","为什么维尼克斯认为你能存活","维尼克斯的生存几率分析"}},{q="“复杂零件”有什么用？",a="这些复杂零件是为维尼克斯的自动化构装体提供动力的特制齿轮、弹簧和精密机械配件。由于他消灭海盗的尝试最终导致机器被拆，维尼克斯需要找回这些精密的零件，以免他宝贵的工程工艺和材料彻底浪费。",al={"什么是复杂零件","维尼克斯为什么要零件","维尼克斯用零件做什么"}}},fp="16,415,21.598.0,26.644.0,27.407.0,54.378.0,51.380.0,47.374.0,40.364.0,56.400.0,42.357.0"}
P.entries["quest:97257"] = {n="Call of Fire",s="Call of Fire 是由天空之墙内的塑风者所监督的萨满祭司成年礼。初学者必须协助召唤烈焰之灵，捕获 Eternal Flame，并与时间赛跑，在瓦拉纳尔点燃火盆。成功完成这项试炼证明了对元素的尊重，并让初学者获得他们的火焰图腾。",h="Call of Fire 是由天空之墙内的塑风者所监督的萨满祭司成年礼。初学者必须协助召唤烈焰之灵，捕获 Eternal...",kw={"call of fire","eternal flame","火焰图腾","firelands","olariaan","天空之墙","瓦拉纳尔","塑风者"},ang={["class:Shaman"]="这个仪式标志着萨满祭司的关键成年礼，赋予他们对火焰的掌控力，并在完成后授予他们火焰图腾。",["race:Skyborne"]="该试炼由天空之墙的塑风者管理，反映了尊崇元素位面的天空萨满传统。"},sec={{t="烈焰仪式",b="Call of Fire 是在天空之墙内进行的一种神圣的元素调和试炼。在塑风者的 Olariaan 的带领下，初学者聚集在 Brazier of Offering 旁，召唤来自 Firelands 的烈焰之灵。如果供品被认为值得，烈焰之灵就会用神圣的 Eternal Flame 点燃祭坛，等待有志之士来驾驭它。"},{t="前往瓦拉纳尔",b="一旦点燃，Eternal Flame 必须被捕获到火炬上，并迅速穿过天空之墙运送到瓦拉纳尔。由于 Firelands 的能量在元素空气位面的旋涡大气中自然会减弱和消散，初学者必须与时间赛跑，在火焰熄灭前到达 Brazier of Eternal Flames 处。"},{t="火焰图腾",b="在瓦拉纳尔重新点燃火盆证明了初学者对元素的纪律和敬畏。为了表彰这一成就，塑风者会授予初学者他们的火焰图腾。正如长者所教导的那样，元素之力乐于服务尊重它的人，但会无情地吞噬那些不尊重它的人。"}},faq={{q="什么是 Call of Fire？",a="Call of Fire 是一种神圣的成年礼，在此仪式中，有抱负的萨满祭司会协助召唤烈焰之灵并捕获 Eternal Flame。将这神圣之火带到瓦拉纳尔证明了初学者对元素位面的尊重，并使他们获得火焰图腾。",al={"call of fire 是什么","call of fire 任务","这个任务的内容是什么"}},{q="Olariaan 是谁？",a="Olariaan 是指导 Brazier of Offering 仪式的主祭。他将必要的材料放在祭坛上，并召唤烈焰之灵来点燃 Eternal Flame。",al={"olariaan 是谁","olariaan 的职责","谁发起了仪式"}},{q="什么是 Eternal Flame？",a="Eternal Flame 是在塑风者仪式中从 Firelands 召唤而来的烈焰之灵的显现。初学者必须将其捕获到火炬上，并点燃瓦拉纳尔的 Brazier of Eternal Flames。",al={"什么是 eternal flame","天空之墙的 eternal flame"}},{q="为什么必须尽快将火焰带到瓦拉纳尔？",a="召唤出的原始元素之火起源于 Firelands，其强烈的热量在天空之墙这个以空气为主导的位面中会迅速消散。初学者必须迅速行动，以确保火炬在到达瓦拉纳尔之前不会熄灭。",al={"为什么 eternal flame 会消散","为什么要赶往瓦拉纳尔","天空之墙的 firelands 之火"}},{q="谁是塑风者？",a="塑风者是居住在天空之墙的一个组织，他们引导初学者通过元素试炼。他们尊崇元素位面的平衡与力量，并监督图腾的授予。",al={"谁是塑风者","塑风者派系"}},{q="完成试炼的奖励是什么？",a="完成仪式并成功重新点燃瓦拉纳尔的火盆，初学者将获得他们的火焰图腾，这是引导炽热元素之力的重要工具和焦点。",al={"call of fire 奖励","火焰图腾奖励","完成 call of fire 能得到什么"}}},fp="12,332,19.355.0,23.333.0,14.322.0,25.262.0,16.197.0,26.213.0,50.237.0,24.187.0,44.172.0"}
P.entries["quest:97263"] = {n="Your Package Has Arrived",s="“Your Package Has Arrived”是一个关于在铁炉堡投递的失落邮件的紧急快递任务。一个从蛮锤部族的堡垒鹰巢山一路寄来的快递板条箱被遗弃在邮箱旁边，收件人明确写着Eldrun Stormbreaker。发现包裹的旅行者需要完成投递任务，确保它到达其合法的收件人手中。",h="“Your Package Has Arrived”是一个关于在铁炉堡投递的失落邮件的紧急快递任务。一个从蛮锤部族的堡垒鹰巢山一路寄来的快递板条箱被遗弃在邮箱旁边，收件人明确写着Eldrun...",kw={"鹰巢山","eldrun stormbreaker","铁炉堡","邮箱","错置的包裹","紧急投递","蛮锤","your package has arrived"},ang={["faction:Alliance"]="在辛特兰和铁炉堡之间保持开放和可靠的通讯路线，对于联盟在卡兹莫丹和北部领土的利益至关重要。",["race:Dwarf"]="矮人们会认可铁炉堡的铜须部族与他们身处鹰巢山的蛮锤表亲之间紧密的联系，这使得这个包裹的安全抵达成为关乎部族尊严的大事。"},sec={{t="错置的货运",b="一次邮政失误导致几个遗失的包裹被丢弃在城市邮箱旁，它们被暴露在外，而没有安全地送到目的地。在这堆被忽视的杂乱货物中，有一个标记为紧急投递的包裹，它是从辛特兰的蛮锤矮人山地据点——鹰巢山一路寄来的。在卡兹莫丹和洛丹伦的遥远前哨站之间运输货物可能充满危险和混乱，这意味着偶尔需要警觉的过路人介入，妥善完成投递路线。"},{t="寄给Eldrun Stormbreaker的包裹",b="这个被放错位置的包裹上清楚地贴着标签，标明铁炉堡为目的地，Eldrun Stormbreaker为最终收件人。包裹上明确标有紧急通知，无论这个包裹里装的是什么货物，都被认为重要到需要从辛特兰的乡村山峰加急运送到矮人首都的地下大厅。拿起这个板条箱就意味着承担起邮政服务的责任，确保Eldrun收到这件跨越山脊和荒原寄来的物品，以免它被盗走或彻底遗忘。"}},faq={{q="邮箱旁发现的包裹是什么？",a="这个包裹是一件从辛特兰的鹰巢山寄出的紧急快递，收件人是铁炉堡的一位名叫Eldrun Stormbreaker的人。它似乎在正常的快递处理过程中没有到达最终目的地，而是与其他几个包裹一起被错放在了邮箱旁边。",al={"包裹是什么","错置的包裹","邮箱旁边丢了什么","邮箱包裹"}},{q="谁是Eldrun Stormbreaker？",a="Eldrun Stormbreaker是这件在矮人首都铁炉堡内被错置的包裹的指定收件人。虽然包裹上清楚地写着他们的名字并注明了加急，但在包裹安全送到他们手中之前，Shipping Label上并没有透露太多其他信息。",al={"谁是eldrun stormbreaker","eldrun stormbreaker","谁收到包裹","包裹收件人"}},{q="包裹是从哪里寄出的？",a="这批货物始发于鹰巢山，这是蛮锤部族位于辛特兰群山之中的重要定居点和堡垒。标签显示它在前往铁炉堡的途中，在经过路线上的当地邮箱附近被错放了。",al={"包裹从哪里来","包裹起源","它是从哪里寄出的","鹰巢山投递"}},{q="为什么包裹被标记为紧急？",a="Shipping Label上带有紧急标签，是因为从鹰巢山寄出板条箱的人认为其内容或到达时间非常重要。考虑到蛮锤高地与铁炉堡城之间横跨的领土距离，延迟的货物可能会给Eldrun Stormbreaker造成重大麻烦。",al={"为什么是紧急的","紧急投递","包裹里有什么","为何紧急"}},{q="为什么包裹被丢在邮箱旁边？",a="几个包裹莫名其妙地被丢弃在邮箱旁，而不是由当地的快递员进行分拣和配送。繁重的快递流量、后勤混乱或单纯的疏忽经常导致货物在运输途中暂时失落，这需要乐于助人的冒险者来解决这一失误。",al={"为什么它被遗弃了","为什么包裹被丢弃","丢失的邮件","错置的包裹"}},{q="这个包裹需要送到哪里？",a="这个包裹标明要投递到铁炉堡，明确指名交给Eldrun Stormbreaker。任何发现这批失落货物的人都必须承担起快递员的角色，将这个紧急包裹直接带给身处地下矮人要塞城市里的Eldrun。",al={"我该送到哪里","包裹目的地","投递地点","我该把包裹带给谁"}},{q="鹰巢山和铁炉堡之间有什么联系？",a="鹰巢山是蛮锤矮人的心脏，而铁炉堡是铜须部族的宏伟王座。虽然这些部族维持着各自独特的习俗和家园，但辛特兰的峭壁和Great Forge的地下大厅之间依然流动着定期的通信、贸易和亲缘关系。",al={"鹰巢山和铁炉堡","蛮锤与铜须贸易","铁炉堡鹰巢山联系","为什么要从鹰巢山寄信"}}},fp="24,396,17.550.0,32.548.0,41.295.0,27.291.0,31.271.0,33.314.0,46.312.0,45.278.0,56.302.0"}
P.entries["quest:97275"] = {n="Whuut's the Rush",s="“Whuut's the Rush”是一个炼金术差事，突显了天赋与严谨工艺之间的张力。Yelmak委托一位冒险者将一瓶不起眼、精心调制的药剂送给他的天才学徒Whuut，以此展示真正的大师从日常植物开始，而不是浪费稀有试剂。",h="“Whuut's the...",kw={"炼金术","黑莲花","香蒲","草药学","山鼠草","药剂","长矛草","whuut","yelmak"},ang={["faction:Horde"]="Yelmak教导有抱负的炼金术师如何保持耐心、足智多谋，以及尊重当地的卡利姆多原料，而不是挥霍宝贵的物资。",["profession:Herbalism"]="采集者和草药师会领会这个差事核心的教训：了解像长矛草和香蒲这样的日常杂草的特性，对于这门手艺来说，可能与寻找传奇花朵同样重要。"},sec={{t="急切的天才",b="在繁忙的炼金药店里，天赋往往会与鲁莽的野心发生碰撞。Whuut被公认为一位真正的天才，在搅拌棒背后有着极高的本能。然而，他的急躁导致他在尚未打下扎实的酿造技术基础前，就耗尽了店里最稀有的试剂。在还没学会普通草药的细微平衡之前，他就去寻找那些传奇植物，把炼金术当成了一场竞赛，而不是一门学科。"},{t="瓶中的一课",b="为了在不压抑Whuut热情的情况下约束他，Yelmak将一课浓缩进了一个药瓶里。Yelmak没有责骂Whuut，而是用普通的长矛草和香蒲通过快速药剂法调制了一种精致的药剂。当这位年轻人在对着黑莲花和山鼠草做白日梦时，这份朴素的混合物被交到了他手中，揭示了真正的炼金术造诣源于技术、耐心以及对日常植物的尊重。"}},faq={{q="Whuut是谁？",a="Whuut是一位年轻的炼金术天才，急于尝试现存最稀有的草药。虽然他无疑很有天赋，但他急于使用异域试剂进行调制，导致他忽略了炼金术的基础。",al={"whuut是谁","whuut背景故事","关于whuut"}},{q="Yelmak是谁？",a="Yelmak是一位经验丰富的炼金术师，在店里担任导师。由于担心Whuut在浪费宝贵的补给，Yelmak调制了一种简单的药剂，以证明真正的大师是从不起眼的本地原料开始的。",al={"谁给这个任务","yelmak的角色","yelmak是谁"}},{q="为什么Yelmak让你送药剂给Whuut？",a="Yelmak想要教会Whuut炼金术基础中的耐心与尊重。通过展示即使使用长矛草和香蒲这样的普通植物也能调制出有效的药剂，他希望抑制Whuut直接冲向那些未经研究的稀有草药的习惯。",al={"yelmak的课程是什么","为什么yelmak要送药剂","任务的核心目的"}},{q="Yelmak在他的药剂里使用了什么原料？",a="Yelmak调制这瓶示范药剂时，只使用了普通的长矛草和香蒲，向他的学徒证明，当以细致的手法进行准备时，普通的路边植被也能产生惊人的效果。",al={"药剂里有什么","yelmak药剂试剂","快速药剂原料"}},{q="Whuut试图使用哪些稀有试剂？",a="在被打断之前，Whuut正急切地去抓艾泽拉斯最珍贵和传奇的植物，特别是黑莲花和山鼠草，完全跳过了日常原料。",al={"whuut在调制什么","whuut想要的稀有草药","whuut使用了什么试剂"}},{q="Whuut学到教训了吗？",a="在品尝了药剂并了解了其朴素的配方后，Whuut惊讶于普通植物竟然能调制出这样的药水。他虚心地承认Yelmak是对的，并决定更加关注他之前忽视的日常植物。",al={"whuut改变主意了吗","whuut对药剂的反应","whuut's the rush的结果"}}},fp="16,323,17.474.0,18.436.0,13.227.0,14.226.0,49.251.0,46.216.0,50.207.0,28.240.0"}
P.entries["quest:97277"] = {n="Grund and Gozwin",s="Grund and Gozwin讲述了西北部雪山营地的一次伏击事件，一名矮人和一名侏儒遭到了雪豹的袭击。虽然侏儒在伙伴的猎枪掩护下幸存了下来，但他珍贵的戈兹温的机械日志却在混乱中遗失了。冒险者们被派往山中取回这些精密的笔记，并除掉那只潜伏的野兽。",h="Grund and...",kw={"矮人","侏儒工程师","gozwin","grund","机械陆行鸟","机械日志","潜行雪豹"},ang={["profession:Engineering"]="Gozwin因丢失戈兹温的机械日志而产生的焦虑，体现了工匠们对于机械陆行鸟的设计和专有笔记是多么看重。",["race:Dwarf"]="Grund迅速的猎枪反应和坚定的篝火情谊，体现了矮人在与侏儒盟友结伴旅行时所展现出的坚定忠诚。",["race:Gnome"]="Gozwin体现了典型的侏儒工匠形象，在从凶猛的捕食者袭击中幸存下来后，他的第一反应是担心自己的机械陆行鸟蓝图的安全。"},sec={{t="篝火旁的伏击",b="当矮人Grund和他的侏儒伙伴Gozwin在雪山中旅行时，他们在晚上搭起了营地。就在Grund转过身准备在火上烤野猪肉时，一只潜行雪豹从灌木丛中猛扑出来，咬住了Gozwin。Grund反应迅速，拿起他那把可靠的猎枪向野兽头顶上方开了一枪，这只捕食者受惊之下丢下侏儒，逃入了寒冷的岩壁之中。"},{t="工匠遗失的作品",b="虽然Gozwin从猫科动物的利齿下逃脱，身上只有深浅不一的抓痕而没有致命伤，但他们的营地已被彻底搅乱。在撤退的混乱中，Gozwin弄丢了他珍贵的戈兹温的机械日志——一本包含他机械陆行鸟关键蓝图的技术笔记本。这名饱受惊吓的侏儒因为担心自己的工程秘密被别人发现而焦急万分，直到一位冒险者同意前往西北部的山中寻回他的日志并除掉那只潜行的捕食者，他才得以安心。"}},faq={{q="Grund和Gozwin是谁？",a="Grund是一名使用猎枪的矮人露营者，Gozwin是他的侏儒工程师伙伴。当他们在雪山中扎营准备烤野猪肉时，他们遭到了潜行雪豹的伏击，导致Gozwin受伤，装备散落一地。",al={"grund和gozwin是谁","grund gozwin"}},{q="是什么袭击了营地里的Gozwin？",a="当Grund正在准备晚餐时，一只凶猛的潜行雪豹从背后伏击了Gozwin。这只野兽咬住了侏儒，正试图把他拖走，Grund开了一记警告射击，吓跑了这只猫科动物。",al={"什么袭击了gozwin","谁袭击了gozwin"}},{q="为什么戈兹温的机械日志对他如此重要？",a="戈兹温的机械日志包含了关于他机械陆行鸟的重要技术蓝图和笔记。Gozwin担心如果其他人得到了他的私人工程笔记，他的项目就会彻底毁了。",al={"为什么日志很重要","gozwin的机械日志"}},{q="Gozwin在袭击中伤得有多重？",a="是的，多亏了Grund迅速开出的那一枪，Gozwin在伏击中幸存了下来。他虽然带着深层的抓痕和严重的惊吓，但在Grund的照料下正在安全地恢复。",al={"gozwin还好吗","gozwin幸存了吗"}},{q="Grund和Gozwin的营地在哪里？",a="这对伙伴的营地坐落在西北部的山中。冒险者们被派遣到该营地取回丢失的日志，并消灭潜伏在周围区域的雪豹捕食者。",al={"营地在哪里","grund的营地位置"}},{q="Grund准备的食物怎么了？",a="在Grund的枪声吓跑了潜行雪豹后，那只野兽又回到了被遗弃的营地，吃掉了Grund原本为晚餐准备的烤野猪肉。",al={"烤野猪肉怎么了","雪豹吃野猪"}}},fp="16,367,21.439.0,22.493.0,25.241.0,29.221.0,51.222.0,40.175.0,41.187.0,46.182.0"}
P.entries["quest:97279"] = {n="Wayward Weapons",s="Wayward Weapons是试炼谷的一项早期训练任务，由监工高内克发布。随着年轻的战士们源源不断地加入部落，武器装备变得愈发匮乏。为了证明纪律性并支持营地，新兵们必须搜寻灌木丛，找回那些能力不足的前任留下的装备。",h="Wayward Weapons是试炼谷的一项早期训练任务，由监工高内克发布。随着年轻的战士们源源不断地加入部落，武器装备变得愈发匮乏。为了证明纪律性并支持营地，新兵们必须搜寻灌木丛，找回那些能力不足的前任留下的装备。",kw={"杜隆塔尔","高内克","克赞·荆条","新兵","回收","大兽穴","训练武器","试炼谷"},ang={["class:Warrior"]="尊重武器是任何战士的基础。回收失败新兵丢弃的武器，在真正的战斗开始前就强调了纪律和自力更生的重要性。",["faction:Horde"]="部落在杜隆塔尔通过坚韧和足智多谋生存下来，即使是那些不称职的人丢弃的武器，他们也拒绝浪费。",["profession:Blacksmithing"]="在杜隆塔尔，每一块金属都很重要。帮助克赞回收损毁的装备，体现了铁匠回收铁料并将残破边缘重铸为可用战争工具的职责。"},sec={{t="为新血武装",b="试炼谷是新兵们在杜隆塔尔残酷的红色荒原中经受考验的熔炉。随着无数渴望为大酋长效忠的志士挺身而出，营地的武器库存已到了极限。武器匠克赞·荆条忙于应付需求，尤其是当早期的训练因未准备好的学员而变得致命或充满挫败感时。"},{t="足智多谋的考验",b="监工高内克将这种短缺转化为一项实际的考验。他不愿浪费金属，而是指引新到达的学员去回收那些失败的新兵在尘土中倒下或逃跑时丢弃的残破利刃和钝重训练武器。将这些回收的武器交给克赞，使铁匠能够修理并回火这些装备以供下一批学员使用，这同时也教导新学员：在部落中生存，既需要挥舞钢铁，也需要学会回收利用。"}},faq={{q="为什么地上会有这么多废弃的训练武器？",a="并非每一个踏入试炼谷的希望之星都拥有部落所要求的力量或决心。胆怯或粗心的新兵经常会在恐慌中丢下装备，或者倒在当地的野猪和蝎群面前，导致配发的武器散落在尘土中。",al={"为什么地上会有武器","杜隆塔尔废弃武器","失败新兵的武器"}},{q="克赞·荆条是谁？",a="克赞·荆条是驻守在试炼谷大兽穴内的驻地武器匠。他负责为新兵装备武器、修理受损的训练器材，并维护部落在新手谷地的军事物资。",al={"克赞·荆条背景故事","克赞是谁","武器匠克赞"}},{q="是谁发布了这个任务？",a="站在大兽穴外面的监工高内克分配了这个任务。他注视着到来的志士，评估他们的基本潜力，并派遣他们去处理试炼场周边的紧急需求。",al={"谁给予了wayward weapons任务","高内克任务"}},{q="克赞会用这些回收的武器做什么？",a="克赞会修理、磨快并修复那些受损的练习武器。由于杜隆塔尔资源稀缺且不断有新兵涌入，回收的铁器和木材必须重新利用，以训练下一批学员。",al={"训练武器会怎样","克赞修理武器"}},{q="这个任务发生在什么地方？",a="它发生在试炼谷，这是一个位于杜隆塔尔南部的孤立峡谷，年轻的兽人和暗矛巨魔在这里开启他们作为部落战士的道路。",al={"试炼谷位置","wayward weapons在哪里"}},{q="为什么部落不干脆锻造全新的武器？",a="杜隆塔尔是一片崎岖干旱的土地，容易获取的铁矿储备有限，年轻的部落承担不起浪费。回收落选者的练习用刃可以确保原始金属被保留给前线部队。",al={"为什么要回收武器","杜隆塔尔金属短缺"}}},fx={c966be67={q="高内克为什么要收集被遗弃的武器？",a="试炼谷新兵不断涌入，营地的军械库因此不堪重负。武器匠克赞缺少练习用的装备，高内克必须确保补给充足，以训练下一批新兵。让你搜遍营地既能解决短缺，也能让高内克检验你在山谷中的勤勉程度和生存能力。",al={"高内克的动机","高内克为什么要武器","为什么收集被遗弃的训练武器"}},["42aac14b"]={q="被遗弃的训练武器有什么用？",a="这些粗制的刀剑和钝器曾属于过去那些不合格或未能完成试炼便已丧命的新兵。它们散落在地上，却依然足够结实，可以修复。你把它们交给克赞·荆条后，他会修理并磨利武器，让未来的新兵有装备可用。",al={"被遗弃的训练武器用途","被遗弃的武器有什么用","被遗弃的训练武器的用途"}},["056af0db"]={q="高内克为什么派新兵去，而不派卫兵？",a="试炼场的存在，就是为了淘汰弱者、选出能干的战士。派老练的卫兵去收拾失败新兵留下的烂摊子，是在浪费老兵的人力；派你去则一举两得：你可以在野外猎杀野猪，积累实战经验，同时证明自己能听从命令并维持营地所需。",al={"为什么不派卫兵","高内克为什么派我去","为什么派新兵去收集武器"}}},fp="15,323,20.384.0,25.431.0,62.279.0,23.243.0,21.204.0,46.201.0,33.160.0,54.215.0"}
P.entries["quest:97281"] = {n="A Simmering Storm",s="当一名冒险者从枯水谷的鹰身人手中夺回一件名为 Dull Stormy Orb 的奇异放电圣物时，A Simmering Storm 便开始了。将这团旋转的微型风暴带给地精技师雷兹拉克，可以了解到鹰身人这些奇怪饰品的来历，并引起棘齿城那些富有进取心的打捞者们的兴趣。",h="当一名冒险者从枯水谷的鹰身人手中夺回一件名为 Dull Stormy Orb 的奇异放电圣物时，A Simmering Storm...",kw={"a simmering storm","枯水谷","dull stormy orb","杜隆塔尔","dustwind","加兹鲁维","鹰身人","雷兹拉克"},ang={["class:Shaman"]="宝珠内包含的微型电风暴反映了原始元素的力量，尽管在这种简陋的容器中驾驭它，让人对鹰身人的手段产生了疑问。",["faction:Horde"]="在枯水谷附近协助地精雷兹拉克的部落冒险者，通过从威胁杜隆塔尔峡谷的敌对鹰身人手中回收的物品，帮助保护了神秘的魔法圣物。",["profession:Engineering"]="像雷兹拉克这样的修补匠和工程师天生就被那些带有不稳定电荷和内部翻腾雾气的奇物所吸引。"},sec={{t="尘土中的火花",b="在与盘踞在整个枯水谷的侵略性极强的 Dustwind 鹰身人交战时，旅行者可能会发现一件不同寻常的奇物：Dull Stormy Orb。虽然它的外表看起来暗淡磨损，但握住它时，能感受到一股原始电流持续不断的振动。在球体内部，黑色的雾气不停翻涌，并不时被内部产生的尖锐火花照亮。这是鹰身人通过奇怪的圣物操纵风暴魔法的铁证。"},{t="地精的好奇心",b="与其让这种不稳定的魔法留在野蛮的鹰身人利爪之中，不如直接将宝珠带给雷兹拉克。这位务实的地精技师驻扎在枯水谷入口处，他对这件奇怪的圣物产生了浓厚的兴趣，并指出它的发现让他想起了他在棘齿城的雇主——首席工程师加兹鲁维——曾给出的古老建议。无论鹰身人想用这股微型风暴酝酿什么，现在它都落入了地精的手中。"}},faq={{q="什么是 Dull Stormy Orb？",a="Dull Stormy Orb 是从杜隆塔尔的一只鹰身人身上回收的奇异魔法古玩。尽管外表暗淡，但它内部嗡嗡作响，带有微弱的电流、翻腾的黑雾和周期性的火花。",al={"什么是 dull stormy orb","风暴宝珠","来自鹰身人的宝珠"}},{q="谁想要 Dull Stormy Orb？",a="这颗宝珠被带给了雷兹拉克，他是一位驻扎在杜隆塔尔枯水谷外的地精侦察兵，对奇异的古玩和有价值的打捞品有着敏锐的眼光。",al={"谁需要 dull stormy orb","上交风暴宝珠","把宝珠带到哪里"}},{q="为什么鹰身人会有这颗宝珠？",a="其具体用途尚不清楚，但枯水谷的鹰身人显然是在利用这颗宝珠来引导或容纳电气和风暴元素能量。",al={"鹰身人用宝珠做什么","为什么鹰身人有风暴宝珠","鹰身人宝珠的用途"}},{q="雷兹拉克是谁？",a="雷兹拉克是在杜隆塔尔北部枯水谷附近工作的一名地精特工，隶属于热砂港，效命于棘齿城的首席工程师加兹鲁维。",al={"雷兹拉克是谁","杜隆塔尔的雷兹拉克","枯水谷附近的地精"}},{q="枯水谷在哪里？",a="枯水谷是杜隆塔尔北部的一个崎岖峡谷系统，到处是充满敌意的 Dustwind 鹰身人，它们骚扰旅行者，破坏当地的贸易和定居点。",al={"枯水谷在哪里","枯水谷位置","杜隆塔尔鹰身人峡谷"}},{q="雷兹拉克对这颗宝珠有什么看法？",a="看到宝珠后，雷兹拉克立刻想起了他的老板——首席工程师加兹鲁维——关于奇异且可能有利可图的怪物的教诲和评论。",al={"雷兹拉克关于加兹鲁维说了什么","雷兹拉克和加兹鲁维的关系"}}},fp="17,323,19.481.0,16.429.0,28.209.0,30.161.0,34.166.0,14.157.0,25.164.0,34.169.0"}
P.entries["quest:97282"] = {n="Stormy Potential",s="Stormy Potential是杜隆塔尔的一个任务，由枯水谷附近的哥布林雷兹拉克提供。雷兹拉克希望能保护他的贸易商队免受掠夺成性的鹰身人的侵害，因此他试图利用本地雷蜥强大的带电器官来为一颗耗尽能量的宝珠充能。",h="Stormy Potential是杜隆塔尔的一个任务，由枯水谷附近的哥布林雷兹拉克提供。雷兹拉克希望能保护他的贸易商队免受掠夺成性的鹰身人的侵害，因此他试图利用本地雷蜥强大的带电器官来为一颗耗尽能量的宝珠充能。",kw={"带电器官","枯水谷","杜隆塔尔","加兹鲁维","鹰身人","宝珠","雷兹拉克","stormy potential","雷蜥"},ang={["faction:Horde"]="雷兹拉克的行动支持着部落在杜隆塔尔的立足点和交通往来，而来自枯水谷的掠夺成性的鹰身人威胁着这里的旅行者和补给商队。",["profession:Engineering"]="利用雷蜥体内不稳定的生物能量来激活休眠装置是典型的哥布林式发明，尽管其安全系数几乎为零。"},sec={{t="把握机会",b="在杜隆塔尔枯水谷的阴影附近，哥布林雷兹拉克发现自己面临两个问题：商队受到当地鹰身人的持续威胁，以及一颗完好无损但能量耗尽的魔法宝珠。雷兹拉克想起了棘齿城首席工程师加兹鲁维的实用建议——机会来临时要果断把握——于是他制定了一个雄心勃勃的计划，通过为这件休眠的装置充能来同时解决这两个问题。"},{t="驾驭风暴",b="为了恢复这颗干涸的宝珠，雷兹拉克需要一个强大且直接的原始电力来源。枯水谷以西的峡谷里栖息着雷蜥——这些生物以其能够产生和传导致命雷电的内脏器官而闻名。通过派遣冒险者去收集这些带电的器官，雷兹拉克希望安全地将它们不稳定的电流直接导入装置中，从而使他脆弱的补给货车在面对未来的鹰身人伏击时拥有强大的防御力。"}},faq={{q="谁提供了Stormy Potential这个任务？",a="Stormy Potential由驻扎在杜隆塔尔枯水谷附近的哥布林商人和技工雷兹拉克提供。他采纳了加兹鲁维关于把握机会的建议，试图利用当地野兽天然的带电特性来恢复一颗未充能的宝珠。",al={"谁提供stormy potential","雷兹拉克在哪里","雷兹拉克任务提供者"}},{q="雷兹拉克想用这些器官为什么充能？",a="雷兹拉克拥有一颗完好无损但能量耗尽的宝珠。他希望利用雷蜥的带电器官将其重新充满能量，这样他就能保护他的商队免受该地区鹰身人的骚扰。",al={"雷兹拉克在为充能什么","为什么需要雷蜥器官","雷兹拉克的宝珠用途"}},{q="雷蜥在哪里可以找到？",a="雷蜥栖息在杜隆塔尔枯水谷附近，雷兹拉克所在位置以西的一个峡谷中。猎人们必须收集它们的带电器官并带回给雷兹拉克。",al={"在哪里寻找雷蜥","杜隆塔尔雷蜥位置","器官在哪里"}},{q="为什么收集雷蜥器官很危险？",a="尽管名字里带有“雷”，但雷蜥不仅仅是咆哮，它们还会释放危险的闪电。正如雷兹拉克所警告的那样，它们的电击往往会给大多数旅行者上一堂终生难忘的痛苦课程。",al={"为什么雷蜥有闪电","雷蜥会使用闪电吗"}},{q="雷兹拉克为什么害怕鹰身人？",a="雷兹拉克的商队遭到了盘踞在枯水谷的敌对鹰身人的伏击。他打算将这颗充能后的宝珠作为威慑手段或武器，让鹰身人在再次袭击他的货物前三思而后行。",al={"雷兹拉克为何需要防御","谁袭击了雷兹拉克","鹰身人袭击商队"}},{q="雷兹拉克与加兹鲁维有什么联系？",a="雷兹拉克视棘齿城的首席工程师加兹鲁维为经验丰富的导师和商业灵感来源。雷兹拉克在制定为宝珠充能的计划时，明确引用了加兹鲁维关于把握机会的商业哲学。",al={"加兹鲁维对雷兹拉克来说是谁","雷兹拉克加兹鲁维建议"}}},fp="16,255,19.421.0,20.486.0,37.266.0,48.233.0,36.167.0,45.207.0,33.210.0,39.234.0"}
P.entries["quest:97287"] = {n="Shrewd Negotiations",s="大法师沃迪恩·伍德格莱尔称赞了你对法师之城的渗透，并表示现在是时候进行一些谈判了。你需要将你获得的奥术微粒带给达拉然的大法师塞琳德拉。",h="大法师沃迪恩·伍德格莱尔称赞了你对法师之城的渗透，并表示现在是时候进行一些谈判了。你需要将你获得的奥术微粒带给达拉然的大法师塞琳德拉。",kw={"奥特兰克山脉","奥术微粒","大法师塞琳德拉","达拉然","肯瑞托","shrewd negotiations","沃迪恩·伍德格莱尔"},sec={{t="谈判之时",b="大法师沃迪恩·伍德格莱尔承认，在艾泽拉斯，没有任何地方在奥术知识方面能与肯瑞托相提并论，即使是他自己那些杰出的研究成果在他们古老的智慧面前也显得黯然失色。他认为现在是让部落进入这个排他性组织的时候了。你需要将你获得的微粒带给达拉然的大法师塞琳德拉，因为沃迪恩确信肯瑞托为了拿回它，什么代价都愿意付出。"}},faq={{q="是谁派你去和达拉然谈判的？",a="大法师沃迪恩·伍德格莱尔，他在你渗透了该城市后，想要采取更具谈判性的手段。",al={"谁发布谈判任务","沃迪恩·伍德格莱尔","谈判任务发布者"}},{q="你要去和谁交涉？",a="达拉然的大法师塞琳德拉。",al={"我该去找谁","塞琳德拉位置","塞琳德拉在哪里"}},{q="你有什么筹码？",a="你获得的奥术微粒。沃迪恩确信肯瑞托为了拿回它，什么代价都愿意付出。",al={"什么是奥术微粒","谈判筹码","奥术微粒"}},{q="为什么沃迪恩·伍德格莱尔想要和达拉然做交易？",a="沃迪恩承认在艾泽拉斯，没有地方在奥术知识方面能与肯瑞托相提并论，并认为现在是时候让部落获得进入他们这个排他性组织的权限了。",al={"为什么要与肯瑞托谈判","沃迪恩的动机","为什么要找达拉然"}}},fp="19,199,17.402.0,40.94.0,31.30.0,27.95.0,53.161.0"}
P.entries["quest:97288"] = {n="Unending Torment",s="Unending Torment始于一个奇怪的憎恶被击杀之时，由于缝合处反复撕裂，它的头颅随之滚落。这个遗物有着被多次切割又重新接上的痕迹，指向了被遗忘者首都内部蓄意进行的黑暗实验。将这个可怕的战利品带给幽暗城的大药剂师法拉尼尔，便能揭开其反复重组背后的扭曲幽默。",h="Unending...",kw={"憎恶头颅","憎恶","apothecarium","黑暗女王","大药剂师法拉尼尔","皇家药剂师协会","sylvanas windrunner","幽暗城","unending torment"},ang={["faction:Horde"]="见证法拉尼尔接收头颅的部落冒险者，能够直接窥见他们幽暗城盟友那令人不安的行为。尽管这些手段行之有效，但被遗忘者无休止的复活和缝合血肉的方法，常常让那些更重荣誉的盟友感到不安。",["race:Undead"]="对于被遗忘者来说，这颗头颅展示了他们的女王Sylvanas Windrunner那冷酷的幽默和不近人情的天性。它时刻提醒着人们黑暗女王的绝对权威以及皇家药剂师协会那阴森可怕的创造力。"},sec={{t="松动的缝合线",b="当那个高大的憎恶在战斗中最终倒下时，它的头颅猛然从肩膀上掉落。仔细观察会发现，它的颈部不仅仅是被切断过一次，而是被缝合、撕裂、又重新接上了无数次。随着每一次重建，缝合处变得越来越脆弱，以至于头颅几乎无法再固定在构装体的肩膀上。这种拙劣却持久的修补，即便对于亡灵构装体来说也是极不寻常的，这表明这个特定的憎恶经历了反复的毁灭与重组循环。任何检查遗骸的人很快就会意识到，普通的拾荒者无法解释这种工艺，只有幽暗城技术精湛的缝合师才能辨认出这个生物的起源。"},{t="黑暗女王的玩笑",b="将断头送到Apothecarium，便会呈现在皇家药剂师协会的领袖——大药剂师法拉尼尔面前。法拉尼尔对这个可怕的样本一点也不感到惊讶，他立刻认出了这张脸。他断定这种反复的重组并非死灵法术的意外失败，而是Sylvanas Windrunner本人精心设计的一个残酷玩笑。至于究竟是什么冒犯或轻视让这个生物受到了如此永恒且令人屈辱的惩罚，只有黑暗女王和她的核心圈子知道。法拉尼尔并没有丢弃这个破损的遗物，而是欣然接受了这颗断头，并坚信皇家药剂师协会可以将它重新用于他们正在进行的炼金和死灵实验中。"}},faq={{q="什么是憎恶头颅？",a="憎恶头颅是某个独特构装体在被击败后掉落的断头。它的颈部留下了反复重新接上的伤疤，每一次重新连接都削弱了血肉和缝合线。它是该生物所遭受的一种怪异且循环往复的惩罚的证明，促使发现者将其带到幽暗城交给大药剂师法拉尼尔进行检查。",al={"憎恶头颅背景故事","什么是憎恶头颅","憎恶头颅任务物品"}},{q="为什么头颅被重新接上了那么多次？",a="这个生物的头颅被反复缝合回身体上，作为一种折磨的手段。据大药剂师法拉尼尔所说，这个生物的状态是Sylvanas Windrunner精心策划的一个残酷玩笑。每当这个构装体倒下或失去头颅时，它就会被重新拼凑起来以继续服役或受折磨，导致颈部越来越脆弱，最终再次断裂。",al={"为什么重接头颅","为什么头颅被缝回去","unending torment头颅缝合线"}},{q="大药剂师法拉尼尔是谁？",a="大药剂师法拉尼尔是皇家药剂师协会的负责人，驻扎在幽暗城的Apothecarium。在女王Sylvanas Windrunner的授权下，法拉尼尔监督被遗忘者的药剂师们进行毒药、瘟疫和解剖改造的研究。他对黑暗女王的项目非常了解，这使他能够立即辨认出这个缝合头颅的起源。",al={"法拉尼尔是谁","大药剂师法拉尼尔背景故事","法拉尼尔幽暗城"}},{q="为什么Sylvanas认为这是一个残酷的玩笑？",a="虽然法拉尼尔没有详细说明这个生物原本的身份，但他认为这个构装体无休止的死亡与重组循环是黑暗女王的一个美妙玩笑。强迫一个生物忍受反复的毁灭，仅仅是为了让它被拙劣地复活并一次又一次地缝合回去，这体现了Sylvanas对敌人那冷酷无情的讽刺和惩罚方式。",al={"sylvanas的玩笑","为什么是黑暗女王的玩笑","黑暗女王的残酷玩笑"}},{q="法拉尼尔会用这个头颅做什么？",a="在收到这颗破损的头颅后，法拉尼尔带着阴森的笑意表示他有用处。作为皇家药剂师协会怪诞实验的监督者，他经常将死灵残骸、血肉和生物畸变体重新用于开发新的配方、瘟疫和构装体强化装置，以协助被遗忘者在不断的冲突中获益。",al={"头颅会怎样","法拉尼尔的用途","药剂师们会用它做什么"}},{q="在哪里提交Unending Torment任务？",a="通过将憎恶头颅直接带给大药剂师法拉尼尔即可完成任务。他居住在幽暗城南区的炼金侧翼——Apothecarium。被遗忘者冒险者和部落盟友可以在那里找到他，他正被沸腾的大锅、助手和实验体包围着，监督着协会的研究工作。",al={"unending torment在哪里交","unending torment任务上交","谁收走憎恶头颅"}},{q="联盟玩家可以完成这个任务吗？",a="由于任务目标要求将任务物品直接交给幽暗城Apothecarium内的大药剂师法拉尼尔，因此该任务专为部落冒险者设计。任何试图接近法拉尼尔的联盟玩家在进入他们的地下据点时，都会面临敌对的幽暗城卫兵，并会被被遗忘者处死。",al={"unending torment是部落专属吗","联盟 unending torment","联盟可以做unending torment吗"}}},fp="16,406,14.772.0,20.739.1,28.399.0,47.406.0,34.404.0,45.388.0,36.370.0,48.346.0,40.355.0"}
P.entries["quest:97289"] = {n="Unending Torment",s="Unending Torment是一个幽暗城的任务，内容涉及复活大元帅奥斯玛尔·加里瑟斯的断头。被遗忘者试图通过准备一个缝合怪作为他的新躯体，来审讯这位曾经的联盟敌人。",h="Unending Torment是一个幽暗城的任务，内容涉及复活大元帅奥斯玛尔·加里瑟斯的断头。被遗忘者试图通过准备一个缝合怪作为他的新躯体，来审讯这位曾经的联盟敌人。",kw={"憎恶","被遗忘者","加里瑟斯","大元帅","男爵的徽记","奥斯玛尔","sylvanas windrunner","幽暗城","unending torment"},ang={["faction:Alliance"]="对大元帅加里瑟斯遗骸进行毛骨悚然的复活，展示了那些在洛丹伦对抗女妖之王的联盟领袖们将面临的惨痛命运。",["faction:Horde"]="在幽暗城协助皇家药剂师学会进行复活实验，展示了被遗忘者邪恶的技艺以及他们对曾经压迫者的复仇。",["race:Undead"]="对于被遗忘者来说，对大元帅加里瑟斯的遗骸进行实验，代表了因果报应，也是对Sylvanas Windrunner征服洛丹伦的直接提醒。"},sec={{t="征服者的战利品",b="在幽暗城深处的地下实验室里，被遗忘者的从业者们用死者的遗骸缝合成了可怕的憎恶。然而，在无数保存完好的颅骨中，有一件遗物承载着非同寻常的历史怨恨：大元帅奥斯玛尔·加里瑟斯的断头。就是这位傲慢的指挥官，在死于黑暗女王之手前，曾率领联盟残部横跨洛丹伦。"},{t="墓穴的秘密",b="被遗忘者保留加里瑟斯的头颅不仅仅是为了作为战争的战利品。通过准备一具拼凑而成的憎恶躯体作为新的宿主，被遗忘者的死灵法师们意图审讯这位前大元帅，并揭开锁在他断头内的联盟秘密。当头颅被带到那具毫无生气的构造体前，拼凑而成的憎恶便涌现出痛苦的知觉，在无尽的折磨中重温其恐怖的最后时刻。"}},faq={{q="奥斯玛尔是谁？",a="奥斯玛尔指的是大元帅奥斯玛尔·加里瑟斯，他是一位臭名昭著的军事指挥官，在第三次战争后率领着洛丹伦的联盟残部。他仇视非人类种族，大药剂师法拉尼尔说，黑暗女王很乐意亲手解决他。",al={"谁是奥斯玛尔","奥斯玛尔的身份","奥斯玛尔是谁"}},{q="为什么被遗忘者要复活奥斯玛尔的遗骸？",a="被遗忘者希望从他带进坟墓的秘密中挖掘出有价值的信息。通过将他保存完好的头颅放置在准备好的憎恶宿主附近，被遗忘者可以直接从复活的遗骸中提取信息。",al={"为什么要复活奥斯玛尔","复活头颅的目的","奥斯玛尔的秘密"}},{q="奥斯玛尔是怎么死的？",a="大药剂师法拉尼尔说，黑暗女王Sylvanas Windrunner很乐意亲手解决大元帅加里瑟斯。",al={"谁杀了奥斯玛尔","奥斯玛尔是怎么死的","奥斯玛尔之死"}},{q="为什么任务物品叫“男爵的徽记”？",a="“男爵”是洛丹伦废墟中那具高大憎恶的名字，这颗头颅正是属于它的。法拉尼尔透露，这颗头颅曾经属于大元帅加里瑟斯。",al={"男爵的徽记奥斯玛尔","为什么叫男爵的徽记"}},{q="奥斯玛尔的新身体在哪里？",a="那具为了接收奥斯玛尔的头颅而建造的无头憎恶被保存在幽暗城内的一间相连的房间里，等待着被遗忘者的从业者们进行复活。",al={"奥斯玛尔的身体在哪里","憎恶位置幽暗城"}},{q="当构造体苏醒时会发生什么？",a="当被放置在拼凑好的构造体附近时，缝合的血肉会剧烈地抽搐并复活。在恢复意识后，遗骸会立刻因为重温加里瑟斯生前最后时刻的恐怖而陷入恐慌。",al={"身体苏醒时会发生什么","完成任务后的反应奥斯玛尔"}}},fp="16,241,20.422.0,20.430.1,15.264.0,50.213.0,19.136.0,51.168.0,35.176.0,40.210.0"}
P.entries["quest:97290"] = {n="Unending Torment",s="Unending Torment 是一项代表幽暗城皇家药剂师学会执行的任务。一位特使面对着一名拒绝合作的挑衅囚犯或目标，对方称请求者为憎恶。将这种抗命行为报告给大药剂师法拉尼尔后，他感到满意而非失望，因为这位药剂师领袖乐于见到折磨顽固目标的机会。",h="Unending Torment...",kw={"憎恶","apothecarium","法拉尼尔","被遗忘者","大药剂师法拉尼尔","皇家药剂师学会","幽暗城","unending torment"},ang={["faction:Horde"]="在洛丹伦活动的部落勇士经常观察到他们被遗忘者盟友身上那令人胆寒的冷酷。法拉尼尔在折磨顽固囚犯时流露出的愉悦，突显了幽暗城内部运作的黑暗实用主义。",["race:Undead"]="被遗忘者冒险者对于被活物称为憎恶早已习以为常。协助大药剂师法拉尼尔巩固了他们对皇家药剂师学会冷酷工作的承诺。"},sec={{t="阴影中的抗命",b="皇家药剂师学会经常与试验品、囚犯和怀有对被遗忘者深深仇恨的敌对实体打交道。在 Unending Torment 中，调查员会遇到一个不合作的个体，对方公开蔑视请求者，称他们为憎恶并坚决拒绝提供任何帮助。该目标绝望的抗命行为突显了许多活物或囚犯对洛丹伦亡灵所抱有的纯粹厌恶与敌意。"},{t="法拉尼尔的野心",b="将囚犯的拒绝报告给幽暗城的大药剂师法拉尼尔会产生意想不到的反应。这位皇家药剂师学会的首领并没有对缺乏进展感到沮丧，反而以一种邪恶的热情欢迎这种反抗。对法拉尼尔来说，一个坚决不从的目标并不是审讯的失败，而是一个引人入胜的挑战——这正好为在药剂师区内施行的残忍独创性和实验方法提供了机会。"}},faq={{q="什么是 Unending Torment？",a="Unending Torment 是与皇家药剂师学会相关的一项任务。冒险者会审讯或调查一名拒绝提供任何帮助并辱骂他们为憎恶的不合作囚犯或实体。冒险者随后必须将此失败的消息传达给幽暗城内的大药剂师法拉尼尔。",al={"unending torment 任务","什么是 unending torment","unending torment 背景故事"}},{q="谁给予了 Unending Torment 任务？",a="该任务始于与一名拒绝任何合作的挑衅目标互动后，对方在咒骂玩家为憎恶并将其驱赶走之后开始。在最初的交谈中，该囚犯并未透露姓名，指示受挫的冒险者将发现带回皇家药剂师学会的领导层。",al={"谁开启 unending torment","unending torment 任务给予者","在哪领取 unending torment"}},{q="大药剂师法拉尼尔是谁？",a="大药剂师法拉尼尔是皇家药剂师学会的首领，基地位于洛丹伦废墟下方的幽暗城药剂师区。他监管着被遗忘者的炼金术士和研究人员，开发新的瘟疫、药剂和毒药，以保卫被遗忘者并铲除艾泽拉斯各地的敌人。",al={"法拉尼尔是谁","大药剂师法拉尼尔","大药剂师法拉尼尔的角色"}},{q="为什么说话者称玩家为憎恶？",a="囚犯对亡灵及其代理人怀有深切的厌恶，这是活物和被遗忘者的敌人中的普遍情绪。斥责访客为憎恶反映了局外人对如今居住在幽暗城的复活亡者所感到的深层偏见与恐惧。",al={"为什么是憎恶","谁称你为憎恶","为什么囚犯很生气"}},{q="完成任务后必须向哪里汇报？",a="必须直接向幽暗城的大药剂师法拉尼尔交付来自不合作目标的调查结果。法拉尼尔居住在药剂师区的深处，周围环绕着沸腾的坩埚、实验室大桶以及致力于为 Sylvanas Windrunner 女王和被遗忘者制造致命药剂的研究同僚。",al={"在哪里上交 unending torment","unending torment 交付","向谁汇报 unending torment"}},{q="大药剂师法拉尼尔对目标的抗命有何反应？",a="大药剂师法拉尼尔对该目标顽固拒绝合作的态度感到非常满意。他并没有因为僵局而感到愤怒，反而将其视为一项有趣的挑战。这位药剂师首领热衷于使用皇家药剂师学会开创的冷酷无情的方法来测试那些棘手目标的极限。",al={"法拉尼尔的反应","法拉尼尔说了什么","法拉尼尔会生气吗"}}},fp="16,401,23.488.0,19.468.0,25.330.0,37.325.0,34.314.0,52.299.0,48.327.0,68.333.0"}
P.entries["quest:97291"] = {n="Unending Torment",s="Unending Torment是幽暗城的一个任务，大药剂师法拉尼尔试图将一个拼凑而成的俘虏束缚在黑暗女王的意志之下。为了完成这种奴役药剂，冒险者必须从被遗忘者的首都各处收集致命的试剂。",h="Unending Torment是幽暗城的一个任务，大药剂师法拉尼尔试图将一个拼凑而成的俘虏束缚在黑暗女王的意志之下。为了完成这种奴役药剂，冒险者必须从被遗忘者的首都各处收集致命的试剂。",kw={"apothecarium","blisterweed","苦楚精华","法拉尼尔","大药剂师法拉尼尔","tawny grisette","toxic skullcap","幽暗城","unending torment"},ang={["class:Rogue"]="该任务需要冒险进入Rogues' Quarter购买苦楚精华，这是一种通常受毒药制造者和刺客青睐的强效试剂。",["faction:Horde"]="皇家药剂师学会在洛丹伦废墟深处继续酿造邪恶的药剂，测试炼金术奴役的极限。",["profession:Herbalism"]="从Apothecarium的草药训练师那里获取Blisterweed，突显了标准植物学研究与学会更黑暗的炼金项目之间的重叠。",["race:Undead"]="对于被遗忘者来说，通过炼金折磨将复活的尸骸束缚在黑暗女王的麾下，是Apothecarium日常运作中的标准做法。"},sec={{t="束缚意志",b="在幽暗城Apothecarium的深处，大药剂师法拉尼尔监督着旨在增强被遗忘者力量的恐怖实验。在成功重新接上了一个饱受摧残的俘虏的断头后，法拉尼尔需要一种特殊的炼金混合物，以粉碎这个生物残存的一点反抗意志，并将其永久地束缚在Sylvanas Windrunner的意志之下。"},{t="药剂试剂",b="为了准备他的奴役药水，法拉尼尔派遣代理人穿过幽暗城去收集强效成分。这项任务包括从Trade Quarter的Tawny Grisette处获得Toxic Skullcap，从欠他债的附近草药训练师那里索取Blisterweed，并从潜伏在Rogues' Quarter的毒药商那里购买苦楚精华。"},{t="杰作",b="在收到这些成分后，法拉尼尔对他即将完成的杰作表示阴森的满意。他很期待将这种药剂在他们的“尊贵客人”身上进行测试，并确信这种痛苦的药水将剥去俘虏残存的虚张声势，使这个迷途的生物顺从地回到黑暗女王的麾下。"}},faq={{q="谁发布了Unending Torment任务？",a="该任务由皇家药剂师学会的领袖、大药剂师法拉尼尔发布，可以在幽暗城的Apothecarium找到他。",al={"谁发布了unending torment","unending torment任务发布者","unending torment起始"}},{q="法拉尼尔的药剂需要什么试剂？",a="大药剂师法拉尼尔需要三种特定的成分：从Trade Quarter的Tawny Grisette处获得的Toxic Skullcap，从Apothecarium的草药训练师附近获得的Blisterweed，以及从Rogues' Quarter的毒药商处获得的苦楚精华。",al={"有什么成分","unending torment物品","法拉尼尔需要什么试剂"}},{q="大药剂师法拉尼尔正在对谁进行实验？",a="实验对象是一个不情愿的俘虏，他的断头刚刚被重新接上。法拉尼尔嘲弄地称他为“迷途的羔羊”和“尊贵的客人”，试图粉碎他在遭受毒打后依然坚持的反抗虚张声势。",al={"这个野兽是谁","法拉尼尔提到的迷途羔羊是谁","谁在遭受折磨"}},{q="法拉尼尔的药水目的是什么？",a="这种药水旨在从精神上摧毁实验对象，并强行将其束缚在被遗忘者的黑暗女王Sylvanas Windrunner的意志之下。法拉尼尔认为该生物遭受重创的状态使其特别容易受到化学控制。",al={"为什么要制作这种药水","unending torment药水的目的","这种药剂有什么作用"}},{q="玩家可以在哪里找到Tawny Grisette？",a="Tawny Grisette位于幽暗城的Trade Quarter，她提供包括药剂师所需的Toxic Skullcap在内的特种商品。",al={"tawny grisette在哪里","toxic skullcap商人","找到grisette女士"}},{q="Blisterweed在哪里？",a="Blisterweed位于幽暗城的草药训练师Alliestars附近，他们居住在Apothecarium内。法拉尼尔提到他们欠他一个人情，允许冒险者自由拿取所需之物。",al={"在哪里找到blisterweed","alliestars草药学","幽暗城草药训练师blisterweed"}}},fp="16,252,16.382.0,19.356.0,15.336.1,38.141.0,51.254.0,51.254.0,38.253.0,38.156.0,33.205.0"}
P.entries["quest:97292"] = {n="Unending Torment",s="Unending Torment 是幽暗城的一项任务，由位于药剂师区的大药剂师法拉尼尔委派。玩家需要协助皇家药剂师学会，将腐蚀性的嘶嘶药剂倒入悬挂在 Othmar 残骸上方的滴注装置中。这项任务是对过去针对黑暗女王所犯罪行的持久报复。",h="Unending Torment 是幽暗城的一项任务，由位于药剂师区的大药剂师法拉尼尔委派。玩家需要协助皇家药剂师学会，将腐蚀性的嘶嘶药剂倒入悬挂在 Othmar...",kw={"apothecarium","黑暗女王","加里索斯","嘶嘶药剂","大药剂师法拉尼尔","othmar","幽暗城","unending torment"},ang={["faction:Horde"]="在幽暗城协助法拉尼尔，展现了被遗忘者对待那些背叛他们与女妖之王的敌人们时所采用的严酷手段。",["race:Undead"]="大药剂师法拉尼尔领导着幽暗城的皇家药剂师学会，而惩罚像加里索斯这样黑暗女王的敌人，是被遗忘者报复行动的核心。"},sec={{t="药剂师的报复",b="在幽暗城药剂师区阴暗的走廊里，大药剂师法拉尼尔正在进行严酷的实验，以确保被遗忘者的敌人永远无法安宁。为了这项任务，法拉尼尔准备了一种被称为嘶嘶药剂的腐蚀性物质，旨在无休止地滴落在悬挂于炼金设备下的受试者身上。"},{t="加里索斯的命运",b="法拉尼尔实验装置的受试者正是 Othmar，也就是大元帅加里索斯的残骸。由于他曾对黑暗女王犯下罪行，法拉尼尔认为持续的化学折磨是他应得的惩罚。药剂被导入 Othmar 躯体上方的悬挂框架中，持续灼烧他的血肉，确保这位陨落的指挥官成为承受永恒惩罚与研究的对象。"}},faq={{q="Othmar 是谁？",a="Othmar 指的是大元帅 Othmar Garithos，他曾是人类指挥官。在收复洛丹伦期间，他曾与 Sylvanas Windrunner 达成过不稳固的盟约，随后却背叛了被遗忘者并被其所杀。大药剂师法拉尼尔获得了他的残骸，以便对他进行持续的折磨与实验。",al={"othmar 是谁","othmar 是什么","othmar garithos"}},{q="为什么 Othmar 要受折磨？",a="Othmar Garithos 曾与 Sylvanas Windrunner 并肩作战，从恐惧魔王手中夺回了洛丹伦王都，但他对非人类种族怀有深深的蔑视，并试图完全为人类收复洛丹伦。被遗忘者认为他应对针对黑暗女王的罪行负责，视这种无休止的化学折磨为对他傲慢与过去行径的恰当报复。",al={"为什么要折磨 othmar","othmar 做了什么","针对希尔瓦娜斯的罪行"}},{q="谁是大药剂师法拉尼尔？",a="大药剂师法拉尼尔是幽暗城药剂师区皇家药剂师学会的负责人。他负责监督新型药剂、毒素和瘟疫的研发，并直接指挥这项针对 Othmar 的行动。",al={"法拉尼尔的角色","谁给予 unending torment 任务","大药剂师法拉尼尔"}},{q="嘶嘶药剂有什么作用？",a="嘶嘶药剂是大药剂师法拉尼尔调配的一种炼金混合物，旨在灼烧血肉并引发剧痛。药剂会被滴入悬挂在 Othmar 躯体上方的滴注装置中。",al={"什么是嘶嘶药剂","药剂的效果","法拉尼尔的药剂"}},{q="Othmar 是活着的还是亡灵？",a="Othmar 是亡灵。加里索斯是被黑暗女王亲自杀死的，他的头颅已被缝合到一个抽搐着重获生机的憎恶躯体上。法拉尼尔称他为“新客人”，并计划让他继续在滴注药剂的折磨下受苦。",al={"othmar 是死是活","加里索斯还活着吗","othmar 的状态"}},{q="法拉尼尔接下来打算怎么处置 Othmar？",a="大药剂师法拉尼尔打算让 Othmar 的血肉继续在滴注装置下灼烧，同时严密监视他。法拉尼尔表示他对 Othmar 的未来有详尽的计划，打算利用这个可怜虫进行持续的实验和报复。",al={"法拉尼尔未来的计划","接下来 othmar 会怎样","othmar 的未来"}}},fp="16,341,22.344.0,20.402.1,14.325.0,30.351.0,34.226.0,31.223.0,26.245.0,47.247.0"}
P.entries["quest:973"] = {n="奥萨拉克斯之塔",s="此任务是奥萨拉克斯之塔调查任务线的第五章，指引联盟的冒险者从黑海岸向南进入灰谷。净化者德尔格伦派遣你去击败居住在被腐蚀的火痕神殿中的兽人术士伊克鲁德·玛格苏尔，并取回他的奥术之书。",h="此任务是奥萨拉克斯之塔调查任务线的第五章，指引联盟的冒险者从黑海岸向南进入灰谷。净化者德尔格伦派遣你去击败居住在被腐蚀的火痕神殿中的兽人术士伊克鲁德·玛格苏尔，并取回他的奥术之书。",kw={"奥萨拉克斯","灰谷","德尔格伦","火痕神殿","伊克鲁德","迈斯特拉","玛格苏尔","书籍","术士"},ang={["class:Paladin"]="与净化者德尔格伦并肩作战，击败邪能召唤师并没收腐化的书籍，体现了圣光对抗恶魔腐化的经典使命。",["class:Warlock"]="对抗伊克鲁德·玛格苏尔意味着你要与一位黑暗技艺的同道者交锋，他会使用召唤的魅魔和虚空行者来守护他的邪恶文献。",["faction:Alliance"]="此项任务将联盟的冒险者带出安全的黑海岸，深入灰谷被恶魔污染的角落，以清除日益增长的黑暗威胁。",["race:NightElf"]="火痕神殿代表了对灰谷古老森林的一种卑劣亵渎，铲除伊克鲁德成为了保卫神圣祖地的一项使命。"},sec={{t="深入灰谷的狩猎",b="沿着在黑海岸奥萨拉克斯之塔发现的黑暗邪教活动线索，神圣战士净化者德尔格伦认出了一个危险施法者的签名：兽人术士伊克鲁德·玛格苏尔。伊克鲁德盘踞在灰谷西南部被称为火痕神殿的恶魔枯萎之地，他的阴暗交易威胁着要将邪恶魔法扩散到纯净的精灵林地。德尔格伦指派你去击杀术士并夺取他的魔法书，以揭露他主子的计划。"},{t="术士的巢穴",b="火痕神殿是一处布满恶魔奴仆的邪能伤痕遗迹。神殿沿其岩石斜坡矗立着险恶的红色柱子，伊克鲁德与他召唤的魅魔以及守护神殿的邪能杀手就栖息于此。在他的邪能领地中心击败这名兽人，就能让德尔格伦从伊克鲁德的书中搜寻到与奥萨拉克斯之塔发生的险恶仪式相关的黑暗知识和指令。"}},faq={{q="谁是净化者德尔格伦？",a="净化者德尔格伦是一位驻扎在迈斯特拉岗哨的联盟勇士，这是位于黑海岸与灰谷交界处的一个暗夜精灵哨所。他负责指挥针对该地区恶魔腐化和邪教徒的行动。",al={"德尔格伦","德尔格伦剧情","任务起始人"}},{q="谁是伊克鲁德·玛格苏尔？",a="伊克鲁德·玛格苏尔是一位强大的兽人术士，他在灰谷西南部的火痕神殿筑巢。虽然德尔格伦最初认为他只是个小麻烦，但由于他与奥萨拉克斯之塔的黑暗仪式有关联，他成为了一个关键目标。",al={"伊克鲁德","谁是伊克鲁德·玛格苏尔","灰谷兽人术士"}},{q="火痕神殿位于何处？",a="该神殿位于灰谷西南部，艾森娜神殿以南，阿斯特兰纳以西。这是一个被腐蚀、被恶魔侵扰的飞地，两侧有两根独特的红色柱子，通向伊克鲁德的祭坛。",al={"火痕神殿位置","伊克鲁德在哪里","如何到达伊克鲁德处"}},{q="为什么德尔格伦需要伊克鲁德·玛格苏尔之书？",a="伊克鲁德的书里记载了他的黑暗仪式和通讯信息。德尔格伦旨在破译这些文字，以揭开将这位兽人术士与徘徊在奥萨拉克斯之塔周围的邪教徒联系在一起的险恶阴谋。",al={"为什么需要书籍","伊克鲁德之书的内容","书籍的作用"}},{q="这个任务是如何将黑海岸与灰谷连接起来的？",a="故事线始于对黑海岸北岸奥萨拉克斯之塔的调查。随着谜团加深，邪教徒的网络引导冒险者穿过黑海岸，深入到饱受争夺的灰谷森林。",al={"从黑海岸到灰谷的任务","奥萨拉克斯之塔任务链关联"}},{q="取回那本书后会发生什么？",a="德尔格伦会查阅书中的内容，以推断奥萨拉克斯之塔的邪教徒身影背后的更深层阴谋，从而引出任务链的最终对抗。",al={"下一个任务","奥萨拉克斯之塔5后续"}}},fx={b25de95c={q="净化者德尔格伦为什么要完成这件事？",a="净化者德尔格伦一心要根除当地的恶魔腐化。他以前认为伊尔克鲁德·玛格索鲁只是个小麻烦，但这个术士邪恶的研究，以及他在遭到腐化的火痕神殿中的活动，都让他逐渐成为德尔格伦再也无法忽视的威胁。",al={"德尔格伦的动机","为什么杀死伊尔克鲁德·玛格索鲁","净化者德尔格伦的目标"}}},fp="22,305,21.502.0,18.385.1,28.227.0,24.253.0,38.211.0,46.206.0,51.230.0,39.167.0"}
P.entries["quest:97326"] = {n="Rocks to Rests",s="“Rocks to Rests”是为Thra执行的一个轻松跑腿任务。Thra是一位兽人幼童，正在奥格瑞玛的Grommash Hold后方与朋友们玩游戏。孩子们需要一位冒险者的力量，将圆滑的巨石搬运到他们的空地上，用作临时的座椅和桌子。这个任务为玩家提供了一个迷人的视角，一窥在部落首都长大的年轻一代的日常生活和游戏。",h="“Rocks to Rests”是为Thra执行的一个轻松跑腿任务。Thra是一位兽人幼童，正在奥格瑞玛的Grommash...",kw={"杜隆塔尔","grommash hold","兽人","奥格瑞玛","rocks to rests","圆滑的巨石","桌面游戏","thra"},ang={["faction:Horde"]="花时间在大酋长的据点后方帮助年轻的兽人，这表明即使在一个崇尚武力的社会中，奥格瑞玛的社区和日常生活也同样重要。",["race:Orc"]="在Grommash Hold后方自创游戏的兽人幼童，反映了在杜隆塔尔中心地带成长起来的下一代的日常成长环境。"},sec={{t="奥格瑞玛的一处静谧角落",b="在奥格瑞玛Grommash Hold后方的一片泥土地上，一群年轻的兽人聚在这里，远离了要塞卫兵严厉的目光。这片空地提供了充足的开阔地带供他们摆放微型人偶，但这里没有任何像样的家具，使得孩子们只能直接坐在尘土中玩耍。"},{t="临时家具",b="发现路过的冒险者后，一个名叫Thra的幼童请求帮助，希望能搬运八块中等大小、圆滑的巨石到他们的游戏场地。多亏了巨石平坦的侧面，这些沉重的石头成了坚固的临时座椅和低矮的桌子，让孩子们可以舒适地摆弄他们的游戏，而不必坐在尘土中。"}},faq={{q="谁发布了“Rocks to Rests”任务？",a="Thra是一个年轻的兽人，正在奥格瑞玛Grommash Hold后方的空地上与朋友们玩游戏。Thra观察敏锐且生性活泼，请求路过的冒险者伸出援“手”，以改善他们的游戏区。",al={"谁发布了rocks to rests","thra 奥格瑞玛","thra是谁"}},{q="这个任务发生在哪里？",a="该任务发生在Grommash Hold后方的空地上，此处位于奥格瑞玛智慧谷内，是萨尔大酋长的所在地。孩子们聚集在这片远离要塞繁忙交通的相对清净的泥土地上。",al={"rocks to rests在哪里","thra的位置","grommash hold后方在哪里"}},{q="为什么Thra需要圆滑的巨石？",a="Thra和其他孩子需要圆滑的中型岩石来充当临时座椅和桌子。没有家具，他们在摆放和进行微型游戏时只能直接坐在地上。",al={"为什么需要石头","圆滑的巨石有什么用","为什么是巨石"}},{q="在Grommash Hold后方玩什么游戏？",a="Thra和同伴们正在进行一种非正式的桌面游戏，他们在地上铺开了许多小人偶。圆滑的巨石提供了稳定的表面，让他们在玩游戏时可以放置人偶并舒适地就座。",al={"他们在玩什么游戏","thra 游戏 奥格瑞玛","grommash hold后方的人偶"}},{q="“Rocks to Rests”涉及战斗吗？",a="不，“Rocks to Rests”是一个简单、和平的跑腿任务，而非军事行动或战斗考验。它完全依赖蛮力将沉重的巨石搬回孩子们玩耍的地方。",al={"rocks to rests危险吗","rocks to rests有战斗吗"}},{q="孩子们在巨石运到后会怎么做？",a="一旦八块圆滑的巨石送达，Thra和孩子们会将它们挪到泥土地上的相应位置，利用平坦的侧面为他们的桌面人偶制作座位和桌子。",al={"rocks to rests完成后会发生什么","thra用石头做什么"}}},fp="14,375,27.316.0,19.313.0,35.220.0,33.238.0,35.213.0,47.205.0,37.191.0,57.196.0"}
P.entries["quest:97538"] = {n="Pigments for Paints",s="雷霆崖的塔·冬蹄需要一位旅行者前往石爪山脉，为他补充红色颜料。他所需的材料来自幽暗草，这是一种生长在暗色湖中的独特水生植物，其干燥后的幽暗草荚可以制成鲜艳的绯红色染料。",h="雷霆崖的塔·冬蹄需要一位旅行者前往石爪山脉，为他补充红色颜料。他所需的材料来自幽暗草，这是一种生长在暗色湖中的独特水生植物，其干燥后的幽暗草荚可以制成鲜艳的绯红色染料。",kw={"暗色湖","幽暗草","幽暗草荚","pigments for paints","红色颜料","石爪山脉","塔·冬蹄","雷霆崖"},ang={["faction:Horde"]="这个请求展示了牛头人主城雷霆崖与附近崎岖的石爪山脉山口之间日常的往来联系。",["profession:Herbalism"]="虽然暗色湖的水域十分危险，但原生的幽暗草证明了区域性水生植物除了作为常规草药之外，还能提供有用的材料和颜料。",["race:Tauren"]="塔·冬蹄代表了雷霆崖的工匠们，他们依赖卡利姆多各地的天然植物来生产传统的颜料和染料。"},sec={{t="工匠的需求",b="塔·冬蹄是雷霆崖高地城市里的一位年长牛头人工匠，在用光了红色颜料后，他的创作被迫停止了。由于年轻时四处游历的日子已经过去，这位画家只能指望体力充沛的旅行者前往北方的石爪山脉，为他补充颜料储备。"},{t="暗色湖的水域",b="塔·冬蹄那鲜艳绯红色的秘密隐藏在暗色湖的深处，那是一个位于石爪山脉山口的显眼圆形水域。幽暗草就潜生在这些水域中，这是一种独特的水生植物，其种荚在采摘并妥善干燥后，会变成一种鲜艳夺目的红色。通过收集三十个这样的草荚，旅行者可以为这位大师级工匠提供恢复工作所需的原材料。"}},faq={{q="谁发布了“Pigments for Paints”这个任务？",a="塔·冬蹄在雷霆崖发布了这个任务。作为一位年长的牛头人工匠，他早已过了四处奔波的年纪，因此他寻找那些腿脚更灵便的人代为收集原材料。",al={"谁发布了pigments for paints","pigments任务发布者","塔·冬蹄位置"}},{q="幽暗草荚在哪里可以找到？",a="幽暗草生长在暗色湖的水域中，这是一个位于石爪山脉山口中央的大型圆形湖泊。",al={"去哪里找幽暗草荚","幽暗草位置","暗色湖在哪里"}},{q="为什么塔·冬蹄需要幽暗草？",a="塔·冬蹄的艺术创作已经没有红色颜料可用了。幽暗草的草荚在干燥后会变成鲜艳的红色，这使它们成为他制作颜料的理想天然染料。",al={"为什么要收集幽暗草","幽暗草有什么用","为什么是红色颜料"}},{q="需要多少个幽暗草荚？",a="塔·冬蹄需要30个直接从暗色湖水域中收集的幽暗草荚，以补充他的红色颜料储备。",al={"需要多少草荚","幽暗草数量"}},{q="什么是幽暗草？",a="幽暗草是一种生长在石爪山脉暗色湖中的独特水生植物。它的主要特征是其草荚干燥后会变成深红色颜料。",al={"幽暗草是什么植物","幽暗草详情"}},{q="塔·冬蹄在哪里？",a="塔·冬蹄居住在莫高雷的雷霆崖高地城市上，他在那里从事手工艺创作并制作传统的颜料。",al={"塔·冬蹄在哪里","雷霆崖的塔·冬蹄"}}},fp="19,275,17.349.0,24.434.0,40.189.0,30.143.0,38.178.0,34.132.0,17.158.0,32.132.0"}
P.entries["quest:97539"] = {n="Silky Sutures",s="“Silky Sutures”是阿拉希高地的一项部落任务，由落锤镇前哨站的格里高利·维克托医生提供。由于一直未修复的攻城战损和日渐匮乏的医疗物资，这位营地驻地医师对现状感到沮丧，他招募冒险者去采集有毒的高地蜘蛛丝，用作紧急野战缝合线。这项任务突显了落锤镇守军所面临的绝望而物资匮乏的处境，他们正竭尽全力让守卫和劳工保持战斗力。",h="“Silky...",kw={"阿拉希高地","格里高利·维克托医生","野战缝合","落锤镇","医务室","silky sutures","蜘蛛丝","医用蛛丝"},ang={["faction:Horde"]="落锤镇是部落在阿拉希高地的一个关键据点，因此维克托医生为保持守卫者健康并随时准备战斗所做的努力，对于该阵营在这一地区的生存至关重要。",["race:Undead"]="格里高利·维克托医生将一种被遗忘者特有的务实且不带个人情感的医疗专业知识带到了落锤镇，利用高地上的临时资源来维持诊所的运作。"},sec={{t="摇摇欲坠的前哨站",b="落锤镇在崎岖的阿拉希高地苦苦支撑，但这座营地显露出长期压力下的可见痕迹。未修复的攻城战损遍布外围，这让当地医师格里高利·维克托医生苦涩地感叹，疏于管理似乎已成了官方方针。尽管防御工事摇摇欲坠，且缺乏广泛的支持，维克托拒绝让腐朽侵蚀他的医务室。维持一家运作正常的诊所对于让劳工和哨兵守卫保持站立并随时准备战斗至关重要。"},{t="临时医疗物资",b="物资的减少让落锤镇的医务室濒临耗尽，迫使维克托医生转向战场应急方案。当传统的绷带和缝合线稀缺时，从高地蜘蛛身上采集到的坚韧且富有弹性的蛛丝可以被拧成出人意料的强韧野战缝合线。虽然维克托冷淡地打趣说，感染风险对于受伤士兵来说是最小的忧虑，但采集这些蛛丝确实为医务室提供了在敌对领地补救伤员所需的关键器材。"},{t="落锤镇的苦涩幽默",b="在被围困的情况下经营一线诊所需要坚毅的性格，而格里高利·维克托医生充分展现了这一点。他用关于严峻预后和蜘蛛丝缝合的讽刺笑话来迎接旅行者，以此掩盖落锤镇被孤立的严酷现实。高地上的常规援助依然罕见，因此任何来自过往勇士的帮助对于维持诊所至关重要。通过临时补救措施和顽强的反抗，维克托确保了落锤镇的伤员能够得到照顾，即使他们身处的哨站看起来已被遗弃而任其腐朽。"}},faq={{q="格里高利·维克托医生是谁？",a="格里高利·维克托医生是阿拉希高地落锤镇医务室的驻地医疗官兼创伤外科医生。他拥有尖刻的机智，对待战场分诊有着务实的态度，不懈地治疗着受伤的守卫和劳工。尽管整个哨站面临严重的物资短缺和未修复的攻城战损，维克托仍决心防止医务室因被忽视而荒废。",al={"谁是维克托","格里高利·维克托背景故事","落锤镇医生"}},{q="为什么维克托医生需要蜘蛛丝？",a="落锤镇的医务室几乎完全耗尽了标准的医疗物资和器材。在极端的战场压力下，维克托医生只能依靠应急手段，将结实的高地蜘蛛丝捻成有效的医用缝合线，用来缝合裂伤和创口。在缺乏正规临床缝合线的情况下，这些蜘蛛丝提供了足以将撕裂的皮肉缝合在一起的耐用线材。",al={"为什么需要蜘蛛丝","医用蛛丝的用途","蜘蛛丝缝合线"}},{q="这个任务期间落锤镇处于什么状况？",a="落锤镇处于一种肉眼可见的荒废和物理破败状态。旧的攻城战损在营地的防御工事上依然未得到任何修复，这让维克托医生认为行政上的漠视已成了官方方针。该基地缺乏持续的外部援助和补给，使得驻守的卫兵、劳工和医务人员不得不自谋生路。",al={"落锤镇现状","为什么落锤镇会受损","落锤镇的状况"}},{q="这个任务中的蜘蛛来自哪里？",a="这些蜘蛛潜伏在落锤镇营地周边的阿拉希高地荒野中。冒险者冒险走出哨站围墙，必须在高地平原上猎杀这些充满侵略性的蛛形纲生物，以采集维克托医生进行野战缝合所需的医用蛛丝，然后安全返回诊所。",al={"阿拉希蜘蛛","在哪里寻找蛛丝","医用蛛丝位置"}},{q="为什么维克托医生会讽刺感染问题？",a="当把收集到的蜘蛛丝交给他时，维克托医生开玩笑说，对于正在缝合伤口的受伤士兵来说，一点感染根本算不了什么。这种黑色幽默反映了落锤镇前线分诊的残酷现实：在战场上，防止严重失血和致命创伤比追求无菌的临床环境更为优先。",al={"医生的幽默感","蜘蛛丝与感染","维克托的玩笑"}},{q="为什么落锤镇的物资如此匮乏？",a="落锤镇坐落在阿拉希高地内一个充满争议且与世隔绝的位置，四周环绕着敌对威胁，且与稳定的补给线隔绝。外部的增援和物流补给很少抵达，这使得该哨站的驻军和医务室不得不长期忍受原材料、工具和基本治疗用品的短缺。",al={"为什么没有补给","落锤镇物资短缺","落锤镇缺乏援助"}},{q="落锤镇的医务室治疗哪些人？",a="医务室直接归格里高利·维克托医生管理，负责治疗驻扎在落锤镇的劳工和卫兵。由于该哨站不断承受着来自高地危险和结构性损伤的压力，维护这些守卫者的身体健康对于保持该定居点的防御能力和运作功能至关重要。",al={"维克托治疗谁","落锤镇伤员","诊所患者"}}},fp="13,478,21.507.0,26.542.0,27.573.0,29.431.0,40.397.0,50.396.0,46.324.0,47.364.0,41.347.0,43.336.0"}
P.entries["quest:97558"] = {n="Hides for the Forsaken",s="在提瑞斯法林地，被遗忘者的亡灵生存环境十分严峻，他们必须收集兽皮来替换腐烂的血肉。舍伦尼·洛巴尔特指派冒险者收集Darkhound毛皮、夜行蝙蝠翼膜和Vile Fin鱼人皮，以修补受损的躯体。",h="在提瑞斯法林地，被遗忘者的亡灵生存环境十分严峻，他们必须收集兽皮来替换腐烂的血肉。舍伦尼·洛巴尔特指派冒险者收集Darkhound毛皮、夜行蝙蝠翼膜和Vile Fin鱼人皮，以修补受损的躯体。",kw={"darkhound毛皮","夜行蝙蝠翼","hides for the forsaken","舍伦尼·洛巴尔特","提瑞斯法林地","亡灵移植","vile fin鱼人"},ang={["profession:Tailoring"]="被遗忘者的裁缝技艺通常与殡葬学有所重叠，他们使用缝合技巧不仅是为了制作服装，更是为了将未处理的野兽膜层固定在腐烂的骨架上。",["race:Undead"]="这鲜明地提醒着人们被遗忘者所承受的现实负担，他们的生存需要手动维护和搜寻移植组织，而不是自然愈合。"},sec={{t="亡灵的代价",b="被遗忘者的血肉无法自然愈合。身体受到的创伤会留下无法通过正常生理方式再生的腐烂空洞。为了维持形态并保持尸体功能正常，被遗忘者必须从生者的世界获取有机材料，并将替代组织缝合在伤口上。"},{t="特殊材料",b="并非所有的毛皮都有相同的解剖学用途。厚实的Darkhound毛皮可以提供耐用性，用于大面积、稳固的修补。精致的夜行蝙蝠翼膜轻盈柔软，足以覆盖脸部和手指，而不会产生僵硬、笨拙的层次。与此同时，收集柔软的Vile Fin鱼人皮是为了内衬内部膜层和敏感区域，例如口腔内壁。"}},faq={{q="被遗忘者为什么要动物皮？",a="亡灵的皮肤在受损后不会自然愈合或再生。为了在身体受伤后继续存在并延缓外部腐烂，被遗忘者会采集活体生物的皮肤和膜层，缝补在他们受伤的躯体上。",al={"被遗忘者为何需要毛皮","亡灵愈合背景知识","亡灵会自愈吗"}},{q="舍伦尼·洛巴尔特是谁？",a="舍伦尼·洛巴尔特是提瑞斯法林地的一名被遗忘者制皮师。她收集各种毛皮和生物材料，以确保受损的被遗忘者有足够的资源来修补他们腐烂的躯体。",al={"舍伦尼·洛巴尔特","舍伦尼是谁"}},{q="为什么特别需要夜行蝙蝠翼膜？",a="与沉重的毛皮相比，夜行蝙蝠翼膜异常薄且柔软。这种轻盈的特性使其成为覆盖敏感和复杂解剖部位（如面部特征和手指）的理想选择，避免移植的皮肤变得过于厚重或僵硬。",al={"夜行蝙蝠翼的用途","为什么要用夜行蝙蝠翼膜"}},{q="鱼人皮有什么用？",a="Vile Fin鱼人皮具有独特的湿润度和柔韧性，非常适合用作内部膜层或脆弱的粘膜表面，例如脸颊内部和口腔。",al={"为什么用鱼人皮","鱼人皮与亡灵"}},{q="这些材料在哪里可以找到？",a="这三种生物都在提瑞斯法林地那令人不安的土地上徘徊。Darkhound和夜行蝙蝠潜伏在树林和路边，而Vile Fin鱼人则在北部海岸和内陆水道筑巢。",al={"到哪里获取毛皮","提瑞斯法林地的野兽"}},{q="使用动物皮对被遗忘者来说很常见吗？",a="是的。从动物和搜寻到的遗骸中获取组织是被遗忘者日常生存的基础。如果没有可替换的血肉和毛皮，未愈合的伤口会将底层的骨骼、器官和肌肉完全暴露在外界环境中。",al={"所有被遗忘者都会用毛皮吗","被遗忘者的血肉构造"}}},fx={["84f1a52c"]={q="暗牙狼的皮有什么用？",a="亡灵的躯体受伤后不会自然愈合，因此被遗忘者不得不用采集来的野兽毛皮修补身体。脆弱的组织需要薄膜，而暗牙狼皮这类更厚实坚韧的毛皮，则能作为耐用的移植材料，用于身体上需要坚韧耐磨替代皮肤的大面积部位。",al={"暗牙狼皮的用途","为什么要暗牙狼皮","暗牙狼皮和被遗忘者"}}},fp="22,266,20.316.0,21.383.0,38.240.0,23.197.0,51.273.0,29.175.0,32.197.0,46.256.0"}
P.entries["quest:97583"] = {n="WRIGGLE.",s="WRIGGLE. 是一场与一只极其兴奋的年轻软泥怪的邂逅，它热爱跳舞，直到耗尽所有精力。为了复苏并与这只生物成为朋友，冒险者必须从幽暗城的运河中取回一批特殊的营养丰富的泥浆怪淤泥。",h="WRIGGLE.",kw={"运河","兴奋的软泥怪","营养丰富的泥浆怪淤泥","软泥怪","淤泥","幽暗城","wriggle"},ang={["faction:Horde"]="获取这种特殊的淤泥需要冒险进入被遗忘者的首都幽暗城的运河，与当地商人进行交易。",["race:Undead"]="被遗忘者非常习惯于幽暗城运河网络中流动的有毒径流和活体软泥怪，因此让软泥怪成为同伴再合适不过了。"},sec={{t="跳舞的软泥怪",b="WRIGGLE. 涉及与一只活泼、兴奋的小软泥怪互动，它喜欢模仿友好旅行者的舞蹈动作。尽管热情高涨，但跳舞很快会耗尽这只小软泥怪的体力，使它变得疲惫，需要补充养分来恢复精力。"},{t="来自运河的养分",b="为了让疲惫不堪的生物恢复活力，冒险者必须寻找营养丰富的泥浆怪淤泥，这是一种在幽暗城恶臭的运河中出售的特殊混合物。在吸收了这种它钟爱的污秽佳肴后，精力充沛的软泥怪会急切地与提供者建立羁绊，准备跟随它的新朋友。"}},faq={{q="什么是 WRIGGLE.？",a="WRIGGLE. 是一场遭遇战，冒险者通过跳舞与一只兴奋的小软泥怪结为朋友，却发现这只生物需要专门的养分来维持它的精力。",al={"wriggle 任务","什么是 wriggle","软泥怪跳舞任务"}},{q="去哪里寻找营养丰富的泥浆怪淤泥？",a="营养丰富的泥浆怪淤泥由幽暗城运河内的一位商人出售，在那里炼金废料和径流随处可见。",al={"哪里获取淤泥","营养丰富的泥浆怪淤泥商人","喂食幽暗城软泥怪"}},{q="如果软泥怪看起来累了，该如何引起它的注意？",a="如果这只兴奋的软泥怪变得疲惫或分心，与它共舞可以吸引它的注意力，并模仿它顽皮的动作。",al={"如何引起软泥怪注意","疲惫的软泥怪","唤醒软泥怪 wriggle"}},{q="为什么软泥怪以淤泥为食？",a="软泥怪吸收周围的炼金淤泥和泥浆来维持自身并恢复活力，在消耗体力后进行恢复。",al={"为什么软泥怪吃淤泥","软泥怪吃什么"}},{q="喂食软泥怪后会发生什么？",a="在用它偏爱的淤泥喂养后，恢复活力的软泥怪会与冒险者建立羁绊，并试图跟随他们。",al={"软泥怪会跟随你吗","软泥怪同伴","wriggle 奖励"}},{q="联盟玩家能轻易获得这些淤泥吗？",a="由于获得必要的营养丰富的泥浆怪淤泥需要前往幽暗城运河中的商人处，联盟旅行者会发现进入被遗忘者之城极其危险。",al={"联盟可以完成 wriggle 吗","联盟软泥怪淤泥"}}},fp="8,236,15.270.0,26.283.0,17.182.0,42.139.0,57.124.0,34.127.0,35.129.0,46.196.0"}
P.entries["quest:976"] = {n="奥伯丁的补给品",s="“运往奥伯丁的补给”是一个护送任务，联盟的冒险者需要保护费罗·艾隆汉，护送他带着关键的补给品和信件，从迈斯特拉岗哨向北前往黑海岸。鉴于奥萨拉克斯之塔散发的威胁日益加剧，以及灰谷中潜伏着充满敌意的渗透者，这条道路的安全无法得到保障。",h="“运往奥伯丁的补给”是一个护送任务，联盟的冒险者需要保护费罗·艾隆汉，护送他带着关键的补给品和信件，从迈斯特拉岗哨向北前往黑海岸。鉴于奥萨拉克斯之塔散发的威胁日益加剧，以及灰谷中潜伏着充满敌意的渗透者，这条道路的安全无法...",kw={"灰谷","奥伯丁","怨恨者巴利扎尔","黑海岸","净化者德尔格伦","费罗·艾隆汉","迈斯特拉岗哨","哨兵星风","奥萨拉克斯之塔"},ang={["faction:Alliance"]="守护这条走廊确保了灰谷的前哨站能与奥伯丁的后勤枢纽保持联系，维护了联盟在卡利姆多北部脆弱的据点。",["race:Human"]="费罗·艾隆汉代表了人类愿意深入陌生且危险的古老森林，去支持卡多雷盟友的意愿。",["race:NightElf"]="运往北方的补给和公文直接帮助了奥伯丁的哨兵们，使她们能够应对横跨黑海岸和灰谷边境日益增长的黑暗。"},sec={{t="险象环生的北上之路",b="迈斯特拉岗哨坐落在灰谷的西侧前线，这是一个宁静的前哨站，夹在丛林中狂野的紧张局势和黑海岸动荡的土地之间。在调查了围绕奥萨拉克斯之塔的邪恶活动后，净化者德尔格伦收集了重要的补给品和情报，准备送往奥伯丁的哨兵星风处。为了不让信使孤身犯险，前哨站决定指派武装护卫，陪同费罗·艾隆汉踏上穿越林间道路的旅程。"},{t="小径阴影",b="旅途揭示了道路周边的荒野处境是多么危险。费罗的路线遭到了一连串协调一致的伏击。暗滩邪教徒试图封锁任何有关其恶魔仪式的消息，被遗忘者斥候在林地灌木丛中潜伏，而像怨恨者巴利扎尔、折磨者阿里加和恶毒的凯达卡尔这样凶残的指挥官，都试图在商队抵达边境前将其歼灭。"}},faq={{q="费罗·艾隆汉是谁？",a="费罗·艾隆汉是一名驻扎在灰谷西部的迈斯特拉岗哨的人类信使。他受净化者德尔格伦之托，携带重要信件和后勤物资前往奥伯丁。他非常谨慎，如果没有得力的保镖随行，他拒绝踏上旅程。",al={"费罗","费罗·艾隆汉背景故事","护送的矮人是谁"}},{q="为什么奥伯丁需要这些补给？",a="黑海岸和灰谷北部正面临日益严重的腐化，以及从奥萨拉克斯之塔活动的恶魔邪教徒所带来的威胁。驻扎在奥伯丁的暗夜精灵哨兵们，在哨兵星风等当地人物的领导下，需要新鲜的补给和最新的情报，以维持对海岸线的防御。",al={"为什么要运送补给到奥伯丁","奥伯丁补给","哨兵星风"}},{q="是谁在路上袭击了费罗？",a="费罗警告说森林里到处都是危险的敌人，并请求派人保护。在护送过程中，袭击者的身份将会被揭露。",al={"谁伏击了费罗","费罗的伏击者","谁在路上发动攻击"}},{q="这与奥萨拉克斯之塔有什么联系？",a="净化者德尔格伦一直在策划旨在揭露并破坏奥萨拉克斯之塔邪教徒黑暗仪式的行动。这次护送正是该调查工作的一部分，旨在确保情报和关键支持能送达奥伯丁的暗夜精灵领导层手中。",al={"奥萨拉克斯之塔关联","奥萨拉克斯之塔","德尔格伦关联"}},{q="护送费罗完成后我该向谁汇报？",a="在确保费罗安全通过灰谷的伏击区后，你需要回到迈斯特拉岗哨向净化者德尔格伦汇报，确认任务顺利完成。",al={"交还奥伯丁补给任务","护送费罗后去哪里","任务交付"}}},fx={["1813fb85"]={q="费罗·艾隆汉为什么要运送这些补给？",al={"费罗·艾隆汉的动机","费罗为什么需要帮助","为什么要把补给送到奥伯丁"}},affb8fb0={q="费罗·艾隆汉为什么请你保护他，而不是请岗哨的卫兵？",a="费罗带着重要补给和信件穿越危险的灰谷，实在不愿独自上路。他请你担任护卫，确保货物安全送达奥伯丁。",al={"费罗为什么派我去","费罗为什么需要护卫","费罗为什么不独自上路"}}},fp="21,347,21.488.0,23.428.1,22.248.0,39.317.0,33.151.0,49.269.0,41.153.0"}
P.entries["quest:97891"] = {n="Prompt Potion Runner",s="“Prompt Potion Runner”是一项紧急的幽暗城运送任务，玩家必须穿过粘液运河，将一种不稳定的药剂争分夺秒地送到Apothecarium。该任务突显了亡灵躯体的孱弱以及被遗忘者炼金研究的挥发性。",h="“Prompt Potion Runner”是一项紧急的幽暗城运送任务，玩家必须穿过粘液运河，将一种不稳定的药剂争分夺秒地送到Apothecarium。该任务突显了亡灵躯体的孱弱以及被遗忘者炼金研究的挥发性。",kw={"亚历山德罗","apothecarium","马丁·费尔本药剂师","prompt potion runner","皇家药剂师学会","粘液运河","幽暗城","不稳定药剂"},ang={["faction:Horde"]="幽暗城是部落的关键枢纽，尽管旅行者必须穿过其有毒的粘液运河，协助被遗忘者完成他们危险的炼金事业。",["race:Undead"]="这次运送展示了被遗忘者不死状态下脆弱的生理现实，易碎的关节和腐朽的膝盖很容易导致皇家药剂师学会的重要实验室工作毁于一旦。"},sec={{t="与腐朽的赛跑",b="在幽暗城的地下走廊里，被遗忘者炼金师亚历山德罗急需一名迅捷的信使。他配制了一种极不稳定、保质期极短的药剂，由于他那脆弱的亡灵关节无法承受奔跑，他不敢冒险亲自带着药剂穿过城内的毒液运河。冒险者必须与时间赛跑，确保药剂在降解成无用的淤泥之前完好地送达。"},{t="Apothecarium的需求",b="目的地是Apothecarium，马丁·费尔本药剂师正焦急地等待着这份药剂以继续他的研究。费尔本透露，之前的六名信使或尝试都失败了，因为药剂在运输途中变得不稳定。及时的送达能让药剂师继续他那阴暗的实验，这既强调了皇家药剂师学会制剂的易挥发性，也展示了亡灵躯体的生理缺陷。"}},faq={{q="谁发布了这个任务？",a="该任务由幽暗城的亚历山德罗发布。他需要一名冒险者飞奔穿过粘液运河，因为他那腐朽的亡灵膝盖一跑就会脱臼并发出响声。",al={"谁发布了prompt potion runner","谁开启了prompt potion runner","谁是亚历山德罗"}},{q="药剂需要送到哪里？",a="药剂必须送给马丁·费尔本药剂师，他在幽暗城的Apothecarium进行炼金实验。",al={"要把药剂带到哪里","谁是马丁·费尔本药剂师","prompt potion runner交任务"}},{q="为什么这次运送有时间限制？",a="这种制剂是一种不稳定的药剂，保质期极短。如果不尽快穿过运河送达，混合物就会变得不稳定并失去效用。",al={"为什么有时间限制","不稳定药剂的保质期","为什么要赶时间"}},{q="之前的运送尝试是否失败过？",a="马丁·费尔本药剂师指出，亚历山德罗之前尝试送出的六瓶药剂在到达Apothecarium之前就已在中途变得不稳定，因此你的成功送达是一次难得的胜利。",al={"是否有其他信使失败过","亚历山德罗过去的尝试","有多少瓶药剂失败了"}},{q="为什么亚历山德罗不能亲自送药？",a="亚历山德罗解释说，每当他试图奔跑时，他的膝盖就会发出嘎吱声并脱臼，这是亡灵身份带来的不幸生理副作用，导致他无法亲自赶去送药。",al={"为什么亚历山德罗不能自己去送","亚历山德罗的膝盖"}},{q="费尔本药剂师在进行什么实验？",a="马丁·费尔本是一位在Apothecarium进行实验的药剂师。虽然具体配方保密，但一旦稳定的混合物送达，他就会立即继续他的研究。",al={"费尔本药剂师的工作","药剂的用途是什么"}}},fp="20,263,20.434.0,26.420.0,21.183.0,33.127.0,26.171.0,36.194.0,48.195.0,37.191.0"}
P.entries["quest:97894"] = {n="Business in Auberdine",s="“Business in Auberdine”是暴风城的一位矮人商人博古斯·钢手发布的差事。博古斯请求前往西方的旅客顺道探望他的兄弟高尔博德，后者最近在暗夜精灵港口奥伯丁做起了生意。这项任务连接着人类首都繁忙的码头与卡利姆多北部迷雾缭绕的海岸。",h="“Business in...",kw={"奥伯丁","博古斯·钢手","business in auberdine","黑海岸","高尔博德·钢手","商人","钢手","暴风城港口"},ang={["faction:Alliance"]="暴风城港口与奥伯丁之间的直接海上航线加强了人类王国与卡利姆多北部的卡多雷领地之间的贸易和军事联系。",["race:Dwarf"]="矮人的商业触角远及卡兹莫丹群山之外，像钢手这样的进取商人甚至在暗夜精灵宁静幽暗的定居点中也设立了摊位。"},sec={{t="背井离乡的矮人",b="钢手家族以头脑精明和交易公道而闻名，博古斯也总是以此为荣。他的兄弟高尔博德·钢手最近冒险横跨无尽之海，前往奥伯丁经营一个商铺。为停靠在黑海岸的船只提供补给看起来是一条致富捷径，但几周以来杳无音信，这让博古斯对远在铁炉堡和暴风城之外的兄弟的处境感到不安。"},{t="港口航线",b="从东部王国航行到卡利姆多那未受开发的荒野，过去需要通过米奈希尔港或藏宝海湾这类中立地精港口进行复杂的转运。博古斯指引旅客前往暴风城港口最南端的码头，那里有一艘船只，提供直达奥伯丁漫长木质码头的海上航线。"}},faq={{q="博古斯·钢手是谁？",a="博古斯·钢手是暴风城的一名矮人商人。他对自己家族诚实交易的声誉感到自豪，因此寻找路过的冒险者为他远在海外的兄弟高尔博德捎去口信。",al={"博古斯·钢手","谁发布了business in auberdine","博古斯"}},{q="高尔博德·钢手在哪里？",a="高尔博德·钢手驻扎在奥伯丁，这是卡利姆多西北海岸黑海岸的主要港口定居点。他在那里经营着一家面向进出港船只的商铺。",al={"高尔博德在哪里","寻找高尔博德·钢手","高尔博德位置"}},{q="如何从暴风城前往奥伯丁？",a="一艘船直接从暴风城港口最南端的码头出发，运送乘客横跨无尽之海，直达黑海岸的奥伯丁码头。",al={"前往奥伯丁的船","如何从暴风城前往黑海岸","暴风城到奥伯丁的船"}},{q="为什么博古斯担心他的兄弟？",a="高尔博德几周前离开家乡前往奥伯丁的商铺，本指望靠补给航行船只赚上一大笔钱。然而他自离开后就再也没有寄回任何消息，这促使博古斯请求旅客前去调查。",al={"为什么要探望高尔博德","高尔博德发生了什么"}},{q="奥伯丁是什么样的定居点？",a="奥伯丁是一个主要由暗夜精灵建造和居住的沿海避风港。它位于黑海岸，是联盟连接卡利姆多北部与泰达希尔岛屿王国的主要航运枢纽和渡轮中转点。",al={"什么是奥伯丁","奥伯丁城镇"}},{q="钢手家族以什么闻名？",a="钢手家族是一个矮人商人家族，以经商、商铺经营以及无论对旅客还是码头工人都能提供公道交易而闻名。",al={"钢手家族","钢手"}}},fp="21,329,21.430.0,18.345.0,24.185.0,35.169.0,42.162.0,40.238.0,37.232.0,39.163.0"}
P.entries["quest:97903"] = {n="Camping 101: First Aid",s="Camping 101: First Aid是一项指导性任务，旨在指引技术娴熟的旅行者前往剃刀岭寻找Rawrk，他会传授如何制作野外生存所需的First Aid Kit。该任务强调了旅途中自力更生的必要性，提醒冒险者们掌握篝火制作方法，并尊重当地定居点，选择在荒野中露营。",h="Camping 101: First Aid是一项指导性任务，旨在指引技术娴熟的旅行者前往剃刀岭寻找Rawrk，他会传授如何制作野外生存所需的First Aid...",kw={"篝火","camping 101","杜隆塔尔","急救包","rawrk","剃刀岭","生存","荒野营地"},ang={["faction:Horde"]="这项训练以杜隆塔尔的剃刀岭为基地，旨在为那些希望在卡利姆多崎岖边境上维持生存的部落旅行者提供帮助。",["profession:Cooking"]="露营技巧和烹饪技能相辅相成；Rawrk指出，搭建一个合适的营地需要熊熊燃烧的篝火，这是一项由烹饪训练师传授的基本技术。"},sec={{t="边境生存之道",b="在杜隆塔尔及更广阔的蛮荒之地生存，需要的不仅仅是纯粹的武力，更需要在旅途中自给自足。在剃刀岭，Rawrk为寻求制作必要野外装备的有能力的漫游者提供指导。通过Camping 101: First Aid，那些已经证明自己具备基础能力的实践者可以学会组装专属的First Aid Kit，这让他们即便远离药剂师或医务所，也有手段包扎伤口、处理伤情。"},{t="篝火的艺术",b="搭建营地是一门遵循实用边境礼仪和需求的艺术。Rawrk告诫冒险者，在剃刀岭这样的定居点中心搭建帐篷是不受欢迎的，这意味着这些野外站点必须在开阔的荒野中进行测试。此外，没有熊熊燃烧的篝火来抵御夜晚的寒冷，任何营地都无法正常运作，因此，对于任何有志于露营的人来说，掌握烹饪艺术（即最初学习生火的地方）是一项至关重要的资产。"}},faq={{q="Rawrk是谁？他在哪里？",a="Rawrk位于杜隆塔尔的剃刀岭。他提供生存露营技巧的指导，教导已证明自身能力的实践者如何组装属于他们自己的First Aid Kit，以用于偏远地区的旅行。",al={"谁教授露营急救","rawrk在哪里","camping 101训练师"}},{q="搭建野外营地前需要什么条件？",a="搭建营地需要开阔的荒野环境和合适的篝火。Rawrk警告说，在城镇范围内露营是不被提倡的，并提醒旅行者在出发前应先向烹饪训练师学习基本的生火技巧。",al={"露营需要什么","如何搭建营地","露营篝火需求"}},{q="可以在城镇或定居点内搭建营地吗？",a="营地不能放置在定居点或城镇中心内。当地居民反对旅行者在街道中间搭帐篷，因此冒险者必须前往开阔的荒野来搭建营地。",al={"可以在剃刀岭露营吗","在城市内露营","可以在哪里放置营地"}},{q="这项训练教会冒险者制作什么？",a="完成这项训练可以指导冒险者制作个人First Aid Kit，这是一种用于维持健康并支持在荒野中进行持续探险的必备野外配件。",al={"camping 101: first aid奖励","这教导什么物品","first aid kit制作"}},{q="为什么Rawrk建议学习烹饪？",a="一个合适的营地需要一堆温暖的篝火作为核心。由于生火和照看基本火堆的基础知识是由烹饪训练师传授的，Rawrk建议露营者预先学习烹饪艺术。",al={"为什么露营需要烹饪","烹饪篝火露营"}},{q="学习这项工艺前需要什么先决条件？",a="旅行者必须先展现出他们在医疗和生存技能方面的基础熟练度，Rawrk才会教他们如何制作专业的野外First Aid Kit。",al={"camping 101: first aid前置要求","露营急救所需技能"}}},fp="22,349,24.489.0,23.482.0,35.190.0,53.243.0,49.218.0,51.189.0,42.205.0,57.163.0"}
P.entries["quest:97905"] = {n="Camping 101: Herbalism",s="《Camping 101: Herbalism》向采集者介绍了利用野生植物制作熏香蜡烛的技艺。它强调了荒野生存的基本规则，从搭建合适的篝火到在扎营前离开文明城镇。",h="《Camping 101: Herbalism》向采集者介绍了利用野生植物制作熏香蜡烛的技艺。它强调了荒野生存的基本规则，从搭建合适的篝火到在扎营前离开文明城镇。",kw={"营地","篝火","露营","烹饪","草药学","熏香蜡烛","荒野"},ang={["profession:Cooking"]="基础烹饪训练教授旅行者如何点燃合适的篝火，这是任何营地的必要中心。",["profession:Herbalism"]="草药师学习使用采集的植物制作熏香蜡烛，为荒野营地带来温暖、芳香和实用价值。"},sec={{t="荒野的芳香技艺",b="在艾泽拉斯的荒野中生存，需要的不仅仅是利刃，还需要将采集到的植物转化为实用生活用品的知识。通过草药学，采集者可以学会制作自己的熏香蜡烛，将采集物转化为适合旅途生活的舒缓芳香。由于城镇居民不希望帐篷挤占城市街道，这些蜡烛被设计用于在受保护的定居点城墙之外使用。"},{t="营地的核心",b="在荒野中，如果没有篝火的温暖光芒，任何营地都算不上真正完整。在营地中心搭建合适的篝火是使用熏香蜡烛的前提。草药学提供芳香的燃烧体验，而旅行者必须通过烹饪技艺向各地的厨师学习基本的生火技巧。"}},faq={{q="什么是熏香蜡烛？",a="熏香蜡烛是一种由草药师制作的芳香露营用品。它混合了野生植物，旨在荒野营地中与熊熊燃烧的篝火一同使用。",al={"什么是熏香蜡烛","熏香蜡烛用途","露营草药学物品"}},{q="在哪里可以搭建营地？",a="营地不能在城镇中心搭建，因为城镇居民不希望旅行者在公共通道上铺开营地。任何想要试用熏香蜡烛并搭建营地的人都必须前往开阔的荒野。",al={"哪里可以搭建营地","可以在城镇里露营吗","在城市里露营"}},{q="为什么搭建营地需要篝火？",a="每个功能性的营地都需要一堆熊熊燃烧的篝火作为核心。基本的篝火搭建技巧由艾泽拉斯各地的烹饪训练师教授，因此旅行者在出发前应学习入门级的烹饪技艺。",al={"如何制作篝火","露营需要篝火吗","烹饪与篝火露营"}},{q="谁教授篝火搭建方法？",a="烹饪训练师会教授旅行者如何点燃简单的篝火。学习烹饪技艺的基础知识，是你在野外生火的先决条件。",al={"谁教授篝火搭建","学习生火","烹饪训练师篝火"}},{q="草药学与露营有何关联？",a="草药学提供制作专用熏香蜡烛所需的芳香植物和树脂，利用在荒野中采集的天然植物来改善营地的环境，让人倍感舒缓。",al={"草药学与露营的联系","为什么草药学与露营有关","草药学能为营地提供什么"}},{q="使用熏香蜡烛需要篝火吗？",a="如果没有合适的篝火，营地就被认为是不完整的。旅行者被要求先搭建好篝火，再安顿下来享受熏香蜡烛带来的益处。",al={"没有篝火可以点燃熏香蜡烛吗","熏香蜡烛对篝火的需求"}}},fp="22,255,26.413.0,25.346.0,26.180.0,28.226.0,44.218.0,35.171.0,36.190.0,48.186.0"}
P.entries["quest:97907"] = {n="Camping 101: Mining",s="Camping 101: Mining是一项教学性专业任务，指引初出茅庐的矿工前往剃刀岭寻找克鲁恩。通过展示其专业技能，矿工们可以学会锻造磁石，这是一种专门的营地设施，可以增强在荒野篝火旁聚集的战士的战斗力。",h="Camping 101: Mining是一项教学性专业任务，指引初出茅庐的矿工前往剃刀岭寻找克鲁恩。通过展示其专业技能，矿工们可以学会锻造磁石，这是一种专门的营地设施，可以增强在荒野篝火旁聚集的战士的战斗力。",kw={"营地","篝火","camping 101: mining","烹饪","杜隆塔尔","克鲁恩","磁石","采矿","剃刀岭"},ang={["faction:Horde"]="穿行于杜隆塔尔的部落矿工可以向剃刀岭的克鲁恩报到，学习为他们的探险活动制作磁石的工艺。",["profession:Cooking"]="烹饪训练师提供了建造基础篝火所需的基础知识，这是任何功能性野外营地的核心。",["profession:Mining"]="采矿让你能够挖掘原始矿石，并制作像磁石这样的专门野外工具，以在营地支持你的盟友。"},sec={{t="矿工营地",b="采矿业是一份诚实的工作，能为荒野探索和生存提供实用的材料。随着矿工不断提升专业水平并展示出熟练的采掘技巧，他们可以学会制作专门的营地装备。在杜隆塔尔，熟练的矿工会被指引前往剃刀岭的聚落寻找克鲁恩，了解如何为他们的旅途锻造磁石。"},{t="篝火情谊",b="磁石是荒野中休息的冒险者们休憩时的魅力核心。当设置在营地旁时，它能为聚集在火堆旁的战斗人员提供额外的战斗力加成。然而，正当的营地礼仪要求离开文明定居点：城镇居民不乐意看到营地搭建在城市广场上，这意味着旅行者必须前往开阔的荒野来测试他们的手艺。"},{t="火焰与野外技艺",b="如果没有合适的火焰作为营地的锚点，即使是最坚固的磁石也毫无用处。在建立任何休息点之前，基础的篝火是必不可少的，那些不熟悉如何生火的人建议去寻找烹饪训练师。接受烹饪艺术的训练可以确保野外探险有足够的温暖和城墙之外生存所需的基本补给。"}},faq={{q="什么是Camping 101: Mining？",a="Camping 101: Mining是一项针对矿工的入门培训任务。它引导已证明自身能力的矿工前往剃刀岭寻找克鲁恩，以学习如何制作一种名为磁石的营地工具。",al={"什么是camping 101 mining","采矿露营任务","采矿磁石任务"}},{q="克鲁恩是谁？",a="克鲁恩是位于杜隆塔尔剃刀岭的一位训练师。当熟练的矿工展现出足够的专业技能时，他会指导他们如何打造磁石等营地物品。",al={"克鲁恩是谁","克鲁恩在哪里","剃刀岭训练师"}},{q="磁石有什么用？",a="磁石是一种由矿工制作的可制造营地设施。当放置在野外篝火旁时，它能使聚集在火堆周围的物理战斗者获得额外的战斗天赋，从而增强他们的作战能力。",al={"磁石有什么用","磁石的好处","为什么要制作磁石"}},{q="可以在剃刀岭内安营扎寨吗？",a="城镇居民和定居点当局不喜欢在人口稠密的街道中间搭建营地。你必须前往周边的荒野去扎营并放置你的磁石。",al={"我可以在城里露营吗","为什么我不能在剃刀岭露营","在城市内露营"}},{q="为什么在扎营前需要篝火？",a="每一个功能性的营地都需要以篝火为中心。基础篝火的建造由烹饪训练师教授，这使得烹饪成为前往荒野的露营者的一项重要辅助技能。",al={"我需要篝火吗","如何开始露营","露营的生火要求"}},{q="谁可以学习制作磁石？",a="制作磁石需要接受采矿专业的训练。在采矿技艺上展现出足够水平的矿工可以直接从剃刀岭的克鲁恩那里学习该技术。",al={"谁可以制作磁石","任何人都可以制作磁石吗"}}},fp="19,287,16.379.0,20.419.0,19.382.0,28.220.0,13.183.0,29.211.0,38.209.0,50.208.0,35.178.0"}
P.entries["quest:97908"] = {n="Camping 101: Skinning",s="《Camping 101: Skinning》是一项入门级的野外探索任务，它指引奥格瑞玛的剥皮师前往Thuwd处学习如何制作营地椅子。通过将采集到的毛皮用于野外休憩，冒险者可以在卡利姆多的荒野中建立合适的营地。",h="《Camping 101: Skinning》是一项入门级的野外探索任务，它指引奥格瑞玛的剥皮师前往Thuwd处学习如何制作营地椅子。通过将采集到的毛皮用于野外休憩，冒险者可以在卡利姆多的荒野中建立合适的营地。",kw={"营地椅子","营火","露营","camping 101: skinning","奥格瑞玛","剥皮","thuwd"},ang={["faction:Horde"]="Thuwd在奥格瑞玛训练剥皮师，这使得在杜隆塔尔活动的部落冒险者能够以独特的方式接触到这种野外工艺入门。",["profession:Cooking"]="一个合适的营地既需要座位也需要热源；我们鼓励新手剥皮师学习烹饪基础，掌握如何搭建基础营火。"},sec={{t="荒野中的舒适",b="采集倒下野兽的毛皮和皮革是冒险者在野外可以培养的最实用的生存技能之一。虽然生皮通常用于制皮，但熟练的剥皮师也能将采集到的毛皮转化成野外休憩的工具。在奥格瑞玛，导师会指引有能力的剥皮师去找Thuwd，学习用鞣制的皮革组装一把坚固的营地椅子的工艺。"},{t="旅行规则",b="城镇居民和卫兵不赞成旅行者在繁忙的城市街道上搭建临时营地。正如Thuwd提醒新工匠的那样，营地椅子是为远离定居点围墙的开阔地带准备的。此外，没有任何野外营地是单靠座位就能完善的；一个合适的营地还需要温暖的营火，这是卡利姆多各地的厨师都会教授的一项基本技术。"}},faq={{q="谁教剥皮师如何制作营地物品？",a="该任务指引剥皮师新手在证明了自己在采集工艺方面的基本熟练度后，前往部落主城奥格瑞玛，与剥皮和制皮训练师Thuwd交谈。",al={"谁提供 camping 101 skinning 任务","在奥格瑞玛找谁对话","thuwd是谁"}},{q="剥皮师可以制作什么营地物品？",a="剥皮师学习如何利用从倒下的野兽身上采集的毛皮和皮革来制作营地椅子。它提供了一个舒适的座位，让人们在野外时可以休息和恢复体力。",al={"剥皮师为营地制作什么","剥皮营地工艺","营地椅子剥皮"}},{q="可以在城市里架设营地椅子吗？",a="城市居民和卫兵不赞成在城镇中心架设营地设备。冒险者必须前往定居点大门之外的荒野，才能扎营并摆放椅子。",al={"我能在奥格瑞玛扎营吗","在城市内露营","在哪里扎营"}},{q="完成一个营地还需要什么？",a="没有用于保暖、照明和烹饪的火，营地就不完整。建议冒险者在扎营前咨询烹饪训练师，学习如何建造简单的营火。",al={"为什么需要营火","扎营先决条件","如何搭建营地"}},{q="为什么冒险者需要制作一把营地椅子？",a="在狩猎间隙坐在舒适的椅子上休息片刻，有助于冒险者从旅途中恢复体力，并确保他们在进入下一次冲突前保持最佳状态。",al={"剥皮对露营的益处","为什么要坐在营地椅子上休息","营地椅子的好处"}},{q="Thuwd什么时候会传授营地椅子图纸？",a="剥皮师必须证明自己在从倒下的野兽身上采集皮毛方面的基本熟练度，Thuwd才会分享制作野外营地家具的秘诀。",al={"什么时候可以学习营地椅子","camping 101 要求","需要的剥皮技能"}}},fp="21,260,19.381.0,18.353.0,44.209.0,37.172.0,42.203.0,41.191.0,44.181.0,45.167.0"}
P.entries["quest:97914"] = {n="Expanding Horizons",s="“Expanding Horizons”是一项始于黑海岸的外交信使任务，它将暗夜精灵定居点奥伯丁与人类王国暴风城直接联系起来。受桑德瑞斯·风织者之托，一位冒险者跨越重洋，将官方信件送达给城市建筑师巴隆斯·阿历克斯顿，旨在加强这两个遥远的联盟领地之间的联系与贸易。",h="“Expanding...",kw={"亚米萨兰","奥伯丁","巴隆斯·阿历克斯顿","巴莎兰","黑海岸","达纳苏斯","expanding horizons","港口","暴风城","桑德瑞斯·风织者"},ang={["faction:Alliance"]="这项任务展示了将跨越两块大陆的不同种族融合为一个运作良好的统一阵营，需要付出怎样的实际基层工作。",["race:Human"]="带着卡多雷避难所的印记回到暴风城，突显了这个重建王国的触角延伸和全球影响力。",["race:NightElf"]="对于卡多雷来说，开辟通往东部王国的海上航线，代表着对一万年来与世隔绝状态的根本性突破，使你们的种族与人类文明紧密地联系在了一起。"},sec={{t="跨越两半球",b="数千年来，暗夜精灵一直栖息在卡利姆多的森林中，与东部王国隔绝。第三次战争后，他们加入了大联盟，这使得双方不仅在意识形态上，更需要在后勤物流上建立真正的联系。奥伯丁是卡多雷大陆的主要北部港口，但长期以来，它一直处于亚米萨兰和巴莎兰等古老废墟城市的阴影之下。随着奥伯丁与暴风城之间直接海上航线的建立，当地领导人试图巩固这些新开辟的航运路线，并将他们的沿海社区融入到更广阔的联盟网络中。"},{t="给城市建筑师的信",b="这封穿越无尽之海的信件是专门写给暴风城城市建筑师巴隆斯·阿历克斯顿的。作为负责人类首都重建与基础设施建设的总建筑师，阿历克斯顿掌管着宏大的公共工程和物流事务。桑德瑞斯的目的更简单：他希望奥伯丁的工作得到认可，让它的家园为人所知。"}},faq={{q="是谁让你执行这项任务？",a="奥伯丁的一位有影响力的暗夜精灵桑德瑞斯·风织者将此任务交给旅行者。他感到奥伯丁既被高高在上的达纳苏斯所忽视，也被海洋彼岸的遥远盟友所遗忘，因此他寻求与人类王国建立正式的联系。",al={"任务发起人 expanding horizons","谁给予 expanding horizons","桑德瑞斯任务"}},{q="巴隆斯·阿历克斯顿是谁？",a="巴隆斯·阿历克斯顿是暴风城的城市建筑师。他是一位受人尊敬的城市规划师，年轻时曾结识艾德温·范克里夫，他负责监督整个首都的建筑和结构管理工作。",al={"巴隆斯·阿历克斯顿背景故事","巴隆斯是谁","暴风城城市建筑师"}},{q="为什么奥伯丁要寻求与暴风城的联系？",a="奥伯丁希望其港口能被视为补给、商业和联盟旅行的重要门户。随着黑海岸和东部王国之间新建立的海上航线，当地领导人希望加强与人类王国的经济和后勤联系。",al={"为什么寄信给暴风城","奥伯丁与暴风城的联系","为什么要联系人类"}},{q="奥伯丁和暴风城之间的交通是如何运作的？",a="一艘新船现在连接着奥伯丁与暴风城王国，它横跨无尽之海，直达暴风城港口，为奥伯丁的海岸带来了生机与补给。",al={"前往暴风城的船","如何从奥伯丁前往暴风城"}},{q="亚米萨兰和巴莎兰是什么？",a="它们曾是上古黑海岸繁荣的艾萨拉上层精灵城市，在一万年前大分裂粉碎了这片大陆之前。今天，它们沦为闹鬼的废墟，在卡多雷的历史中，它们往往比奥伯丁这样的现存村庄更被人铭记。",al={"亚米萨兰背景故事","巴莎兰","古代黑海岸城市"}},{q="为什么要把这封信交给建筑师，而不是安度因国王或伯瓦尔？",a="任务中没有说明桑德瑞斯为什么选择他。桑德瑞斯只是要求将这封信交给一位名叫巴隆斯·阿历克斯顿的人类，即暴风城的城市建筑师，以便奥伯丁的工作能得到认可。",al={"为什么是巴隆斯·阿历克斯顿","为什么不是伯瓦尔","为什么不是大领主伯瓦尔"}}},fp="18,372,24.620.0,31.370.0,28.266.0,22.201.0,43.263.0,53.180.0,36.261.0,66.187.0"}
P.entries["quest:97916"] = {n="Camping 101: Blacksmithing",s="《野营基础：锻造》是闪金镇的一项入门任务，指导铁匠制作野外装备。通过咨询铁匠阿古斯，熟练的金属工可以学会锻造一种用于野外旅行的便携式磨刀石。它强调了野外准备工作，重点介绍了在开阔地区建立工作营地和准备合适的篝火的必要性。",h="《野营基础：锻造》是闪金镇的一项入门任务，指导铁匠制作野外装备。通过咨询铁匠阿古斯，熟练的金属工可以学会锻造一种用于野外旅行的便携式磨刀石。它强调了野外准备工作，重点介绍了在开阔地区建立工作营地和准备合适的篝火的必要性。",kw={"锻造","篝火","野营","野营基础","艾尔文森林","闪金镇","磨刀石","铁匠阿古斯"},ang={["faction:Alliance"]="在闪金镇开启旅程的联盟工匠可以咨询铁匠阿古斯，为城镇围墙之外的长期探险做好准备。",["profession:Blacksmithing"]="在艾尔文森林学习手艺的铁匠可以制作磨刀石，以便在野外维护装备和磨砺利刃。",["profession:Cooking"]="一个合适的营地需要可靠的篝火，这使得基础烹饪训练成为野外金属加工的天然伙伴。"},sec={{t="行囊中的锻造",b="闪金镇的铁匠阿古斯为有志于成为金属工的玩家提供指导，教他们如何将手艺带到路上。比起只能在城镇的铁砧旁工作，展现出足够技巧的铁匠可以学习制作适合野外生存的实用装备。本次教学专注于锻造个人磨刀石，这是在长途旅行中保持利刃锋利的基本工具。"},{t="野外生活",b="建立营地不仅仅需要野外装备；适当的野外礼仪和准备工作也同样至关重要。镇民们不赞成在闪金镇这样的定居点中间扎营，这意味着工匠必须寻找开阔的边境地区来部署他们的装备。此外，没有温暖的篝火，野外营地就不算完整，因此拜访当地的烹饪师学习基本的生火技巧是必不可少的第一步。"}},faq={{q="什么是《野营基础：锻造》？",a="该任务向初级铁匠介绍生存工艺，教他们如何为野外探险锻造便携式磨刀石。",al={"该任务的作用","《野营基础：锻造》的目的","我能学到什么"}},{q="铁匠阿古斯是谁？",a="铁匠阿古斯是位于艾尔文森林闪金镇的常驻铁匠兼训练师。他指导有前途的铁匠进行基础的金属加工和野营工艺。",al={"铁匠阿古斯是谁","闪金镇铁匠训练师","阿古斯 闪金镇"}},{q="什么是磨刀石？",a="磨刀石是一种专业特定的野营物品，铁匠可以学习制作它以备探险之需，让他们在远离传统城镇铁匠铺的地方磨砺工具和武器。",al={"什么是磨刀石","野营 磨刀石","铁匠野营物品"}},{q="可以在镇内扎营吗？",a="镇民们不喜欢在像闪金镇这样的定居区扎营。铁匠必须前往野外才能部署他们的装备。",al={"我能在闪金镇扎营吗","在镇内扎营","我可以在哪里扎营"}},{q="为什么扎营需要篝火？",a="每个营地都需要一堆熊熊燃烧的篝火才算完整。建议铁匠在出发前咨询烹饪训练师，学习基本的生火技巧。",al={"扎营需要烹饪技能吗","营地篝火","如何建立营地"}},{q="什么时候可以学习这种野营工艺？",a="在铁匠阿古斯教你如何锻造专业的野营装备之前，你必须展现出足够的锻造技艺。",al={"《野营基础》的要求","锻造技艺要求"}}},fp="26,355,21.401.0,17.424.0,35.150.0,19.170.0,27.188.0,32.150.0,40.167.0,38.141.0"}
P.entries["quest:97917"] = {n="Camping 101: Enchanting",s="Camping 101: Enchanting 指导附魔师前往暴风城寻找贝蒂·奎因（Betty Quin），以学习专业的露营技巧。通过为附魔的鲁特琴等休闲物品注入魔法，附魔师能够帮助旅途中的人们保持高昂的士气和充分的休息。",h="Camping 101: Enchanting 指导附魔师前往暴风城寻找贝蒂·奎因（Betty...",kw={"贝蒂·奎因","露营","camping 101","camping 101: enchanting","附魔的鲁特琴","附魔","暴风城"},ang={["faction:Alliance"]="在联盟领地旅行的附魔师会被指引前往暴风城中心，寻找贝蒂·奎因以接受露营指导。"},sec={{t="旅途中的魔法",b="在艾泽拉斯的旅途中，生存所需的不仅仅是钢铁和口粮；在野外，士气和舒适度对于长途旅行的生存同样至关重要。附魔师可以为营火增添魔法色彩，利用他们深奥的技艺将宁静的休息时间转化为恢复性的娱乐活动，为旅行者应对前路的考验做好准备。"},{t="寻找贝蒂·奎因",b="想要制作特色露营物品的附魔师应前往暴风城寻找贝蒂·奎因。一旦修行者证明了其附魔技艺足够精湛，她就会传授制作附魔的鲁特琴所需的知识，这是一种编织了法术咒语、能在营火旁提振精神的乐器。"}},faq={{q="什么是 Camping 101: Enchanting？",a="Camping 101: Enchanting 指导附魔专业的修行者学习如何制作魔法露营用品。当附魔师磨练好技艺后，它会指引他们前往暴风城寻找贝蒂·奎因。",al={"什么是 camping 101 enchanting","camping 101 附魔师","附魔露营任务"}},{q="贝蒂·奎因是谁？",a="贝蒂·奎因是一位居住在暴风城的导师，她教导知识渊博的附魔师如何制作有用的魔法装备，以供在路途中的生存与休闲使用。",al={"贝蒂·奎因是谁","暴风城附魔训练师贝蒂","贝蒂·奎因在哪里"}},{q="什么是附魔的鲁特琴？",a="附魔的鲁特琴是一种注入了魔法的乐器，旨在为营地休息期间提供娱乐和士气加成，帮助冒险者在踏上旅途时面对困难。",al={"附魔的鲁特琴有什么用","为什么制作附魔的鲁特琴","附魔的鲁特琴用途"}},{q="为什么营地需要附魔师？",a="附魔师能为营地带来有益的魔法，将日常的休息时间转化为恢复、准备和娱乐的时刻，帮助旅行者忍受艰苦的荒野旅程。",al={"为什么营地需要附魔师","附魔师的营地作用"}},{q="我该去哪里完成这个任务？",a="该任务指引你在暴风城的主城内寻找贝蒂·奎因，该城市位于同名的王国之中。",al={"我在哪里提交 camping 101 enchanting","贝蒂·奎因位置"}},{q="学习露营附魔配方需要什么技能？",a="在贝蒂·奎因教你制作附魔的鲁特琴等露营物品之前，你必须展现出扎实的附魔造诣。",al={"camping 101 enchanting 要求","我什么时候可以学习附魔的鲁特琴"}}},fp="23,252,18.332.0,18.297.0,32.216.0,18.157.0,26.193.0,40.185.0,36.119.0,57.139.0"}
P.entries["quest:97919"] = {n="Camping 101: First Aid",s="Camping 101: First Aid向艾尔文森林的初出茅庐的冒险者们介绍了野外医疗这一实用的生存艺术。它指引旅行者前往闪金镇寻找Michelle Belle，学习如何为野外营地准备急救包。",h="Camping 101: First Aid向艾尔文森林的初出茅庐的冒险者们介绍了野外医疗这一实用的生存艺术。它指引旅行者前往闪金镇寻找Michelle Belle，学习如何为野外营地准备急救包。",kw={"绷带","营地急救包","camping 101","艾尔文森林","急救","闪金镇","michelle belle","生存"},ang={["class:Rogue"]="潜行者在远离支援的阴影中行动，他们依靠野外医疗在前往下一个目标前包扎流血的伤口。",["class:Warrior"]="没有与生俱来的治疗法术，前线战士在野外进行持久战时，严重依赖绷带和急救包来生存。",["faction:Alliance"]="闪金镇仍然是联盟旅行者从北郡开始旅程并进入广阔的艾尔文地区的重要十字路口。"},sec={{t="路途中的野外医疗",b="在艾尔文森林中旅行的冒险者很快就会发现，战斗和严酷的野外生存环境会带来沉重的代价。虽然城镇里的治疗者和旅店能提供喘息之机，但在危险地区穿行往往需要即时的、自给自足的护理。学习急救技能提供了一种治疗流血和外伤的实用方法，让旅行者无需依赖奥术仪式或圣光祈祷就能处理伤口。"},{t="营地补给",b="一个稳固的营地不仅仅是有火堆和睡袋，它是抵御野外危险的临时避风港。在闪金镇Lion's Pride Inn的Michelle Belle的指导下，技艺娴熟的修行者可以学会组装专门的急救包。在营地备好医疗物资，可以确保疲惫的队伍在面对前方的危险之前，能够处理伤势并恢复体力。"}},faq={{q="这个任务的目的是什么？",a="这个任务引导已经掌握了基础急救技能的冒险者去寻找闪金镇的Michelle Belle。她会教导修行者如何制作急救包，以便让他们的野外营地储备必要的医疗物资。",al={"露营急救目的","这个任务是做什么的","为什么camping 101 first aid"}},{q="我需要在闪金镇与谁交谈？",a="你需要与闪金镇的训练师Michelle Belle交谈。一旦你证明了自己拥有足够的急救技能，她就会分享制作适合野外医疗的露营补给品所需的技巧。",al={"michelle belle是谁","闪金镇急救训练师","营地急救训练师"}},{q="为什么急救对旅行者很重要？",a="冒险总是伴随着来自野兽、强盗和恶劣环境的身体伤害风险。急救让任何人，无论是否掌握神圣或奥术魔法，都能在战斗间隙包扎伤口并恢复状态。",al={"为什么要学急救","急救是否有用","急救背景知识"}},{q="闪金镇在哪里？",a="闪金镇是艾尔文森林的主要村庄，位于暴风城以南的主贸易道路上。它是补给、本地训练师和在Lion's Pride Inn休息的中心枢纽。",al={"闪金镇在哪里","闪金镇位置","如何找到michelle belle"}},{q="我需要先前的训练才能完成这个任务吗？",a="是的。Michelle Belle要求你在她教你制作适合该专业的营地急救包之前，先证明你在急救方面的熟练程度。",al={"camping 101要求","所需的急救技能","前置条件"}},{q="急救包如何应用在露营中？",a="野外营地提供了一个安全的休整区域，而配备急救包可以确保受伤的流浪者能够及时获得包扎和治疗，从而在远离城镇医疗者的地方挽救生命。",al={"营地急救包用途","露营物品急救","为什么要制作急救包"}}},fp="22,239,26.409.0,25.391.0,34.232.0,41.207.0,41.226.0,27.208.0,47.151.0,42.221.0"}
P.entries["quest:97920"] = {n="Camping 101: Fishing",s="Camping 101: Fishing向艾尔文森林的初级垂钓者介绍了荒野生存和露营设施的实用工艺。通过寻找闪金镇附近的当地钓鱼专家Lee Brown，旅行者可以学习如何将他们的垂钓知识应用于制作舒适的露营地装饰，比如能鼓舞冒险者士气的装饰性鱼缸。",h="Camping 101: Fishing向艾尔文森林的初级垂钓者介绍了荒野生存和露营设施的实用工艺。通过寻找闪金镇附近的当地钓鱼专家Lee...",kw={"露营工艺","camping 101: fishing","水晶湖","艾尔文森林","鱼缸","闪金镇","lee brown"},ang={["faction:Alliance"]="在艾尔文森林开始冒险的人类旅行者可以依靠闪金镇熟悉的水域来学习基本的荒野自给自足技能。"},sec={{t="垂钓者的露营工艺",b="虽然钓鱼常被认为是一种在安静的湖岸和河边进行的孤独消遣，但经验丰富的生存专家明白，露营生活需要的不仅仅是食物和住所。制作像鱼缸这样令人舒适的装置，能为在探险间隙休息的疲惫旅行者带来轻松和士气，这强化了一种信念：健全的心智和高昂的斗志能造就强大的战士。"},{t="Lee Brown的专业知识",b="经验丰富的垂钓者Lee Brown驻扎在闪金镇外的水域旁，为寻求扩展技艺的初级渔夫提供协助。那些展示出足够钓竿和鱼线熟练度的垂钓者会被指引去向他请教如何将简单的渔获和基础材料转化为功能性的露营地强化物品。"}},faq={{q="这个任务的目的是什么？",a="该任务将有志向的垂钓者指引至闪金镇附近的Lee Brown处。一旦你展示了基础的钓鱼熟练度，他就会教你如何制作专门的露营物品，例如鱼缸，来美化路边的营地。",al={"为什么要露营钓鱼","camping 101有什么用","任务目的"}},{q="Lee Brown是谁？",a="Lee Brown是一位知识渊博的钓鱼训练师，驻扎在艾尔文森林闪金镇外侧的水晶湖畔。他提供垂钓指导，并教授如何建造专为垂钓者设计的露营工艺品。",al={"lee brown在哪里","谁教授露营钓鱼","lee brown"}},{q="鱼缸对营地有什么用？",a="鱼缸是一种露营装置，旨在为休息的冒险者带来舒适和快乐。宜人的露营环境能提升士气，帮助冒险者在面对荒野危险时感到准备充分且能力出众。",al={"鱼缸的效果","鱼缸的作用","为什么要制作鱼缸"}},{q="这种训练在哪里进行？",a="该任务发生在艾尔文森林，引导玩家前往闪金镇周边当地垂钓者聚集的水域。",al={"任务地点","我要去哪里","艾尔文森林露营训练师"}},{q="我需要有之前的钓鱼技能才能完成吗？",a="是的。Lee Brown只会指导那些已经练习过抛竿并展示了钓鱼行业基本熟练度的旅行者。",al={"钓鱼技能要求","需要钓鱼技能吗","熟练度要求"}},{q="露营对战斗有帮助吗？",a="是的。一个维护良好的营地能提供舒适感，从而增强冒险者的身心准备，并直接反映在他们在野外的韧性和战斗效率上。",al={"露营有助战斗吗","露营增益","为什么要露营"}}},fp="20,358,21.392.0,21.312.0,34.220.0,17.215.0,40.218.0,36.123.0,50.138.0,29.187.0"}
P.entries["quest:97921"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism是一项训练任务，旨在引导熟练的采集者前往艾尔文森林寻求专业的野外指导。在展示了采集植物的熟练技巧后，草药师将被指引去寻找Herbalist Pomeroy，学习制作营地用品的艺术。完成此项训练将解锁制作熏香蜡烛的能力，这种植物辅助品旨在为在野外休息的施法者提供专注力与精神上的支持。",h="Camping 101: Herbalism是一项训练任务，旨在引导熟练的采集者前往艾尔文森林寻求专业的野外指导。在展示了采集植物的熟练技巧后，草药师将被指引去寻找Herbalist...",kw={"营地","camping 101","艾尔文森林","治疗者","草药学","herbalist pomeroy","熏香蜡烛","施法者"},ang={["class:Mage"]="法师在野外非常重视熏香蜡烛那种舒缓的植物特性，这使得草药师同伴在漫长的野外旅行中格外受欢迎。",["class:Priest"]="牧师和其他虔诚的治疗者能从靠近熏香蜡烛的休息中获益良多，它能振奋精神并帮助在远征期间恢复重要的能量。",["faction:Alliance"]="由于Herbalist Pomeroy居住在艾尔文森林，联盟的冒险者可以轻松方便地获得这项专业的营地指导。",["profession:Herbalism"]="此任务将草药学从一种简单的采集行业提升为一种主动的营地支持角色，使植物学家能够制作出协助旅行同伴的熏香蜡烛。"},sec={{t="旅途中的植物用品",b="对于漫游的草药师来说，在艾泽拉斯的荒野中采集草药，其目的远不止于酿制基础的恢复药水或将成捆的花束卖给城市商人。随着从业者磨练他们的采集技艺，将植物学知识应用于野外生存的机会随之而来。野外营地需要的不仅仅是熊熊燃烧的营火和干燥的睡袋；维持旅行团队的耐力和精神敏锐度需要专业的舒适保障。经验丰富的采集者知道，某些植物具有能够振奋疲惫心灵的芳香特性。通过将有潜力的草药师引荐给资深的导师，这项任务将简单的采集与实用的野外生存技巧结合在了一起，证明了对自然馈赠的敏锐洞察力可以支撑整个远征队在远离文明的地方生存下去。"},{t="Herbalist Pomeroy的指引",b="渴望拓展营地技艺的草药师学徒将被派往艾尔文森林的中心地带，去请教Herbalist Pomeroy。Pomeroy精通周边林地的各种植物，她深知如何将干燥的花瓣、芳香的茎秆和天然树脂混合制成实用的营地装备。她不再仅仅让草药师将药草用于炼金药剂，而是指导他们制作熏香蜡烛。在营地燃烧时，这种芬芳的创作能够安抚疲惫的旅行者，并鼓舞依赖法力的同伴。找到Pomeroy并证明自己使用镰刀的熟练程度，将确保草药师成为任何冒险进入蛮荒之地的探险队中不可或缺的一员。"}},faq={{q="什么是Camping 101: Herbalism？",a="Camping 101: Herbalism是一项入门任务，指导经验丰富的草药师如何将他们的采集行业扩展到营地用品的制作上。它指引玩家前往艾尔文森林会见Herbalist Pomeroy，她将传授如何为野外营地制作专门的熏香蜡烛。",al={"camping 101 herbalism 任务","草药学营地任务","什么是 camping 101 herbalism"}},{q="谁传授草药师的营地配方？",a="Herbalist Pomeroy传授草药学营地配方。她位于艾尔文森林，在那里她分享关于当地植物的知识，并指导熟练的采集者如何制作芳香的熏香蜡烛以增强他们在营地的休息效果。",al={"谁传授草药学营地技能","camping 101 训练师","herbalist pomeroy 在哪里","herbalist pomeroy 位置"}},{q="通过此任务，草药师学会制作什么物品？",a="完成此项训练后，草药师可以为他们的营地制作熏香蜡烛。使用采集到的草药和植物材料制成的蜡烛，能散发出舒缓的香气，提振精神，并为在野外休息的施法者和治疗者提供受欢迎的增益效果。",al={"草药师为营地制作什么","草药学营地物品","熏香蜡烛 草药学","camping 101 教授什么"}},{q="开始Camping 101: Herbalism有哪些要求？",a="在接受此任务之前，你必须练习草药学专业并展示出足够的采集熟练度。一旦你的草药学技能超过了新手水平，导师们就会认为你已足够老练，可以从Herbalist Pomeroy那里学习如何准备植物营地用品了。",al={"camping 101 herbalism 要求","什么时候可以接取 camping 101 herbalism","camping 101 所需草药学技能"}},{q="为什么熏香蜡烛对探险队有用？",a="熏香蜡烛释放出的舒缓草药香气可以提升士气并恢复精神专注。在野外，施法者和治疗者需要消耗巨大的精力来引导魔法力量，这使得这些香氛蜡烛所带来的精神和魔法增益在野外休整期间显得尤为宝贵。",al={"熏香蜡烛有什么用","为什么要制作熏香蜡烛","熏香蜡烛的好处","草药学熏香蜡烛用途"}},{q="此任务在哪里进行？",a="任务目标引导冒险者前往艾尔文森林，这片环绕着暴风城的茂密林地。玩家将前往艾尔文乡间咨询Herbalist Pomeroy，完成任务并解锁制作植物类营地补给的能力。",al={"camping 101 herbalism 区域","去哪里提交 camping 101 herbalism","艾尔文森林草药学任务"}},{q="非草药师可以制作熏香蜡烛吗？",a="不能，制作熏香蜡烛直接与草药学专业挂钩。该配方依赖于对野生植物、花卉保存和芳香精油的专业理解，这些知识由Herbalist Pomeroy专门传授给那些采集植物的冒险者。",al={"任何人都能制作熏香蜡烛吗","熏香蜡烛是草药学专属吗","制作熏香蜡烛需要草药学吗"}}},fp="22,450,32.806.0,33.739.0,31.293.0,46.240.0,55.276.0,58.300.0,55.310.0,33.278.0,44.262.0"}
P.entries["quest:97922"] = {n="Camping 101: Leatherworking",s="《露营指南：制皮》指引制皮学徒前往闪金镇寻找阿黛尔·菲尔德，学习制作旅行帐篷的手艺。在野外搭建帐篷可以提供遮蔽和休息，帮助冒险者抵御恶劣天气，是定居城镇之外重要的生存工具。",h="《露营指南：制皮》指引制皮学徒前往闪金镇寻找阿黛尔·菲尔德，学习制作旅行帐篷的手艺。在野外搭建帐篷可以提供遮蔽和休息，帮助冒险者抵御恶劣天气，是定居城镇之外重要的生存工具。",kw={"阿黛尔·菲尔德","篝火","露营","艾尔文森林","闪金镇","制皮","帐篷","荒野求生"},ang={["faction:Alliance"]="这项训练以艾尔文森林的闪金镇为基地，旨在引导联盟制皮师学习实用的生存工艺，以应对他们在艾泽拉斯各地的旅程。",["profession:Cooking"]="阿黛尔·菲尔德指出，没有篝火的野外营地是不完整的，她敦促旅人们学习烹饪，掌握如何点燃一堆合适的火焰。"},sec={{t="广阔道路上的庇护所",b="对于在城门外漫游的冒险者来说，住所与护甲同样重要。艾尔文森林的制皮师们被指引前往闪金镇的阿黛尔·菲尔德那里，以学习制作腰带和外套之外的新手艺。一旦工匠证明了自己对兽皮和针线的熟练掌握，阿黛尔就会传授这种实用的技术：制作能抵御长途远征中恶劣天气的耐用露营帐篷。"},{t="露营基础",b="完成的帐篷不仅仅是装饰性的遮蔽物；它能在烈日下为疲惫的旅人提供阴凉，在暴雨中保持干燥，并在危险的遭遇战之间提供充分的休息。然而，野外礼仪和城市条例同样重要：闪金镇的居民和城市守卫绝不容忍在城镇街道中间搭建营地。工匠必须前往广阔的野外来设立营地。阿黛尔还提醒所有旅人，没有从烹饪训练师那里学到的篝火，露营地就不算完整。"}},faq={{q="谁教导制皮师如何制作帐篷？",a="阿黛尔·菲尔德位于艾尔文森林的闪金镇。一旦合格的制皮师证明了他们的工艺水平，她就会教导他们如何制作坚固的求生帐篷。",al={"谁提供帐篷训练","阿黛尔·菲尔德位置","制皮帐篷导师"}},{q="制作出的帐篷有什么用？",a="精心制作的帐篷可以保护旅人免受极端天气的侵袭，在炎热的日子里保持凉爽，在倾盆大雨中保持干燥。更重要的是，它能为冒险者提供在荒野旅行时保持敏锐所需的休息。",al={"为什么要制作帐篷","帐篷有什么作用","帐篷的好处"}},{q="可以在城镇内搭帐篷吗？",a="帐篷不能随意搭建；城镇居民不喜欢旅人在街道或城镇中心堆放露营地。冒险者应该带着装备去野外妥善设立营地。",al={"可以在镇里搭帐篷吗","在哪里可以使用帐篷","在暴风城或闪金镇使用帐篷"}},{q="除了帐篷，搭建营地还需要什么？",a="仅有一个帐篷并不能构成一个功能齐全的营地。阿黛尔·菲尔德强调，每个合格的营地都需要篝火，它在野外提供了温暖和实际的用途。",al={"搭建营地还需要什么","帐篷和篝火需求","如何完成营地"}},{q="旅人在哪里可以学习建造篝火？",a="烹饪训练师和当地厨师会教授点燃篝火的基本知识。准备露营的冒险者被建议学习烹饪艺术，这样无论走到哪里，他们都知道如何生起可靠的火堆。",al={"谁教导篝火","如何学习篝火","营地用火"}},{q="制皮师什么时候可以学习制作露营帐篷？",a="有志于此的制皮师必须首先证明自己在制皮方面的熟练度，阿黛尔·菲尔德才会教导他们制作帐篷。一旦展现出足够的工艺水准，就可以学习该项技术。",al={"帐篷技能需求","如何获取帐篷配方","什么时候可以制作帐篷"}}},fp="27,277,25.402.0,27.521.0,46.203.0,39.246.0,35.215.0,56.175.0,47.212.0,55.206.0"}
P.entries["quest:97923"] = {n="Camping 101: Mining",s="“Camping 101: Mining”是一项入门任务，旨在教导矿工如何制作磁石来强化野外营地。在暴风城的Gelman Stonehand指导下，勘探者们将学会引导共鸣大地技艺，以增强伙伴们在营火旁的战斗能力。",h="“Camping 101: Mining”是一项入门任务，旨在教导矿工如何制作磁石来强化野外营地。在暴风城的Gelman Stonehand指导下，勘探者们将学会引导共鸣大地技艺，以增强伙伴们在营火旁的战斗能力。",kw={"营火","camping 101: mining","营地","gelman stonehand","磁石","采矿","暴风城","荒野"},ang={["faction:Alliance"]="Gelman Stonehand在暴风城工作，指导联盟的工匠们将原始的大地技艺转化为实用的野外工具。",["profession:Cooking"]="营地的运作从根本上依赖于照料良好的营火，这使得基础烹饪训练成为专业营地配件不可或缺的伙伴。",["profession:Mining"]="磨练过技艺的矿工可以锻造磁石来强化他们的野外营地，为在身旁休息的盟友提供武力加成。"},sec={{t="大地共鸣之力",b="采矿是一门艰苦而诚实的劳动，但它的回报远不止于熔炼矿锭和锻造护甲。暴风城的专业矿工可以学习如何将大地天然的磁性引导至功能性的磁石中。当放置在远征营地时，这种石头能增强围坐在营火旁的任何战士的战斗活力。身为王国首都经验丰富的采矿训练师，Gelman Stonehand会将这门手艺传授给证明了自己镐法娴熟的勘探者们。"},{t="野外营地与营火",b="磁石不能随意丢弃在大教堂广场或贸易区的鹅卵石路上。城镇居民对于在城市范围内搭建临时营地的旅行者持排斥态度，这意味着先驱者们必须前往荒野去建立营地。此外，如果没有营火这一温暖的基础，像磁石这样的专业装备将毫无用处，而营火本身是整个领域内厨师都会传授的一种基础野外生存技能。"}},faq={{q="什么是“Camping 101: Mining”？",a="这项任务旨在向矿工介绍制作专业营地强化物品的艺术。一旦你证明了自己在采矿方面的造诣，就可以与暴风城的Gelman Stonehand交谈，学习如何锻造磁石。",al={"什么是camping 101 mining","任务目标","我该做什么"}},{q="谁教授磁石图纸？",a="Gelman Stonehand是一位位于暴风城的采矿训练师。他教导合格的矿工如何制作磁石，以支持他们在野外的远征。",al={"谁教授磁石","gelman stonehand在哪里","stonehand位置"}},{q="磁石有什么作用？",a="磁石是一种放置在野外营地的物品。它会在营火周围散发出一种强化能量，提升聚集在此休息的战士和其他武技斗士的战斗实力。",al={"磁石有什么作用","磁石增益","为什么要做磁石"}},{q="我可以在暴风城内扎营吗？",a="城市当局和普通民众不喜欢人们在城镇广场或城市街道上扎营。你必须前往定居点大门之外的荒野，才能扎营并部署你的磁石。",al={"我可以在城镇里扎营吗","我在哪里可以放置营地","扎营限制"}},{q="为什么扎营时需要营火？",a="在可以使用任何专业营地装备之前，每个营地都需要一个基础营火作为核心基础。厨师通常会教旅行者如何用简单的木材和燧石生火。",al={"扎营需要烹饪技能吗","如何搭建营地","营火需求"}},{q="谁从磁石的聚集中受益最大？",a="任何挥舞刀剑、斧头或锤子的人都能从磁石的力量中获益匪浅。它散发出一种额外的武力优势，战士们在危险战斗前围坐在火堆旁休息时，正是为了寻求这种加成。",al={"谁能从磁石中获益","磁石适合近战吗","磁石职业"}}},fp="19,281,26.496.0,30.439.0,28.209.0,36.163.0,25.207.0,35.210.0,40.192.0,52.198.0"}
P.entries["quest:97924"] = {n="Camping 101: Skinning",s="Camping 101: Skinning是一项针对在艾尔文森林中旅行的熟练剥皮者的入门指导任务。它指引冒险者前往闪金镇寻找赫琳·皮皮斯金，学习如何用收集的皮革制作一把营地椅子。学会制作个人营地用品可以让荒野旅行者在远离城镇安全区的地方休息和恢复。",h="Camping 101...",kw={"营地椅子","营火","camping 101: skinning","闪金镇","赫琳·皮皮斯金","剥皮","荒野露营"},ang={["faction:Alliance"]="造访艾尔文森林的新手联盟剥皮者会被指引前往闪金镇的赫琳·皮皮斯金处，以提升他们的荒野生存技能。",["profession:Cooking"]="学习搭建野外营地的剥皮者建议咨询厨师，因为没有用于保暖和烹饪食物的简单营火，营地就不算完整。"},sec={{t="荒野中的生活舒适度",b="对于荒野猎人和侦察兵来说，采集兽皮的艺术不仅仅是为了获取贸易商品和护甲废料。经验丰富的剥皮者可以制作营地椅子等野外生活用品，让旅行者能够坐下来休息肢体，并在穿越危险地区的漫长旅途中保持最佳身体状态。闪金镇的赫琳·皮皮斯金会指导熟练的剥皮者如何将生兽皮转化为舒适的营地座椅。"},{t="营地规则",b="建立野外休息点需要尊重当地定居点，并做好适当的户外准备。大多数城镇居民反感冒险者在城镇广场搭建个人营地，因此旅行者必须前往荒野地区才能展开装备。此外，如果没有营火，任何野外营地都无法真正发挥作用，这促使许多剥皮者学习基本的烹饪艺术来掌握生火技巧。"}},faq={{q="什么是Camping 101: Skinning？",a="Camping 101: Skinning是一项入门训练任务，指导熟练的剥皮者学习如何用收集的兽皮制作营地椅子，从而扩展他们的荒野生存能力。",al={"什么是camping 101 skinning","这个任务有什么用","剥皮营地椅子任务"}},{q="谁教授剥皮者如何制作营地椅子？",a="赫琳·皮皮斯金是一位位于艾尔文森林闪金镇的制皮和剥皮训练师，她负责教授熟练的剥皮者如何制作这种椅子。",al={"谁教授营地椅子","赫琳·皮皮斯金位置","camping 101 skinning在哪里交任务"}},{q="制作营地椅子的目的是什么？",a="营地椅子可以为冒险者在他们的营地中提供一个舒适的座位，用于休息和恢复，确保他们保持最佳状态以应对荒野中的旅行和战斗。",al={"营地椅子有什么用","为什么要制作营地椅子","营地椅子用途"}},{q="冒险者可以在哪里安营扎寨？",a="城镇居民通常不喜欢在定居点中心搭建营地。冒险者在架设椅子和营地之前，应当先进入荒野地区。",al={"我可以在镇里露营吗","我可以在哪里放置营地椅子","在闪金镇露营"}},{q="搭建一个完整的营地还需要什么？",a="在布置装备之前，每一个正式的营地都需要基本的营火。不懂生火技术的冒险者，建议向当地厨师学习烹饪艺术。",al={"露营需要什么","露营需要营火吗","营火要求"}},{q="谁有资格学习这种露营工艺？",a="这种特殊的露营工艺是为那些已经在剥取野兽毛皮方面证明了熟练度的剥皮者量身定制的，他们可以将野外采集的皮革用于实际的生存用途。",al={"谁可以学习营地椅子","非剥皮者可以做这个吗","露营的剥皮要求"}}},fp="21,368,29.435.0,21.394.0,30.200.0,47.149.0,45.173.0,34.188.0,51.174.0,44.199.0"}
P.entries["quest:97925"] = {n="Camping 101: Tailoring",s="《露营指南101：裁缝》引导技艺高超的裁缝前往艾尔文森林东谷伐木场的埃尔德林处。通过他，裁缝们可以学习编织阵营旗帜，这种旗帜能为野外营地带来激励效果，并提升士气。",h="《露营指南101：裁缝》引导技艺高超的裁缝前往艾尔文森林东谷伐木场的埃尔德林处。通过他，裁缝们可以学习编织阵营旗帜，这种旗帜能为野外营地带来激励效果，并提升士气。",kw={"旗帜","露营","露营指南101","东谷伐木场","埃尔德林","艾尔文森林","阵营旗帜","裁缝"},ang={["faction:Alliance"]="联盟冒险者被指引前往艾尔文森林东谷伐木场的埃尔德林处，以学习阵营旗帜的缝制方法。",["profession:Tailoring"]="裁缝可以编织一面鼓舞人心的阵营旗帜，以在长期探险期间提振士气，并使营地保持充沛的精力。"},sec={{t="编织者在野外的使命",b="《露营指南101：裁缝》将有前途的缝纫工引向埃尔德林，一位常驻在艾尔文森林东部东谷伐木场的工匠。裁缝往往因制作防护性布甲和背包而受到赞誉，但这项任务强调了其在维持野外探险方面的重要作用。对于那些证明了自己在针线和织布机方面拥有才能的冒险者，埃尔德林会提供专业的指导，帮助他们制作出支持在荒野中长期旅行的露营装备。"},{t="士气旗帜",b="这项指导中教授的主要工艺是阵营旗帜，这是一种设计用于在旅行者营火旁竖立的标志。无论是在危险的旅途中还是战场上，保持高昂的士气与维护武器或口粮同样重要。在营地上方展示一面鼓舞人心的旗帜，能为疲惫的冒险者提供熟悉的决心象征，赋予他们深入敌境所需的能量。"}},faq={{q="《露营指南101：裁缝》的目的是什么？",a="《露营指南101：裁缝》引导有抱负的裁缝寻找位于艾尔文森林东谷伐木场的埃尔德林。一旦裁缝展示出足够的熟练度，埃尔德林就会指导他们如何缝制一面鼓舞人心的阵营旗帜，以提振营地士气。",al={"什么是露营指南101裁缝","裁缝营地物品任务","如何获得营地旗帜"}},{q="埃尔德林是谁？在哪里可以找到他？",a="埃尔德林是一位居住在艾尔文森林东部东谷伐木场的工匠。他拥有指导熟练裁缝制作适用于营地的阵营旗帜的专业知识。",al={"埃尔德林是谁","埃尔德林在哪里","埃尔德林位置"}},{q="阵营旗帜对营地有什么作用？",a="阵营旗帜是营地的核心装饰，旨在促进士气和激发灵感。在野外，展示你的阵营立场有助于让疲惫的旅行者在艰苦的战役中保持活力和专注。",al={"裁缝旗帜有什么作用","阵营旗帜露营","为什么要制作阵营旗帜"}},{q="从埃尔德林那里学习这门工艺需要什么条件？",a="在埃尔德林传授该技术之前，需要展示出在裁缝方面的熟练度。只有磨练过针线活的从业者才能正确地编织和组装这种旗帜。",al={"我需要什么技能","露营旗帜要求","任何裁缝都能制作旗帜吗"}},{q="东谷伐木场位于哪里？",a="东谷伐木场坐落在艾尔文森林东部的树林中，位于通往赤脊山的道路沿线。这是一个活跃的伐木中心，当地的工匠和工人们聚集于此。",al={"东谷伐木场在哪里","艾尔文森林东谷伐木场"}},{q="这项任务是联盟裁缝独有的吗？",a="这项特定的任务会将工匠送往位于艾尔文森林中心地带的埃尔德林处，这里完全处于联盟领地。因此，它服务于在东部定居点运作的联盟阵营工匠。",al={"部落可以做这个任务吗","这是联盟专属吗"}}},fp="22,234,30.473.0,17.433.0,46.267.0,40.179.0,43.211.0,60.191.0,43.207.0,43.206.0"}
P.entries["quest:97926"] = {n="Making Do",s="“Making Do”是一个连接黑海岸的奥伯丁港口与遥远的暴风城王国的联盟任务。探险家受托将巴隆斯·阿历克斯顿的一封正式回复送交给桑德拉斯·风织者长老，却带来了一个严峻的消息：暴风城日益枯竭的国库已经无力援助这个陷入困境的暗夜精灵定居点。",h="“Making...",kw={"阿历克斯顿","阿历克斯顿的回复","奥伯丁","国库","黑海岸","making do","暴风城","桑德拉斯·风织者"},ang={["faction:Alliance"]="这个任务突显了联盟内部脆弱的凝聚力，说明了地理距离和内部压力是如何让像奥伯丁这样的偏远定居点在没有暴风城财政支持的情况下只能自谋生路。",["race:Human"]="阿历克斯顿的信反映了暴风城王国所面临的严峻现实，国库枯竭和广泛的国内困境使王室无法为海外救援行动提供资金。",["race:NightElf"]="对于奥伯丁的暗夜精灵来说，暴风城的拒绝更加深了他们的认识，即无论是远在海对岸的人类盟友，还是近在咫尺的达纳苏斯，都没有站出来解决他们的当地困难。"},sec={{t="跨海信使",b="“Making Do”任务要求旅行者带着阿历克斯顿的回复穿越海洋，送交奥伯丁的桑德拉斯·风织者长老。这封信里并非援助承诺或派兵部署，而是一份不幸的拒绝信。暴风城的代表惋惜地表示，王国的财政已经捉襟见肘，仅存的那点财富也已经难以维持其自身苦苦挣扎的领土。"},{t="自生自灭",b="在收到回复后，桑德拉斯·风织者对结果深感惋惜，但感谢了旅行者完成这段漫长的旅途。由于暴风城无法提供援助，达纳苏斯也同样缺席，桑德拉斯只能无奈地接受现实，让族人自食其力，并感叹奥伯丁的命运完全掌握在他们自己手中。"}},faq={{q="“Making Do”是什么任务？",a="“Making Do”是一个任务，探险家需要将巴隆斯·阿历克斯顿从暴风城寄来的正式回复送回奥伯丁，交给桑德拉斯·风织者长老，信中带着令人失望的消息，即暴风城无力支援黑海岸。",al={"什么是making do","making do任务","奥伯丁暴风城任务"}},{q="为什么暴风城拒绝援助奥伯丁？",a="暴风城的代表解释说，王国的国库已经严重亏空，仅存的资源在支撑其本土领土时已十分勉强，导致他们无法资助奥伯丁。",al={"为什么暴风城拒绝","暴风城国库空虚","为什么暴风城不援助奥伯丁"}},{q="桑德拉斯·风织者对这个消息有何反应？",a="桑德拉斯·风织者怀着沉重的心情收下了这封信，但接受了现实，结论是既然暴风城和达纳苏斯都不会提供支持，奥伯丁的人民只能掌握自己的命运。",al={"桑德拉斯对暴风城的反应","桑德拉斯作何反应"}},{q="是谁寄出了阿历克斯顿的回复？",a="巴隆斯·阿历克斯顿是暴风城的城市建筑师，他传达了王国的回应，在传达暴风城无力提供经济援助的残酷事实的同时，也表达了对奥伯丁困境的个人同情。",al={"阿历克斯顿是谁","阿历克斯顿的回复发送者"}},{q="达纳苏斯在帮助奥伯丁吗？",a="在读过阿历克斯顿的信后，桑德拉斯·风织者指出，无论是暴风城还是他们附近的首都达纳苏斯，都没有伸出援手，导致奥伯丁定居点孤立无援，只能靠自己。",al={"达纳苏斯援助奥伯丁","为什么达纳苏斯不提供帮助"}},{q="阿历克斯顿的回复是在哪里交付的？",a="该任务在黑海岸沿岸的奥伯丁港口小镇结束，桑德拉斯·风织者正在那里等待从暴风城归来的信使。",al={"该任务在哪里结束","making do交接地点"}}},fp="9,322,24.392.0,22.316.1,28.231.0,43.211.0,47.222.0,26.214.0,31.205.0,36.156.0"}
P.entries["quest:97932"] = {n="Camping 101: Fishing",s="Camping 101: Fishing 向垂钓者介绍了如何用手工制品装饰野外营地。通过向血蹄村的 Uthan Stillwater 展示精湛的技艺，渔夫们可以学会制作鱼缸，为在野外休息的旅行者带来鼓舞士气的乐趣。",h="Camping 101: Fishing 向垂钓者介绍了如何用手工制品装饰野外营地。通过向血蹄村的 Uthan Stillwater 展示精湛的技艺，渔夫们可以学会制作鱼缸，为在野外休息的旅行者带来鼓舞士气的乐趣。",kw={"血蹄村","营火","露营","camping 101: fishing","鱼缸","钓鱼","莫高雷","uthan stillwater"},ang={["faction:Horde"]="穿行于莫高雷的部落垂钓者可以从血蹄村的 Uthan Stillwater 那里学习制作营地设施。",["profession:Cooking"]="每个像样的营地都需要一个基本的营火才能开始，这使得基本的烹饪训练成为任何渔夫野外营地的天然补充。"},sec={{t="野外垂钓",b="穿行于莫高雷的垂钓者可以通过 Camping 101: Fishing 将他们安静的消遣转化为实用的营地工艺。已经证明了自己拥有精湛钓鱼技术的冒险者应前往血蹄村寻找 Uthan Stillwater。熟练的渔夫不仅能提供食物，还能学会为野外生活制作一件家居饰品：一个能让营地增色的个人鱼缸。"},{t="营地舒适度",b="对于饱经风霜的流浪者来说，鱼缸可能是一个奇怪的伙伴，但一个舒适的休息点会让旅途获益匪浅。这个小装置为严酷的荒野带来了一丝轻松与宁静，为在火焰旁休息的任何人提振士气。正如老练的生存专家所知，高昂的精神直接转化为敏锐的直觉和更强的战斗韧性。"},{t="营火与旷野",b="搭建营地既需要尊重当地习俗，也需要扎实的基本功。像血蹄村这样的定居点不允许旅行者在城镇中央搭建临时营地，这意味着鱼缸只能在广阔的荒野中测试。此外，没有合适的营火就无法建立营地，这要求有抱负的露营者寻找烹饪训练师，掌握基本的生火技能。"}},faq={{q="鱼缸对营地有什么作用？",a="鱼缸是由熟练的渔夫制作的装饰性营地设施。它的设计初衷是为在荒野中休息的冒险者带来快乐和舒适，保持高昂的士气，使他们在战斗中保持敏锐和能力。",al={"鱼缸营地","鱼缸的作用","鱼缸的好处"}},{q="谁传授鱼缸配方？",a="Uthan Stillwater 在位于莫高雷草海平原的血蹄村传授这门手艺。他会指导那些已经在钓鱼技能上展现出足够熟练度的垂钓者。",al={"哪里学习鱼缸制作","谁传授鱼缸","uthan stillwater 的位置"}},{q="为什么不能在定居点内搭建营地？",a="城镇居民和村庄守卫通常不赞成旅行者在街道中央搭建完整的营地并点火。营地必须搭建在野外的旷野之中。",al={"在城镇内露营","为什么不能在血蹄村露营","在城市内露营"}},{q="搭建营地还需要什么？",a="没有以营火为核心，合适的营地就无法运作。没有生火技能的旅行者建议在搭建营地前寻找烹饪训练师，掌握生火的艺术。",al={"露营需要营火","露营需要生火","露营基础生火"}},{q="学习鱼缸前需要满足什么要求？",a="在 Uthan Stillwater 分享制作营地设施的秘密之前，需要证明在钓鱼方面的熟练度。新手垂钓者需要先花些时间在水边磨练自己的技艺。",al={"钓鱼熟练度与露营","什么时候可以获得鱼缸","camping 101: fishing 要求"}},{q="为什么冒险者在露营时需要一个鱼缸？",a="在艾泽拉斯的旅途中，生活是严峻而疲惫的。一点点家庭生活的点缀和宁静的爱好，比如在篝火旁看着鱼缸里的鱼，能提供难得的快乐火花，提振冒险者的精神。",al={"为什么露营要带鱼缸","营地鱼缸背景"}}},fp="20,285,19.401.0,16.384.0,25.420.0,42.228.0,33.196.0,45.194.0,39.211.0,59.214.0,55.218.0"}
P.entries["quest:97934"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking 指导有抱负的制皮师前往莫高雷的血蹄村，学习制作便携式露营帐篷的艺术。通过在 Chaw Stronghide 的指导下掌握这项基本工艺，旅行者可以在旅途中建立起提供保护的荒野避难所，保持休息和韧性。它强调了在边境地区自力更生、荒野生存和户外准备的重要性。",h="Camping 101: Leatherworking 指导有抱负的制皮师前往莫高雷的血蹄村，学习制作便携式露营帐篷的艺术。通过在 Chaw Stronghide...",kw={"血蹄村","营火","camping 101","chaw stronghide","制皮","莫高雷","避难所","帐篷"},ang={["faction:Horde"]="穿越卡利姆多广阔干旱地形的部落旅行者，必须依靠坚固的露营装备，才能在远离防御堡垒的地方生存。",["profession:Cooking"]="烹饪训练师传授建造合适营火的艺术，这对于将简单的皮革帐篷变成功能齐全、温暖的营地至关重要。",["race:Tauren"]="制作便携式皮革避难所，与莫高雷平原上牛头人部落的游牧传统和荒野生存遗产自然地契合。"},sec={{t="广阔平原上的避难所",b="对于在卡利姆多广袤荒野中穿行的制皮师来说，知道如何缝制坚固的帐篷与鞣制皮革同样重要。制作精良的帐篷能保护疲惫的旅行者免受正午烈日的炙烤，也能抵挡无情的草原骤雨。它不仅仅是简单的帆布和皮革，更提供了一个安静的庇护所，让冒险者可以在面对广阔平原上的下一次考验之前，得到充分的休息并恢复体力。"},{t="Chaw Stronghide 的手艺",b="在莫高雷金色的草丛中，坐落着宁静的牛头人定居点血蹄村，Chaw Stronghide 在这里传授荒野生存的实用秘诀。Chaw 会观察制皮师是否已经具备了处理更厚重的皮革和进行粗犷缝合的必要技能。一旦工匠证明了自己的熟练程度，他就会教导他们如何建造一种耐用的露营帐篷，这种帐篷专为在远离文明的漫长旅途中抵御恶劣天气而设计。"},{t="荒野营地",b="搭帐篷需要良好的判断力，并尊重当地的定居点。村民们不喜欢旅行者在他们的中心道路和交通要道上随意搭建个人营地，这意味着制皮师必须前往荒野边境，才能扎下他们的避难所。此外，没有噼啪作响的炉火带来的温暖和保护，荒野营地就不算真正完整，这促使漫游者去咨询熟练的厨师，学习如何生起一堆像样的营火。"}},faq={{q="这个任务教给制皮师什么？",a="这个任务指导制皮师学习如何为旅行建造个人露营帐篷。坚固的帐篷能提供对抗恶劣天气的关键保护，在酷热下让旅行者保持凉爽，在倾盆大雨中保持干爽，同时确保他们在荒野中得到充分的休息。",al={"制皮帐篷任务","camping 101 教什么","制皮露营物品"}},{q="谁教制皮师制作露营帐篷？",a="位于莫高雷血蹄村的 Chaw Stronghide 指导制皮师制作露营避难所。一旦制皮师展示出足够的工艺熟练度，他就会同意分享他的帐篷制作知识，传授适用于在荒野中进行长途探险的传统生存技巧。",al={"谁教帐篷制作","chaw stronghide 帐篷","制皮帐篷训练师"}},{q="旅行者可以在哪里搭设露营帐篷？",a="露营帐篷必须搭在开阔的荒野中，而不是人口稠密的定居点内。城镇居民和村长不喜欢旅行者在城镇广场或繁忙的道路中间搭设私人避难所，所以漫游者必须冒险进入野外乡村来测试他们的新装备。",al={"我可以在哪里搭帐篷","我可以在城里露营吗","帐篷放置"}},{q="为什么帐篷旁边需要营火？",a="一个像样的荒野营地，如果没有噼啪作响的营火来提供光亮、温暖和食物，就不算完整。虽然制皮师可以制作遮蔽用的帐篷，但生火需要基本的生存烹饪技巧。建议旅行者在进入荒野之前，先拜访当地的厨师，学习如何建造和维护营火。",al={"为什么需要营火","烹饪 营火 帐篷","帐篷和火"}},{q="血蹄村位于哪里？",a="血蹄村是一个重要的牛头人定居点，位于莫高雷中部，雷霆崖以南，石牛湖岸边。它是当地猎人、采集者和工匠的重要社区中心，为探索周边平原的旅行者提供训练、贸易物资和指导。",al={"血蹄村在哪里","血蹄村位置","如何找到 chaw stronghide"}},{q="维持一个像样的营地需要烹饪技能吗？",a="虽然缝制皮革帐篷并不严格要求烹饪技能，但强烈建议任何露营者学习烹饪艺术。厨师会教旅行者如何点燃基本的营火，这对完成户外营地、温暖夜间空气以及在无人居住的土地上进行长途旅行时准备食物至关重要。",al={"露营需要烹饪吗","我需要烹饪吗","营火烹饪基础"}},{q="露营帐篷为旅行者提供什么好处？",a="露营帐篷提供了可靠的避难所，可以抵御边境地区严酷的天气，保护漫游者免受晴天烈日的炙烤，并在倾盆大雨中保持干爽。在制作精良的帐篷内休息，可以确保冒险者在探索遥远领土时保持精神饱满、警觉，并随时准备面对危险。",al={"露营帐篷的好处","为什么要制作帐篷","帐篷有什么用"}}},fp="27,418,28.445.0,28.472.0,17.472.0,42.292.0,51.329.0,44.310.0,42.342.0,35.321.0,56.330.0,53.324.0"}
P.entries["quest:97935"] = {n="Camping 101: Mining",s="《Camping 101: Mining》向矿工介绍了如何通过自身专业进行野外生存。通过寻找雷霆崖的Brek Stonehoof，矿工可以学会制作一种特殊的磁石，从而增强在营火旁休息的冒险者的战斗力。",h="《Camping 101: Mining》向矿工介绍了如何通过自身专业进行野外生存。通过寻找雷霆崖的Brek Stonehoof，矿工可以学会制作一种特殊的磁石，从而增强在营火旁休息的冒险者的战斗力。",kw={"brek stonehoof","营地","营火","camping 101: mining","磁石","采矿","雷霆崖"},ang={["faction:Horde"]="在矿工营火旁休息的部落远征队员会从准备好的磁石中获益，从而为即将到来的战斗增强他们的前线战斗人员。",["profession:Mining"]="矿工通过为远征营地准备磁石，学习如何将他们的采集工艺直接应用于野外生存。",["race:Tauren"]="这项指导会将矿工带到位于雷霆崖台地顶部的Brek Stonehoof处，利用牛头人对石料和土木工艺的知识。"},sec={{t="大地上的诚实劳动",b="采矿或许缺乏高等奥术那样的华丽与优雅，但它依然是整个艾泽拉斯最基础、最诚实的劳动。从业者从深层的岩壁中开采出有用的矿物和致密的石料，为武器、护甲以及如今的实用野外工艺提供了必要的材料。通过露营工艺，矿工可以将开采出的石料塑造成坚固的增强道具，供他们在野外驻留时使用。"},{t="雷霆崖的磁石",b="对于那些寻求将自身专业转向生存之道的勘探者，雷霆崖的Brek Stonehoof提供了专门的指导。一旦矿工展示出对矿镐的熟练运用，Brek就会传授如何塑形营地磁石的工艺。将这种石头放置在燃烧的篝火旁，它能为任何准备在战斗中挥舞利刃的人提供战斗活力和关键优势。"}},faq={{q="磁石对营地有什么作用？",a="放置在营地的制作磁石会散发出微妙的武力属性，为聚集在营火旁的战士和冒险者提供额外的战斗力和活力。",al={"磁石营地增益","磁石加成","磁石有什么作用"}},{q="Brek Stonehoof是谁？",a="Brek Stonehoof位于牛头人的主城雷霆崖。他指导经验丰富的矿工如何利用开采出的石料和矿石制作专业的露营工具。",al={"brek stonehoof位置","brek stonehoof在哪里","谁教授采矿露营物品"}},{q="矿工什么时候可以学习制作磁石？",a="矿工必须首先展示出其采矿专业的基础熟练度，Brek Stonehoof才会教授他们构建磁石所需的技术。",al={"什么时候可以学习磁石","磁石采矿技能要求"}},{q="谁能从矿工的磁石中获益最大？",a="任何需要挥舞武器的人都能从磁石的存在中获益，因为当物理战斗者在其身旁休息时，它散发出的影响能提供额外的战斗力量。",al={"谁能从磁石中获益","磁石适合近战吗"}},{q="采矿与建立营地有何关联？",a="除了为熔炼炉和铁匠提供原始金属外，采矿还允许野外旅行者制作诸如磁石之类的坚固石制工具，从而加强野外生存营地的功能。",al={"为什么为了露营而采矿","采矿如何帮助露营"}},{q="《Camping 101: Mining》的目的是什么？",a="《Camping 101: Mining》是一份指导指令，旨在引导有志向的矿工前往雷霆崖，以便他们学习制作适用于野外生存的实地工具。",al={"camping 101: mining概览","什么是camping 101: mining"}}},fp="19,267,25.382.0,30.360.0,42.171.0,22.173.0,48.162.0,43.163.0,49.183.0,43.169.0"}
P.entries["quest:97936"] = {n="Camping 101: Skinning",s="《露营指南：剥皮》指引熟练的剥皮者前往血蹄村，以拓展他们的实际野外生存技能。在Yonn Deepcut的指导下，剥皮者学会了将野兽毛皮制成舒适的营地椅子，用于野外生存。这项训练强调了当深入远离文明安全区的地方旅行时，休息与准备的重要性。",h="《露营指南：剥皮》指引熟练的剥皮者前往血蹄村，以拓展他们的实际野外生存技能。在Yonn...",kw={"血蹄村","营地椅子","营火","露营指南","camping 101: skinning","莫高雷","剥皮","yonn deepcut"},ang={["faction:Horde"]="在莫高雷活动的部落剥皮者可以造访血蹄村，学习如何用他们收集的兽皮制作实用的露营装备。",["profession:Cooking"]="一个像样的营地需要温暖的营火来搭配座位，世界各地的烹饪训练师都可以教冒险者如何生火。",["race:Tauren"]="Yonn Deepcut在莫高雷中心地带教导剥皮者如何用兽皮制作舒适的椅子，以便在野外休息。"},sec={{t="荒野之皮",b="采集倒下野兽的兽皮和毛皮是艾泽拉斯最实用的生存技能之一。除了鞣制皮革以制作护甲和装备外，一个足智多谋的剥皮者还能将粗糙的兽皮变成野外舒适用品。对于那些花上数周时间穿越荒野的旅行者来说，学会如何将兽皮加工成休息装备，是避免精疲力竭与在战斗中保持敏锐的关键区别。"},{t="血蹄村的课程",b="在莫高雷，剥皮者会被指引前往血蹄村与Yonn Deepcut交谈。一旦剥皮者展现出采集兽皮的基本功底，Yonn就会传授缝制营地椅子的工艺。城镇和村庄里的居民不欢迎旅行者在街道中央扎营，因此这些椅子是专门为野外使用而设计的，并搭配由当地厨师传授的噼啪作响的营火。"}},faq={{q="什么是《露营指南：剥皮》？",a="《露营指南：剥皮》是一项入门任务，指引熟练的剥皮者在莫高雷寻找专门的导师。在展示了采集兽皮的技能后，剥皮者将学习如何制作营地椅子来布置他们的野外营地。",al={"什么是露营指南剥皮","露营剥皮任务","这个任务有什么用"}},{q="谁传授营地椅子配方？",a="驻扎在莫高雷血蹄村的剥皮训练师Yonn Deepcut，会在冒险者证明了采集兽皮的熟练度后，传授制作营地椅子的技术。",al={"谁教营地椅子","露营剥皮找谁","yonn deepcut在哪里"}},{q="营地椅子有什么用途？",a="营地椅子为在野外扎营时提供了一个舒适的休息场所。花时间坐下来放松有助于冒险者恢复体力，并保持最佳状态以迎接即将到来的战斗。",al={"营地椅子有什么用","营地椅子使用","为什么要制作营地椅子"}},{q="在哪里可以扎营？",a="城镇居民不欢迎旅行者在定居点中间扎营。冒险者必须前往荒野去扎营并测试他们制作的装备。",al={"在哪里可以扎营","可以在镇里扎营吗","城市里的营地椅子"}},{q="扎营还需要什么？",a="没有熊熊燃烧的营火，营地就不完整。冒险者在建立营地之前必须先升起一堆火，这是一项通常由烹饪训练师和厨师传授的基本技能。",al={"扎营还需要什么","需要营火","扎营需要生火吗"}},{q="血蹄村在哪里？",a="血蹄村是位于莫高雷风吹草动的平原上的一个主要牛头人定居点，这里居住着各种各样的商人和工匠，包括剥皮训练师。",al={"血蹄村在哪里","血蹄村位置"}}},fp="21,361,17.406.0,28.429.0,30.248.0,34.189.0,30.204.0,28.180.0,39.180.0,35.149.0"}
P.entries["quest:97938"] = {n="Camping 101: Alchemy",s="Camping 101: Alchemy 是一项引导任务，它将基础的药水制作与野外生存结合了起来。炼金师会被指引前往多兰纳尔寻找辛达·轻语，学习如何为营地搭建一座清凉的法力之井，为旅行中的施法者和治疗者提供关键的魔法补充。",h="Camping 101: Alchemy...",kw={"炼金","营地","camping 101","camping 101: alchemy","辛达·轻语","多兰纳尔","法力之井","泰达希尔"},ang={["faction:Alliance"]="在泰达希尔冒险的联盟炼金师会被直接引导至多兰纳尔，通过魔法营地设施提升他们的野外生存技能。",["race:NightElf"]="在多兰纳尔工作的暗夜精灵草药师和炼金师将自然植物学与野营技艺相结合，以支持野外的施法者。"},sec={{t="炼金师的野外技艺",b="Camping 101: Alchemy 指导炼金师学员将他们的药水制作技巧应用到旅途中。冒险者们不再仅仅是在实验室的玻璃器皿中酿制药剂，而是学会创建野外设施，在漫长的荒野旅途中为旅行小队提供支持。"},{t="多兰纳尔的法力之井",b="该任务指示冒险者在展现出初步的专业能力后，前往多兰纳尔寻找辛达·轻语。她会传授在营地搭建法力之井的技术，这是一种专门为帮助远离城镇和定居点的法力依赖型治疗者和施法者而设计的清凉之泉。"}},faq={{q="什么是 Camping 101: Alchemy？",a="Camping 101: Alchemy 是一项指导任务，引导炼金新手前往多兰纳尔。它教授旅行者如何将药水制作技巧应用于在荒野中建立功能性的营地设施。",al={"什么是 camping 101 alchemy","camping 101 alchemy 任务","炼金营地任务"}},{q="谁教授这项野营技能？",a="辛达·轻语是一位炼金训练师，位于泰达希尔的多兰纳尔。她会指导那些在酿造和制作专业野营物品方面展现出足够能力的从业者。",al={"辛达·轻语是谁","辛达·轻语位置","辛达·轻语在哪里"}},{q="什么是法力之井？",a="法力之井是炼金师为营地制作的一种专业野外设施。它提供了一种清凉的奥术恢复源，能够吸引需要在旅途中补充魔法储备的施法者和治疗者。",al={"法力之井有什么作用","法力之井营地物品","法力之井背景故事"}},{q="这个任务会将你带到哪里？",a="多兰纳尔是位于泰达希尔中部的一个暗夜精灵村庄，是年轻冒险者在离开幽影谷后的重要枢纽和商业技能训练中心。",al={"多兰纳尔在哪里","如何前往多兰纳尔","多兰纳尔位置"}},{q="谁能从炼金师的营地设施中获益？",a="治疗者和旅行中的施法者最能从法力之井中获益，因为这些召唤或酿造的泉水在远离城镇的艰苦旅程中能提供至关重要的恢复与补给。",al={"谁能从法力之井获益","谁使用法力之井","法力之井施法者"}},{q="学习制作法力之井需要什么条件？",a="炼金师必须先证明自己在基础酿造和药水制作方面的熟练度，辛达·轻语才会教授他们组装法力之井之类的野营设施。",al={"我什么时候可以学习法力之井","camping 101 要求","所需的技能熟练度"}}},fp="20,304,26.291.0,25.319.0,29.212.0,31.224.0,20.245.0,31.156.0,51.177.0,54.189.0"}
P.entries["quest:97942"] = {n="Camping 101: First Aid",s="《Camping 101: First Aid》向冒险者介绍了野外生存的基础，教导他们如何为营地制作简易的急救包。本课程由多兰纳尔的Byancie指导，强调了远离城镇诊所时的自给自足与实用分诊能力。",h="《Camping 101: First Aid》向冒险者介绍了野外生存的基础，教导他们如何为营地制作简易的急救包。本课程由多兰纳尔的Byancie指导，强调了远离城镇诊所时的自给自足与实用分诊能力。",kw={"byancie","篝火","露营","多兰纳尔","野外军医","急救","急救包","猎人"},ang={["class:Hunter"]="对于那些需要长时间在外追踪野兽、远离文明社会的猎人来说，将野外生存技能与急救相结合，让他们无需依赖城镇的治疗师即可处理伤势。",["profession:Cooking"]="营地生活既需要食物也需要温暖，因此基础的烹饪训练对于学习如何点燃所需的篝火至关重要。"},sec={{t="野外实地医疗",b="深入荒野意味着时刻面临危险，无论是猛兽的撕咬还是崎岖的地形。对于游侠和野外旅行者而言，他们无法总是等待回到城镇才能获得医疗补给。学习制作专用的急救包可以将简单的路边休息点变成功能性的野外工作站，确保轻微的擦伤在露天环境下不会恶化成致命伤。"},{t="多兰纳尔的课程",b="Byancie位于多兰纳尔绿荫掩映的凉亭中，她指导那些在分诊方面受过训练的旅行者，教他们如何打包适合艰苦野外生活的医疗补给。设置这类装备需要尊重当地定居点；城镇居民不会容忍在城镇中心搭建帐篷和随意堆放补给品，因此露营者必须前往森林深处才能建立营地。"},{t="营地的炉火",b="每个功能完备的营地都始于一团营火。在放下急救包或铺盖之前，冒险者必须先点燃篝火以获取温暖和保护。由于生火与维持火势是野外生存的基础，训练师建议在尝试维持野外营地之前，先向厨师请教并掌握生火的艺术。"}},faq={{q="Byancie是谁？",a="Byancie是位于泰达希尔的多兰纳尔定居点的一名导师。她专门指导那些在医疗技能方面展现出熟练度的冒险者，教他们如何组装用于野外露营的专用急救包。",al={"byancie是谁","byancie的位置","byancie在哪里"}},{q="什么是露营急救包？",a="急救包是由受过医疗训练的冒险者制作的一种专业露营工具。当它被放置在建立好的营地时，它会提供一个专门的工作站，用于在野外治疗伤口并提供必要的医疗救护。",al={"什么是急救包营地","急救包如何运作","露营急救包"}},{q="在哪里可以搭建营地？",a="定居点的居民和卫兵对旅行者在城市广场或定居点中心搭建临时营地的行为表示不满。营地必须建立在远离城镇边界的开阔荒野中。",al={"我可以在城镇里露营吗","为什么要到城镇外露营","露营规则"}},{q="为什么营地需要篝火？",a="篝火是任何野外营地的核心基础，它提供热量、照明和安全保障。冒险者通常从烹饪训练师和厨师那里学习如何点燃基础篝火。",al={"我为什么需要篝火","烹饪篝火营地","篝火需求"}},{q="为什么急救被认为对猎人很有实用价值？",a="猎人经常独自在偏远的荒野中活动，远离已知的治疗师或圣殿骑士。掌握野外分诊和绷带制作技术，可以确保他们在追踪猎物或遭遇伏击时能够自给自足。",al={"为什么猎人需要急救","猎人治疗"}},{q="如何学习制作露营急救包？",a="冒险者必须首先展示出在急救学科方面的基本熟练度，之后多兰纳尔的Byancie便可传授他们组装露营急救包所需的具体技术。",al={"如何获得急救包","学习急救包制作"}}},fp="22,250,27.356.0,19.372.0,22.350.0,15.220.0,32.222.0,28.201.0,38.191.0,50.219.0,50.196.0"}
P.entries["quest:97943"] = {n="Camping 101: Fishing",s="《Camping 101: Fishing》为垂钓者介绍了荒野生活的舒适艺术，教导他们为营地制作装饰性的鱼缸。来到达纳苏斯寻找阿斯塔娅的钓鱼好手们会学到，生活中的一点小乐趣就能鼓舞冒险者的士气，并增强在荒野中的作战能力。",h="《Camping 101: Fishing》为垂钓者介绍了荒野生活的舒适艺术，教导他们为营地制作装饰性的鱼缸。来到达纳苏斯寻找阿斯塔娅的钓鱼好手们会学到，生活中的一点小乐趣就能鼓舞冒险者的士气，并增强在荒野中的作战能力。",kw={"阿斯塔娅","营火","露营","camping 101: fishing","营地","达纳苏斯","鱼缸","钓鱼"},ang={["faction:Alliance"]="阿斯塔娅居住在达纳苏斯，这使得这座暗夜精灵的主城成为了联盟垂钓者扩展营地工艺的主要目的地。",["profession:Cooking"]="营地需要适当的营火才能建立，这使得基础烹饪训练成为垂钓者户外避难所的重要伙伴。"},sec={{t="营地的舒适",b="在卡利姆多旅行的垂钓者经常发现，水边安静的时光能起到更大的作用。在达纳苏斯，技师阿斯塔娅会向经验丰富的钓鱼者展示如何将渔获和技艺转化为营地设施，特别是制作可在营地展示的鱼缸。这件装饰品能为旅途劳顿的旅行者提供舒适和欢乐。"},{t="荒野必需品",b="建立一个像样的荒野避难所需要的不仅仅是钓鱼装备。营地不能设在拥挤的市中心或城区，冒险者需要前往开阔的户外。此外，每个营地的基础都需要一个温暖的营火，因此冒险者在入夜休息前，需要先拜访当地的烹饪训练师，掌握基本的生火技能。"}},faq={{q="谁教你制作钓鱼用的露营物品？",a="阿斯塔娅位于达纳苏斯。一旦垂钓者展现出足够的钓鱼水平，阿斯塔娅就会教他们如何为营地制作装饰性的鱼缸。",al={"谁教授营地钓鱼","阿斯塔娅在哪里","鱼缸训练师"}},{q="鱼缸在营地里有什么用？",a="鱼缸是营地设施，旨在为休息的冒险者带来舒适和快乐。快乐且休息充分的露营者战斗时会更有活力，这对户外探险直接有利。",al={"鱼缸有什么用","营地鱼缸用途","鱼缸营地设施"}},{q="可以在达纳苏斯或其他城市设置营地吗？",a="营地不能搭建在定居点或城镇中心。要搭建营地并放置鱼缸之类的设施，旅行者必须前往荒野。",al={"可以在达纳苏斯露营吗","在哪里搭建营地","在城市中露营"}},{q="在搭建营地之前需要什么？",a="没有基础营火的营地是不完整的。建议旅行者在建立荒野营地之前，先寻找烹饪训练师学习如何生火。",al={"露营需要什么","如何开始露营","需要营火"}},{q="需要钓鱼技能才能学习制作鱼缸吗？",a="要从阿斯塔娅那里学习这项工艺，冒险者必须首先展现出垂钓专业的熟练度。",al={"露营钓鱼技能","什么时候可以学习鱼缸"}},{q="为什么冒险者要在荒野中搭建营地？",a="搭建营地为户外旅行者提供了休息之所和提振士气的设施，例如制作的鱼缸，确保冒险者在荒野探险期间保持充足的休息和能力。",al={"为什么要露营","露营的好处"}}},fp="20,296,23.391.0,22.390.0,55.172.0,44.193.0,55.165.0,42.174.0,60.107.0,44.191.0"}
P.entries["quest:97944"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism向采集者介绍了该专业在野外生存方面的实用应用。通过拜访多兰纳尔的Malorne Bladeleaf，熟练的草药师可以学会制作舒缓的熏香蜡烛，从而为营火旁的治疗者和施法者提供辅助。",h="Camping 101: Herbalism向采集者介绍了该专业在野外生存方面的实用应用。通过拜访多兰纳尔的Malorne...",kw={"露营","camping 101: herbalism","多兰纳尔","草药学","熏香蜡烛","malorne bladeleaf","泰达希尔"},ang={["faction:Alliance"]="在泰达希尔周围活动的联盟草药师会被指引前往多兰纳尔，向当地的暗夜精灵从业者学习专业的野外制作技术。",["profession:Herbalism"]="草药师们发现，采集植物不仅仅是为了炼金，还可以用于实际的荒野生存，提供原始的植物原料来制作像熏香蜡烛这样的营地用品。",["race:NightElf"]="暗夜精灵早已了解自然草药的氛围和恢复特性，并在多兰纳尔这样的定居点分享这些传统。"},sec={{t="不仅仅是采花",b="草药学远不止是在草地上漫步采摘花朵。虽然采集者通常会出售他们的发现或供应给炼金术师，但经验丰富的荒野旅行者知道，野生植物可以直接制作成有价值的营地装备。学习如何将收获的植物用于生存目的，可以确保采集的产出直接支持在野外的长途跋涉。"},{t="多兰纳尔的舒缓之火",b="在多兰纳尔定居点，一位名叫Malorne Bladeleaf的导师会教导精通草药学的玩家如何制作熏香蜡烛。这些芳香的蜡烛可以在营火周围营造一个专注、精神振奋的避风港，为治疗者和施法者在危险间隙恢复魔法能量时提供一种令人恢复活力的氛围。"}},faq={{q="这个任务的目的是什么？",a="Camping 101: Herbalism是一项入门级的专业任务，旨在指导熟练的采集者学习专业的荒野工艺。它引导草药师学习如何利用他们在野外采集的植物来制作营地用品。",al={"什么是camping 101 herbalism","草药学营地任务"}},{q="熏香蜡烛对营地有什么作用？",a="熏香蜡烛可以在营地提供一种令人振奋的氛围，振奋精神并提供一种舒缓的增益，施法者和治疗者在维持魔法专注时非常依赖这种增益。",al={"熏香蜡烛的作用","熏香蜡烛的好处"}},{q="谁是Malorne Bladeleaf？",a="Malorne Bladeleaf是一位居住在多兰纳尔的导师，他拥有制作草药师营地补给品的知识，专门指导精通采集的玩家制作熏香蜡烛。",al={"谁教授熏香蜡烛制作","谁是malorne bladeleaf","多兰纳尔的bladeleaf"}},{q="这个任务会把你带到哪里？",a="多兰纳尔是位于泰达希尔岛上的一个暗夜精灵定居点，是旅行者、训练师和林地工匠的区域中心。",al={"多兰纳尔在哪里","多兰纳尔位置"}},{q="为什么熏香蜡烛对魔法使用者有用？",a="治疗者和施法者最能直接受益于熏香蜡烛所营造的宁静、专注的环境，这有助于他们在荒野探险期间补充精力和恢复魔法意志。",al={"谁能从熏香蜡烛中受益","熏香蜡烛是给施法者用的吗"}},{q="Malorne Bladeleaf教你之前有什么要求？",a="采集者必须在草药学方面表现出足够的实际技能和熟练度，Malorne Bladeleaf才会愿意分享制作营地用品的工艺。",al={"什么时候可以学习熏香蜡烛","营地任务的草药学技能要求"}}},fp="22,259,25.388.0,30.344.0,34.233.0,42.187.0,25.197.0,31.146.0,46.198.0,57.167.0"}
P.entries["quest:97946"] = {n="Camping 101: Leatherworking",s="《露营基础：制皮》向泰达希尔的熟练工匠们介绍了户外生存帐篷的制作技艺。通过寻找在多兰纳尔和达纳苏斯之间道路上的纳迪亚·织鬃（Nadyia Maneweaver），制皮师们可以学会制作耐用的帐篷，保护旅行者免受荒野旅途中的恶劣天气侵袭。",h="《露营基础：制皮》向泰达希尔的熟练工匠们介绍了户外生存帐篷的制作技艺。通过寻找在多兰纳尔和达纳苏斯之间道路上的纳迪亚·织鬃（Nadyia...",kw={"营火","露营","达纳苏斯","多兰纳尔","制皮","纳迪亚·织鬃","帐篷","荒野"},ang={["class:Rogue"]="在荒野中穿行的潜行者依靠良好的休息和庇护所来保持敏锐，这使得个人皮革帐篷成为不可或缺的生存工具。",["profession:Cooking"]="建立一个合格的营地需要温暖的营火，这是通过各地的烹饪训练师传授的一项基本技能。"},sec={{t="荒野中的庇护所",b="对于在卡利姆多的荒野中跋涉的冒险者来说，露宿野外意味着要应对突如其来的暴雨或烈日灼烤等严酷挑战。熟练的制皮师被传授如何利用兽皮和毛皮制作耐用的庇护所，让旅行者无论走到哪里都能建立一个可靠的栖身之所。通过制作个人露营帐篷，游荡者可以确保获得必要的休息，在远离城镇旅店安全区的地方，依然能保持敏锐的反应和清晰的头脑。"},{t="多兰纳尔之路",b="在蜿蜒于多兰纳尔定居点与达纳苏斯枝干之间的林间道路上，纳迪亚·织鬃（Nadyia Maneweaver）为高阶制皮师提供指导。她传授缝制适合野外生活、坚固耐用帐篷的技艺。然而，仅有一个帐篷并不能构成一个功能齐备的营地；旅行者还必须知道如何点燃营火——这是一项由厨师传授的基础生存技能，并且必须记住在广阔的荒野中搭建帐篷，而不是在城镇街道上造成阻碍。"}},faq={{q="谁传授这项露营技能？",a="该任务指引渴望进阶的制皮师前往泰达希尔，在从多兰纳尔通往达纳苏斯的路上与纳迪亚·织鬃（Nadyia Maneweaver）交谈。",al={"谁给予露营基础制皮任务","谁传授露营基础","纳迪亚·织鬃"}},{q="制皮师能从这个任务中学到什么？",a="它指导制皮师如何制作他们自己的露营帐篷，旨在让旅行者在野外炎热的白天保持凉爽，并在雨天保持干爽。",al={"露营基础传授什么","帐篷配方","我能从露营基础中学到什么"}},{q="在哪里可以搭建露营帐篷？",a="帐篷不能在定居点或城市中心内搭建，因为镇民不喜欢在镇中心看到营地。旅行者必须前往城镇之外的广阔荒野中设置他们的营地。",al={"我在哪里可以搭建帐篷","我能在镇里搭建帐篷吗","城市里露营"}},{q="设置营地还需要什么？",a="每个合格的营地在建立之前，除了帐篷外还需要一堆点燃的营火。基础营火的制作通常可以向烹饪训练师学习。",al={"建立营地需要什么","营火需求","搭建帐篷需要营火吗"}},{q="为什么帐篷对旅行者有用？",a="可靠的帐篷能提供避风港，确保冒险者获得充足的休息，从而在远离旅店的旅途中保持警觉和敏锐。",al={"为什么要建造帐篷","帐篷休息增益","为什么要露营"}},{q="纳迪亚·织鬃（Nadyia Maneweaver）在哪里？",a="纳迪亚·织鬃（Nadyia Maneweaver）位于从多兰纳尔村通往暗夜精灵主城达纳苏斯的主干道上。",al={"纳迪亚·织鬃在哪里","纳迪亚位置","通往达纳苏斯之路的训练师"}}},fp="27,320,25.499.0,22.491.0,31.156.0,45.173.0,32.201.0,39.160.0,42.153.0,35.140.0"}
P.entries["quest:97948"] = {n="Camping 101: Mining",s="“Camping 101: Mining”是一项入门任务，指引矿工前往奥伯丁寻找库德拉姆·石锤。通过展示他们的专业技能，矿工们可以学习制作营地磁石，从而增强在篝火旁休息的盟友的战斗能力。",h="“Camping 101: Mining”是一项入门任务，指引矿工前往奥伯丁寻找库德拉姆·石锤。通过展示他们的专业技能，矿工们可以学习制作营地磁石，从而增强在篝火旁休息的盟友的战斗能力。",kw={"奥伯丁","野营工艺","篝火","camping 101: mining","黑海岸","库德拉姆·石锤","磁石","采矿"},ang={["faction:Alliance"]="库德拉姆·石锤在黑海岸的奥伯丁海岸边提供指导，这使得经过卡利姆多北部的联盟旅行者可以轻松获得这项野营工艺。",["profession:Mining"]="矿工可以利用矿物工艺来帮助路上的旅行者，将粗糙的石头变成实用的营地磁石，从而增强前线战士的能力。"},sec={{t="土石的实用艺术",b="采矿是一项艰苦而诚实的劳动，但它的用途远不止于冶炼矿锭和锻造护甲。经验丰富的勘探者可以将原始矿石和磁性矿石塑造成专门的野营装备，让旅行者能够在荒野中建立坚固的营地。“Camping 101: Mining”向矿工介绍了这项技艺的实际应用。"},{t="奥伯丁的导师",b="该任务指引有前途的矿工前往黑海岸熙熙攘攘的沿海避风港——奥伯丁，寻找库德拉姆·石锤。一旦矿工证明了自己的奉献精神和技能，库德拉姆就会传授制作营地磁石的方法。将磁石放置在火堆旁，它会散发出一种强化的气息，提升附近聚集的近战同伴的战斗力。"}},faq={{q="什么是“Camping 101: Mining”？",a="“Camping 101: Mining”指引矿工前往港口城镇奥伯丁寻找库德拉姆·石锤。一旦你展现出了采矿方面的专业能力，他就会教你如何制作一种特殊的磁石来增强营地效果。",al={"这个任务是什么","camping 101: mining 目标","camping 101: mining 我该做什么"}},{q="库德拉姆·石锤是谁？",a="库德拉姆·石锤是一位位于黑海岸沿岸奥伯丁的专家工匠。他会指导合格的矿工如何制作营地辅助物品，特别是磁石。",al={"库德拉姆·石锤是谁","奥伯丁采矿训练师","库德拉姆·石锤位置"}},{q="什么是营地磁石？",a="磁石是由矿工为营地制作的物品。当竖立在篝火旁时，它能提供一种令人振奋的气息，使物理战斗者获得额外的力量和战斗能力。",al={"磁石有什么用","营地磁石效果","野营加成增益"}},{q="这个任务发生在哪里？",a="奥伯丁是黑海岸的一个沿海港口定居点，也是卡利姆多北部联盟的主要港口和交通枢纽。库德拉姆·石锤居住在那里，指导有抱负的矿工学习野营工艺。",al={"奥伯丁在哪里","奥伯丁位置","如何前往奥伯丁"}},{q="谁能从营地磁石中受益？",a="磁石特别受到那些在近距离挥舞刀剑和武器的近战战士的青睐，因为当他们在火堆旁休息时，其共鸣力量能为战斗型旅行者提供增强的活力。",al={"谁能从磁石中受益","磁石对战士有用吗","营地磁石增益目标"}},{q="什么时候可以学习制作磁石？",a="你必须在采矿行业表现出足够的专业能力，库德拉姆·石锤才会与你分享制作营地磁石的秘密。",al={"什么时候可以学习磁石","制作营地磁石的采矿等级","专业技能要求"}}},fp="19,259,36.352.0,21.368.0,28.217.0,27.188.0,25.183.0,33.202.0,35.211.0,42.145.0"}
P.entries["quest:97949"] = {n="Camping 101: Skinning",s="《Camping 101: Skinning》指导野外旅行者如何制作他们自己的便携式营地椅子。它强调了户外生存的基础知识，提醒冒险者们，一个合适的营地需要远离城镇，并生起一堆营火。",h="《Camping 101: Skinning》指导野外旅行者如何制作他们自己的便携式营地椅子。它强调了户外生存的基础知识，提醒冒险者们，一个合适的营地需要远离城镇，并生起一堆营火。",kw={"营地椅子","营火","camping 101","camping 101: skinning","烹饪","剥皮","荒野"},ang={["profession:Cooking"]="建议露营者向烹饪训练师学习基本的烹饪，因为知道如何生火对于在荒野中建立一个合适的营地至关重要。"},sec={{t="旅途的舒适",b="《Camping 101: Skinning》向户外爱好者和剥皮者介绍了荒野生存的技艺。通过将采集到的毛皮和材料投入实际用途，旅行者们可以学会为他们的旅途制作一把便携式的营地椅子。冒险者们不应在繁忙的城市中心造成拥堵——当地人会反对搭建营地——而应该将他们的技艺带到艾泽拉斯广阔的荒野中去。"},{t="必不可少的营火",b="在荒野中，如果没有一堆温暖的营火，任何营地都无法正常运作。建立营地首先需要生火，以提供热量并抵御风雨。尚未掌握基本烹饪技能的新手生存者，建议去拜访一位烹饪训练师，他们可以教导如何在野外任何地方生火的基本技艺。"}},faq={{q="从《Camping 101: Skinning》中你能学到什么？",a="完成这项任务将教你如何制作自己的营地椅子，这是在荒野中休息时必不可少的舒适装备。",al={"我能得到什么","camping 101奖励什么","制作营地椅子"}},{q="可以在城镇里建立营地吗？",a="城镇居民通常不欢迎旅行者在城镇广场或城市街道上扎营。你需要前往荒野才能正确地搭建你的营地。",al={"可以在城里扎营吗","在暴风城搭帐篷","在城市内扎营"}},{q="建立营地需要营火吗？",a="一个合适的营地在建立之前需要先点燃营火。基本的生火技巧可以从艾泽拉斯各地的烹饪训练师那里学到。",al={"扎营需要火吗","如何制作营火","营地椅子的火"}},{q="在哪里可以学会如何生火？",a="大多数烹饪导师和烹饪训练师都能教你基本的食物烹饪方法，其中就包括如何用简单的火石和木材生起一堆营火。",al={"谁教导营火","烹饪营火训练师","哪里学习烹饪营火"}},{q="为什么必须前往荒野扎营？",a="荒野提供了足够的空地，可以在不打扰城镇居民或阻塞当地道路和定居点的情况下扎营。",al={"为什么需要荒野","我在哪里可以使用营地椅子","在哪里扎营"}},{q="剥皮与制作营地椅子有什么关系？",a="剥皮者使用从野兽身上获取的皮革和毛皮，这些材料非常适合拉伸和缝制成营地椅子这样便携的户外座椅。",al={"剥皮与露营的关系","为什么椅子需要剥皮","剥皮营地椅子"}}},fp="21,255,21.388.0,22.368.0,45.124.0,30.160.0,36.164.0,43.163.0,53.137.0,48.158.0"}
P.entries["quest:97955"] = {n="Camping 101: First Aid",s="《露营基础：急救》指引有医学背景的冒险者前往布瑞尔寻找护士妮拉。通过学习制作适合营地的急救包，旅行者可以在荒野深处生存时提供救命的治疗和休养。",h="《露营基础：急救》指引有医学背景的冒险者前往布瑞尔寻找护士妮拉。通过学习制作适合营地的急救包，旅行者可以在荒野深处生存时提供救命的治疗和休养。",kw={"布瑞尔","营火","露营","露营基础","急救","急救包","护士妮拉","提瑞斯法林地"},ang={["faction:Horde"]="护士妮拉在提瑞斯法林地的被遗忘者定居点布瑞尔开展工作，这使得该指导成为部落冒险者的一项重要本地资源。",["profession:Cooking"]="烹饪导师教授点燃基础营火的艺术，这是在添加医疗设施之前建立任何荒野营地的必要条件。",["race:Undead"]="护士妮拉常驻布瑞尔，帮助被遗忘者及其盟友调整医疗技能，以适应洛丹伦废墟景观中的生存需求。"},sec={{t="野外医疗",b="冒险进入防御城镇之外的地区总是伴随着持续的身体危险，从敌对野兽到敌对阵营皆是如此。对于急救专业的旅行者来说，学习组装专用的急救包可以让普通的荒野休息站变成移动的野战医院，在远离文明基础设施的地方包扎伤口并恢复生命力。"},{t="布瑞尔的指导",b="在被遗忘者城镇布瑞尔，护士妮拉提供如何将基础医学知识转化为实用营地装备的指导。一旦旅行者表现出足够的绷带和治疗技巧，她就会传授制作便携式急救包所需的技能。设置此类装备需要一个以基础营火为中心的合适的荒野营地，标准的烹饪导师可以教导旅行者建造营火。"}},faq={{q="护士妮拉是谁？",a="护士妮拉是一位位于提瑞斯法林地被遗忘者定居点布瑞尔的医疗从业者。她指导熟练的急救专业人士如何制作专为野外营地设计的急救包。",al={"护士妮拉是谁","护士妮拉在哪里","护士妮拉位置"}},{q="急救包在营地有什么作用？",a="急救包是由急救专业人士制作的专业露营配件。当在荒野营地设置时，它提供基本的治疗资源，用于处理冒险时受到的伤害。",al={"什么是急救包","急救包用途","营地急救包"}},{q="为什么设置营地需要营火？",a="营火是任何荒野营地的基础，在设置医疗包等额外设施之前必须先有营火。基础营火的建造通常由烹饪训练师和厨师教授。",al={"为什么需要营火","如何制作营火","烹饪营火营地"}},{q="可以在城镇内扎营吗？",a="城镇居民和当地政府通常反对旅行者在城镇街道中间搭帐篷和生火。营地必须建立在开阔的荒野中。",al={"可以在城镇里露营吗","在布瑞尔露营","为什么要在大荒野露营"}},{q="谁教授如何制作急救包？",a="布瑞尔的护士妮拉在符合条件的冒险者表现出足够的急救专业熟练度后，会教授他们如何制作该急救包。",al={"谁教授露营急救","露营急救训练师","急救包训练师"}},{q="《露营基础：急救》的目标是什么？",a="《露营基础：急救》是一项入门任务，指引有志于医疗的冒险者前往布瑞尔寻找护士妮拉。它教授冒险者如何将他们的野外医学技能应用于为户外营地制造医疗用品。",al={"什么是露营基础急救","露营基础任务"}}},fp="22,261,21.354.0,20.426.0,19.208.0,39.214.0,42.204.0,36.189.0,42.142.0,43.217.0"}
P.entries["quest:97957"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism 指引初出茅庐的草药师前往艾泽拉斯各地的专业训练师处（例如布瑞尔的 Faruza），以掌握熏香蜡烛的制作工艺。这些芬芳的产物能为在野外营地休息的施法者提供关键的恢复帮助。",h="Camping 101: Herbalism 指引初出茅庐的草药师前往艾泽拉斯各地的专业训练师处（例如布瑞尔的 Faruza），以掌握熏香蜡烛的制作工艺。这些芬芳的产物能为在野外营地休息的施法者提供关键的恢复帮助。",kw={"布瑞尔","露营","eleanor shackleton","faruza","草药学","熏香蜡烛","提瑞斯法"},ang={["class:Mage"]="施法者非常重视能制作熏香蜡烛的草药师，因为在远离酒馆舒适环境的地方，这种舒缓的烟雾能帮助他们恢复注意力和精神。",["profession:Herbalism"]="草药师不仅可以酿造药水或出售茎叶，还能通过为营火制作芬芳的熏香蜡烛，直接支援冒险队伍。",["race:Undead"]="从丧钟镇和布瑞尔出发的被遗忘者旅行者会向 Faruza 学习如何利用提瑞斯法枯萎的植被制作实用的野外手工艺品。"},sec={{t="营地植物",b="虽然草药学通常被视为炼金术的基础，但实际的野外生存同样依赖于采集到的根茎和花朵。经验丰富的旅行者会指引有抱负的采集者前往地区的草药学大师处，学习如何制作熏香蜡烛。在提瑞斯法林地，Eleanor Shackleton 会指引有潜力的采集者，在证明自己具备基本技能后，前往布瑞尔拜访 Faruza。"},{t="精神食粮",b="旅途生活会对施法者和通灵师的精神造成巨大负担。熏香蜡烛散发的芬芳旨在振奋精神、舒缓疲惫的心智。通过将干燥的植物融入蜡烛，采集者能为在长途旅行中魔法储备衰竭的治疗者和法师提供至关重要的帮助。"}},faq={{q="这个任务的目的是什么？",a="该任务指引草药师达到一定的熟练度，以便他们能从草药学训练师那里学习如何制作熏香蜡烛。这些蜡烛用于在野外休息时维持和协助施法者。",al={"为什么进行露营草药学","camping 101 提供什么","camping 101 草药学目标"}},{q="谁在提瑞斯法林地提供这个任务？",a="Eleanor Shackleton 在提瑞斯法林地为草药师提供指导，并指引他们前往附近的布瑞尔定居点寻找 Faruza。",al={"谁提供提瑞斯法 camping 101 草药学","eleanor shackleton 任务"}},{q="熏香蜡烛有什么作用？",a="熏香蜡烛能为营地提供环境增益，提振精神，并帮助那些需要在野外休息时恢复精神集中的治疗者和施法者。",al={"熏香蜡烛效果","熏香蜡烛的作用"}},{q="谁传授熏香蜡烛配方？",a="当冒险者获得资格后，当地的草药学训练师会进行指导。在提瑞斯法林地，布瑞尔的 Faruza 负责训练；而在其他城市和城镇，则由奥格瑞玛的 Jandi、铁炉堡的 Reyna Stonebranch 以及多兰纳尔的 Malorne Bladeleaf 等训练师负责。",al={"谁教授露营草药学","在哪提交 camping 101 草药学"}},{q="其他阵营和种族的成员可以接受这个任务吗？",a="可以。虽然 Eleanor Shackleton 和 Faruza 服务于提瑞斯法林地的旅行者，但其他任务给予者和训练师也会为卡利姆多和东部王国的草药师提供相同的指导。",al={"camping 101 是部落专属吗","联盟 camping 101 草药学"}},{q="完成训练需要什么技能要求？",a="草药师必须展现出专业技能的真正熟练度，达到二十点的草药学技能后，训练师才会传授蜡烛配方。",al={"需要多少草药学技能","camping 101 技能等级"}}},fp="22,259,18.400.0,23.318.0,34.223.0,41.136.0,31.176.0,38.256.0,56.196.0,58.140.0"}
P.entries["quest:97960"] = {n="Camping 101: Skinning",s="Camping 101: Skinning 是一项为提瑞斯法林地和艾泽拉斯各地的初级采集者提供的荒野生存入门指导。它指引那些已经磨练过自己手艺的剥皮师前往当地的工匠处，学习如何用采集到的皮毛制作一把耐用的营地椅子。",h="Camping 101: Skinning 是一项为提瑞斯法林地和艾泽拉斯各地的初级采集者提供的荒野生存入门指导。它指引那些已经磨练过自己手艺的剥皮师前往当地的工匠处，学习如何用采集到的皮毛制作一把耐用的营地椅子。",kw={"布瑞尔","营地椅子","露营","eleanor shackleton","rand rhobart","剥皮","提瑞斯法林地","幽暗城"},ang={["faction:Horde"]="部落的猎人和采集者会利用被杀野兽的每一块碎料，确保在无情的道路上没有任何浪费。",["race:Undead"]="即使是已经摆脱了凡人疲劳的被遗忘者，在猎杀提瑞斯法遭受瘟疫的野兽时，也发现维持实用的野外营地具有现实意义。"},sec={{t="荒野中的舒适",b="在荒野中生存不仅需要锋利的刀刃，还需要懂得如何在艰难困苦间养精蓄锐。像 Eleanor Shackleton 这样的冒险者强调，采集野兽毛皮所带来的不仅仅是原材料。通过培养基本的野外技能，剥皮师可以用处理过的毛皮制作必需的营地舒适用品，例如椅子，让疲惫的旅人在下一次危险的遭遇前能够好好休息和恢复。"},{t="掌握这门手艺",b="在提瑞斯法林地，年轻的被遗忘者剥皮师在达到初步能力后，会被指引去找 Rand Rhobart，他在连接布瑞尔和幽暗城废墟的道路旁从事他的行当。Rhobart 分享了将粗糙的皮革转化为实用营地座椅的实用技巧，这种艺术在部落和联盟的领地中，都有剥皮大师在效仿。"}},faq={{q="这个任务的目的是什么？",a="该任务指引初级剥皮师寻找一位熟练的行业导师，学习如何使用采集到的动物毛皮组装一把野外营地椅。",al={"camping 101 skinning 有什么作用","为什么要完成 camping 101 skinning","camping 101 奖励"}},{q="在提瑞斯法林地，谁提供这种训练？",a="在提瑞斯法林地，这项任务由 Eleanor Shackleton 发布，旨在引导新的剥皮师前往布瑞尔和幽暗城之间的大道上寻找 Rand Rhobart。",al={"提瑞斯法林地的任务发布者","eleanor shackleton 任务"}},{q="完成此任务需要什么技能等级？",a="你的剥皮技能必须至少达到 20 点，训练师才会认为你经验足够，可以学习如何制作野外营地装备。",al={"我需要多少剥皮等级","camping 101 skinning 要求","需要的剥皮技能"}},{q="Rand Rhobart 在哪里可以找到？",a="Rand Rhobart 驻扎在提瑞斯法林地从布瑞尔向南通往幽暗城入口的主路旁。",al={"rand rhobart 位置","rand rhobart 在哪里","rand rhobart 提瑞斯法"}},{q="其他阵营的成员可以学习这项技术吗？",a="可以。虽然被遗忘者向 Rand Rhobart 学习，但同等的导师也会在闪金镇、铁炉堡、多兰纳尔、奥格瑞玛、血蹄村和申达尔村训练剥皮师。",al={"这是部落专属吗","联盟可以做 camping 101 skinning 吗","联盟剥皮营地椅"}},{q="制作营地椅子有什么用？",a="营地椅子可以在荒野中提供一个舒适的休息处来恢复体力，帮助冒险者保持充沛的精力以应对即将到来的战斗。",al={"营地椅有什么用","为什么要制作营地椅"}}},fp="21,270,20.439.0,19.382.0,34.152.0,44.157.0,51.149.0,32.127.0,51.169.0,36.153.0"}
P.entries["quest:97965"] = {n="Camping 101: First Aid",s="《Camping 101: First Aid》指引旅行者前往申达尔村，学习如何为野外营地制作必要的医疗补给。通过寻找Naleeia Tattermend，技艺精湛的从业者可以制作能够治疗伤口并挽救生命，且远离文明社会的营地急救包。",h="《Camping 101: First Aid》指引旅行者前往申达尔村，学习如何为野外营地制作必要的医疗补给。通过寻找Naleeia...",kw={"绷带","露营","camping 101: first aid","急救","急救包","naleeia tattermend","申达尔村","荒野生存"},sec={{t="荒野中的治疗",b="艾泽拉斯的旅途充满了暴力、野兽和环境危险。对于任何旅行者而言，学习急救既实用又光荣，它能确保在不完全依赖法术的情况下包扎流血的伤口和骨折。在野外营地建立一个专门的急救包可以提供一个可靠的治疗中心，让筋疲力尽的冒险者在继续前进之前能够恢复体力和照料同伴。"},{t="申达尔村的导师",b="并非每一位战地医护人员都知道如何正确组装耐用的野外医疗用品。在申达尔村，一位名叫Naleeia Tattermend的专家指导致力于此的从业者学习制作营地急救包的艺术。那些寻求她指导的人必须首先展示自己在基础医疗护理方面的熟练程度，她才会传授她的技巧。"}},faq={{q="我需要找谁来完成这个任务？",a="你必须在申达尔村寻找Naleeia Tattermend。她拥有为野外营地制作专业医疗装备所需的知识。",al={"寻找谁来学习野外急救","naleeia tattermend在哪里","camping 101: first aid 任务提交"}},{q="申达尔村在哪里？",a="申达尔村是泽风岛上的一个村庄，医护人员Naleeia Tattermend就住在那里。寻求高级野外急救训练的从业者会在磨练好技能后前往那里。",al={"申达尔村在哪里","申达尔村位置","申达尔村急救"}},{q="制作营地急救包的目的是什么？",a="这项训练允许你为冒险者的营地制作量身定做的急救包。在荒野中，在营地随时备有医疗用品能提供旅途间隙至关重要的治疗，这甚至可能意味着生与死的区别。",al={"野外急救有什么用","营地急救包","为什么制作急救包"}},{q="Naleeia Tattermend什么时候会教我制作急救包？",a="Naleeia Tattermend要求你在她同意分享制作方法之前，先展示出足够的急救技能熟练度。你必须在组装野外急救包之前练习基本的包扎和治疗技术。",al={"什么时候可以学习制作急救包","naleeia tattermend 要求","camping 101: first aid 要求"}},{q="为什么急救被认为既光荣又实用？",a="伤口和身体创伤是艾泽拉斯冒险中不可避免的危险。绷带和医疗处理允许各种职业的旅行者处理自己的伤口，并在不完全依赖魔法援助的情况下稳定同伴的伤势。",al={"为什么急救很重要","急救背景知识","急救是否有用"}},{q="任何冒险者都可以制作野营急救包吗？",a="任何致力于学习急救并证明自己能力的冒险者，都可以向申达尔村的Naleeia Tattermend学习如何为他们的营地制作急救包。",al={"任何人都能学习这个急救包吗","谁可以制作营地急救包"}}},fp="22,281,25.455.0,30.355.0,43.150.0,34.199.0,57.243.0,55.223.0,57.242.0,49.177.0"}
P.entries["quest:97967"] = {n="Camping 101: Fishing",s="Camping 101: Fishing 指导有抱负的钓鱼者如何运用他们对钓竿和鱼线的耐心来提升野外探险的体验。通过在申达尔村寻找 Fenn Fairweather，精通钓鱼的玩家可以学习制作装饰性的鱼缸，以增强士气和营地舒适度。",h="Camping 101: Fishing 指导有抱负的钓鱼者如何运用他们对钓竿和鱼线的耐心来提升野外探险的体验。通过在申达尔村寻找 Fenn...",kw={"野营","camping 101: fishing","fenn fairweather","鱼缸","钓鱼","申达尔村"},sec={{t="炉火的慰藉",b="在野外生活不仅仅需要锋利的刀刃和坚固的盔甲；保持高昂的士气往往是决定成功与精疲力竭的关键。虽然钓鱼通常被视为一种安静的消遣或获取食物的手段，但技术娴熟的钓鱼者可以将他们的技艺用于改善营地的舒适度。通过捕获活鱼并准备专门的装置，旅行者可以将荒凉的营地变成温馨的避风港。"},{t="申达尔的工匠",b="在申达尔村，工匠 Fenn Fairweather 会与懂得钓竿和卷轴之耐心的老练钓鱼者分享行业秘密。展现出足够技巧的人可以学习制作鱼缸——一种旨在为疲惫的同伴带来欢乐和放松的简单营地装置。在野外保持高昂的精神有助于小队成员在面对迫在眉睫的危险时保持专注和坚定。"}},faq={{q="谁教授鱼缸野营制作工艺？",a="Fenn Fairweather 居住在申达尔村。一旦你证明了自己在钓鱼技艺上的足够造诣，Fenn 就能教你如何制作鱼缸来布置和点亮你的营地。",al={"谁提供鱼缸","fenn fairweather 在哪里","鱼缸训练师"}},{q="鱼缸在营地中有什么用途？",a="鱼缸是营地的一种装饰性设施，能为你和你的同伴带来一丝舒适和欢乐。维护良好的营地和高昂的精神状态能让冒险者保持敏锐，并增强他们应对野外危险挑战的准备。",al={"鱼缸有什么作用","鱼缸增益","野营鱼缸效果"}},{q="申达尔村在哪里？",a="申达尔村是一个聚集了各行各业的工匠和导师的定居点，其中包括 Fenn Fairweather。钓鱼从业者会前往那里学习适合他们技能的实用野营工艺。",al={"申达尔村在哪里","申达尔村位置"}},{q="学习这种野营工艺需要什么技能？",a="在从事这项工艺之前，你必须首先证明自己作为钓鱼者具备扎实的基本功。一旦你磨练了钓鱼技能，申达尔村的导师就会分享组装像鱼缸这样的营地设施的方法。",al={"野营钓鱼要求","什么时候可以学习鱼缸","如何开始野营钓鱼"}},{q="为什么钓鱼对野外露营很重要？",a="除了单纯地捕获猎物以维持生计外，钓鱼者敏锐的眼光和耐心还能以意想不到的方式为营地生活做出贡献。在制作精美的鱼缸中展示新鲜的渔获，可以在漫长的野外探险中提供宁静的亲切感并提振士气。",al={"为什么野营需要钓鱼","钓鱼在营地的用处"}},{q="Fenn Fairweather 是谁？",a="Fenn Fairweather 是一位位于申达尔村的工匠兼导师。Fenn 深知野外生活的实用舒适性，并与技术娴熟的钓鱼者分享有关营地设施的专业知识。",al={"fenn fairweather 是谁","fenn fairweather 背景故事"}}},fp="20,292,22.452.0,23.416.0,40.199.0,44.251.0,26.221.0,51.241.0,47.256.0,24.206.0"}
P.entries["quest:97968"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism 指导采集者前往导师处，学习制作用于野外营地的熏香蜡烛。利用采摘的植物成分，草药师可以提供芳香的慰藉，在漫长的旅途中提振施法者和治疗者的精神。",h="Camping 101: Herbalism 指导采集者前往导师处，学习制作用于野外营地的熏香蜡烛。利用采摘的植物成分，草药师可以提供芳香的慰藉，在漫长的旅途中提振施法者和治疗者的精神。",kw={"营地","露营","camping 101: herbalism","治疗者","草药学","草药","熏香蜡烛","施法者"},ang={["class:Mage"]="在战斗中耗尽专注力的施法者非常感激那些旨在舒缓心灵并支持奥术恢复的营地熏香蜡烛。",["class:Priest"]="在营地中点燃的熏香蜡烛能提升神圣治疗者在战斗间隙的精神，并补充他们的精神储备。",["profession:Herbalism"]="采集荒野各处的植物提供了制作营地熏香所需的原始芳香草药，使得草药师的搜寻工作在炼金术之外也具有了生存实用性。"},sec={{t="小径上的野生植物",b="对于整日在荒野中跋涉的旅行者来说，采集根茎和花瓣远不止是无谓的搜寻。Camping 101: Herbalism 向熟练的采集者介绍了实用的野外技艺，将他们引荐给懂得如何将野生芳香植物转化为营地专用熏香蜡烛的导师。采集者不仅可以出售新鲜的茎叶或酿造药剂，还可以利用采集到的植物在旅途中为同伴提供支持。"},{t="舒缓心灵",b="在充满敌意的领土上长途跋涉会消耗治疗者和施法者的精力，他们的精神储备和士气在战斗中至关重要。在活跃的营地中点燃一支熏香蜡烛，空气中会弥漫着令人舒缓、恢复活力的香气，使人精神振奋。魔法使用者和治疗者尤其看重这种芳香带来的加成，确保同伴在重返险境之前恢复清醒和力量。"}},faq={{q="什么是 Camping 101: Herbalism？",a="Camping 101: Herbalism 是一项针对已经练习过草药采集的冒险者的任务。它将草药师引荐给专业的工匠，这些工匠能够传授如何为野外营地制作熏香蜡烛。",al={"什么是 camping 101 herbalism","camping 101 herbalism 任务","草药学露营任务"}},{q="熏香蜡烛有什么用途？",a="熏香蜡烛是一种使用草药材料制作的营地配件。在营地中点燃一支可以增强休息中冒险者的士气和精神，特别能为治疗者和施法者提供有益的加成。",al={"熏香蜡烛有什么用","熏香蜡烛营地效果","为什么制作熏香蜡烛"}},{q="谁教授如何制作熏香蜡烛？",a="训练师取决于你的起始地点：铁炉堡的雷娜·石枝、多兰纳尔的马洛恩·叶刃、艾尔文森林的草药师波默罗伊、奥格瑞玛的詹迪、布瑞尔的法鲁扎、雷霆崖的科敏·冬蹄，或是瓦拉纳尔的希瑞尔·夜雨。",al={"谁教授熏香蜡烛","熏香蜡烛训练师","在哪里学习熏香蜡烛"}},{q="为什么熏香蜡烛对魔法使用者特别有用？",a="在战斗中引导魔法和治疗伤口会消耗体力与精神专注。高昂的士气对于让施法者时刻准备战斗至关重要，而熏香蜡烛散发的舒缓烟雾有助于这种恢复。",al={"为什么施法者需要熏香","熏香蜡烛治疗者","熏香蜡烛魔法使用者"}},{q="做这个任务需要成为草药师吗？",a="这项指导直接针对那些拥有植物和草药采集技能的人，因为这些技术涉及识别和利用芳香的野生植物。",al={"任何人都能学习熏香蜡烛吗","做 camping 101 herbalism 需要草药学吗","草药学需求露营蜡烛"}},{q="草药学如何与露营联系起来？",a="除了酿造药剂和药膏之外，采集到的野生植物在营地周围还有实用的芳香用途，例如制作熏香来让疲惫的同伴焕发精神。",al={"草药学只是为了药水吗","草药的露营用途","草药学营地物品"}}},fp="22,291,23.430.0,17.397.0,31.221.0,35.222.0,42.243.0,58.224.0,50.165.0,36.175.0"}
P.entries["quest:97969"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking 指导初出茅庐的制皮师寻求关于制作耐用野外遮蔽物的高级指导。在申达尔村的 Indari Sunseam 的引导下，工匠们学习缝制保护性帐篷，以便在漫长的野外探险中获得必要的休息。",h="Camping 101: Leatherworking 指导初出茅庐的制皮师寻求关于制作耐用野外遮蔽物的高级指导。在申达尔村的 Indari Sunseam...",kw={"露营帐篷","篝火","露营","烹饪","indari sunseam","制皮","申达尔村","帐篷","荒野"},ang={["profession:Cooking"]="仅有一个帐篷并不能构成一个功能齐全的营地；旅行者还必须掌握基本的篝火制作工艺，这通常向烹饪训练师学习。"},sec={{t="旅途中的住所",b="对于旅行的制皮师来说，将兽皮和毛皮加工成耐用的野外装备的能力至关重要。在学会这门手艺后，工匠们会被指引去寻找申达尔村的 Indari Sunseam，学习如何制作合适的露营帐篷。这样的住所能让冒险者在无情的暴雨中保持干爽，在烈日下保持凉爽，确保他们在漫长的旅途中得到充分的休息。"},{t="野外营地",b="搭帐篷需要尊重市民边界，因为城镇居民不喜欢粗陋的营地挤占市政街道。营地必须搭建在野外。此外，坚固的住所只是成功的一半：没有温暖的篝火，任何营地都是不完整的，这促使冒险者在踏入荒野之前去拜访当地的厨师，学习基本的生火技能。"}},faq={{q="谁教导制皮师如何制作帐篷？",a="Indari Sunseam 居住在申达尔村，并指导精通制皮的工匠如何制作他们自己的露营帐篷。",al={"谁教制皮帐篷","露营帐篷训练师","indari sunseam 在哪里"}},{q="制作帐篷的目的是什么？",a="制作精良的帐篷可以保护旅行者免受雨水和烈日等恶劣天气的侵袭，让冒险者获得必要的休息，以在旅途中保持警觉。",al={"帐篷有什么用","帐篷用途","帐篷的好处"}},{q="可以在哪里搭建露营帐篷？",a="帐篷不能搭建在当地人反对的城镇中心。旅行者必须前往开阔的荒野才能扎营。",al={"我可以在城里搭帐篷吗","在哪里使用帐篷","营地规则"}},{q="搭建合适的营地还需要什么？",a="每一个完整的营地除了住所外，还需要一堆熊熊燃烧的篝火。建议冒险者寻找烹饪训练师，学习如何生火。",al={"我需要篝火吗","营地要求","营地还需要什么"}},{q="Indari Sunseam 何时会教你帐篷图纸？",a="你必须练习制皮，并在你的专业技能中展现出足够的熟练度，Indari Sunseam 才会教你制作露营物品。",al={"我什么时候能学帐篷","帐篷要求","制皮帐篷要求"}},{q="什么是申达尔村？",a="申达尔村是 Indari Sunseam 生活和工作的地方，为旅行者提供制作露营用品的专业指导。",al={"申达尔村在哪里","申达尔村位置","indari sunseam 所在的城镇"}}},fp="27,285,19.396.0,20.392.0,47.123.0,39.162.0,36.144.0,43.167.0,52.151.0,25.142.0"}
P.entries["quest:97971"] = {n="Camping 101: Skinning",s="Camping 101: Skinning 指导冒险者如何将收集到的毛皮制作成实用的营地椅子，用于野外露营。在申达尔村的 Mendalass Tattermend 的指引下，剥皮师们学会了将采集技艺与野外生存及篝火休闲相结合。",h="Camping 101: Skinning 指导冒险者如何将收集到的毛皮制作成实用的营地椅子，用于野外露营。在申达尔村的 Mendalass Tattermend...",kw={"营地椅子","篝火","camping 101","毛皮","mendalass tattermend","申达尔村","剥皮","荒野"},ang={["profession:Cooking"]="烹饪与野外生存相辅相成；正如 Mendalass 所指出的，搭建一个合适的营地需要基础的篝火，这通常是由烹饪训练师传授的技能。"},sec={{t="野外舒适度",b="从被击败的野兽身上采集毛皮是艾泽拉斯各地的一项基本生存技能，但它的用途远不止于简单的护甲制作。通过 Camping 101: Skinning，采集者们学会了将他们的专业技能转向野外生存，制作一把便携式的营地椅子。在野外找个舒适的座位休息片刻，能让疲惫的冒险者在下一次战斗前恢复体力，保持巅峰作战状态。"},{t="申达尔村的教导",b="一旦冒险者证明了自己剥皮刀的熟练度，他们就会被派往申达尔村去见 Mendalass Tattermend，以掌握这个配方。Mendalass 会指导旅行者如何用收集到的毛皮组装耐用的座椅。然而，建立一个营地不仅仅需要家具：定居点不会容忍在城镇范围内搭建临时营地，而且没有噼啪作响的篝火，营地就不算真正完成——这项技能通常是向当地烹饪训练师学习的。"}},faq={{q="Camping 101: Skinning 是关于什么的？",a="Camping 101: Skinning 指引熟练的剥皮师前往申达尔村寻找 Mendalass Tattermend。通过完成此项训练，冒险者可以学会如何将收获的毛皮重新利用，制作成一把实用的营地椅子，用于野外休息和恢复。",al={"这是什么任务","camping 101 的目的","为什么要完成这个任务"}},{q="Mendalass Tattermend 是谁？",a="Mendalass Tattermend 是一位位于申达尔村的剥皮训练师。他教导熟练的剥皮师如何将采集到的毛皮缝制成舒适的野外露营座椅。",al={"mendalass 是谁","谁教授营地椅子","mendalass tattermend"}},{q="在哪里可以找到 Mendalass Tattermend？",a="Mendalass Tattermend 居住在申达尔村，冒险者必须前往那里展示他们的技能，并学习制作营地装备的艺术。",al={"mendalass 在哪里","申达尔村在哪里","我在哪里交任务"}},{q="这个任务教你制作什么物品？",a="剥皮师学会了配方，可以使用从被击败的野兽身上采集到的皮和毛皮来制作营地椅子，为在野外时提供一个舒适的休息座位。",al={"剥皮师制作什么","营地椅子配方","我能得到什么物品"}},{q="你可以在城镇内搭建营地吗？",a="城镇居民不赞成在定居点中间搭建营地。营地和营地椅子应该搭建在远离城市中心的荒野中。",al={"我能在城里露营吗","我在哪里可以搭营地","在哪里使用营地椅子"}},{q="搭建一个合适的营地还需要什么？",a="每一个合适的营地在完成前都需要一堆噼啪作响的篝火。尚未掌握生火技能的冒险者建议咨询烹饪训练师来学习基础知识。",al={"搭营地还需要什么","需要篝火","营地要求"}}},fp="21,267,20.446.0,33.502.0,36.232.0,28.185.0,40.147.0,44.170.0,34.158.0,44.189.0"}
P.entries["quest:97973"] = {n="Camping 101: Tailoring",s="《Camping 101: Tailoring》向裁缝们介绍了为野外营地制作专业装备的艺术。通过向Shen'dar Village的Taleen Shimmerthread展示技艺，裁缝们可以学会缝制一面鼓舞人心的阵营旗帜，以提振士气并维持营地状态。",h="《Camping 101: Tailoring》向裁缝们介绍了为野外营地制作专业装备的艺术。通过向Shen'dar Village的Taleen...",kw={"营地旗帜","露营","camping 101: tailoring","阵营旗帜","申达尔村","裁缝","taleen shimmerthread","专业技能"},ang={["profession:Tailoring"]="裁缝们学会制作鼓舞人心的阵营旗帜，这能提升营地士气并为野外的盟友补充活力。"},sec={{t="织布工对营地的贡献",b="《Camping 101: Tailoring》指导布甲工匠将他们的技艺扩展到简单的服装和包袋之外。在荒野中，生存不仅仅需要保暖的衣物；一个合适的营地往往决定了你能坚持多久。我们鼓励裁缝们寻求进阶指导，将布卷转化为团结与坚韧的象征。"},{t="Shen'dar Village的指导",b="该任务引导有抱负的裁缝前往Shen'dar Village，Taleen Shimmerthread将在那里提供露营工艺的指导。那些在裁缝技艺上达到足够熟练度的工匠可以学习制作阵营旗帜的方法。这种旗帜经过精心缝制，骄傲地插在营地中，不仅能作为激励人心的集合点，还能提升士气，让盟友们在接下来的挑战中保持活力。"}},faq={{q="什么是《Camping 101: Tailoring》？",a="《Camping 101: Tailoring》引导有潜力的裁缝去寻求野外工艺的专业指导。一旦你展示了足够的裁缝技艺，就可以学习如何为野外营地制作一面装饰性且鼓舞人心的阵营旗帜。",al={"这是什么任务","camping 101 tailoring任务","裁缝露营旗帜"}},{q="Taleen Shimmerthread是谁？",a="Taleen Shimmerthread是位于Shen'dar Village的一位裁缝专家。她指导技艺娴熟的工匠如何编织露营专用的裁缝物品，包括能提升营地士气的旗帜。",al={"taleen shimmerthread","谁教授裁缝旗帜","taleen shimmerthread在哪里"}},{q="Shen'dar Village在哪里？",a="Shen'dar Village是Taleen Shimmerthread居住的定居点。裁缝们会前往那里，接受关于如何将他们的布艺技艺应用到露营装备上的专业指导。",al={"shendar village在哪里","shendar village位置"}},{q="裁缝可以学习制作什么露营物品？",a="阵营旗帜是裁缝可以制作的一种露营物品。在任何战场或艰苦的远征中，保持灵感和士气至关重要，插上一面旗帜能为在营地休息的人们提供充满活力的氛围。",al={"阵营旗帜露营","裁缝为营地做什么","裁缝营地物品"}},{q="学习露营旗帜有什么要求？",a="你必须在Shen'dar Village向Taleen Shimmerthread展示你在裁缝专业上的熟练度，她才会教你编织阵营旗帜的图纸。",al={"如何学习阵营旗帜","裁缝露营旗帜要求"}},{q="为什么阵营旗帜在营地中很有价值？",a="士气和灵感在任何战役中都至关重要。裁缝们缝制阵营旗帜是为了展示忠诚，并提供一个能激发活力的焦点，支撑冒险者们度过艰苦的旅程。",al={"为什么制作阵营旗帜","露营旗帜士气"}}},fp="22,281,33.349.0,31.405.0,31.244.0,28.199.0,26.178.0,45.216.0,54.169.0,41.196.0"}
P.entries["quest:97977"] = {n="Nature's Call",s="Nature's Call是幽影谷的一个任务，树妖塔琳德拉试图找出当地的止松熊怪为何会突然反目，背弃与暗夜精灵长久以来的盟友关系。通过收集他们废弃营地中的雕刻图腾，冒险者们得以揭示正在泰达希尔蔓延的令人不安的精神腐蚀。",h="Nature's Call是幽影谷的一个任务，树妖塔琳德拉试图找出当地的止松熊怪为何会突然反目，背弃与暗夜精灵长久以来的盟友关系。通过收集他们废弃营地中的雕刻图腾，冒险者们得以揭示正在泰达希尔蔓延的令人不安的精神腐蚀。",kw={"熊怪","止松","小鬼","贪婪小鬼","nature's call","梦魇","幽影谷","塔琳德拉","泰达希尔","图腾"},ang={["class:Druid"]="德鲁伊能感知到自然平衡以及影响卡利姆多生物的精神腐蚀，这使得被梦魇驱动的熊怪图腾腐蚀成为一个令人担忧的动向。",["faction:Alliance"]="保卫泰达希尔的枝干对于保护这个新兴的暗夜精灵国度至关重要，也能确保他们新结识的联盟盟友在卡利姆多站稳脚跟。",["race:NightElf"]="止松熊怪曾是暗夜精灵长期的伙伴，因此他们堕落为敌对和疯狂的状态，对于泰达希尔的守卫者而言是一场极为私人的悲剧。"},sec={{t="调查幽影谷",b="Nature's Call是幽影谷的一个调查任务，由树妖塔琳德拉发布。她无法相信止松熊怪会无缘无故地抛弃与暗夜精灵数百年的友谊，因此请求旅行者们搜寻位于山谷西侧边缘、被熊怪匆忙遗弃的营地，以找回完好的雕刻图腾。"},{t="阴影与梦魇",b="解读找回的图腾揭示了一场悲惨的堕落。止松熊怪一直饱受反复出现的梦魇困扰，梦见某种即将毁灭他们的阴影正在逼近。久而久之，纯粹的恐惧逐渐转化为盲目的愤怒，扭曲了他们的心智，使他们将长久以来的精灵邻居视为他们所恐惧的那种阴影。塔琳德拉希望这些发现能揭示泰达希尔蔓延的不详征兆。"}},faq={{q="谁发布了Nature's Call任务？",a="塔琳德拉是一位在泰达希尔的幽影谷守护的树妖。由于担心当地止松熊怪突然表现出的敌意，她指引冒险者从他们废弃的营地中回收圣物，以调查他们疯狂的根源。",al={"谁发布了nature's call","塔琳德拉是谁","塔琳德拉位置"}},{q="为什么止松熊怪会变得充满敌意？",a="从止松图腾中回收的雕刻显示，熊怪开始遭受可怕的梦魇困扰，梦见一个威胁要毁灭他们的阴影。这种蔓延的恐惧逐渐扭曲成无法控制的偏执和狂怒，导致他们将古老的暗夜精灵盟友视为敌人。",al={"为什么止松熊怪发动攻击","为什么止松熊怪疯狂","止松熊怪发生了什么"}},{q="止松图腾在哪里？",a="较小的图腾可以在位于幽影谷西侧边缘的废弃止松熊怪营地中找到，不过在废墟中搜寻的小鬼和贪婪小鬼已经把其中一些散落到了周围的区域。",al={"止松图腾在哪里","寻找止松图腾","止松营地位置"}},{q="为什么玩家无法收集营地里较大的图腾？",a="塔琳德拉特别建议不要尝试回收营地中发现的较大图腾。作为一名树妖，她表示自己完全不知道该如何处理那种笨重的雕刻，更倾向于使用较小、便于携带的雕刻图腾。",al={"为什么忽略大型图腾","我可以拾取大型图腾吗","大型止松图腾"}},{q="谁是止松熊怪？",a="止松部族是泰达希尔原生的熊怪，曾与暗夜精灵作为和平的盟友共同生活。他们最近转变为具有攻击性的敌对势力，是由蔓延的梦魇引起的一种反常现象，而非源于古老的恶意。",al={"谁是止松熊怪","止松传说","止松熊怪是邪恶的吗"}},{q="图腾中提到的伟大阴影是什么？",a="雕刻中提到了一个困扰着熊怪梦境的未知“伟大阴影”。虽然这种黑暗影响的确切来源尚不清楚，但塔琳德拉希望解读他们的命运将有助于理清泰达希尔所受到的更广泛的腐蚀。",al={"止松阴影是什么","泰达希尔的阴影是什么","泰达希尔的梦魇"}}},fp="13,321,22.354.0,28.424.1,34.247.0,44.280.0,39.225.0,57.252.0,30.248.0,49.245.0"}
P.entries["quest:97979"] = {n="The Goddess Provides",s="“The Goddess Provides”是一项介绍Kaldorei的初始任务，核心在于领会Elune的赐福。该任务设定在“Long Vigil”结束后泰达希尔的枝桠间，教导年轻的暗夜精灵接受月神之母带来的月光指引与隐遁阴影。",h="“The Goddess Provides”是一项介绍Kaldorei的初始任务，核心在于领会Elune的赐福。该任务设定在“Long...",kw={"elune","goddess provides","海加尔山","kaldorei","long vigil","月神之母","影遁","泰达希尔"},ang={["class:Priest"]="Kaldorei中的牧师群体致力于侍奉“Mother Moon”，直接引导Elune的优雅作为指引的光辉与神圣的庇护。",["faction:Alliance"]="在海加尔山的战斗之后，暗夜精灵结束了长期的孤立并加入了联盟，将他们神圣的月亮力量贡献于共同防御。",["race:NightElf"]="作为群星之子，Kaldorei继承了Elune的直接赐福，利用月光揭示未见的道路，并利用隐蔽能力融入阴影之中。"},sec={{t="结束的守望",b="在大分裂后的数千年里，Kaldorei维持着孤独的“Long Vigil”，守护着卡利姆多，并保卫着海加尔山的神圣山巅。第三次战争的浩劫以及对世界之树的关键防御迫使这段古老的与世隔绝走向终结。如今，移居至泰达希尔庇护之下的枝桠间，暗夜精灵们面对着一个陌生的世界，通过与远方海洋彼岸的盟友结盟，踏上了艾泽拉斯更广阔的舞台。"},{t="月神之母的祝福",b="即便是在结盟对象更迭与居所变迁之时，Kaldorei认同感的根基依然植根于对“Mother Moon”Elune的崇拜。暗夜精灵从幼年起就被教导呼唤她的双重形态：指引战斗打击与澄清目标的辉光，以及掩盖自身于敌方视线之外的阴影。呼唤这些与生俱来的天赋，既是精神上的交流，也是为大树之外的危险所做的实践准备。"}},faq={{q="什么是“The Goddess Provides”？",a="“The Goddess Provides”是为栖居在泰达希尔枝桠间的年轻暗夜精灵准备的入门仪式。它指导Kaldorei识别并展示月亮女神Elune赋予他们的天赋赐福。",al={"什么是the goddess provides","the goddess provides任务"}},{q="任务中提到的女神是谁？",a="这位女神是Elune，也被Kaldorei尊称为“Mother Moon”。她是暗夜精灵文化与精神生活的核心神祇，被认为赐予其子民保护、澄明与潜行的月之祝福。",al={"女神是谁","谁是月神之母","暗夜精灵女神"}},{q="Elune赋予了Kaldorei什么天赋？",a="Elune赋予的优雅可以照亮战士的打击以确保命中，同时也赋予了他们融入周围阴影的能力，正如月亮在日食期间遮蔽太阳一般。",al={"elune给予什么天赋","elune种族技能","elune的力量"}},{q="什么是“Long Vigil”？",a="“Long Vigil”是暗夜精灵为守护卡利姆多而维持的数千年的警戒与孤立状态。在对燃烧军团的海加尔山关键防御战之后，这段时期宣告结束，促使Kaldorei最终开放了国界。",al={"什么是long vigil","为什么long vigil结束"}},{q="为什么暗夜精灵加入了联盟？",a="海加尔山的防御战终结了他们孤独的隐居生活，Kaldorei选择与海那边的凡人种族建立联系，加入了大联盟以求共同生存与结伴。",al={"为什么暗夜精灵加入联盟","kaldorei联盟"}},{q="这项指导在何处进行？",a="泰达希尔是位于卡利姆多北海岸外巨大的世界之树。第三次战争后，其高耸且受庇护的枝桠成为了暗夜精灵人民新的家园与圣所。",al={"泰达希尔在哪里","什么是泰达希尔"}}},fp="20,274,17.476.0,24.466.0,29.226.0,44.222.0,46.194.0,24.252.0,45.213.0,39.196.0"}
P.entries["quest:98013"] = {n="Swelling Forces",s="Swelling Forces是一个任务，Arbal指挥古树之林的冒险者去猎杀盘踞在东北方废墟中日益壮大的Stormscale娜迦。这些受到诅咒的前上层精灵与阴险的Twilight's Hammer邪教结盟，威胁着林地。向他们拿起武器对于保护古老森林免遭进一步的破坏至关重要。",h="Swelling Forces是一个任务，Arbal指挥古树之林的冒险者去猎杀盘踞在东北方废墟中日益壮大的Stormscale娜迦。这些受到诅咒的前上层精灵与阴险的Twilight's...",kw={"arbal","古树之林","上层精灵","侍从","娜迦","女巫","stormscale","swelling forces","twilight's hammer"},ang={["faction:Alliance"]="保卫黑海岸和古树之林周围神圣森林的联盟军队，必须应对娜迦和Twilight's Hammer之间协同作战的前线。",["race:NightElf"]="在这些废墟中游荡的娜迦曾经是暗夜精灵的上层精灵同族。看到他们与黑暗邪教徒一起回来亵渎和掠夺古老的森林，这真是一种痛苦的背叛。"},sec={{t="沉没之城的毒蛇",b="在古树之林，Arbal带着深切的担忧注视着东北方的废墟。受到诅咒的上层精灵，已经变成了Stormscale部族的蛇形娜迦，占据了他们曾经辉煌文明的残骸。沉没的石块不再安静地承载着回忆，而是回荡着侵略大军滑行的脚步声。Arbal委派保卫者前往废墟，在他们的力量扩散到更广阔的森林之前，削减其不断增长的数量。"},{t="邪恶的联盟",b="Stormscale娜迦的出现不仅仅是简单的领土侵略。Arbal透露，这些扭曲的前上层精灵正在协助虚无主义的Twilight's Hammer邪教。对于这些生物来说，亵渎和掠夺曾经庇护过它们的森林——特别是在服务于邪恶、阴暗的主人时——是不可原谅的罪行。遏制他们的数量迫在眉睫，以防止该邪教及其蛇形盟友进一步加强对这片土地的控制。"}},faq={{q="谁发布了Swelling Forces任务？",a="Swelling Forces由Arbal发布，他指引古树之林的冒险者去对抗聚集在东北方废墟中的敌对娜迦势力。",al={"谁发布swelling forces","arbal任务发布者","arbal在哪里"}},{q="为什么在这个任务中要针对娜迦？",a="Stormscale娜迦已经占领了附近的废墟，并威胁着周围的林地。更令人担忧的是，他们似乎在协助Twilight's Hammer邪教，给他们曾经称之为家园的土地带来了暴力。",al={"为什么要杀娜迦","废墟里的娜迦","stormscale的威胁"}},{q="娜迦与这些废墟之间有什么联系？",a="正如Arbal所指出的，娜迦曾经是古代卡利姆多的上层精灵，遭受了可怕的诅咒。尽管他们曾经居住在这些宏伟的城市中，但现在他们已化身为扭曲的毒蛇，寻求征服和破坏。",al={"什么是stormscale娜迦","娜迦的起源","被诅咒的上层精灵"}},{q="娜迦与Twilight's Hammer有什么联系？",a="任务揭示了娜迦正在协助阴暗的Twilight's Hammer邪教。虽然他们的具体安排仍未可知，但Arbal警告说，他们的结盟只会给古老的森林带来进一步的毁灭和苦难。",al={"twilight's hammer娜迦","为什么娜迦与邪教合作"}},{q="Stormscale的势力聚集在哪里？",a="废墟位于古树之林的东北方。冒险者被派往那里，通过猎杀他们的侍从、女巫和战士来遏制日益壮大的Stormscale军队。",al={"废墟在哪里","去哪里找stormscale"}},{q="为什么Arbal认为娜迦的行为是不可原谅的？",a="对Arbal来说，听命于黑暗主人而掠夺自己的古老家园是绝对不可原谅的。上层精灵曾经拥有的任何高贵品质，都已经随着他们堕落入残酷和黑暗的联盟中而彻底消失了。",al={"为什么arbal痛恨娜迦","arbal眼中的不可原谅"}}},fp="15,381,27.499.0,18.482.1,36.166.0,46.225.0,54.221.0,55.222.0,38.184.0,56.221.0"}
P.entries["quest:98021"] = {n="Journey to Sentinel Hill",s="“前往哨兵岭”指引联盟的冒险者前往西部荒野动荡的农田地带，向哨兵岭的哨所报到。当地指挥官数月来一直向暴风城请求皇家增援，却始终杳无音讯，这让他们感到十分沮丧。因此，他们已经准备好让任何愿意帮忙的旅行者直接投入工作。",h="“前往哨兵岭”指引联盟的冒险者前往西部荒野动荡的农田地带，向哨兵岭的哨所报到。当地指挥官数月来一直向暴风城请求皇家增援，却始终杳无音讯，这让他们感到十分沮丧。因此，他们已经准备好让任何愿意帮忙的旅行者直接投入工作。",kw={"journey to sentinel hill","人民民兵","哨兵岭","瘦弱的精灵","暴风城","西部荒野"},ang={["faction:Alliance"]="西部荒野是一片急需支援的联盟领土，然而暴风城却将当地指挥官的增援请求置之不理，只能依靠任何出现的志愿者。",["race:NightElf"]="哨兵岭的边境指挥官可能会抱怨派来的是个“瘦弱的精灵”而不是久经沙场的暴风城步兵，但哨兵岭确实需要一切它能得到的援助。"},sec={{t="抵达边境",b="“前往哨兵岭”标志着冒险者踏入了饱受战火蹂躏的西部荒野地区。哨兵岭哨所是周围农田的主要防御堡垒，但其驻军却长期人手不足，且遭到皇家法庭的忽视。当旅行者前来提供援助时，当地指挥官根本无暇去质疑他们的身份，而是急切地想让任何愿意出力的人投入工作。"},{t="向暴风城恳求",b="数月以来，哨兵岭的领导层一直向暴风城请求军事增援，以确保该地区免受日益严重的威胁。王国的漠视迫使当地指挥官只能接受任何上门求助的人——即便这意味着要用一句冷嘲热讽来迎接刚抵达的冒险者，抱怨自己想要的是一支军队，结果却只等来了一个瘦弱的精灵。在西部荒野，乞丐是没资格挑肥拣瘦的。"}},faq={{q="什么是“前往哨兵岭”？",a="“前往哨兵岭”是一项联盟任务，指引冒险者前往西部荒野的边境领土。它向新人介绍了驻扎在哨兵岭的当地守卫，他们一直在向暴风城请求援助，却始终未能获得足够的正式增援。",al={"什么是前往哨兵岭","前往哨兵岭任务","哨兵岭任务"}},{q="为什么哨兵岭要寻求帮助？",a="驻扎在哨兵岭的军事领导层数月来一直恳求暴风城派遣增援部队，以处理困扰西部荒野的种种麻烦。当地领导层被迫依靠偶尔出现的个别冒险者，而不是正规部队。",al={"谁在向暴风城乞求援助","哨兵岭驻军","为什么哨兵岭需要帮助"}},{q="为什么任务文本提到了一个瘦弱的精灵？",a="在完成旅程后，指挥官会提到他们数月来一直恳求暴风城的援助，结果却只被派来了一个瘦弱的精灵。指挥官一边抱怨着乞丐没资格挑肥拣瘦，一边迅速决定让新到的冒险者立即投入工作。",al={"瘦弱的精灵语录","为什么是瘦弱的精灵","哨兵岭对精灵的评论"}},{q="为什么暴风城没有派遣合适的增援部队？",a="暴风城的皇家政府目前正分身乏术，焦头烂额，导致西部荒野等外围领土在很大程度上被忽视了。哨兵岭在几个月内多次发出求援呼吁，但官方的皇家支持始终未能落实，迫使当地指挥官只能依靠志愿者。",al={"为什么暴风城不帮助西部荒野","暴风城忽视西部荒野","暴风城对西部荒野的援助"}},{q="什么是哨兵岭？",a="哨兵岭是西部荒野人民民兵的核心军事哨所和堡垒。它是抵御肆虐该地区农田的无法无天之徒、迪菲亚盗贼和豺狼人的第一道防线。",al={"哨兵岭在哪里","什么是哨兵岭","哨兵岭位置"}},{q="到达哨兵岭后会发生什么？",a="一旦你在哨兵岭报到，当地守卫会毫不拖延地让你投入工作。冒险者的任务是帮助处理西部荒野平原和农田各处的诸多威胁。",al={"在西部荒野做什么","西部荒野后续任务","到达西部荒野后发生什么"}}},fp="24,291,23.433.0,18.430.0,33.285.0,37.265.0,45.249.0,48.288.0,22.223.0,42.200.0"}
P.entries["quest:98024"] = {n="Journey to the Crossroads",s="Journey to the Crossroads引导着刚从元素位面抵达的旅行者前往贫瘠之地那崎岖的草原。冒险者们被指派去向十字路口的索克报到，以协助部落军队应对严酷的前线。这对了解部落在卡利姆多所面临的致命威胁而言是一次必不可少的引导。",h="Journey to the...",kw={"贫瘠之地","十字路口","元素位面","部落","journey to the crossroads","索克"},ang={["faction:Horde"]="这次旅程引导刚抵达的勇士们为部落拿起武器，在卡利姆多崎岖的前线提供了一次烈火般的试炼。",["race:Skyborne"]="既然已从元素位面抵达艾泽拉斯，旅行者们被敦促不要小看凡世的冲突，并要在为部落的服务中证明自己的勇气。"},sec={{t="前线的召唤",b="在从元素位面旅途归来并抵达艾泽拉斯的旅行者们面对的是一个清醒的现实：凡人的冲突相比之下似乎微不足道，但部落所面临的危险却是实实在在的。在前线服役为那些寻求成长并在此过程中协助凡世领域的人们提供了一个至关重要的试炼场。"},{t="卡利姆多的十字路口",b="为了开始服役，冒险者们会被指引向西南方，进入贫瘠之地那片广袤且被太阳炙烤的平原。那里坐落着十字路口，这是一个至关重要的枢纽，也是一个关键的部落哨站，其引以为傲的守卫者们时刻都在应对着周遭的危险。直接向索克报到能让新人们融入到定居点的防御体系中。"}},faq={{q="索克是谁？",a="索克是驻扎在贫瘠之地十字路口的一位重要的部落权威人物。他负责监管当地的防御工作，并指挥冒险者们去协助解决威胁着定居点及其周边领土的诸多危险。",al={"索克是谁","十字路口领袖","索克在哪里"}},{q="十字路口是什么？",a="十字路口是坐落于贫瘠之地主要道路交汇处的一个中心部落哨站和贸易枢纽。这里被充满敌意的野生生物、半人马部落和野猪人劫掠者所包围，守卫者们需要不断的援助来确保重要补给线的安全。",al={"十字路口是什么","贫瘠之地十字路口","为什么要去十字路口"}},{q="贫瘠之地位于哪里？",a="贫瘠之地是一片广袤且干旱的草原，位于卡利姆多中部，杜隆塔尔的西南方。它是一片连接整个大陆上部落领土的重要广袤区域。",al={"贫瘠之地在哪里","贫瘠之地位置"}},{q="为什么任务提到了元素位面？",a="任务中提到旅行者最近刚从元素位面抵达。虽然超凡界的冲突看起来似乎宏大，但威胁凡世领域和部落的危险却是迫在眉睫且严峻的。",al={"元素位面抵达","为什么提到元素位面","从元素位面旅程"}},{q="Journey to the Crossroads的任务目的是什么？",a="该任务旨在指引新人们直接向十字路口的索克报到，让他们融入到部落的前线作战中，并通过光荣的服役提供了一条变得强大的途径。",al={"十字路口任务目的","为什么派往十字路口"}},{q="十字路口的居民面临着什么样的危险？",a="贫瘠之地持续面临着来自原生掠食者、游荡的半人马、野猪人战帮以及联盟入侵的侵略，这使得每一个哨站都成为了需要有能力的守卫者驻守的争夺据点。",al={"贫瘠之地有什么危险","贫瘠之地威胁"}}},fp="25,335,22.324.0,26.328.0,13.222.0,23.260.0,30.167.0,47.209.0,49.199.0,52.195.0"}
P.entries["quest:98025"] = {n="WANTED: Jai'vhanel",s="WANTED: Jai'vhanel 是由黑海岸奥伯丁村议会发布的联盟赏金任务。公告要求除掉名为“剑羽”的疯狂黑猫头鹰 Jai'vhanel，她开始袭击奥伯丁附近道路上的旅客。冒险者必须在亚米萨兰遗迹附近猎杀这只生物，并将她死亡的证明交给哨兵戈琳达·纳希恩。",h="WANTED: Jai'vhanel 是由黑海岸奥伯丁村议会发布的联盟赏金任务。公告要求除掉名为“剑羽”的疯狂黑猫头鹰...",kw={"亚米萨兰","奥伯丁","黑猫头鹰","黑海岸","戈琳达·纳希恩","jai'vhanel","剑羽","wanted: jai'vhanel"},ang={["class:Druid"]="暗夜精灵德鲁伊密切关注着黑海岸的野生动物，像 Jai'vhanel 这样高贵的鸟类突然陷入疯狂并产生攻击性，这是一种令人担忧的生态干扰。",["class:Hunter"]="这只被称为“剑羽”的凶猛漆黑猛禽，是黑海岸山区附近极具攻击性的追踪者，她的狩猎习惯变得极其不稳定且具有致命危险。",["faction:Alliance"]="奥伯丁村议会依靠联盟冒险者和暗夜精灵哨兵来保护黑海岸重要的沿海公路免受疯狂掠食者的侵害。"},sec={{t="路上的威胁",b="奥伯丁村议会发布的一则公告向黑海岸沿海道路的旅客发出警告，称存在严重的威胁。一只著名的当地猫头鹰 Jai'vhanel（绰号“剑羽”）突然陷入了疯狂。她不再待在茂密的荒野中，而是开始袭击奥伯丁附近的旅客和信使，将一只普通的林地掠食者变成了该定居点的严重危险。"},{t="议会的赏金",b="为了确保道路安全，议会悬赏捉拿 Jai'vhanel。猎手们被指示追踪这只黑羽猛禽到亚米萨兰遗迹以北、山脚下的狩猎场。猎手必须带回她身上的一根标志性黑羽，交给奥伯丁的哨兵戈琳达·纳希恩以核实猎杀成果并领取奖励。"}},faq={{q="Jai'vhanel 是谁？",a="Jai'vhanel，也被称为“剑羽”，是一只以浑身漆黑羽毛而闻名的巨型猫头鹰。她本是黑海岸森林中常见的野生生物，但现在已经陷入疯狂，并开始对旅客表现出强烈的攻击性。",al={"jaivhanel 是谁","jaivhanel 是什么","剑羽是谁"}},{q="为什么要悬赏 Jai'vhanel？",a="奥伯丁村议会之所以对 Jai'vhanel 发出正式悬赏，是因为她已经发疯并开始攻击奥伯丁附近主要道路上的旅客，对当地交通构成了严重威胁。",al={"为什么要猎杀 jaivhanel","为什么要悬赏 jaivhanel","为什么这只猫头鹰会发起攻击"}},{q="在哪里可以找到 Jai'vhanel？",a="人们最后一次见到 Jai'vhanel 是在黑海岸的古代亚米萨兰遗迹以北，她在东部山脉的山脚下徘徊。",al={"jaivhanel 在哪里","jaivhanel 的位置","在哪里找到剑羽"}},{q="是谁悬赏了 Jai'vhanel？",a="这份赏金是由奥伯丁村议会发布的，他们负责监督这个沿海定居点及周边道路的民事安全与当地福利。",al={"谁发布了悬赏","谁想要 jaivhanel 死"}},{q="谁负责领取 Jai'vhanel 的赏金？",a="赏金猎人必须出示 Jai'vhanel 的一根黑羽作为她死亡的证明，并交给驻守在奥伯丁镇的哨兵戈琳达·纳希恩。",al={"谁负责收取死亡证明","在哪里上交 jaivhanel 的羽毛","戈琳达·纳希恩悬赏"}},{q="需要什么证明才能领取赏金？",a="任何要求领取议会赏金的人都必须找回并出示 Jai'vhanel 身上的一根标志性黑羽，以证明这只疯狂的鸟已经被杀。",al={"jaivhanel 的死亡证明是什么","什么物品证明 jaivhanel 已死"}}},fp="18,379,20.436.0,20.388.0,18.249.0,36.208.0,30.132.0,36.150.0,39.154.0,41.148.0"}
P.entries["quest:98042"] = {n="It's All Fun and Games Until...",s="It's All Fun and Games Until... 是一个与提交给桑德里斯的一项令人深感不安的发现有关的任务。在辨认出这件古老邪恶之物那无法误认的标记后，桑德里斯安排将该圣物立即送往达纳苏斯进行深入研究。",h="It's All Fun and Games Until...",kw={"古老邪恶","ande'thoras-ethil","达纳苏斯","古老邪恶的标记","暗夜精灵","桑德里斯"},ang={["faction:Alliance"]="联盟冒险者将令人不安的发现带给暗夜精灵当局，有助于确保危险的圣物得到达纳苏斯学者的检查和控制。",["race:NightElf"]="这项调查直接触及了暗夜精灵对古老腐化的警惕，促使达纳苏斯立即介入。"},sec={{t="令人不安的报告",b="一项令人不安的发现促使冒险者前往寻找桑德里斯，就此事寻求建议。在听取了冒险者的报告并检查了所带来的东西后，桑德里斯陷入了沉思，他意识到了一些无法等闲视之的黑暗征兆。"},{t="古老邪恶的标记",b="在仔细检查此事后，桑德里斯辨认出该发现物上附着着无法误认的古老邪恶标记。意识到危险远远超出了当地发生的意外，桑德里斯决定立即将该圣物送往达纳苏斯，托付给首都的学者和祭司进行严格的研究和封印。"}},faq={{q="谁参与完成了此任务？",a="该任务是提交给桑德里斯并由他结束的，他会听取不安的冒险者的汇报，并在准备将其运走之前检查所提交的物品或证据。",al={"谁发布了its all fun and games until","桑德里斯任务","谁回收its all fun and games until"}},{q="为什么要把这个物体送到达纳苏斯？",a="桑德里斯确认该神器或发现物带有古老邪恶的标记。桑德里斯表示他会立刻将其送往达纳苏斯进行进一步研究，除此之外他没有透露更多信息。",al={"为什么送到达纳苏斯","达纳苏斯研究","达纳苏斯的古老邪恶"}},{q="桑德里斯所指的古老邪恶是什么？",a="桑德里斯确认该发现物带有古老邪恶的标记，尽管关于其确切起源的具体细节在暗夜精灵首都进行更深入的研究之前仍处于保密状态。",al={"古老邪恶是什么","古老邪恶标记的含义"}},{q="'Ande'thoras-ethil' 是什么意思？",a="'Ande'thoras-ethil' 是桑德里斯在你谈话结束时所说的一句达纳苏斯语，在他说了该发现物将被带到达纳苏斯之后。",al={"ande'thoras-ethil的含义","andethoras ethil暗夜精灵短语","达纳苏斯语告别桑德里斯"}},{q="任务完成后会发生什么？",a="在揭露了那古老的腐化后，桑德里斯准备将这件令人不安的圣物立即运往达纳苏斯，以便首都的学者们可以对其进行检查。",al={"its all fun and games until完成之后会发生什么","fun and games之后的下一个任务","to darnassus后续"}},{q="哪个阵营负责这项调查？",a="此事由达纳苏斯的领导层和像桑德里斯这样的暗夜精灵人物负责处理，重点在于提交给暗夜精灵当局的威胁。",al={"its all fun and games是联盟专属吗","谁能执行its all fun and games until"}}},fp="31,248,18.272.0,24.322.1,41.170.0,42.196.0,48.187.0,35.146.0,40.170.0,41.160.0"}
P.entries["quest:98046"] = {n="Crown of the Earth",s="Crown of the Earth 是达纳苏斯的一个任务，大德鲁伊范达尔·鹿盔在一次涉及一瓶水的咒语施法失败后，放弃了该仪式并由此开启了此任务。这位沮丧的大德鲁伊打发走了冒险者，命令其将 Drained Vessel 送往 Temple of the Moon 交给女祭司拉里亚进行处理。然而，女祭司在检查瓶子时发现里面还有些许残留的水，这不禁让人怀疑仪式失败的真正原因。",h="Crown of the Earth 是达纳苏斯的一个任务，大德鲁伊范达尔·鹿盔在一次涉及一瓶水的咒语施法失败后，放弃了该仪式并由此开启了此任务。这位沮丧的大德鲁伊打发走了冒险者，命令其将 Drained Vessel...",kw={"塞纳里奥议会","crown of the earth","达纳苏斯","排空的器皿","艾露恩","范达尔·鹿盔","拉里亚","玛法里奥","temple of the moon"},ang={["class:Druid"]="范达尔明确地将冒险者称为德鲁伊同僚，在将其赶走之前，他对仪式失败表现出了生硬的不耐烦。",["faction:Alliance"]="该任务展示了在玛法里奥·怒风缺席的情况下，卡利姆多主要的联盟主城达纳苏斯内部平静的领导层紧张局势。",["race:NightElf"]="这项差事揭示了达纳苏斯内部日常的压力，将范达尔·鹿盔尖刻的权威与 Temple of the Moon 中 The Sisterhood of Elune 的耐心奉献形成了鲜明对比。"},sec={{t="范达尔的沮丧",b="在达纳苏斯，大德鲁伊范达尔·鹿盔承担着玛法里奥·怒风缺席期间引导暗夜精灵的重任。在寻找答案的过程中，范达尔试图利用瓶中盛放的圣水进行咒语仪式。当仪式似乎毫无结果时，大德鲁伊的脾气爆发了。他认定这些水毫无用处，便言语尖刻地打发走冒险者，并指示他们将 Drained Vessel 送往南方的 Temple of the Moon，让那里的女祭司处理掉。"},{t="残留的水滴",b="在抵达 Temple of the Moon 后，女祭司拉里亚表现得非常温和，她让冒险者不必介意范达尔严厉的态度，毕竟他肩负着沉重的担子。然而当她检查瓶子时，她发现了大德鲁伊在匆忙中忽略的一件事：瓶中仍残留着几滴水。这一残留物引发了一种明显的可能性：范达尔的仪式并非因魔法本身有缺陷而失败，而是因为容器未被彻底清空。"}},faq={{q="谁发布了 Crown of the Earth 任务？",a="该任务由达纳苏斯的大德鲁伊范达尔·鹿盔发布。范达尔目前在玛法里奥·怒风缺席期间主持塞纳里奥议会，在一次涉及圣水的咒语未能得出他想要的答案后，他极其烦躁地指派了这项任务。",al={"谁开启了 crown of the earth","crown of the earth 任务发布者","范达尔任务"}},{q="你需要将 Drained Vessel 送到哪里？",a="你需要将 Drained Vessel 送交至达纳苏斯南部 Temple of the Moon 的女祭司拉里亚。范达尔命令你将其移交以便让艾露恩的女祭司们处理，他认为这个用过的容器已毫无用处。",al={"去哪里上交 drained vessel","drained vessel 上交","拉里亚在哪里"}},{q="为什么范达尔·鹿盔如此沮丧？",a="大德鲁伊范达尔·鹿盔在玛法里奥·怒风离职期间领导暗夜精灵和塞纳里奥议会，承受着巨大的压力。当他的魔法咒语毫无所获时，他的烦躁和傲慢使他大发雷霆，并迅速打发走了冒险者，而不是深入探究失败的原因。",al={"为什么范达尔生气","范达尔的态度","为什么范达尔不耐烦"}},{q="为什么范达尔的咒语失败了？",a="范达尔·鹿盔认为水本身缺乏任何有用的力量，但女祭司拉里亚在接过瓶子时注意到一个关键细节。瓶内仍有几滴水残留，这表明咒语之所以失败，可能仅仅是因为在仪式过程中瓶子未被完全清空。",al={"为什么咒语会失败","范达尔的仪式成功了吗","失败的咒语"}},{q="在这个任务中玛法里奥在哪里？",a="玛法里奥·怒风目前不在达纳苏斯，这使得塞纳里奥议会的领导权和对暗夜精灵的指导责任落在了大德鲁伊范达尔·鹿盔身上。这种缺席给范达尔带来了沉重的负担，这也加剧了他的易怒和对挫折的不耐烦。",al={"玛法里奥在哪里","为什么玛法里奥缺席","玛法里奥的状态"}},{q="女祭司拉里亚是谁？",a="女祭司拉里亚是一位驻扎在达纳苏斯 Temple of the Moon 的艾露恩信徒。她从冒险者手中接过了瓶子，在对范达尔沉重的职责表示同情的同时，敏锐地察觉到瓶中仍有残留的水。",al={"谁是拉里亚","女祭司拉里亚背景故事","拉里亚 temple of the moon"}}},fp="18,440,21.512.0,19.479.1,39.284.0,37.232.0,38.307.0,35.304.0,37.287.0,24.283.0"}
P.entries["quest:98065"] = {n="Crown of the Earth",s="Crown of the Earth 是一个达纳苏斯任务，冒险者需要将净化的 Moonwell Remnants 送交给高阶女祭司泰兰德·语风。该任务发生在 Temple of the Moon 内部，揭示了艾露恩之水的神圣意义，以及泰兰德与大德鲁伊范达尔·鹿盔之间日益紧张的政治关系。",h="Crown of the Earth 是一个达纳苏斯任务，冒险者需要将净化的 Moonwell Remnants 送交给高阶女祭司泰兰德·语风。该任务发生在 Temple of the Moon...",kw={"crown of the earth","达纳苏斯","艾露恩","范达尔·鹿盔","玛法里奥","月亮井残骸","temple of the moon","泰兰德·语风"},ang={["class:Druid"]="泰兰德对于大德鲁伊范达尔·鹿盔的尖锐言辞，凸显了在玛法里奥缺席的情况下，塞纳里奥议会内部日益增长的摩擦。",["class:Priest"]="服务于高阶女祭司泰兰德·语风，巩固了艾露恩的教士在引导和管理暗夜精灵社会中所扮演的重要角色。",["faction:Alliance"]="获得觐见达纳苏斯领袖的机会，可以让人一窥联盟主要首府之一所面临的内部政治压力。",["race:NightElf"]="直接运送神圣的月亮井水，凸显了卡多雷双重领导体制的现状，即夹在泰兰德的祭司体系与范达尔的德鲁伊体系之间。"},sec={{t="觐见高阶女祭司",b="在收集到神圣的 Moonwell Remnants 后，冒险者需要将这些受祝福的圣水转移到一个仪式容器中，并直接交给泰兰德·语风。艾露恩的高阶女祭司居住在达纳苏斯的 Temple of the Moon 高处，守护着这座城市，并为每一位进入其中的人提供女神的光芒。将这神圣之水交由她保管，被视为一种荣耀以及对艾露恩的虔诚表现。"},{t="领导层之间的紧张关系",b="在收到圣水残骸后，泰兰德对冒险者拯救这受祝福之水的行为表示了深深的感激，但她的思绪很快便转回了笼罩着达纳苏斯的政治紧张局势。在玛法里奥·怒风缺席期间，大德鲁伊范达尔·鹿盔接管了德鲁伊事务，但泰兰德明确表示，统治卡多雷是她个人的职责。尽管她敦促人们尊重鹿盔的职位，但这次交流揭示了 The Sisterhood of Elune 与塞纳里奥议会之间尖锐的摩擦。"}},faq={{q="什么是 Crown of the Earth？",a="Crown of the Earth 是达纳苏斯的一个任务，冒险者需要将一容器的 Moonwell Remnants 带给 Temple of the Moon 内的高阶女祭司泰兰德·语风。这标志着与暗夜精灵最高领袖直接交流的一个时刻。",al={"什么是 crown of the earth","crown of the earth 任务","任务 crown of the earth"}},{q="泰兰德·语风是谁？",a="泰兰德·语风是艾露恩的高阶女祭司，也是暗夜精灵的政治领袖。她在 Temple of the Moon 的上层俯瞰着达纳苏斯，肩负着在动荡时期引导她的人民这一重担。",al={"泰兰德·语风是谁","泰兰德在哪里","高阶女祭司泰兰德"}},{q="为什么要将 Moonwell Remnants 带给泰兰德？",a="Moonwell Remnants 是受艾露恩祝福的神圣之水。鉴于其神圣属性，必须将其转移至仪式容器中并带给泰兰德，以便她能代表女神接收并守护这些圣水。",al={"为什么要带 moonwell remnants 给泰兰德","什么是 moonwell remnants","达纳苏斯神圣之水"}},{q="泰兰德和范达尔·鹿盔之间有什么争端？",a="在玛法里奥·怒风缺席期间，大德鲁伊范达尔·鹿盔领导着德鲁伊，但泰兰德坚定地主张，管理达纳苏斯和领导卡多雷仍然是她自己的责任，她拒绝让德鲁伊的权威盖过艾露恩的祭司。",al={"泰兰德与范达尔的紧张关系","为什么泰兰德不喜欢鹿盔","范达尔对战泰兰德"}},{q="这个任务期间玛法里奥在哪里？",a="玛法里奥·怒风目前不在达纳苏斯，导致德鲁伊之间出现了领导空缺，大德鲁伊范达尔·鹿盔填补了这一空缺，这加剧了与泰兰德之间的政治紧张关系。",al={"玛法里奥在哪里","玛法里奥发生了什么","玛法里奥缺席"}},{q="Temple of the Moon 在哪里？",a="Temple of the Moon 位于达纳苏斯的中心。它是 The Sisterhood of Elune 的主要圣殿，泰兰德在主圣殿大厅正上方的上层接见来访者。",al={"temple of the moon 位置","temple of the moon 在哪里","在哪里可以找到泰兰德"}}},fp="18,325,32.433.0,22.494.1,27.258.0,27.229.0,49.219.0,57.257.0,37.201.0,32.214.0"}
P.entries["quest:98067"] = {n="Eyes of the Sentinels",s="“Eyes of the Sentinels”是一个达纳苏斯的任务，玩家需要协助哨兵达莉亚·阳刃在暗夜精灵主城的关键哨位部署魔法侦察猫头鹰。面对泰达希尔日益增长的不安局势，这种空中监视不仅加强了城市的防御，还让哨兵们有时间向艾露恩祈祷。",h="“Eyes of the...",kw={"塞纳里奥要塞","工匠区","达莉亚·阳刃","达纳苏斯","艾露恩","eyes of the sentinels","羽月","哨兵猫头鹰","泰达希尔","temple of the moon"},ang={["class:Hunter"]="部署侦察猫头鹰体现了典型的暗夜精灵侦察手段，即训练有素的野兽和天上的禽类守望者是女猎手感知的自然延伸。",["class:Priest"]="哨兵们强调，仅靠武器无法保护卡多雷；定期的祈祷和来自艾露恩的精神馈赠对于她们的守护工作至关重要。",["faction:Alliance"]="确保达纳苏斯的安全可以保障暗夜精灵的首都，并巩固联盟在卡利姆多北部的核心据点。",["race:NightElf"]="哨兵部队是暗夜精灵传统的常备军和守护者，她们将武技与艾露恩的神圣祝福及注视结合在一起。"},sec={{t="奉献与防御",b="在月神殿的神圣庇护所中，哨兵达莉亚·阳刃负责守护达纳苏斯。遵照珊蒂斯·羽月将军的谕令——即每一位战士都必须兼顾武技与精神奉献——达莉亚安排在城市的各个关键枢纽部署警觉的哨兵猫头鹰。承担这些日常职责让哨兵们在月亮女神面前获得了宝贵的祈祷与反思时间，同时也确保了卡多雷首都始终处于严密的防守之下。"},{t="守望达纳苏斯",b="泰达希尔上空弥漫着不安的气息，促使哨兵们加倍警惕。为了防范渗透和动乱，哨兵猫头鹰被部署在关键路口：北部的塞纳里奥要塞下方深处、镇中心的繁华银行、工匠区内的旅店，以及主城门处。在当地城卫的协助下，这些禽类哨兵化身为沉默的守护者，监视着每一位行走在世界之树街道上的人。"}},faq={{q="什么是“Eyes of the Sentinels”？",a="“Eyes of the Sentinels”是达纳苏斯的一项任务，冒险者通过在城市各处的关键位置部署哨兵猫头鹰，协助哨兵达莉亚·阳刃维持警惕，以应对迫在眉睫的威胁。",al={"eyes of the sentinels任务","什么是eyes of the sentinels","eyes of the sentinels概述"}},{q="谁是哨兵达莉亚·阳刃？",a="哨兵达莉亚·阳刃是一位驻守在达纳苏斯月神殿的卡多雷守护者，她负责监督当地的防御常规，并确保警觉的猫头鹰能守卫城市的关键通路。",al={"谁是达莉亚·阳刃","达莉亚·阳刃背景故事","哨兵达莉亚·阳刃"}},{q="为什么要将哨兵猫头鹰安置在达纳苏斯各处？",a="哨兵猫头鹰是警觉的空中哨兵，也是艾露恩赐予的神圣侦察者，使哨兵们能够监视达纳苏斯各处的关键聚集点和交通咽喉。",al={"为什么要放置哨兵猫头鹰","哨兵猫头鹰的作用","哨兵猫头鹰的目的"}},{q="哨兵猫头鹰被放置在哪里？",a="哨兵猫头鹰被部署在北部塞纳里奥要塞下方深处的入口、镇中心的达纳苏斯银行、工匠区的旅店以及城市大门处。",al={"猫头鹰放置点","猫头鹰在哪里","eyes of the sentinels地点"}},{q="为什么哨兵们在泰达希尔处于高度戒备状态？",a="哨兵达莉亚·阳刃指出，泰达希尔世界之树的各个地方都有些不对劲，这促使哨兵们加强监视，时刻准备应对潜伏的危险。",al={"为什么哨兵感到担忧","泰达希尔出了什么问题","泰达希尔的不安"}},{q="羽月将军在哨兵的日常职责中扮演什么角色？",a="珊蒂斯·羽月将军统领着哨兵部队，并确保她的女猎手们能够平衡武职责任与对月亮女神艾露恩的日常奉献和祈祷。",al={"羽月将军的角色","珊蒂斯·羽月与哨兵","羽月的祈祷准则"}}},fp="21,324,20.489.0,20.490.0,30.201.0,31.195.0,52.188.0,35.188.0,50.197.0,71.175.0"}
P.entries["quest:98071"] = {n="Brewer's Trade",s="我们与丹加洛克的酿酒同族达成了一项交易，他们和任何人一样怀念法洛克家族的葡萄园。一箱法洛克特酿会被运往位于希尔斯布莱德丘陵东南部的堡垒，作为回报，我们将带回一袋他们的自酿啤酒花。",h="我们与丹加洛克的酿酒同族达成了一项交易，他们和任何人一样怀念法洛克家族的葡萄园。一箱法洛克特酿会被运往位于希尔斯布莱德丘陵东南部的堡垒，作为回报，我们将带回一袋他们的自酿啤酒花。",kw={"酿酒同族","丹加洛克","法洛克","法洛克特酿","希尔斯布莱德","自酿啤酒花","啤酒花","葡萄酒"},sec={{t="往昔的味道",b="法洛克葡萄酒最棒的陈酿大多早已被饮尽，但仍有一些法洛克特酿存放在地窖中。丹加洛克的酿酒同族也很怀念法洛克家族的葡萄园，因此我们与他们达成了一项交易。"},{t="丹加洛克的交换",b="将那箱酒运往东南方的丹加洛克，放在他们堡垒底部聚集处的壁炉旁。作为回报，你将带回一袋他们的自酿啤酒花。"}},faq={{q="这次交换交易了什么物品？",a="一箱从地窖运出的法洛克特酿葡萄酒，用于交换一袋他们的自酿啤酒花。",al={"我送的是什么","酿酒师的交易物品","法洛克葡萄酒"}},{q="在丹加洛克，酒需要被送到哪里？",a="你需要把它留在堡垒底部，也就是他们聚集处的壁炉旁。",al={"壁炉在哪里","丹加洛克交付地点","把酒留在哪里"}},{q="丹加洛克位于何处？",a="丹加洛克位于希尔斯布莱德丘陵的东南部。",al={"丹加洛克位置","丹加洛克在哪里"}},{q="法洛克一家是谁？",a="法洛克家族经营的葡萄园令人怀念。他们最棒的陈酿大多早已被饮尽，不过地窖里还剩有一些。",al={"法洛克家族","法洛克葡萄园"}}},fp="14,253,19.243.0,25.195.0,38.127.0,44.102.0,27.55.0,23.164.0"}
P.entries["quest:981"] = {n="奥萨拉克斯之塔",s="这一差事标志着针对奥萨拉克斯之塔黑滩教派的战役取得了胜利。在消灭了黑海岸邪恶废墟中该教派的领导层后，冒险者将消息带往南方的灰谷，传达给净化者德尔格伦。这对联盟来说是一次至关重要的胜利，清除了古代暗夜精灵边境的恶魔腐蚀。",h="这一差事标志着针对奥萨拉克斯之塔黑滩教派的战役取得了胜利。在消灭了黑海岸邪恶废墟中该教派的领导层后，冒险者将消息带往南方的灰谷，传达给净化者德尔格伦。这对联盟来说是一次至关重要的胜利，清除了古代暗夜精灵边境的恶魔腐蚀。",kw={"奥萨拉克斯","灰谷","巴苏尔","教派","黑滩","黑海岸","德尔格伦","迈斯特拉岗哨"},ang={["class:Paladin"]="向净化者德尔格伦报告对圣骑士来说有着特殊的意义，他们与他有着共同的圣洁使命，即从世界上净化恶魔腐蚀和邪恶教派。",["faction:Alliance"]="消灭该教派保护了连接黑海岸和灰谷的陆路，确保联盟的侦察兵和旅行者免受恶魔伏击的安全。",["race:NightElf"]="对于暗夜精灵来说，净化奥萨拉克斯之塔消除了玷污他们神圣沿海森林的古代上层精灵遗迹中的污秽。"},sec={{t="切断威胁",b="奥萨拉克斯之塔在黑海岸北部矗立了数周，像是一道化脓的伤口，被狂热的黑滩教派及其阴影主人所占据。通过不懈的追踪、情报收集和激烈的冲突，该教派的行动被彻底瓦解。随着他们的术士被杀，黑暗仪式被破坏，黑海岸恶魔渗透的直接威胁终于得到了遏制。"},{t="向迈斯特拉岗哨报告",b="在教派领袖死亡后，巴苏尔·影击指引胜利者前往南方的灰谷迈斯特拉岗哨。净化者德尔格伦正在那里等待，他是圣光的忠实战士，负责监督针对奥萨拉克斯之塔邪恶占领者的十字军行动。传达教派覆灭的消息让区域防御者感到安心，同时也为这位勇士赢得了德尔格伦永恒的祝福和当之无愧的感激。"}},faq={{q="这个任务的目标是什么？",a="这个任务是漫长的奥萨拉克斯之塔任务线的最后一步。你只需要从塔附近前往灰谷的迈斯特拉岗哨，并将你的决定性胜利报告给净化者德尔格伦。",al={"奥萨拉克斯之塔目标","奥萨拉克斯之塔任务提交","981号任务在哪里提交"}},{q="净化者德尔格伦是谁？",a="净化者德尔格伦是一位驻扎在灰谷北部迈斯特拉岗哨的联盟勇士。他手握圣光，致力于在整个卡利姆多北部清除腐蚀并对抗像黑滩教派这样的恶魔威胁。",al={"谁是德尔格伦","德尔格伦背景故事","净化者德尔格伦"}},{q="巴苏尔·影击是谁？",a="巴苏尔·影击是一位在黑海岸奥萨拉克斯之塔附近执行任务的联盟特工。他与德尔格伦密切合作，监控教派的动向，并引导冒险者从内部瓦解这个黑暗集团。",al={"巴苏尔","巴苏尔背景故事","谁是巴苏尔·影击"}},{q="黑滩教派在塔里做了什么？",a="黑滩教派占据了奥萨拉克斯之塔的古代遗迹，以进行黑暗仪式、召唤恶魔实体，并扩大他们在黑海岸沿海地区的邪恶影响力。",al={"黑滩教派","奥萨拉克斯发生了什么","奥萨拉克斯之塔背景故事"}},{q="迈斯特拉岗哨位于哪里？",a="迈斯特拉岗哨是一个位于灰谷西北部的联盟哨所，就在沿大路从黑海岸过来的边界关卡以南。",al={"迈斯特拉岗哨位置","迈斯特拉岗哨在哪里","德尔格伦位置"}},{q="黑滩教派被彻底消灭了吗？",a="虽然他们在奥萨拉克斯之塔的领导层已被处决，主要的仪式已被破坏，但分散的教徒和残党仍然在卡利姆多偏僻的角落出没。然而，他们在黑海岸的有组织威胁已被粉碎。",al={"教派消失了吗","黑滩教派被摧毁","我们杀死了教派吗"}}},fx={b456cfd7={q="巴苏尔·影击为什么要完成这件事？",a="黑海岸教派已被击溃，其首领也已覆灭。巴苏尔希望你把胜利的消息带回给净化者德尔格伦。是德尔格伦发起了对塔中邪教徒的行动，而巴苏尔认为你的功劳应当得到应有的认可，并领取圣骑士承诺的奖励。",al={"为什么让我回去找德尔格伦","巴苏尔的动机","为什么要向德尔格伦报告"}}},fp="22,390,16.431.0,24.418.0,31.228.0,28.247.0,29.233.0,56.205.0,32.143.0,52.238.0"}
P.entries["quest:98155"] = {n="Pristine Pesterhide Pelts",s="“Pristine Pesterhide Pelts”是一项代表克里斯蒂·格兰特（Kristy Grant）进行的任务，她是一位旅行者，正在千针石林寻找Pesterhide土狼那色彩鲜艳的毛皮。由于缺乏战斗训练，克里斯蒂依靠能干的冒险者来猎杀这些野兽并收集它们的毛皮。她的目标是将这些独特的皮毛运回无尽之海彼岸的暴风城，交给她的姐妹们，让她们将其制作成精致的服装和商品。",h="“Pristine Pesterhide Pelts”是一项代表克里斯蒂·格兰特（Kristy...",kw={"毛皮","狩猎","土狼","克里斯蒂·格兰特","pesterhide","暴风城","千针石林"},ang={["faction:Alliance"]="作为一位暴风城旅行者为她在首都从事工艺创作的家族提供供应的努力，这项任务凸显了联盟子民如何深入卡利姆多边境寻找异域材料。",["profession:Tailoring"]="从事布料和装饰性皮草工作的工匠们能够理解克里斯蒂姐妹们的雄心，她们试图将卡利姆多的野性毛皮转化为精致的服装。",["race:Human"]="克里斯蒂·格兰特体现了暴风城人类跨海远行、与王国内亲人保持密切联系的进取精神。"},sec={{t="姐妹的志向",b="远离暴风城繁华的鹅卵石街道，克里斯蒂·格兰特发现自己正穿行于千针石林那干旱、被阳光炙烤的峡谷底部。在观察当地野生动物时，她被本土Pesterhide土狼所披皮毛那令人惊叹的色泽和品质所吸引。克里斯蒂意识到这些独特的毛皮在东部王国几乎闻所未闻，于是她设想将一批毛皮运回故乡交给她的姐妹们。在她眼中，这些毛皮不仅是卡利姆多边境的一抹特色，更是原料，能经由家族中熟练的工匠之手，转化为真正非凡的物品。"},{t="盐碱平原与峡谷的猎人",b="尽管拥有工艺和贸易的眼光，克里斯蒂·格兰特并非战士，也没有面对峡谷中凶猛掠食者的战斗经验。Pesterhide土狼是凶残的群体食腐动物，游荡在参天平顶山下的尘土旷野中，这使得对于任何独自旅行的人来说，收获完整的毛皮都十分危险。为了在不危及自己生命的情况下获得五张无瑕的毛皮，克里斯蒂寻求路过千针石林的资深冒险者的帮助。这项任务需要冒险进入荒野，战胜那些领地意识极强的野兽，并仔细收集她家族在故乡进行工艺创作所需的毛皮。"}},faq={{q="谁是克里斯蒂·格兰特？",a="克里斯蒂·格兰特是一位来自暴风城王国的旅行者，目前正在卡利姆多游历。与穿行于千针石林的强硬士兵和雇佣兵不同，她承认自己没有任何战斗经验。相反，她依靠敏锐的观察力和对贵重工艺材料的独到眼光，雇佣能干的冒险者代她收集像土狼毛皮这样的货物。",al={"克里斯蒂·格兰特背景故事","谁发布了pristine pesterhide pelts任务","克里斯蒂·格兰特是谁"}},{q="什么是Pesterhide土狼？",a="Pesterhide土狼是原产于千针石林干旱峡谷底部和旷野的野生犬科掠食者。它们成群结队地在严酷的地形中游荡，进行狩猎和食腐。除了凶猛的本性外，它们还因其绚丽、色彩优美的皮毛而闻名，这些皮毛在沙漠岩石的映衬下显得格外显眼，吸引了过往裁缝和皮草商的注意。",al={"pesterhide土狼","千针石林的土狼","什么是pesterhide"}},{q="为什么克里斯蒂·格兰特想要这些毛皮？",a="克里斯蒂·格兰特想要收集完整的土狼毛皮，并将它们运回无尽之海彼岸的暴风城王国交给她的姐妹们。她对这些毛皮绚丽的色泽印象深刻，并相信她的姐妹们拥有将这些异域皮毛编织或剪裁成令人惊叹的成品所需的工艺。",al={"为什么要收集pesterhide毛皮","pesterhide毛皮的用途","克里斯蒂如何处理这些毛皮"}},{q="这些毛皮最终会去哪里？",a="在千针石林收集的毛皮最终将运往东部王国，具体来说是暴风城这座城邦。克里斯蒂打算将收获的毛皮运回无尽之海彼岸的故乡，这样她的姐妹们就可以使用那些在艾尔文森林或赤脊山等熟悉的林地中几乎无法获得的异域材料进行创作。",al={"毛皮被运往何处","运往暴风城的毛皮","谁获得了这些土狼毛皮"}},{q="为什么克里斯蒂不能自己猎杀土狼？",a="克里斯蒂·格兰特公开承认她完全没有任何战斗经验。千针石林的野兽极具攻击性且危险重重，特别是对于手无寸铁的工匠或旅行者而言。与其在游荡的土狼群面前冒受伤或死亡的风险，她雇佣熟练的流浪者来安全地猎杀这些动物。",al={"为什么克里斯蒂不能战斗","克里斯蒂·格兰特的战斗能力","为什么克里斯蒂需要帮助"}},{q="是什么让这些毛皮被称为“完整的”（Pristine）？",a="由于这些毛皮旨在供克里斯蒂在暴风城的姐妹们进行精细的工艺和时尚创作，普通的或破损的毛皮是不够的。只有未受损、完整的毛皮才能保留制作高质量服装所需的鲜艳色泽和质地，因此必须小心狩猎，并从野兽身上精心挑选出最好的样本。",al={"完整毛皮的含义","为什么需要完整的毛皮","pristine pesterhide pelts的质量"}}},fp="25,416,19.626.0,37.648.0,20.388.0,27.373.0,37.309.0,26.326.0,41.329.0,32.339.0"}
P.entries["quest:98190"] = {n="A Friend of the Family",s="“家族之友”是一项紧急的快递任务，始于湿地的米奈希尔港。由于担心龙喉兽人等当地威胁，港口当局委托一位冒险者将无价的米奈希尔雕像直接送到暴风城的暴风城要塞，交给伯瓦尔·弗塔根公爵。",h="“家族之友”是一项紧急的快递任务，始于湿地的米奈希尔港。由于担心龙喉兽人等当地威胁，港口当局委托一位冒险者将无价的米奈希尔雕像直接送到暴风城的暴风城要塞，交给伯瓦尔·弗塔根公爵。",kw={"伯瓦尔","龙喉氏族","弗塔根","港口","米奈希尔","雕像","暴风城","泰瑞纳斯","湿地"},ang={["class:Paladin"]="“米奈希尔”这个名字让人想起白银之手骑士团的创始赞助人，因此保护这件遗物对任何圣光战士来说都是庄严的职责。",["faction:Alliance"]="运送这件遗物不仅是为了纪念历史悠久的北方联盟，还能防止它落入龙喉氏族的手中。",["race:Human"]="对于人类来说，守护米奈希尔王朝的一件文物，就是守护陨落的洛丹伦那份引以为傲却又充满悲剧色彩的记忆，同时也强化了暴风城作为最后伟大人类王国的职责。"},sec={{t="岌岌可危的港口",b="米奈希尔港是连接东部王国北部和南部的关键海上门户。该港口以洛丹伦已故国王泰瑞纳斯·米奈希尔二世的名字命名，孤立在危险的沼泽和充满敌意的敌人之中。随着当地威胁的增加，港口领导层认识到，与北方陨落王国相关的无价遗物无法在这样一个暴露的前哨站中得到安全保护。"},{t="龙喉氏族的威胁",b="湿地仍然盘踞着龙喉氏族的残党，这些野蛮的兽人以其黑暗的过去和无情的投机主义而闻名。鉴于他们就在附近且渴望征服，港口守卫担心龙喉氏族会不择手段地掠夺像米奈希尔雕像这样的历史珍宝，甚至可能为了自己的目的而亵渎或将这种象征武器化。"},{t="直接面见公爵",b="为了避免通过常规官僚或军事渠道造成的延误，快递员被指示完全绕过指挥链。遗物被直接发往暴风城要塞，交到年轻的安度因·乌瑞恩国王的摄政王——伯瓦尔·弗塔根公爵手中，坚信首都的领导层最能保护这份洛丹伦的遗产。"}},faq={{q="什么是米奈希尔雕像？",a="米奈希尔雕像是一件与洛丹伦王室血统和泰瑞纳斯·米奈希尔二世国王有关的珍贵传家宝。它代表了北方王国与联盟之间的历史纽带，使其成为了拾荒者和敌人的目标。",al={"米奈希尔遗物","雕像是什么","雕像背景"}},{q="为什么雕像不能留在米奈希尔港？",a="米奈希尔港位置偏远，四周环绕着充满敌意的沼泽、黑铁矮人、鱼人和敌对兽人。驻军认为该定居点过于脆弱，无法安全保护如此重要的遗物。",al={"为什么要转移雕像","米奈希尔港不安全吗"}},{q="龙喉氏族是谁，为什么他们想要它？",a="龙喉氏族是盘踞在湿地内的一支兽人派系。港口官员担心他们会不惜牺牲战士来掠夺享有盛誉的联盟遗物，并可能对其进行亵渎或恶意利用。",al={"龙喉氏族威胁","为什么兽人想要雕像"}},{q="为什么要将遗物直接交给伯瓦尔·弗塔根？",a="作为暴风城的摄政王和年轻的安度因国王的守护者，伯瓦尔·弗塔根公爵在首都拥有最高行政权力。直接交给他可以确保遗物绕过行政僵局，并获得最高级别的安全保障。",al={"为什么是伯瓦尔","为什么要绕过指挥链"}},{q="伯瓦尔·弗塔根公爵在哪里？",a="伯瓦尔·弗塔根公爵站在暴风城要塞的王座大厅里，与年幼的安度因·乌瑞恩国王在一起。",al={"伯瓦尔位置","伯瓦尔在哪里"}},{q="米奈希尔港与泰瑞纳斯国王有什么联系？",a="米奈希尔港是为了纪念泰瑞纳斯·米奈希尔二世国王而命名的，他在第三次战争中不幸去世之前，曾领导洛丹伦并在第二次战争期间支持洛丹伦联盟。",al={"为什么叫米奈希尔港","泰瑞纳斯·米奈希尔联系"}}},fx={ece51c60={q="为什么选你把米奈希尔雕像送到暴风城？",a="米奈希尔港地处偏僻，湿地各处的敌对势力一直威胁着这里，驻军不得不全力防守港口。你已经找回传家宝，证明了自己的能力和可靠。委托一位能干而独立的旅人，可以避免削弱当地防御，也能让任务在穿越危险地带时保持隐秘。",al={"为什么派我去","为什么不派卫兵","为什么要运送雕像"}}},fp="22,291,19.430.0,20.362.0,24.373.0,31.240.0,48.205.0,46.226.0,51.236.0,43.118.0,49.192.0"}
P.entries["quest:98191"] = {n="A Friend of the Family",s="伯瓦尔·弗塔根公爵委托一位冒险者将一座珍贵的米奈希尔雕像送到Cathedral of Light。这座遗物描绘了洛丹伦已故的国王泰瑞纳斯·米奈希尔二世，它已经开始汇聚圣光之力。它被移交给格雷森·沙东布瑞克公爵，以在暴风城的精神中心进行永久保存。",h="伯瓦尔·弗塔根公爵委托一位冒险者将一座珍贵的米奈希尔雕像送到Cathedral of...",kw={"伯瓦尔","大教堂","洛丹伦","米奈希尔","沙东布瑞克","雕像","暴风城","泰瑞纳斯"},ang={["class:Paladin"]="对于一名圣骑士来说，守护一件带有圣光有形触感的泰瑞纳斯国王遗物，代表了对最初批准成立白银之手骑士团的统治者的深切敬意。",["class:Priest"]="在一尊简单的雕像中汇聚圣光能量，印证了洛丹伦信徒即使在王国物质毁灭之后，依然长存的精神遗产。",["faction:Alliance"]="泰瑞纳斯·米奈希尔二世国王是洛丹伦联盟的基石，这使得任何与他有关的文物都成为团结和纪念的宝贵象征。"},sec={{t="一份珍贵的纪念品",b="泰瑞纳斯·米奈希尔二世国王是第二次战争期间大联盟的缔造者，也是一位极具个人奉献精神的人。尽管他在人类诸王国中地位崇高，泰瑞纳斯却非常谦逊，并以不喜欢为自己树碑立传而闻名。由于他的个人抵触，很少有人委托制作他的肖像，而在洛丹伦遭受恐怖的毁灭和天灾军团的蹂躏后，幸存下来的就更少了。"},{t="神恩的触碰",b="当伯瓦尔·弗塔根公爵检查幸存的米奈希尔雕像时，他发现了远超简单工艺的东西。圣光本身已经开始在这尊雕像内汇聚，赋予其宁静的精神共鸣。伯瓦尔认为Stormwind Keep的皇宫对于这样一件神圣的物品来说并不是合适的圣所，于是他指示将其带过城市送到Cathedral of Light，交由圣骑士训练师格雷森·沙东布瑞克公爵保管。"}},faq={{q="泰瑞纳斯·米奈希尔二世国王是谁？",a="泰瑞纳斯·米奈希尔二世国王是洛丹伦王国的受人爱戴的统治者。在第二次战争期间，他召集了不同的人类国家，并与矮人、侏儒和高等精灵联手组建了大联盟，最终击败了兽人部落。他在自己王国的陷落中被杀。",al={"泰瑞纳斯·米奈希尔","泰瑞纳斯是谁","洛丹伦国王"}},{q="为什么泰瑞纳斯国王的雕像如此稀少？",a="尽管他享有崇高的声望并深受人民爱戴，泰瑞纳斯国王却以个人谦逊而闻名，不喜欢奢华的自我纪念碑。很少有雕像或纪念碑是以他的形象雕刻的，而且几乎没有在洛丹伦的天灾毁灭中幸存下来。",al={"为什么雕像很少","米奈希尔雕像的稀有度","为什么纪念碑很少"}},{q="为什么米奈希尔雕像会散发出圣光？",a="伯瓦尔注意到圣光似乎已经在雕像中汇聚。他称赞泰瑞纳斯是一位善良而虔诚的人，但并没有解释为什么这座特定的雕像会聚集圣光之力。",al={"为什么雕像有圣光","神圣雕像","汇聚的圣光"}},{q="格雷森·沙东布瑞克公爵是谁？",a="格雷森·沙东布瑞克公爵是一位白银之手骑士团的人类老兵圣骑士，也是Cathedral of Light内的一位杰出大师。他驻扎在Cathedral Square，负责训练有志向的圣骑士，并为暴风城的信徒监督圣职事务。",al={"沙东布瑞克是谁","格雷森的角色"}},{q="为什么伯瓦尔公爵要将雕像送到Cathedral of Light？",a="虽然伯瓦尔尊崇泰瑞纳斯作为联盟之父的角色，但雕像已经明显聚集了圣光之力。伯瓦尔认为，这种圣光的载体不属于Stormwind Keep的宫廷官僚，而应该在圣职教团的照看下存放在Cathedral of Light中。",al={"为什么要送到大教堂","为什么不留在stormwind keep"}},{q="Cathedral of Light位于何处？",a="Cathedral of Light俯瞰着Cathedral Square，位于暴风城的中心地带，处于Dwarven District、Trade District和Mage Quarter之间。它是南部王国圣光教会的主要圣所和礼拜中心。",al={"cathedral of light在哪里","cathedral square的位置"}}},fp="22,330,18.456.0,16.505.0,33.294.0,40.275.0,53.193.0,34.252.0,61.275.0,40.275.0"}
P.entries["quest:982"] = {n="深不可测的海洋",s="“深海，浩瀚之洋”是一个联盟任务，由奥伯丁的高尔博德·钢手提供。玩家的任务是潜入村庄北侧的水域，从两艘沉没的暗夜精灵船只——“银色黎明号”和“迷雾面纱号”中找回私人锁箱。这两艘船都遭到了沿海鱼人的伏击，幸存的船员们正急于寻求一个了结。",h="“深海，浩瀚之洋”是一个联盟任务，由奥伯丁的高尔博德·钢手提供。玩家的任务是潜入村庄北侧的水域，从两艘沉没的暗夜精灵船只——“银色黎明号”和“迷雾面纱号”中找回私人锁箱。这两艘船都遭到了沿海鱼人的伏击，幸存的船员们正急于...",kw={"奥伯丁","黑海岸","深海浩瀚之洋","高尔博德·钢手","锁箱","迷雾面纱号","鱼人","沉船","银色黎明号"},ang={["faction:Alliance"]="奥伯丁船员们共同的悲痛展现了矮人与暗夜精灵在卡利姆多海岸之间紧密的航海合作。",["race:Dwarf"]="高尔博德·钢手展现了矮人缅怀阵亡同伴、在异乡港口支持其他船员的典型本能。",["race:NightElf"]="阵亡的船长们是服务于奥伯丁海上贸易的暗夜精灵航海家，找回他们的遗物是一项关乎祖先荣誉的任务。"},sec={{t="海岸悲剧",b="黑海岸外的水域变得越来越危险，不仅仅是因为暗流和天然暗礁，还有极具攻击性的沿海部落。“银色黎明号”和“迷雾面纱号”在前往奥伯丁港口的途中，被成群的鱼人淹没。两艘船都没能幸免于难，沉没在定居点北部的浅滩中。幸存的船员虽然逃到了岸上，但船只和船长的损失给港口笼罩上了一层沉重的阴影。"},{t="找回失落的记忆",b="驻扎在奥伯丁的矮人高尔博德·钢手主动承担起缅怀阵亡暗夜精灵船长的责任。尽管这些船只现在已是水下废墟，被当地鱼人当作战利品和巢穴，但船长们的锁箱仍锁在进水的船舱里。找回里面的航海日志和个人物品，可以让奥伯丁的幸存船员们妥善哀悼他们的指挥官，并让逝者的灵魂得到安息。"}},faq={{q="沉船位于哪里？",a="“银色黎明号”和“迷雾面纱号”的残骸都淹没在黑海岸外，就在奥伯丁码头的正北方。",al={"沉船位置","沉船地点","在哪里找到银色黎明号"}},{q="“银色黎明号”和“迷雾面纱号”发生了什么事？",a="两艘船在穿越大海前往奥伯丁的途中都遭到了鱼人的伏击。船员们被鱼人压制，两位船长不幸丧生，船只沉没在海底。",al={"船只是如何沉没的","为什么船只沉没","什么让迷雾面纱号沉没"}},{q="高尔博德·钢手是谁？",a="高尔博德·钢手是一位居住在暗夜精灵港口奥伯丁的矮人。他照顾着镇上的幸存船员，并委托冒险者找回失踪船长的遗物。",al={"谁提供深海浩瀚之洋任务","高尔博德·钢手背景故事"}},{q="锁箱里有什么？",a="锁箱里装着阵亡的暗夜精灵船长的个人物品和航海日志，这些都是在海难中幸存的船员们所珍视的物品。",al={"锁箱里有什么","船长锁箱内容物"}},{q="为什么幸存者如此在意这些遗物？",a="这些船长是备受尊崇的暗夜精灵航海家。找回他们的日志和遗物是对幸存船员的一种慰藉，据信这也有助于让逝者的灵魂得到安息。",al={"为什么要找回锁箱","为什么要帮助船长"}},{q="现在是什么生物占据了沉船？",a="废墟已被鱼人占领，它们将沉没的船体当作战利品，并在周围的水域游荡。",al={"什么在守卫沉船","沉船处的怪物"}}},fp="20,359,21.488.0,24.426.0,35.143.0,54.185.0,25.193.0,29.164.0,54.177.0,42.115.0"}
P.entries["quest:98208"] = {n="Bloom of the Heavens",s="“天之绽”涉及到寻回诺德尔，这是一种神圣的暗夜精灵花卉，必须在满月时于海加尔山采集。这朵花在暗夜精灵船只“飞鱼号”于米奈希尔港以南遭遇海难时遗失了，与其一同沉没的还有库尔提拉斯第三舰队的船只。现在，找回这朵花的任务落在了那些勇敢到足以面对盘踞在残骸中的鱼人的冒险者手中。",h="“天之绽”涉及到寻回诺德尔，这是一种神圣的暗夜精灵花卉，必须在满月时于海加尔山采集。这朵花在暗夜精灵船只“飞鱼号”于米奈希尔港以南遭遇海难时遗失了，与其一同沉没的还有库尔提拉斯第三舰队的船只。现在，找回这朵花的任务落在了...",kw={"奥伯丁","bloom of the heavens","飞鱼号","米奈希尔港","海加尔山","鱼人","诺德尔","赛蕾莎·暮语","泰达希尔","湿地"},ang={["faction:Alliance"]="遗失的飞鱼号在米奈希尔港海岸外遭遇灾难前，曾与库尔提拉斯第三舰队一同航行。",["profession:Herbalism"]="诺德尔是一种极其罕见的暗夜精灵花卉，必须在海加尔山顶的满月下培育，使其成为一种非凡的植物学奇观。",["race:NightElf"]="诺德尔代表了一种珍贵的来自海加尔山的植物圣物，是在暗夜精灵将家园迁往泰达希尔枝叶之前采集的。"},sec={{t="海加尔山的圣物",b="赛蕾莎·暮语从卡利姆多海岸的奥伯丁远道而来，前往米奈希尔港，试图打捞一件具有深厚文化意义的宝物。她寻找的货物是诺德尔，通用语称其为“天之绽”，这是一种神圣的花朵，在满月时采集于海加尔山之巅。对于如今居住在泰达希尔的流离失所的暗夜精灵来说，这些来自故土山脉的圣物是他们文化传承中无可替代的珍宝。"},{t="飞鱼号的命运",b="这朵花在许多个月前就已经遗失了。当时，暗夜精灵的“飞鱼号”船只在与库尔提拉斯第三舰队同行时，在米奈希尔港以南的岩石海岸遭遇海难。如今，这艘破损的船体残骸静静地躺在浅滩中，作为这场灾难的沉重纪念碑。更糟糕的是，凶猛的鱼人掠夺者占据了沉船残骸，它们极力守卫着这艘破船，并威胁着任何试图收回卡多雷货物的人。"}},faq={{q="什么是诺德尔？",a="诺德尔在达纳苏斯语中的意思是“天之绽”。它是对暗夜精灵具有重要意义的神圣花卉，在满月时从暗夜精灵的祖居地——海加尔山之巅采摘。",al={"什么是诺德尔","诺德尔花卉","什么是天之绽"}},{q="飞鱼号是什么？",a="飞鱼号是一艘与库尔提拉斯第三舰队同行的暗夜精灵船只。许多个月前，这艘船在湿地的米奈希尔港以南海岸遭遇海难，其珍贵的货物也随之散落。",al={"飞鱼号船只","哪艘船沉没了","库尔提拉斯第三舰队湿地"}},{q="赛蕾莎·暮语是谁？",a="赛蕾莎·暮语是一位暗夜精灵使者，她跨越海洋，从奥伯丁和泰达希尔的枝叶间来到米奈希尔港，专门为了替族人寻回这朵遗失的花朵。",al={"谁是赛蕾莎·暮语","米奈希尔港的任务发布者","米奈希尔的暗夜精灵"}},{q="沉船为什么危险？",a="凶猛的鱼人掠夺者已经侵占了米奈希尔港以南的海岸残骸，占领了飞鱼号的残骸，这使得赛蕾莎的打捞工作变得极其危险。",al={"为什么鱼人在残骸处","谁守卫着残骸","米奈希尔以南的残骸"}},{q="为什么诺德尔对暗夜精灵如此重要？",a="这朵花是在泰达希尔建立之前，于卡多雷曾经的家园——海加尔山之巅采摘的。由于其来源的特殊性和在满月下采摘的神圣仪式，它对暗夜精灵而言具有巨大的文化和情感价值。",al={"为什么这朵花很重要","赛蕾莎为什么想要诺德尔"}},{q="在哪里可以找到残骸？",a="飞鱼号的残骸位于湿地的米奈希尔港以南的海岸上，坐落在如今被敌对鱼人占领的岩石之中。",al={"残骸在哪里","花在哪里","湿地沉船地点"}}},fp="20,370,22.466.0,29.455.0,16.225.0,27.218.0,27.190.0,31.166.0,47.248.0,32.143.0"}
P.entries["quest:98209"] = {n="Bloom of the Heavens",s="“天界之花”是一次跨海旅程，旨在运送一种名为“诺德尔”的暗夜精灵奇迹植物遗物。人们认为它已经失传数代，但这一幸存的植株成为了艾露恩的恩典以及卡多雷在失去永生后依然坚韧不拔的强大象征。",h="“天界之花”是一次跨海旅程，旨在运送一种名为“诺德尔”的暗夜精灵奇迹植物遗物。人们认为它已经失传数代，但这一幸存的植株成为了艾露恩的恩典以及卡多雷在失去永生后依然坚韧不拔的强大象征。",kw={"奥伯丁","bloom of the heavens","黑海岸","达纳苏斯","艾露恩","米奈希尔港","诺德尔","塞莱萨","桑德里斯风歌","湿地"},ang={["faction:Alliance"]="这一任务连接了东部王国繁忙的联盟港口——米奈希尔港，以及横跨无尽之海后的卡利姆多北部的奥伯丁与达纳苏斯。",["profession:Herbalism"]="草药师和植物学家们一定会对诺德尔的失而复得感到欣喜，这是一种被认为失传已久、需要在达纳苏斯进行培育的神圣植物。",["race:NightElf"]="诺德尔是卡利姆多神圣遗产的珍贵遗存，也是艾露恩在卡多雷适应失去永生的过程中依然眷顾着他们的美好征兆。"},sec={{t="危险的回收",b="在湿地的沼泽中，塞莱萨成功回收了传说中的花朵——诺德尔，并抵御了当地凶猛鱼人的攻击。由于在惊险的逃脱后精疲力竭，她将这株寻回的植物托付给一位冒险者，让他将其带过无尽之海送往奥伯丁。从米奈希尔港出发的船只可以直达黑海岸，连接起东部王国与卡利姆多北部。"},{t="艾露恩恩典的征兆",b="当奥伯丁的桑德里斯·风歌长老收到诺德尔时，他感到无比震惊，因为他一直以为这株神圣的花朵早已永远消失了。对于在海加尔山之战后不得不接受失去永生这一代价的暗夜精灵来说，诺德尔的奇迹般幸存如同艾露恩降下的福泽，闪耀着光芒。桑德里斯准备将这株娇贵的植物送往达纳苏斯，以确保它能被妥善培育并传承给后代。"}},faq={{q="什么是诺德尔？",a="诺德尔是暗夜精灵认为早已失传的一种神圣植物。它在多年后被重新发现并幸存下来，使其成为艾露恩神圣眷顾的珍贵象征，也是大自然顽强生命力的见证。",al={"什么是诺德尔","诺德尔之花","神圣之花"}},{q="谁发布了“天界之花”这个任务？",a="该任务由位于湿地的塞莱萨发布。尽管遭到敌对鱼人的伏击和追击，她还是成功找回了这株神圣的花朵，但这次磨难使她精疲力竭，无法亲自完成余下的旅程。",al={"谁发布天界之花任务","湿地诺德尔任务发布者","湿地塞莱萨"}},{q="诺德尔需要被送往哪里？",a="诺德尔必须被送过大海，交给位于黑海岸沿岸的奥伯丁的桑德里斯·风歌长老。从米奈希尔港出发，旅客可以乘船直达奥伯丁。",al={"我该把诺德尔带到哪里","桑德里斯风歌位置","奥伯丁交付"}},{q="为什么诺德尔对暗夜精灵如此重要？",a="桑德里斯·风歌长老认为这株花朵的幸存是黑暗时期中极其罕见的希望灯塔。它神圣地提醒着人们艾露恩的恩典，以及卡多雷在第三次战争中牺牲了永生后依然坚韧不拔的精神。",al={"为什么诺德尔对暗夜精灵很重要","诺德尔背景故事","暗夜精灵永生诺德尔"}},{q="这朵花到达奥伯丁后会发生什么？",a="在奥伯丁收到这株花后，桑德里斯·风歌会安排将其安全地运往内陆的达纳苏斯，由那里的暗夜精灵植物学家和祭司进行精心的培育。",al={"诺德尔后续","诺德尔达纳苏斯","桑德里斯把诺德尔送到哪"}},{q="如何从米奈希尔港前往奥伯丁？",a="旅客可以搭乘停靠在湿地米奈希尔港的客船，该船会横跨无尽之海，直接抵达黑海岸的奥伯丁码头。",al={"如何从湿地前往奥伯丁","米奈希尔港前往奥伯丁的船","前往黑海岸的船"}}},fp="20,274,20.407.0,23.464.0,16.200.0,41.219.0,40.188.0,49.256.0,56.197.0,52.165.0"}
P.entries["quest:98245"] = {n="Razormaw Needling",s="“刃喉之针”是湿地的一项任务，在该任务中，Howin Kindfeather委托旅行者从当地的刃喉迅猛龙身上收集门齿。Howin打算用它们锋利的牙齿制作耐用的锥子，以便刺穿并缝合幼龙鳞片，从而制成抗火护甲。",h="“刃喉之针”是湿地的一项任务，在该任务中，Howin Kindfeather委托旅行者从当地的刃喉迅猛龙身上收集门齿。Howin打算用它们锋利的牙齿制作耐用的锥子，以便刺穿并缝合幼龙鳞片，从而制成抗火护甲。",kw={"黑铁","龙喉","howin kindfeather","恐龙岭","迅猛龙","刃喉门齿","razormaw needling","盐沫沼泽","湿地","幼龙鳞片"},ang={["faction:Alliance"]="确保防龙火装备的供给，有助于联盟对抗占据东部沼泽的龙类和龙喉部队的持续斗争。",["race:Dwarf"]="Howin Kindfeather与蛮锤矮人和铁炉堡矮人一样，对肆虐湿地和格瑞姆巴托的黑铁氏族和龙喉兽人怀有深切的仇恨。"},sec={{t="复仇工具",b="在湿地那潮湿的土地上，Howin Kindfeather对那些长期祸害该地区的敌人怀有深刻的仇恨：狡诈的黑铁矮人、残暴的龙喉兽人，以及他们带入战场、口吐烈焰的幼龙。为了反击并防备龙火，Howin致力于用幼龙鳞片制作防护护甲。然而，这些坚韧的兽皮在没有特殊制作工具的情况下，极难缝合在一起。"},{t="獠牙化作针",b="为了刺穿坚韧的幼龙皮，Howin需要比普通钢针更锋利、更坚固的工具，因为普通钢针在龙鳞上很容易弯曲或变钝。他将目光投向了潜伏在东北部恐龙岭和西北部盐沫沼泽的本地刃喉迅猛龙。刃喉迅猛龙因其致命且如针尖般锋利的牙齿而得名，完整的刃喉迅猛龙门齿是完美的锥子，可以刺穿坚硬的鳞片而不会在压力下破碎。"}},faq={{q="谁发布了任务“刃喉之针”？",a="Howin Kindfeather在湿地发布了这个任务。他深切痛恨黑铁矮人、龙喉氏族以及他们骑乘的幼龙，并试图用幼龙鳞片制作抗龙火护甲。",al={"谁发布了刃喉之针任务","howin kindfeather是谁","刃喉之针任务发布者"}},{q="为什么Howin Kindfeather需要刃喉迅猛龙的门齿？",a="Howin正在使用坚韧的幼龙鳞片制作防护护甲，但这种皮太厚，难以缝合。他需要刃喉迅猛龙锋利而坚固的门齿来制作一套足以刺穿鳞片而不会折断的锥子。",al={"为什么howin需要迅猛龙牙齿","刃喉迅猛龙门齿的用途","这些牙齿是用来做什么的"}},{q="刃喉迅猛龙在哪里？",a="刃喉迅猛龙在湿地有两处主要的狩猎场：位于东北部高地的恐龙岭，以及位于西北部靠近海岸的盐沫沼泽。",al={"在哪里可以找到刃喉迅猛龙","湿地刃喉迅猛龙位置","迅猛龙在哪里"}},{q="Howin Kindfeather用幼龙鳞片制作什么？",a="Howin正在将幼龙鳞片缝合成防护装备。这些鳞片能提供卓越的防御力来抵御烈焰吐息，从而在对抗龙类和龙喉氏族的幼龙时提供至关重要的保护。",al={"howin在制作什么护甲","湿地幼龙鳞片护甲","为什么要用幼龙鳞片"}},{q="为什么Howin憎恨黑铁矮人和龙喉氏族？",a="湿地和周围的山脉留下了黑铁氏族和龙喉兽人的深深创伤，这些兽人在第二次战争期间奴役了红龙。Howin痛恨这两个派系以及他们的飞行坐骑，并决心要一雪前耻。",al={"为什么憎恨黑铁和龙喉","howin的敌人","为什么howin憎恨龙喉氏族"}},{q="Howin把迅猛龙门齿变成了什么？",a="锥子是一种细长的尖头手工工具，用于在缝纫前在坚硬的兽皮和皮革上钻孔。通过将完整的迅猛龙门齿安装在手柄上，或者利用它们天然的锥度，Howin制作出了耐用的锥子，能够刺穿龙鳞而不会折断。",al={"什么是锥子","刃喉锥子","迅猛龙牙齿如何用作工具"}}},fp="17,275,20.479.0,16.435.0,38.217.0,50.270.0,39.178.0,55.213.0,49.257.0,46.258.0"}
P.entries["quest:98246"] = {n="Trying Times",s="“Trying Times”是湿地的一项联盟任务，冒险者需要协助矮人霍文·羽言。为了让他那脾气暴躁的狮鹫“低音喙”为接下来的任务做好准备，霍文需要收集十二枚从凶猛的剃刀鳄（Razormaw）迅猛龙那里获得的新鲜蛋。",h="“Trying Times”是湿地的一项联盟任务，冒险者需要协助矮人霍文·羽言。为了让他那脾气暴躁的狮鹫“低音喙”为接下来的任务做好准备，霍文需要收集十二枚从凶猛的剃刀鳄（Razormaw）迅猛龙那里获得的新鲜蛋。",kw={"低音喙","狮鹫","霍文·羽言","恐龙岭","剃刀鳄蛋","盐沫沼泽","trying times","湿地"},ang={["faction:Alliance"]="保持狮鹫的健康对于卡兹莫丹各地的联盟旅行和通讯至关重要，特别是在当地威胁危及区域安全的时候。",["race:Dwarf"]="矮人狮鹫骑士深知，一只脾气暴躁的狮鹫和任何敌人一样危险，因此在起飞前进行适当的喂养和照料是绝对必要的。",["race:Gnome"]="霍文幽默地指出，剃刀鳄迅猛龙蛋的蛋黄有侏儒脑袋那么大，这提供了一个生动但略显不敬的矮人度量衡。"},sec={{t="安抚饥饿的狮鹫",b="在湿地那阴暗辽阔的区域里，维持一匹能用的坐骑需要时刻保持警惕。与他的狮鹫“低音喙”一同工作的矮人霍文·羽言，在没能满足他伙伴那反复无常的胃口之前，绝不肯启程飞行。饥饿的狮鹫顽固、不可预测，而且容易暴起伤人，因此在沼泽地进行任何空中行动前，提供一顿正餐是首要条件。"},{t="剃刀鳄的赏金",b="在湿地，寻找可靠且未受污染的食物变得越来越困难。为了满足“低音喙”，霍文将目标对准了位于东北方向恐龙岭和西北方向盐沫沼泽中的本地剃刀鳄迅猛龙的巢穴。迅猛龙蛋以拥有如侏儒脑袋般大小的蛋黄而闻名，能为“低音喙”在面对该地区危险之前提供所需的充足且未受污染的食物。"}},faq={{q="霍文·羽言是谁？",a="霍文·羽言是一位在湿地照料一只名叫“低音喙”的狮鹫的矮人驯兽师。他派遣冒险者去收集新鲜的迅猛龙蛋来喂养他的伙伴，然后才会实施他的计划。",al={"霍文·羽言是谁","霍文·羽言 湿地","任务发布者 trying times"}},{q="“低音喙”是谁？",a="“低音喙”是霍文·羽言的狮鹫。据霍文所说，它在饥饿时会变得焦躁不安，甚至极度危险，如果不让它吃饱，骑乘或使用它都是不安全的。",al={"谁是低音喙","狮鹫低音喙","霍文的狮鹫"}},{q="霍文为什么需要迅猛龙蛋？",a="霍文专门寻找剃刀鳄迅猛龙蛋，是因为在湿地很难找到未受污染的食物，而这些蛋能提供巨大的、营养丰富的蛋黄，足以满足“低音喙”那惊人的胃口。",al={"为什么要迅猛龙蛋","为什么要喂狮鹫吃蛋","这些蛋是做什么用的"}},{q="在哪里可以找到剃刀鳄迅猛龙？",a="剃刀鳄迅猛龙栖息在湿地东北部的恐龙岭和西北部的盐沫沼泽。冒险者必须亲自深入这些巢穴以获取完好的蛋。",al={"剃刀鳄迅猛龙在哪里","去哪找剃刀鳄蛋","湿地迅猛龙位置"}},{q="为什么这些蛋必须完美无缺？",a="霍文坚持要求蛋不能有任何裂缝或瑕疵，以确保食物完全新鲜且未受污染，这样才能让“低音喙”保持健康和满足，而不是喂给它变质的残渣。",al={"为什么蛋必须完美","破碎的蛋 trying times"}},{q="霍文打算带“低音喙”做什么？",a="霍文提到他有一个涉及“低音喙”的更宏大的计划，但他坚持在狮鹫吃饱并冷静下来，足以在区域威胁中安全飞行之前，不对外透露细节。",al={"霍文的计划是什么","霍文和低音喙打算做什么"}}},fp="12,240,26.401.0,19.405.0,25.204.0,16.178.0,32.200.0,36.176.0,35.181.0,43.204.0"}
P.entries["quest:98247"] = {n="Shipping Label",s="Shipping Label是一个贴在艾泽拉斯贸易局所属补给箱上的已寻回货运标记。它指示信使前往位于赤脊山三角路口的贸易枢纽，并向旅行者介绍了该组织旗下的独立运输商网络。",h="Shipping Label是一个贴在艾泽拉斯贸易局所属补给箱上的已寻回货运标记。它指示信使前往位于赤脊山三角路口的贸易枢纽，并向旅行者介绍了该组织旗下的独立运输商网络。",kw={"艾泽拉斯贸易局","补给箱","货物配送","商人恩惠","赤脊山","shipping label","三角路口"},ang={["faction:Alliance"]="艾泽拉斯贸易局通过三角路口开展业务，依靠南方的联盟领地里的流动冒险者来回收流失货物并保障陆路运输路线的安全。"},sec={{t="流失的货物",b="这张破损的Shipping Label被发现贴在装满货物的补给箱上，标记着属于艾泽拉斯贸易局的货物。尽管预定的目的地和收件人信息已被撕毁，但上面清楚地指示发现货物的人将其送回或向该局位于赤脊山的贸易前哨报告。在正式文本旁边，有一张简陋的地图，勾勒出了通往三角路口交叉点的道路。"},{t="贸易局的枢纽",b="在三角路口的交叉点，艾泽拉斯贸易局的代表会积极招募旅行者成为独立信使。贸易局并不要求运输商签订严格的商业合同，而是运营着一个非正式网络，冒险者可以通过找回丢失的货物并完成沿途遗弃的配送任务来获得“商人恩惠”作为报酬。"}},faq={{q="什么是Shipping Label？",a="Shipping Label是一份在已寻回补给箱侧面发现的破损单据。虽然收件人的名字不见了，但标签上明确了这些货物属于艾泽拉斯贸易局，并指示发现它的人向他们位于三角路口的枢纽报告。",al={"什么是shipping label","shipping label任务","破损的shipping label"}},{q="什么是艾泽拉斯贸易局？",a="艾泽拉斯贸易局是一个负责组织该地区物流、贸易和货运的企业。他们维护着当地的贸易枢纽，用于回收丢失的货物，并雇佣无需长期合同的流动信使。",al={"谁是aca","艾泽拉斯贸易局","什么是艾泽拉斯贸易局"}},{q="艾泽拉斯贸易局的贸易枢纽位于哪里？",a="艾泽拉斯贸易局的贸易枢纽位于赤脊山的三角路口，战略性地坐落在连接艾尔文森林、暮色森林和湖畔镇的道路上。",al={"aca贸易枢纽在哪里","三角路口枢纽","在哪里提交shipping label"}},{q="什么是商人恩惠？",a="商人恩惠是一种由艾泽拉斯贸易局发给独立信使的专用代币或信用额。分支机构成员可以用它购买贸易局前哨提供的各种贸易商品和物流服务。",al={"什么是商人恩惠","商人恩惠","aca报酬"}},{q="如何成为艾泽拉斯贸易局的关联成员？",a="成为关联成员不需要正式合同、文书工作或长期承诺。艾泽拉斯贸易局仅要求信使协助归还或完成在世界各地发现的遗失货物。",al={"如何成为aca关联成员","加入aca","我需要合同吗"}},{q="交付标签后补给箱会怎样？",a="标签本身会促使贸易枢纽的代表询问其所附着的实体补给箱的情况，因为归还空置或已完成运输的货运容器对他们的贸易运作至关重要。",al={"补给箱会怎样","丢失的补给箱","他们需要补给箱吗"}}},fp="14,287,16.447.0,28.387.0,27.270.0,39.220.0,58.199.0,25.225.0,65.232.0,53.203.0"}
P.entries["quest:98248"] = {n="Shipping Label",s="在一个重新补给过的货运箱上发现了一份撕毁的派送单，上面指引信使前往贫瘠之地的一个区域商队枢纽。杜隆塔尔补给后勤部依赖四处游历的旅行者来寻回丢失的板条箱，并将文书送回他们位于十字路口以西的哨所。完成送达任务能够维护卡利姆多中部至关重要的供应链和商业贸易。",h="在一个重新补给过的货运箱上发现了一份撕毁的派送单，上面指引信使前往贫瘠之地的一个区域商队枢纽。杜隆塔尔补给后勤部依赖四处游历的旅行者来寻回丢失的板条箱，并将文书送回他们位于十字路口以西的哨所。完成送达任务能够维护卡利姆多...",kw={"板条箱","十字路口","杜隆塔尔补给后勤部","shipping label","贫瘠之地","贸易哨所"},ang={["faction:Horde"]="穿越贫瘠之地的部落冒险者经常会遇到杜隆塔尔补给后勤部的行动，帮助维护杜隆塔尔与卡利姆多中部之间至关重要的商业和供应线。"},sec={{t="一份迷失的派送单",b="这份撕毁的文件贴在一个刚补给过的货运板条箱上，上面写着杜隆塔尔补给后勤部的物流说明。虽然收件人的名字已经因为旅途磨损而难以辨认，但来源标题清晰地标明了这家在部落领地内运营的货运公司。文字旁边的一张粗略绘制的路线图引导着信使直奔该组织位于中部平原的集结地。"},{t="边境贸易",b="这则告示邀请旅行者将流失的集装箱、损坏的货物或打捞证明运送到他们位于十字路口正西方的贸易哨所。杜隆塔尔补给后勤部在贫瘠之地的严酷环境中运作，非常依赖独立的运输者和路人来寻回散落的货物，并向那些协助保持区域供应渠道顺畅的人提供报酬。"}},faq={{q="什么是Shipping Label？",a="这是一份贴在已补给好的板条箱上的文件，上面详细列出了杜隆塔尔补给后勤部的退还说明，指引丢失或空置的集装箱送回他们靠近十字路口的哨所。",al={"什么是shipping label","shipping label任务","撕毁的shipping label"}},{q="这个标签应该送到哪里？",a="标签指示信使将其交给驻扎在杜隆塔尔补给后勤部贸易枢纽的人员，该枢纽位于贫瘠之地，十字路口的正西方。",al={"shipping label应该送到哪里","谁需要shipping label","shipping label上交"}},{q="什么是杜隆塔尔补给后勤部？",a="杜隆塔尔补给后勤部是一家在杜隆塔尔和贫瘠之地运营的商业货运组织，负责部落领地内的货物运输、板条箱回收和物流支持。",al={"什么是杜隆塔尔补给后勤部","杜隆塔尔补给哨所"}},{q="这批货物最初的收件人是谁？",a="预期收件人的名字已经从标签上完全撕掉了，板条箱上只留下了退还说明和该公司的来源信息。",al={"板条箱原本是给谁的","板条箱收件人"}},{q="杜隆塔尔补给后勤部的贸易哨所在哪里？",a="根据标签上标注的指示和粗略地图，该哨所位于贫瘠之地十字路口定居点的正西方。",al={"贸易哨所在哪里","杜隆塔尔补给点十字路口位置"}},{q="杜隆塔尔补给后勤部会为归还板条箱的旅行者提供补偿吗？",a="是的，印刷的告示明确承诺，信使在将损坏的货物、标签或空板条箱送回枢纽后，其花费的时间和精力将得到补偿。",al={"他们会为归还的板条箱付费吗","杜隆塔尔补给补偿"}}},fp="14,364,18.424.0,17.415.0,27.191.0,36.161.0,37.198.0,45.164.0,64.158.0,76.184.0"}
P.entries["quest:98283"] = {n="Carnage",s="“屠戮者”是湿地的一项任务，由绿带草地的绿色守卫者雷希耶尔委派。雷希耶尔请求旅行者引诱并杀死屠戮者，这是一头疯狂的利刃爪迅猛龙首领，其因瘟疫引发的狂乱扰乱了该地区的自然秩序。",h="“屠戮者”是湿地的一项任务，由绿带草地的绿色守卫者雷希耶尔委派。雷希耶尔请求旅行者引诱并杀死屠戮者，这是一头疯狂的利刃爪迅猛龙首领，其因瘟疫引发的狂乱扰乱了该地区的自然秩序。",kw={"屠戮者","洛克莫丹","恐龙岭","利刃爪","绿色守卫者雷希耶尔","烂爪","绿带草地","湿地"},ang={["class:Druid"]="德鲁伊们对于湿地破碎的自然平衡与雷希耶尔有着同样的悲痛，在那里，疾病已将像屠戮者这样的掠食者扭曲成了毫无理智的恐怖存在。",["class:Hunter"]="猎人们明白，当一个掠食者首领因瘟疫引发的愤怒而丧失其本能，并开始捕食同类时，会构成怎样的危险。"},sec={{t="破碎的平衡",b="在湿地的沼泽中，自然秩序已开始破裂。利刃爪迅猛龙曾经扮演着重要的生态角色，防止荒野过度生长。现在，它们的种群等级被其可怕的首领、那头只被称为“屠戮者”的嗜血野兽所打破。屠戮者非但没有引导种群，反而给自己的同类带来了恐惧，它肆意屠杀，使当地的生态系统陷入混乱。"},{t="引诱首领",b="守护着绿带草地的绿色守卫者雷希耶尔认为，屠戮者已经屈服于依然困扰着该地区的邪恶腐化。为了将这头狂乱的野兽从藏身处引出，旅行者必须收集从洛克莫丹游荡下来的患病烂爪熊的恶性内脏。将这些腐肉放置在恐龙岭下方屠戮者的洞穴巢穴中，会激怒这只怪物发起攻击，从而让旅行者结束它的痛苦。"}},faq={{q="谁是屠戮者？",a="屠戮者是湿地利刃爪迅猛龙群中可怕的首领。这头野兽没有正常地领导它的族群，而是被疾病逼疯，所过之处只留下屠杀，甚至连它的迅猛龙同类都感到恐惧。",al={"谁是屠戮者","屠戮者迅猛龙","什么是屠戮者"}},{q="谁发布了“屠戮者”任务？",a="该任务由绿色守卫者雷希耶尔发布，他是一位驻扎在湿地绿带草地的守卫者，致力于恢复该地区被腐化的自然平衡。",al={"谁发布屠戮者任务","在哪里上交屠戮者任务","雷希耶尔湿地"}},{q="为什么要消灭屠戮者？",a="雷希耶尔寻求屠戮者的死亡，因为这头野兽已被一种非自然的疾病逼疯，破坏了利刃爪迅猛龙的自然等级制度，并摧毁了当地的生态。",al={"为什么要杀死屠戮者","为什么雷希耶尔想让屠戮者死"}},{q="如何引诱出屠戮者？",a="屠戮者是通过用在东北方恐龙岭下方发现的患病熊的恶性肉块和内脏作为诱饵，在其洞穴巢穴中引出的。",al={"如何召唤屠戮者","如何引诱屠戮者","屠戮者的洞穴在哪里"}},{q="雷希耶尔提到的患病熊是什么？",a="这些患病的熊是从洛克莫丹迁移下来的烂爪熊。在挥之不去的腐化影响下变得疯狂，它们被污染的肉体成为了引诱那只疯狂迅猛龙首领的有力诱饵。",al={"什么是烂爪熊","患病的熊来自哪里"}},{q="利刃爪迅猛龙最初在湿地扮演什么角色？",a="在正常情况下，利刃爪迅猛龙通过防止自然动植物过度生长来维持湿地的生态平衡。屠戮者的疯狂破坏了这一至关重要的角色。",al={"利刃爪扮演什么角色","为什么迅猛龙对湿地很重要"}}},fp="7,243,16.445.0,16.443.0,15.226.0,28.162.0,30.185.0,25.145.0,49.186.0,68.200.0"}
P.entries["quest:98286"] = {n="Camping 101: Enchanting",s="《露营指南：附魔》指引奥术修行者前往申达尔村，学习如何制造专业的野外装备。通过与纳萨兰娜·风歌交谈，经验丰富的附魔师可以学会制作一把附魔的鲁特琴，在营火旁娱乐同伴并振奋他们的士气。",h="《露营指南：附魔》指引奥术修行者前往申达尔村，学习如何制造专业的野外装备。通过与纳萨兰娜·风歌交谈，经验丰富的附魔师可以学会制作一把附魔的鲁特琴，在营火旁娱乐同伴并振奋他们的士气。",kw={"营火","露营","露营指南","附魔的鲁特琴","附魔","鲁特琴","纳萨兰娜·风歌","申达尔村"},sec={{t="炉火的慰藉",b="旅途生活需要的不仅仅是锋利的刀刃和口粮；休息和士气对于维持长期的远征至关重要。附魔师为营地生活带来了独特的魔法慰藉，利用他们对周围奥术的精通，在休息时间为旅行者提供精神支持。在艾泽拉斯各地的荒野营地中，附魔师的存在确保了疲惫的冒险者在重返险峻的道路之前，能够恢复体力和精神。"},{t="申达尔之歌",b="想要学习营地制造的精妙魔法，立志成为附魔师的人会被指引前往申达尔村。在那里，纳萨兰娜·风歌会指导合格的施法者制作附魔的鲁特琴。工匠必须首先证明自己在附魔方面的专注和熟练程度，纳萨兰娜才会分享如何制造一种能在星空下编织治愈旋律的乐器的秘密。"}},faq={{q="纳萨兰娜·风歌是谁？",a="纳萨兰娜·风歌是一位居住在申达尔村的导师。她教导熟练的从业者如何为野外营地制作特殊的专业物品，特别是为证明了自己工艺水平的附魔师制作附魔的鲁特琴。",al={"谁教授附魔的鲁特琴","谁是纳萨兰娜·风歌","纳萨兰娜·风歌在哪里"}},{q="申达尔村在哪里？",a="申达尔村是纳萨兰娜·风歌居住的定居点。在掌握了核心技能后，想要学习如何制作附魔的鲁特琴等露营装备的冒险者都会前往那里。",al={"申达尔村在哪里","如何找到申达尔村"}},{q="什么是附魔的鲁特琴？",a="附魔的鲁特琴是由附魔师制作的一种魔法露营乐器。它能在营火旁的休息时间提供娱乐和恢复士气，帮助旅行者调整心态，为面对前方野外的严酷挑战做好准备。",al={"附魔的鲁特琴有什么用","为什么要制作附魔的鲁特琴","露营鲁特琴"}},{q="学习配方有什么要求？",a="在纳萨兰娜·风歌教你如何制作附魔的鲁特琴之前，你必须先证明自己在附魔这一魔法艺术上的造诣。只有经验丰富的从业者才被信任能制作这些营地功能性附魔物品。",al={"露营指南附魔要求","什么时候可以学习附魔的鲁特琴"}},{q="为什么附魔师在野外营地很有价值？",a="附魔师为偏远的营地带来了微妙的实用性和魔法慰藉，因为普通的补给往往难以满足需求。通过为普通的营地工具注入魔法强化，他们帮助冒险者恢复精力、保持娱乐，并为旅途中可能遇到的突发危险做好准备。",al={"为什么露营者需要附魔师","附魔师露营福利"}},{q="其他专业可以制作露营物品吗？",a="是的，各行各业的工匠和采集者都会学习建造专用的露营工具。对于附魔师来说，这种专业的工艺表现为由申达尔村的纳萨兰娜·风歌教授的附魔的鲁特琴。",al={"还有其他露营物品吗","其他专业的营地制作"}}},fp="23,296,22.461.0,20.402.0,28.252.0,26.213.0,26.250.0,46.233.0,52.266.0,42.228.0"}
P.entries["quest:98293"] = {n="Forced Disarmament",s="Forced Disarmament是湿地的一项联盟任务，要求冒险者从龙喉营地的龙喉氏族手中夺取武器储藏。通过收集三十捆军械，玩家可以阻止这些敌对兽人武装更多士兵用于未来的突袭。缴获的装备会被送往米奈希尔城堡的斯托菲队长处，以保卫该地区至关重要的港口。",h="Forced...",kw={"斯托菲队长","龙喉军械","龙喉氏族","龙喉营地","forced disarmament","米奈希尔港","米奈希尔城堡","湿地"},ang={["faction:Alliance"]="联盟军队将米奈希尔港视为跨越无尽之海的关键生命线，因此解除附近敌对氏族的武装是一项紧急的战略必要。",["race:Dwarf"]="来自铁炉堡的矮人守军负责维持米奈希尔城堡的驻军，致力于保卫卡兹莫丹的边界，防止陷于沼泽中的旧日敌人的侵袭。",["race:Orc"]="龙喉氏族代表了旧部落的一个四分五裂且执迷不悟的残余势力，他们暴力的好战行径使他们与卡利姆多的新部落领导层彻底隔绝。"},sec={{t="沼泽中的军械库",b="在湿地的沼泽地带，敌对的龙喉氏族开始在龙喉营地内囤积惊人数量的武器。如果不加遏制，这些物资将使这些叛变兽人能够武装起一波波新战士，并对邻近定居点发动毁灭性的袭击。解除他们营地的武装是对其后勤能力的直接打击，可以在他们的战团完成动员并走上战场之前，挫败任何预谋的攻势。"},{t="守卫沿海港口",b="米奈希尔港是连接卡兹莫丹、暴风城与海洋的主要门户，因此附近任何军事集结都是严重的威胁。斯托菲队长在米奈希尔城堡协调防御措施，密切监视着入侵城镇的敌对氏族和野兽。回收三十套龙喉军械不仅剥夺了兽人的基本军需品，还能为矮人驻军提供关于敌人准备情况的关键情报。"}},faq={{q="斯托菲队长是谁？",a="斯托菲队长是一位驻扎在米奈希尔城堡的矮人军官，负责保卫米奈希尔港和周边的湿地。面对来自敌对野兽、黑铁矮人破坏者以及龙喉氏族的持续压力，斯托菲积极指挥士兵和冒险者，在港口关键的补给线和港口设施被攻占之前压制附近的威胁。",al={"斯托菲","斯托菲是谁","米奈希尔城堡队长"}},{q="为什么需要解除龙喉氏族的武装？",a="龙喉氏族正在他们的营地中积极囤积武器，以装备新的战斗人员。如果任由他们不受阻挠地囤积军需品，他们的战团可能会压垮当地的联盟防御力量，并危及米奈希尔港。夺取三十捆武器直接阻碍了他们的后勤准备，并阻止更多的兽人士兵走上战场。",al={"为什么要夺取龙喉武器","龙喉军械的目的","解除龙喉武装"}},{q="龙喉营地位于哪里？",a="龙喉营地是龙喉兽人在湿地建立的一处据点，位于米奈希尔港外向东延伸的山脉方向。该氏族利用这一隐蔽的前哨站来集结兵力、储存武器，并对沼泽中的旅行者发动袭击。冒险者必须深入营地中心，回收他们囤积的武器。",al={"龙喉营地位置","龙喉营地在哪里","湿地龙喉营地"}},{q="什么是龙喉军械？",a="龙喉军械是龙喉氏族为了供给战士而锻造或掠夺的战斗装备、刀剑和补给缓存。这些武器代表了该氏族在当地的即时军事实力。斯托菲队长要求没收三十捆这些军需品，并带回米奈希尔城堡进行评估和处理。",al={"龙喉武器","什么是军械","龙喉装备"}},{q="龙喉氏族在25 ADP时是部落的一部分吗？",a="不是，湿地的龙喉氏族是一个独立的敌对派系，不听从萨尔酋长的号令。在第二次战争后，这些兽人依然忠于他们旧有的行事方式，对联盟怀有深仇大恨，并拒绝任何和平提议。因此，联盟守军和独立的旅行者都将他们视为致命的对手。",al={"龙喉氏族属于部落吗","龙喉氏族派系","龙喉萨尔"}},{q="为什么米奈希尔城堡会关注龙喉氏族？",a="米奈希尔城堡是保卫米奈希尔港的行政和军事要塞，而米奈希尔港是联盟在卡兹莫丹的主要海上枢纽。由于港口周边的湿地饱受沼泽野兽和好战兽人的侵扰，斯托菲队长不能允许像龙喉营地这样重装防守的据点在靠近王国码头和贸易路线的地方壮大。",al={"米奈希尔城堡龙喉威胁","为什么斯托菲在意","米奈希尔港防御"}}},fp="18,389,24.469.0,25.479.0,25.398.0,41.365.0,35.362.0,29.356.0,50.362.0,50.382.0"}
P.entries["quest:98298"] = {n="Arugal's Folly",s="Arugal's Folly 是银松森林中的一个被遗忘者任务，达拉尔·道恩维沃尔在此调查格雷迈恩之墙附近徘徊的狼人的真正起源。通过分析收集到的狼人残骸，达拉尔试图证明大法师阿鲁高只是一个冒牌货，他仅仅是束缚住了这些生物，而非召唤了他们的诅咒。",h="Arugal's Folly...",kw={"阿鲁高","arugal's folly","达拉尔·道恩维沃尔","格雷迈恩之墙","银松森林","瑟伯切尔","狼人碎片","狼人诅咒"},ang={["class:Mage"]="奥术修行者们可以欣赏达拉尔对阿鲁高所谓魔法诅咒的分析性解构，从而分辨出束缚附魔与传染性苦难之间的区别。",["faction:Horde"]="协助达拉尔·道恩维沃尔的部落冒险者们，帮助保护了银松森林免受猖獗的野蛮掠食者以及正屈服于苦难的邻近人类定居点的侵害。",["race:Undead"]="对于驻扎在瑟伯切尔的被遗忘者来说，理清银松森林中狼人爆发的本质，对于保护洛丹伦免受无法控制的野蛮威胁至关重要。"},sec={{t="揭穿大法师",b="驻扎在银松森林瑟伯切尔的被遗忘者法师达拉尔·道恩维沃尔，试图拆穿他竞争对手大法师阿鲁高的神秘面纱。在检查了附魔枷锁后，达拉尔断定阿鲁高缺乏足以显现或创造出困扰该地区的狼群的原始力量。相反，阿鲁高只是掌握了一些能够暂时束缚住这些野兽的低级附魔，这使得狼人野性传染的真正机制和起源依然是个未解之谜。"},{t="野兽入侵",b="为了寻求实证，达拉尔派遣冒险者前往南方的格雷迈恩之墙那令人生畏的防御工事。在周边的荒野中，凶猛的狼人已经开始攻击并感染附近的人类居民。通过斩杀这些贪婪的生物并取回解剖组织样本，调查员们为达拉尔提供了所需的直接物理标本，以分析这种苦难的生物学和魔法真相。"},{t="苦涩的辩解",b="在检查了收获的狼人残骸后，达拉尔兴高采烈地宣布他在学术声誉上战胜了阿鲁高，证实了这位大法师与苦难的起源毫无关系。然而，这一揭示对被遗忘者来说却带来了一个严峻的后果：如果阿鲁高从未发明过这种诅咒，那么他所制定的所谓补救措施和对策就完全是无用的，这使得狼人爆发的真正谜团依然完全未被解开。"}},faq={{q="谁发布了任务 Arugal's Folly？",a="该任务由达拉尔·道恩维沃尔发布并完成，他是一位驻扎在银松森林瑟伯切尔的奥术研究员兼被遗忘者法师。",al={"谁发布 arugal's folly","在哪里交 arugal's folly","arugal's folly 任务发布者"}},{q="为什么达拉尔·道恩维沃尔认为阿鲁高是个骗子？",a="达拉尔·道恩维沃尔断定大法师阿鲁高是个傲慢的骗子。达拉尔认为，阿鲁高仅仅拥有勉强能暂时束缚住狼人的魔法能力，而非创造或引发它们，从而将所谓的“阿鲁高的诅咒”揭露为一场骗局。",al={"达拉尔如何看待阿鲁高","阿鲁高是否制造了狼人","阿鲁高是骗子"}},{q="在哪里可以找到给达拉尔的狼人碎片？",a="为了完成任务，冒险者们需要向南穿过银松森林前往格雷迈恩之墙，凶猛的狼人就在当地人类定居点附近徘徊。击杀这些野兽即可获得达拉尔调查所需的狼人碎片。",al={"狼人碎片在哪里","格雷迈恩之墙狼人","arugal's folly 去哪里"}},{q="达拉尔找到了治愈狼人诅咒的方法吗？",a="此处并未发现补救方法。由于达拉尔发现阿鲁高最初并未创造出狼人苦难，因此阿鲁高调制的任何补救措施或反制法术都毫无用处，这使得被遗忘者不得不去别处寻找真正的解决方案。",al={"狼人诅咒能治愈吗","阿鲁高的补救措施有效吗","是否有狼人解药"}},{q="狼人的苦难是如何在格雷迈恩之墙附近传播的？",a="达拉尔指出，狼人的苦难似乎并非通过阿鲁高施展的某种宏大的奥术仪式或法术，而是通过身体接触和撕咬直接传播给格雷迈恩之墙附近的人类居民。",al={"诅咒如何传播","狼人传播给人类","谁正在被感染"}},{q="达拉尔在检查了狼人碎片后得出了什么结论？",a="检查被击杀狼人的解剖碎片向达拉尔证明了它们的诅咒与阿鲁高的法术毫无关系。虽然这证实了他竞争对手的魔法无能，但也证实了狼人诅咒仍然是一个活跃的、未被解释的威胁，且没有有效的解药。",al={"达拉尔从碎片中学到了什么","arugal's folly 结论","arugal's folly 剧情揭示"}}},fp="14,316,21.476.0,21.440.0,20.435.1,35.143.0,50.256.0,44.244.0,44.255.0,62.233.0,58.282.0"}
P.entries["quest:98299"] = {n="Stop the Spread",s="“阻止蔓延”是银松森林的一项任务，内容是遏制与大法师阿鲁高有关的狼人诅咒。当研究人员寻求阻止该痛苦的方法时，针对格雷迈恩之墙附近活着的人类难民的先发制人措施已被下达，以防止他们变成阿鲁高的仆从。",h="“阻止蔓延”是银松森林的一项任务，内容是遏制与大法师阿鲁高有关的狼人诅咒。当研究人员寻求阻止该痛苦的方法时，针对格雷迈恩之墙附近活着的人类难民的先发制人措施已被下达，以防止他们变成阿鲁高的仆从。",kw={"阿鲁高","诅咒","被遗忘者","格雷迈恩之墙","难民","银松森林","天降","stop the spread","狼人"},ang={["race:Human"]="聚集在紧闭的格雷迈恩之墙处的未感染人类难民，在被遗忘者研究人员看来是阿鲁高扩散诅咒的主要载体。",["race:Skyborne"]="天降的冒险者在执行格雷迈恩之墙附近的严酷遏制命令时，被直接警告要避免被咬伤。",["race:Undead"]="被遗忘者似乎对狼人痛苦具有独特的免疫力，这使得遏制行动在亡灵部队没有感染风险的情况下变得可行。"},sec={{t="银松森林的痛苦",b="在银松森林，狼人的祸害在叛逃的大法师阿鲁高的手中蔓延。虽然这种野性疾病传播背后的具体方法和机制在很大程度上仍然未知，但它对该领土构成的危险是不可否认的。研究人员正在积极努力了解这种魔法的本质，但他们目前的重点是防止阿鲁高聚集一支无法阻挡的野蛮追随者大军。"},{t="在格雷迈恩之墙的遏制",b="被遗忘者调查人员观察到，他们的亡灵生理结构使他们对狼人感染免疫。然而，活着的人类并没有这种天然的防御能力。在南部的边界，一大群人类难民绝望地聚集在紧闭的格雷迈恩之墙大门周围。由于担心这些毫无防备的幸存者会被咬伤并转化为阿鲁高的忠实奴隶，先发制人且残酷的遏制命令已被下达，要求在痛苦折磨他们之前清除这些聚集的人群。"}},faq={{q="任务“阻止蔓延”是关于什么的？",a="“阻止蔓延”是一项侧重于遏制蹂躏银松森林的狼人诅咒的任务。为了防止大法师阿鲁高获得新的仆从，部队被派遣去消灭格雷迈恩之墙附近的人类难民，以免他们屈服于这种痛苦。",al={"什么是阻止蔓延","阻止蔓延任务背景"}},{q="谁应该为银松森林的狼人负责？",a="大法师阿鲁高被认为应对银松森林内狼人的存在负责，无论是通过他蓄意的阴谋还是他魔法的不可预见后果。他日益壮大的狼群威胁着整个地区。",al={"谁传播了狼人诅咒","阿鲁高狼人关联"}},{q="被遗忘者会感染狼人诅咒吗？",a="根据当地被遗忘者的研究，狼人诅咒无法感染亡灵。这种免疫力使被遗忘者特工能够直面威胁，而不必担心变成阿鲁高的野兽仆从。",al={"被遗忘者能成为狼人吗","亡灵对狼人免疫吗"}},{q="为什么要在格雷迈恩之墙针对人类难民？",a="一大群人类难民聚集在紧闭的格雷迈恩之墙外。因为活着的人类容易受到阿鲁高诅咒的影响，他们被视为壮大狼人队伍的紧迫威胁。",al={"为什么杀害难民","格雷迈恩之墙难民"}},{q="狼人痛苦是如何传播的？",a="虽然已知狼人诅咒可以通过咬伤传播，但其传播的确切魔法和生物学机制仍处于银松森林研究人员的积极调查中。",al={"狼人如何传播","狼人诅咒传播"}},{q="有办法阻止或治愈狼人诅咒吗？",a="目前，尚无已知的治疗狼人痛苦的方法。研究人员正在试图发现一种治疗方法来阻止这种诅咒，但他们的当务之急仍然是积极的遏制。",al={"狼人诅咒能治愈吗","狼人疗法"}}},fp="15,307,25.434.0,23.511.1,40.259.0,48.223.0,40.203.0,59.218.0,38.201.0,48.189.0"}
P.entries["quest:983"] = {n="传声盒827号",s="嗡鸣箱827是侏儒维兹班恩·曲针在黑海岸沿岸建造的一系列实验性通讯中继站中的第一个。这些奇特的机械装置经常发生故障，依靠一种古怪的设计来运作，即利用当地野生动物的身体部位进行现场维修。修复这台沉默的机器可以让维兹班恩直接从奥伯丁测试他的远程语音网络。",h="嗡鸣箱827是侏儒维兹班恩·曲针在黑海岸沿岸建造的一系列实验性通讯中继站中的第一个。这些奇特的机械装置经常发生故障，依靠一种古怪的设计来运作，即利用当地野生动物的身体部位进行现场维修。修复这台沉默的机器可以让维兹班恩直接...",kw={"奥伯丁","嗡鸣箱827","蟹腿","黑海岸","侏儒工程学","礁蟹","潮滩蟹","维兹班恩·曲针"},ang={["profession:Engineering"]="使用有机几丁质和节肢动物的肢体来代替锻造的黄铜齿轮是典型的侏儒式即兴创作，牺牲了耐用性，换取了容易从当地获取的材料。",["race:Gnome"]="维兹班恩的装置代表了经典的侏儒式雄心，试图将技术连接带到一个从未见过电话或无线电的古老、狂野的土地上。",["race:NightElf"]="这些叮当作响、冒着烟的嗡鸣箱是卡利姆多神圣而阴郁的海岸上的一道诡异的风景，尽管奥伯丁的暗夜精灵们容忍了这位技师的实验。"},sec={{t="古老海岸上的侏儒创新",b="在造访奥伯丁期间，古怪的侏儒工程师维兹班恩·曲针试图用一系列被称为“嗡鸣箱”的远程声学中继站，来跨越狂野海岸间的漫长距离。这些装置上布满了操纵杆，专为远距离语音传输而设计，与黑海岸古老的废墟和阴郁的森林形成了鲜明的对比。然而，就像许多雄心勃勃的侏儒发明一样，它们长期处于不稳定状态，需要近乎不断的维护才能让内部齿轮正常运转。"},{t="生态维护",b="维兹班恩没有选择将精炼的铁齿轮和铜销运过荒野，而是采取了一种非传统的解决方案：他将每个嗡鸣箱都设计为使用从附近原生动物身上采集的部件进行维护。嗡鸣箱827位于奥伯丁以南的多雾海岸线上，其工程设计是利用当地潮滩蟹和礁蟹坚固的节肢腿来运作。将蟹腿放入接收料斗中，机器就会自动组装并恢复活力，通过扬声器广播维兹班恩遥远的声音。"}},faq={{q="什么是嗡鸣箱？",a="嗡鸣箱是一种由侏儒维兹班恩·曲针发明的远程语音通讯机器。它配备了操纵杆和内部机械，旨在将声音跨越黑海岸未经开发的广阔区域进行传输，使人们能够在数英里的距离外进行交谈。",al={"嗡鸣箱的作用","嗡鸣箱的目的","黑海岸侏儒装置"}},{q="为什么金属机器需要螃蟹腿来运行？",a="维兹班恩特意将每个嗡鸣箱设计为使用来自周围野生动物的有机部件作为临时替代零件。通过将嗡鸣箱827放置在蟹类栖息的海滩附近，他确保了旅行者可以使用几丁质的肢体代替稀有的机械金属进行紧急机械维修。",al={"为什么用蟹腿","蟹腿修理","为什么喂它腿"}},{q="嗡鸣箱827位于何处？",a="嗡鸣箱827位于黑海岸的海岸线上，就在奥伯丁沿海定居点以南不远处。",al={"嗡鸣箱827位置","嗡鸣箱827在哪里","寻找嗡鸣箱827"}},{q="维兹班恩·曲针是谁？",a="维兹班恩·曲针是一位住在奥伯丁旅店楼上的侏儒技师。他雄心勃勃、富有进取心，尽管他的原型机不断发生故障，但他仍试图在黑海岸建立一个互联的通讯网络。",al={"维兹班恩·曲针","谁制造了嗡鸣箱","奥伯丁侏儒"}},{q="我可以在哪里找到用于维修的蟹腿？",a="蟹腿可以从奥伯丁以南黑海岸海滩的沙地和浅滩上爬行的侏儒潮滩蟹和幼年礁蟹身上收集到。",al={"蟹腿位置","如何获得蟹腿","侏儒潮滩蟹"}},{q="修复嗡鸣箱827后会发生什么？",a="一旦将蟹腿喂入料斗，机器就会将其研磨到位，嗡嗡作响恢复活力，并转播来自奥伯丁的维兹班恩的声音。对成功感到满意的他，会立即要求你前往更远的海岸，去修理链条中的下一个装置——嗡鸣箱411。",al={"嗡鸣箱827之后","嗡鸣箱后续任务","嗡鸣箱827完成"}}},fx={aa80bf26={q="维兹班恩·曲针为什么要修理827号蜂鸣器？",a="维兹班恩·曲针正在测试他最新的发明：一套覆盖黑海岸的实验性通信网络，让人们能够远距离交谈。遗憾的是，他的蜂鸣器需要不断维护，而且经常发生故障。让827号蜂鸣器恢复运转，是证明他的网络确实有效的第一步。",al={"维兹班恩·曲针的动机","为什么修理827号蜂鸣器","维兹班恩为什么要完成这件事"}},["2c1df07a"]={q="蟹腿有什么用？",a="维兹班恩设计的每台蜂鸣器都依赖从附近本土野生动物身上采集的零件。827号蜂鸣器需要六条蟹腿，用来替换固定装置中磨损或损坏的机械部件。装入蟹腿后，装置内部的齿轮会将它们碾磨并卡入适当位置，从而恢复供电和传输功能。",al={"蟹腿有什么用","蟹腿与蜂鸣器","为什么要蟹腿"}}},fp="11,384,36.502.0,22.539.0,18.258.0,47.302.0,29.121.0,27.256.0,45.164.0,42.278.1"}
P.entries["quest:98319"] = {n="Secure the Mountain",s="“Secure the Mountain”是联盟的一个任务，旨在解决丹莫罗的灰色洞穴中温迪戈突然激增并泛滥成灾的问题。冒险者们需要进入被怪物占据的洞穴，找到一位鲁莽的矮人侦察兵科尼利厄斯，并为白须取回一份重要的报告。",h="“Secure the Mountain”是联盟的一个任务，旨在解决丹莫罗的灰色洞穴中温迪戈突然激增并泛滥成灾的问题。冒险者们需要进入被怪物占据的洞穴，找到一位鲁莽的矮人侦察兵科尼利厄斯，并为白须取回一份重要的报告。",kw={"科尼利厄斯","丹莫罗","灰色洞穴","登山者","secure the mountain","巨魔","温迪戈","白须"},ang={["faction:Alliance"]="确保白须收到情报报告，对于联盟军队维持边境安全以抵御本土山地威胁至关重要。",["race:Dwarf"]="夺回像灰色洞穴这样的洞穴，可以保护矮人登山者和旅行者免受那些侵占丹莫罗道路的温迪戈的伤害。"},sec={{t="泛滥的洞穴",b="驻守在冰冷山坡上的矮人侦察兵们面临着双重威胁。除了时刻存在的霜鬃巨魔威胁外，当地的温迪戈也开始疯狂繁衍，它们放弃了原本孤独的巢穴，成群结队地涌入北边的灰色洞穴。这些野蛮的野兽使山路对于巡逻队和信使来说变得极其危险。"},{t="鲁莽的英勇",b="一位名叫科尼利厄斯的侦察兵一头冲进了灰色洞穴，试图取回一份给白须的重要报告。他这种冲动的英勇行为导致他的同伴被困在外面，只能寻求能干的冒险者进入怪物密布的洞穴，找到那位鲁莽的矮人，并削减凶猛的温迪戈数量。"}},faq={{q="谁是科尼利厄斯？",a="科尼利厄斯是与任务发布者搭档的一名侦察兵或登山者。他因鲁莽的勇气而直接冲进了布满温迪戈的灰色洞穴，将同伴留在外面等待救援，以寻回他本人和白须的报告。",al={"科尼利厄斯是谁","矮人科尼利厄斯","科尼利厄斯在哪里"}},{q="什么是灰色洞穴？",a="灰色洞穴是位于登山者营地北侧的一个洞穴。虽然温迪戈通常只待在深山巢穴中，但最近它们却异常大量地涌入了该洞穴。",al={"什么是灰色洞穴","温迪戈在哪里","丹莫罗温迪戈洞穴"}},{q="为什么温迪戈在扩散？",a="温迪戈通常待在与世隔绝的洞穴里，但当地侦察兵注意到，它们已经开始在冰雪覆盖的山脊上大量繁殖并迅速蔓延，与当地的巨魔威胁一起构成了严重的隐患。",al={"为什么温迪戈在扩散","丹莫罗温迪戈问题","温迪戈像兔子一样繁衍"}},{q="谁是白须，他的报告是什么？",a="白须是一位权威人士或指挥官，正在等待一份关于山区状况的重要侦察报告。科尼利厄斯在鲁莽冲进洞穴之前，正携带着或试图确保这份报告的安全。",al={"谁是白须","白须的报告","森内尔·白须"}},{q="“Secure the Mountain”的目标是什么？",a="这是一项营救和清理任务，要求冒险者进入灰色洞穴，找到失踪的侦察兵科尼利厄斯，并清理洞穴中猖獗的温迪戈。",al={"什么是secure the mountain","secure the mountain任务目标"}},{q="巨魔是如何导致山区麻烦的？",a="当地侦察兵在山峰上已经面临着来自本土霜鬃巨魔的持续压力。突然激增的温迪戈为试图守卫山口的巡逻队制造了危险的双重威胁。",al={"丹莫罗的巨魔","巨魔威胁"}}},fp="19,269,13.358.0,14.321.0,17.251.0,25.196.0,31.204.0,41.195.0,40.177.0,54.215.0"}
P.entries["quest:98321"] = {n="Flintfire's Shipment",s="卡拉诺斯的Tognus Flintfire正面临严重的物资短缺，因为凶猛的温迪戈占领了他主要的矿石来源——灰色洞穴。矿工们在撤离时被迫丢下了装满矿石的板条箱，冒险者们受命找回这些遗失的货物，以维持当地熔炉的运转。",h="卡拉诺斯的Tognus Flintfire正面临严重的物资短缺，因为凶猛的温迪戈占领了他主要的矿石来源——灰色洞穴。矿工们在撤离时被迫丢下了装满矿石的板条箱，冒险者们受命找回这些遗失的货物，以维持当地熔炉的运转。",kw={"丹莫罗","flintfire","熔炉","灰色洞穴","卡拉诺斯","矿工","矿石","货物","tognus flintfire","温迪戈"},ang={["profession:Blacksmithing"]="找回Flintfire的货物对于确保卡拉诺斯的当地熔炉有充足的可加工金属供应至关重要。",["profession:Mining"]="遗失的货物由矿工在温迪戈袭击时撤离主要挖掘点所留下的重要矿石组成。",["race:Gnome"]="Tognus Flintfire特别欢迎愿意在丹莫罗从事繁重体力劳动的侏儒冒险者，并对他们的毅力表示真诚的赞赏。"},sec={{t="卡拉诺斯的物资危机",b="在冰雪覆盖的卡拉诺斯定居点，Tognus Flintfire的熔炉正面临严重的物资危机。在凶猛的温迪戈入侵挖掘现场后，该地区最富产、最可靠的矿石来源突然沉寂了。当地矿工在猝不及防的情况下遭到了这些凶猛捕食者的袭击，被迫立即放弃岗位，四散逃命，留下了散落在洞穴地面上、刚刚打包好的珍贵矿石板条箱。"},{t="深入灰色洞穴",b="这个被占领的矿坑名为灰色洞穴，位于卡拉诺斯以西。虽然Tognus很庆幸所有矿工都从那些凶猛野兽的口中平安逃脱，但停工却威胁到了当地铁匠铺的全面运作。与其等待武装远征队去清理洞穴，Tognus更希望寻求勇敢的冒险者潜入温迪戈的巢穴，收集那些滞留的板条箱，并将至关重要的矿石带回熔炉。"}},faq={{q="Tognus Flintfire是谁？",a="Tognus Flintfire是卡拉诺斯的一名矮人，依靠稳定的矿石运输来维持其熔炉的运作。在温迪戈占领了他主要的采矿洞穴并导致严重的物资短缺后，他招募旅行者去面对危险，取回那些被遗弃的板条箱。",al={"tognus flintfire是谁","tognus flintfire","任务发布者"}},{q="灰色洞穴位于何处？",a="灰色洞穴是位于丹莫罗卡拉诺斯以西的一个洞穴系统。它曾经是一个可靠的采矿点，现在却成了凶猛的温迪戈的巢穴，迫使任何想要寻找遗失矿石的人必须进入这片敌对区域。",al={"灰色洞穴在哪里","灰色洞穴位置","货物在哪里寻找"}},{q="采矿洞穴为何被废弃？",a="在敌对的温迪戈入侵并占领该地点之前，这个洞穴曾是当地矿工最可靠的矿石来源。工人们在绝望的撤离中被迫丢弃了设备和储备的货物，奇迹般地幸存了下来。",al={"矿工为何逃离","矿坑发生了什么","温迪戈袭击"}},{q="丢失的货物里有什么？",a="这些货物由矿工在被驱逐前打包进板条箱的开采矿石组成。没有这些材料，卡拉诺斯的当地金属加工和熔炉作业将陷入停滞。",al={"flintfire的货物是什么","板条箱里有什么","货物内容"}},{q="在袭击中是否有矿工受伤？",a="尽管温迪戈极其凶猛，但Tognus欣慰地表示，所有的矿工都设法平安逃出了灰色洞穴，只留下了他们的补给品和矿石。",al={"矿工生还了吗","矿工伤亡","温迪戈受害者"}},{q="货物被找回后会发生什么？",a="确保找回这些货物，能为Tognus Flintfire提供重启当地熔炉所需的原材料，而无需先清理整个被侵扰的洞穴。",al={"为什么需要矿石","找回后会发生什么","熔炉运转"}}},fp="20,302,27.462.0,31.435.0,24.270.0,34.235.0,34.255.0,37.209.0,42.189.0,46.204.0"}
P.entries["quest:98322"] = {n="Secure the Mountain",s="“Secure the Mountain”是丹莫罗卡拉诺斯的一项联盟任务。一位负责为铁炉堡搜集情报的当地官员在负责调查好斗的温迪戈的侦察兵失联后，派遣冒险者前往镇子西面查看山地巡逻队员格雷琴的情况。",h="“Secure the Mountain”是丹莫罗卡拉诺斯的一项联盟任务。一位负责为铁炉堡搜集情报的当地官员在负责调查好斗的温迪戈的侦察兵失联后，派遣冒险者前往镇子西面查看山地巡逻队员格雷琴的情况。",kw={"丹莫罗","矮人","铁炉堡","卡拉诺斯","山地巡逻队员格雷琴","secure the mountain","温迪戈","白须"},ang={["faction:Alliance"]="协助卡拉诺斯周围的当地矮人巡逻队加强了整个卡兹莫丹冰雪腹地的防御协调。",["race:Dwarf"]="丹莫罗的山地巡逻队员在雪山脊和危险的洞穴中保持着警惕的巡逻，可靠的侦察对于保障矮人定居点的安全至关重要。"},sec={{t="逾期的报告",b="一位卡拉诺斯的官员受命为铁炉堡的High Seat汇编当地的军事情报，但他的日常工作却被打断了。一支被派去评估附近温迪戈活动的山地巡逻队未能带回最新的消息。这位官员没有亲自去钻冰冷的洞穴，而是招募了有能力的旅行者前往镇子西面，去确认侦察兵们的状况。"},{t="西部山脊的麻烦",b="在卡拉诺斯西面找到山地巡逻队员格雷琴后，原本平静的区域监视工作变得令人担忧起来。格雷琴确认她收到了白须的询问，但她透露，周围山岩中的温迪戈骚乱远比最初的报告所显示的更加不稳定，这也为进一步深入附近的荒野进行侦察埋下了伏笔。"}},faq={{q="谁发布了“Secure the Mountain”任务？",a="该任务由卡拉诺斯的森内尔·白须发布，山地巡逻队员格雷琴称他为“老白须”。他的职责包括汇编关于当地荒野威胁的正式报告，并将其发送给铁炉堡的矮人领导层。",al={"谁发布了“secure the mountain”","“secure the mountain”任务发布者","谁开启了“secure the mountain”"}},{q="在哪里可以找到山地巡逻队员格雷琴？",a="山地巡逻队员格雷琴驻扎在丹莫罗的卡拉诺斯镇西面，负责监视附近山坡和洞穴中存在的当地温迪戈威胁。",al={"格雷琴在哪里","山地巡逻队员格雷琴的位置","寻找山地巡逻队员格雷琴"}},{q="任务发布者为什么要寻找山地巡逻队员格雷琴？",a="任务发布者负责将情报送回铁炉堡，但被派去调查当地温迪戈活动的侦察兵没能按时报告。由于进度落后，且为了避免危险的洞穴探索，他请求一位路过的冒险者去查看山地巡逻队员格雷琴的情况。",al={"为什么要派遣冒险者","为什么白须需要帮助","为什么要查看格雷琴的情况"}},{q="什么温迪戈问题正在威胁该地区？",a="温迪戈栖息在卡拉诺斯周围的岩石山脚和黑暗洞穴中。它们咄咄逼人的存在对旅行者和当地哨所构成了直接威胁，促使铁炉堡的侦察兵密切监视它们的动向。",al={"卡拉诺斯的温迪戈威胁","温迪戈在做什么","为什么会出现温迪戈问题"}},{q="抵达后山地巡逻队员格雷琴报告了什么？",a="在镇西找到山地巡逻队员格雷琴后，她确认收到了白须的询问，并严肃地指出，附近温迪戈的整个局势已经变得非常糟糕。",al={"格雷琴说了什么","“secure the mountain”任务交付","格雷琴报告的状况"}},{q="山地巡逻队员在卡拉诺斯周围扮演什么角色？",a="山地巡逻队员是铁炉堡矮人的主要边境守卫、追踪者和侦察部队，他们勘测丹莫罗各处的偏远隘口、黑暗洞穴和雪地小径，以保护像卡拉诺斯这样的城镇。",al={"谁是山地巡逻队员","铁炉堡山地巡逻队","山地巡逻队员的职责"}}},fp="19,263,17.400.0,28.377.1,40.242.0,40.162.0,55.298.0,45.217.0,51.195.0,47.205.0"}
P.entries["quest:98323"] = {n="Secure the Mountain",s="《Secure the Mountain》是一份代表登山者格雷琴递交给卡拉诺斯森内尔·白须的侦察报告。在一次前往附近洞穴的探险遭遇灾难性后果后，格雷琴断定该洞穴已经无法挽回，并拒绝再派遣任何侦察兵进入这个到处都是敌人的死亡陷阱。这项任务突显了铁炉堡的登山者们在日益增长的威胁中保卫丹莫罗安全的持续斗争。",h="《Secure the...",kw={"洞穴","科尼利厄斯","丹莫罗","卡拉诺斯","登山者格雷琴","登山者的报告","secure the mountain","森内尔·白须"},ang={["faction:Alliance"]="确保铁炉堡周围的高海拔山口的安全，对于维护联盟在卡兹莫丹冰雪要塞中的安全通行和防御至关重要。",["race:Dwarf"]="丹莫罗是铜须矮人的祖居之地，这使得登山者格雷琴的顽强坚守成为了一项保护她的族人免受周围威胁的重要努力。"},sec={{t="一份严峻的报告",b="登山者格雷琴驻扎在丹莫罗寒冷的峰顶，肩负着确保高海拔山口安全的职责。然而，最近一次对附近洞穴的突入表明，这片荒野远未平定。在评估了局势后，格雷琴认为该洞穴已经变成了一个彻头彻尾的死亡陷阱，充斥着敌对的怪物。与其冒着牺牲更多生命的风险，她选择坚守在斜坡上的岗位，决心守住防线，同时派遣一名信使去递交她的书面评估。"},{t="深渊中的损失",b="放弃继续深入该洞穴的决定是在付出惨重代价后做出的。在这场失败的侦察行动中，科尼利厄斯不幸遇难，他的牺牲让登山者格雷琴感到沉重。在承认当前条件下无法收复该洞穴后，她下令停止所有对地下隧道的进一步探索任务。她的工作重点从进攻性清理转向了防御性封锁，拒绝再让更多的侦察兵白白牺牲在这些潜伏在雪山峭壁下的凶残生物手中。"},{t="森内尔·白须的档案",b="在繁忙的卡拉诺斯定居点，森内尔·白须追踪着侵扰矮人领地的众多危险。在收到格雷琴那份严峻的评估报告后，白须对于洞穴完全失控的消息并没有感到多少惊讶。他默默接受了丹莫罗所面临的严峻现实，将格雷琴的信件收进了他那堆积如山的实地报告中。这些情报成为了铁炉堡在更广泛地记录和管理动荡边境的过程中，又一份发人深省的资料。"}},faq={{q="登山者格雷琴是谁？",a="登山者格雷琴是一名驻扎在丹莫罗冰雪荒野中的铁炉堡哨兵。她恪尽职守，拒绝在周围领土被判定安全之前离开她的高山岗位。在一次进入附近洞穴的致命侦察任务后，她写下了一份详细描述了敌方重兵把守的正式实地报告，并将其送往卡拉诺斯。",al={"格雷琴","登山者格雷琴背景故事","格雷琴是谁"}},{q="森内尔·白须是谁？",a="森内尔·白须是一位驻扎在卡拉诺斯镇的矮人官员。他负责收集情报并协调丹莫罗各地的本地安全行动，接收来自实地登山者们的派遣报告和侦察评估。当获悉危险的敌军入侵或失陷的洞穴时，他会将这些报告编入正式档案，以评估区域威胁等级。",al={"森内尔·白须","白须 卡拉诺斯","森内尔是谁"}},{q="科尼利厄斯是谁？",a="科尼利厄斯是参与探索山上那处受灾洞穴的一名同僚或侦察兵。登山者格雷琴怀着遗憾提到了他的悲惨命运，表明他是在那次不幸的侦察行动中阵亡的。他的死直接影响了格雷琴将洞穴判定为致命死亡陷阱的决定，并禁止任何人再在里面白白送命。",al={"科尼利厄斯","科尼利厄斯是谁","科尼利厄斯发生了什么","科尼利厄斯 secure the mountain"}},{q="山洞里发生了什么？",a="当侦察兵发现隧道完全被敌对的怪物占领后，对洞穴的探索宣告失败。这次任务导致了科尼利厄斯的悲剧性丧生。在这一严峻的发现之后，登山者格雷琴宣布该地下通道已无法挽回，并断定再派人进入无异于自杀，于是决定封锁或避开该区域。",al={"洞穴里有什么","为什么洞穴是死亡陷阱","洞穴无法挽回"}},{q="为什么格雷琴拒绝离开她的岗位？",a="登山者格雷琴非常重视她保护丹莫罗的誓言，并坚定地声明在山脉本身安全之前，她绝不会放弃自己的阵地。尽管她承认附近的洞穴太过危险而无法夺回，但她依然坚守在白雪皑皑的山巅，守卫着通道并保持警惕，同时将威胁的消息传回卡拉诺斯。",al={"为什么格雷琴要留下来","格雷琴的岗位","为什么要留在山上"}},{q="森内尔·白须对格雷琴的报告有何反应？",a="森内尔·白须对得知洞穴被彻底占领的消息几乎毫不惊讶，这表明这种敌对入侵在丹莫罗已成为太过常见的麻烦。比起表现出震惊，他冷静地接受了这个坏消息，并将格雷琴的书面报告收进他那堆积如山的笔记中，细致地记录着威胁到王国的种种危险。",al={"森内尔的反应","白须对报告的反应","森内尔做什么工作"}},{q="登山者在丹莫罗扮演什么角色？",a="登山者是铁炉堡警惕的边境侦察兵和守卫，在丹莫罗险峻的雪覆盖山峰、高海拔小径和山口进行巡逻。这些坚韧的矮人驻扎在远离温暖首都的地方，监控着敌对野兽的动向，侦察洞穴，并将重要情报传回卡拉诺斯这样的本地枢纽，以保护旅行者和定居点。",al={"铁炉堡登山者","什么是登山者","矮人登山者背景故事"}}},fp="19,408,13.521.0,20.537.1,26.515.0,28.375.0,24.401.0,18.390.0,35.405.0,43.359.0,53.378.0,49.403.0"}
P.entries["quest:98326"] = {n="Frosthowl",s="Frosthowl是丹莫罗的一项任务，要求冒险者从一只偷窃的温迪戈那里找回一袋被偷的鱼。这只野兽伏击了一位当地的矮人渔夫，并逃进了灰色洞穴的深处。",h="Frosthowl是丹莫罗的一项任务，要求冒险者从一只偷窃的温迪戈那里找回一袋被偷的鱼。这只野兽伏击了一位当地的矮人渔夫，并逃进了灰色洞穴的深处。",kw={"丹莫罗","frosthowl","冰冻湖泊","灰色洞穴","冰钓","paxton","被偷的鱼","温迪戈"},ang={["faction:Alliance"]="保护Brewnall和卡拉诺斯附近的冰雪小径和钓鱼点免受凶猛掠食者的侵害，是当地联盟冒险者义不容辞的责任。",["race:Dwarf"]="坚韧的矮人渔夫在丹莫罗的冰冻湖面上忍受着刺骨的严寒，这使得温迪戈的捕食性袭击成为了当地家园定居者和生计时刻面临的威胁。"},sec={{t="被盗的渔获",b="在丹莫罗冰冷的水域进行冰钓是一项艰苦而痛苦的工作。一位矮人渔夫和她的丈夫Paxton在冰封的湖面上冒着刺骨的寒风待了数日，才仅仅收获了一袋鱼。当名为Frosthowl的凶猛且咆哮着的温迪戈袭击营地并抢走他们全部的渔获逃进雪原时，他们的辛苦劳作瞬间化为乌有。"},{t="灰色洞穴中的吵闹鬼",b="Frosthowl并非普通的食腐动物；这头野兽以其震耳欲聋的咆哮声而闻名，这些吼声能震碎冰层并吓跑湖中稀少的鱼群。在抢走渔夫的补给袋后，这只流着口水的生物退回到了位于东南方向的灰色洞穴的黑暗隧道深处，留下了陷入困境的渔夫们，他们迫切希望有人能去对抗这只怪物并取回被盗的物品。"}},faq={{q="Frosthowl是谁？",a="Frosthowl是一只潜伏在丹莫罗的吵闹且极具攻击性的温迪戈。它以咆哮和恐吓冰封的水道而闻名，最近还袭击了一位当地的矮人渔夫，并抢走了她丈夫辛苦捕获的鱼。",al={"关于frosthowl","frosthowl是什么","frosthowl温迪戈"}},{q="在哪里可以找到Frosthowl？",a="Frosthowl躲在灰色洞穴的深处，这是一个位于Paxton捕鱼的冰冻湖泊东南方向的洞穴系统。",al={"frosthowl在哪里","frosthowl位置","温迪戈躲在哪里"}},{q="Frosthowl偷走了什么？",a="Frosthowl伏击了一位矮人渔夫，偷走了一整袋鱼，那是她丈夫Paxton在冰冻湖面上花了几天时间才捕获的。冒险者们受托去猎杀这只野兽并找回被盗的渔获。",al={"frosthowl偷了什么","为什么要击杀frosthowl","温迪戈拿走了什么"}},{q="Paxton是谁？",a="Paxton是一位矮人渔夫，他在冰封的湖面上花了数天时间试图捕获一些鱼。在Frosthowl偷走了他们唯一的一袋鱼之后，他的妻子委托路过的旅行者去追踪这只野兽。",al={"关于paxton","丹莫罗的paxton","渔夫paxton"}},{q="什么是灰色洞穴？",a="灰色洞穴是丹莫罗冰冻湖泊东南方一处已知的温迪戈巢穴，它是像Frosthowl这样的野兽用来囤积腐肉和被盗补给的黑暗巢穴。",al={"什么是灰色洞穴","灰色洞穴温迪戈巢穴","丹莫罗的温迪戈栖息地"}},{q="这头野兽为什么叫Frosthowl？",a="这只温迪戈被称为“吵闹鬼”，它那震耳欲聋的咆哮和嚎叫声在雪原上回荡，吓跑了鱼群，并让任何在冰湖上工作的人感到恐惧。",al={"frosthowl得名原因","为什么叫frosthowl","吵闹的温迪戈"}}},fp="9,205,13.383.0,33.394.0,17.220.0,29.135.0,25.209.0,14.211.0,25.197.0,33.187.0"}
P.entries["quest:98341"] = {n="The Great Windborne Cat Spirit",s="The Great Windborne Cat Spirit是一位来自泽弗拉斯（Zephras）国度的神圣导师，以塞琳南化身（Avatar of Saeyleenan）的形象出现在月光林地。它引导年轻的申多雷（shen'dorei）德鲁伊通过他们的灵性试炼，以便他们能掌握来自遥远故乡的风生猫形态。",h="The Great Windborne Cat Spirit是一位来自泽弗拉斯（Zephras）国度的神圣导师，以塞琳南化身（Avatar of...",kw={"猫形态","猫灵","德鲁伊试炼","月光林地","塞琳南","申多雷","风生猫","泽弗拉斯"},ang={["class:Druid"]="来自泽弗拉斯的德鲁伊通过与风生猫灵沟通来掌握他们的猫科形态，完成一项为他们独特的文化传承量身定制的仪式，而非采用传统的艾泽拉斯之道。",["race:Skyborne"]="被称为申多雷的逐天者德鲁伊在故乡泽弗拉斯的灵体引导下进行修行，而非采用艾泽拉斯本土的形态。"},sec={{t="来自泽弗拉斯的访客",b="在月光林地的神圣庇护所中，一个来自遥远泽弗拉斯国度的灵体出现在双桥南侧。这个自称为塞琳南化身的风生猫灵穿梭来到艾泽拉斯，旨在引导和教导那些准备解锁猫科变形形态的年轻申多雷德鲁伊。"},{t="风生形态的本质",b="虽然所有德鲁伊最终都会寻求猫科形态的智慧，但来自泽弗拉斯的德鲁伊所传承的传统与艾泽拉斯的原住民截然不同。申多雷德鲁伊并非采用艾泽拉斯野生猫科动物的形态，而是化身为他们故乡的风生掠食者。为了确保他们能领悟其灵性本质，塞琳南会亲自监督他们在月光林地的试炼。"}},faq={{q="The Great Windborne Cat Spirit是谁？",a="风生猫灵以塞琳南化身的形象显现，这是一种来自遥远故乡泽弗拉斯的灵体。它来到月光林地是为了教导和考验那些寻求获得其猫科形态的年轻申多雷德鲁伊。",al={"风生猫灵是谁","什么是塞琳南化身","塞琳南背景故事"}},{q="在哪里可以找到塞琳南化身？",a="该灵体的化身出现在月光林地的南部区域，位于双桥正南侧。",al={"月光林地猫灵位置","塞琳南化身所在地","风生猫位置"}},{q="为什么泽弗拉斯的德鲁伊要与不同的猫灵沟通？",a="因为申多雷德鲁伊起源于泽弗拉斯，他们的猫科形态反映的是故乡的风生灵体，而非艾泽拉斯本土的大型猫科动物。该灵体会亲自监督他们的试炼，以确保他们能正确掌握其精髓。",al={"为什么猫形态看起来不同","泽弗拉斯猫形态区别","为什么不用艾泽拉斯猫灵"}},{q="风生猫的试炼包含什么？",a="塞琳南化身会让受试者进行艾泽拉斯巨猫之灵的试炼，同时亲自介入监督，确认德鲁伊能够领悟风生灵体的独特本质。",al={"猫灵给予什么试炼","泽弗拉斯猫灵试炼","如何获得风生猫形态"}},{q="申多雷指的是什么？",a="塞琳南化身将受试者称为申多雷，以此表明他们源自泽弗拉斯，并将他们的传统和灵性习俗与艾泽拉斯的原住民区分开来。",al={"谁是申多雷","申多雷德鲁伊","申多雷是什么意思"}},{q="什么是泽弗拉斯？",a="泽弗拉斯是申多雷遥远的故乡。那里的原生动植物和灵体与艾泽拉斯明显不同，这使得其德鲁伊拥有独特的变形形态。",al={"什么是泽弗拉斯","泽弗拉斯在哪里","泽弗拉斯故乡"}}},fp="30,266,22.312.0,32.368.0,38.227.0,44.106.0,58.248.0,48.211.0,30.191.0,16.188.0"}
P.entries["quest:98362"] = {n="To Thunder Bluff",s="“To Thunder Bluff” 标志着一位年轻的牛头人德鲁伊从月光林地与塞纳里奥议会的交流中凯旋归来。在赢得了 The Great Cat Spirit 的青睐后，这位新学徒回到了长者高地，寻找图拉克·符文图腾，以掌握猫科变形的艺术。",h="“To Thunder Bluff” 标志着一位年轻的牛头人德鲁伊从月光林地与塞纳里奥议会的交流中凯旋归来。在赢得了 The Great Cat Spirit...",kw={"猫形态","德迪利特·星焰","德鲁伊","长者高地","the great cat spirit","月光林地","雷霆崖","图拉克·符文图腾"},ang={["class:Druid"]="这项仪式代表着你捕食本能的解锁，让你能够像图拉克·符文图腾所教导的那样，掌握潜行和利爪的技巧。",["faction:Horde"]="虽然塞纳里奥议会保持中立，但部落的德鲁伊必须回到他们的主城，以确保他们日益增长的力量能够为保卫同胞服务。",["race:Tauren"]="这段旅程强调了牛头人与塞纳里奥传统的重新连接，将来自神圣月光林地的教诲带回了雷霆崖的长者高地。"},sec={{t="从月光林地归来",b="在月光林地的神圣树林中向德迪利特·星焰和 The Great Cat Spirit 证明了自己的见识和价值后，年轻的德鲁伊必须将圣兽的祝福带回莫高雷。与这种原始力量的交流是德鲁伊训练中的一个关键里程碑，它将古老的暗夜精灵教义与牛头人自身的土灵传统联系了起来。"},{t="掌握猫形态",b="图拉克·符文图腾正在雷霆崖的长者高地之巅等待着你的归来。虽然德迪利特促成了你与圣兽本身的交流，但引导身体形态的转变还得依靠图拉克。在 The Great Cat Spirit 的祝福得到认可后，这位老训练师将传授化身为敏捷、捕食性的猫形态所需的神圣知识。"}},faq={{q="这个任务在哪里开始和结束？",a="该任务由月光林地的德迪利特·星焰发布。它指引旅行者回到雷霆崖的长者高地，与图拉克·符文图腾交谈。",al={"交任务的地方","谁发布 to thunder bluff","to thunder bluff 任务交接"}},{q="这个任务的目的是什么？",a="它作为德鲁伊猫之试炼的最终过渡阶段。在月光林地获得 The Great Cat Spirit 的祝福后，新学徒必须回到雷霆崖的导师身边，最终学会如何变身为猫形态。",al={"为什么要做 to thunder bluff","做 to thunder bluff 能得到什么","猫形态任务"}},{q="图拉克·符文图腾是谁？",a="图拉克·符文图腾是一位受人尊敬的牛头人德鲁伊长者，驻扎在雷霆崖的长者高地。他负责监督那些寻求与自然和谐相处并掌握变形形态的部落年轻德鲁伊的训练和入门仪式。",al={"图拉克·符文图腾背景故事","图拉克是谁"}},{q="德迪利特·星焰是谁？",a="德迪利特·星焰是一位隶属塞纳里奥议会的暗夜精灵守护者，他在月光林地的永夜港为到访的德鲁伊提供指导。他不顾阵营间的紧张关系，在古老的卡多雷传统与牛头人修行者之间架起了教义的桥梁。",al={"德迪利特·星焰的作用","月光林地的暗夜精灵"}},{q="The Great Cat Spirit 是什么？",a="The Great Cat Spirit 是一个古老的原始实体，深受德鲁伊的崇敬，它体现了捕食本能、潜行和敏捷。每一位寻求化身为猫形态的德鲁伊都必须通过试炼来赢得它的祝福，并理解它既顽皮又致命的双重本性。",al={"the great cat spirit 背景故事","猫之灵"}},{q="联盟德鲁伊有对应的任务吗？",a="有。暗夜精灵德鲁伊在月光林地进行类似的仪式，他们返回达纳苏斯向自己的导师报告，而不是前往莫高雷那风吹过的平顶山。",al={"to thunder bluff 的联盟版本","暗夜精灵猫形态任务交接"}}},fx={cdfa9758={q="德迪利特·星焰为什么让你返回雷霆崖？",a="德迪利特·星焰在月光林地担任导师和考官，引导你与The Great Cat Spirit沟通。如今试炼已经完成，你也获得了那位精灵的青睐，他在你这一阶段的训练中便已尽责。他让你返回图拉克·符文图腾那里，由你的主导师传授最后的教诲，并引导你真正掌握变形为猫形态的能力。",al={"为什么要去雷霆崖","德迪利特·星焰的动机","为什么返回图拉克·符文图腾那里"}}},fp="16,278,21.359.0,22.359.0,36.169.0,34.235.0,23.236.0,26.240.0,29.262.0,43.168.0"}
P.entries["quest:98372"] = {n="An Unfortunate End",s="暮色森林的阴影中躺着一名倒下的守夜人，他被一头身份不明的掠食者残忍撕咬。取回他冰冷手指间那支未点燃的火把，便能驱散周围的黑暗，揭示阴影中隐藏的一切。",h="暮色森林的阴影中躺着一名倒下的守夜人，他被一头身份不明的掠食者残忍撕咬。取回他冰冷手指间那支未点燃的火把，便能驱散周围的黑暗，揭示阴影中隐藏的一切。",kw={"不幸的结局","野兽","暮色森林","撕咬","守夜人","火把"},sec={{t="骇人的发现",b="一名倒下的守夜人成员静静躺在暮色森林昏暗的土地上，身上布满了凶猛搏斗留下的严重伤口和撕裂痕迹。这些狰狞的伤口表明，这名巡逻兵还没来得及逃脱，就遭到了一头巨兽的伏击。"},{t="黑暗中的光明",b="倒下的守卫僵硬的手指间紧握着一支未点燃的火把。将火把从他手中取走，便能得到一件对抗不断逼近的阴影的宝贵工具，照出暮色森林的浓重阴霾和其他黑暗小径中隐藏的事物。"}},faq={{q="这是谁的尸体？",a="这具倒下的尸体属于一名守夜人成员。守夜人负责巡逻暮色森林的黑暗道路和边境。这名守卫独自死在阴影之中，遭遇了暴力袭击。",al={"这具尸体是谁的","谁死在这里","死去的守夜人是谁"}},{q="是什么杀死了守卫？",a="他遭到一头大型野兽撕咬，尸体上留下了深深的伤口和狰狞的撕裂痕迹。袭击他的生物在他来得及自卫或照亮道路之前就制服了他。",al={"什么杀死了守夜人","守卫是怎么死的","是什么袭击了他"}},{q="火把为什么重要？",a="从守卫手中取下的未点燃火把可以照亮周围的阴霾，帮助游荡者揭开暮色森林及其外的土地上浓重黑暗所遮蔽的事物。",al={"火把有什么用","火把要怎么用","暮色森林火把用途"}}},fp="18,247,16.253.0,21.269.0,19.179.0,25.180.0,27.172.0"}
P.entries["quest:98386"] = {n="奥瑟尔伐木场",s="奥瑟尔伐木场是赤脊山的一个任务，由湖畔镇的工头奥斯洛提供。工头需要冒险者清除附近伐木场内危险的塔兰图拉毒蛛，以便工人们能安全地取回完成湖畔镇桥梁所需的木材。",h="奥瑟尔伐木场是赤脊山的一个任务，由湖畔镇的工头奥斯洛提供。工头需要冒险者清除附近伐木场内危险的塔兰图拉毒蛛，以便工人们能安全地取回完成湖畔镇桥梁所需的木材。",kw={"奥瑟尔伐木场","桥梁","工头奥斯洛","湖畔镇","伐木场","赤脊山","塔兰图拉毒蛛"},ang={["faction:Alliance"]="重建湖畔镇的基础设施对暴风城王国至关重要，但不断的威胁一直在分散用于桥梁建设的资源。"},sec={{t="木材瓶颈",b="工头奥斯洛为了维持湖畔镇桥梁的维修进度，可谓焦头烂额。面对敌对的黑石兽人、不断逼近的豺狼人部族以及止水湖沿岸好斗的鱼人，他的工人早已精疲力竭。最新的麻烦直接打击了他的供应链：位于东部的奥瑟尔伐木场被巨大的塔兰图拉毒蛛占领，导致该镇桥梁所需的木材供应中断。"},{t="清除虫害",b="伐木场里潜伏着毒蛛，堆积的木材完全无法使用。工头奥斯洛不敢冒险让工人们进入高等塔兰图拉毒蛛的巢穴，于是他雇佣有能力的冒险者去清除这些蛛形纲生物并摧毁它们的卵囊。虽然奥斯洛对奥瑟尔任由伐木场陷入混乱感到不满，但恢复木材供应比任何个人恩怨都更为重要。"}},faq={{q="工头奥斯洛是谁？",a="工头奥斯洛是负责修复和重建湖畔镇桥梁的石匠兼监工。他一直受到当地各种威胁的困扰，这些威胁延误了他的施工进度。",al={"工头奥斯洛是谁","赤脊山工头奥斯洛"}},{q="什么是奥瑟尔伐木场？",a="奥瑟尔伐木场位于赤脊山，湖畔镇以东。它为湖畔镇周边的建筑工程，包括桥梁工程在内，提供至关重要的木材供应。",al={"什么是奥瑟尔伐木场","奥瑟尔伐木场在哪里"}},{q="奥瑟尔是谁？",a="奥瑟尔是湖畔镇东部伐木场的所有者或经营者。据工头奥斯洛所述，奥瑟尔负责管理该场所，但目前他的伐木场已被蜘蛛侵扰。",al={"奥瑟尔是谁","奥瑟尔在哪里"}},{q="工头奥斯洛为什么要清理奥瑟尔伐木场？",a="在塔兰图拉毒蛛侵扰伐木场的情况下，工头奥斯洛无法安全地派遣工人去收集必需的木材。清除蜘蛛并摧毁它们的卵可以确保伐木场安全地恢复桥梁建设所需的木材供应。",al={"为什么要清理奥瑟尔伐木场","为什么要杀赤脊山的蜘蛛"}},{q="什么在侵扰奥瑟尔伐木场？",a="高等塔兰图拉毒蛛和蜘蛛卵囊侵扰了伐木场，这对任何被派去取回木材的工人来说都构成了严重威胁。",al={"奥瑟尔伐木场有什么蜘蛛","赤脊山蜘蛛"}},{q="工头奥斯洛要建造什么桥？",a="工头奥斯洛正在努力重建湖畔镇的桥梁，但他的进度屡屡被敌对的兽人、豺狼人、鱼人以及当地害虫造成的资源短缺所拖延。",al={"赤脊山的桥","湖畔镇大桥"}}},fp="13,266,22.434.0,24.416.0,21.184.0,22.193.0,14.214.0,50.241.0,32.148.0,45.179.0"}
P.entries["quest:98387"] = {n="Blackrock Blockade",s="“黑石封锁”是湖畔镇的治安官马瑞斯发布的一项联盟军事任务。为了应对止水湖东岸不断逼近的黑石兽人，镇卫兵旨在切断入侵者的补给并缴获他们的武器。",h="“黑石封锁”是湖畔镇的治安官马瑞斯发布的一项联盟军事任务。为了应对止水湖东岸不断逼近的黑石兽人，镇卫兵旨在切断入侵者的补给并缴获他们的武器。",kw={"破斧","blackrock blockade","黑石氏族","湖畔镇","治安官马瑞斯","赤脊山","石堡要塞"},ang={["class:Warrior"]="在与粗犷的黑石兽人进行近身遭遇战时，剥夺敌人的重型切肉刀和补给是边境作战的基本原则。",["faction:Alliance"]="从黑石先锋队缴获的每一件武器，都能为湖畔镇争取到宝贵的时间，毕竟这里必须在没有暴风城大量援助的情况下抵御敌军的进攻。"},sec={{t="消耗战",b="尽管黑石氏族已经大举入侵了赤脊山，但他们鲁莽地推进到联盟领土的行为已经让他们的后勤陷入了崩溃的边缘。由于被切断了常规的补给线，他们的先锋作战部队被迫在这片严酷的赤脊山丘陵中寻找生存资源。治安官马瑞斯深知，即使是凶猛的兽人，没有稳定的给养和钢铁武器也无法维持长久的战役。"},{t="切断前沿营地",b="位于石堡要塞南侧的兽人营地是黑石氏族进攻的矛头所在。通过突袭这些营地、搜刮物资储备并夺走他们窃取的武器，联盟守军希望能削弱先遣队的战斗力并摧毁他们的士气。"}},faq={{q="“黑石封锁”的目标是什么？",a="该任务旨在破坏石堡要塞以南黑石氏族的前沿营地。通过突袭他们的补给线、夺取食物并回收武器，湖畔镇守卫希望能断绝兽人的供给，以此减缓他们对赤脊山的攻势。",al={"什么是黑石封锁","黑石封锁目标","封锁目的"}},{q="谁发布了这项任务？",a="治安官马瑞斯，湖畔镇镇守卫的指挥官，负责监督赤脊山的防御并指挥破坏黑石氏族补给的行动。",al={"谁发布黑石封锁","任务发布者","治安官马瑞斯任务"}},{q="这些黑石营地位于何处？",a="目标战营位于赤脊山脉的东部丘陵，就在石堡要塞以南，与湖畔镇隔河相望。",al={"兽人在哪里","黑石营地位置","石堡营地在哪里"}},{q="为什么湖畔镇选择消耗战，而不是直接进攻？",a="湖畔镇守卫人手不足，且几乎没有从暴风城得到增援。这是一场消耗战：黑石兽人鲁莽地深入联盟领土，导致他们陷入了脆弱的境地，补给断绝，只能依赖周围的山区来获取资源，而大军是无法在饥肠辘辘的情况下作战的。",al={"为何饿死兽人","为何不直接攻击石堡","湖畔镇战略"}},{q="哪些武器正从兽人手中没收？",a="治安官马瑞斯希望缴获囤积在黑石营地中的武器和补给，让兽人失去他们的战争工具。",al={"需要什么物品","什么斧头","战损的斧头背景"}},{q="这些兽人是萨尔部落的成员吗？",a="不是。赤脊山的这些黑石兽人属于盘踞在黑石山的叛乱势力——黑石氏族（黑铁氏族/黑石氏族）。他们拒绝萨尔的领导，并且对联盟和新部落都抱有强烈的敌意。",al={"这些是部落兽人吗","黑石是部落吗","萨尔黑石氏族"}}},fp="18,226,18.396.0,26.282.0,43.267.0,27.167.0,46.134.0,67.307.0,49.139.0,46.205.0"}
P.entries["quest:98389"] = {n="A Light in the Darkness",s="这项任务由丧钟镇的Aramis Hammerhand提供，要求被遗忘者冒险者解救困在蛛网洞穴中新复活的亡灵。它突显了那些使用圣光的亡灵与深深不信任他们的民众之间微妙的关系。通过援助他们陨落的同胞，这些圣光修行者希望向希尔瓦娜斯和被遗忘者的大义证明他们的忠诚。",h="这项任务由丧钟镇的Aramis...",kw={"aramis hammerhand","丧钟镇","执行官阿伦","被遗忘者","圣光","蛛网洞穴","提瑞斯法林地","被网住的受害者"},ang={["class:Priest"]="对于引导圣光能量的被遗忘者来说，这项任务说明了在残留的凡人信仰与严酷的亡灵现实之间行走的微妙平衡。",["race:Undead"]="这项任务展示了被遗忘者复杂的内心挣扎，展示了个人如何克服自身刚复活的族群中的偏见。"},sec={{t="摇摇欲坠的信仰",b="圣光对亡灵来说是众所周知的痛苦与危险，然而一些被遗忘者保留了他们生前所使用的神圣魔法的联系。在丧钟镇，像Aramis Hammerhand这样的人物致力于证明他们的信仰并没有让他们背离自己的人民。为了消除人们对圣光修行者会把其他亡灵视为怪物而反戈一击的猜疑，他们积极利用自己的能力和同情心来守护同胞。"},{t="蛛网洞穴",b="在丧钟镇西北方坐落着蛛网洞穴，这是一个阴暗潮湿、爬满凶猛蜘蛛的洞穴。刚刚复活的亡灵，由于苏醒后的迷茫和缺乏自卫的智力，经常误入洞穴，最终被困在粘稠的蛛网中。解救这些不幸的被遗忘者具有双重目的：为黑暗女王挽救新兵，并向执行官阿伦这样的领袖证明，圣光修行者是被遗忘者的忠实仆人。"}},faq={{q="谁给予了任务“A Light in the Darkness”？",a="该任务由驻扎在提瑞斯法林地丧钟镇的圣光修行者Aramis Hammerhand给予。",al={"任务给予者","谁开启a light in the darkness","aramis hammerhand任务"}},{q="蛛网洞穴位于哪里？",a="蛛网洞穴位于提瑞斯法林地的山丘中，丧钟镇的西北方。",al={"蛛网洞穴位置","被蛛网困住的受害者在哪","洞穴在哪"}},{q="为什么被遗忘者不信任圣光的使用者？",a="圣光对亡灵之躯有极大的灼烧感和危险。许多被遗忘者担心任何使用圣光力量的人会将他们视为应当根除的畸形怪物，而不是应当接纳的同胞。",al={"为什么惧怕圣光","为什么被遗忘者讨厌圣骑士","被遗忘者对圣光的恐惧"}},{q="被困在蛛网里的受害者是谁？",a="茧里的受害者是刚刚苏醒、在找到方向前误闯蜘蛛洞穴的被遗忘者冒险者。",al={"谁被网住了","蛛网里有什么","被困的受害者"}},{q="执行官阿伦是谁，为什么Aramis想要打动他？",a="执行官阿伦负责监督丧钟镇的军事和民事秩序。对于希望顺利融入被遗忘者军队的圣光使用者来说，获得他的信任至关重要。",al={"谁是执行官阿伦","为什么阿伦很重要"}},{q="亡灵真的可以使用圣光吗？",a="是的，通过惊人的意志力和虔诚，一些亡灵保留了他们与圣光的联系，尽管引导这种力量会带来巨大的不适，且他们自身的社会也以怀疑的眼光审视他们。",al={"被遗忘者能用圣光吗","亡灵圣光背景故事"}}},fx={f946e0be={q="阿拉米斯·锤掌为什么想救出被蛛网缠住的受害者？",a="阿拉米斯想向被遗忘者同胞证明，使用圣光的亡灵并不会威胁自己的同类。丧钟镇有许多人，包括执行官阿伦，都害怕或怀疑圣光使用者会把力量用在其他亡灵身上，将他们视作怪物。阿拉米斯希望通过从夜行蜘蛛洞穴的蜘蛛手中救出新近复活的被遗忘者，证明他们的力量是为了保护被遗忘者，服务于黑暗女王的愿景。",al={"阿拉米斯·锤掌的动机","为什么解救被蛛网缠住的受害者","阿拉米斯为什么要完成这件事"}}},fp="23,388,18.444.0,18.480.0,44.104.0,36.90.0,51.201.0,40.137.0,63.169.0,43.194.0"}
P.entries["quest:98391"] = {n="The Sisterhood of Elune",s="The Sisterhood of Elune是一个入门任务，引导冒险者前往达纳苏斯会见艾奎恩妮。作为暗夜精灵社会主要的精神权威，The Sisterhood of Elune需要外界迅速提供援助，以应对领地内日益严峻的挑战。",h="The Sisterhood of Elune是一个入门任务，引导冒险者前往达纳苏斯会见艾奎恩妮。作为暗夜精灵社会主要的精神权威，The Sisterhood of...",kw={"艾奎恩妮","达纳苏斯","艾露恩","女祭司","the sisterhood of elune","泰达希尔"},ang={["class:Priest"]="卡多雷文化中的祭司身份等同于对艾露恩的虔诚，而回应艾奎恩妮则直接与神殿的崇高传统相连。",["faction:Alliance"]="达纳苏斯作为卡利姆多联盟的重要首都，协助The Sisterhood of Elune能确保暗夜精灵精神与公民治理的稳定。",["race:NightElf"]="The Sisterhood of Elune是暗夜精灵社会与领导层的精神核心，对于任何星之子而言，回应她们的召唤是一项神圣的职责。"},sec={{t="首都的召唤",b="“The Sisterhood of Elune”是一份召唤令，指引冒险者前往暗夜精灵的首都达纳苏斯寻找艾奎恩妮。作为艾露恩信徒的代表，女祭司们经常会向可靠的勇士发出呼唤，请他们协助处理影响族人和圣地的紧急事务。"},{t="向艾奎恩妮报到",b="当你抵达达纳苏斯并找到艾奎恩妮后，她会为你如此迅速地赶到而深感欣慰。她的欢迎意味着你正式开始为The Sisterhood of Elune服务，也表明女祭司们正面临日益繁重的需求，需要来自她们隐修圈之外的可靠帮手。"}},faq={{q="艾奎恩妮是谁？",a="艾奎恩妮是服务于达纳苏斯城内The Sisterhood of Elune的一名特使和女祭司。她负责接待那些前来协助教团处理暗夜精灵所面临紧急事务的旅者。",al={"艾奎恩妮是谁","艾奎恩妮 达纳苏斯","艾奎恩妮在哪里"}},{q="什么是The Sisterhood of Elune？",a="The Sisterhood of Elune是一个古老的暗夜精灵女祭司组织，她们致力于侍奉月之女神艾露恩。作为卡多雷文化中的精神向导、治疗者和领袖，她们负责监督族人的精神福祉与防卫工作。",al={"什么是the sisterhood of elune","the sisterhood of elune成员","暗夜精灵女祭司"}},{q="我需要去哪里完成这个任务？",a="你必须前往泰达希尔之上的暗夜精灵伟大首都达纳苏斯。艾奎恩妮会在城中等你，为你传达代表The Sisterhood of Elune的简报。",al={"the sisterhood of elune任务交付","the sisterhood of elune任务地点","the sisterhood of elune去哪接"}},{q="为什么The Sisterhood of Elune需要援助？",a="艾奎恩妮指出，The Sisterhood of Elune需要迅速的外界援助，以应对达纳苏斯及周边暗夜精灵领地所面临的紧迫麻烦。与她交谈将解锁更多代表她们执行的任务。",al={"为什么the sisterhood of elune需要帮助","the sisterhood of elune困境","the sisterhood of elune需要什么援助"}},{q="部落角色可以接受这个任务吗？",a="不能。The Sisterhood of Elune是暗夜精灵领导层的核心，且完全与联盟保持一致。达纳苏斯是联盟首都，因此该任务仅限联盟冒险者接取。",al={"部落能接这个任务吗","部落能否完成the sisterhood of elune"}},{q="谁领导着The Sisterhood of Elune？",a="泰兰德·语风大祭司是The Sisterhood of Elune的精神领袖，也是卡多雷民族的最高统帅，她在达纳苏斯的Temple of the Moon指引着她的姐妹们。",al={"谁领导the sisterhood of elune","the sisterhood of elune领袖","泰兰德 the sisterhood of elune"}}},fp="23,262,21.297.0,27.292.0,22.215.0,32.239.0,45.187.0,36.224.0,42.189.0,34.199.0"}
P.entries["quest:98392"] = {n="Darkness in the Glade",s="Darkness in the Glade是由哨兵阿瑞尼亚·碎云领导的一项调查，旨在调查从神谕林地的鸟身人身上收集到的受污染的皮带。从鸟身人女族长身上找回的护身符证实，恶魔般的魔苔腐蚀已经在泰达希尔的枝干中扎根。",h="Darkness in the Glade是由哨兵阿瑞尼亚·碎云领导的一项调查，旨在调查从神谕林地的鸟身人身上收集到的受污染的皮带。从鸟身人女族长身上找回的护身符证实，恶魔般的魔苔腐蚀已经在泰达希尔的枝干中扎根。",kw={"阿瑞尼亚·碎云","arysa","darkness in the glade","魔苔","gaedress","鸟身人","hatescreech","神谕林地","泰达希尔"},ang={["class:Druid"]="魔苔污染野生动物和皮革纤维的迹象表明，一种非自然的腐蚀正在影响世界之树的自然平衡。",["faction:Alliance"]="哨兵碎云代表了达纳苏斯的军事警惕，致力于识别威胁联盟领土的恶魔污染。",["race:NightElf"]="邪能腐蚀通过神谕林地等神圣枝干的蔓延，直接打击了卡多雷培育和保护泰达希尔的努力。"},sec={{t="受污染的纤维",b="在神谕林地宁静的树冠下，哨兵阿瑞尼亚·碎云注意到当地的鸟身人族群有些不对劲。从这些生物身上回收的皮带显示出一种直接编织在材料中的非自然污秽。碎云怀疑这不是普通的野兽侵略，而是恶魔入侵，因此在向达纳苏斯发出警报之前，她需要确凿的证据。"},{t="确认腐蚀",b="碎云指挥勇士们前往西部的巢穴，击败了该族群的女族长：Hatescreech、Windmistress Gaedress和Witchmother Arysa。每一位领袖都携带一枚带有其力量明显痕迹的护身符。在检查这些石头时，哨兵发现宝石中包裹着邪恶的绿色旋涡，这证实了魔苔正在积极地扭曲鸟身人，并渗入神圣的枝干中。"}},faq={{q="Darkness in the Glade是什么？",a="Darkness in the Glade是由哨兵阿瑞尼亚·碎云在神谕林地指挥的一项任务。在注意到鸟身人皮带中存在非自然的污秽后，她派遣冒险者从鸟身人领袖那里找回护身符，以核实这种折磨的来源。",al={"darkness in the glade是什么","darkness in the glade任务"}},{q="谁提供了这个任务？",a="哨兵阿瑞尼亚·碎云提供了这项任务。她驻守在神谕林地，守护着泰达希尔的枝干，并调查居住在那里的鸟身人之间出现的异常骚动。",al={"谁发布了darkness in the glade","神谕林地任务发布者"}},{q="为什么阿瑞尼亚想要鸟身人领袖身上的护身符？",a="哨兵碎云在从普通鸟身人身上获取的皮带中发现了受污染的纤维，因此需要进一步的证据。她怀疑鸟身人领袖所携带的珠宝揭示了这种蔓延的腐蚀的真实性质和起源。",al={"为什么要击杀鸟身人领袖","为什么要获取护身符","鸟身人护身符的原因"}},{q="哪些鸟身人领袖持有护身符？",a="这些护身符属于筑巢于西部的三位杰出领袖：Hatescreech、Windmistress Gaedress和Witchmother Arysa。",al={"哪些鸟身人持有护身符","神谕林地的鸟身人领袖"}},{q="是什么导致了林地中的腐蚀？",a="这种腐蚀源于魔苔。当阿瑞尼亚检查找回的护身符时，她识别出宝石中邪恶的绿色旋涡，确认魔苔正在污染该地区。",al={"是什么在腐蚀鸟身人","绿色旋涡是什么","林地黑暗的起源"}},{q="这种腐蚀是否出现在其他地方？",a="是的，哨兵碎云指出，有报道称魔苔正在使环境变得对暗夜精灵不利，这种情况也出现在幽影谷以及世界之树的其他枝干上。",al={"其他地方的魔苔","幽影谷是否受到腐蚀"}}},fp="21,273,14.379.0,18.410.1,30.255.0,21.184.0,52.224.0,37.125.0,44.185.0,43.179.0"}
P.entries["quest:98393"] = {n="The Great Cat Spirit",s="The Great Cat Spirit 是一项神圣的德鲁伊任务，召唤修行者前往月光林地的永夜港，去见德迪利特·星焰。在已经掌握了熊的形态之后，德鲁伊们受到召唤，要在塞纳留斯大人的祝福下，开始他们探索荒野中猫之视角的旅程。",h="The Great Cat Spirit...",kw={"猫之形态","塞纳留斯","德迪利特·星焰","德鲁伊训练","月光林地","永夜港","the great cat spirit"},ang={["class:Druid"]="这次召唤标志着德鲁伊在熊之外扩展对荒野形态掌握能力的重要试炼。",["race:NightElf"]="月光林地是卡多雷德鲁伊回应塞纳留斯所传授的古老教诲的祖地。",["race:Tauren"]="牛头人德鲁伊在塞纳里奥议会的共同指导下，与他们的暗夜精灵同胞一同自由前往永夜港。"},sec={{t="月光林地的召唤",b="在证明了自己已经掌握了持久的熊之形态后，心怀抱负的德鲁伊们发现自己再次受到了召唤，前往神圣的月光林地。德迪利特·星焰长老向这片土地发出了呼唤，邀请弟子们来到宁静的避风港——永夜港，开始他们与自然融合的下一阶段。德鲁伊们施展独特的精神魔法跨越遥远的距离，聚集在塞纳里奥智慧那宁静的核心之地。"},{t="猫之视角",b="当你抵达永夜港后，德迪利特·星焰会向塞纳留斯大人祈祷，在欢迎这位日益成长的弟子时，召唤出一道微弱的力量光环。他揭示了拥抱猫之视角的时刻已经到来，这是一种荒野中富有掠食性和敏捷性的形态。正如之前的试炼一样，德迪利特将开启理解之路，但具体如何去体现并传承这种猫之精神，则完全取决于修行者自己。"}},faq={{q="是谁在 The Great Cat Spirit 中召唤你？",a="你的德鲁伊训练师代表德迪利特·星焰召唤你，他是一位驻扎在月光林地隐秘避风港——永夜港的长老导师。",al={"谁给予 the great cat spirit 任务","德迪利特·星焰召唤"}},{q="德迪利特·星焰在哪里？",a="德迪利特·星焰居住在月光林地的中心定居点永夜港，可以通过德鲁伊的传送魔法到达。",al={"德迪利特·星焰在哪里","德迪利特·星焰位置"}},{q="面见德迪利特·星焰的目的是什么？",a="德迪利特准备引导你与自然的猫之形态进行沟通并加以理解，在你学习了熊之道后，继续你的精神进阶。",al={"德迪利特教授什么","猫形态训练任务"}},{q="为什么德迪利特要祈求塞纳留斯大人？",a="德迪利特在迎接你时祈求塞纳留斯大人，以此向这位半神，也是最初教导凡人自然与变形秘密的德鲁伊教派守护者表达敬意。",al={"为何提到塞纳留斯大人","塞纳留斯提及德迪利特"}},{q="德鲁伊如何为这项召唤前往月光林地？",a="每当导师召唤时，德鲁伊们会利用他们与自然沟通的天生精神能力，直接传送至月光林地。",al={"如何前往月光林地","德鲁伊传送至月光林地"}},{q="这种形态与熊之形态有何关联？",a="德鲁伊教义通过不同的视角来接触自然。新手首先要掌握熊那持久的力量，然后再进阶到猫那敏捷的掠食者心态。",al={"猫形态与熊形态背景故事","先学熊形态"}}},fp="20,299,24.440.0,26.441.0,42.143.0,38.137.0,50.156.0,41.166.0,51.134.0,47.184.0"}
P.entries["quest:98397"] = {n="To Darnassus",s="To Darnassus 是暗夜精灵德鲁伊与 The Great Cat Spirit 沟通之旅的终点。在月光林地向德迪利特·星焰证明了自己之后，你将被送回塞纳里奥区，学习掌握变身为猎豹形态的技艺。",h="To Darnassus 是暗夜精灵德鲁伊与 The Great Cat Spirit 沟通之旅的终点。在月光林地向德迪利特·星焰证明了自己之后，你将被送回塞纳里奥区，学习掌握变身为猎豹形态的技艺。",kw={"猎豹形态","塞纳里奥区","德迪利特·星焰","great cat spirit","玛斯雷·驭熊者","月光林地","泰达希尔","to darnassus"},ang={["class:Druid"]="这个任务标志着你开始在阴影中狩猎，使你能够通过猎豹形态直接引导 The Great Cat Spirit 的力量。",["faction:Alliance"]="联盟德鲁伊从月光林地的中立领土返回达纳苏斯，加强了他们家园的魔法防御。",["race:NightElf"]="返回达纳苏斯是对世界之树泰达希尔下由塞纳里奥议会所守护的暗夜精灵传统的致敬。"},sec={{t="返回塞纳里奥区",b="在月光林地接受德迪利特·星焰的指引并与 The Great Cat Spirit 沟通后，有抱负的暗夜精灵德鲁伊必须回到泰达希尔。星焰承认你已经证明了自己是一名合格的学生，并指引你回到你的首席导师玛斯雷·驭熊者身边，他正在达纳苏斯的塞纳里奥区树荫下等你。"},{t="猎豹的本性",b="抵达达纳苏斯后，玛斯雷·驭熊者承认你已经领悟了 The Great Cat Spirit 的智慧。在他看来，每一代德鲁伊都要面对由这个古老实体所设定的试炼，它既顽皮又致命。随着你与它的连接建立，你的精神也已准备就绪，玛斯雷将传授你变身为优雅猎豹形态所需的最终仪式。"}},faq={{q="这个任务的目的是什么？",a="这个任务结束了你与 The Great Cat Spirit 的试炼。在月光林地完成德迪利特·星焰交给你的任务后，他会指引你回到达纳苏斯的玛斯雷·驭熊者身边，让他教你如何变身为猎豹形态。",al={"为什么要做这个任务","to darnassus 目的","猎豹形态任务"}},{q="是谁让你回到达纳苏斯的？",a="德迪利特·星焰是一位居住在月光林地圣地永夜港的资深德鲁伊，在你获得 The Great Cat Spirit 的祝福后，他会交给你这个任务。",al={"谁开始这个任务","任务给予者"}},{q="我在哪里可以找到玛斯雷·驭熊者？",a="玛斯雷·驭熊者驻扎在塞纳里奥区，这是位于泰达希尔上达纳苏斯西北区的德鲁伊圣所。",al={"玛斯雷位置","驭熊者在哪里"}},{q="The Great Cat Spirit 有什么意义？",a="The Great Cat Spirit 是一种古老而野性的自然之灵，代表着敏捷而致命的掠食者。德鲁伊必须在获准引导其形态之前，赢得它的青睐，并理解它那顽皮与致命并存的双重本性。",al={"猎豹之灵传说","什么是 great cat spirit"}},{q="所有德鲁伊完成的试炼都是一样的吗？",a="根据玛斯雷·驭熊者的说法，虽然所有德鲁伊都必须通过 The Great Cat Spirit 授予的试炼才能掌握其形态，但每一代试炼的具体内容各不相同。",al={"德鲁伊试炼是否相同","世代试炼"}},{q="非暗夜精灵可以接这个任务吗？",a="这个特定的任务是为返回达纳苏斯的联盟暗夜精灵德鲁伊准备的。牛头人德鲁伊遵循他们自己的道路，在访问月光林地后会向他们自己的训练师汇报。",al={"这是联盟专属吗","牛头人能做吗"}}},fx={["5fd4c60a"]={q="德迪利特·星焰为什么让你返回达纳苏斯？",a="你已在月光林地的The Great Cat Spirit面前证明了自己的价值，在德迪利特·星焰的指导下进行的试炼也已完成。德迪利特的职责是监督你与古老精灵沟通；如今，你最初的训练师玛斯雷·驭熊者正在达纳苏斯等你，帮助你运用那些精神教诲，最终掌握猫形态的变形技艺。",al={"为什么要去达纳苏斯","德迪利特·星焰的动机","为什么返回玛斯雷那里"}}},fp="12,246,21.359.0,21.391.0,34.229.0,32.172.0,39.143.0,49.232.0,44.180.0,36.193.0"}
P.entries["quest:98398"] = {n="The Oracle Tree",s="The Oracle Tree是一个任务，在该任务中，一名有前途的冒险者被指引去与一棵有感知力的古树进行交流。通过寻找这棵树刻意脱落的一块树皮，旅行者们可以收到它令人舒心的心灵感应信息，并为即将到来的更艰巨的任务做好准备。",h="The Oracle...",kw={"oracle tree","oracle tree树皮","有感知力的树","脱落的树皮","心灵感应","the oracle tree"},ang={["class:Druid"]="德鲁伊天生就能与有感知力的植物生命和古树的声音产生共鸣，使得与The Oracle Tree的交流成为他们对自然崇敬的一种延伸。"},sec={{t="召唤更伟大的使命",b="The Oracle Tree是一棵睿智且有感知力的树，它守护着周围的环境，并指引那些证明了自己的勇气的旅行者。当它在世界上需要代理人时，它会特意在附近脱落一片树皮。注意到这一点的人会被召唤上前，这标志着他们初步的任务已经完成，更伟大的责任正在等待他们。"},{t="通过树皮进行心灵沟通",b="The Oracle Tree不会用普通的物理声音说话。相反，检查那片落下的树皮可以让这棵树直接触及寻求者的心灵。它的存在平静而舒缓，像微风拂过树冠一样拂过听者的心灵，无需说出一个字就能传达思想和愿望。"}},faq={{q="什么是The Oracle Tree？",a="The Oracle Tree是一棵古老且有感知力的树，能够与附近的人进行心灵感应交流。当它希望传达信息或分配任务时，它会脱落一块树皮来吸引值得信赖的冒险者的注意。",al={"什么是oracle tree","oracle tree背景故事"}},{q="The Oracle Tree如何交流？",a="The Oracle Tree不是用可听见的声音说话，而是通过心灵感应来传达它的思想。任何检查掉落树皮的人都会听到一个平静、舒缓的声音进入他们的脑海，就像微风拂过树叶一样。",al={"oracle tree如何说话","oracle tree交流方式"}},{q="为什么要寻找The Oracle Tree的树皮？",a="当树有需要处理的目标或职责时，它会专门脱落一片树皮。检查树皮是接收这棵树心灵感应指导的焦点。",al={"为什么要寻找树皮","掉落树皮的目的"}},{q="是谁指引你前往The Oracle Tree？",a="一位一直在观察你成就的当地监督者或看护人，他们意识到未来有更伟大的职责等着你。注意到刚脱落的树皮，他们会指引你接近这棵树以接受它的指导。",al={"谁指引你去oracle tree","oracle tree任务发布者"}},{q="任务“The Oracle Tree”的目的是什么？",a="该任务开启了一名有成就的旅行者与这棵树本身之间的接触。通过寻找树皮，你开启心灵去倾听树的信息，并了解它需要完成什么更伟大的任务。",al={"oracle tree任务目标","oracle tree想要什么"}},{q="在哪里可以找到The Oracle Tree的树皮？",a="脱落的树皮位于The Oracle Tree附近的地面上，等待着感知力足够敏锐、能听到其信息的人去检查。",al={"在哪里找到oracle树皮","树皮位置"}}},fp="15,263,24.358.0,26.358.0,24.230.0,37.225.0,47.190.0,35.216.0,49.203.0,36.149.0"}
P.entries["quest:984"] = {n="熊怪的威胁",s="“威胁有多大？”是一个由奥伯丁的特伦希斯给予联盟的任务。在目睹了熊怪的疯狂在泰达希尔蔓延后，这位暗夜精灵德鲁伊派遣斥候调查黑海岸当地的熊怪定居点，以确认这种同样的黑暗腐蚀是否已经跨越了海洋。",h="“威胁有多大？”是一个由奥伯丁的特伦希斯给予联盟的任务。在目睹了熊怪的疯狂在泰达希尔蔓延后，这位暗夜精灵德鲁伊派遣斥候调查黑海岸当地的熊怪定居点，以确认这种同样的黑暗腐蚀是否已经跨越了海洋。",kw={"亚米萨兰","奥伯丁","腐蚀","黑海岸","熊怪","泰达希尔","特伦希斯","威胁"},ang={["class:Druid"]="熊怪与自然和古老的荒野之灵有着深刻的联系，这使得他们突然陷入腐蚀成为致力于修复卡利姆多平衡的德鲁伊们极度担忧的问题。",["faction:Alliance"]="作为联盟进入卡利姆多北部大陆的主要门户，保护奥伯丁免受旷野威胁对于地区安全和后勤保障至关重要。",["race:NightElf"]="对于卡多雷来说，目睹像熊怪这样古老的盟友在第三次大战争后不久就屈服于非理性的黑暗，既是一场痛苦的悲剧，也是对神圣土地的迫在眉睫的危险。"},sec={{t="跨海阴影",b="卡利姆多北部的暗夜精灵长期以来一直与当地的熊怪部落保持着友好或和平的关系。然而，第三次大战争之后，某种奇怪的腐蚀开始侵蚀泰达希尔熊怪的心智，导致他们对曾经的盟友进行暴力绑架和野蛮攻击。驻扎在奥伯丁的德鲁伊特伦希斯担心，这种险恶的折磨并非仅限于世界之树，而是正在黑海岸迷雾笼罩的海岸线上，在大陆部落中积极蔓延。"},{t="风暴前夕",b="对亚米萨兰遗迹附近一个熊怪营地的侦察证实了特伦希斯最糟糕的怀疑。那里的熊怪表现出反复无常、充满敌意的侵略性，带有与困扰北方地区相同的腐蚀迹象。他们距离奥伯丁非常近，这使得他们从一个和平的旷野邻居，变成了一个威胁到联盟定居点的紧急防御隐患。"}},faq={{q="特伦希斯是谁？",a="特伦希斯是一位驻扎在沿海避风港奥伯丁的暗夜精灵德鲁伊。由于泰达希尔各地不断传来暗夜精灵遭到疯狂熊怪袭击和俘虏的消息，他致力于监控并压制整个黑海岸出现的威胁。",al={"特伦希斯 任务给予者","谁给予 威胁有多大","特伦希斯 奥伯丁"}},{q="为什么黑海岸的熊怪变得充满敌意？",a="特伦希斯已经在黑海岸看到了腐蚀的迹象，并怀疑熊怪可能受到了影响，就像泰达希尔的一些熊怪一样。他要求对这些营地进行调查，因为他还没有掌握到广泛传播的证据。",al={"为什么熊怪发狂","黑海岸受腐蚀的熊怪","熊怪腐蚀"}},{q="受腐蚀的熊怪营地在哪里？",a="营地位于黑海岸中部内陆，就在古老的上层精灵遗迹亚米萨兰的北面，奥伯丁的东南方。",al={"营地位置","熊怪营地在哪里","威胁有多大 位置"}},{q="这与泰达希尔发生的事件有什么联系？",a="在泰达希尔，几只受腐蚀的熊怪绑架并伤害了暗夜精灵哨兵和平民。特伦希斯在寻求确认黑海岸大陆是否面临同样的危机时，提到了那些最近的救援行动。",al={"泰达希尔的联系","泰达希尔熊怪","为什么特伦希斯提到泰达希尔"}},{q="向特伦希斯汇报后会发生什么？",a="向奥伯丁的特伦希斯报告任何腐蚀迹象。你返回后，他会揭晓对调查结果的回应。",al={"后续任务","威胁有多大的后续","任务延续"}},{q="为什么暗夜精灵如此担心奥伯丁附近的熊怪营地？",a="奥伯丁是联盟在大陆上的主要港口和补给生命线。如果深陷腐蚀、充满敌意的部落驻扎在触手可及的地方，贸易道路、侦察小队和城镇本身都将变得极易受到突然袭击。",al={"对奥伯丁的威胁","为什么关心熊怪"}}},fx={["0269df0a"]={q="特伦希斯为什么要完成这件事？",a="特伦希斯曾立誓，在他的暗夜精灵同胞不得不从泰达希尔的腐化熊怪手中获救后，不再让更多人流血。他已经察觉到黑海岸也出现了腐化的微弱迹象，担心这股瘟疫会在当地熊怪部族中悄然蔓延。他派你侦察那些营地，希望在更多人丧命前查明危险是否已逼近奥伯丁。",al={"特伦希斯的动机","为什么调查黑海岸的熊怪","特伦希斯为什么在意"}},["1e1a0eb0"]={q="你被派去调查谁？",a="你奉命侦察居住在黑海岸一带的熊怪部族。许多熊怪氏族曾与暗夜精灵和平共处，或过着隐居生活，但黑暗势力开始扭曲他们的心智，使他们陷入疯狂。特伦希斯派你检查他们的聚居地，确认这种疾病是否已在那些居住于奥伯丁附近的部族中扎根。",al={"我要调查谁","什么熊怪营地","目标是谁"}}},fp="17,284,22.502.0,17.381.1,17.245.0,50.218.0,42.141.0,45.214.0,47.115.0,68.246.0"}
P.entries["quest:98403"] = {n="Twisted Hatred",s="Twisted Hatred是泰达希尔的一个任务，旨在揭露梅伦纳斯领主背后的操纵者。冒险者们前往多兰纳尔西北方的大断崖，去直面邪恶的塞索尔，并在他那邪恶的阴谋蔓延至树冠之前消灭他那些被腐化的蜘蛛。",h="Twisted Hatred是泰达希尔的一个任务，旨在揭露梅伦纳斯领主背后的操纵者。冒险者们前往多兰纳尔西北方的大断崖，去直面邪恶的塞索尔，并在他那邪恶的阴谋蔓延至树冠之前消灭他那些被腐化的蜘蛛。",kw={"被玷污的蛛木蜘蛛","大断崖","多兰纳尔","梅伦纳斯领主","成熟的魔苔","萨特","塔隆凯·捷根","泰达希尔","twisted hatred","邪恶的塞索尔"},ang={["class:Druid"]="泰达希尔的自然蛛形纲生物被扭曲成污秽的巢群，这破坏了自然平衡，需要塞纳里奥保卫者们将其净化。",["faction:Alliance"]="协助塔隆凯·捷根可以保护多兰纳尔定居点，使其免受萨特阴谋在联盟位于卡利姆多的主要避难所中的蔓延。",["race:NightElf"]="泰达希尔是卡多雷复兴的新生心脏，大断崖本土野生动物中滋生的恶魔腐化，是对你们族人的直接侮辱与威胁。"},sec={{t="阴影中的操纵者",b="梅伦纳斯领主并非孤身一人行事的发现，揭示了泰达希尔荒野下涌动着更黑暗的暗流。在梅伦纳斯的身后站着邪恶的塞索尔，这位盘踞在此的萨特在森林的阴影中操纵着一切，企图破坏世界之树宁静的枝叶。"},{t="大断崖的污秽巢群",b="邪恶的塞索尔在多兰纳尔西北方一处名为大断崖的隐秘飞地中安身，并将注意力转向了泰达希尔本土的蛛形纲生物。通过将当地的蛛木蜘蛛扭曲成污秽的野兽，这名萨特试图将它们的毒液武器化，用于险恶的恶魔阴谋。塔隆凯·捷根派遣冒险者去猎杀这些巢群，并在腐化进一步蔓延之前夺取塞索尔手中的成熟的魔苔。"}},faq={{q="谁是邪恶的塞索尔？",a="邪恶的塞索尔是一名邪恶的萨特，他在泰达希尔策划着腐化。他指挥着梅伦纳斯领主，并将巢穴设在大断崖，通过扭曲本土蜘蛛并利用成熟的魔苔来包藏他险恶的阴谋。",al={"谁是塞索尔","邪恶的塞索尔","谁是那个萨特"}},{q="大断崖位于何处？",a="大断崖是泰达希尔上多兰纳尔西北方森林深处的一处隐秘区域，邪恶的塞索尔和他的污秽巢群就栖居于此。",al={"大断崖在哪里","大断崖位置","在哪里找到塞索尔"}},{q="为什么泰达希尔的蜘蛛会被玷污？",a="被玷污的蛛木蜘蛛是泰达希尔本土的蜘蛛，它们被邪恶的塞索尔所腐化。这名萨特扭曲了它们的心智和生理结构，意图收集它们的毒液来执行一个肮脏的恶魔计划。",al={"为什么蜘蛛会变异","什么是被玷污的蛛木蜘蛛","被玷污的蛛木蜘蛛背景"}},{q="谁是塔隆凯·捷根？",a="塔隆凯·捷根是一名驻扎在泰达希尔多兰纳尔村的暗夜精灵守卫，他会委派冒险者去铲除周围森林中的恶魔颠覆活动。",al={"谁发布了这个任务","塔隆凯在哪里","塔隆凯·捷根的作用"}},{q="什么是成熟的魔苔？",a="成熟的魔苔是邪恶的塞索尔所携带的一种具有腐蚀性的植物样本，塔隆凯·捷根试图寻找它，以进一步揭开这名萨特的真实动机以及他在泰达希尔正在进行的勾当。",al={"成熟的魔苔","为什么要收集魔苔","什么是魔苔"}},{q="梅伦纳斯领主是如何卷入其中的？",a="梅伦纳斯领主的所作所为并非出于孤立的恶意，而是在邪恶的塞索尔明确指使下进行的，这揭露了在泰达希尔内部运作的一个有组织的萨特阴谋。",al={"梅伦纳斯的关联","谁是梅伦纳斯领主","梅伦纳斯与塞索尔"}}},fp="14,273,18.291.0,31.408.1,26.227.0,27.169.0,43.188.0,27.178.0,28.194.0,30.171.0"}
P.entries["quest:98404"] = {n="The Great Windborne Cat Spirit",s="The Great Windborne Cat Spirit是摆在德鲁伊新秀面前，关于狡诈与潜行的神圣试炼。受试者必须进入附近的Stormrage Barrow Den，在避开敌对、狂怒的灵魂的同时寻回三件古代圣物。通过这项灵性仪式，证明了受试者掌握了猫科动物潜行、凶猛和狡诈的美德，从而获得驾驭猫形态的祝福。",h="The Great Windborne Cat Spirit是摆在德鲁伊新秀面前，关于狡诈与潜行的神圣试炼。受试者必须进入附近的Stormrage Barrow...",kw={"saeyleenan的化身","猫形态","德鲁伊试炼","狂怒的灵魂","利爪圣物","尖牙圣物","静影圣物","saeyleenan","stormrage barrow den","the great windborne cat spirit"},ang={["class:Druid"]="对于学习引导野猫敏捷、潜行和捕食本能的德鲁伊来说，这项仪式是一个重要的里程碑。在灵魂赋予其变形祝福之前，必须证明自己具备狡诈和凶猛的特质。",["race:NightElf"]="Stormrage Barrow Den承载着最显赫的暗夜精灵德鲁伊家族之一的名字。探索其深处能让卡多雷修行者直接与古代兽穴遗产以及他们人民的祖先灵魂相连。"},sec={{t="狡诈与潜行试炼",b="为了汲取The Great Cat Spirit的力量，志向者必须证明他们拥有捕食者的气质。与猫科动物达成真正的和谐需要理解狡诈与耐心，并要在受困时展现出爆发性的凶猛。灵魂不会轻易将天赋赐予那些仅是索求力量的人；相反，它会考验寻觅者是否能像荒野中的猫科猎手那样思考、行动和打击。唯有展现出这些内在特质，新秀才有望获得化身为猫的权利。"},{t="Stormrage Barrow Den",b="这项考验会将寻觅者送入附近Stormrage Barrow Den的阴暗之中，它位于灵魂化身的东面。在这些地下大厅深处存放着三件神圣信物：尖牙圣物、利爪圣物和静影圣物。然而，获取它们绝非易事。这座兽穴已然充斥着狂怒的灵魂，它们会对视野中的任何入侵者进行猛烈攻击。为了在洞穴中生存并抵达圣物所在地，寻觅者不能仅依靠蛮力，而必须在黑暗中小心潜行。"},{t="Saeyleenan的化身",b="这场试炼的核心是Saeyleenan的化身，这是The Great Windborne Cat Spirit与年轻新秀沟通的实体显现。考虑到未经训练的寻觅者缺乏老练捕食者那种与生俱来的潜行能力，兽穴入口处的一座雕像会提供暂时的隐匿祝福。那些成功避开狂乱灵魂并带回全部三件圣物的人，证明了他们已经领悟了捕食者的课程。作为回报，化身会认可他们的资格，并赋予他们化身为猫形态所需的祝福。"}},faq={{q="谁是The Great Windborne Cat Spirit？",a="The Great Windborne Cat Spirit是一位野性守护者，指引年轻的德鲁伊掌握猫科动物变形术。它通过Saeyleenan的化身显现，体现了狡诈、潜行和凶猛这些核心的捕食者美德。它并不会随意赋予其形态，而是通过神圣试炼来考验志向者，以确保他们尊重猫科动物的捕食本能与天性。",al={"the great windborne cat spirit","saeyleenan是谁","cat spirit背景故事"}},{q="什么是Saeyleenan的化身？",a="Saeyleenan的化身是The Great Windborne Cat Spirit的实体存在与发言人。化身位于Stormrage Barrow Den的西面，负责监督该地区的德鲁伊试炼。它指派寻觅者执行找回被盗或隐藏的兽穴圣物的任务，并评估新秀是否展现出足够的潜行和狡诈来赢得猫科动物的祝福。",al={"saeyleenan的化身","saeyleenan的化身是谁","saeyleenan npc"}},{q="试炼需要哪些圣物？",a="试炼需要从Stormrage Barrow Den内找回三件特定的圣物：尖牙圣物、利爪圣物和静影圣物。这些神器共同象征着定义猫灵形态的核心物理武器与难以捉摸的潜行能力，证明了新秀对捕食者每一面的敬畏。",al={"三件圣物","利爪圣物","stormrage barrow den圣物"}},{q="Stormrage Barrow Den位于何处？",a="Stormrage Barrow Den位于Saeyleenan的化身东面。这些地下室是德鲁伊试炼的试验场，存放着三件神圣圣物。新秀必须深入这些黑暗的大厅，同时避开在隧道中游荡的危险的狂怒灵魂。",al={"stormrage barrow den位置","barrow den在哪里","哪里寻找圣物"}},{q="为什么狂怒的灵魂在守卫兽穴？",a="Stormrage Barrow Den已被强大的狂怒灵魂所占据，它们会攻击视野中的任何活体入侵者。这些敌对实体并非自愿的守卫者，而是兽穴内活跃的危险，这迫使德鲁伊志向者必须利用狡诈与潜行来取回圣物，而不是进行直接战斗。",al={"灵魂为何狂怒","barrow den的狂怒灵魂","barrow den守卫"}},{q="寻觅者如何潜行穿过狂怒的灵魂？",a="立在Stormrage Barrow Den入口处的一座石像会给予寻觅者暂时的潜行祝福。由于年轻的新秀尚未获得自身固有的猫形态或潜行能力，这种防护附魔使他们能够未被察觉地溜过警惕的敌对灵魂，从而获取圣物。",al={"如何在barrow den潜行","石像潜行增益","如何避开狂怒灵魂"}},{q="完成试炼后会获得什么奖励或祝福？",a="在交回尖牙圣物、利爪圣物和静影圣物后，Saeyleenan的化身会认为寻觅者有资格获得The Great Windborne Cat Spirit的祝福。这项仪式标志着新秀对猫科动物真实本性的理解，赋予他们化身为捕食者形态所需的灵性认可。",al={"试炼奖励","从cat spirit获得什么","cat spirit的祝福"}}},fp="30,389,32.527.0,24.549.0,24.577.0,38.385.0,33.383.0,39.359.0,42.302.0,48.345.0,46.323.0,61.330.0"}
P.entries["quest:98407"] = {n="Show of Force",s="Show of Force是赤脊山的一项联盟防御任务，由菲尔顿副队长发布。为了阻止在湖畔镇附近不断逼近的豺狼人族群，冒险者们受命猎杀豺狼人剥皮者并收集它们的尖刺项圈，以震慑这些试图侵入人类定居点的生物。",h="Show of Force是赤脊山的一项联盟防御任务，由菲尔顿副队长发布。为了阻止在湖畔镇附近不断逼近的豺狼人族群，冒险者们受命猎杀豺狼人剥皮者并收集它们的尖刺项圈，以震慑这些试图侵入人类定居点的生物。",kw={"菲尔顿副队长","豺狼人剥皮者","豺狼人","湖畔镇","赤脊山","show of force","尖刺项圈"},ang={["class:Warrior"]="豺狼人只屈服于直接而彻底的暴力——这使得直接的前线武力镇压成为打破它们防线的理想方法。",["faction:Alliance"]="湖畔镇是联盟在南部东部王国最靠东的堡垒之一；确保其边界免受野兽侵袭对于区域稳定至关重要。",["race:Human"]="赤脊山的农场主和镇民是暴风城的臣民，他们处于极其危险的境地，没有任何保护，只能依靠他们的同胞来击退这些狂野的掠夺者。"},sec={{t="大胆的侵袭",b="赤脊山长期以来一直庇护着狂野的豺狼人部落，但它们现在变得愈发猖狂。豺狼人劫掠小队不再只是在崎岖的丘陵高处与世隔绝，而是在距离湖畔镇和外围人类家园极其危险的地方建立了营地。随着暴风城的军事力量捉襟见肘，无法为农村边境提供援军，当地当局必须依靠过往的冒险者来保卫边境，防止这些侵袭小队聚集胆量袭击城镇本身。"},{t="它们的语言",b="菲尔顿副队长深知豺狼人是残忍且毫无组织的生物，除了绝对的武力压制外，它们几乎什么都不怕。要迫使它们退回荒野，外交手段或折中办法毫无用处。菲尔顿试图打击它们最凶猛的先锋——豺狼人剥皮者——并收获它们的尖刺项圈，作为支配地位的冷酷证明。通过击溃它们的前线战士并展示它们的失败战利品，湖畔镇的守卫者希望以此威慑幸存的族群，让它们撤回高地。"}},faq={{q="谁提供了这个任务？他们位于哪里？",a="该任务由菲尔顿副队长提供，他是一名驻扎在赤脊山湖畔镇附近外围的城镇守卫。",al={"任务发布者","菲尔顿副队长位置","谁发布show of force"}},{q="为什么豺狼人会逼近湖畔镇？",a="豺狼人是极具侵略性的机会主义者，它们会不断试探自己的边界。由于湖畔镇在防守上面临压力，且几乎没有得到暴风城的军事援助，豺狼人变得胆大妄为，直接在人类定居点外建立了狩猎营地。",al={"豺狼人为何攻击","赤脊山豺狼人威胁","为什么豺狼人靠得这么近"}},{q="为了这个任务，需要击败哪些敌人？",a="该任务的目标是豺狼人剥皮者，它们是当地豺狼人族群中更危险、更具侵略性的突击战士，佩戴着沉重的尖刺项圈。",al={"哪些豺狼人","需要击杀什么怪物","豺狼人剥皮者"}},{q="为什么菲尔顿副队长特别想要尖刺项圈？",a="豺狼人依靠残酷的等级制度和原始力量生存。夺取剥皮者的尖刺项圈是一种直接的力量展示，旨在恐吓幸存的豺狼人，迫使它们撤回山丘。",al={"为什么要尖刺项圈","项圈的用途","为什么要拿走项圈"}},{q="暴风城能提供士兵来对付豺狼人吗？",a="暴风城在很大程度上任由赤脊山自生自灭。由于王国国内局势动荡且各处兵力短缺，暴风城几乎没有派遣任何增援部队，迫使当地副队长不得不依靠独立的勇士。",al={"暴风城对赤脊山的援助","为什么没有暴风城军队","守卫在哪里"}},{q="豺狼人通常在赤脊山的什么地方扎营？",a="豺狼人营地散布在止水湖周围的丘陵和低矮山脊上，以及通往东部石堡区域的道路沿线。",al={"豺狼人营地","在哪里找到豺狼人","赤脊山豺狼人位置"}}},fp="13,284,19.520.0,23.530.0,49.120.0,49.244.0,50.136.0,56.214.0,55.228.0,52.149.0"}
P.entries["quest:98423"] = {n="The Treaty of Understanding",s="谅解条约是一块古老的矮人石板，详细记载了三锤之战后铜须部族与蛮锤部族之间达成的历史性和平协议。这件文物从地底深处被发掘出来，并被带到了国王麦格尼·铜须面前，它不仅保存了矮人历史上关键的一刻，也突显了黑铁部族因这场和平协议被排斥在外而留下的深刻裂痕。",h="谅解条约是一块古老的矮人石板，详细记载了三锤之战后铜须部族与蛮锤部族之间达成的历史性和平协议。这件文物从地底深处被发掘出来，并被带到了国王麦格尼·铜须面前，它不仅保存了矮人历史上关键的一刻，也突显了黑铁部族因这场和平协议...",kw={"黑铁部族","铁炉堡","madoran bronzebeard","magni bronzebeard","和平条约","谅解条约","三锤之战","蛮锤部族"},ang={["faction:Alliance"]="铜须矮人和蛮锤矮人之间历史性的和平，奠定了他们在现代大联盟中合作的基础。",["race:Dwarf"]="这块石板是矮人和解的有形记录，展示了你的先祖们如何在争夺山脉的战争结束后，放下了他们的宿怨。"},sec={{t="矮人的一件和解遗物",b="Recovered from deep within an ancient vault, the Treaty of Understanding is a historic stone tablet documenting the formal cessation of hostilities between dwarven clans. Dating to the turbulent aftermath of the War of the Three Hammers, it represents the moment peace was forged between the Bronzebeard and Wildhammer clans after the Bronzebeards secured control of Ironforge mountain."},{t="未签署的和平",b="当这块被找回的石板呈现在国王麦格尼·铜须面前时，他认出这是他的祖先，第一位铁炉堡铜须国王Madoran Bronzebeard的作品。虽然这份文件上有铜须和蛮锤领袖的签名，但显然缺少了黑铁部族的印记，这也成了黑铁部族与他们的山中同胞之间持久裂痕的永久见证。"}},faq={{q="什么是谅解条约？",a="谅解条约是一块从深层金库中发掘出来的古老矮人石板。它记录了三锤之战结束后，铜须部族与蛮锤部族之间达成的正式和平协议。",al={"什么是谅解条约","条约石板","这是什么条约"}},{q="谁制定了该条约？",a="该条约是在三锤之战结束后，由第一位在三部族争夺铁炉堡控制权后统治铁炉堡的铜须国王Madoran Bronzebeard在位期间起草的。",al={"谁写了谅解条约","谁制作了谅解条约","谁起草了条约"}},{q="黑铁部族为什么没有签署该条约？",a="在铜须部族夺取了铁炉堡的控制权后，黑铁部族拒绝接受和平。因此，只有铜须部族和蛮锤部族签署了该协议，导致黑铁部族被孤立并怀恨在心。",al={"为什么黑铁没有签署","黑铁签署了条约吗","黑铁不在条约上"}},{q="谁对谅解条约感兴趣？",a="这块石板被送到了铁炉堡High Seat的国王麦格尼·铜须手中，他将其视为先祖Madoran和矮人历史上无价的遗物。",al={"谁想要这个条约","我把谅解条约交给谁","在哪里上交条约"}},{q="什么是三锤之战？",a="三锤之战是铜须、蛮锤和黑铁这三个矮人部族之间为争夺铁炉堡的控制权而进行的一场残酷内战。铜须部族最终获胜，夺取了铁炉堡，而其他部族则被赶走。",al={"什么是三锤之战","矮人内战","三锤战争"}},{q="Madoran Bronzebeard是谁？",a="Madoran Bronzebeard是国王麦格尼·铜须的祖先，也是三个矮人部族内战后，第一位统治铁炉堡的铜须国王。",al={"madoran bronzebeard是谁","madoran bronzebeard","麦格尼的祖先madoran"}}},fp="27,406,33.386.0,18.411.0,36.252.0,23.210.0,47.215.0,49.162.0,38.254.0,28.166.0"}
P.entries["quest:98459"] = {n="A Lack of Virtue",s="“A Lack of Virtue”是一个送信任务，讲述了两名玩牌的水手——“半鱼”汤姆和巴特·潮汐水手之间经久不息的小摩擦。旅行者们带着一份包裹好的礼物跨越海洋来到米奈希尔港，却意外卷入了两人关于“少女的贞洁号”是如何得来的互相指控之中。",h="“A Lack of...",kw={"a lack of virtue","巴特·潮汐水手","少女的贞洁号","米奈希尔港","扑克","塔纳利斯","汤姆·半鱼","汤姆的礼物","湿地"},ang={["faction:Alliance"]="路过米奈希尔港的联盟旅行者经常会遇到正在对船员咆哮的巴特·潮汐水手，这使得送信成为了在等待横跨无尽之海的交通工具时的一个小插曲。"},sec={{t="苦涩的积怨",b="“A Lack of Virtue”的核心是两位老练的海上赌徒之间尖锐的竞争：汤姆·半鱼和巴特·潮汐水手。汤姆招募过往的旅行者将一个包裹送过海面交给米奈希尔港的巴特，以此作为对这位前同伴尖酸刻薄的嘲弄。一路上，汤姆警告说巴特根本不是真正的海员，而是一个曾经靠在牌局中出老千来买下船只指挥权的演员。"},{t="摊牌",b="当在米奈希尔港的码头上收到“汤姆的礼物”时，巴特·潮汐水手一听到他这位老相识的名字就勃然大怒。巴特立即反唇相讥，发誓说出老千的其实是汤姆，而且只有在他们的牌局将“半鱼”踢出去之后，他才赢得了足够的金币买下“少女的贞洁号”。尽管脾气爆发，巴特还是很快控制住了自己，为对送信人发火表示了歉意，并欢迎旅行者来到港口。"}},faq={{q="巴特·潮汐水手是谁？",a="巴特·潮汐水手是停靠在米奈希尔港的“少女的贞洁号”的自封船长。据他的老相识汤姆·半鱼所说，巴特原本是一名演员，他是用玩牌赢来的钱买下了这艘船——尽管两人都指责对方玩牌出老千。",al={"巴特·潮汐水手是谁","巴特·潮汐水手背景故事","少女的贞洁号的船长是谁"}},{q="汤姆·半鱼是谁？",a="汤姆·半鱼是巴特·潮汐水手的一位老相识，他给旅行者一份礼物，让他们带过海面交给巴特。他怀着对这位船长的强烈积怨，声称巴特是个骗子、吝啬鬼，还是个玩牌的老千。",al={"半鱼是谁","汤姆·半鱼是谁","谁发布了a lack of virtue任务"}},{q="“少女的贞洁号”是什么？",a="“少女的贞洁号”是一艘停靠在湿地米奈希尔港的船只。巴特·潮汐水手声称这是无尽之海最棒的船，尽管汤姆·半鱼贬损说这艘船航行的最远距离也就像塔纳利斯的一块石头那么远。",al={"什么是少女的贞洁号","少女的贞洁号船只","少女的贞洁号在哪里"}},{q="“汤姆的礼物”是什么？",a="“汤姆的礼物”是汤姆·半鱼寄给米奈希尔港巴特·潮汐水手的一个包裹。虽然送货人不知道里面的具体内容，但收到礼物后，巴特立即就汤姆本人打扑克出老千的问题破口大骂。",al={"什么是汤姆的礼物","汤姆的礼物里面有什么","为什么巴特对汤姆的礼物感到生气"}},{q="到底是谁在打扑克时出老千？",a="两位水手都激烈地指责对方出老千。汤姆·半鱼坚称巴特是个只靠出老千赢牌买船的演员，而巴特则声称只有在将汤姆踢出他们的牌局之后，他才名正言顺地赢得了自己的船只。",al={"谁在打扑克时出老千","巴特打扑克时出老千了吗","汤姆打扑克时出老千了吗"}},{q="如何将礼物送到米奈希尔港？",a="旅行者可以乘坐跨越无尽之海的船只到达湿地的米奈希尔港。任务发布者指出，一班直达船在米奈希尔港有停靠。",al={"如何前往米奈希尔港","前往米奈希尔港的船"}}},fp="16,307,15.452.0,18.486.1,22.281.0,21.231.0,28.229.0,19.251.0,30.269.0,47.179.0"}
P.entries["quest:98461"] = {n="Unrequited Love",s="Unrequited Love是联盟的一项送信任务，起始于Darkshore岸边的奥伯丁。Hollee请求搭乘船只前往米奈希尔港的旅人将一封私人信件交给塔雷尔·石纹，他是她曾经的考古学同学，她至今对他怀有默默的爱慕。",h="Unrequited Love是联盟的一项送信任务，起始于Darkshore岸边的奥伯丁。Hollee请求搭乘船只前往米奈希尔港的旅人将一封私人信件交给塔雷尔·石纹，他是她曾经的考古学同学，她至今对他怀有默默的爱慕。",kw={"奥伯丁","darkshore","考古","hollee","霍莉的便笺","米奈希尔港","merrin","塔雷尔·石纹","unrequited love","wetlands"},ang={["faction:Alliance"]="这次运送将Darkshore的联盟港口奥伯丁与Wetlands的米奈希尔港直接连接起来，连通了卡利姆多和东部王国。",["race:Dwarf"]="塔雷尔·石纹和Hollee都有考古背景，这是矮人传统和Azeroth学术研究的核心职业。"},sec={{t="跨海传书",b="在Darkshore多雾的海岸边，海港小镇奥伯丁，Hollee注视着登上前往东部王国船只的旅人。她寻求路人的帮助来联系一位老同学塔雷尔·石纹，在毕业将他们分隔在不同的大陆之前，他们曾一起学习多年的考古技艺。"},{t="未诉说的情感",b="虽然Hollee深情地回忆起塔雷尔敏锐的头脑和考古技能，但一提到他的妻子Merrin，她的神情就会变得不自然。尽管相隔遥远且他已婚，Hollee还是将一封私人信件托付给了一位冒险者，请求他们前往米奈希尔港附近寻找塔雷尔，以确认他是否平安。"}},faq={{q="谁发布了Unrequited Love任务？",a="Hollee在Darkshore的沿海定居点奥伯丁发布了这个任务。她请求搭乘前往米奈希尔港船只的旅人将一封私人便笺交给一位老同学。",al={"谁发布了unrequited love","奥伯丁的任务发布者"}},{q="塔雷尔·石纹是谁？",a="塔雷尔·石纹是一位考古学家，也是Hollee以前的同学。学业结束后，他被派往Wetlands，现在和他的妻子Merrin一起在米奈希尔港附近工作。",al={"塔雷尔·石纹是谁","塔雷尔相关传说"}},{q="Merrin是谁？",a="Merrin是塔雷尔·石纹的妻子。Hollee在提到她时显得犹豫不决且眉头紧锁，这揭示了尽管塔雷尔已经结婚，她对他仍有挥之不去、未得到回应的感情。",al={"merrin是谁","塔雷尔的妻子"}},{q="为什么任务叫Unrequited Love？",a="这个标题指的是Hollee对塔雷尔·石纹那份默默的情感。尽管他们作为亲密的同学一起学习考古，但塔雷尔娶了Merrin，留下了Hollee在远隔重洋的奥伯丁独自思念。",al={"unrequited love任务内容","为什么叫unrequited love"}},{q="塔雷尔·石纹在哪里？",a="塔雷尔·石纹可以在Wetlands的米奈希尔港附近找到，这里与Darkshore隔着无尽之海。从奥伯丁出发的客船可以将旅人直接送达港口码头。",al={"在哪里找到塔雷尔·石纹","塔雷尔所在的wetlands"}},{q="这个任务要传送什么物品？",a="你被要求携带霍莉的便笺去交给塔雷尔·石纹，以确认他在Wetlands的近况并传达她的私人信息。",al={"你要送什么","hollee的信"}}},fp="15,272,24.318.0,17.299.0,37.180.0,25.188.0,14.182.0,40.208.0,35.183.0,37.134.0"}
P.entries["quest:98463"] = {n="Talk of the Town",s="一位友好的酒保指引那些渴望热闹聚会的旅客前往位于荆棘谷的藏宝海湾。如果想要寻找更狂野的同伴，则被告知去Salty Sailor Tavern寻找尼克斯拉克斯·菲拉马克。",h="一位友好的酒保指引那些渴望热闹聚会的旅客前往位于荆棘谷的藏宝海湾。如果想要寻找更狂野的同伴，则被告知去Salty Sailor Tavern寻找尼克斯拉克斯·菲拉马克。",kw={"藏宝海湾","地精酒馆","尼克斯拉克斯·菲拉马克","salty sailor tavern","荆棘谷","talk of the town"},sec={{t="柜台间的消息",b="消息在酒保和顾客之间流传得很快，并且传得很远。一位友好的酒保透漏了哪里正在酝酿真正的骚乱，指引任何寻找更狂野场面的人前往藏宝海湾。"},{t="咸水帆船",b="目的地是Salty Sailor Tavern，这是一间由地精在熙熙攘攘的荆棘谷中经营的热闹场所。在那里，尼克斯拉克斯·菲拉马克为每一位走进店里的客人斟满酒杯。"}},faq={{q="这会带你到哪里？",a="这会带你前往荆棘谷，直达地精经营的港口城镇藏宝海湾。",al={"我要去哪里","目的地","藏宝海湾指引"}},{q="在藏宝海湾应该去找谁？",a="你被指引去Salty Sailor Tavern寻找尼克斯拉克斯·菲拉马克，他会在那里为大家斟满酒杯。",al={"要拜访谁","尼克斯拉克斯是谁","尼克斯拉克斯·菲拉马克"}},{q="为什么要让人跑那么远去荆棘谷？",a="酒保总能从客人的闲谈中听到各种流言，据说Salty Sailor Tavern有着附近最狂野的庆祝活动，无论是否由地精管理。",al={"为什么去咸水帆船","为什么要前往藏宝海湾","为什么有此推荐"}}},fp="16,221,25.271.0,16.199.0,21.84.0,42.117.0,51.166.0"}
P.entries["quest:985"] = {n="熊怪的威胁",s="“威胁有多大？”是一个联盟任务，由奥伯丁的暗夜精灵特伦希斯提供。在已经侦察过镇子南面的敌对黑木熊怪营地后，冒险者被派去消灭受腐化的探路者和风语者，以免他们的疯狂威胁到定居点。",h="“威胁有多大？”是一个联盟任务，由奥伯丁的暗夜精灵特伦希斯提供。在已经侦察过镇子南面的敌对黑木熊怪营地后，冒险者被派去消灭受腐化的探路者和风语者，以免他们的疯狂威胁到定居点。",kw={"奥伯丁","黑木","黑海岸","魔苔","熊怪","格里姆克劳","探路者","特伦希斯","风语者"},ang={["class:Druid"]="德鲁伊对此悲剧感触尤深，因为熊怪的困境反映了森林在魔苔污染下所遭受的持续痛苦。",["faction:Alliance"]="奥伯丁是联盟在黑海岸的重要港口据点，因此清除附近的敌对营地对于确保该地区的安全至关重要。",["race:NightElf"]="对于暗夜精灵来说，清理黑木熊怪是一种痛苦的悲哀；与熊怪数百年的亲族关系因第三次战争残留的恶魔枯萎病而破碎。"},sec={{t="必要的清理",b="在对奥伯丁南部进行初步侦察后，哨兵部队判定黑木熊怪对黑海岸的难民和守卫者构成了直接威胁。特伦希斯指派有战斗能力的旅行者直接突袭他们的营地，消灭黑木探路者和风语者，以打破他们的攻势。"},{t="受腐化者的悲剧",b="暗夜精灵传统上将熊怪视为精神上的亲族和荒野的历史盟友。然而，魔苔和恶魔污染在卡利姆多北部的恶性蔓延导致黑木部落陷入疯狂。由于目前没有已知的补救措施可以恢复熊怪的神智，奥伯丁的守卫者们将暴力视为防止无辜死亡的冷酷必要手段。"},{t="格里姆克劳的到来",b="在向特伦希斯汇报清理任务后，一只名叫格里姆克劳的白熊冲进奥伯丁，奔向那名暗夜精灵。它的到来标志着蹂躏海岸线的野生动物和腐化问题出现了紧急的新进展，开启了奥伯丁防御工作的下一阶段。"}},faq={{q="特伦希斯为什么要消灭黑木熊怪？",a="奥伯丁南部的黑木部落已经堕入腐化，变得暴力且失去理智。由于他们的营地对定居点构成了迫在眉睫的威胁，且目前尚未发现针对这种腐化的治疗方法，特伦希斯下令发动先发制人的打击以确保奥伯丁的安全。",al={"为什么要消灭黑木熊怪","熊怪清理的原因","特伦希斯的熊怪任务"}},{q="黑木熊怪营地在哪里？",a="营地位于奥伯丁以南，沿着黑海岸的沿海森林，坐落在黑木部落聚集的受腐化树木之中。",al={"黑木熊怪的位置","探路者和风语者在哪里","黑海岸的熊怪营地"}},{q="格里姆克劳是谁？",a="格里姆克劳是一只与黑海岸荒野调查相关的白熊。",al={"奥伯丁的白熊","熊格里姆克劳"}},{q="是什么导致熊怪发疯？",a="熊怪受到了魔苔和第三次战争后残留的恶魔腐化的毒害。蹂躏黑海岸的黑暗能量扭曲了它们的心智和身体，驱使原本爱好和平的部族陷入无法控制的狂暴之中。",al={"为什么熊怪会发疯","黑海岸熊怪的腐化","是什么腐化了黑木部落"}},{q="为什么暗夜精灵不愿杀害熊怪？",a="熊怪和暗夜精灵分享着数千年的友谊和对自然的崇敬。对暗夜精灵来说，杀死它们就像是在屠杀自己的荒野兄弟，但腐化让他们别无选择。",al={"暗夜精灵与熊怪","为什么要哀悼熊怪"}},{q="“威胁有多大？”任务的第一阶段和第二阶段有什么区别？",a="第一个任务通过要求你定位并观察黑木营地来测试侦察能力。第二个任务则是一项直接的战斗任务，在威胁确认后，旨在削减营地中的探路者和风语者数量。",al={"“威胁有多大”的组成部分","“威胁有多大”的区别"}}},fx={["0dbe6a0f"]={q="黑木探路者和风语者是什么人？",a="他们是黑木熊怪部族的成员，在奥伯丁南边建立了一处营地。森林腐化不断蔓延，使他们陷入疯狂并变得好斗；他们的斥候和萨满对暗夜精灵的聚居地构成了迫在眉睫且日益加剧的威胁。在找到治愈他们的方法之前，特伦希斯认为，削减他们的人数是保护族人的唯一办法。",al={"黑木探路者","黑木风语者","我们要杀谁"}},a17cffed={q="为什么特伦希斯派冒险者去，而不是派奥伯丁的哨兵？",a="特伦希斯转而求助于一位旅行者，此人此前已证明自己擅长侦察黑木营地。他想知道这位旅行者是否也准备好与部族交战，降低奥伯丁面临的威胁。",al={"为什么派我去","为什么不用卫兵","特伦希斯为什么需要我"}}},fp="17,277,16.332.0,24.358.0,18.281.1,54.277.0,44.150.0,16.84.1,39.227.0,47.250.0,79.225.0"}
P.entries["quest:98512"] = {n="Al'Aketh Assassins",s="Al'Aketh Assassins 是一个要求消灭一群危险杀手的任务。冒险者需要协助一名斥候消除威胁，并获得将要在给瓦拉纳尔的报告中提到的正式表彰。",h="Al'Aketh Assassins 是一个要求消灭一群危险杀手的任务。冒险者需要协助一名斥候消除威胁，并获得将要在给瓦拉纳尔的报告中提到的正式表彰。",kw={"奥拉凯斯","刺客","杀手","任务","报告","瓦拉纳尔"},ang={["class:Rogue"]="面对像奥拉凯斯这样的致命杀手，需要具备同样致命的专注力和冷酷的精准度。"},sec={{t="致命威胁",b="Al'Aketh Assassins 在野外构成了致命威胁，当地斥候称他们为冷酷的杀手。他们无情的效率和协同作战的能力，使得任何与他们的冲突对当地斥候和旅行者来说都极其危险。处理他们的存在需要迅速果断的行动，以免他们先发制人。"},{t="向瓦拉纳尔报告",b="在消灭了敌对的奥拉凯斯部队后，一名盟军特工对你在面对如此危险的对手时幸存下来表示深感欣慰。为了感谢你及时的干预，这名斥候承诺将在发往瓦拉纳尔的官方报告中正式记录你的英勇援助。"}},faq={{q="什么是 Al'Aketh Assassins？",a="Al'Aketh Assassins 是一个任务，要求冒险者消灭一支致命的奥拉凯斯部队。他们构成的威胁十分严重，需要立即干预并提交正式报告。",al={"什么是 alaketh assassins","什么是这个任务","alaketh assassins 任务"}},{q="谁是奥拉凯斯刺客？",a="奥拉凯斯刺客被描述为冷酷的杀手，他们以协同作战的危险突击部队形式活动。他们致命的作风使他们成为野外严重的威胁。",al={"谁是奥拉凯斯","谁是奥拉凯斯刺客","奥拉凯斯杀手"}},{q="瓦拉纳尔是谁？",a="瓦拉纳尔是位于岛屿东南边缘的定居点，也是维和人员的基地。这名斥候计划在返回瓦拉纳尔时，将你的协助记录在报告中。",al={"谁是瓦拉纳尔","什么是瓦拉纳尔","向瓦拉纳尔报告"}},{q="为什么必须处理奥拉凯斯刺客？",a="奥拉凯斯刺客对该地区的特工和旅行者构成了致命且迫在眉睫的危险。消灭他们对于保护盟军并确保生存是必要的。",al={"为什么对付奥拉凯斯","为什么要击杀奥拉凯斯刺客","奥拉凯斯威胁"}},{q="处理完这些刺客后会发生什么？",a="在与刺客的冲突结束后，这名斥候准备向瓦拉纳尔报告，并承认了你在行动中提供的关键援助。",al={"alaketh assassins 之后发生了什么","下一个任务 alaketh","向瓦拉纳尔报告任务"}},{q="谁承认了你在击败刺客时提供的帮助？",a="该任务涉及一名驻扎在野外监视敌对势力动向的盟军特工。感谢你对致命刺客的干预，这名斥候记录了你的贡献，以供指挥部参考。",al={"谁发布了 alaketh assassins","谁是这名斥候","斥候报告瓦拉纳尔"}}},fp="18,221,15.370.0,21.289.0,27.207.0,31.177.0,16.178.0,46.178.0,46.164.0,53.200.0"}
P.entries["quest:98545"] = {n="Leonid's Letter",s="Leonid's Letter 是一个送信任务，指引旅行者深入幽暗城。由于与希尔瓦娜斯·风行者（Sylvanas Windrunner）过去的紧张关系，Leonid本人不愿进入被遗忘者首都，因此雇佣了一名中立的信使，将一封信送给驻扎在贸易区（Trade Quarter）的旧识地精 Glix Xizzix。",h="Leonid's Letter 是一个送信任务，指引旅行者深入幽暗城。由于与希尔瓦娜斯·风行者（Sylvanas...",kw={"黑暗女王","glix xizzix","leonid","失物招领","纳克萨玛斯","密封的信","希尔瓦娜斯","trade quarter","幽暗城"},ang={["faction:Horde"]="代表外来者进入被遗忘者首都，让部落冒险者可以轻松使用幽暗城贸易区的设施。",["race:Undead"]="Leonid 与黑暗女王的历史使他无法亲自踏入幽暗城，这突显了独立亡灵与希尔瓦娜斯忠诚者之间的政治紧张局势。"},sec={{t="外来者的差事",b="Leonid需要一名信使将一封密封的信件送到幽暗城的一位熟人手中。由于与希尔瓦娜斯·风行者过去存在的摩擦和紧张关系，Leonid选择不亲自踏入被遗忘者首都的大厅，而是委托一名路过的中立人员，在不引起警报的情况下通过城市守卫。"},{t="贸易区的旧识",b="收信人是 Glix Xizzix，一个在幽暗城贸易区做生意的机会主义地精。收到信件后，Glix 回忆起与 Leonid 一起在天灾军团的要塞纳克萨玛斯（Naxxramas）阴影下生存的往事。虽然对 Leonid 承诺的报酬感到惊讶和恼火，但 Glix 还是勉强从粗心的亡灵客户留下的失物招领中支付了酬金。"}},faq={{q="Leonid 是谁，为什么他不愿进入幽暗城？",a="Leonid 是一位经验丰富的士兵，与各派势力保持着微妙的关系。由于与希尔瓦娜斯·风行者之间复杂的过往，他避免直接进入幽暗城，而是依靠路过的冒险者为他送信给熟人。",al={"谁给了leonid的信","leonid bartholomew","leonid任务给予者"}},{q="Glix Xizzix 是谁？",a="Glix Xizzix 是一名驻扎在繁华的幽暗城贸易区的地精。他似乎在理发服务处附近经营，保留着健忘的亡灵顾客留下的失物招领。",al={"glix xizzix在哪里","谁是glix xizzix","幽暗城地精理发师"}},{q="Leonid 与黑暗女王之间有什么历史？",a="Leonid 承认他与被遗忘者的女妖之王希尔瓦娜斯·风行者之间有着“相当丰富的过往”。为了避免激怒她或她的守卫，他雇佣中立的第三方来处理他在城内的事务。",al={"leonid与黑暗女王的历史","leonid和希尔瓦娜斯"}},{q="Leonid 和 Glix 是怎么认识的？",a="Glix 记得 Leonid 是在对抗天灾军团的激烈战争中久经沙场的退伍军人，并回忆起可怕的要塞纳克萨玛斯向他们倾泻毁灭的岁月。",al={"glix xizzix与leonid和纳克萨玛斯","glix和leonid怎么认识的"}},{q="为什么 Glix 用失物招领中的物品作为报酬？",a="Leonid 告诉信使 Glix 会乐意给小费，但 Glix 并没有做出这种承诺。尽管不情愿，这位地精还是提供了从沙龙的失物招领中搜集到的、由健忘的被遗忘者客户遗留下的奇特小饰品。",al={"glix的任务奖励","为什么是失物招领"}},{q="这封信被送到了哪里？",a="这封信被带到了被遗忘者的首都幽暗城，直接送到了商人、工匠和地精在皇家药剂师学会和城市守卫的注视下进行交易的贸易区。",al={"leonid的信送到哪里","贸易区送信"}}},fp="15,315,20.328.0,33.404.0,47.259.0,19.218.0,44.236.0,39.175.0,51.231.0,30.227.0"}
P.entries["quest:98574"] = {n="Hallowed Memorandum",s="“神圣备忘录”是一份书面传唤，指示寒脊山谷中初出茅庐的侏儒牧师前往安威玛尔拜见布兰斯托克·卡德尔。它标志着他们精神修行的开始，将圣光描绘成一个非常适合侏儒的智力和好奇心的哲学谜题。",h="“神圣备忘录”是一份书面传唤，指示寒脊山谷中初出茅庐的侏儒牧师前往安威玛尔拜见布兰斯托克·卡德尔。它标志着他们精神修行的开始，将圣光描绘成一个非常适合侏儒的智力和好奇心的哲学谜题。",kw={"安威玛尔","布兰斯托克·卡德尔","寒脊山谷","丹莫罗","侏儒牧师","hallowed memorandum","圣光"},ang={["class:Priest"]="这份备忘录标志着寒脊山谷正式牧师教学的开始，向新晋的治疗者介绍了圣光的哲学。",["race:Gnome"]="接近圣光的侏儒在精神学习中带来了敏锐的智力和好奇心，将神圣的奥秘视为与信仰一起思考的谜题。"},sec={{t="前往安威玛尔的传唤",b="当在寒脊山谷协助盟友时，有前途的侏儒见习生会收到“神圣备忘录”，这是一份指导他们前往安威玛尔寻找布兰斯托克·卡德尔的入门信件。作为精神学习的号召，这张便条邀请有抱负的牧师开始他们在丹莫罗的正式教导。"},{t="信仰之谜",b="在出示备忘录后，布兰斯托克·卡德尔欢迎这位新手加入。他解释说，钻研圣光并非一项死板的技术工艺，而是一个需要好奇心、敏锐智力以及智力与情感和谐统一的深奥谜题。通过沉思和实践，学生们学会将这些神圣的奥秘引导为恢复性的修补和神圣的惩戒。"}},faq={{q="是谁寄送了“神圣备忘录”？",a="这份备忘录是由你在寒脊山谷附近协助时的一位当地盟友转交的，它源自居住在安威玛尔内的牧师训练师布兰斯托克·卡德尔。",al={"谁给了我备忘录","谁发送了神圣备忘录","便条从哪里来"}},{q="布兰斯托克·卡德尔是谁？",a="布兰斯托克·卡德尔是一位驻扎在寒脊山谷安威玛尔内的矮人牧师训练师。他指导初出茅庐的牧师了解圣光，并利用神圣的力量来治愈伤口或打击邪恶。",al={"布兰斯托克是谁","布兰斯托克·卡德尔 安威玛尔"}},{q="侏儒是如何看待圣光的？",a="布兰斯托克解释说，侏儒的好奇心和智力是理解圣光的天然途径。他鼓励人们将其视为一个结合了思想与情感的哲学谜题，而不是将其作为一种严格的技术工艺来对待。",al={"侏儒可以成为牧师吗","侏儒与圣光的联系","侏儒如何看待圣光"}},{q="布兰斯托克教导了关于圣光的什么内容？",a="布兰斯托克将圣光描述为不仅仅是一门精确的技术学科，而是一个谜题，它通过结合个人的思想和内在情感来提供实际的祝福和人生课程。",al={"根据布兰斯托克的说法什么是圣光","圣光之谜 布兰斯托克"}},{q="布兰斯托克提供哪些技能教导？",a="一旦牧师开始理解圣光，布兰斯托克就会提供指导，教导如何将这种力量直接引导为防御性的治疗祈祷和对邪恶者的神圣打击，以此换取微薄的捐赠。",al={"布兰斯托克教什么","牧师训练师能教什么"}},{q="在哪里可以找到布兰斯托克·卡德尔？",a="安威玛尔是位于丹莫罗寒脊山谷中心地带的中央堡垒和欢迎大厅，为矮人和来访的侏儒提供训练师和避难所。",al={"安威玛尔在哪里","布兰斯托克位置"}}},fp="19,298,21.309.0,20.398.0,33.184.0,25.205.0,38.246.0,42.193.0,45.208.0,37.168.0"}
P.entries["quest:98575"] = {n="Tainted Tablet",s="Tainted Tablet是试炼谷的一项初始任务，指引有志向的施法者前往大兽穴寻找纳托克。它展现了杜隆塔尔术士们务实而谨慎的思想，尽管过去留下了挥之不去的耻辱，但他们仍试图驾驭虚空来铸就自己的命运。",h="Tainted Tablet是试炼谷的一项初始任务，指引有志向的施法者前往大兽穴寻找纳托克。它展现了杜隆塔尔术士们务实而谨慎的思想，尽管过去留下了挥之不去的耻辱，但他们仍试图驾驭虚空来铸就自己的命运。",kw={"杜隆塔尔","纳托克","虚空","tainted tablet","大兽穴","试炼谷","术士"},ang={["class:Warlock"]="Tainted Tablet标志着杜隆塔尔的新手术士们正式被引荐给他们的训练师纳托克，并敦促他们驾驭虚空，而不是恐惧它。",["faction:Horde"]="虽然萨尔领导的新部落对恶魔腐化心存戒备，但潜伏在大兽穴等地方的施法者宣称，他们可以安全地驾驭虚空力量，从而为他们的人民确保未来。",["race:Orc"]="鉴于恶魔契约在德拉诺留下的灾难性遗产，练习邪能魔法在兽人中仍然备受争议，这迫使杜隆塔尔的术士们不得不保持秘密与大胆。"},sec={{t="黑暗的召唤",b="Tainted Tablet是传送给刚抵达试炼谷并开始旅程的见习施法者的一条铭文信息。这块石板经由不安的营地看守人之手，传达了纳托克的召唤，这位术士训练师在大兽穴的阴影角落里安了家。信件邀请读者放下普通的部落职责，去探索更深层、被禁忌的魔法洪流。"},{t="驾驭虚空",b="在回应召唤后，纳托克坦率地谈到了兽人和虚空之间动荡的历史。他认为，强者应当掌控自己的命运，而不是因为羞耻或恐惧而放弃这些不稳定的能量。在他眼中，当传统的酋长们举步维艰时，能够以狡诈手段驾驭虚空实体的施法者将会脱颖而出。然而，由于恐惧者往往会轻易攻击他们无法理解的事物，他警告说，必须时刻严加守护这种力量。"}},faq={{q="什么是Tainted Tablet？",a="Tainted Tablet是传达给试炼谷见习施法者的一份书面召唤。它指示他们去寻找他们的职业训练师纳托克，他就在大兽穴内等候。",al={"什么是tainted tablet","tainted tablet任务","石板的目的"}},{q="谁发送了Tainted Tablet？",a="这块石板由纳托克发送，他是一位驻扎在试炼谷大兽穴内的兽人术士训练师。他用它来向新来的见习施法者介绍自己，并邀请他们接受指导。",al={"谁写了石板","纳托克是谁","谁发送了石板"}},{q="在哪里可以找到纳托克？",a="纳托克居住在大兽穴内，这是一处隐藏在试炼谷中的洞穴，人们在那里远离视线地练习黑魔法和专业技能。",al={"纳托克在哪里","大兽穴在哪里","如何找到纳托克"}},{q="为什么纳托克警告要严加守护你的力量？",a="纳托克告诫说，普通人会恐惧他们无法理解的力量，并经常在恐慌中反击。由于兽人在过去深受恶魔腐化的苦难，术士们必须守护好他们的技艺，并谨慎行事。",al={"为什么术士要隐藏","为什么守护力量","为什么术士要保密"}},{q="纳托克对练习邪能魔法有什么看法？",a="纳托克认为，当传统的领导者举步维艰时，那些掌握了虚空实体的人能够开辟自己的道路，掌握权力来塑造他们人民的命运，而不是成为命运的奴隶。",al={"纳托克的目标是什么","纳托克的哲学","为什么要使用虚空力量"}},{q="谁给了你Tainted Tablet？",a="试炼谷的一位当地任务发布者传递了这块石板，他公开承认对邪能施法者感到不安，但同时也认识到传递纳托克的召唤是必要的。",al={"谁递交了石板","谁把石板交给我"}}},fp="14,296,14.424.0,21.513.0,27.188.0,28.199.0,26.146.0,50.226.0,46.203.0,33.181.0"}
P.entries["quest:98576"] = {n="Glyphic Parchment",s="Glyphic Parchment 是发给在“试炼谷”的法师新手的入门召唤函。这份书面信函由“高内克”转交，指引新手前往“大兽穴”附近的巨魔法师训练师“迈安”处，开始他们的奥术修行。",h="Glyphic Parchment 是发给在“试炼谷”的法师新手的入门召唤函。这份书面信函由“高内克”转交，指引新手前往“大兽穴”附近的巨魔法师训练师“迈安”处，开始他们的奥术修行。",kw={"奥术","杜隆塔尔","glyphic parchment","高内克","法师","迈安","大兽穴","试炼谷"},ang={["class:Mage"]="这封信标志着你正式被认可为一名 A Student of the Arcane，指引你前往“迈安”处开始学习并扩充你的法术书。",["faction:Horde"]="“试炼谷”的导师制确保了即使是奥术这种不稳定的技艺，也能通过纪律来培养，从而加强部落的未来。",["race:Troll"]="“迈安”代表了“暗矛巨魔”日益发展的奥术传统，她贡献出自己的宇宙见解来指导同胞巨魔和盟军新兵。"},sec={{t="学习的召唤",b="虽然新兵要在“杜隆塔尔”的当地害虫面前证明他们的身体素质，但那些拥有奥术天赋的人不能仅仅依靠蛮力。“高内克”会递交一份刻有符文的书面通知，指示法师新手去找“迈安”，由她负责部落新兵早期的魔法指导。"},{t="奥术之道",b="“迈安”驻扎在“大兽穴”入口外，磨练着年轻施法者的志向。她不主张鲁莽地释放原始魔法，而是强调耐心、时机和深思熟虑的智慧。在她的指导下，新手学会将宇宙视为可以编织的纤细丝线，而不是任其爆发的狂暴风暴。"}},faq={{q="谁寄出了 Glyphic Parchment？",a="这份羊皮纸是由位于“试炼谷”的“大兽穴”附近的法师训练师“迈安”发送的。“高内克”保管着这封信，一旦法师新手开始他们的试炼，他就会将其交给他们。",al={"谁写了 glyphic parchment","谁发送了这个","羊皮纸作者"}},{q="在哪里可以找到“迈安”？",a="“迈安”位于“杜隆塔尔”的“试炼谷”，和其他职业导师一起驻扎在“大兽穴”的入口外。",al={"迈安在哪里","迈安的位置","寻找迈安"}},{q="这个任务的目的是什么？",a="它旨在向法师新手介绍他们的职业训练师。与“迈安”对话将开启你对奥术艺术的正规指导，从而解锁新法术和基础训练。",al={"glyphic parchment有什么用","为什么要进行这个任务","任务目标"}},{q="“迈安”对魔法的哲学理念是什么？",a="“迈安”认为奥术魔法需要智慧、克制和审慎的耐心。一位有效的法师不会冲动行事，而是会仔细观察，并在精确的时刻以适当的反应进行攻击。",al={"迈安教什么","迈安的背景故事"}},{q="为什么一位巨魔会在“试炼谷”训练法师？",a="“试炼谷”欢迎年轻的兽人和“暗矛巨魔”加入部落。“暗矛巨魔”施法者，比如“迈安”，贡献出她们的智慧和对宇宙力量的掌控来教导初出茅庐的修行者。",al={"为什么有巨魔法师","巨魔与奥术","兽人地区的巨魔训练师"}},{q="谁把羊皮纸交给玩家？",a="“高内克”是位于“试炼谷”中央营地的主要试炼监督者，当你完成早期任务并返回他身边时，他会把羊皮纸交给你。",al={"谁给予了 glyphic parchment","高内克的任务"}}},fp="17,250,18.345.0,21.326.0,32.183.0,26.132.0,34.186.0,37.221.0,54.209.0,41.159.0"}
P.entries["quest:98581"] = {n="Archaic Rune",s="Archaic Rune是丹莫罗为新手矮人萨满提供的入门任务。这块神圣的石板上灌注了来自远古蛮锤铭文的元素之力，向年轻的入门者们展示了他们的元素传承。将这块石头送到安威玛尔的提奥·蛮锤手中，标志着他们正式开始学习大地、空气、火焰和水的之道。",h="Archaic...",kw={"安威玛尔","archaic rune","铜须","寒脊山谷","元素","萨满","提奥·蛮锤","蛮锤氏族"},ang={["class:Shaman"]="Archaic Rune代表了矮人萨满精神旅程的第一步，验证了他们的元素共鸣，并将他们引向其首位导师。",["faction:Alliance"]="蛮锤导师将萨满艺术带到丹莫罗扩大了联盟的精神修行，使元素传统与圣光之道得以并存。",["race:Dwarf"]="这枚符文标志着矮人氏族间一次重要的文化交流，蛮锤矮人与寒脊山谷的铜须同胞分享了他们古老的精神传统。"},sec={{t="古老的铭文",b="寒脊山谷的冒险新手在安威玛尔附近协助当地盟友后，会发现Archaic Rune。这块石头上刻有蛮锤氏族风格的独特文字，并且可以清晰地感受到其中充盈着远古的元素力量。这枚符文不仅是一件石刻遗物，更是一次元素试炼：只有那些对原始灵魂有着天生共鸣的人，才能解读其风化表面上镌刻的文字。对于那些能够解读这些文字的人来说，它提供了明确的指引，让他们前往附近矮人哨站寻求正式的教导。"},{t="丹莫罗的蛮锤智慧",b="在安威玛尔的大厅内，蛮锤萨满提奥·蛮锤接收了这块铭文石。世世代代以来，萨满元素之术主要由生活在风蚀山峰间的蛮锤氏族所保存。如今，这些传统已开始在铁炉堡和丹莫罗的铜须矮人中扎根。提奥·蛮锤成为了两个矮人文化之间的重要桥梁，他欢迎那些展现出与元素沟通天赋的年轻入门者，并为他们提供关于大地、空气、火焰和水之道的正式教导。"}},faq={{q="什么是Archaic Rune？",a="Archaic Rune是一块刻有古老蛮锤文字并灌注了元素之力的古代石板。它被分发给寒脊山谷中前途无量的新冒险者，作为对其精神潜力的初步考验。如果一名入门者拥有能够解读符文的内在感应，这就证实了他们召唤萨满之道的使命，并指引他们前往安威玛尔寻找训练师。",al={"archaic rune任务","这个符文是什么","archaic rune物品"}},{q="是谁雕刻了Archaic Rune？",a="符文上的铭文是采用蛮锤氏族的传统风格雕刻的。它由居住在安威玛尔内的蛮锤萨满提奥·蛮锤发出，他利用这块刻字石来识别并联系那些拥有与元素灵魂先天连接的新晋入门者。",al={"谁制作了archaic rune","符文起源","蛮锤符文制造者"}},{q="提奥·蛮锤是谁？",a="提奥·蛮锤是一名蛮锤矮人，也是驻扎在寒脊山谷安威玛尔内的萨满训练师。他来到丹莫罗是为了帮助分享其氏族祖传的萨满教义给铜须矮人，指导新的修行者学习大地、火焰、水和空气之道。",al={"提奥·蛮锤是谁","安威玛尔提奥·蛮锤","安威玛尔萨满训练师"}},{q="为什么蛮锤的教义要与铜须矮人分享？",a="虽然萨满艺术在过去很长一段时间里传统上一直由蛮锤氏族保存和守护，但这些元素修行之法最近也已转交到铜须矮人手中并开始普及。像提奥·蛮锤这样的导师挺身而出，教导铁炉堡的矮人如何与元素灵魂沟通并向其致敬。",al={"为什么矮人会成为萨满","铜须蛮锤萨满","矮人萨满背景故事"}},{q="我应该把Archaic Rune带到哪里？",a="符文必须交给位于寒脊山谷安威玛尔主营地内的提奥·蛮锤。向他呈交符文展示了你引导元素的能力，并能开启你后续基础萨满法术的训练。",al={"哪里交还archaic rune","archaic rune交还","寻找提奥·蛮锤"}},{q="解读符文意味着什么？",a="Archaic Rune中灌注了古代矮人文字的元素能量。只有对元素力量有着天生共鸣的入门者才能破译其文字。成功解读它证明了冒险者拥有成为真正萨满的自然天赋和精神准备。",al={"为什么我能读懂符文","符文含义","解读archaic rune"}}},fp="12,371,22.600.0,31.566.0,25.392.0,28.298.0,23.292.0,67.343.0,33.257.0,35.290.0"}
P.entries["quest:986"] = {n="失踪的主人",s="“失踪的主人”这一任务要求联盟冒险者收集材料，以协助寻找在黑海岸荒野中失踪的暗夜精灵沃科尔。奥伯丁的特伦希斯提出要编织一件附魔伪装斗篷来保护救援者，这需要从海岸最凶猛的月夜猛虎身上获取毛皮。",h="“失踪的主人”这一任务要求联盟冒险者收集材料，以协助寻找在黑海岸荒野中失踪的暗夜精灵沃科尔。奥伯丁的特伦希斯提出要编织一件附魔伪装斗篷来保护救援者，这需要从海岸最凶猛的月夜猛虎身上获取毛皮。",kw={"失踪的主人","奥伯丁","黑海岸","优质月夜猛虎毛皮","格里姆克劳","月夜猛虎","特伦希斯","沃科尔","急弯河"},ang={["class:Druid"]="德鲁伊们定能领会特伦希斯对月夜猛虎自然潜行能力的尊重，并将其野性本质转化为保护性的伪装。",["class:Hunter"]="猎人们会理解沃科尔与格里姆克劳之间的羁绊，以及追踪和猎杀黑海岸的雌雄猛虎所需的高超技巧。",["race:NightElf"]="搜寻沃科尔的过程，体现了暗夜精灵在黑海岸那未受开垦的荒野中，守护族人和野生伙伴的职责。"},sec={{t="深入荒野的搜寻",b="在追踪黑海岸沿岸的威胁时，奥伯丁的特伦希斯对沃科尔及其伙伴格里姆克劳的安危感到担忧。由于该地区充斥着好斗的掠食者和受到腐蚀的野生动物，深入南部地区向来极其危险。特伦希斯没有贸然派遣毫无防备的侦察兵，而是制定了一个计划：制作一件灌注了野性幻象的防护斗篷。"},{t="狮群之皮",b="为了编织一件能够迷惑黑海岸野兽的斗篷，普通的兽皮是不够的。特伦希斯需要专门从成年的雄性或雌性月夜猛虎身上获取优质月夜猛虎毛皮。这些强大的大猫在奥伯丁南部的林地，靠近急弯河一带游荡，一直延伸到灰谷的森林边缘。"},{t="精细的魔法",b="成品斗篷利用月夜猛虎的皮毛和自然附魔，让穿着者在搜寻沃科尔时能不受阻碍地穿过敌对区域。然而，特伦希斯警告说，这种幻象十分脆弱：进行剧烈活动或战斗会打破附魔，使搜寻者暴露在外。"}},faq={{q="沃科尔是谁？",a="沃科尔是一位在黑海岸南部荒野失踪的暗夜精灵侦察兵或追踪者。他的伙伴格里姆克劳和奥伯丁的特伦希斯正在寻找他的下落，从而引发了这次搜寻任务。",al={"沃科尔是谁","沃科尔背景故事","失踪的主人沃科尔"}},{q="谁提供了这个任务？",a="特伦希斯，一位驻扎在黑海岸奥伯丁定居点的暗夜精灵，在冒险者协助他处理了早先的当地问题后，便提供了这个任务。",al={"任务发放者","失踪的主人任务领取","特伦希斯位置"}},{q="在哪里可以找到雄性和雌性月夜猛虎？",a="这些成年的月夜猛虎在黑海岸南部游荡，特别是在急弯河河岸附近，以及更南边接近灰谷边界的地方。",al={"优质月夜猛虎毛皮位置","哪里寻找月夜猛虎","急弯河猫科动物"}},{q="这件斗篷有什么作用？",a="特伦希斯打算制作一件附魔斗篷，将穿着者隐藏起来，使其免受黑海岸敌对野兽的攻击，从而能够在不频繁引发战斗的情况下寻找沃科尔。",al={"斗篷有什么作用","特伦希斯斗篷","斗篷附魔"}},{q="为什么特伦希斯需要特定的毛皮？",a="特伦希斯说他需要五张优质毛皮，这些毛皮必须取自雄性或雌性月夜猛虎，这样才有足够的材料来制作斗篷。",al={"为什么是雄性和雌性猛虎","为什么要优质毛皮"}},{q="这种伪装斗篷有限制吗？",a="是的。特伦希斯警告说，这种附魔很脆弱。与他人交谈是允许的，但剧烈的互动或战斗会迅速驱散幻象。",al={"幻象会失效吗","斗篷限制"}}},fx={bc18541c={q="特伦希斯为什么要这么做？",a="特伦希斯十分担心自己的暗夜精灵同胞沃科尔。他在黑海岸南部危机四伏的荒野中失踪了；而忠诚的熊格里姆克劳则来到奥伯丁，为主人寻求帮助。特伦希斯不肯让你毫无防护地进入如此危险的地带，因此坚持先准备一件魔法伪装斗篷，确保你能安全找到沃科尔，不会被海岸上的掠食者撕碎。",al={"为什么帮助沃科尔","特伦希斯的动机","特伦希斯为什么要毛皮"}}},fp="13,298,23.399.0,18.341.0,14.304.0,14.185.0,21.154.0,49.157.0,30.179.0,39.123.0,43.157.0"}
P.entries["quest:98601"] = {n="A Difficult Path",s="“A Difficult Path”标志着被遗忘者圣骑士在丧钟镇正式开始训练。在处理了从墓穴中爬出来的无脑亡灵后，新觉醒的圣光勇士会被指引去见教堂里的Aramis Hammerhand，去面对在亡灵之躯中使用圣光之力的痛苦现实。",h="“A Difficult Path”标志着被遗忘者圣骑士在丧钟镇正式开始训练。在处理了从墓穴中爬出来的无脑亡灵后，新觉醒的圣光勇士会被指引去见教堂里的Aramis...",kw={"a difficult path","aramis hammerhand","祝圣卷轴","丧钟镇","被遗忘者圣骑士","圣光","暗影牧师萨维斯","提瑞斯法林地"},ang={["class:Paladin"]="这个任务代表了被遗忘者圣骑士的基础试炼，它将圣光之力定义为并非轻松的祝福，而是一场关于纪律和耐力的痛苦磨砺。",["race:Undead"]="对于被遗忘者来说，召唤圣光证明了虔诚与纪律可以在肉体死亡后依然存在，即使这种魔法会灼烧引导它的容器。"},sec={{t="一份发臭的卷轴",b="当一名刚刚苏醒的被遗忘者圣骑士清理完墓穴外的野性亡灵后，暗影牧师萨维斯会递交一份意想不到的物品。这份祝圣卷轴散发出的圣光能量如此强烈，以至于这位暗影牧师明显退缩了，并直截了当地让持有者走开。对于一个信奉暗影与腐朽的修行者来说，圣光本身的气息就像火焰一样灼人。"},{t="圣火的试炼",b="在丧钟镇那座饱经摧残的教堂里，坐镇着被遗忘者圣骑士训练师Aramis Hammerhand。其他种族可以自然且愉悦地运用圣光，但亡灵若想召唤圣光，则必须忍受灼烧般的剧痛。Aramis并未试图减轻这种痛苦：通过腐烂的躯体引导圣光之力是一种纯粹的折磨，但他要求他的弟子拥抱这种痛苦，而不是退缩，将其作为一种淬炼他们新得决心的熔炉。"}},faq={{q="为什么暗影牧师萨维斯不喜欢这份卷轴？",a="暗影牧师萨维斯致力于暗影魔法的研究，并保护着他的亡灵同胞。祝圣卷轴散发着纯粹的圣光能量，这从本质上对亡灵躯体有害，且会让暗影的修行者感到深深的不安。",al={"萨维斯 圣光卷轴","为什么萨维斯感到不安","暗影牧师对卷轴的反应"}},{q="被遗忘者真的能在不死亡的情况下使用圣光吗？",a="被遗忘者可以通过纯粹的意志力和信仰来运用圣光，但这会给他们带来剧烈的痛苦，尤其是在引导圣光治疗自己或他人时。这需要极强的精神耐力来维持引导。",al={"被遗忘者圣骑士背景故事","亡灵使用圣光","圣光会伤害被遗忘者吗"}},{q="谁是Aramis Hammerhand？",a="Aramis Hammerhand是驻扎在丧钟镇教堂的圣骑士训练师。他指导刚复活的被遗忘者圣骑士，教导他们如何在亡灵状态下忍受使用圣光的剧痛，并将其锻造成有效的武器。",al={"谁是aramis hammerhand","丧钟镇圣骑士训练师","aramis的角色"}},{q="这个任务在哪里进行？",a="任务开始于丧钟镇中心空地上的暗影牧师萨维斯，并在几步之遥的村庄废弃教堂内结束，Aramis Hammerhand就在那里。",al={"a difficult path在哪里","任务地点","丧钟镇教堂在哪里"}},{q="我必须阅读祝圣卷轴才能完成任务吗？",a="不需要，阅读卷轴并非完成目标的必要条件；直接与教堂内的Aramis Hammerhand交谈即可推进你的训练。",al={"阅读祝圣卷轴","是否需要阅读卷轴","跳过阅读卷轴"}},{q="为什么这条道路被称为“艰难的”？",a="这个名字反映了被遗忘者圣骑士残酷的修行之路。当圣光的其他战士从信仰中获得安慰与慰藉时，亡灵圣骑士每次施放祝福或打击敌人时，都必须忍受炽热的圣火在死尸躯体中奔涌的痛苦。",al={"为什么是艰难的道路","任务名称的含义"}}},fx={["6833d98f"]={q="暗影牧师萨维斯为什么要这么做？",a="萨维斯只是不想再看见圣光。你在清剿那些没有心智的天灾军团时，祝圣卷轴送到了你手中；它散发的光辉魔力自然令他那受暗影影响的感官不适。与其留在卷轴旁，或是应付一个刚踏上圣骑士之路的人，他让你去向自己的训练师阿拉米斯·锤手报到，好开始学习如何磨炼这门令你痛苦的信条。",al={"萨维斯为什么派我去找阿拉米斯","萨维斯的动机 困难的道路","萨维斯为什么给我卷轴"}}},fp="16,322,16.384.0,25.449.0,49.238.0,54.212.0,25.226.0,33.179.0,63.159.0,35.256.0"}
P.entries["quest:98738"] = {n="Blessings of the Great Windborne Cat Spirit",s="Blessings of the Great Windborne Cat Spirit 是一项成年礼任务，标志着受训者在与 Zephras 的 The Great Cat Spirit 交流后的回归。在吸收了野猫的潜行、速度和凶猛之后，受训者向 Dendrite 展示他们新觉醒的光环，以接受进一步的精神指导。",h="Blessings of the Great Windborne Cat Spirit 是一项成年礼任务，标志着受训者在与 Zephras 的 The Great Cat Spirit...",kw={"blessings of the great windborne cat spirit","猫形态","dendrite","德鲁伊","大猫灵","shen'dorei","潜行","zephras"},ang={["class:Druid"]="这个任务标志着掌握猫科掠食本能的一个重要里程碑，赋予了德鲁伊与猫沟通并化身为猫所需的潜行、速度和凶猛。",["race:Skyborne"]="灵魂特别认出受训者是年轻的 shen'dorei，并在他们学习驾驭野性力量时，从 Zephras 提供风与影的指引。"},sec={{t="与风之灵的沟通",b="Blessings of the Great Windborne Cat Spirit 标志着与 Zephras 的 The Great Cat Spirit 进行神圣沟通的顶峰。在寻找到这位风之守护者并赢得其青睐后，受训者回到 Dendrite 身边，展示他们已经内化了野猫的狡黠、掠食者的潜行和凶猛。"},{t="Dendrite 的教导",b="在获得祝福后展示自己时，Dendrite 会进行微妙的身体动作来解读受训者新觉醒的光环。Dendrite 感应到编织在他们灵魂中的猫科动物本能，承认这位候选人终于准备好集中精神，呼唤猫的真正形态。"}},faq={{q="什么是 Blessings of the Great Windborne Cat Spirit？",a="Blessings of the Great Windborne Cat Spirit 是一项成年礼任务，受训者在寻找并获得 The Great Cat Spirit 的祝福后，回到 Dendrite 身边完成他们的精神交流。",al={"这个任务是什么","猫的祝福任务","猫灵任务"}},{q="谁是 Dendrite？",a="Dendrite 是一位导师，他派遣受训者去与 The Great Cat Spirit 沟通。在他们返回后，他会引导仪式手势来感知这种转变，确认受训者是否已经吸收了引导猫科动物天性所需的潜行、速度和狡黠。",al={"谁是dendrite","dendrite背景"}},{q="谁是 The Great Cat Spirit？",a="The Great Cat Spirit 是位于 Zephras 的古老守护灵。它在受训者返回继续接受指导之前，会将精神恩惠、风的速度和掠食者的潜行赐予值得的受训者。",al={"什么是猫灵","大风之猫灵"}},{q="Zephras 位于何处？",a="Zephras 是 The Great Cat Spirit 的家园，也是有前途的受训者前往寻求建议、接受风与影的祝福并学习猫科形态基础知识的地方。",al={"zephras在哪里","猫灵位置"}},{q="为什么灵魂称呼受训者为 shen'dorei？",a="The Great Cat Spirit 直接称呼受训者为年轻的 shen'dorei，这指出了寻求与自然之灵交流并掌握野性变形的修行者的祖先传承。",al={"谁是shendorei","年轻的shendorei"}},{q="猫灵的祝福赋予了什么？",a="这种祝福赋予了猫科形态的狡黠、速度和潜行。在获得祝福后，受训者获得了 Dendrite 的认可，可以集中他们内心的凶猛并呼唤猫的真正本性。",al={"祝福赋予什么","猫灵祝福效果"}}},fp="43,313,35.325.0,22.316.0,52.216.0,16.273.0,28.216.0,25.187.0,55.199.0,47.214.0"}
P.entries["quest:98815"] = {n="Highland Hides",s="Highland Hides是由詹姆斯·哈洛兰委托的一份探险合同，他是一位在米奈希尔港工作的制皮师。为了从高地多雾的山地沼泽中寻求优质的材料，哈洛兰用精制的皮革制品来交换丛林迅猛龙坚韧的皮。",h="Highland Hides是由詹姆斯·哈洛兰委托的一份探险合同，他是一位在米奈希尔港工作的制皮师。为了从高地多雾的山地沼泽中寻求优质的材料，哈洛兰用精制的皮革制品来交换丛林迅猛龙坚韧的皮。",kw={"highland hides","高地","詹姆斯·哈洛兰","米奈希尔港","迅猛龙皮","制皮师","丛林迅猛龙","湿地"},ang={["class:Hunter"]="进入高地山地沼泽的猎人们会发现丛林迅猛龙这样的可怕野兽，它们坚韧的皮需要精准的追踪和干净利落的狩猎技巧。",["faction:Alliance"]="米奈希尔港是湿地的一个主要联盟港口，像詹姆斯·哈洛兰这样的商人们就在这里为前往周围危险沼泽的旅行者提供装备。"},sec={{t="制皮师的机会",b="詹姆斯·哈洛兰是一位在米奈希尔港口小镇工作的熟练制皮师，他一直在留意异域的制作材料。当听说有一支探险队正在高地探索被遗忘的遗迹时，哈洛兰没怎么去关注古代历史，反而更在意那些在山地沼泽中潜行的凶猛野兽。他敏锐地察觉到了这些野生动物的商业和制作价值，于是委托勇敢的冒险者深入迷雾笼罩的山峰，带回上等的毛皮。"},{t="高地的野兽",b="在高地潜伏的动物群中，丛林迅猛龙是以适应崎岖沼泽地形而闻名的掠食者。它们坚韧且纹理独特的皮深受工匠的喜爱，可用于专业的皮革加工。哈洛兰指派旅行者追踪这些生物，并带回四张完好的皮，他将用这些皮为自己工作室的作品制作精致的细节装饰和边缘饰品。"}},faq={{q="詹姆斯·哈洛兰是谁？",a="詹姆斯·哈洛兰是一位驻扎在米奈希尔港的当地制皮师和工匠。他从事皮革和油脂加工，寻找来自湿地和周围高地的奇异野兽的优质皮，以此来制作精美的饰边和护甲。",al={"谁发布了highland hides任务","詹姆斯·哈洛兰是谁","米奈希尔港的制皮师"}},{q="为什么詹姆斯·哈洛兰需要这些皮？",a="哈洛兰寻求丛林迅猛龙的皮，是因为它们出色的耐用性和纹理。他认为这些是他经手过的最好的皮革之一，并用它们为皮制品的饰边增添了惊人的细节。",al={"highland hides的用途","为什么詹姆斯需要迅猛龙皮","迅猛龙皮的用途"}},{q="在哪里可以找到丛林迅猛龙？",a="丛林迅猛龙栖息在高地的山地沼泽中，潜伏在探险队目前正在考察的古代遗迹附近的崎岖荒野中。",al={"丛林迅猛龙在哪里","丛林迅猛龙位置","迅猛龙在哪里"}},{q="哈洛兰提到的遗迹是什么？",a="高地拥有一处被遗忘的遗迹，目前正由一支探险队进行调查。虽然像哈洛兰这样的工匠关注的是野生动物，但学者和探险家们却深入研究了该地区的古代秘密。",al={"高地有什么遗迹","高地探险遗迹","谁在探索高地"}},{q="这次狩猎是为团队准备的吗？",a="哈洛兰建议带上装备精良的同伴。高地的山地沼泽栖息着凶猛的野生动物，这使得针对丛林迅猛龙这类掠食者的狩猎对于孤身一人的旅行者来说危机四伏。",al={"highland hides是否危险","highland hides需要组队吗","做highland hides需要同伴吗"}},{q="詹姆斯·哈洛兰提供什么交易？",a="为了换取四张原始的丛林迅猛龙皮，哈洛兰会提供他工作室定制的优质皮制品，让冒险者可以选择一件适合他们旅程的装备。",al={"哈洛兰交易什么","highland hides奖励背景"}}},fp="14,272,22.488.0,23.393.0,22.231.0,41.212.0,35.172.0,36.217.0,34.216.0,40.187.0"}
P.entries["quest:98824"] = {n="Prehistoric Prism",s="Prehistoric Prism是一个探索任务，引导冒险者将一件多面的泰坦圣物从湿地运送到铁炉堡。受勘察员维尔加所托，这件圣物被捐赠给了位于探险者大厅的高级探险家麦格拉斯，以推进探险者协会对古代守护者的研究。",h="Prehistoric Prism是一个探索任务，引导冒险者将一件多面的泰坦圣物从湿地运送到铁炉堡。受勘察员维尔加所托，这件圣物被捐赠给了位于探险者大厅的高级探险家麦格拉斯，以推进探险者协会对古代守护者的研究。",kw={"hall of explorers","高级探险家麦格拉斯","铁炉堡","prehistoric prism","勘察员维尔加","泰坦圣物","奥达曼","湿地"},ang={["faction:Alliance"]="捐赠发现的古代宝藏能直接丰富铁炉堡著名的探险者大厅的学术收藏。",["race:Dwarf"]="找回真正的泰坦圣物是矮人身份认同的核心，也是探险者协会揭示其制造者起源这一使命的关键。"},sec={{t="古老的发现",b="在勘测湿地时，勘察员维尔加发现了一件非凡的文物，其刻面上装饰着复杂的守护者铭文。这位矮人勘察员认识到，如此具有历史意义的发现应当交到学者手中，因此他极力敦促立即将其运送到矮人主城铁炉堡。维尔加希望这次发现能被正式编入目录，确保冒险者在圣物鉴定过程中获得应有的功绩。"},{t="博物馆的馈赠",b="在探险者大厅那充满传奇色彩的大厅内，高级探险家麦格拉斯代表探险者协会接收了这件圣物。这位首席考古学家对圣物上真实的制造者印记赞叹不已，并指出光线穿过其打磨过的刻面时呈现出的折射效果，让他回想起了自己早年在奥达曼挖掘时所见到的奇观。捐赠这件文物能将其妥善保存以供研究，从而扩充探险者协会不断增长的泰坦遗产记录。"}},faq={{q="谁发布了Prehistoric Prism任务？",a="勘察员维尔加在湿地鉴定了圣物刻面上发现的类似泰坦的铭文后，指引你将其送往铁炉堡。",al={"谁发布了prehistoric prism","prehistoric prism起始地点","prehistoric prism任务发布者"}},{q="你在哪里交付Prehistoric Prism？",a="你将这件圣物交付给位于铁炉堡探险者大厅的高级探险家麦格拉斯，他非常乐意将其收入博物馆的藏品中。",al={"prehistoric prism交付对象","prehistoric prism交付地点","prehistoric prism完成情况"}},{q="Prehistoric Prism是什么类型的文物？",a="这是一件古老的多面文物，带有明显的守护者印记。当被光照亮时，光线在其晶体结构中舞动的方式，令人想起在奥达曼出土的圣物。",al={"什么是prehistoric prism","prehistoric prism是否属于泰坦","什么是该圣物"}},{q="为什么探险者大厅对这个棱镜感兴趣？",a="探险者协会积极收集和编目泰坦起源的真迹。高级探险家麦格拉斯认为，这种级别的文物对于增进世界知识和理解古代历史至关重要。",al={"为什么麦格拉斯想要它","为什么要捐赠棱镜","探险者大厅棱镜"}},{q="这个棱镜与奥达曼有何关联？",a="在检查了文物的折射效果和守护者标记后，高级探险家麦格拉斯将其闪烁的光芒与他在奥达曼进行的第一次考古挖掘中所研究的圣物进行了比较。",al={"奥达曼是否与该棱镜有关","奥达曼联系","棱镜奥达曼"}},{q="你的名字会被记录在博物馆的目录中吗？",a="勘察员维尔加和高级探险家麦格拉斯确保你找回圣物的功绩被正式认可，并记录在探险者协会的历史档案中。",al={"prehistoric prism目录","你会被记录在案吗","历史功绩棱镜"}}},fp="17,294,20.472.0,20.438.0,38.150.0,43.143.0,47.205.0,53.223.0,37.186.0,54.171.0"}
P.entries["quest:98895"] = {n="Darkspear Islands Clash",s="Darkspear Islands Clash 是联盟的一项军事征召令，号召勇士们防守关键阵地，抵御凶猛的暗矛突袭者。如果前线得不到及时的支援，联盟将面临彻底失去这片争议群岛的风险。",h="Darkspear Islands Clash 是联盟的一项军事征召令，号召勇士们防守关键阵地，抵御凶猛的暗矛突袭者。如果前线得不到及时的支援，联盟将面临彻底失去这片争议群岛的风险。",kw={"联盟","战场","准将","暗矛群岛","darkspear islands clash","暗矛突袭者","荣誉印记"},ang={["class:Paladin"]="联盟的圣职战士们带着坚定的决心投入到激烈的冲突中，响应号召，保卫联盟的生命，击退敌对势力。",["class:Warrior"]="前线战士在抵御凶猛的巨魔突袭者时承受着巨大的压力，他们用铁的纪律和战场上的英勇扭转了战局。",["faction:Alliance"]="联盟最高指挥部依靠勇士志愿者来加强前线对抗暗矛突袭者，并保卫群岛上的战略阵地。"},sec={{t="争议前线",b="为了争夺暗矛群岛的控制权，联盟与好战的暗矛突袭者战团之间爆发了公开战争。联盟指挥官警告称，若无紧急援军，他们在群岛的立足点将会失守，因此发出了战斗征召，号召有能力的勇士前来抵挡敌人的攻势。"},{t="英勇的证明",b="联盟指挥层依靠那些愿意直接奔赴前线的实战勇士。为了确保纪律并嘉奖真正的英雄主义，指挥官要求战士们带回暗矛群岛荣誉印记，以此作为他们战斗服役的切实证明，表彰那些扭转战局的人。"}},faq={{q="什么是 Darkspear Islands Clash？",a="Darkspear Islands Clash 是由负责前线战事的联盟军官发布的一项军事征召令。联盟勇士的任务是与暗矛突袭者交战，并通过从战斗中收集荣誉印记来证明自己的贡献。",al={"什么是 darkspear islands clash","冲突任务","暗矛群岛之战"}},{q="谁是暗矛突袭者？",a="暗矛突袭者是争夺暗矛群岛控制权的巨魔战团。他们咄咄逼人的攻势威胁到了联盟在该地区的立足点，迫使最高指挥部发出紧急援军请求。",al={"谁是暗矛突袭者","暗矛突袭者敌人","我们在暗矛群岛对抗谁"}},{q="为什么联盟要在暗矛群岛作战？",a="联盟试图守住暗矛群岛的战略领土，防止该地区完全落入巨魔的控制之下。如果失去这片阵地，将危及联盟在这一争议海域的影响力和安全。",al={"为什么联盟在暗矛群岛作战","为什么要在这里作战","联盟暗矛战争"}},{q="谁来发布并完成这项任务？",a="一名驻扎在战场之外的联盟准将负责监督部队调动，并接收返程勇士提交的战场服役证明。",al={"谁发布 darkspear islands clash","谁收取暗矛荣誉印记","联盟准将位置"}},{q="什么是暗矛群岛荣誉印记？",a="荣誉印记是颁发给在前线表现出英勇和积极参与战斗的战士的军事代币。向联盟准将提交三枚此类印记，即是证明你战场贡献的确凿证据。",al={"什么是荣誉印记","暗矛群岛荣誉印记","如何证明前线服役"}},{q="如果联盟失败，会有什么后果？",a="如果没有迅速的增援，联盟在暗矛群岛的阵地将无法承受暗矛突袭者无情的压力而全面崩溃。守住群岛可以防止敌方部队确立对整个群岛的统治地位。",al={"如果联盟输掉暗矛群岛会发生什么","为什么需要紧急援助","失去暗矛群岛"}}},fp="23,242,17.337.0,14.308.0,32.280.0,30.215.0,54.233.0,38.161.0,42.236.0,39.257.0"}
P.entries["quest:98896"] = {n="Darkspear Islands Clash",s="Darkspear Islands Clash呼吁战士们集结同伴，击败那些争夺群岛的敌对暗矛突袭者。持续不断的战斗需要协同行动，以遏制敌人对争议岛屿链的入侵。",h="Darkspear Islands Clash呼吁战士们集结同伴，击败那些争夺群岛的敌对暗矛突袭者。持续不断的战斗需要协同行动，以遏制敌人对争议岛屿链的入侵。",kw={"冲突","暗矛群岛","暗矛突袭者","群岛冲突","集结","小规模冲突","巨魔突袭者"},ang={["faction:Horde"]="这是联盟一方为暗矛群岛进行的战斗，这些位于卡利姆多海岸外的神圣巨魔群岛一直被部落占据，以抵御所有外来者。",["race:Troll"]="对于巨魔冒险者来说，这份联盟指令所针对的暗矛突袭者正是沃金的族人，他们正在保卫自己部族的神圣岛屿。"},sec={{t="战火中的群岛",b="Darkspear Islands Clash代表了在争议不断的暗矛群岛内进行的一次主动军事推进。部署到该战区的部队被敦促坚守阵地，抵御一波又一波持续在海滩和内陆地区发动小规模冲突的暗矛突袭者。这场冲突并非孤立事件，而是确保在群岛中据点领土的持久战役的一部分。"},{t="集结前线",b="前线的指挥官们强调了组织和兵力对于战胜顽强突袭者的必要性。生存和胜利取决于将附近的盟友集结成一支有凝聚力的部队，这支部队必须有能力抵御反击、击溃筑防的突袭小队，并打破他们对争议岛屿据点的控制。"}},faq={{q="什么是Darkspear Islands Clash？",a="Darkspear Islands Clash是一项任务，呼吁冒险者们在暗矛群岛持续不断的冲突中集结盟友，并对敌对的暗矛突袭者发起进攻。",al={"任务简述","darkspear islands clash摘要","冲突任务信息"}},{q="这场战斗发生在什么地方？",a="这场小规模冲突发生在暗矛群岛各地，这是一片因激烈的领土争夺和持续的海上冲突而闻名的群岛。",al={"战斗发生地","暗矛群岛位置","冲突地点"}},{q="谁是暗矛突袭者？",a="暗矛突袭者是部落在暗矛群岛的巨魔守卫，这些群岛是沃金部族的神圣岛屿。指令要求战斗人员在他们争夺岛屿领土时击败他们。",al={"敌方是谁","对抗目标","暗矛突袭者目标"}},{q="为什么必须为这场冲突集结部队？",a="冲突需要召集和集结盟军部队，以抵御持续的反击并击破敌方突袭者的防线。",al={"为什么要集结部队","任务目标","如何完成冲突"}},{q="为什么暗矛群岛的战斗会持续不断？",a="部落和联盟在这些岛屿据点的争夺中陷入了僵局：部落将这里作为神圣的巨魔领地进行守卫，而联盟则试图在卡利姆多海岸外建立一个据点。",al={"为何开战","岛屿冲突原因","群岛战斗起因"}},{q="是谁在指挥这次交战的部队？",a="该指令由奥特兰克山脉的联盟准将发布，敦促地面士兵毫不动摇地向前推进。",al={"任务发布者","冲突任务发布人","冲突指挥官"}}},fp="23,244,22.393.0,23.328.0,36.187.0,33.138.0,30.209.0,42.141.0,53.198.0,42.147.0"}
P.entries["quest:99"] = {n="阿鲁高的愚行",s="“阿鲁高的愚行”是一项危险的调查任务，旨在探究困扰焚木村的诅咒。达拉尔·道恩维沃尔派遣部落特工从村民身上获取附魔镣铐，以解读大法师阿鲁高扭曲的杰作。解开这些束缚，就能揭示让这个定居点处于狼人阴影之下的悲剧魔法。",h="“阿鲁高的愚行”是一项危险的调查任务，旨在探究困扰焚木村的诅咒。达拉尔·道恩维沃尔派遣部落特工从村民身上获取附魔镣铐，以解读大法师阿鲁高扭曲的杰作。解开这些束缚，就能揭示让这个定居点处于狼人阴影之下的悲剧魔法。",kw={"阿鲁高","arugal's folly","达拉尔·道恩维沃尔","月怒狼人","焚木镣铐","焚木村","银松森林","瑟伯切尔"},ang={["class:Mage"]="对于奥术修行者来说，阿鲁高的镣铐是一个冷酷的提醒，告诫他们当肯瑞托的魔法与异界召唤的野兽混合时，可能会陷入何等的疯狂。",["faction:Horde"]="获得这些镣铐打破了阿鲁高对通往格雷迈恩之墙南下道路的神秘控制。",["race:Undead"]="被遗忘者以冰冷的着迷和无情的实用主义看待焚木村，渴望拆除阿鲁高的附魔以确保银松森林南部的安全。"},sec={{t="焚木村的双重生活",b="瑟伯切尔以南是焚木村，这是一个处于诡异存在状态的定居点。在白昼的阳光下，居民们像普通人类农民一样过着恐惧而封闭的生活。然而，当黄昏降临森林时，他们的人类形态就会撕裂，变成野蛮的月怒狼人，在阿鲁高的支配下在街上游荡。达拉尔·道恩维沃尔试图解开导致这种昼夜恐怖的精确奥术束缚。"},{t="粉碎镣铐",b="为了分析束缚焚木村的附魔，道恩维沃尔需要从变身的城镇居民身上直接取得附魔的“焚木镣铐”。这些枷锁并非简单的铁制品，它们震颤着阿鲁高失败结界的残余魔法。通过研究其奥术构成，这位被遗忘者法师希望理解这种野兽般变形的机制，并设法最终打倒影牙城堡的那位叛逃大法师。"}},faq={{q="为什么焚木村的人在晚上会变成狼人？",a="大法师阿鲁高在焚木村施加了扭曲的附魔。白天，他的咒语维持着人类的幻象或沉睡状态，但夜幕降临会导致城镇居民在他的控制下变身为月怒狼人。",al={"焚木村昼夜","焚木村诅咒","为什么白天是人晚上是狼"}},{q="什么是“焚木镣铐”？",a="它们是被诅咒的焚木村居民所佩戴的附魔束缚。阿鲁高将它们作为他控制该镇魔法的一部分，而达拉尔·道恩维沃尔则利用其残余能量来研究这一诅咒。",al={"焚木镣铐","阿鲁高镣铐"}},{q="达拉尔·道恩维沃尔是谁？",a="达拉尔·道恩维沃尔是一位驻扎在银松森林瑟伯切尔的被遗忘者法师。他负责领导被遗忘者对大法师阿鲁高召唤的狼人进行的魔法调查。",al={"达拉尔·道恩维沃尔背景故事","瑟伯切尔的任务发放者是谁"}},{q="完成这个任务能治愈焚木村吗？",a="不能。取回的镣铐为达拉尔·道恩维沃尔提供了理解阿鲁高魔法所需的奥术见解，但诅咒依然让焚木村处于永恒的折磨之中。",al={"焚木村可以被治愈吗","焚木村的人民会被治愈吗"}},{q="阿鲁高是如何控制村民的？",a="通过鲁莽的附魔和附魔镣铐，阿鲁高将村民束缚在他的意志之下，强迫他们变成守护他影牙城堡领地入口的野兽形态。",al={"阿鲁高与焚木村的联系","阿鲁高如何控制他们"}},{q="完成“阿鲁高的愚行”任务线后会发生什么？",a="此项任务标志着“阿鲁高的愚行”系列任务的最终章。所收集的情报使被遗忘者能够全面评估影牙城堡的威胁，并策划阿鲁高的垮台。",al={"阿鲁高的愚行之后","阿鲁高的愚行结局"}}},fx={["0ad90a3b"]={q="达拉尔·道恩维沃尔为什么想要焚木村的镣铐？",a="达拉尔·道恩维沃尔正在研究大法师阿鲁高施加于银松森林各处的奇异附魔。通过分析村民镣铐中束缚的魔法，达拉尔希望揭开阿鲁高所谓疗法的真相，掌握他狂乱法术的秘密，并收集至关重要的知识，最终击败这名疯狂的法师，解除他鲁莽施展的巫术。",al={"达拉尔为什么想要这个","达拉尔·道恩维沃尔的动机","为什么收集焚木村的镣铐"}}},fp="14,342,26.434.0,23.448.1,64.222.0,31.198.0,24.175.0,48.176.1,38.183.0,61.185.1"}
P.entries["quest:990"] = {n="灰谷之旅",s="“前往灰谷”是一项联盟的旅程任务，指引经验丰富的冒险者从黑海岸向南进入灰谷的原始森林。哨兵塞拉伊前来奥伯丁寻求援助，并指派旅行者前往阿斯特兰纳镇向莱恩·狼行者报到，当地的哨兵正努力对抗蔓延的腐蚀。",h="“前往灰谷”是一项联盟的旅程任务，指引经验丰富的冒险者从黑海岸向南进入灰谷的原始森林。哨兵塞拉伊前来奥伯丁寻求援助，并指派旅行者前往阿斯特兰纳镇向莱恩·狼行者报到，当地的哨兵正努力对抗蔓延的腐蚀。",kw={"灰谷","阿斯特兰纳","黑海岸","暗夜精灵","莱恩·狼行者","哨兵塞拉伊","前往灰谷"},ang={["faction:Alliance"]="作为一名联盟勇士，响应阿斯特兰纳的呼唤可以加强与暗夜精灵的联系，并巩固该阵营在卡利姆多北部的核心立足点。",["race:NightElf"]="对于暗夜精灵来说，这段旅程是回归卡利姆多的神圣中心地带，响应姐妹们的呼唤，保护古老圣地免受非自然腐烂的侵蚀。"},sec={{t="离开海岸",b="响应了哨兵塞拉伊在奥伯丁发出的援助请求后，旅行者们将告别阴郁灰暗的海岸和阴影笼罩的遗迹。哨兵认可那些拥有自保能力的强大战士和侦察兵，并直接指引他们前往暗夜精灵林地领土的中心地带。在解决了黑海岸的地方威胁后，注意力转向了从南方入侵的更严峻的危机。"},{t="通往阿斯特兰纳的路",b="向南的道路沿着一条古老的暗夜精灵之路蜿蜒而行，穿过灰谷茂密的古老树冠。驻扎在阿斯特兰纳的哨兵指挥官莱恩·狼行者发出了紧急的增援呼吁。在恶魔的玷污、猖獗的野生动物以及对祖地的外部入侵之间，阿斯特兰纳的哨兵们兵力不足，需要外部援助来维持对这片神圣森林的控制。"}},faq={{q="是谁让你踏上这段旅程？",a="哨兵塞拉伊，一位被莱恩·狼行者派往奥伯丁寻求帮助的暗夜精灵哨兵，指引你向南前往阿斯特兰纳。",al={"任务发布者","谁开启前往灰谷任务","塞拉伊"}},{q="莱恩·狼行者是谁？",a="莱恩·狼行者是常驻阿斯特兰纳的首席哨兵指挥官，负责组织灰谷的防御，并协调各方努力以遏制侵蚀森林的腐化。",al={"莱恩","狼行者","阿斯特兰纳领袖"}},{q="为什么要派冒险者去灰谷？",a="灰谷的古老森林正屈服于蔓延的腐化和日益增加的外部威胁。当地的暗夜精灵哨兵已不堪重负，迫切需要有能力的盟友来协助阿斯特兰纳的市民和保卫者。",al={"为什么去灰谷","灰谷发生了什么","灰谷腐化"}},{q="黑海岸和灰谷之间的道路安全吗？",a="哨兵塞拉伊特别建议紧贴大路行走。偏离路径深入森林会使旅行者暴露在徘徊于荒野边缘的凶猛掠食者、萨特和敌对势力面前。",al={"道路安全","灰谷道路安全吗"}},{q="到达阿斯特兰纳后我该做什么？",a="在直接向莱恩·狼行者报到后，她建议与阿斯特兰纳各处的其他居民和保卫者交谈，因为他们中有许多人需要即时的帮助来处理当地的危机。",al={"在阿斯特兰纳做什么","到达阿斯特兰纳"}},{q="这项任务适合什么等级的冒险者？",a="这段旅程通常标志着在19级左右从黑海岸毕业，将中级冒险者带入灰谷这个更广阔且充满争夺的前线。",al={"什么等级","等级要求"}}},fx={b4a50545={q="哨兵塞拉伊为什么要你去灰谷？",a="哨兵塞拉伊听命于莱恩·狼行者，后者负责监督阿斯特兰纳的防务和重建工作。随着腐化蔓延至灰谷的古老森林，当地哨兵已人手紧缺，压力沉重。塞拉伊会将黑海岸证明过实力的勇士直接引荐给她的上司，让有能力的人手立即着手缓解森林的困境。",al={"为什么派我去灰谷","塞拉伊的动机","为什么前往灰谷"}}},fp="17,339,17.409.0,21.425.0,27.126.0,24.193.0,44.232.0,49.209.0,44.192.0,46.171.0"}
P.entries["quest:99046"] = {n="The Lost Runner",s="The Lost Runner是一项搜寻哨兵艾露亚·影叶的任务，她是一位从The Oracle Tree出发、逾期未归的信使学徒。这项任务至关重要，因为这棵神圣之树与达纳苏斯的长老们之间的联络对于暗夜精灵的领导层来说必不可少。",h="The Lost Runner是一项搜寻哨兵艾露亚·影叶的任务，她是一位从The Oracle...",kw={"森林议会","达纳苏斯","艾露亚·影叶","神谕林地","the oracle tree","哨兵","the lost runner"},ang={["faction:Alliance"]="维护泰达希尔境内安全畅通的道路和通讯线路，有助于保障达纳苏斯和联盟领土的稳定。",["race:NightElf"]="确保古老的The Oracle Tree与达纳苏斯领导层之间的安全通讯，对于卡多雷的安全和精神指引至关重要。"},sec={{t="神谕者的信使",b="森林议会在泰达希尔受人尊敬的神谕林地中驻扎了一支哨兵小队。这棵树负责向暗夜精灵的长老们传达神圣的信息，并依靠忠诚的信使沿着蜿蜒的林间道路将这些信件送回达纳苏斯。确保这些信件安全送达，对于卡多雷的指引和统治至关重要。"},{t="逾期的信使",b="来自The Oracle Tree的信息传递时间并不固定，但如果信使久久未现身，这种异常的沉默会引起警觉。最近一次任务落在了哨兵艾露亚·影叶身上，她还是一名正在接受训练的学徒。她的上级担心她在路上遭遇了不幸，因此指示旅行者搜寻通往神谕林地的西向道路，以确定她的下落。"}},faq={{q="迷失的信使是谁？",a="失踪的信使是哨兵艾露亚·影叶，她是一位正在受训的暗夜精灵哨兵，任务是将来自The Oracle Tree的信息送往达纳苏斯。",al={"谁是迷失的信使","失踪的哨兵","谁是艾露亚"}},{q="什么是The Oracle Tree？",a="The Oracle Tree是位于神谕林地的一棵古树，它会定期向达纳苏斯的暗夜精灵长老传达信息，需要驻扎的哨兵安全地进行传递。",al={"什么是the oracle tree","神谕林地的目的","为什么要有来自the oracle tree的信息"}},{q="艾露亚·影叶要去哪里？",a="艾露亚原本应该出现在连接达纳苏斯和神谕林地的西向道路上，信使经常往返于该路段，传递来自该树的交流信息。",al={"艾露亚要去哪里","艾露亚的路线","迷失的信使位置"}},{q="是谁将哨兵驻扎在The Oracle Tree？",a="森林议会指派了一支哨兵分遣队前往The Oracle Tree，以确保信息能够安全、迅速地传达给达纳苏斯的长老们。",al={"谁派哨兵去the oracle tree","什么是森林议会"}},{q="为什么她的失踪令人担忧？",a="虽然来自The Oracle Tree的信息传递频率不固定，但她的缺席时间已经长得反常，考虑到她学员的身份，这引起了她上级的担忧。",al={"为什么她的延误不寻常","神谕多久发送一次信息"}},{q="这项搜寻任务的目标是什么？",a="你需要沿着通往神谕林地的西向小路前进，搜寻哨兵艾露亚·影叶，找出是什么延误了她的行程。",al={"在the lost runner中要做什么","the lost runner任务目标"}}},fp="15,238,24.380.0,18.378.0,23.164.0,24.189.0,36.160.0,47.157.0,29.162.0,37.141.0"}
P.entries["quest:99047"] = {n="Not Dead Yet",s="“Not Dead Yet”是Eralya发出的紧急呼救，她是一名受了致命伤的暗夜精灵，在前往The Oracle Tree的灾难性任务后被发现。她被凶残的鹰身人袭击，恳求过路人将她巡逻队遭遇的命运转达给多兰纳尔的Byancie。这凸显了泰达希尔林间小径上日益逼近的致命威胁。",h="“Not Dead Yet”是Eralya发出的紧急呼救，她是一名受了致命伤的暗夜精灵，在前往The Oracle...",kw={"byancie","多兰纳尔","eralya","鹰身人","not dead yet","the oracle tree","泰达希尔"},ang={["faction:Alliance"]="当外勤侦察兵被阻断并陷入重围时，探索泰达希尔的联盟冒险者受命将紧急消息带回多兰纳尔这样的定居点前哨。",["race:NightElf"]="倒下的信使Eralya和她的姐妹们是在泰达希尔服役的哨兵。目睹暗夜精灵守卫在神圣的The Oracle Tree附近遭到鹰身人伏击，这直接揭示了这片巨枝之上日益严重的威胁。"},sec={{t="遭到伏击的巡逻队",b="“Not Dead Yet”是泰达希尔荒野中的绝望呼救，故事围绕Eralya展开，她是一名受了伤的暗夜精灵信使，被发现时正流血不止，生命垂危。她与姐妹们一同被派往神圣的The Oracle Tree执行一项关键任务，但在途中遭到了入侵的鹰身人的暴力伏击并被屠戮。援军无望，且体力迅速衰竭，Eralya只能委托过路的旅行者将紧急消息带回安全地带。"},{t="呼唤多兰纳尔",b="Eralya大口喘着气，并不时咳血，她恳求玩家将她的报告带给附近多兰纳尔村的Byancie。那些盘踞在泰达希尔巨枝之上的鹰身人变得越来越大胆和具有攻击性，对那些试图穿越林间小径的独行信使和哨兵构成了致命威胁。传递Eralya的求救信息能确保多兰纳尔定居点在更多生命逝去之前，获知关于The Oracle Tree伏击事件的消息。"}},faq={{q="Eralya是谁？",a="Eralya是一名在前往The Oracle Tree执行任务途中遭到伏击的暗夜精灵哨兵或信使。她生命垂危，咳血不止，恳求过路的冒险者在她的生命走到尽头之前，带去关于她小队命运的消息。",al={"eralya是谁","eralya任务","垂死的暗夜精灵"}},{q="什么是The Oracle Tree？",a="The Oracle Tree是位于泰达希尔神谕林地的一处古老地标。Eralya和她的姐妹们在前往那里的途中，带着一封紧急信件时被敌方压制。",al={"什么是the oracle tree","神谕林地之树","eralya要去哪里"}},{q="Eralya和她的巡逻队发生了什么事？",a="Eralya和她的姐妹们遭到了盘踞在泰达希尔枝叶间的鹰身人的伏击并被其压制。这些生物蜂拥而至，屠戮了巡逻队，并将Eralya打成重伤。",al={"谁袭击了eralya","谁伏击了她","eralya为什么在流血"}},{q="Byancie是谁？",a="Byancie是驻扎在暗夜精灵村庄多兰纳尔的一名联络人。Eralya急切地要求将鹰身人伏击和巡逻队困境的消息直接带给Byancie。",al={"byancie是谁","byancie在哪里","byancie 多兰纳尔"}},{q="Eralya的消息必须送到哪里？",a="多兰纳尔是位于泰达希尔幽影谷以南道路旁的主要暗夜精灵村庄。Byancie居住在那里，负责接收报告并协调当地的防御工作。",al={"消息送到哪里","eralya的传信","多兰纳尔在哪里"}},{q="执行任务的其他姐妹们发生了什么事？",a="Eralya的暗夜精灵哨兵同伴在凶残的鹰身人突袭中失散或阵亡。由于看不到援军，Eralya担心她的姐妹中无人能从这场屠杀中幸免。",al={"eralya的姐妹们发生了什么","哨兵巡逻队姐妹"}}},fp="12,332,18.433.0,18.460.0,14.233.0,24.184.0,39.196.0,15.178.0,41.186.0,50.188.0"}
P.entries["quest:99048"] = {n="A Missing Hand",s="A Missing Hand是杜隆塔尔的一项任务，内容涉及Shattered Hand侦察兵Heglan Shadeeye的突然失踪。她原本的任务是负责监视提拉加德城堡。在她的常规情报报告突然中断后，一位调查员被派去寻找她的岗哨，以查明究竟是什么让她噤声。",h="A Missing Hand是杜隆塔尔的一项任务，内容涉及Shattered Hand侦察兵Heglan...",kw={"a missing hand","杜隆塔尔","heglan shadeeye","潜行者","侦察兵","shattered hand","提拉加德城堡"},ang={["class:Rogue"]="Shattered Hand是部落隐秘的脊梁和情报公会。调查一名失踪特工的情况，足以证明他们的实地监视任务有多么危险。",["faction:Horde"]="监视提拉加德城堡的库尔提拉斯残余势力对于杜隆塔尔的安全至关重要，而一名侦察兵无法解释的失踪，预示着奥格瑞玛家门口可能存在着尚未察觉的威胁。",["race:Orc"]="杜隆塔尔是新近稳固的兽人领土，让一名特工在附近人类居住者的眼皮底下失踪，引起了对王国安全的高度警惕。"},sec={{t="沉默的报告",b="A Missing Hand的起因是人们对Shattered Hand侦察兵Heglan Shadeeye日益增长的担忧。她被派驻在杜隆塔尔，从远处监视占领提拉加德城堡的敌对人类驻军，但她持续的情报报告却毫无预兆地中断了。她的上级怀疑人类士兵是否真的成功发现并抓获了她，担心是有意想不到且更危险的威胁介入了。冒险者们被派往城堡以北寻找她的岗哨，以确定这次中断仅仅是通讯延迟，还是有更可怕的事情发生。"},{t="寒冷的小屋",b="到达提拉加德城堡以北指定的观察哨后，搜寻工作以悲剧告终。Heglan冰冷的尸体躺在一间破败小屋的碎片之中。留下的实物证据表明，袭击者并非人类，这留下了一个令人不安的疑问：究竟是什么生物或实体在如此靠近部落领土的地方击杀了一名训练有素的特工？散落在残骸附近的线索暗示了一种必须被揭开的陌生威胁。"}},faq={{q="什么是A Missing Hand任务？",a="A Missing Hand是杜隆塔尔的一项任务，冒险者需要寻找Shattered Hand侦察特工Heglan Shadeeye，她原本驻扎在提拉加德城堡以北，但她的常规情报报告突然中断了。",al={"a missing hand是什么","a missing hand任务概览"}},{q="Heglan Shadeeye是谁？",a="Heglan Shadeeye是一名Shattered Hand特工，任务是从附近的有利位置秘密监视提拉加德城堡。她的监视报告突然中断，促使人们对她的下落展开调查。",al={"heglan是谁","heglan shadeeye在哪里","失踪的侦察兵"}},{q="Heglan Shadeeye发生了什么事？",a="这正是本任务要查明的内容。她从提拉加德城堡以北的岗哨发回的报告毫无预警地中断了，派你去执行任务的人怀疑人类士兵并没有抓获她，而是担心有更危险的事情正在发生。",al={"heglan shadeeye发生了什么","heglan死了吗","heglan的命运"}},{q="什么是Shattered Hand？",a="在现代部落中，Shattered Hand是一个由隐秘特工、刺客和间谍组成的组织。他们执行秘密监视和情报行动，以保护部落领土。",al={"什么是shattered hand","shattered hand是什么组织"}},{q="提拉加德城堡的人类杀害了Heglan吗？",a="她的上级对此表示怀疑。尽管Heglan一直在监视占领提拉加德城堡的敌对库尔提拉斯人类，但委派你任务的人不相信他们能抓住她，并担心有更危险的事情在发生。",al={"是人类杀了heglan吗","是提拉加德的士兵杀了她吗"}},{q="为什么要监视提拉加德城堡？",a="提拉加德城堡是敌对的库尔提拉斯水兵和士兵占据的据点，威胁着杜隆塔尔的海岸。Heglan被派驻在附近以密切关注他们的行动，并将情报传回部落。",al={"为什么heglan要监视提拉加德城堡","提拉加德城堡监视"}}},fp="14,289,14.588.0,12.461.1,33.223.0,23.220.0,33.218.0,27.202.0,45.228.0,37.212.0"}
P.entries["quest:99049"] = {n="Threat from Below",s="Threat from Below是一个部落任务，核心内容是调查杜隆塔尔东海岸发生的一起暴力伏击事件。在哨兵赫格兰·暗眼于她的哨岗遭遇猛烈的小规模袭击后，冒险者必须检查这片受损区域，寻找袭击者的线索。发现的实物证据揭示了一个直接威胁到剃刀岭防线的入侵隐患。",h="Threat from...",kw={"杜隆塔尔","赫格兰·暗眼","部落","娜迦","奥戈尼尔·魂痕","剃刀岭","斥候","threat from below"},ang={["faction:Horde"]="调查海岸线对于杜隆塔尔的防御至关重要，能保护年轻的部落国度免受沿海边境侧翼打击的威胁。",["race:Orc"]="兽人防卫者认为针对斥候赫格兰·暗眼的伏击是对他们定居家园不可容忍的入侵，要求立即进行调查和反击。",["race:Troll"]="暗矛巨魔非常了解娜迦的狡诈本性，他们此前曾在无尽之海面对过海巫和水生恐怖生物。"},sec={{t="杜隆塔尔海岸的伏击",b="杜隆塔尔海岸发生的一场暴力小规模战斗留下了破碎的地面，引起了部落防卫者们的即刻警觉。破碎之手斥候赫格兰·暗眼在她的哨岗执行守望任务时，遭到了未知敌人的伏击。交战地点的情况清晰地表明，赫格兰进行了激烈的反击并重创了袭击者。由于敌对势力在东海岸长驱直入，部落冒险者们奉命调查这片受损的营地，仔细搜寻地面的线索，并查明袭击斥候的究竟是何种敌人。"},{t="娜迦威胁",b="搜寻残骸后发现了破碎的旗帜和一截异样兵器的残片，这些都属于蛇形生物——娜迦。这些邪恶的水生生物似乎是从艾萨拉一路沿杜隆塔尔海岸向南潜行，企图建立一个掠夺性的据点。对于驻扎在剃刀岭的守军来说，这一发现标志着危机将至。该定居点南面受困于提拉加德城堡的人类入侵者，西面又有野猪人的威胁，无法承受来自北方的新一轮海上攻势，否则将面临彻底崩溃的风险。"}},faq={{q="什么是Threat from Below？",a="Threat from Below是杜隆塔尔的一项任务，部落冒险者需在任务中调查针对斥候赫格兰·暗眼的伏击。在沿着海岸线发现暴力战斗的痕迹后，玩家需在受扰的地面上搜寻不明袭击者留下的线索。随后，回收的文物将被直接送往剃刀岭的奥戈尼尔·魂痕处，以评估该地区面临的军事危险。",al={"threat from below任务","什么是threat from below","threat from below概览"}},{q="赫格兰·暗眼是谁？",a="赫格兰·暗眼是一名破碎之手斥候，她曾在一座位于提拉加德城堡北侧的小屋中执行监视任务，守护部落的核心领地。在执行任务期间，她在海岸的观测点遭到了伏击。营地遭受的严重破坏表明她曾与袭击者进行过激烈的战斗，这引起了剃刀岭定居点领导层的紧急质询。",al={"赫格兰·暗眼","赫格兰是谁","赫格兰·暗眼背景故事"}},{q="谁袭击了赫格兰·暗眼？",a="赫格兰·暗眼遭到了沿杜隆塔尔海岸向南移动的娜迦的伏击。从交战现场回收的实物证据，特别是那面独特的旗帜和那块断裂的刀刃，证实了这次袭击是由这些蛇形生物实施的。战斗的惨烈程度也让袭击者自身负了伤。",al={"谁伏击了赫格兰","赫格兰的袭击者","什么袭击了赫格兰·暗眼"}},{q="奥戈尼尔·魂痕是谁？",a="奥戈尼尔·魂痕是驻扎在杜隆塔尔中部剃刀岭的一位著名兽人长官。他的职责是组织该地区的防御并协调部落斥候，负责监督有关敌对入侵的情报。当赫格兰·暗眼失去联络时，奥戈尼尔依靠返回的斥候和冒险者来识别袭击者并保障定居点的安全。",al={"奥戈尼尔是谁","奥戈尼尔·魂痕","剃刀岭的奥戈尼尔"}},{q="为什么娜迦对剃刀岭构成威胁？",a="剃刀岭已经面临着南面深根蒂固的库尔提拉斯人类海军，以及西面敌对野猪人的巨大军事压力。如果娜迦在北面的东海岸建立永久的滩头阵地，部落前哨将面临被夹击的风险，导致其有限的驻军过度分散，并切断横跨杜隆塔尔的增援路线。",al={"为什么娜迦在这里很危险","娜迦对剃刀岭的威胁","剃刀岭娜迦威胁"}},{q="袭击的娜迦来自哪里？",a="回收的军事残骸表明，娜迦是从北方水域沿海岸南下的，很可能源自艾萨拉或无尽之海的架层。通过利用水道避开内陆巡逻队，这些水生入侵者在杜隆塔尔防卫者组织起防线之前，便迅速袭击了孤立的海岸观测哨。",al={"娜迦来自哪里","杜隆塔尔的娜迦起源","娜迦如何到达杜隆塔尔"}}},fp="17,381,27.563.0,18.564.1,26.391.0,23.367.0,29.310.0,23.374.0,40.379.0,39.355.0"}
P.entries["quest:99050"] = {n="The Great Tree Provides",s="“大树的馈赠”是多兰纳尔的一个任务，拜安希在任务中寻求帮助以遏制威胁埃拉莉亚的危险疾病。玩家通过采集泰达希尔湖泊中的露水鞭笞者嫩叶并收集基本补给品，来帮助配制一种急救药膏。",h="“大树的馈赠”是多兰纳尔的一个任务，拜安希在任务中寻求帮助以遏制威胁埃拉莉亚的危险疾病。玩家通过采集泰达希尔湖泊中的露水鞭笞者嫩叶并收集基本补给品，来帮助配制一种急救药膏。",kw={"疾病","拜安希","露水鞭笞者嫩叶","多兰纳尔","埃拉莉亚","治疗药膏","奥拉密斯湖","泰达希尔","the great tree provides","涌泉湖"},ang={["class:Druid"]="德鲁伊们很欣赏泰达希尔植物中蕴含的天然修复特性，他们倾向于依赖像鞭笞者嫩叶这样的原生植物，而不是人工合成的制剂。",["profession:Herbalism"]="采集露水鞭笞者嫩叶等原生植物材料来酿制强效治疗药膏，对于经验丰富的草药师来说是本能般的技能。",["race:NightElf"]="泰达希尔的草药疗法反映了卡多雷的信仰，即他们的世界之树养育并保护着他们，为突发的疾病提供了生命之药。"},sec={{t="与时间赛跑",b="在多兰纳尔的森林村庄里，拜安希一直照料着当地暗夜精灵的健康。当埃拉莉亚在泰达希尔野外遭遇危险疾病的消息传来时，拜安希立刻着手准备急救治疗。如果不能快速配制出药膏来遏制病情，埃拉莉亚将无法支撑到被送回村庄接受正式治疗。"},{t="慷慨的世界之树",b="即使在危机时刻，卡多雷依然信任泰达希尔的慷慨馈赠。拜安希求助于这棵充满生命的世界之树来寻找疗法，她寻找着生长在南面奥拉密斯湖和西北面涌泉湖附近的露水鞭笞者嫩叶。将这些叶片与简单的玻璃瓶中的清凉的泉水混合，就能得到遏制疾病所需的救命药物。"}},faq={{q="“大树的馈赠”是什么？",a="“大树的馈赠”是多兰纳尔的一项紧急任务，由拜安希发布。她试图配制一种修复药膏，以在无法进行后续治疗前遏制威胁埃拉莉亚的疾病。",al={"大树的馈赠是什么","大树的馈赠任务","拜安希任务"}},{q="拜安希是谁？",a="拜安希是一位居住在泰达希尔多兰纳尔村的暗夜精灵治疗者或药剂师，致力于照料病人并利用当地植物配制天然药物。",al={"谁是拜安希","拜安希多兰纳尔","任务发布者拜安希"}},{q="埃拉莉亚是谁？她发生了什么事？",a="埃拉莉亚是一位身处多兰纳尔外、目前病情正在迅速恶化的受难者。拜安希需要一种紧急药膏来使她的情况稳定下来，以便将其安全送回城里接受全面治疗。",al={"谁是埃拉莉亚","埃拉莉亚怎么了","埃拉莉亚疾病"}},{q="哪里可以找到露水鞭笞者嫩叶？",a="露水鞭笞者嫩叶生长在多兰纳尔正南方的奥拉密斯湖，以及西北方向的涌泉湖及其河流周围的鞭笞者身上。",al={"哪里找到露水鞭笞者嫩叶","露水鞭笞者嫩叶位置","泰达希尔鞭笞者嫩叶"}},{q="配制药膏需要什么材料？",a="拜安希需要六片从本土鞭笞者身上采集的露水鞭笞者嫩叶、一个空瓶以及清凉的泉水来调配这种急救药膏。",al={"拜安希需要什么材料","多兰纳尔药膏材料","大树的馈赠物品"}},{q="在哪里可以获得空瓶和清凉的泉水？",a="空瓶和清凉的泉水都可以直接从多兰纳尔定居点的杂货或贸易补给品商人处购买。",al={"哪里获取瓶子和泉水","多兰纳尔空瓶","多兰纳尔清凉的泉水"}}},fp="23,260,19.409.0,24.393.0,32.190.0,15.180.0,39.214.0,35.159.0,51.149.0,63.150.0"}
P.entries["quest:99051"] = {n="Threat from Below",s="Threat from Below是一项防御任务，旨在清除附近建立营地的侵略性娜迦侦察兵。通过打击侦察部队并收集它们的脊鳍，冒险者们的目标是将这些蛇形入侵者赶回北方，保卫该地区。",h="Threat from Below是一项防御任务，旨在清除附近建立营地的侵略性娜迦侦察兵。通过打击侦察部队并收集它们的脊鳍，冒险者们的目标是将这些蛇形入侵者赶回北方，保卫该地区。",kw={"步兵","娜迦","娜迦脊鳍","侦察兵","蛇渣","脊鳍","threat from below"},ang={["faction:Horde"]="任务发布者动员部落步兵观察是否有漏网之鱼，这使其成为部落领地针对逼近的娜迦侦察兵的一次主动防御行动。"},sec={{t="蛇形入侵",b="Threat from Below旨在应对因娜迦侦察兵入侵而日益严重的边境骚乱。这些蛇形袭击者开始在附近建立前进营地，迫使当地防卫力量在入侵者稳固立足之前发动打击。冒险者们受命清除侦察部队，并带回娜迦脊鳍作为营地已被摧毁的证据。"},{t="保卫边境",b="这并非蛇人第一次滋扰该地区，当地指挥官明确表示绝不容忍它们的存在。在对它们的侦察营地进行打击后，目标是将任何幸存的娜迦赶回北方，并派遣警惕的部落步兵守卫，以防漏网之鱼或突如其来的伏击。"}},faq={{q="什么是Threat from Below？",a="Threat from Below是一项部落任务，任务要求冒险者们消灭开始在附近建立营地的娜迦侦察兵。为了确保入侵被阻止，玩家必须杀死这些逼近的蛇人并收集娜迦脊鳍作为任务完成的证明。",al={"什么是threat from below","threat from below任务"}},{q="命令中提到的蛇是指谁？",a="“蛇”或“蛇渣”指的是娜迦，这是一种两栖蛇形类人生物，它们从海岸或水底深处浮出，侦察当地的防线。",al={"蛇是指谁","threat from below里的蛇"}},{q="为什么要消灭娜迦侦察兵？",a="这些营地表明这是一种有组织的侦察活动，而非偶然游荡的生物。当地指挥官要求迅速反击，以便在入侵者发动更大规模袭击或进一步扎根之前将它们赶走。",al={"为什么要杀娜迦侦察兵","娜迦的动机"}},{q="为什么要收集娜迦脊鳍？",a="被割下的脊鳍是侦察营地已被发现并拆除的无可辩驳的实物证据，证实了边境沿线的直接压力已经解除。",al={"为什么要收集脊鳍","娜迦的证据"}},{q="娜迦预计会撤退到哪里？",a="在交付脊鳍后，指挥官表示希望这次打击能将娜迦赶回北方，并指派步兵监视是否有漏网之鱼或可疑动向。",al={"娜迦会去哪里","娜迦撤往北方"}},{q="侦察兵被杀后由谁负责警戒？",a="部落步兵受命负责监视该区域，以确保没有漏网之鱼，并防止娜迦尝试任何进一步的入侵。",al={"谁负责监视娜迦","步兵监视娜迦"}}},fp="17,245,20.379.0,20.334.0,26.262.0,43.157.0,39.231.0,33.178.0,39.179.0,43.143.0"}
P.entries["quest:99052"] = {n="Threat from Below",s="“Threat from Below”是一项部落悬赏任务，要求冒险者们前往杜隆塔尔的北部海岸，猎杀一头危险的海洋巨人。击败这样一个巨大的海岸泰坦，不仅能保卫附近的海岸线，还能赢得杜隆塔尔勇士们的尊敬。",h="“Threat from Below”是一项部落悬赏任务，要求冒险者们前往杜隆塔尔的北部海岸，猎杀一头危险的海洋巨人。击败这样一个巨大的海岸泰坦，不仅能保卫附近的海岸线，还能赢得杜隆塔尔勇士们的尊敬。",kw={"血与雷","海岸怪物","杜隆塔尔","部落任务","北部海岸","海洋巨人","threat from below"},ang={["class:Warrior"]="在近战中面对一个庞大的海洋巨人是一场残酷的武力耐力考验，是对抗海岸上最强大的蛮兽之一的证明。",["faction:Horde"]="在杜隆塔尔海岸线上击杀海洋巨人，消除了一个潜伏在部落心脏地带门户附近的危险巨兽。",["race:Orc"]="兽人的荣誉感崇尚正面面对泰坦般的强敌，并以“血与雷”的战吼回应压倒性的力量。"},sec={{t="北部海岸线",b="在杜隆塔尔的北部海岸线，无尽之海的海水拍打着锯齿状的沙滩和岩石岸边。虽然这里通常只有普通的食腐动物和螃蟹出没，但北部海岸却潜藏着更致命的威胁：一个庞大的海洋巨人在浅滩徘徊，威胁着任何试图在部落这片干旱新家园的沿海水域旅行或获取资源的人。"},{t="波涛泰坦",b="海洋巨人是巨大的蛮兽，能够轻易摧毁长船，并用巨大的拳头碾碎战士。对于年轻的冒险者来说，击杀它们绝非易事；能终结这个波涛中的巨兽，足以在兽人中赢得极高的尊敬，并伴随着在干红色的峭壁间回荡的传统战吼——“血与雷”的庆祝。"}},faq={{q="“Threat from Below”是什么任务？",a="“Threat from Below”是一项交给部落勇士的任务，要求他们追踪并击败在杜隆塔尔北部海岸徘徊的巨型海洋巨人，并带回证明以完成任务。",al={"什么是threat from below","threat from below任务","杜隆塔尔海洋巨人任务"}},{q="在哪里可以找到海洋巨人？",a="这头海洋巨人在杜隆塔尔北部海岸的水域和岸边徘徊。",al={"海洋巨人在哪里","杜隆塔尔海洋巨人位置","threat from below位置"}},{q="海洋巨人是什么样的生物？",a="海洋巨人是巨大的、古老的海岸巨兽，它们被创造出来的目的是疏浚海洋并塑造艾泽拉斯的海岸线。很少有流浪者能在与它们的直接对抗中幸存。",al={"什么是海洋巨人","海洋巨人背景故事","谁是海洋巨人"}},{q="为什么要消灭海洋巨人？",a="如此巨大规模的生物在杜隆塔尔附近游荡，对海岸边的旅行者、渔民以及部落营地构成了严重的威胁。",al={"为什么要杀海洋巨人","海洋巨人危险吗","对杜隆塔尔的威胁"}},{q="任务发布者所说的“血与雷”是什么意思？",a="“血与雷”是传统的兽人战斗口号，旨在赞颂尚武精神、勇猛，以及在对抗危险对手并获得胜利后的荣耀。",al={"血与雷的含义","兽人问候语血与雷"}},{q="完成任务需要什么证明？",a="该任务要求从北部海岸带回这头海洋巨人被击杀的切实物理证明，以确认这一庞然大物已被消灭。",al={"threat from below任务证明","成就证明"}}},fp="17,246,22.365.0,20.340.0,36.172.0,29.92.0,37.170.0,45.156.0,54.152.0,44.150.0"}
P.entries["quest:99053"] = {n="Escaping Ban'ethil",s="“逃离班奈希尔”是泰达希尔地下兽穴中的一项营救任务。哨兵莱尼莎·暮花在向沉睡的德鲁伊传递信息时被好战的棘木熊怪俘虏，她必须被安全护送回地面，并向多兰纳尔报告平安。",h="“逃离班奈希尔”是泰达希尔地下兽穴中的一项营救任务。哨兵莱尼莎·暮花在向沉睡的德鲁伊传递信息时被好战的棘木熊怪俘虏，她必须被安全护送回地面，并向多兰纳尔报告平安。",kw={"班奈希尔兽穴","多兰纳尔","escaping ban'ethil","熊怪","棘木","卡多雷","凯拉·星歌","莱尼莎·暮花","the oracle tree","泰达希尔"},ang={["class:Druid"]="班奈希尔兽穴本应是沉睡的德鲁伊与翡翠梦境沟通的圣所，它被野蛮的熊怪占领，这对塞纳里奥的保护者来说是一场紧急危机。",["faction:Alliance"]="保护达纳苏斯和泰达希尔需要协助哨兵，对抗被腐化的本土野生生物和部族日益增长的敌意。",["race:NightElf"]="哨兵莱尼莎·暮花是并肩作战的战友，她被困在根须之下，这违背了暗夜精灵与泰达希尔广阔星空和林冠之间的神圣纽带。"},sec={{t="根须下的伏击",b="哨兵莱尼莎·暮花受“The Oracle Tree”委派，前去向在班奈希尔兽穴中休息的德鲁伊传达一条紧急信息。这项原本例行的信使任务却演变成了一场灾难，因为她发现这些地下密室已被好战的棘木熊怪完全占据。她在撤退前被截断去路并遭到伏击，被关押在阴暗的隧道中。她本以为自己难逃一死，直到一位冒险者介入，护送她回到了地面。"},{t="安全返回多兰纳尔",b="对于卡多雷哨兵来说，兽穴的地下阴暗处是一个既不自然又令人厌恶的牢笼，这里远离了艾露恩那令人慰藉的星光，也远离了泰达希尔的广阔天空。从深渊中被救出后，莱尼莎逃回了文明世界，关于她生还的消息也传到了多兰纳尔。在那里，哨兵凯拉·星歌得知好友生还的消息后如释重负，并嘉奖了那些帮助她战友保卫卡多雷人民的冒险者。"}},faq={{q="谁是哨兵莱尼莎·暮花？",a="哨兵莱尼莎·暮花是一位驻扎在泰达希尔的暗夜精灵哨兵。她受“The Oracle Tree”委派，前去向在班奈希尔兽穴中休息的德鲁伊传达一条至关重要的信息，但她在深入地下时遭到了棘木熊怪的伏击并被俘虏。",al={"谁是莱尼莎·暮花","莱尼莎·暮花","谁被困在兽穴里"}},{q="哨兵莱尼莎为什么会进入班奈希尔兽穴？",a="她受“The Oracle Tree”的正式委派，去向在班奈希尔兽穴中沉睡的德鲁伊传达一条信息。当她到达地下兽穴时，还没来得及传达信件，就发现那里已经被敌对的熊怪占领了。",al={"莱尼莎为什么去班奈希尔","莱尼莎的任务是什么","the oracle tree 的消息"}},{q="是谁俘虏了哨兵莱尼莎？",a="她被居住在兽穴中的棘木熊怪俘虏了。这些好战且充满敌意的部族在她逃脱前将其伏击，并拖入了深处，这让她担心自己会成为他们的下一顿盘中餐。",al={"谁俘虏了莱尼莎","班奈希尔里有什么熊怪","棘木熊怪"}},{q="什么是班奈希尔兽穴？",a="班奈希尔兽穴是位于泰达希尔的一处地下圣所，位于多兰纳尔以西。传统上，这里是在地底开凿出的暗夜精灵德鲁伊进行深度沟通时的休憩之所，但现在已被腐化的棘木熊怪所占据。",al={"班奈希尔兽穴在哪里","什么是班奈希尔兽穴","泰达希尔兽穴"}},{q="谁是哨兵凯拉·星歌？",a="哨兵凯拉·星歌是一位驻扎在多兰纳尔村的暗夜精灵哨兵。她是莱尼莎·暮花的挚友，正急切地等待着莱尼莎逃脱并安全返回的消息。",al={"谁是凯拉·星歌","在哪里交还“逃离班奈希尔”","多兰纳尔哨兵"}},{q="为什么莱尼莎厌恶身处地下？",a="虽然德鲁伊会利用兽穴进行神圣的沉睡，但许多暗夜精灵哨兵和战士非常不喜欢被困在地下。卡多雷文化珍视广阔的夜空、艾露恩的星光，以及森林树冠的庇护，而不是地下的隧道。",al={"为什么暗夜精灵不喜欢兽穴","地底不属于卡多雷"}}},fp="18,283,26.512.0,23.504.0,36.266.0,52.249.0,30.236.0,29.245.0,30.201.0,42.281.0"}
P.entries["quest:99073"] = {n="Easing Suffering",s="Easing Suffering是泰达希尔的一项任务，其核心内容是为哨兵埃拉莉亚·叶影提供紧急援助，她正躺在通往The Oracle Tree的道路上，饱受一种剧毒腐烂病的折磨。玩家必须争分夺秒地将鞭水愈膏送到她身边，以缓解她的痛苦，让她临终前的气息得到安宁。",h="Easing Suffering是泰达希尔的一项任务，其核心内容是为哨兵埃拉莉亚·叶影提供紧急援助，她正躺在通往The Oracle...",kw={"easing suffering","埃拉莉亚·叶影","鞭水愈膏","the oracle tree","腐烂病","哨兵埃拉莉亚","泰达希尔"},ang={["faction:Alliance"]="在达纳苏斯的家园道路上援助倒下的暗夜精灵哨兵，有助于守住对抗泰达希尔枝干上日益增长的腐化的脆弱前线。",["race:NightElf"]="哨兵埃拉莉亚·叶影是你的一位同胞，在泰达希尔靠近The Oracle Tree的荒野中，她染上了一种剧毒的腐化。为她提供慰藉，是对哨兵为族人所尽职责的尊崇。"},sec={{t="与腐烂病的赛跑",b="哨兵埃拉莉亚·叶影正躺在通往The Oracle Tree的道路上，深受一种迅速蔓延、不断恶化的腐烂病折磨。为了阻止她痛苦地走向死亡，必须在病情完全恶化之前，尽快将新鲜调制的鞭水愈膏送到她身边。"},{t="阴影中的安宁",b="虽然救治她的人怀疑鞭水愈膏是否有能力彻底根除这种枯萎病，但使用它能迅速平复埃拉莉亚那沉重而含混的呼吸。尽管她能否存活仍是个未知数，但这种治疗确实在她最黑暗的时刻给予了她安宁。"}},faq={{q="哨兵埃拉莉亚·叶影是谁？",a="哨兵埃拉莉亚·叶影是一位暗夜精灵卫兵，人们在通往The Oracle Tree的路上发现了她，当时她正饱受疾病的折磨。她被一种极具侵略性的溃烂腐病击倒，被发现时已失去行动能力，生命垂危。",al={"埃拉莉亚是谁","埃拉莉亚·叶影","哨兵埃拉莉亚是谁"}},{q="什么是鞭水愈膏？",a="鞭水愈膏是一种配制好的药剂，用于缓解哨兵埃拉莉亚所患的剧毒腐烂病引起的剧烈疼痛。虽然不能确定是否能彻底治愈，但它能缓解她的痛苦。",al={"什么是鞭水愈膏","鞭水愈膏","药膏能否治愈腐烂病"}},{q="哨兵埃拉莉亚能从这种疾病中幸存吗？",a="这种药膏缓解了哨兵埃拉莉亚的呼吸，带给她暂时的安宁，但她究竟能否完全康复，还是会屈服于缠身已久的腐烂病，仍不确定。",al={"埃拉莉亚能否幸存","埃拉莉亚是否痊愈","埃拉莉亚死了吗"}},{q="在哪里可以找到哨兵埃拉莉亚·叶影？",a="哨兵埃拉莉亚·叶影位于通往The Oracle Tree的道路旁，处于泰达希尔古老的区域内。",al={"the oracle tree在哪里","通往the oracle tree的路","埃拉莉亚的位置"}},{q="哨兵埃拉莉亚患了什么病？",a="埃拉莉亚患有一种极具侵略性且不断恶化的腐烂病，这种病在她体内迅速蔓延。这种污染的确切来源尚不明确，但它发作迅速，且随时间推移毒性越来越强。",al={"是什么导致了埃拉莉亚的疾病","什么是腐烂病","埃拉莉亚的病痛"}},{q="为什么要急着送达药膏？",a="腐烂病在埃拉莉亚体内迅速溃烂并加剧。必须争分夺秒，因为每耽误一刻，她就离被痛苦和腐化彻底吞噬更近一步。",al={"为什么要急送药膏","为什么要争分夺秒救埃拉莉亚"}}},fp="16,278,22.266.0,20.296.1,34.208.0,24.209.0,44.175.0,46.129.0,39.191.0,43.194.0"}
P.entries["quest:99079"] = {n="Longwalker Malah",s="远行者玛拉是一位失踪的牛头人侦察兵，她代表血蹄村被派往勘查莫高雷的东部边境。作为直接听命于大酋长的精英远行者，她在出发三天后未能按时归来，这引发了寻找她的紧急行动，以确保她的生存以及山谷的安全。",h="远行者玛拉是一位失踪的牛头人侦察兵，她代表血蹄村被派往勘查莫高雷的东部边境。作为直接听命于大酋长的精英远行者，她在出发三天后未能按时归来，这引发了寻找她的紧急行动，以确保她的生存以及山谷的安全。",kw={"贝恩·血蹄","血蹄村","羽毛法杖","longwalker malah","远行者组织","玛拉·长风","莫高雷","牛头人侦察兵"},ang={["class:Hunter"]="猎人们尊重远行者所需的野外追踪技能和耐力，他们徒步巡逻莫高雷的最边缘地带。",["faction:Horde"]="协助血蹄村的领导层寻找失踪的边境侦察兵，有助于保护莫高雷免受入侵部落领地的外部威胁。",["race:Tauren"]="远行者是受人尊敬的侦察兵，直接听命于大酋长凯恩·血蹄，因此他们的安全是所有牛头人在文化和战术上都极为关注的问题。"},sec={{t="大酋长的双眼",b="远行者是舒哈鲁人的耳目，他们因不知疲倦的步伐和野外生存技巧而闻名于平原。这些精英侦察兵直接宣誓效忠于大酋长凯恩·血蹄，他们的任务是穿越广阔的领土以收集情报并传递重要信息。虽然他们最终只效忠于大酋长，但年轻的贝恩·血蹄偶尔也会请求他们的协助，以保护血蹄村及其周边的牧场。"},{t="消失在边境",b="远行者玛拉·长风被派往监视莫高雷的东部边境，进行一次例行的三天侦察任务。当她未能按计划返回血蹄村时，村里的领导层感到十分担忧。鉴于远行者掌握着重要情报，且莫高雷边境峭壁处处潜藏危险，人们呼吁侦察兵和乐于助人的旅行者去寻找她的踪迹并确认她的安全。玛拉可以通过她所属组织的传统标志来辨认：一条仪式头带和一根羽毛法杖。"}},faq={{q="谁是远行者玛拉？",a="远行者玛拉·长风是一位受人尊敬的牛头人侦察兵，效忠于大酋长。她被派往莫高雷东部边境附近执行侦察任务，随身携带着代表她所属组织标志的传统头带和羽毛法杖。",al={"谁是玛拉","玛拉背景故事","远行者玛拉身份"}},{q="什么是远行者？",a="远行者是牛头人人民最信任的精英侦察兵和信使。他们的首要忠诚直接对大酋长负责，不过其他部落领袖（例如年轻的贝恩·血蹄）偶尔也会请求他们的帮助，以获取关键的边境情报。",al={"什么是远行者","谁是远行者","牛头人侦察兵"}},{q="为什么要寻找远行者玛拉？",a="玛拉被派去勘查莫高雷的东部边缘，原定三天内返回。当她未能归来时，血蹄村的人们开始担心她在巡逻崎岖边境时遇到了麻烦。",al={"为什么玛拉失踪了","玛拉任务原因","玛拉去了哪里"}},{q="在哪里可以找到玛拉？",a="远行者玛拉被派往莫高雷的东部边境，经过血蹄村向边界山脊进发。寻找她的旅行者必须搜索村庄以东的边境地带。",al={"玛拉在哪里","玛拉位置","寻找玛拉"}},{q="如何辨认远行者玛拉？",a="玛拉可以通过远行者的标志性服饰来辨认：一条独特的头带和一根她所属尊贵组织侦察兵所携带的高大羽毛法杖。",al={"玛拉外观","如何辨认玛拉","远行者装备"}},{q="贝恩·血蹄为什么会与远行者有往来？",a="虽然远行者只向大酋长凯恩·血蹄汇报，但他的儿子贝恩负责血蹄村的当地事务，偶尔会请求他们的追踪专长来监视边境活动并确保山谷的安全。",al={"贝恩角色","为什么贝恩参与其中","贝恩·血蹄侦察兵"}}},fp="16,324,25.502.0,27.554.0,24.243.0,25.268.0,43.230.0,25.192.0,38.160.0,53.249.0"}
P.entries["quest:991"] = {n="莱恩的净化",s="“莱恩的净化”始于莱恩·狼行者请求冒险者追踪她失踪的朋友泰罗尼恩。为了寻找平息灰谷各地猖獗的熊怪侵略的方法，泰罗尼恩动身前往法拉希姆湖寻找一颗魔法宝石。",h="“莱恩的净化”始于莱恩·狼行者请求冒险者追踪她失踪的朋友泰罗尼恩。为了寻找平息灰谷各地猖獗的熊怪侵略的方法，泰罗尼恩动身前往法拉希姆湖寻找一颗魔法宝石。",kw={"灰谷","法拉希姆","熊怪","宝石","鱼人","莱恩","泰罗尼恩","狼行者"},ang={["faction:Alliance"]="抵达阿斯特兰纳的联盟新兵很快就会了解到，灰谷的神圣林地正受到充满敌意的野生野兽、熊怪和入侵鱼人的围攻。",["race:NightElf"]="泰罗尼恩的失踪对暗夜精灵来说又是沉重的一击，他们本就为了治愈灰谷并保护神龛免受腐蚀而疲于奔命。"},sec={{t="朋友的牵挂",b="莱恩·狼行者在阿斯特兰纳与哨兵部队并肩作战，保卫灰谷免受日益严重的威胁。泰罗尼恩是她最亲密的伙伴之一，他自告奋勇去寻找能有效防御那些愈发暴躁的熊怪部落的方法。当他多日未归时，莱恩深感忧虑，但又因坚守岗位而无法脱身，只能在担忧中饱受煎熬。"},{t="权杖探寻",b="泰罗尼恩追寻着关于一根由已故邪恶法师铸造的强大权杖的传言，相信其魔法能够平息熊怪的怒火。为了修复这件神器，他需要一颗隐藏在位于西侧山脉附近法拉希姆湖一座暗夜精灵神龛中的附魔宝石。不幸的是，这片宁静的水域最近已经被凶猛的鱼人部落占领。"},{t="法拉希姆湖的悲剧",b="沿着泰罗尼恩的踪迹来到法拉希姆湖中的岛屿，展现在眼前的是一幅凄惨的景象。泰罗尼恩没能活着离开这片水域；他的尸体倒在神龛上，身上布满了鱼人武器和利爪留下的深深伤痕，他的探寻也就此画上了终点。"}},faq={{q="莱恩·狼行者是谁？",a="莱恩·狼行者是一位隶属于灰谷哨兵部队的暗夜精灵，驻扎在阿斯特兰纳。她负责监督各项防御工作，以保护森林免受入侵敌人的侵害。",al={"莱恩","莱恩是谁","任务发布者"}},{q="泰罗尼恩是谁？",a="泰罗尼恩是莱恩·狼行者的挚友，他曾寻求古代魔法的解决方案来拯救森林。他相信一根附魔权杖能够平息被腐蚀的熊怪，于是只身前往搜集所需的部件。",al={"泰罗尼恩是谁","泰罗尼恩背景","失踪的朋友"}},{q="泰罗尼恩在哪里失踪的？",a="泰罗尼恩失踪于法拉希姆湖，这片水域位于灰谷西侧山脉脚下，现已被充满敌意的鱼人占领。",al={"泰罗尼恩在哪里","泰罗尼恩位置","法拉希姆湖"}},{q="为什么泰罗尼恩要寻找一颗宝石？",a="这颗宝石是充能一根由已故邪恶法师制作的魔法权杖所需的关键组件。泰罗尼恩希望利用权杖的力量来遏制狂暴熊怪的攻击。",al={"什么宝石","为什么需要宝石","泰罗尼恩的宝石"}},{q="泰罗尼恩遭遇了什么？",a="自从他前往法拉希姆湖后，莱恩就再也没有他的消息。顺着他的足迹便能发现他的结局。",al={"泰罗尼恩怎么死的","杀害泰罗尼恩的凶手","谁杀了泰罗尼恩"}},{q="为什么熊怪要攻击灰谷？",a="灰谷的熊怪在第三次战争后屈服于恶魔的腐蚀与疯狂，导致原本爱好和平的部落转而对他们往日的盟友发动了无休止的暴力攻击。",al={"熊怪攻击","为什么熊怪如此狂暴","熊怪疯狂"}}},fx={["82e89856"]={q="莱恩·狼行者为什么要找到特罗尼斯？",a="特罗尼斯是莱恩·狼行者信赖多年的老友，他曾挺身而出，帮助哨兵对抗暴怒的熊怪。他离开去寻找一根魔棒和一颗宝石，希望借此阻止那些族人遭受的袭击，却再也没有回来。莱恩十分担心他的安危，也迫切想知道他是否找到了能帮助这片饱受蹂躏土地的东西。",al={"莱恩为什么要找特罗尼斯","莱恩·狼行者的动机","为什么寻找特罗尼斯"}}},fp="17,245,18.364.0,21.353.0,24.268.1,24.182.0,16.210.0,29.155.0,34.185.0,25.98.1,41.194.0"}
P.entries["quest:99108"] = {n="Sparring Match",s="Sparring Match是一项由格斗训练师唐·石蹄监管的入门试炼。该试炼旨在测试所有新兵，无论其职业或背景如何。它要求冒险者击败三名竞技场新兵或其他的决斗者，以证明他们在正面交锋中的实力。",h="Sparring Match是一项由格斗训练师唐·石蹄监管的入门试炼。该试炼旨在测试所有新兵，无论其职业或背景如何。它要求冒险者击败三名竞技场新兵或其他的决斗者，以证明他们在正面交锋中的实力。",kw={"竞技场","战斗训练","决斗","新兵战士","比武","sparring match","唐·石蹄"},ang={["class:Warrior"]="虽然唐·石蹄无法对非战士职业进行其特定学科的训练，但他的比武场强调了战士的哲学：战斗的基本功、勇气以及磨砺个人的战斗决心对任何冒险者都有益处。",["race:Tauren"]="唐·石蹄使用传统的牛头人短语，比如“磨砺犄角”来描述对一个人实力的考验，并欢迎任何愿意切磋的对手进入比武竞技场，无论他们的出身如何。"},sec={{t="切磋场地",b="由资深训练师唐·石蹄监管，Sparring Match邀请各路冒险者进入竞技场来测试自己的实力。尽管唐明确表示欢迎那些并非战士职业的人，但他坚持认为，武艺纪律和正面战斗能为这个危险世界中的任何旅行者提供通用的智慧。"},{t="磨砺犄角",b="在唐·石蹄的竞技场里，出身和武器偏好的区别都不重要。无论是使用剑、弓还是法术，挑战者都需要击败三名自愿的对手——无论是训练中的新兵战士还是进行决斗的其他冒险者——来证明自己的战斗准备情况。完成这些战斗后，你将赢得唐的尊重，并获得用于处理战斗伤口的绷带。"}},faq={{q="唐·石蹄是谁？",a="唐·石蹄是一位监管当地比武竞技场的格斗训练师。即使对于那些并非战士职业的人，唐也会提供格斗指导，并邀请有潜力的冒险者在与新兵或自愿同僚的正面战斗中测试自己的实力。",al={"唐·石蹄是谁","唐·石蹄背景故事","任务发布者"}},{q="唐·石蹄对Sparring Match有什么要求？",a="这项试炼要求在竞技场内击败三名对手——可以是进行决斗的其他自愿冒险者，也可以是在唐·石蹄指导下驻扎在那里的新兵战士。其目的是为了展示在正面战斗中的准备情况和武艺能力。",al={"sparring match目标","sparring match怎么做","与谁战斗"}},{q="为什么战士训练师要训练其他职业？",a="唐·石蹄认为，每一位冒险者，无论其挥舞的是刀剑、长弓还是魔法，都能从正面战斗中受益。在他的竞技场里，出身和特定的职业纪律远不如测试自我和磨砺战斗决心来得重要。",al={"非战士职业可以做吗","为什么其他职业要进行比武","不是战士"}},{q="Sparring Match在哪里进行？",a="比赛就在唐·石蹄面前的露天比武竞技场内进行，新兵们在那里进行训练，而自愿的挑战者也可以在平等的条件下互相切磋。",al={"在哪里对抗新兵","竞技场位置","比武场在哪里"}},{q="我能和玩家决斗而不是对战新兵战士吗？",a="可以。唐·石蹄接受你击败竞技场中训练的新兵战士，也接受你通过正式决斗击败其他冒险者，他只关心你是否在与自愿的对手对抗来测试自己的能力。",al={"我可以和玩家决斗吗","为了任务与玩家决斗","新兵战士还是玩家"}},{q="当你完成比赛时，唐·石蹄会说什么？",a="当你证明了自己的实力并击败三名对手后，唐会认可你的技巧，并对新一代的冒险者寄予希望，同时提供医疗补给来让你处理伤口，为前方的艰难旅途做好准备。",al={"sparring match奖励","唐给什么奖励"}}},fp="14,280,20.350.0,20.393.0,22.269.0,56.247.0,50.262.0,41.171.0,58.204.0,57.198.0"}
P.entries["quest:99123"] = {n="Lost in the Shadows",s="“Lost in the Shadows”是一个任务，内容是营救Pal'juh，一位鲁莽的猎人，她独自闯入了危险之中。对她的营救凸显了荒野追踪者在原始的攻击性和耐心的潜行之间所必需的微妙平衡。",h="“Lost in the Shadows”是一个任务，内容是营救Pal'juh，一位鲁莽的猎人，她独自闯入了危险之中。对她的营救凸显了荒野追踪者在原始的攻击性和耐心的潜行之间所必需的微妙平衡。",kw={"猎人","lost in the shadows","pal'juh","迅猛龙","老虎"},ang={["class:Hunter"]="该任务强调了一项基本的猎人纪律：耐心，像老虎一样潜行，而不是像饥饿的迅猛龙那样鲁莽冲锋。",["race:Troll"]="Pal'juh的名字和性情反映了年轻的Darkspear猎人，他们在掌握克制力之前就急于在荒野中证明自己的实力。"},sec={{t="鲁莽的斥候",b="“Lost in the Shadows”涉及寻找并营救Pal'juh，她是一位才华横溢但脾气火爆的猎人，独自闯入了敌对领地。她不愿等待支援，结果陷入了困境，需要外界的帮助才能确保安全返回。"},{t="狩猎的耐心",b="在Pal'juh获救后，她的监督者们指出，虽然她作为斥候和追踪者的潜力不可否认，但她像迅猛龙一样横冲直撞，而不是像老虎那样耐心地潜行。这次幸存下来的经历严酷地提醒了人们荒野的无情本质。"}},faq={{q="Pal'juh是谁？",a="Pal'juh是一位前途无量的年轻猎人，以独自闯入危险地带而闻名。虽然很有天赋，但她因行事鲁莽而声名狼藉，经常发现自己被野兽和荒野困住或淹没。",al={"pal'juh是谁","pal'juh背景故事","pal'juh"}},{q="在“Lost in the Shadows”任务期间发生了什么？",a="在“Lost in the Shadows”中，Pal'juh独自外出，再次陷入了麻烦。需要一位冒险者去追踪她，并在她受到严重伤害之前提供援助。",al={"lost in the shadows发生了什么","lost in the shadows任务背景","lost in the shadows故事"}},{q="为什么任务给予者说Pal'juh表现得更像迅猛龙而不是老虎？",a="这个比喻指的是狩猎技巧和纪律。迅猛龙在没有谨慎和预见的情况下猛烈扑击，而老虎则等待、耐心地潜行，并以精确和深谋远虑的狡诈进行攻击。",al={"为什么是迅猛龙和老虎","像迅猛龙而不像老虎的含义","猎人 迅猛龙 老虎"}},{q="谁负责接收“Lost in the Shadows”的报告？",a="任务以一位导师或同伴的结语告终，他足够了解Pal'juh并预料到了她的鲁莽，表达了对有人介入营救这位固执的追踪者感到欣慰。",al={"谁接收lost in the shadows任务","lost in the shadows任务给予者"}},{q="Pal'juh从这次不幸的冒险中吸取教训了吗？",a="多亏了外界的干预，Pal'juh才度过了这次磨难，尽管她的监督者们仍然在密切关注她是否会真正吸取独自外出带来的危险教训。",al={"pal'juh吸取教训了吗","pal'juh还好吗"}},{q="Pal'juh被认为是一位熟练的猎人吗？",a="她被认为是一位有前途的猎人，拥有充足的天赋和勇气，但她的导师警告说，在追踪危险猎物时，单纯的直觉无法取代战术上的耐心。",al={"pal'juh是优秀的猎人吗","pal'juh技能"}}},fp="19,237,16.263.0,20.278.0,15.204.0,52.175.0,74.211.0,48.179.0,53.179.0,39.182.0"}
P.entries["quest:99127"] = {n="A Net Disaster",s="“A Net Disaster”是艾尔文森林的一项任务，围绕着水晶湖的一次异常骚乱展开。由于垂钓一无所获，甚至连浅滩里的小鱼都不见了踪影，探险者们被派去检查过夜设置的陷阱。被毁坏的陷阱显示，附近充满敌意的入侵者正在大肆破坏当地的渔具。",h="“A Net...",kw={"a net disaster","水晶湖","艾尔文森林","鱼类储备","捕鱼陷阱","lee","鱼人","麻烦制造者"},ang={["faction:Alliance"]="水晶湖坐落在艾尔文森林的中心地带，因此当地的动荡直接威胁到了支持联盟领土核心区域的生计和补给。"},sec={{t="水晶湖的困境",b="在艾尔文森林的水晶湖，当地渔民面临着渔获量急剧下降的惊人状况。空钩并不罕见，但当连浅滩里的小鱼都消失不见时，日常垂钓就变成了一个严重的谜团。为了尽可能挽回损失，他们设置了过夜陷阱，希望能捕到一些基本的鱼获。"},{t="损坏的陷阱与邻近的麻烦",b="拉出没入水中的陷阱后发现，问题不在于运气不佳，而是赤裸裸的破坏行为。湖岸边充满敌意的邻近生物毁坏了陷阱，如果不加以制止，这将威胁到当地渔民的生计。"}},faq={{q="什么是“A Net Disaster”？",a="“A Net Disaster”是一项设定在艾尔文森林水晶湖的任务。当地渔民发现鱼儿不再上钩，甚至连小鱼也消失了，这促使人们对过夜陷阱展开调查。",al={"什么是a net disaster","a net disaster任务","水晶湖a net disaster"}},{q="你在哪里检查捕鱼陷阱？",a="捕鱼陷阱位于水晶湖的深水区，是由Lee在夜间放置的，目的是在常规垂钓失败时维持鱼类的储备。",al={"陷阱在哪里","a net disaster位置","水晶湖陷阱"}},{q="谁是Lee？",a="Lee是水晶湖的一名当地渔民，他连夜设置了陷阱，以帮助在鱼儿不再正常上钩时确保鱼类储备。",al={"谁是lee","渔夫lee"}},{q="水晶湖的鱼发生了什么事？",a="鱼类已经完全从水面消失了，连一条小鱼都看不见。检查发现，过夜陷阱已经被附近的麻烦制造者毁坏了。",al={"水晶湖的鱼怎么了","为什么水晶湖没有鱼","水晶湖空空如也"}},{q="最后提到的邻近麻烦制造者是谁？",a="任务发布者指的是入侵水晶湖的新的邻近麻烦制造者。在水晶湖的水域和岸边，好斗的鱼人已经建立了营地，并对当地的野生动物和渔具造成了破坏。",al={"谁是附近的麻烦制造者","a net disaster的麻烦制造者","谁破坏了陷阱"}},{q="为什么鱼类的缺乏对渔民来说是个大问题？",a="任务发布者的生计直接依赖于水晶湖的鱼类资源。随着陷阱受损和捕获量归零，如果不停止这种破坏，他们将面临破产的威胁。",al={"为什么任务发布者很在意","水晶湖渔业"}}},fp="14,338,31.310.0,39.280.1,23.215.0,39.146.0,11.137.0,42.192.0,55.231.0,61.191.0"}
P.entries["quest:99128"] = {n="Slimy Menace",s="“Slimy Menace”讲述了艾尔文森林中水晶湖沿岸日益严重的鱼人滋扰问题。这些极具攻击性的生物威胁要耗尽湖中的鱼类资源，并危及附近的居民，需要迅速采取行动以控制它们的数量。",h="“Slimy Menace”讲述了艾尔文森林中水晶湖沿岸日益严重的鱼人滋扰问题。这些极具攻击性的生物威胁要耗尽湖中的鱼类资源，并危及附近的居民，需要迅速采取行动以控制它们的数量。",kw={"水晶湖","艾尔文森林","鱼","闪金镇","鱼人","slimy menace"},ang={["faction:Alliance"]="保卫水晶湖的湖岸可以保护艾尔文当地的渔民和闪金镇附近的旅行者免受鱼人的袭击。",["race:Human"]="对于艾尔文森林的居民来说，鱼人的侵扰直接威胁着他们的水道、食物来源以及附近定居点的安全。"},sec={{t="水晶湖的麻烦",b="在水晶湖的东岸，一群极具攻击性的鱼人建立了立足点。这些野蛮的半水生生物长着锋利的牙齿，脾气暴躁，将原本平静的水域变成了危险的捕食场。当地居民的生计严重依赖于这个湖泊，但鱼人的出现现在威胁到了任何胆敢在此捕鱼或靠近水边的人。"},{t="无尽的滋扰",b="除了对旅行者造成的直接威胁外，如果任由这些鱼人繁衍，它们会吃光湖里的每一条鱼。削减它们的数量可以给当地水域带来急需的喘息之机，尽管它们那怪异、回荡的鸣叫声依然时刻提醒着人们它们的顽强。即使被驱散，鱼人也能迅速补充兵力，确保对湖岸保持警惕成为一项持续的必要工作。"}},faq={{q="“Slimy Menace”任务是关于什么的？",a="“Slimy Menace”是一项关于居住在水晶湖远岸的侵略性鱼人群体的本地任务。如果不加控制，这些两栖生物会吞食当地的鱼类，并威胁任何试图在附近工作或旅行的人。",al={"什么是slimy menace","slimy menace任务信息","slimy menace概述"}},{q="这个任务的事件发生在哪里？",a="这一骚乱发生在艾尔文森林的水晶湖，一群鱼人聚集在对岸的湖边。它们的出现破坏了湖泊的自然生态，并对当地居民构成了危险。",al={"水晶湖的鱼人在哪里","水晶湖位置","事件发生地点"}},{q="为什么要清理水晶湖的鱼人？",a="鱼人正在迅速消耗湖中的鱼类资源，同时用它们残暴的脾气和锋利的牙齿恐吓周围地区。清理它们的队伍有助于保护湖泊的渔业，并暂时阻止它们的扩张。",al={"为什么要杀死水晶湖的鱼人","鱼人吃鱼","鱼人有什么问题"}},{q="清理鱼人能彻底解决问题吗？",a="清理鱼人只能提供暂时的缓解。正如任务完成时所提到的，鱼人的繁殖和重组速度惊人，确保了尽管有最初的损失，它们的数量也会迅速恢复。",al={"鱼人永远消失了吗","我们消灭了鱼人吗","水晶湖的鱼人会回来吗"}},{q="是谁请求协助处理“Slimy Menace”？",a="该任务由一名关心水晶湖状况的艾尔文当地居民发布。他们对鱼人不安的鸣叫声和贪婪的食欲感到苦恼，因此请求冒险者削减这些生物的数量以保护渔场。",al={"谁发布了slimy menace","slimy menace任务发布者"}},{q="是什么让鱼人成为如此大的威胁？",a="鱼人被描述为残暴、脾气暴躁的两栖生物，长着锋利的牙齿，并发出臭名昭著的喉音。它们聚集在湖岸，极具攻击性地保卫领地，并袭击任何过于靠近它们捕食地点的生物。",al={"鱼人是什么样的","水晶湖鱼人的习性"}}},fp="12,255,23.409.0,22.433.0,37.239.0,45.220.0,47.247.0,58.213.0,40.227.0,37.257.0"}
